


SET statement_timeout = 0;
SET lock_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;


CREATE SCHEMA IF NOT EXISTS "public";


ALTER SCHEMA "public" OWNER TO "pg_database_owner";


COMMENT ON SCHEMA "public" IS 'standard public schema';



CREATE OR REPLACE FUNCTION "public"."_active_permission_admin_count"("p_exclude_auth_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
    select count(*)::integer
    from public.app_users au
    where au.account_status = 'Active'
      and (
          p_exclude_auth_user_id is null
          or au.auth_user_id <> p_exclude_auth_user_id
      )
      and public.user_has_permission(
          au.auth_user_id,
          'permissions.manage'
      );
$$;


ALTER FUNCTION "public"."_active_permission_admin_count"("p_exclude_auth_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_assert_access_control_manager"() RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
    if auth.uid() is null then
        raise exception 'Authentication required.';
    end if;

    if not public.can_manage_permissions() then
        raise exception
            'Permission denied: permissions.manage';
    end if;
end;
$$;


ALTER FUNCTION "public"."_assert_access_control_manager"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_create_invoice_atomic_core"("p_invoice" "jsonb", "p_lines" "jsonb", "p_sources" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    v_invoice_id uuid;
    v_customer_id uuid;
    v_project_id uuid;
    v_site_id uuid;
    v_invoice_type text;
    v_invoice_date date;
    v_due_date date;
    v_currency text;
    v_price_book_id uuid;
    v_customer_price_book_id uuid;
    v_default_price_book_id uuid;
    v_payment_terms_type text;
    v_payment_terms_days integer;
    v_line_amount_type text;
    v_customer_discount numeric(7,4) := 0;

    v_subtotal numeric(18,2) := 0;
    v_discount_total numeric(18,2) := 0;
    v_tax_total numeric(18,2) := 0;
    v_invoice_total numeric(18,2) := 0;

    v_line jsonb;
    v_source jsonb;

    v_line_no integer;
    v_line_type text;
    v_description text;
    v_notes text;
    v_project_area_id uuid;

    v_product_id uuid;
    v_product_code text;
    v_product_name text;
    v_product_type text;
    v_is_service_item boolean;

    v_sales_uom_code text;
    v_base_uom_code text;
    v_conversion_factor numeric(18,6);
    v_base_quantity numeric(18,6);
    v_allow_fractional boolean;

    v_price_book_line_id uuid;
    v_price_source text;
    v_resolved_unit_price numeric(18,2);
    v_requested_unit_price numeric(18,2);
    v_original_unit_price numeric(18,2);

    v_quantity numeric(18,6);
    v_discount_percent numeric(7,4);
    v_line_subtotal numeric(18,2);
    v_line_discount numeric(18,2);
    v_taxable_amount numeric(18,2);
    v_tax_rate numeric(7,4);
    v_line_tax numeric(18,2);
    v_line_total numeric(18,2);

    v_can_override_price_book boolean;
    v_can_override_unit_price boolean;
    v_can_override_discount boolean;
begin
    if p_invoice is null or jsonb_typeof(p_invoice) <> 'object' then
        raise exception 'Invoice header must be a JSON object.';
    end if;

    if p_lines is null
       or jsonb_typeof(p_lines) <> 'array'
       or jsonb_array_length(p_lines) = 0 then
        raise exception 'At least one Invoice line is required.';
    end if;

    if p_sources is null or jsonb_typeof(p_sources) <> 'array' then
        raise exception 'Invoice sources must be a JSON array.';
    end if;

    v_can_override_price_book :=
        public.has_permission('invoices.override_price_book');
    v_can_override_unit_price :=
        public.has_permission('invoices.override_unit_price');
    v_can_override_discount :=
        public.has_permission('invoices.override_discount');

    v_customer_id := nullif(p_invoice ->> 'customer_id', '')::uuid;
    v_project_id := nullif(p_invoice ->> 'project_id', '')::uuid;
    v_site_id := nullif(p_invoice ->> 'project_site_id', '')::uuid;
    v_invoice_type :=
        coalesce(
            nullif(btrim(p_invoice ->> 'invoice_type'), ''),
            'Standard'
        );
    v_invoice_date :=
        coalesce(
            nullif(p_invoice ->> 'invoice_date', '')::date,
            current_date
        );

    if v_invoice_type in ('Credit Note', 'Retention Release') then
        raise exception
            'Use the dedicated Credit Note or Retention Release RPC.';
    end if;

    perform public.validate_invoice_context(
        v_customer_id,
        v_project_id,
        v_site_id
    );

    select
        c.price_book_id,
        cfs.default_currency,
        cfs.payment_terms_type,
        cfs.payment_terms_days,
        cfs.line_amount_type,
        cfs.discount_percent
    into
        v_customer_price_book_id,
        v_currency,
        v_payment_terms_type,
        v_payment_terms_days,
        v_line_amount_type,
        v_customer_discount
    from public.customers c
    left join public.customer_financial_settings cfs
        on cfs.customer_id = c.customer_id
    where c.customer_id = v_customer_id
      and c.is_deleted = false
      and c.is_active = true;

    if not found then
        raise exception 'Customer is missing, inactive, or deleted.';
    end if;

    select pb.price_book_id
    into v_default_price_book_id
    from public.price_books pb
    where pb.is_default = true
      and pb.is_active = true
      and pb.is_deleted = false
      and (
          pb.effective_from is null
          or pb.effective_from <= v_invoice_date
      )
      and (
          pb.effective_to is null
          or pb.effective_to >= v_invoice_date
      )
    order by pb.effective_from desc nulls last, pb.created_at desc
    limit 1;

    v_price_book_id :=
        coalesce(
            nullif(p_invoice ->> 'price_book_id', '')::uuid,
            v_customer_price_book_id,
            v_default_price_book_id
        );

    if nullif(p_invoice ->> 'price_book_id', '') is not null
       and nullif(p_invoice ->> 'price_book_id', '')::uuid
           is distinct from v_customer_price_book_id
       and not v_can_override_price_book then
        raise exception
            'You do not have permission to override the Customer Price Book.';
    end if;

    if v_price_book_id is not null
       and not exists (
            select 1
            from public.price_books pb
            where pb.price_book_id = v_price_book_id
              and pb.is_active = true
              and pb.is_deleted = false
              and (
                  pb.effective_from is null
                  or pb.effective_from <= v_invoice_date
              )
              and (
                  pb.effective_to is null
                  or pb.effective_to >= v_invoice_date
              )
       ) then
        raise exception
            'Selected Price Book is inactive, deleted, or outside its effective dates.';
    end if;

    v_currency :=
        coalesce(
            nullif(btrim(v_currency), ''),
            'AUD'
        );
    v_payment_terms_type :=
        coalesce(
            nullif(btrim(v_payment_terms_type), ''),
            'Days After Bill'
        );
    v_payment_terms_days :=
        coalesce(v_payment_terms_days, 14);
    v_line_amount_type :=
        coalesce(
            nullif(btrim(v_line_amount_type), ''),
            'Exclusive'
        );
    v_customer_discount :=
        coalesce(v_customer_discount, 0);

    -- Customer Financial Settings follows Xero's stored value
    -- "NoTax". Invoice documents use the display snapshot "No Tax".
    if v_line_amount_type = 'NoTax' then
        v_line_amount_type := 'No Tax';
    end if;

    v_due_date :=
        coalesce(
            nullif(p_invoice ->> 'due_date', '')::date,
            public.invoice_due_date_from_terms(
                v_customer_id,
                v_invoice_date
            )
        );

    if v_due_date < v_invoice_date then
        raise exception 'Due date cannot be before Invoice date.';
    end if;

    if (
        select count(*)
        from (
            select (value ->> 'line_no')::integer as line_no
            from jsonb_array_elements(p_lines)
        ) x
    ) <> (
        select count(distinct line_no)
        from (
            select (value ->> 'line_no')::integer as line_no
            from jsonb_array_elements(p_lines)
        ) x
    ) then
        raise exception 'Duplicate Invoice line_no values are not allowed.';
    end if;

    -- Validate and total every line before creating the header.
    for v_line in
        select value
        from jsonb_array_elements(p_lines)
    loop
        v_line_no := nullif(v_line ->> 'line_no', '')::integer;
        v_product_id := nullif(v_line ->> 'product_id', '')::uuid;
        v_project_area_id :=
            nullif(v_line ->> 'project_area_id', '')::uuid;
        v_description :=
            btrim(coalesce(v_line ->> 'description', ''));
        v_notes := nullif(btrim(v_line ->> 'notes'), '');
        v_quantity :=
            coalesce(
                nullif(v_line ->> 'quantity', '')::numeric,
                0
            );
        v_tax_rate :=
            coalesce(
                nullif(v_line ->> 'tax_rate', '')::numeric,
                0
            );

        if v_line_no is null or v_line_no <= 0 then
            raise exception
                'Each Invoice line requires a positive line_no.';
        end if;

        if v_quantity <= 0 then
            raise exception
                'Line % quantity must be greater than zero.',
                v_line_no;
        end if;

        if v_tax_rate < 0 or v_tax_rate > 100 then
            raise exception
                'Line % tax rate must be between 0 and 100.',
                v_line_no;
        end if;

        if v_project_area_id is not null then
            if v_site_id is null then
                raise exception
                    'Line % has a Project Area but the Invoice has no Project Site.',
                    v_line_no;
            end if;

            if not exists (
                select 1
                from public.project_areas pa
                where pa.area_id = v_project_area_id
                  and pa.site_id = v_site_id
                  and pa.is_active = true
                  and pa.is_deleted = false
            ) then
                raise exception
                    'Line % Project Area does not belong to the selected Project Site.',
                    v_line_no;
            end if;
        end if;

        v_product_code := null;
        v_product_name := null;
        v_product_type := null;
        v_is_service_item := false;
        v_sales_uom_code := null;
        v_base_uom_code := null;
        v_conversion_factor := null;
        v_base_quantity := null;
        v_allow_fractional := true;
        v_price_book_line_id := null;
        v_price_source := 'Manual';
        v_resolved_unit_price := null;

        if v_product_id is not null then
            select
                p.product_code,
                p.product_name,
                p.product_type,
                p.is_service_item,
                coalesce(
                    nullif(v_line ->> 'sales_uom_code', ''),
                    p.default_sales_uom_code,
                    p.base_uom_code
                ),
                p.base_uom_code
            into
                v_product_code,
                v_product_name,
                v_product_type,
                v_is_service_item,
                v_sales_uom_code,
                v_base_uom_code
            from public.products p
            where p.product_id = v_product_id
              and p.is_active = true
              and p.is_deleted = false;

            if not found then
                raise exception
                    'Line % Product is missing, inactive, or deleted.',
                    v_line_no;
            end if;

            if v_description = '' then
                v_description := v_product_name;
            end if;

            if v_sales_uom_code = v_base_uom_code then
                v_conversion_factor := 1;
                v_allow_fractional := true;
            else
                select
                    puc.conversion_factor,
                    puc.allow_fractional_quantity
                into
                    v_conversion_factor,
                    v_allow_fractional
                from public.product_uom_conversions puc
                where puc.product_id = v_product_id
                  and puc.from_uom_code = v_sales_uom_code
                  and puc.to_uom_code = v_base_uom_code
                  and puc.is_active = true
                  and puc.is_deleted = false
                order by puc.sort_order, puc.created_at
                limit 1;

                if v_conversion_factor is null then
                    raise exception
                        'Line % Sales UOM (%) has no active conversion to Base UOM (%).',
                        v_line_no,
                        v_sales_uom_code,
                        v_base_uom_code;
                end if;
            end if;

            if not v_allow_fractional
               and v_quantity <> trunc(v_quantity) then
                raise exception
                    'Line % Sales UOM (%) does not allow fractional quantity.',
                    v_line_no,
                    v_sales_uom_code;
            end if;

            v_base_quantity :=
                round(v_quantity * v_conversion_factor, 6);

            if v_price_book_id is not null then
                select
                    pbl.price_book_line_id,
                    pbl.unit_price
                into
                    v_price_book_line_id,
                    v_resolved_unit_price
                from public.price_book_lines pbl
                where pbl.price_book_id = v_price_book_id
                  and pbl.product_id = v_product_id
                  and pbl.is_active = true
                  and pbl.is_deleted = false
                  and (
                      pbl.effective_from is null
                      or pbl.effective_from <= v_invoice_date
                  )
                  and (
                      pbl.effective_to is null
                      or pbl.effective_to >= v_invoice_date
                  )
                order by pbl.effective_from desc nulls last,
                         pbl.created_at desc
                limit 1;

                if v_price_book_line_id is not null then
                    v_price_source := 'Price Book';
                end if;
            end if;
        end if;

        if v_description = '' then
            raise exception
                'Line % requires a Product or description.',
                v_line_no;
        end if;

        v_requested_unit_price :=
            nullif(v_line ->> 'unit_price', '')::numeric;

        if v_resolved_unit_price is null then
            if v_requested_unit_price is null then
                raise exception
                    'Line % has no active Price Book price. Entering a manual price requires the appropriate permission.',
                    v_line_no;
            end if;

            if v_product_id is not null
               and not v_can_override_unit_price then
                raise exception
                    'Line % Product has no Price Book price and you do not have permission to enter a manual price.',
                    v_line_no;
            end if;

            v_resolved_unit_price := v_requested_unit_price;
            v_price_source := 'Manual';
        elsif v_requested_unit_price is not null
              and v_requested_unit_price
                  is distinct from v_resolved_unit_price then
            if not v_can_override_unit_price then
                raise exception
                    'You do not have permission to override the unit price on line %.',
                    v_line_no;
            end if;

            v_original_unit_price := v_resolved_unit_price;
            v_resolved_unit_price := v_requested_unit_price;
            v_price_source := 'Manual';
        end if;

        if v_resolved_unit_price < 0 then
            raise exception
                'Line % unit price cannot be negative.',
                v_line_no;
        end if;

        v_original_unit_price :=
            coalesce(v_original_unit_price, v_resolved_unit_price);

        if nullif(v_line ->> 'discount_percent', '') is null then
            v_discount_percent := v_customer_discount;
        else
            v_discount_percent :=
                (v_line ->> 'discount_percent')::numeric;

            if v_discount_percent
                   is distinct from v_customer_discount
               and not v_can_override_discount then
                raise exception
                    'You do not have permission to override the discount on line %.',
                    v_line_no;
            end if;
        end if;

        if v_discount_percent < 0
           or v_discount_percent > 100 then
            raise exception
                'Line % discount must be between 0 and 100.',
                v_line_no;
        end if;

        v_line_subtotal :=
            round(v_quantity * v_resolved_unit_price, 2);
        v_line_discount :=
            round(
                v_line_subtotal * v_discount_percent / 100,
                2
            );
        v_taxable_amount :=
            v_line_subtotal - v_line_discount;

        if v_line_amount_type = 'No Tax' then
            v_tax_rate := 0;
            v_line_tax := 0;
            v_line_total := v_taxable_amount;
        elsif v_line_amount_type = 'Inclusive' then
            v_line_tax :=
                case
                    when v_tax_rate = 0 then 0
                    else round(
                        v_taxable_amount
                        - (
                            v_taxable_amount
                            / (1 + v_tax_rate / 100)
                        ),
                        2
                    )
                end;
            v_line_total := v_taxable_amount;
        else
            v_line_tax :=
                round(
                    v_taxable_amount * v_tax_rate / 100,
                    2
                );
            v_line_total :=
                v_taxable_amount + v_line_tax;
        end if;

        v_subtotal := v_subtotal + v_line_subtotal;
        v_discount_total :=
            v_discount_total + v_line_discount;
        v_tax_total := v_tax_total + v_line_tax;
        v_invoice_total := v_invoice_total + v_line_total;
    end loop;

    insert into public.customer_invoices (
        customer_id,
        project_id,
        project_site_id,
        price_book_id,
        invoice_date,
        due_date,
        invoice_type,
        document_status,
        payment_status,
        due_status,
        subtotal_amount,
        discount_amount,
        tax_amount,
        total_amount,
        paid_amount,
        balance_amount,
        currency_code,
        payment_terms_type,
        payment_terms_days,
        line_amount_type,
        customer_reference,
        notes,
        original_invoice_id,
        credit_note_reason,
        retention_release_amount,
        created_by,
        updated_by
    )
    values (
        v_customer_id,
        v_project_id,
        v_site_id,
        v_price_book_id,
        v_invoice_date,
        v_due_date,
        v_invoice_type,
        'Draft',
        'Unpaid',
        'Not Applicable',
        round(v_subtotal, 2),
        round(v_discount_total, 2),
        round(v_tax_total, 2),
        round(v_invoice_total, 2),
        0,
        round(v_invoice_total, 2),
        v_currency,
        v_payment_terms_type,
        v_payment_terms_days,
        v_line_amount_type,
        nullif(btrim(p_invoice ->> 'customer_reference'), ''),
        nullif(btrim(p_invoice ->> 'notes'), ''),
        null,
        null,
        0,
        auth.uid(),
        auth.uid()
    )
    returning customer_invoice_id into v_invoice_id;

    for v_line in
        select value
        from jsonb_array_elements(p_lines)
    loop
        v_line_no := (v_line ->> 'line_no')::integer;
        v_product_id := nullif(v_line ->> 'product_id', '')::uuid;
        v_project_area_id :=
            nullif(v_line ->> 'project_area_id', '')::uuid;
        v_description :=
            btrim(coalesce(v_line ->> 'description', ''));
        v_notes := nullif(btrim(v_line ->> 'notes'), '');
        v_quantity := (v_line ->> 'quantity')::numeric;
        v_tax_rate :=
            coalesce(
                nullif(v_line ->> 'tax_rate', '')::numeric,
                0
            );

        v_product_code := null;
        v_product_name := null;
        v_product_type := null;
        v_is_service_item := false;
        v_sales_uom_code := null;
        v_base_uom_code := null;
        v_conversion_factor := null;
        v_base_quantity := null;
        v_allow_fractional := true;
        v_price_book_line_id := null;
        v_price_source := 'Manual';
        v_resolved_unit_price := null;
        v_original_unit_price := null;

        if v_product_id is not null then
            select
                p.product_code,
                p.product_name,
                p.product_type,
                p.is_service_item,
                coalesce(
                    nullif(v_line ->> 'sales_uom_code', ''),
                    p.default_sales_uom_code,
                    p.base_uom_code
                ),
                p.base_uom_code
            into
                v_product_code,
                v_product_name,
                v_product_type,
                v_is_service_item,
                v_sales_uom_code,
                v_base_uom_code
            from public.products p
            where p.product_id = v_product_id;

            if v_description = '' then
                v_description := v_product_name;
            end if;

            if v_sales_uom_code = v_base_uom_code then
                v_conversion_factor := 1;
                v_allow_fractional := true;
            else
                select
                    puc.conversion_factor,
                    puc.allow_fractional_quantity
                into
                    v_conversion_factor,
                    v_allow_fractional
                from public.product_uom_conversions puc
                where puc.product_id = v_product_id
                  and puc.from_uom_code = v_sales_uom_code
                  and puc.to_uom_code = v_base_uom_code
                  and puc.is_active = true
                  and puc.is_deleted = false
                order by puc.sort_order, puc.created_at
                limit 1;
            end if;

            v_base_quantity :=
                round(v_quantity * v_conversion_factor, 6);

            if v_price_book_id is not null then
                select
                    pbl.price_book_line_id,
                    pbl.unit_price
                into
                    v_price_book_line_id,
                    v_resolved_unit_price
                from public.price_book_lines pbl
                where pbl.price_book_id = v_price_book_id
                  and pbl.product_id = v_product_id
                  and pbl.is_active = true
                  and pbl.is_deleted = false
                  and (
                      pbl.effective_from is null
                      or pbl.effective_from <= v_invoice_date
                  )
                  and (
                      pbl.effective_to is null
                      or pbl.effective_to >= v_invoice_date
                  )
                order by pbl.effective_from desc nulls last,
                         pbl.created_at desc
                limit 1;

                if v_price_book_line_id is not null then
                    v_price_source := 'Price Book';
                end if;
            end if;
        end if;

        v_requested_unit_price :=
            nullif(v_line ->> 'unit_price', '')::numeric;

        if v_resolved_unit_price is null then
            v_resolved_unit_price := v_requested_unit_price;
            v_price_source := 'Manual';
        elsif v_requested_unit_price is not null
              and v_requested_unit_price
                  is distinct from v_resolved_unit_price then
            v_original_unit_price := v_resolved_unit_price;
            v_resolved_unit_price := v_requested_unit_price;
            v_price_source := 'Manual';
        end if;

        v_original_unit_price :=
            coalesce(v_original_unit_price, v_resolved_unit_price);
        v_discount_percent :=
            coalesce(
                nullif(v_line ->> 'discount_percent', '')::numeric,
                v_customer_discount
            );
        v_line_subtotal :=
            round(v_quantity * v_resolved_unit_price, 2);
        v_line_discount :=
            round(
                v_line_subtotal * v_discount_percent / 100,
                2
            );
        v_taxable_amount :=
            v_line_subtotal - v_line_discount;

        if v_line_amount_type = 'No Tax' then
            v_tax_rate := 0;
            v_line_tax := 0;
            v_line_total := v_taxable_amount;
        elsif v_line_amount_type = 'Inclusive' then
            v_line_tax :=
                case
                    when v_tax_rate = 0 then 0
                    else round(
                        v_taxable_amount
                        - (
                            v_taxable_amount
                            / (1 + v_tax_rate / 100)
                        ),
                        2
                    )
                end;
            v_line_total := v_taxable_amount;
        else
            v_line_tax :=
                round(
                    v_taxable_amount * v_tax_rate / 100,
                    2
                );
            v_line_total :=
                v_taxable_amount + v_line_tax;
        end if;

        v_line_type :=
            coalesce(
                nullif(btrim(v_line ->> 'line_type'), ''),
                case
                    when v_product_id is null then 'Manual'
                    when v_is_service_item
                         or v_product_type = 'Service'
                        then 'Service'
                    when v_product_type = 'Material'
                        then 'Material'
                    else 'Product'
                end
            );

        insert into public.customer_invoice_items (
            customer_invoice_id,
            line_no,
            line_type,
            product_id,
            product_code_snapshot,
            product_name_snapshot,
            project_area_id,
            description,
            sales_uom_code,
            base_uom_code,
            conversion_factor,
            base_quantity,
            allow_fractional_quantity,
            quantity,
            price_book_id,
            price_book_line_id,
            price_source,
            original_unit_price,
            unit_price,
            line_subtotal,
            discount_percent,
            discount_amount,
            tax_rate,
            tax_amount,
            line_total,
            notes,
            created_by,
            updated_by
        )
        values (
            v_invoice_id,
            v_line_no,
            v_line_type,
            v_product_id,
            v_product_code,
            v_product_name,
            v_project_area_id,
            v_description,
            v_sales_uom_code,
            v_base_uom_code,
            v_conversion_factor,
            v_base_quantity,
            v_allow_fractional,
            v_quantity,
            case
                when v_product_id is null then null
                else v_price_book_id
            end,
            v_price_book_line_id,
            v_price_source,
            v_original_unit_price,
            v_resolved_unit_price,
            v_line_subtotal,
            v_discount_percent,
            v_line_discount,
            v_tax_rate,
            v_line_tax,
            v_line_total,
            v_notes,
            auth.uid(),
            auth.uid()
        );
    end loop;

    for v_source in
        select value
        from jsonb_array_elements(p_sources)
    loop
        perform public.validate_invoice_source_context(
            v_customer_id,
            v_project_id,
            v_site_id,
            btrim(v_source ->> 'source_type'),
            nullif(v_source ->> 'source_id', '')::uuid,
            coalesce(
                nullif(v_source ->> 'source_amount', '')::numeric,
                0
            )
        );

        insert into public.invoice_sources (
            customer_invoice_id,
            source_type,
            source_id,
            source_amount,
            created_by,
            updated_by
        )
        values (
            v_invoice_id,
            btrim(v_source ->> 'source_type'),
            (v_source ->> 'source_id')::uuid,
            coalesce(
                nullif(v_source ->> 'source_amount', '')::numeric,
                0
            ),
            auth.uid(),
            auth.uid()
        );
    end loop;

    return v_invoice_id;
end;
$$;


ALTER FUNCTION "public"."_create_invoice_atomic_core"("p_invoice" "jsonb", "p_lines" "jsonb", "p_sources" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_invoice_active_allocated_amount"("p_invoice_id" "uuid") RETURNS numeric
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
    select coalesce(sum(a.allocated_amount), 0)
    from public.customer_payment_allocations a
    join public.customer_payments p
      on p.customer_payment_id = a.customer_payment_id
    where a.customer_invoice_id = p_invoice_id
      and a.is_deleted = false
      and a.reversed_at is null
      and p.is_deleted = false
      and p.payment_status = 'Recorded';
$$;


ALTER FUNCTION "public"."_invoice_active_allocated_amount"("p_invoice_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_payment_allocated_amount"("p_payment_id" "uuid") RETURNS numeric
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
    select coalesce(sum(a.allocated_amount), 0)
    from public.customer_payment_allocations a
    where a.customer_payment_id = p_payment_id
      and a.is_deleted = false
      and a.reversed_at is null;
$$;


ALTER FUNCTION "public"."_payment_allocated_amount"("p_payment_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_recalculate_invoice_payment_state"("p_invoice_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    v_invoice public.customer_invoices%rowtype;
    v_paid numeric(18,2);
    v_balance numeric(18,2);
    v_payment_status text;
begin
    select *
    into v_invoice
    from public.customer_invoices
    where customer_invoice_id = p_invoice_id
    for update;

    if not found then
        raise exception 'Invoice not found during payment-state recalculation.';
    end if;

    v_paid := round(public._invoice_active_allocated_amount(p_invoice_id), 2);
    v_balance := round(v_invoice.total_amount - v_paid, 2);

    if v_paid <= 0 then
        v_payment_status := 'Unpaid';
    elsif v_balance > 0 then
        v_payment_status := 'Partially Paid';
    elsif v_balance = 0 then
        v_payment_status := 'Paid';
    else
        v_payment_status := 'Overpaid';
    end if;

    update public.customer_invoices
    set
        paid_amount = v_paid,
        balance_amount = v_balance,
        payment_status = v_payment_status,
        updated_by = auth.uid()
    where customer_invoice_id = p_invoice_id;
end;
$$;


ALTER FUNCTION "public"."_recalculate_invoice_payment_state"("p_invoice_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_replace_purchase_order_lines_atomic"("p_purchase_order_id" "uuid", "p_supplier_id" "uuid", "p_header_project_id" "uuid", "p_header_site_id" "uuid", "p_lines" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
    v_auth_user_id uuid := auth.uid();
    v_line jsonb;
    v_line_no integer := 0;
    v_created_count integer := 0;

    v_product public.products%rowtype;
    v_supplier_link public.material_supplier_links%rowtype;
    v_stock_request_item public.stock_request_items%rowtype;
    v_stock_request public.stock_requests%rowtype;
    v_requirement_line public.material_requirement_lines%rowtype;
    v_requirement public.material_requirements%rowtype;

    v_purchase_order_line_id uuid;
    v_product_id uuid;
    v_material_supplier_link_id uuid;
    v_stock_request_item_id uuid;
    v_material_requirement_line_id uuid;

    v_source_type text;
    v_description text;
    v_purchase_uom_code text;
    v_base_uom_code text;
    v_conversion_factor numeric(18,6);
    v_allow_fractional boolean;
    v_quantity numeric(18,6);
    v_ordered_base_quantity numeric(18,6);
    v_unit_cost numeric(18,6);
    v_tax_rate numeric(8,4);
    v_discount_percent numeric(8,4);
    v_gross_amount numeric(18,6);
    v_discount_amount numeric(18,6);
    v_line_subtotal numeric(18,6);
    v_tax_amount numeric(18,6);
    v_line_total numeric(18,6);

    v_project_id uuid;
    v_site_id uuid;
    v_area_id uuid;
    v_required_by_date date;
    v_lead_time_days integer;
    v_supplier_product_code text;
    v_supplier_product_name text;
    v_tax_type text;
    v_notes text;

    v_existing_linked_base numeric(18,6);
    v_available_base numeric(18,6);
    v_approved_base numeric(18,6);
    v_already_ordered_base numeric(18,6);
begin
    if p_lines is null
       or jsonb_typeof(p_lines) <> 'array'
       or jsonb_array_length(p_lines) = 0 then
        raise exception 'At least one purchase order line is required.';
    end if;

    -- Deactivate/delete old Material Requirement links before replacing Draft lines.
    update public.material_requirement_procurement_links link_row
    set
        link_status = 'Cancelled',
        is_active = false,
        is_deleted = true,
        deleted_at = now(),
        updated_at = now(),
        updated_by = v_auth_user_id
    where link_row.purchase_order_line_id in (
        select purchase_order_line_id
        from public.purchase_order_lines
        where purchase_order_id = p_purchase_order_id
          and is_deleted = false
    )
      and link_row.is_deleted = false;

    -- Soft-delete current active Draft lines.
    update public.purchase_order_lines
    set
        is_deleted = true,
        deleted_at = now(),
        updated_at = now(),
        updated_by = v_auth_user_id
    where purchase_order_id = p_purchase_order_id
      and is_deleted = false;

    for v_line in
        select item.value
        from jsonb_array_elements(p_lines) item(value)
    loop
        v_line_no := v_line_no + 1;

        begin
            v_product_id := nullif(btrim(v_line ->> 'product_id'), '')::uuid;
            v_material_supplier_link_id :=
                nullif(btrim(v_line ->> 'material_supplier_link_id'), '')::uuid;
            v_stock_request_item_id :=
                nullif(btrim(v_line ->> 'stock_request_item_id'), '')::uuid;
            v_material_requirement_line_id :=
                nullif(btrim(v_line ->> 'material_requirement_line_id'), '')::uuid;
            v_project_id :=
                nullif(btrim(v_line ->> 'project_id'), '')::uuid;
            v_site_id :=
                nullif(btrim(v_line ->> 'site_id'), '')::uuid;
            v_area_id :=
                nullif(btrim(v_line ->> 'area_id'), '')::uuid;
            v_required_by_date :=
                nullif(v_line ->> 'required_by_date', '')::date;
        exception
            when invalid_text_representation then
                raise exception 'Invalid ID or date on purchase order line %.', v_line_no;
        end;

        if v_product_id is null then
            raise exception 'Product is required on purchase order line %.', v_line_no;
        end if;

        select *
        into v_product
        from public.products
        where product_id = v_product_id
          and is_deleted = false
          and is_active = true;

        if not found then
            raise exception 'Active product was not found on purchase order line %.', v_line_no;
        end if;

        v_source_type := coalesce(
            nullif(btrim(v_line ->> 'source_type'), ''),
            case
                when v_material_requirement_line_id is not null then 'MaterialRequirement'
                when v_stock_request_item_id is not null then 'StockRequest'
                else 'Manual'
            end
        );

        if v_source_type not in ('Manual', 'StockRequest', 'MaterialRequirement') then
            raise exception 'Invalid source type on purchase order line %.', v_line_no;
        end if;

        if (
            v_source_type = 'Manual'
            and (
                v_stock_request_item_id is not null
                or v_material_requirement_line_id is not null
            )
        ) or (
            v_source_type = 'StockRequest'
            and (
                v_stock_request_item_id is null
                or v_material_requirement_line_id is not null
            )
        ) or (
            v_source_type = 'MaterialRequirement'
            and (
                v_material_requirement_line_id is null
                or v_stock_request_item_id is not null
            )
        ) then
            raise exception 'Source fields are inconsistent on purchase order line %.', v_line_no;
        end if;

        -- Reset supplier-link-derived values for every loop.
        v_supplier_product_code := null;
        v_supplier_product_name := null;
        v_lead_time_days := null;
        v_tax_type := null;

        if v_material_supplier_link_id is not null then
            select *
            into v_supplier_link
            from public.material_supplier_links
            where material_supplier_link_id = v_material_supplier_link_id
              and product_id = v_product_id
              and supplier_id = p_supplier_id
              and is_deleted = false
              and is_active = true;

            if not found then
                raise exception 'Active supplier-product link was not found on purchase order line %.', v_line_no;
            end if;

            v_supplier_product_code := v_supplier_link.supplier_product_code;
            v_supplier_product_name := v_supplier_link.supplier_product_name;
            v_lead_time_days := v_supplier_link.lead_time_days;
            v_tax_type := v_supplier_link.default_tax_type;
        end if;

        v_purchase_uom_code := coalesce(
            nullif(btrim(v_line ->> 'purchase_uom_code'), ''),
            case
                when v_material_supplier_link_id is not null
                then v_supplier_link.purchase_uom_code
                else null
            end,
            v_product.default_purchase_uom_code,
            v_product.base_uom_code
        );

        v_base_uom_code := v_product.base_uom_code;

        if v_purchase_uom_code is null or v_base_uom_code is null then
            raise exception 'Purchase UOM or Base UOM is missing on purchase order line %.', v_line_no;
        end if;

        if v_purchase_uom_code = v_base_uom_code then
            v_conversion_factor := 1;
            begin
                v_allow_fractional := coalesce(
                    nullif(v_line ->> 'allow_fractional_quantity', '')::boolean,
                    true
                );
            exception
                when invalid_text_representation then
                    raise exception 'Invalid fractional-quantity setting on purchase order line %.', v_line_no;
            end;
        else
            select
                conversion_factor,
                allow_fractional_quantity
            into
                v_conversion_factor,
                v_allow_fractional
            from public.product_uom_conversions
            where product_id = v_product_id
              and from_uom_code = v_purchase_uom_code
              and to_uom_code = v_base_uom_code
              and is_deleted = false
              and is_active = true
            order by sort_order, created_at
            limit 1;

            if not found then
                raise exception
                    'No active UOM conversion from % to % on purchase order line %.',
                    v_purchase_uom_code,
                    v_base_uom_code,
                    v_line_no;
            end if;
        end if;

        begin
            v_quantity := nullif(v_line ->> 'quantity', '')::numeric;
            v_tax_rate := coalesce(
                nullif(v_line ->> 'tax_rate', '')::numeric,
                0
            );
            v_discount_percent := coalesce(
                nullif(v_line ->> 'discount_percent', '')::numeric,
                0
            );

            v_unit_cost := nullif(v_line ->> 'unit_cost', '')::numeric;

            if v_unit_cost is null and v_material_supplier_link_id is not null then
                v_unit_cost := coalesce(
                    v_supplier_link.last_purchase_price,
                    v_supplier_link.default_cost_price
                );
            end if;

            v_lead_time_days := coalesce(
                nullif(v_line ->> 'lead_time_days', '')::integer,
                v_lead_time_days
            );
        exception
            when invalid_text_representation then
                raise exception 'Invalid quantity, price, tax, discount or lead time on purchase order line %.', v_line_no;
        end;

        if v_quantity is null or v_quantity <= 0 then
            raise exception 'Quantity must be greater than zero on purchase order line %.', v_line_no;
        end if;

        if not coalesce(v_allow_fractional, true)
           and v_quantity <> trunc(v_quantity) then
            raise exception 'Fractional quantity is not allowed on purchase order line %.', v_line_no;
        end if;

        if v_unit_cost is null or v_unit_cost < 0 then
            raise exception 'Unit cost must be zero or greater on purchase order line %.', v_line_no;
        end if;

        if v_tax_rate < 0 or v_tax_rate > 100 then
            raise exception 'Tax rate must be between 0 and 100 on purchase order line %.', v_line_no;
        end if;

        if v_discount_percent < 0 or v_discount_percent > 100 then
            raise exception 'Discount percent must be between 0 and 100 on purchase order line %.', v_line_no;
        end if;

        if v_lead_time_days is not null and v_lead_time_days < 0 then
            raise exception 'Lead time cannot be negative on purchase order line %.', v_line_no;
        end if;

        v_ordered_base_quantity := round(v_quantity * v_conversion_factor, 6);

        v_gross_amount := round(v_quantity * v_unit_cost, 2);
        v_discount_amount := round(v_gross_amount * v_discount_percent / 100, 2);
        v_line_subtotal := round(v_gross_amount - v_discount_amount, 2);
        v_tax_amount := round(v_line_subtotal * v_tax_rate / 100, 2);
        v_line_total := round(v_line_subtotal + v_tax_amount, 2);

        v_project_id := coalesce(v_project_id, p_header_project_id);
        v_site_id := coalesce(v_site_id, p_header_site_id);

        v_description := coalesce(
            nullif(btrim(v_line ->> 'description'), ''),
            v_product.product_name
        );
        v_notes := nullif(btrim(v_line ->> 'notes'), '');

        v_supplier_product_code := coalesce(
            nullif(btrim(v_line ->> 'supplier_product_code'), ''),
            v_supplier_product_code
        );
        v_supplier_product_name := coalesce(
            nullif(btrim(v_line ->> 'supplier_product_name'), ''),
            v_supplier_product_name
        );
        v_tax_type := coalesce(
            nullif(btrim(v_line ->> 'tax_type'), ''),
            v_tax_type
        );

        -- -------------------------------------------------------------
        -- Stock Request source validation
        -- -------------------------------------------------------------
        if v_source_type = 'StockRequest' then
            select *
            into v_stock_request_item
            from public.stock_request_items
            where stock_request_item_id = v_stock_request_item_id
              and product_id = v_product_id
              and is_deleted = false
            for update;

            if not found then
                raise exception 'Stock Request item was not found on purchase order line %.', v_line_no;
            end if;

            select *
            into v_stock_request
            from public.stock_requests
            where stock_request_id = v_stock_request_item.stock_request_id
              and is_deleted = false
            for update;

            if not found then
                raise exception 'Stock Request was not found on purchase order line %.', v_line_no;
            end if;

            if v_stock_request.request_status not in (
                'Approved',
                'Ordered',
                'Partially Delivered'
            ) then
                raise exception
                    'Stock Request % is not eligible for purchase ordering.',
                    v_stock_request.stock_request_no;
            end if;

            if p_header_project_id is not null
               and p_header_project_id <> v_stock_request.project_id then
                raise exception 'Stock Request project does not match the Purchase Order.';
            end if;

            if p_header_site_id is not null
               and p_header_site_id <> v_stock_request.site_id then
                raise exception 'Stock Request site does not match the Purchase Order.';
            end if;

            v_approved_base := coalesce(
                v_stock_request_item.approved_base_quantity,
                case
                    when v_stock_request_item.approved_quantity is not null
                    then round(
                        v_stock_request_item.approved_quantity
                        * coalesce(v_stock_request_item.conversion_factor_to_base, 1),
                        6
                    )
                    else 0
                end
            );

            select coalesce(sum(existing_line.ordered_base_quantity), 0)
            into v_already_ordered_base
            from public.purchase_order_lines existing_line
            join public.purchase_orders existing_po
              on existing_po.purchase_order_id = existing_line.purchase_order_id
             and existing_po.is_deleted = false
             and existing_po.order_status <> 'Cancelled'
            where existing_line.stock_request_item_id = v_stock_request_item_id
              and existing_line.is_deleted = false;

            if v_ordered_base_quantity >
               round(v_approved_base - v_already_ordered_base, 6) then
                raise exception
                    'Quantity exceeds the remaining approved Stock Request quantity on purchase order line %.',
                    v_line_no;
            end if;

            v_project_id := v_stock_request.project_id;
            v_site_id := v_stock_request.site_id;
            v_area_id := coalesce(v_area_id, v_stock_request.area_id);
            v_required_by_date := coalesce(
                v_required_by_date,
                v_stock_request.required_date
            );
        end if;

        -- -------------------------------------------------------------
        -- Material Requirement source validation and outstanding control
        -- -------------------------------------------------------------
        if v_source_type = 'MaterialRequirement' then
            select *
            into v_requirement_line
            from public.material_requirement_lines
            where material_requirement_line_id = v_material_requirement_line_id
              and product_id = v_product_id
              and is_deleted = false
              and is_active = true
            for update;

            if not found then
                raise exception 'Material Requirement line was not found on purchase order line %.', v_line_no;
            end if;

            select *
            into v_requirement
            from public.material_requirements
            where material_requirement_id = v_requirement_line.material_requirement_id
              and is_deleted = false
              and is_active = true
            for update;

            if not found then
                raise exception 'Material Requirement was not found on purchase order line %.', v_line_no;
            end if;

            if v_requirement.requirement_status not in (
                'Approved',
                'InPreparation',
                'PartiallyReady'
            ) then
                raise exception
                    'Material Requirement % is not eligible for purchase ordering.',
                    v_requirement.material_requirement_no;
            end if;

            if v_requirement_line.line_status not in (
                'Required',
                'PartiallyAllocated',
                'Ordered'
            ) then
                raise exception
                    'Material Requirement line % is not eligible for purchase ordering.',
                    v_requirement_line.line_no;
            end if;

            if v_base_uom_code <> v_requirement_line.base_uom_code then
                raise exception
                    'Material Requirement Base UOM does not match the product on purchase order line %.',
                    v_line_no;
            end if;

            select coalesce(sum(link_row.linked_base_quantity), 0)
            into v_existing_linked_base
            from public.material_requirement_procurement_links link_row
            where link_row.material_requirement_line_id =
                  v_material_requirement_line_id
              and link_row.is_deleted = false
              and link_row.is_active = true
              and link_row.link_status in ('Active', 'Completed');

            v_available_base := round(
                v_requirement_line.required_base_quantity
                - v_existing_linked_base,
                6
            );

            if v_ordered_base_quantity > v_available_base then
                raise exception
                    'Quantity exceeds Material Requirement procurement outstanding on purchase order line %. Available base quantity: % %.',
                    v_line_no,
                    v_available_base,
                    v_requirement_line.base_uom_code;
            end if;

            if p_header_project_id is not null
               and p_header_project_id <> v_requirement.project_id then
                raise exception 'Material Requirement project does not match the Purchase Order.';
            end if;

            if p_header_site_id is not null
               and p_header_site_id is distinct from v_requirement.site_id then
                raise exception 'Material Requirement site does not match the Purchase Order.';
            end if;

            v_project_id := v_requirement.project_id;
            v_site_id := v_requirement.site_id;
            v_area_id := coalesce(v_area_id, v_requirement_line.project_area_id);
            v_required_by_date := coalesce(
                v_required_by_date,
                v_requirement_line.required_by_date,
                v_requirement.required_by_date
            );
        end if;

        if p_header_project_id is not null
           and v_project_id is distinct from p_header_project_id then
            raise exception 'Line project does not match Purchase Order project on line %.', v_line_no;
        end if;

        if p_header_site_id is not null
           and v_site_id is distinct from p_header_site_id then
            raise exception 'Line site does not match Purchase Order site on line %.', v_line_no;
        end if;

        insert into public.purchase_order_lines (
            purchase_order_id,
            product_id,
            line_no,
            description,
            unit_of_measure,
            quantity,
            unit_cost,
            tax_rate,
            tax_amount,
            line_total,
            notes,
            is_deleted,
            created_by,
            updated_by,
            project_id,
            site_id,
            area_id,
            stock_request_item_id,
            purchase_uom_code,
            base_uom_code,
            conversion_factor_to_base,
            ordered_base_quantity,
            allow_fractional_quantity,
            material_supplier_link_id,
            source_type,
            supplier_product_code,
            supplier_product_name,
            required_by_date,
            lead_time_days,
            discount_percent,
            discount_amount,
            line_subtotal,
            tax_type,
            source_snapshot
        )
        values (
            p_purchase_order_id,
            v_product_id,
            v_line_no,
            v_description,
            v_purchase_uom_code,
            round(v_quantity, 6),
            round(v_unit_cost, 6),
            round(v_tax_rate, 4),
            v_tax_amount,
            v_line_total,
            v_notes,
            false,
            v_auth_user_id,
            v_auth_user_id,
            v_project_id,
            v_site_id,
            v_area_id,
            v_stock_request_item_id,
            v_purchase_uom_code,
            v_base_uom_code,
            round(v_conversion_factor, 6),
            v_ordered_base_quantity,
            v_allow_fractional,
            v_material_supplier_link_id,
            v_source_type,
            v_supplier_product_code,
            v_supplier_product_name,
            v_required_by_date,
            v_lead_time_days,
            round(v_discount_percent, 2),
            v_discount_amount,
            v_line_subtotal,
            v_tax_type,
            jsonb_build_object(
                'source_type', v_source_type,
                'material_requirement_line_id', v_material_requirement_line_id,
                'stock_request_item_id', v_stock_request_item_id,
                'product_id', v_product_id,
                'product_code', v_product.product_code,
                'product_name', v_product.product_name,
                'purchase_uom_code', v_purchase_uom_code,
                'base_uom_code', v_base_uom_code,
                'conversion_factor_to_base', v_conversion_factor,
                'material_supplier_link_id', v_material_supplier_link_id,
                'supplier_product_code', v_supplier_product_code,
                'supplier_product_name', v_supplier_product_name
            )
        )
        returning purchase_order_line_id
        into v_purchase_order_line_id;

        if v_source_type = 'MaterialRequirement' then
            insert into public.material_requirement_procurement_links (
                material_requirement_line_id,
                link_type,
                purchase_order_line_id,
                linked_base_quantity,
                base_uom_code,
                link_status,
                notes,
                is_active,
                is_deleted,
                created_by,
                updated_by
            )
            values (
                v_material_requirement_line_id,
                'PurchaseOrder',
                v_purchase_order_line_id,
                v_ordered_base_quantity,
                v_base_uom_code,
                'Active',
                'Created by Purchase Order atomic workflow.',
                true,
                false,
                v_auth_user_id,
                v_auth_user_id
            );
        end if;

        v_created_count := v_created_count + 1;
    end loop;

    return jsonb_build_object(
        'created_line_count', v_created_count
    );
end;
$$;


ALTER FUNCTION "public"."_replace_purchase_order_lines_atomic"("p_purchase_order_id" "uuid", "p_supplier_id" "uuid", "p_header_project_id" "uuid", "p_header_site_id" "uuid", "p_lines" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_validate_payment_invoice"("p_payment_id" "uuid", "p_invoice_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    v_payment_customer_id uuid;
    v_payment_currency text;
    v_payment_status text;
    v_payment_deleted boolean;
    v_invoice_customer_id uuid;
    v_invoice_currency text;
    v_invoice_type text;
    v_document_status text;
    v_invoice_deleted boolean;
begin
    select customer_id, currency_code, payment_status, is_deleted
    into v_payment_customer_id, v_payment_currency, v_payment_status, v_payment_deleted
    from public.customer_payments
    where customer_payment_id = p_payment_id;

    if v_payment_customer_id is null then
        raise exception 'Customer Payment not found.';
    end if;

    if v_payment_deleted then
        raise exception 'Archived Customer Payment cannot be allocated.';
    end if;

    if v_payment_status <> 'Recorded' then
        raise exception 'Only Recorded Customer Payments can be allocated.';
    end if;

    select customer_id, currency_code, invoice_type, document_status, is_deleted
    into v_invoice_customer_id, v_invoice_currency, v_invoice_type, v_document_status, v_invoice_deleted
    from public.customer_invoices
    where customer_invoice_id = p_invoice_id;

    if v_invoice_customer_id is null then
        raise exception 'Customer Invoice not found.';
    end if;

    if v_invoice_deleted then
        raise exception 'Archived Customer Invoice cannot receive a Payment.';
    end if;

    if v_document_status <> 'Issued' then
        raise exception 'Payments can only be allocated to Issued Invoices.';
    end if;

    if v_invoice_type = 'Credit Note' then
        raise exception 'Payments cannot be allocated to Credit Notes.';
    end if;

    if v_payment_customer_id <> v_invoice_customer_id then
        raise exception 'Payment Customer does not match Invoice Customer.';
    end if;

    if v_payment_currency <> v_invoice_currency then
        raise exception 'Payment currency does not match Invoice currency.';
    end if;
end;
$$;


ALTER FUNCTION "public"."_validate_payment_invoice"("p_payment_id" "uuid", "p_invoice_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."accept_quotation_atomic"("p_quotation_id" "uuid", "p_required_by_date" "date" DEFAULT NULL::"date", "p_delivery_stock_location_id" "uuid" DEFAULT NULL::"uuid", "p_responsible_auth_user_id" "uuid" DEFAULT NULL::"uuid", "p_material_requirement_notes" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    v_user_id uuid;

    v_quotation public.quotations%rowtype;

    v_site_id uuid;
    v_project_id uuid;

    v_accepted_revision_id uuid;
    v_material_requirement_id uuid;
    v_promoted_area_count integer;
begin
    -- ========================================================
    -- 1. AUTHENTICATION AND PERMISSIONS
    -- ========================================================

    v_user_id := auth.uid();

    if v_user_id is null then
        raise exception
            'Authentication is required.';
    end if;

    if not public.has_permission(
        'quotations.accept'
    ) then
        raise exception
            'Permission denied: quotations.accept';
    end if;

    if not public.has_permission(
        'material_requirements.create'
    ) then
        raise exception
            'Permission denied: material_requirements.create';
    end if;


    -- ========================================================
    -- 2. LOCK AND LOAD QUOTATION
    -- ========================================================

    select q.*
    into v_quotation
    from public.quotations q
    where q.quotation_id = p_quotation_id
      and q.is_deleted = false
    for update;

    if not found then
        raise exception
            'Quotation not found.';
    end if;

    if v_quotation.is_active = false then
        raise exception
            'Inactive quotation cannot be accepted.';
    end if;

    if v_quotation.quotation_status = 'Accepted' then
        raise exception
            'Quotation has already been accepted.';
    end if;

    if v_quotation.quotation_status not in (
        'Sent',
        'Revised'
    ) then
        raise exception
            'Only Sent or Revised quotations can be accepted. Current status: %',
            v_quotation.quotation_status;
    end if;

    if v_quotation.project_site_id is null then
        raise exception
            'Quotation does not have a Project Site.';
    end if;


    -- ========================================================
    -- 3. RESOLVE PROJECT AND SITE
    -- ========================================================

    select
        ps.site_id,
        ps.project_id
    into
        v_site_id,
        v_project_id
    from public.project_sites ps
    where ps.site_id = v_quotation.project_site_id
      and ps.is_deleted = false
    for update;

    if not found then
        raise exception
            'Project Site linked to the quotation was not found or has been deleted.';
    end if;

    if v_project_id is null then
        raise exception
            'Project Site does not have a Project.';
    end if;

    perform 1
    from public.projects pr
    where pr.project_id = v_project_id
      and pr.is_deleted = false
    for update;

    if not found then
        raise exception
            'Project linked to the quotation Site was not found or has been deleted.';
    end if;


    -- ========================================================
    -- 4. VALIDATE ORIGINAL OR REVISED ACCEPTANCE SOURCE
    -- ========================================================

    if v_quotation.quotation_status = 'Sent' then
        -- Original quotation acceptance.

        if v_quotation.current_revision_id is not null then
            raise exception
                'Sent quotation has a current revision. It must use the Revised workflow.';
        end if;

        v_accepted_revision_id := null;

    else
        -- Revised quotation acceptance.

        if v_quotation.current_revision_id is null then
            raise exception
                'Revised quotation does not have a current revision.';
        end if;

        select qr.revision_id
        into v_accepted_revision_id
        from public.quotation_revisions qr
        where qr.revision_id =
              v_quotation.current_revision_id
          and qr.quotation_id =
              v_quotation.quotation_id
          and qr.revision_status = 'Sent'
          and qr.is_deleted = false
          and qr.is_active = true
        for update;

        if not found then
            raise exception
                'Current quotation revision was not found, does not belong to this quotation, or is not Sent.';
        end if;
    end if;


    -- ========================================================
    -- 5. ACCEPT REVISION WHEN APPLICABLE
    -- ========================================================

    if v_accepted_revision_id is not null then
        update public.quotation_revisions
        set
            revision_status = 'Accepted',
            accepted_at = now(),
            accepted_by = v_user_id,
            updated_at = now(),
            updated_by = v_user_id
        where revision_id = v_accepted_revision_id;
    end if;


    -- ========================================================
    -- 6. ACCEPT QUOTATION
    -- ========================================================

    update public.quotations
    set
        quotation_status = 'Accepted',
        accepted_revision_id = v_accepted_revision_id,
        accepted_at = now(),
        accepted_by = v_user_id,
        updated_at = now(),
        updated_by = v_user_id
    where quotation_id = p_quotation_id;


    -- ========================================================
    -- 7. PROMOTE PROVISIONAL PROJECT
    -- ========================================================

    update public.projects
    set
        project_status = 'Approved',
        is_active = true,
        updated_at = now(),
        updated_by = v_user_id
    where project_id = v_project_id
      and is_deleted = false
      and project_status in (
          'Draft',
          'Quoted'
      );


    -- ========================================================
    -- 8. PROMOTE PROVISIONAL SITE
    -- ========================================================

    update public.project_sites
    set
        site_status = 'Active',
        is_active = true,
        updated_at = now(),
        updated_by = v_user_id
    where site_id = v_site_id
      and is_deleted = false
      and site_status = 'Quotation';


    -- ========================================================
    -- 9. PROMOTE ONLY AREAS IN THE ACCEPTED COMMERCIAL SOURCE
    -- ========================================================

    if v_accepted_revision_id is null then
        -- ----------------------------------------------------
        -- Accepted Base Quotation
        -- ----------------------------------------------------

        update public.project_areas pa
        set
            area_status = 'Active',
            is_active = true,
            updated_at = now(),
            updated_by = v_user_id
        where pa.project_id = v_project_id
          and pa.site_id = v_site_id
          and pa.is_deleted = false
          and pa.area_status = 'Quotation'
          and exists (
              select 1
              from public.quotation_lines ql
              where ql.quotation_id =
                    p_quotation_id
                and ql.project_area_id =
                    pa.area_id
                and ql.is_deleted = false
          );

    else
        -- ----------------------------------------------------
        -- Accepted Quotation Revision
        -- ----------------------------------------------------

        update public.project_areas pa
        set
            area_status = 'Active',
            is_active = true,
            updated_at = now(),
            updated_by = v_user_id
        where pa.project_id = v_project_id
          and pa.site_id = v_site_id
          and pa.is_deleted = false
          and pa.area_status = 'Quotation'
          and exists (
              select 1
              from public.quotation_revision_lines qrl
              where qrl.revision_id =
                    v_accepted_revision_id
                and qrl.project_area_id =
                    pa.area_id
                and qrl.is_deleted = false
          );
    end if;

    get diagnostics
        v_promoted_area_count = row_count;


    -- ========================================================
    -- 10. GENERATE MATERIAL REQUIREMENT
    -- ========================================================

    v_material_requirement_id :=
        public.generate_material_requirement_from_accepted_quotation(
            p_quotation_id,
            p_required_by_date,
            p_delivery_stock_location_id,
            p_responsible_auth_user_id,
            p_material_requirement_notes
        );


    -- Deferred revision-pointer constraints are checked
    -- before returning from the transaction.

    set constraints all immediate;


    return v_material_requirement_id;
end;
$$;


ALTER FUNCTION "public"."accept_quotation_atomic"("p_quotation_id" "uuid", "p_required_by_date" "date", "p_delivery_stock_location_id" "uuid", "p_responsible_auth_user_id" "uuid", "p_material_requirement_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."accept_variation_atomic"("p_variation_id" "uuid", "p_required_by_date" "date" DEFAULT NULL::"date", "p_delivery_stock_location_id" "uuid" DEFAULT NULL::"uuid", "p_responsible_auth_user_id" "uuid" DEFAULT NULL::"uuid", "p_material_requirement_notes" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    v_user_id uuid := auth.uid();
    v_variation public.variations%rowtype;
    v_mr_id uuid;
begin
    if v_user_id is null then
        raise exception 'Authentication is required.';
    end if;

    if not public.has_permission('variations.accept') then
        raise exception 'Permission denied: variations.accept is required.';
    end if;

    if not public.has_permission('material_requirements.create') then
        raise exception 'Permission denied: material_requirements.create is required.';
    end if;

    select *
    into v_variation
    from public.variations
    where variation_id = p_variation_id
      and is_active = true
      and is_deleted = false
    for update;

    if not found then
        raise exception 'Variation was not found, is inactive, or is archived.';
    end if;

    if v_variation.variation_status = 'Accepted' then
        raise exception 'Variation has already been accepted.';
    end if;

    if v_variation.variation_status <> 'Sent' then
        raise exception 'Only a Sent Variation can be accepted. Current status: %.', v_variation.variation_status;
    end if;

    if not exists (
        select 1 from public.variation_lines
        where variation_id = p_variation_id
          and is_deleted = false
    ) then
        raise exception 'At least one active Variation line is required.';
    end if;

    update public.variations
    set
        variation_status = 'Accepted',
        accepted_at = now(),
        accepted_by = v_user_id,
        rejected_at = null,
        rejected_by = null,
        rejection_reason = null,
        cancelled_at = null,
        cancelled_by = null,
        cancellation_reason = null,
        updated_by = v_user_id
    where variation_id = p_variation_id
      and variation_status = 'Sent';

    if not found then
        raise exception 'Variation could not be accepted because its workflow state changed.';
    end if;

    update public.project_areas pa
    set
        area_status = 'Active',
        is_active = true,
        updated_at = now(),
        updated_by = v_user_id
    where pa.project_id = v_variation.project_id
      and pa.site_id = v_variation.project_site_id
      and pa.area_status = 'Quotation'
      and pa.is_deleted = false
      and exists (
          select 1
          from public.variation_lines vl
          where vl.variation_id = p_variation_id
            and vl.project_area_id = pa.area_id
            and vl.is_deleted = false
      );

    v_mr_id :=
        public.generate_material_requirement_from_accepted_variation(
            p_variation_id,
            p_required_by_date,
            p_delivery_stock_location_id,
            p_responsible_auth_user_id,
            p_material_requirement_notes
        );

    return v_mr_id;
end;
$$;


ALTER FUNCTION "public"."accept_variation_atomic"("p_variation_id" "uuid", "p_required_by_date" "date", "p_delivery_stock_location_id" "uuid", "p_responsible_auth_user_id" "uuid", "p_material_requirement_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_material_requirement_operational_line"("p_material_requirement_id" "uuid", "p_product_id" "uuid", "p_project_area_id" "uuid", "p_description" "text", "p_requirement_uom_code" "text", "p_requirement_quantity" numeric, "p_base_uom_code" "text", "p_adjustment_reason" "text", "p_conversion_factor_to_base" numeric DEFAULT 1, "p_allow_fractional_quantity" boolean DEFAULT true, "p_waste_percent" numeric DEFAULT 0, "p_preferred_supplier_id" "uuid" DEFAULT NULL::"uuid", "p_required_by_date" "date" DEFAULT NULL::"date", "p_notes" "text" DEFAULT NULL::"text", "p_commercial_impact" "text" DEFAULT 'None'::"text", "p_variation_required" boolean DEFAULT false, "p_variation_status" "text" DEFAULT 'NotRequired'::"text", "p_variation_reference" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_actor uuid;
    v_header public.material_requirements%ROWTYPE;
    v_line public.material_requirement_lines%ROWTYPE;

    v_adjustment_id uuid;
    v_next_line_no integer;

    v_description text;
    v_adjustment_reason text;
    v_notes text;
    v_variation_reference text;

    v_approval_required boolean;
    v_approval_status text;
BEGIN
    -- ================================================================
    -- Authentication and permission
    -- ================================================================

    v_actor := auth.uid();

    IF v_actor IS NULL THEN
        RAISE EXCEPTION
            'Authentication is required.';
    END IF;

    IF NOT public.has_permission(
        'material_requirements.adjust'
    ) THEN
        RAISE EXCEPTION
            'Permission denied: material_requirements.adjust is required.';
    END IF;


    -- ================================================================
    -- Normalize and validate input
    -- ================================================================

    v_description :=
        NULLIF(
            btrim(p_description),
            ''
        );

    v_adjustment_reason :=
        NULLIF(
            btrim(p_adjustment_reason),
            ''
        );

    v_notes :=
        NULLIF(
            btrim(p_notes),
            ''
        );

    v_variation_reference :=
        NULLIF(
            btrim(p_variation_reference),
            ''
        );

    IF p_material_requirement_id IS NULL THEN
        RAISE EXCEPTION
            'Material Requirement ID is required.';
    END IF;

    IF v_description IS NULL THEN
        RAISE EXCEPTION
            'Description is required.';
    END IF;

    IF v_adjustment_reason IS NULL THEN
        RAISE EXCEPTION
            'Adjustment reason is required.';
    END IF;

    IF NULLIF(
        btrim(p_requirement_uom_code),
        ''
    ) IS NULL THEN
        RAISE EXCEPTION
            'Requirement UOM is required.';
    END IF;

    IF NULLIF(
        btrim(p_base_uom_code),
        ''
    ) IS NULL THEN
        RAISE EXCEPTION
            'Base UOM is required.';
    END IF;

    IF p_requirement_quantity IS NULL
       OR p_requirement_quantity < 0 THEN
        RAISE EXCEPTION
            'Requirement quantity must be zero or greater.';
    END IF;

    IF p_conversion_factor_to_base IS NULL
       OR p_conversion_factor_to_base <= 0 THEN
        RAISE EXCEPTION
            'Conversion factor to Base UOM must be greater than zero.';
    END IF;

    IF p_waste_percent IS NULL
       OR p_waste_percent < 0 THEN
        RAISE EXCEPTION
            'Waste percent must be zero or greater.';
    END IF;

    IF p_commercial_impact NOT IN (
        'None',
        'Internal',
        'CustomerCharge',
        'CustomerCredit',
        'PendingReview'
    ) THEN
        RAISE EXCEPTION
            'Invalid commercial impact: %.',
            p_commercial_impact;
    END IF;

    IF p_variation_status NOT IN (
        'NotRequired',
        'Required',
        'Pending',
        'Approved',
        'Rejected',
        'Cancelled'
    ) THEN
        RAISE EXCEPTION
            'Invalid variation status: %.',
            p_variation_status;
    END IF;

    IF p_variation_required = false
       AND p_variation_status <> 'NotRequired' THEN
        RAISE EXCEPTION
            'Variation status must be NotRequired when variation_required is false.';
    END IF;

    IF p_variation_required = true
       AND p_variation_status = 'NotRequired' THEN
        RAISE EXCEPTION
            'Variation status cannot be NotRequired when variation_required is true.';
    END IF;

    IF p_commercial_impact IN (
        'CustomerCharge',
        'CustomerCredit'
    )
       AND p_variation_required = false THEN
        RAISE EXCEPTION
            'Customer Charge or Customer Credit requires a Variation.';
    END IF;


    -- ================================================================
    -- Lock Header
    --
    -- Locking the Header serializes line-number allocation for this
    -- Material Requirement and prevents two concurrent requests from
    -- receiving the same line number.
    -- ================================================================

    SELECT mr.*
    INTO v_header
    FROM public.material_requirements mr
    WHERE mr.material_requirement_id =
              p_material_requirement_id
      AND mr.is_deleted = false
      AND mr.is_active = true
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'Active Material Requirement was not found.';
    END IF;

    IF v_header.requirement_status <> 'Draft' THEN
        RAISE EXCEPTION
            'Operational lines may currently be added only while the Material Requirement is Draft. Current status: %.',
            v_header.requirement_status;
    END IF;


    -- ================================================================
    -- Validate referenced records without assuming optional columns
    -- ================================================================

    IF p_product_id IS NOT NULL
       AND NOT EXISTS (
           SELECT 1
           FROM public.products product_row
           WHERE product_row.product_id = p_product_id
       ) THEN
        RAISE EXCEPTION
            'Selected Product was not found.';
    END IF;

    IF p_project_area_id IS NOT NULL
       AND NOT EXISTS (
           SELECT 1
           FROM public.project_areas area_row
           WHERE area_row.area_id = p_project_area_id
       ) THEN
        RAISE EXCEPTION
            'Selected Project Area was not found.';
    END IF;

    IF p_preferred_supplier_id IS NOT NULL
       AND NOT EXISTS (
           SELECT 1
           FROM public.suppliers supplier_row
           WHERE supplier_row.supplier_id =
                     p_preferred_supplier_id
       ) THEN
        RAISE EXCEPTION
            'Selected Preferred Supplier was not found.';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM public.units_of_measure uom
        WHERE uom.uom_code =
              btrim(p_requirement_uom_code)
    ) THEN
        RAISE EXCEPTION
            'Requirement UOM was not found: %.',
            p_requirement_uom_code;
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM public.units_of_measure uom
        WHERE uom.uom_code =
              btrim(p_base_uom_code)
    ) THEN
        RAISE EXCEPTION
            'Base UOM was not found: %.',
            p_base_uom_code;
    END IF;


    -- ================================================================
    -- Allocate next active line number
    -- ================================================================

    SELECT COALESCE(
        max(mrl.line_no),
        0
    ) + 1
    INTO v_next_line_no
    FROM public.material_requirement_lines mrl
    WHERE mrl.material_requirement_id =
              p_material_requirement_id
      AND mrl.is_deleted = false;


    -- ================================================================
    -- Insert current operational line
    --
    -- Source columns use neutral values because this line was not
    -- derived from an Accepted Quotation line.
    --
    -- The existing quantity-calculation trigger will calculate:
    --   required_base_quantity_before_waste
    --   waste_base_quantity
    --   required_base_quantity
    -- ================================================================

    INSERT INTO public.material_requirement_lines (
        material_requirement_id,
        line_no,
        line_origin,

        source_quotation_line_id,
        source_revision_line_id,
        source_product_id,
        source_product_code,
        source_product_name,
        source_description,
        source_uom_code,
        source_quantity,
        source_base_uom_code,
        source_conversion_factor,
        source_base_quantity,
        source_allow_fractional_quantity,
        source_is_optional,

        project_area_id,
        product_id,
        description,

        requirement_uom_code,
        requirement_quantity,
        base_uom_code,
        conversion_factor_to_base,
        allow_fractional_quantity,
        waste_percent,

        preferred_supplier_id,
        required_by_date,
        line_status,
        exclusion_reason,
        notes,

        commercial_impact,
        variation_required,
        variation_status,
        variation_reference,

        is_active,
        is_deleted,
        created_by,
        updated_by
    )
    VALUES (
        p_material_requirement_id,
        v_next_line_no,
        'OperationalAddition',

        NULL,
        NULL,
        NULL,
        NULL,
        NULL,
        v_description,
        NULL,
        0,
        NULL,
        1,
        0,
        p_allow_fractional_quantity,
        false,

        p_project_area_id,
        p_product_id,
        v_description,

        btrim(p_requirement_uom_code),
        p_requirement_quantity,
        btrim(p_base_uom_code),
        p_conversion_factor_to_base,
        p_allow_fractional_quantity,
        p_waste_percent,

        p_preferred_supplier_id,
        p_required_by_date,
        'Required',
        NULL,
        v_notes,

        p_commercial_impact,
        p_variation_required,
        p_variation_status,
        v_variation_reference,

        true,
        false,
        v_actor,
        v_actor
    )
    RETURNING *
    INTO v_line;


    -- ================================================================
    -- Determine adjustment approval state
    -- ================================================================

    v_approval_required :=
        p_commercial_impact IN (
            'CustomerCharge',
            'CustomerCredit',
            'PendingReview'
        );

    v_approval_status :=
        CASE
            WHEN v_approval_required
                THEN 'Pending'
            ELSE 'NotRequired'
        END;


    -- ================================================================
    -- Insert append-only adjustment event
    -- ================================================================

    INSERT INTO public.material_requirement_line_adjustments (
        material_requirement_line_id,
        adjustment_no,
        adjustment_type,
        adjustment_reason,

        before_snapshot,
        after_snapshot,
        base_quantity_change,

        commercial_impact,
        variation_required,

        approval_required,
        approval_status,

        created_by
    )
    VALUES (
        v_line.material_requirement_line_id,
        1,
        'Add',
        v_adjustment_reason,

        NULL,
        to_jsonb(v_line),
        v_line.required_base_quantity,

        v_line.commercial_impact,
        v_line.variation_required,

        v_approval_required,
        v_approval_status,

        v_actor
    )
    RETURNING material_requirement_line_adjustment_id
    INTO v_adjustment_id;


    -- ================================================================
    -- Update Header audit timestamp
    -- ================================================================

    UPDATE public.material_requirements
    SET
        updated_at = now(),
        updated_by = v_actor
    WHERE material_requirement_id =
          p_material_requirement_id;


    -- ================================================================
    -- Return new current state and history identity
    -- ================================================================

    RETURN jsonb_build_object(
        'material_requirement_id',
            p_material_requirement_id,
        'material_requirement_line_id',
            v_line.material_requirement_line_id,
        'line_no',
            v_line.line_no,
        'line_origin',
            v_line.line_origin,
        'adjustment_id',
            v_adjustment_id,
        'adjustment_no',
            1,
        'line',
            to_jsonb(v_line)
    );
END;
$$;


ALTER FUNCTION "public"."add_material_requirement_operational_line"("p_material_requirement_id" "uuid", "p_product_id" "uuid", "p_project_area_id" "uuid", "p_description" "text", "p_requirement_uom_code" "text", "p_requirement_quantity" numeric, "p_base_uom_code" "text", "p_adjustment_reason" "text", "p_conversion_factor_to_base" numeric, "p_allow_fractional_quantity" boolean, "p_waste_percent" numeric, "p_preferred_supplier_id" "uuid", "p_required_by_date" "date", "p_notes" "text", "p_commercial_impact" "text", "p_variation_required" boolean, "p_variation_status" "text", "p_variation_reference" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."add_material_requirement_operational_line"("p_material_requirement_id" "uuid", "p_product_id" "uuid", "p_project_area_id" "uuid", "p_description" "text", "p_requirement_uom_code" "text", "p_requirement_quantity" numeric, "p_base_uom_code" "text", "p_adjustment_reason" "text", "p_conversion_factor_to_base" numeric, "p_allow_fractional_quantity" boolean, "p_waste_percent" numeric, "p_preferred_supplier_id" "uuid", "p_required_by_date" "date", "p_notes" "text", "p_commercial_impact" "text", "p_variation_required" boolean, "p_variation_status" "text", "p_variation_reference" "text") IS 'Atomically adds an OperationalAddition line to a Draft Material Requirement and records adjustment event number 1. Does not modify the Accepted commercial source, stock, or Purchase Orders.';



CREATE OR REPLACE FUNCTION "public"."admin_list_app_users"("p_search" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 100, "p_offset" integer DEFAULT 0) RETURNS TABLE("app_user_id" "uuid", "auth_user_id" "uuid", "email" "text", "display_name" "text", "phone" "text", "account_status" "text", "role_id" "uuid", "role_code" "text", "role_name" "text", "approved_at" timestamp with time zone, "approved_by" "uuid", "suspended_at" timestamp with time zone, "suspension_reason" "text", "rejected_at" timestamp with time zone, "rejection_reason" "text", "admin_notes" "text", "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "total_count" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
    IF NOT (
        public.has_permission('users.view')
        OR public.has_permission('users.manage_accounts')
        OR public.can_manage_permissions()
    ) THEN
        RAISE EXCEPTION
            'Permission denied: users.view';
    END IF;

    RETURN QUERY
    SELECT
        au.app_user_id,
        au.auth_user_id,
        au.email,
        au.display_name,
        au.phone,
        au.account_status,

        active_role.role_id,
        active_role.role_code,
        active_role.role_name,

        au.approved_at,
        au.approved_by,

        au.suspended_at,
        au.suspension_reason,

        au.rejected_at,
        au.rejection_reason,

        au.admin_notes,
        au.created_at,
        au.updated_at,

        count(*) OVER () AS total_count

    FROM public.app_users au

    LEFT JOIN LATERAL (
        SELECT
            ar.role_id,
            ar.role_code,
            ar.role_name
        FROM public.app_user_roles aur
        JOIN public.app_roles ar
          ON ar.role_id = aur.role_id
        WHERE aur.auth_user_id = au.auth_user_id
          AND aur.is_active = true
          AND ar.is_active = true
        ORDER BY aur.assigned_at DESC
        LIMIT 1
    ) active_role
      ON true

    WHERE
        (
            NULLIF(btrim(p_search), '') IS NULL
            OR au.email ILIKE '%' || btrim(p_search) || '%'
            OR COALESCE(au.display_name, '')
                ILIKE '%' || btrim(p_search) || '%'
            OR COALESCE(au.phone, '')
                ILIKE '%' || btrim(p_search) || '%'
        )
        AND
        (
            NULLIF(btrim(p_status), '') IS NULL
            OR au.account_status = btrim(p_status)
        )

    ORDER BY
        CASE au.account_status
            WHEN 'Pending' THEN 1
            WHEN 'Suspended' THEN 2
            WHEN 'Active' THEN 3
            WHEN 'Rejected' THEN 4
            ELSE 5
        END,
        au.created_at DESC

    LIMIT LEAST(GREATEST(COALESCE(p_limit, 100), 1), 500)
    OFFSET GREATEST(COALESCE(p_offset, 0), 0);
END;
$$;


ALTER FUNCTION "public"."admin_list_app_users"("p_search" "text", "p_status" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."allocate_customer_payment_atomic"("p_payment_id" "uuid", "p_allocations" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    v_payment public.customer_payments%rowtype;
    v_allocation jsonb;
    v_invoice_id uuid;
    v_allocate_amount numeric(18,2);
    v_requested_total numeric(18,2) := 0;
    v_existing_allocated numeric(18,2);
    v_payment_remaining numeric(18,2);
    v_invoice_remaining numeric(18,2);
    v_invoice_ids uuid[];
begin
    perform public.assert_invoice_permission('payments.allocate');

    if p_allocations is null
       or jsonb_typeof(p_allocations) <> 'array'
       or jsonb_array_length(p_allocations) = 0 then
        raise exception 'At least one Payment allocation is required.';
    end if;

    select *
    into v_payment
    from public.customer_payments
    where customer_payment_id = p_payment_id
      and is_deleted = false
    for update;

    if not found then
        raise exception 'Customer Payment not found.';
    end if;

    if v_payment.payment_status <> 'Recorded' then
        raise exception 'Only Recorded Customer Payments can be allocated.';
    end if;

    select array_agg(invoice_id order by invoice_id::text)
    into v_invoice_ids
    from (
        select distinct nullif(value ->> 'customer_invoice_id', '')::uuid as invoice_id
        from jsonb_array_elements(p_allocations)
    ) x;

    if v_invoice_ids is null or array_position(v_invoice_ids, null) is not null then
        raise exception 'Every allocation requires customer_invoice_id.';
    end if;

    perform 1
    from public.customer_invoices i
    where i.customer_invoice_id = any(v_invoice_ids)
    order by i.customer_invoice_id::text
    for update;

    if (
        select count(*)
        from public.customer_invoices i
        where i.customer_invoice_id = any(v_invoice_ids)
    ) <> cardinality(v_invoice_ids) then
        raise exception 'One or more target Invoices do not exist.';
    end if;

    if (
        select count(*)
        from jsonb_array_elements(p_allocations)
    ) <> cardinality(v_invoice_ids) then
        raise exception 'Duplicate Invoice allocations are not allowed in one request.';
    end if;

    v_existing_allocated := public._payment_allocated_amount(p_payment_id);
    v_payment_remaining := round(v_payment.amount - v_existing_allocated, 2);

    for v_allocation in
        select value from jsonb_array_elements(p_allocations)
    loop
        v_invoice_id := (v_allocation ->> 'customer_invoice_id')::uuid;
        v_allocate_amount := coalesce(
            nullif(v_allocation ->> 'allocated_amount', '')::numeric,
            0
        );

        if v_allocate_amount <= 0 then
            raise exception 'Allocation amount must be greater than zero.';
        end if;

        perform public._validate_payment_invoice(p_payment_id, v_invoice_id);

        if exists (
            select 1
            from public.customer_payment_allocations a
            where a.customer_payment_id = p_payment_id
              and a.customer_invoice_id = v_invoice_id
              and a.is_deleted = false
              and a.reversed_at is null
        ) then
            raise exception 'This Payment is already actively allocated to Invoice %.', v_invoice_id;
        end if;

        select round(
            i.total_amount
            - public._invoice_active_allocated_amount(i.customer_invoice_id),
            2
        )
        into v_invoice_remaining
        from public.customer_invoices i
        where i.customer_invoice_id = v_invoice_id;

        if v_allocate_amount > v_invoice_remaining then
            raise exception
                'Allocation amount (%) exceeds Invoice remaining balance (%).',
                v_allocate_amount,
                v_invoice_remaining;
        end if;

        v_requested_total := round(v_requested_total + v_allocate_amount, 2);
    end loop;

    if v_requested_total > v_payment_remaining then
        raise exception
            'Requested allocation total (%) exceeds Payment remaining amount (%).',
            v_requested_total,
            v_payment_remaining;
    end if;

    for v_allocation in
        select value from jsonb_array_elements(p_allocations)
    loop
        v_invoice_id := (v_allocation ->> 'customer_invoice_id')::uuid;
        v_allocate_amount := (v_allocation ->> 'allocated_amount')::numeric;

        insert into public.customer_payment_allocations (
            customer_payment_id,
            customer_invoice_id,
            allocated_amount,
            created_by,
            updated_by
        )
        values (
            p_payment_id,
            v_invoice_id,
            v_allocate_amount,
            auth.uid(),
            auth.uid()
        );

        perform public._recalculate_invoice_payment_state(v_invoice_id);
    end loop;

    return p_payment_id;
end;
$$;


ALTER FUNCTION "public"."allocate_customer_payment_atomic"("p_payment_id" "uuid", "p_allocations" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_app_user_atomic"("p_auth_user_id" "uuid", "p_role_code" "text", "p_admin_notes" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_actor_id uuid;
    v_app_user_id uuid;
    v_role_id uuid;
BEGIN
    v_actor_id := auth.uid();

    IF v_actor_id IS NULL THEN
        RAISE EXCEPTION 'Authentication required.';
    END IF;

    IF NOT (
        public.has_permission('users.manage_accounts')
        AND public.has_permission('users.assign_roles')
    )
    AND NOT public.can_manage_permissions()
    THEN
        RAISE EXCEPTION
            'Permission denied: users.manage_accounts and users.assign_roles are required.';
    END IF;

    IF p_auth_user_id IS NULL THEN
        RAISE EXCEPTION 'Target auth user is required.';
    END IF;

    IF p_role_code IS NULL
       OR btrim(p_role_code) = ''
    THEN
        RAISE EXCEPTION 'Role code is required.';
    END IF;

    SELECT au.app_user_id
    INTO v_app_user_id
    FROM public.app_users au
    WHERE au.auth_user_id = p_auth_user_id
    FOR UPDATE;

    IF v_app_user_id IS NULL THEN
        RAISE EXCEPTION
            'Application user was not found.';
    END IF;

    SELECT ar.role_id
    INTO v_role_id
    FROM public.app_roles ar
    WHERE ar.role_code = btrim(p_role_code)
      AND ar.is_active = true;

    IF v_role_id IS NULL THEN
        RAISE EXCEPTION
            'Active role "%" was not found.',
            btrim(p_role_code);
    END IF;

    /*
      End every currently active role assignment.
    */
    UPDATE public.app_user_roles
    SET
        is_active = false,
        ended_at = now(),
        ended_by = v_actor_id
    WHERE auth_user_id = p_auth_user_id
      AND is_active = true;

    /*
      Re-activate or create the selected role assignment.
    */
    INSERT INTO public.app_user_roles (
        auth_user_id,
        role_id,
        is_active,
        assigned_at,
        assigned_by,
        ended_at,
        ended_by,
        notes
    )
    VALUES (
        p_auth_user_id,
        v_role_id,
        true,
        now(),
        v_actor_id,
        NULL,
        NULL,
        NULLIF(btrim(p_admin_notes), '')
    )
    ON CONFLICT (auth_user_id, role_id)
    DO UPDATE SET
        is_active = true,
        assigned_at = now(),
        assigned_by = v_actor_id,
        ended_at = NULL,
        ended_by = NULL,
        notes = EXCLUDED.notes;

    UPDATE public.app_users
    SET
        account_status = 'Active',

        approved_at = now(),
        approved_by = v_actor_id,

        suspended_at = NULL,
        suspended_by = NULL,
        suspension_reason = NULL,

        rejected_at = NULL,
        rejected_by = NULL,
        rejection_reason = NULL,

        admin_notes = NULLIF(btrim(p_admin_notes), ''),
        updated_by = v_actor_id
    WHERE app_user_id = v_app_user_id;

    RETURN v_app_user_id;
END;
$$;


ALTER FUNCTION "public"."approve_app_user_atomic"("p_auth_user_id" "uuid", "p_role_code" "text", "p_admin_notes" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."approve_app_user_atomic"("p_auth_user_id" "uuid", "p_role_code" "text", "p_admin_notes" "text") IS 'Approves a REDS application user and atomically assigns one active role.';



CREATE OR REPLACE FUNCTION "public"."approve_invoice_atomic"("p_invoice_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    v_invoice public.customer_invoices%rowtype;
begin
    perform public.assert_invoice_permission('invoices.approve');

    select *
    into v_invoice
    from public.customer_invoices
    where customer_invoice_id = p_invoice_id
      and is_deleted = false
    for update;

    if not found then
        raise exception 'Invoice not found.';
    end if;

    if v_invoice.document_status <> 'Draft' then
        raise exception 'Only Draft Invoices can be approved.';
    end if;

    if not exists (
        select 1
        from public.customer_invoice_items
        where customer_invoice_id = p_invoice_id
          and is_deleted = false
    ) then
        raise exception 'Invoice requires at least one active line.';
    end if;

    update public.customer_invoices
    set
        document_status = 'Approved',
        approved_at = now(),
        approved_by = auth.uid(),
        updated_by = auth.uid()
    where customer_invoice_id = p_invoice_id;

    return p_invoice_id;
end;
$$;


ALTER FUNCTION "public"."approve_invoice_atomic"("p_invoice_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_stock_request_item"("p_stock_request_id" "uuid", "p_stock_request_item_id" "uuid", "p_approved_quantity" numeric) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
    v_request public.stock_requests%rowtype;
    v_request_item public.stock_request_items%rowtype;
begin
    if not public.is_admin_role() then
        raise exception
            'Only an Admin or Manager can approve stock requests.';
    end if;

    if p_stock_request_id is null then
        raise exception 'Stock request is required.';
    end if;

    if p_stock_request_item_id is null then
        raise exception 'Stock request item is required.';
    end if;

    if p_approved_quantity is null
       or p_approved_quantity < 0 then
        raise exception
            'Approved quantity must be zero or greater.';
    end if;

    select *
    into v_request
    from public.stock_requests
    where stock_request_id = p_stock_request_id
      and is_deleted = false
    for update;

    if not found then
        raise exception 'Stock request not found.';
    end if;

    if v_request.request_status <> 'Submitted' then
        raise exception
            'Only a Submitted stock request can be approved. Current status: %.',
            v_request.request_status;
    end if;

    select *
    into v_request_item
    from public.stock_request_items
    where stock_request_item_id = p_stock_request_item_id
      and stock_request_id = p_stock_request_id
      and is_deleted = false
    for update;

    if not found then
        raise exception 'Stock request item not found.';
    end if;

    if p_approved_quantity >
       v_request_item.requested_quantity then
        raise exception
            'Approved quantity cannot exceed requested quantity. Requested: %, approved: %.',
            v_request_item.requested_quantity,
            p_approved_quantity;
    end if;

    update public.stock_request_items
    set
        approved_quantity = p_approved_quantity,
        updated_at = now(),
        updated_by = auth.uid()
    where stock_request_item_id =
          p_stock_request_item_id;

    if exists (
        select 1
        from public.stock_request_items sri
        where sri.stock_request_id = p_stock_request_id
          and sri.is_deleted = false
          and sri.approved_quantity is null
    ) then
        raise exception
            'Every active request item must have an approved quantity.';
    end if;

    update public.stock_requests
    set
        request_status = 'Approved',
        updated_at = now(),
        updated_by = auth.uid()
    where stock_request_id =
          p_stock_request_id;
end;
$$;


ALTER FUNCTION "public"."approve_stock_request_item"("p_stock_request_id" "uuid", "p_stock_request_item_id" "uuid", "p_approved_quantity" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_tool_loan_atomic"("p_tool_loan_id" "uuid", "p_notes" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
    v_loan public.tool_loans%rowtype;
begin
    if not public.has_permission('tool_loans.approve') then
        raise exception 'Permission denied: tool_loans.approve.';
    end if;

    select *
    into v_loan
    from public.tool_loans
    where tool_loan_id = p_tool_loan_id
      and is_deleted = false
    for update;

    if not found then
        raise exception 'Tool Loan was not found.';
    end if;

    if v_loan.loan_status not in ('Submitted', 'UnderReview') then
        raise exception
            'Only Submitted or Under Review Tool Loans can be approved.';
    end if;

    update public.tool_loan_items
    set
        item_status = 'Approved',
        updated_at = now(),
        updated_by = auth.uid()
    where tool_loan_id = p_tool_loan_id
      and is_deleted = false;

    update public.tool_loans
    set
        loan_status = 'Approved',
        approved_at = now(),
        approved_by = auth.uid(),
        notes = coalesce(nullif(btrim(p_notes), ''), notes),
        updated_at = now(),
        updated_by = auth.uid()
    where tool_loan_id = p_tool_loan_id;

    return p_tool_loan_id;
end;
$$;


ALTER FUNCTION "public"."approve_tool_loan_atomic"("p_tool_loan_id" "uuid", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."archive_product_attributes_not_in_category"("p_product_id" "uuid", "p_new_category_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
    v_archived_count integer;
begin
    /*
      WebApp:
      - ตรวจสิทธิ์จาก JWT app_role ตามปกติ

      Supabase SQL Editor / migration:
      - อนุญาต database administration roles
        เพื่อให้ migration และ automated test ทำงานได้
    */
    if not (
        public.is_admin_role()
        or public.is_project_role()
        or current_user in (
            'postgres',
            'service_role',
            'supabase_admin'
        )
    ) then
        raise exception
            'You do not have permission to update product attributes.';
    end if;

    if not exists (
        select 1
        from public.products p
        where p.product_id = p_product_id
          and p.is_deleted = false
    ) then
        raise exception
            'The selected product does not exist or is deleted.';
    end if;

    if not exists (
        select 1
        from public.product_categories c
        where c.category_id = p_new_category_id
          and c.is_deleted = false
    ) then
        raise exception
            'The selected destination category does not exist or is deleted.';
    end if;

    update public.product_attribute_values value_row
       set
           is_deleted = true,
           deleted_at = now(),
           updated_at = now(),
           updated_by = auth.uid()
     where value_row.product_id = p_product_id
       and value_row.is_deleted = false
       and not exists (
           select 1
           from public.get_effective_product_category_attributes(
               p_new_category_id
           ) effective
           where effective.attribute_id =
                 value_row.attribute_id
       );

    get diagnostics v_archived_count = row_count;

    return v_archived_count;
end;
$$;


