CREATE OR REPLACE FUNCTION "public"."assert_product_required_attributes_complete"("p_product_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
    v_missing_labels text;
begin
    select string_agg(
        format('%s (%s)', missing.attribute_label, missing.section_name),
        ', '
        order by missing.section_name, missing.attribute_label
    )
    into v_missing_labels
    from public.get_missing_required_product_attributes(
        p_product_id
    ) missing;

    if v_missing_labels is not null then
        raise exception
            'Required product attributes are incomplete: %',
            v_missing_labels;
    end if;
end;
$$;


