CREATE OR REPLACE FUNCTION "public"."assign_generated_product_code"("p_product_id" "uuid", "p_category_variant_id" "uuid", "p_product_code_type_id" "uuid", "p_size_rule_id" "uuid", "p_colour_id" "uuid", "p_first_value" integer DEFAULT NULL::integer, "p_second_value" integer DEFAULT NULL::integer) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
    v_product public.products%rowtype;
    v_generated record;
begin
    if not (
        public.is_admin_role()
        or public.is_project_role()
        or current_user in (
            'postgres',
            'service_role',
            'supabase_admin'
        )
    ) then
        raise exception
            'You do not have permission to assign Product Codes.';
    end if;

    select *
    into v_product
    from public.products
    where product_id = p_product_id
      and is_deleted = false
    for update;

    if not found then
        raise exception 'Product does not exist.';
    end if;

    if v_product.product_code_generated_at is not null
       or v_product.product_code_category_variant_id is not null
       or v_product.product_code_variant_number is not null then
        raise exception
            'This Product already has a generated Product Code identity.';
    end if;

    select *
    into v_generated
    from public.generate_product_code(
        p_category_variant_id,
        p_product_code_type_id,
        p_size_rule_id,
        p_colour_id,
        p_first_value,
        p_second_value
    );

    if exists (
        select 1
        from public.products existing_product
        where upper(existing_product.product_code) =
              upper(v_generated.generated_product_code)
          and existing_product.product_id <> p_product_id
    ) then
        raise exception
            'Generated Product Code % already exists.',
            v_generated.generated_product_code;
    end if;

    update public.products
    set
        product_code =
            v_generated.generated_product_code,
        product_code_category_variant_id =
            p_category_variant_id,
        product_code_type_id =
            p_product_code_type_id,
        product_code_size_rule_id =
            p_size_rule_id,
        product_colour_id =
            p_colour_id,
        product_code_size_token =
            v_generated.size_token,
        product_code_variant_number =
            v_generated.variant_number,
        product_code_generated_at =
            v_generated.generated_at,
        product_code_generated_by =
            auth.uid()
    where product_id = p_product_id;

    return v_generated.generated_product_code;
end;
$$;


ALTER FUNCTION "public"."assign_generated_product_code"("p_product_id" "uuid", "p_category_variant_id" "uuid", "p_product_code_type_id" "uuid", "p_size_rule_id" "uuid", "p_colour_id" "uuid", "p_first_value" integer, "p_second_value" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assign_material_requirement_responsible"("p_material_requirement_id" "uuid", "p_responsible_auth_user_id" "uuid", "p_assignment_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_actor uuid;

    v_before public.material_requirements%ROWTYPE;
    v_after public.material_requirements%ROWTYPE;

    v_assignment_reason text;
    v_assignment_note text;
BEGIN
    -- -----------------------------------------------------------------
    -- Authentication and permission
    -- -----------------------------------------------------------------

    v_actor := auth.uid();

    IF v_actor IS NULL THEN
        RAISE EXCEPTION
            'Authentication is required.';
    END IF;

    IF NOT public.has_permission(
        'material_requirements.assign'
    ) THEN
        RAISE EXCEPTION
            'Permission denied: material_requirements.assign is required.';
    END IF;

    IF p_material_requirement_id IS NULL THEN
        RAISE EXCEPTION
            'Material Requirement ID is required.';
    END IF;


    -- -----------------------------------------------------------------
    -- Normalize reason
    -- -----------------------------------------------------------------

    v_assignment_reason :=
        NULLIF(
            btrim(p_assignment_reason),
            ''
        );


    -- -----------------------------------------------------------------
    -- Responsible user validation
    --
    -- NULL is allowed to unassign responsibility.
    -- -----------------------------------------------------------------

    IF p_responsible_auth_user_id IS NOT NULL
       AND NOT EXISTS (
           SELECT 1
           FROM auth.users user_row
           WHERE user_row.id =
                 p_responsible_auth_user_id
             AND user_row.deleted_at IS NULL
       ) THEN
        RAISE EXCEPTION
            'Selected Responsible User was not found or has been deleted.';
    END IF;


    -- -----------------------------------------------------------------
    -- Lock active Header
    -- -----------------------------------------------------------------

    SELECT header_row.*
    INTO v_before
    FROM public.material_requirements header_row
    WHERE header_row.material_requirement_id =
              p_material_requirement_id
      AND header_row.is_active = true
      AND header_row.is_deleted = false
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'Active Material Requirement was not found.';
    END IF;


    -- -----------------------------------------------------------------
    -- Workflow rule
    -- -----------------------------------------------------------------

    IF v_before.requirement_status IN (
        'Completed',
        'Cancelled'
    ) THEN
        RAISE EXCEPTION
            'Responsible User cannot be changed while the Material Requirement is %.',
            v_before.requirement_status;
    END IF;


    -- -----------------------------------------------------------------
    -- Reject no-op assignment
    -- -----------------------------------------------------------------

    IF v_before.responsible_auth_user_id
       IS NOT DISTINCT FROM
          p_responsible_auth_user_id THEN
        RAISE EXCEPTION
            'The selected Responsible User is already assigned.';
    END IF;


    -- -----------------------------------------------------------------
    -- Build optional audit note
    -- -----------------------------------------------------------------

    IF v_assignment_reason IS NOT NULL THEN
        v_assignment_note :=
            CASE
                WHEN p_responsible_auth_user_id IS NULL
                THEN
                    '[Responsible user removed] '
                    || v_assignment_reason
                ELSE
                    '[Responsible user assigned] '
                    || v_assignment_reason
            END;
    ELSE
        v_assignment_note := NULL;
    END IF;


    -- -----------------------------------------------------------------
    -- Update assignment
    -- -----------------------------------------------------------------

    UPDATE public.material_requirements
    SET
        responsible_auth_user_id =
            p_responsible_auth_user_id,

        notes =
            CASE
                WHEN v_assignment_note IS NULL
                THEN notes
                ELSE concat_ws(
                    E'\n',
                    NULLIF(btrim(notes), ''),
                    v_assignment_note
                )
            END,

        updated_by =
            v_actor
    WHERE material_requirement_id =
          p_material_requirement_id
    RETURNING *
    INTO v_after;


    RETURN jsonb_build_object(
        'material_requirement_id',
            v_after.material_requirement_id,

        'material_requirement_no',
            v_after.material_requirement_no,

        'requirement_status',
            v_after.requirement_status,

        'previous_responsible_auth_user_id',
            v_before.responsible_auth_user_id,

        'new_responsible_auth_user_id',
            v_after.responsible_auth_user_id,

        'assignment_reason',
            v_assignment_reason,

        'assigned_by',
            v_after.updated_by,

        'assigned_at',
            v_after.updated_at,

        'header',
            to_jsonb(v_after)
    );
END;
$$;


ALTER FUNCTION "public"."assign_material_requirement_responsible"("p_material_requirement_id" "uuid", "p_responsible_auth_user_id" "uuid", "p_assignment_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."assign_material_requirement_responsible"("p_material_requirement_id" "uuid", "p_responsible_auth_user_id" "uuid", "p_assignment_reason" "text") IS 'Atomically assigns, changes or removes the Responsible Auth User for an active Material Requirement that is not Completed or Cancelled.';



CREATE OR REPLACE FUNCTION "public"."assign_user_role_atomic"("p_auth_user_id" "uuid", "p_role_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    v_actor_id uuid;
    v_old_role_id uuid;
    v_old_role_code text;
    v_new_role_code text;
begin
    if auth.uid() is null then
        raise exception 'Authentication required.';
    end if;

    if not (
        public.has_permission('users.assign_roles')
        or public.can_manage_permissions()
    ) then
        raise exception
            'Permission denied: users.assign_roles';
    end if;

    v_actor_id := auth.uid();

    if p_auth_user_id is null
       or p_role_id is null
    then
        raise exception
            'Target user and role are required.';
    end if;

    if not exists (
        select 1
        from public.app_users au
        where au.auth_user_id = p_auth_user_id
          and au.account_status in (
              'Pending',
              'Active',
              'Suspended'
          )
        for update
    ) then
        raise exception
            'Eligible application user was not found.';
    end if;

    select
        ur.role_id,
        r.role_code
    into
        v_old_role_id,
        v_old_role_code
    from public.app_user_roles ur
    join public.app_roles r
      on r.role_id = ur.role_id
    where ur.auth_user_id = p_auth_user_id
      and ur.is_active = true
      and ur.ended_at is null
    order by ur.assigned_at desc
    limit 1
    for update of ur;

    select r.role_code
    into v_new_role_code
    from public.app_roles r
    where r.role_id = p_role_id
      and r.is_active = true;

    if v_new_role_code is null then
        raise exception
            'Active role was not found.';
    end if;

    if v_old_role_id = p_role_id then
        return p_auth_user_id;
    end if;

    if p_auth_user_id = v_actor_id
       and v_old_role_code = 'admin'
       and v_new_role_code <> 'admin'
       and public._active_permission_admin_count(
           p_auth_user_id
       ) < 1
    then
        raise exception
            'You cannot remove the final permission administrator.';
    end if;

    update public.app_user_roles
    set
        is_active = false,
        ended_at = now(),
        ended_by = v_actor_id,
        notes = coalesce(
            nullif(btrim(p_reason), ''),
            notes
        )
    where auth_user_id = p_auth_user_id
      and is_active = true
      and ended_at is null;

    insert into public.app_user_roles (
        auth_user_id,
        role_id,
        is_active,
        assigned_at,
        assigned_by,
        ended_at,
        ended_by,
        notes
    )
    values (
        p_auth_user_id,
        p_role_id,
        true,
        now(),
        v_actor_id,
        null,
        null,
        nullif(btrim(p_reason), '')
    )
    on conflict (auth_user_id, role_id)
    do update
    set
        is_active = true,
        assigned_at = now(),
        assigned_by = v_actor_id,
        ended_at = null,
        ended_by = null,
        notes = excluded.notes;

    insert into public.access_control_audit_log (
        target_auth_user_id,
        target_role_id,
        change_type,
        old_value,
        new_value,
        reason,
        changed_by
    )
    values (
        p_auth_user_id,
        p_role_id,
        case
            when v_old_role_id is null
                then 'Role Assigned'
            else 'Role Changed'
        end,
        jsonb_build_object(
            'role_id',
                v_old_role_id,
            'role_code',
                v_old_role_code
        ),
        jsonb_build_object(
            'role_id',
                p_role_id,
            'role_code',
                v_new_role_code
        ),
        nullif(btrim(p_reason), ''),
        v_actor_id
    );

    if public._active_permission_admin_count() < 1 then
        raise exception
            'At least one active permission administrator must remain.';
    end if;

    return p_auth_user_id;
end;
$$;


ALTER FUNCTION "public"."assign_user_role_atomic"("p_auth_user_id" "uuid", "p_role_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."audit_stock_issue_lifecycle"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
    v_event_code text;
    v_event_name text;
    v_event_severity text;
    v_event_key text;
begin
    if tg_op = 'INSERT' then
        v_event_code := 'stock_issue_created';
        v_event_name := 'Stock Issue Created';
        v_event_severity := 'Info';
        v_event_key :=
            'stock_issue:'
            || new.stock_issue_id::text
            || ':created';

        perform public.record_stock_issue_event(
            new.stock_issue_id,
            v_event_code,
            v_event_name,
            v_event_severity,
            v_event_key,
            null,
            new.issue_status,
            null,
            null,
            jsonb_build_object(
                'stock_issue_no', new.stock_issue_no,
                'priority', new.priority,
                'required_date', new.required_date,
                'recipient_name', new.recipient_name
            ),
            new.notes
        );

        return new;
    end if;

    if new.issue_status is not distinct from old.issue_status then
        return new;
    end if;

    case new.issue_status
        when 'Prepared' then
            v_event_code := 'stock_issue_prepared';
            v_event_name := 'Stock Issue Prepared';
            v_event_severity := 'Info';

        when 'Issued' then
            v_event_code := 'stock_issue_issued';
            v_event_name := 'Stock Issue Issued';
            v_event_severity := 'Info';

        when 'Dispatched' then
            v_event_code := 'stock_issue_dispatched';
            v_event_name := 'Stock Issue Dispatched';
            v_event_severity := 'Info';

        when 'Delivered' then
            v_event_code := 'stock_issue_delivered';
            v_event_name := 'Stock Issue Delivered';
            v_event_severity := 'Info';

        when 'PartiallyReceived' then
            v_event_code :=
                'stock_issue_partially_received';
            v_event_name :=
                'Stock Issue Partially Received';
            v_event_severity := 'Warning';

        when 'Received' then
            v_event_code := 'stock_issue_received';
            v_event_name := 'Stock Issue Received';
            v_event_severity := 'Info';

        when 'Cancelled' then
            v_event_code := 'stock_issue_cancelled';
            v_event_name := 'Stock Issue Cancelled';
            v_event_severity := 'Warning';

        else
            return new;
    end case;

    v_event_key :=
        'stock_issue:'
        || new.stock_issue_id::text
        || ':status:'
        || lower(replace(new.issue_status, ' ', '_'))
        || ':'
        || to_char(
            coalesce(new.updated_at, now()),
            'YYYYMMDDHH24MISSUS'
        );

    perform public.record_stock_issue_event(
        new.stock_issue_id,
        v_event_code,
        v_event_name,
        v_event_severity,
        v_event_key,
        old.issue_status,
        new.issue_status,
        null,
        null,
        jsonb_build_object(
            'stock_issue_no', new.stock_issue_no,
            'priority', new.priority,
            'required_date', new.required_date,
            'recipient_name', new.recipient_name,
            'dispatch_reference',
                new.dispatch_reference,
            'vehicle_reference',
                new.vehicle_reference,
            'cancellation_reason',
                new.cancellation_reason
        ),
        new.notes
    );

    return new;
end;
$$;


ALTER FUNCTION "public"."audit_stock_issue_lifecycle"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."audit_stock_issue_receipt_outcome"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
    v_event_code text;
    v_event_name text;
    v_event_severity text;
    v_event_key text;

    v_received numeric(18,6);
    v_damaged numeric(18,6);
    v_short numeric(18,6);
begin
    if old.receipt_status <> 'Draft'
       or new.receipt_status = 'Draft'
       or new.is_deleted = true then
        return new;
    end if;

    select
        coalesce(sum(received_base_quantity), 0),
        coalesce(sum(damaged_base_quantity), 0),
        coalesce(sum(short_base_quantity), 0)
    into
        v_received,
        v_damaged,
        v_short
    from public.stock_issue_receipt_lines
    where stock_issue_receipt_id =
          new.stock_issue_receipt_id
      and is_deleted = false;

    case new.receipt_status
        when 'Partial' then
            v_event_code :=
                'stock_issue_receipt_partial';
            v_event_name :=
                'Stock Issue Receipt Partial';
            v_event_severity := 'Warning';

        when 'Short' then
            v_event_code :=
                'stock_issue_receipt_short';
            v_event_name :=
                'Stock Issue Receipt Short';
            v_event_severity := 'Critical';

        when 'Damaged' then
            v_event_code :=
                'stock_issue_receipt_damaged';
            v_event_name :=
                'Stock Issue Receipt Damaged';
            v_event_severity := 'Critical';

        when 'Received' then
            v_event_code :=
                'stock_issue_receipt_received';
            v_event_name :=
                'Stock Issue Receipt Completed';
            v_event_severity := 'Info';

        else
            return new;
    end case;

    v_event_key :=
        'stock_issue_receipt:'
        || new.stock_issue_receipt_id::text
        || ':confirmed';

    perform public.record_stock_issue_event(
        new.stock_issue_id,
        v_event_code,
        v_event_name,
        v_event_severity,
        v_event_key,
        old.receipt_status,
        new.receipt_status,
        new.stock_issue_receipt_id,
        null,
        jsonb_build_object(
            'receipt_no', new.receipt_no,
            'receipt_status', new.receipt_status,
            'received_at', new.received_at,
            'received_by_auth_user_id',
                new.received_by_auth_user_id,
            'received_by_employee_id',
                new.received_by_employee_id,
            'received_by_name',
                new.received_by_name,
            'received_base_quantity',
                v_received,
            'damaged_base_quantity',
                v_damaged,
            'short_base_quantity',
                v_short
        ),
        new.receipt_notes
    );

    return new;
end;
$$;


ALTER FUNCTION "public"."audit_stock_issue_receipt_outcome"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."audit_stock_transfer_destination_posting"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
    v_event_key text;
    v_destination_location_id uuid;
    v_destination_lot_no text;
    v_source_lot_no text;
begin
    select
        destination_lot.stock_location_id,
        destination_lot.lot_no,
        source_lot.lot_no
    into
        v_destination_location_id,
        v_destination_lot_no,
        v_source_lot_no
    from public.stock_lots destination_lot
    join public.stock_lots source_lot
      on source_lot.stock_lot_id =
         new.source_stock_lot_id
    where destination_lot.stock_lot_id =
          new.destination_stock_lot_id;

    v_event_key :=
        'stock_transfer_posting:'
        || new.stock_transfer_receipt_posting_id::text;

    perform public.record_stock_issue_event(
        new.stock_issue_id,
        'stock_transfer_destination_posted',
        'Stock Transfer Destination Posted',
        'Info',
        v_event_key,
        null,
        null,
        new.stock_issue_receipt_id,
        new.stock_transfer_receipt_posting_id,
        jsonb_build_object(
            'stock_issue_receipt_line_id',
                new.stock_issue_receipt_line_id,
            'stock_issue_line_id',
                new.stock_issue_line_id,
            'source_stock_issue_allocation_id',
                new.source_stock_issue_allocation_id,
            'source_stock_lot_id',
                new.source_stock_lot_id,
            'source_lot_no',
                v_source_lot_no,
            'destination_stock_lot_id',
                new.destination_stock_lot_id,
            'destination_lot_no',
                v_destination_lot_no,
            'destination_stock_location_id',
                v_destination_location_id,
            'destination_stock_movement_id',
                new.destination_stock_movement_id,
            'posted_base_quantity',
                new.posted_base_quantity,
            'base_uom_code',
                new.base_uom_code,
            'unit_cost',
                new.unit_cost,
            'total_cost',
                new.total_cost
        ),
        new.notes
    );

    return new;
end;
$$;


