CREATE OR REPLACE FUNCTION "public"."build_product_code_size_token"("p_size_rule_id" "uuid", "p_first_value" integer DEFAULT NULL::integer, "p_second_value" integer DEFAULT NULL::integer) RETURNS "text"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
declare
    v_rule public.product_code_size_rules%rowtype;
    v_first_token text;
    v_second_token text;
begin
    select *
    into v_rule
    from public.product_code_size_rules
    where product_code_size_rule_id = p_size_rule_id
      and is_deleted = false
      and is_active = true
      and status = 'active';

    if not found then
        raise exception
            'The selected Product Code Size Rule is not active or does not exist.';
    end if;

    -- First segment: exactly 3 positions.
    if v_rule.first_value_mode = 'not_applicable' then
        v_first_token := 'NNN';
    elsif p_first_value is null then
        if v_rule.allow_first_unspecified then
            v_first_token := 'NNN';
        else
            raise exception '% is required.', v_rule.first_value_label;
        end if;
    else
        if p_first_value < 0 or p_first_value > 999 then
            raise exception
                '% must be between 0 and 999.',
                v_rule.first_value_label;
        end if;

        v_first_token := lpad(p_first_value::text, 3, '0');
    end if;

    -- Second segment: exactly 4 positions.
    if v_rule.second_value_mode = 'not_applicable' then
        v_second_token := 'NNNN';
    elsif p_second_value is null then
        if v_rule.allow_second_unspecified
           or v_rule.second_value_mode = 'random_or_numeric' then
            v_second_token := 'NNNN';
        else
            raise exception '% is required.', v_rule.second_value_label;
        end if;
    else
        if p_second_value < 0 or p_second_value > 9999 then
            raise exception
                '% must be between 0 and 9999.',
                v_rule.second_value_label;
        end if;

        v_second_token := lpad(p_second_value::text, 4, '0');
    end if;

    return v_first_token || 'X' || v_second_token;
end;
$$;


ALTER FUNCTION "public"."build_product_code_size_token"("p_size_rule_id" "uuid", "p_first_value" integer, "p_second_value" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."build_product_code_size_token"("p_size_rule_id" "uuid", "p_first_value" integer, "p_second_value" integer) IS 'Builds the fixed 8-character WWWXLLLL Product Code size token using the selected Size Rule.';



CREATE OR REPLACE FUNCTION "public"."calculate_material_requirement_line_quantities"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
    new.required_base_quantity_before_waste :=
        round(
            new.requirement_quantity
            * new.conversion_factor_to_base,
            6
        );

    new.waste_base_quantity :=
        round(
            new.required_base_quantity_before_waste
            * new.waste_percent
            / 100,
            6
        );

    new.required_base_quantity :=
        round(
            new.required_base_quantity_before_waste
            + new.waste_base_quantity,
            6
        );

    return new;
end;
$$;


ALTER FUNCTION "public"."calculate_material_requirement_line_quantities"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_delete_inventory_transaction_photo"("p_source_type" "text", "p_source_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
    if p_source_type = 'StockRequest' then
        return
            public.has_permission('stock_requests.delete_photos')
            and public.can_view_inventory_transaction_photo(
                p_source_type,
                p_source_id
            );

    elsif p_source_type in ('StockIssue','StockIssueReceipt') then
        return
            public.has_permission('stock_issues.delete_photos')
            and public.can_view_inventory_transaction_photo(
                p_source_type,
                p_source_id
            );

    elsif p_source_type in ('ToolLoan','ToolLoanReturn') then
        return
            public.has_permission('tool_loans.delete_photos')
            and public.can_view_inventory_transaction_photo(
                p_source_type,
                p_source_id
            );
    end if;

    return false;
end;
$$;


ALTER FUNCTION "public"."can_delete_inventory_transaction_photo"("p_source_type" "text", "p_source_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_manage_permissions"() RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    v_has_permission_manager boolean;
begin
    if public.has_permission('permissions.manage') then
        return true;
    end if;

    select exists (
        select 1
        from public.app_user_roles ur
        where ur.is_active = true
          and public.user_has_permission(
              ur.auth_user_id,
              'permissions.manage'
          )
    )
    into v_has_permission_manager;

    if v_has_permission_manager then
        return false;
    end if;

    return public.is_strict_admin_role();
end;
$$;


ALTER FUNCTION "public"."can_manage_permissions"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_manage_products_strict"() RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
    select
        public.is_strict_admin_role()
        or coalesce(auth.role(), '') = 'service_role';
$$;


