CREATE OR REPLACE FUNCTION "public"."can_view_inventory_transaction_photo"("p_source_type" "text", "p_source_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
    if p_source_type = 'StockRequest' then
        return
            public.has_permission('stock_requests.view')
            or (
                public.has_permission('stock_requests.view_own')
                and exists (
                    select 1
                    from public.stock_requests sr
                    where sr.stock_request_id = p_source_id
                      and sr.is_deleted = false
                      and (
                          sr.requester_auth_user_id = auth.uid()
                          or sr.requested_by = auth.uid()
                      )
                )
            );

    elsif p_source_type in ('StockIssue','StockIssueReceipt') then
        return public.has_permission('stock_issues.view');

    elsif p_source_type in ('ToolLoan','ToolLoanReturn') then
        return
            public.has_permission('tool_loans.view')
            or (
                public.has_permission('tool_loans.view_own')
                and exists (
                    select 1
                    from public.tool_loans tl
                    where tl.tool_loan_id =
                        case
                            when p_source_type = 'ToolLoan'
                                then p_source_id
                            else (
                                select tr.tool_loan_id
                                from public.tool_loan_returns tr
                                where tr.tool_loan_return_id = p_source_id
                                  and tr.is_deleted = false
                            )
                        end
                      and tl.is_deleted = false
                      and tl.borrower_auth_user_id = auth.uid()
                )
            );
    end if;

    return false;
end;
$$;


ALTER FUNCTION "public"."can_view_inventory_transaction_photo"("p_source_type" "text", "p_source_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_invoice_atomic"("p_invoice_id" "uuid", "p_reason" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    v_invoice public.customer_invoices%rowtype;
begin
    perform public.assert_invoice_permission('invoices.cancel');

    if nullif(btrim(p_reason), '') is null then
        raise exception 'Cancellation reason is required.';
    end if;

    select *
    into v_invoice
    from public.customer_invoices
    where customer_invoice_id = p_invoice_id
      and is_deleted = false
    for update;

    if not found then
        raise exception 'Invoice not found.';
    end if;

    if v_invoice.document_status not in ('Draft', 'Approved') then
        raise exception 'Only Draft or Approved Invoices can be cancelled.';
    end if;

    update public.customer_invoices
    set
        document_status = 'Cancelled',
        cancelled_at = now(),
        cancelled_by = auth.uid(),
        cancellation_reason = btrim(p_reason),
        updated_by = auth.uid()
    where customer_invoice_id = p_invoice_id;

    return p_invoice_id;
end;
$$;


ALTER FUNCTION "public"."cancel_invoice_atomic"("p_invoice_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_purchase_order_atomic"("p_purchase_order_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
    v_auth_user_id uuid := auth.uid();
    v_po public.purchase_orders%rowtype;
begin
    if v_auth_user_id is null then
        raise exception 'Authentication is required.';
    end if;

    if not public.has_permission('purchase_orders.cancel') then
        raise exception 'You do not have permission to cancel purchase orders.';
    end if;

    if nullif(btrim(p_reason), '') is null then
        raise exception 'Cancellation reason is required.';
    end if;

    select *
    into v_po
    from public.purchase_orders
    where purchase_order_id = p_purchase_order_id
      and is_deleted = false
    for update;

    if not found then
        raise exception 'Purchase Order was not found.';
    end if;

    if v_po.order_status not in ('Draft', 'Submitted', 'Confirmed') then
        raise exception 'Purchase Order status % cannot be cancelled.', v_po.order_status;
    end if;

    if exists (
        select 1
        from public.supplier_deliveries delivery_row
        where delivery_row.purchase_order_id = p_purchase_order_id
          and delivery_row.is_deleted = false
          and delivery_row.delivery_status <> 'Cancelled'
    ) then
        raise exception 'Purchase Order with an active Supplier Delivery cannot be cancelled.';
    end if;

    update public.material_requirement_procurement_links link_row
    set
        link_status = 'Cancelled',
        is_active = false,
        updated_at = now(),
        updated_by = v_auth_user_id
    where link_row.purchase_order_line_id in (
        select purchase_order_line_id
        from public.purchase_order_lines
        where purchase_order_id = p_purchase_order_id
          and is_deleted = false
    )
      and link_row.is_deleted = false
      and link_row.link_status = 'Active';

    update public.purchase_orders
    set
        order_status = 'Cancelled',
        cancelled_at = now(),
        cancelled_by = v_auth_user_id,
        cancellation_reason = btrim(p_reason),
        updated_at = now(),
        updated_by = v_auth_user_id
    where purchase_order_id = p_purchase_order_id;

    return jsonb_build_object(
        'purchase_order_id', p_purchase_order_id,
        'purchase_order_no', v_po.purchase_order_no,
        'order_status', 'Cancelled'
    );
end;
$$;


ALTER FUNCTION "public"."cancel_purchase_order_atomic"("p_purchase_order_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_quotation_atomic"("p_quotation_id" "uuid", "p_cancellation_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    v_user_id uuid;
    v_cancelled_at timestamptz;
    v_reason text;

    v_quotation_no text;
    v_quotation_status text;

    v_current_revision_id uuid;
    v_current_revision_no integer;
    v_current_revision_status text;

    v_accepted_revision_id uuid;
    v_accepted_at timestamptz;
    v_accepted_by uuid;

    v_revision_cancelled boolean := false;
begin
    -- ========================================================================
    -- 1. AUTHENTICATION AND PERMISSION
    -- ========================================================================

    v_user_id := auth.uid();

    if v_user_id is null then
        raise exception
            'Authentication is required.';
    end if;

    if not public.has_permission(
        'quotations.cancel'
    ) then
        raise exception
            'Permission denied: quotations.cancel is required.';
    end if;


    -- ========================================================================
    -- 2. INPUT VALIDATION
    -- ========================================================================

    if p_quotation_id is null then
        raise exception
            'Quotation ID is required.';
    end if;

    v_reason :=
        nullif(
            btrim(p_cancellation_reason),
            ''
        );

    if v_reason is null then
        raise exception
            'Cancellation reason is required.';
    end if;

    v_cancelled_at := now();


    -- ========================================================================
    -- 3. LOCK QUOTATION
    -- ========================================================================

    select
        q.quotation_no,
        q.quotation_status,
        q.current_revision_id,
        q.accepted_revision_id,
        q.accepted_at,
        q.accepted_by

    into
        v_quotation_no,
        v_quotation_status,
        v_current_revision_id,
        v_accepted_revision_id,
        v_accepted_at,
        v_accepted_by

    from public.quotations q

    where q.quotation_id =
          p_quotation_id
      and q.is_active = true
      and q.is_deleted = false

    for update;

    if not found then
        raise exception
            'Quotation was not found, is inactive, or is archived.';
    end if;


    -- ========================================================================
    -- 4. VALIDATE QUOTATION WORKFLOW
    -- ========================================================================

    if v_quotation_status = 'Accepted'
       or v_accepted_revision_id is not null
       or v_accepted_at is not null
       or v_accepted_by is not null then
        raise exception
            'Accepted quotation cannot be cancelled. Use a Variation or the appropriate contract workflow.';
    end if;

    if v_quotation_status not in (
        'Draft',
        'Sent',
        'Revised'
    ) then
        raise exception
            'Only a Draft, Sent, or Revised quotation can be cancelled. Current status: %.',
            v_quotation_status;
    end if;

    if exists (
        select 1
        from public.material_requirements mr
        where mr.quotation_id =
              p_quotation_id
          and mr.is_deleted = false
    ) then
        raise exception
            'Quotation cannot be cancelled because an active Material Requirement already references it.';
    end if;


    -- ========================================================================
    -- 5. LOCK AND VALIDATE CURRENT REVISION, IF PRESENT
    -- ========================================================================

    if v_current_revision_id is not null then
        select
            qr.revision_no,
            qr.revision_status

        into
            v_current_revision_no,
            v_current_revision_status

        from public.quotation_revisions qr

        where qr.revision_id =
              v_current_revision_id
          and qr.quotation_id =
              p_quotation_id
          and qr.is_active = true
          and qr.is_deleted = false

        for update;

        if not found then
            raise exception
                'Current quotation revision was not found, is inactive, archived, or does not belong to the quotation.';
        end if;

        if v_current_revision_status = 'Accepted' then
            raise exception
                'Accepted quotation revision cannot be cancelled.';
        end if;

        if v_current_revision_status not in (
            'Draft',
            'Sent'
        ) then
            raise exception
                'Current revision cannot be cancelled from status %. Expected Draft or Sent.',
                v_current_revision_status;
        end if;

        if exists (
            select 1
            from public.material_requirements mr
            where mr.accepted_revision_id =
                  v_current_revision_id
              and mr.is_deleted = false
        ) then
            raise exception
                'Current revision cannot be cancelled because an active Material Requirement references it.';
        end if;
    end if;


    -- ========================================================================
    -- 6. CANCEL CURRENT REVISION, IF PRESENT
    -- ========================================================================

    if v_current_revision_id is not null then
        update public.quotation_revisions
        set
            revision_status =
                'Cancelled',

            cancelled_at =
                v_cancelled_at,

            cancelled_by =
                v_user_id,

            cancellation_reason =
                v_reason,

            rejected_at =
                null,

            rejected_by =
                null,

            rejection_reason =
                null,

            updated_by =
                v_user_id

        where revision_id =
              v_current_revision_id
          and quotation_id =
              p_quotation_id
          and revision_status in (
              'Draft',
              'Sent'
          )
          and is_active = true
          and is_deleted = false;

        if not found then
            raise exception
                'Current quotation revision could not be cancelled because its workflow state changed.';
        end if;

        v_revision_cancelled := true;
    end if;


    -- ========================================================================
    -- 7. CANCEL PARENT QUOTATION
    -- ========================================================================

    update public.quotations
    set
        quotation_status =
            'Cancelled',

        current_revision_id =
            null,

        cancelled_at =
            v_cancelled_at,

        cancelled_by =
            v_user_id,

        cancellation_reason =
            v_reason,

        rejected_at =
            null,

        rejected_by =
            null,

        rejection_reason =
            null,

        updated_by =
            v_user_id

    where quotation_id =
          p_quotation_id
      and quotation_status in (
          'Draft',
          'Sent',
          'Revised'
      )
      and accepted_revision_id is null
      and accepted_at is null
      and accepted_by is null
      and is_active = true
      and is_deleted = false;

    if not found then
        raise exception
            'Quotation could not be cancelled because its workflow state changed.';
    end if;


    -- ========================================================================
    -- 8. FINAL CONSISTENCY CHECK
    -- ========================================================================

    if exists (
        select 1
        from public.quotations q
        where q.quotation_id =
              p_quotation_id
          and (
              q.quotation_status <>
                  'Cancelled'
              or q.current_revision_id is not null
              or q.cancelled_at is null
              or q.cancelled_by is distinct from
                 v_user_id
              or nullif(
                    btrim(q.cancellation_reason),
                    ''
                 ) is null
          )
    ) then
        raise exception
            'Quotation cancellation consistency check failed.';
    end if;


    -- ========================================================================
    -- 9. RETURN RESULT
    -- ========================================================================

    return jsonb_build_object(
        'quotation_id',
            p_quotation_id,

        'quotation_no',
            v_quotation_no,

        'previous_quotation_status',
            v_quotation_status,

        'quotation_status',
            'Cancelled',

        'cancelled_at',
            v_cancelled_at,

        'cancelled_by',
            v_user_id,

        'cancellation_reason',
            v_reason,

        'current_revision_id',
            null,

        'revision_cancelled',
            v_revision_cancelled,

        'cancelled_revision_id',
            case
                when v_revision_cancelled
                    then v_current_revision_id
                else null
            end,

        'cancelled_revision_no',
            case
                when v_revision_cancelled
                    then v_current_revision_no
                else null
            end
    );
end;
$$;


ALTER FUNCTION "public"."cancel_quotation_atomic"("p_quotation_id" "uuid", "p_cancellation_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_quotation_revision_atomic"("p_revision_id" "uuid", "p_cancellation_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    v_user_id uuid;
    v_cancelled_at timestamptz;
    v_reason text;

    v_quotation_id uuid;
    v_revision_no integer;
    v_revision_status text;

    v_quotation_no text;
    v_quotation_status text;
    v_current_revision_id uuid;

    v_accepted_revision_id uuid;
    v_accepted_at timestamptz;
    v_accepted_by uuid;
begin
    -- ========================================================================
    -- 1. AUTHENTICATION AND PERMISSION
    -- ========================================================================

    v_user_id := auth.uid();

    if v_user_id is null then
        raise exception
            'Authentication is required.';
    end if;

    if not public.has_permission(
        'quotations.cancel'
    ) then
        raise exception
            'Permission denied: quotations.cancel is required.';
    end if;


    -- ========================================================================
    -- 2. INPUT VALIDATION
    -- ========================================================================

    if p_revision_id is null then
        raise exception
            'Quotation Revision ID is required.';
    end if;

    v_reason :=
        nullif(
            btrim(p_cancellation_reason),
            ''
        );

    if v_reason is null then
        raise exception
            'Cancellation reason is required.';
    end if;

    v_cancelled_at := now();


    -- ========================================================================
    -- 3. LOCK REVISION
    -- ========================================================================

    select
        qr.quotation_id,
        qr.revision_no,
        qr.revision_status

    into
        v_quotation_id,
        v_revision_no,
        v_revision_status

    from public.quotation_revisions qr

    where qr.revision_id =
          p_revision_id
      and qr.is_active = true
      and qr.is_deleted = false

    for update;

    if not found then
        raise exception
            'Quotation revision was not found, is inactive, or is archived.';
    end if;


    -- ========================================================================
    -- 4. LOCK PARENT QUOTATION
    -- ========================================================================

    select
        q.quotation_no,
        q.quotation_status,
        q.current_revision_id,
        q.accepted_revision_id,
        q.accepted_at,
        q.accepted_by

    into
        v_quotation_no,
        v_quotation_status,
        v_current_revision_id,
        v_accepted_revision_id,
        v_accepted_at,
        v_accepted_by

    from public.quotations q

    where q.quotation_id =
          v_quotation_id
      and q.is_active = true
      and q.is_deleted = false

    for update;

    if not found then
        raise exception
            'Parent quotation was not found, is inactive, or is archived.';
    end if;


    -- ========================================================================
    -- 5. VALIDATE WORKFLOW
    -- ========================================================================

    if v_revision_status = 'Accepted'
       or v_quotation_status = 'Accepted'
       or v_accepted_revision_id is not null
       or v_accepted_at is not null
       or v_accepted_by is not null then
        raise exception
            'Accepted quotation revision cannot be cancelled.';
    end if;

    if v_revision_status not in (
        'Draft',
        'Sent'
    ) then
        raise exception
            'Only a Draft or Sent quotation revision can be cancelled. Current status: %.',
            v_revision_status;
    end if;

    if v_quotation_status not in (
        'Sent',
        'Revised'
    ) then
        raise exception
            'Parent quotation must be Sent or Revised before its current revision can be cancelled. Current status: %.',
            v_quotation_status;
    end if;

    if v_current_revision_id is distinct from
       p_revision_id then
        raise exception
            'Only the current quotation revision can be cancelled.';
    end if;

    if v_revision_status = 'Draft'
       and v_quotation_status <> 'Sent' then
        raise exception
            'A Draft current revision requires the parent quotation to remain Sent.';
    end if;

    if v_revision_status = 'Sent'
       and v_quotation_status <> 'Revised' then
        raise exception
            'A Sent current revision requires the parent quotation to have Revised status.';
    end if;

    if exists (
        select 1
        from public.material_requirements mr
        where (
                mr.accepted_revision_id =
                    p_revision_id
                or mr.quotation_id =
                    v_quotation_id
              )
          and mr.is_deleted = false
    ) then
        raise exception
            'Quotation revision cannot be cancelled because an active Material Requirement references its commercial source.';
    end if;


    -- ========================================================================
    -- 6. CANCEL REVISION
    -- ========================================================================

    update public.quotation_revisions
    set
        revision_status =
            'Cancelled',

        cancelled_at =
            v_cancelled_at,

        cancelled_by =
            v_user_id,

        cancellation_reason =
            v_reason,

        rejected_at =
            null,

        rejected_by =
            null,

        rejection_reason =
            null,

        updated_by =
            v_user_id

    where revision_id =
          p_revision_id
      and revision_status in (
          'Draft',
          'Sent'
      )
      and is_active = true
      and is_deleted = false;

    if not found then
        raise exception
            'Quotation revision could not be cancelled because its workflow state changed.';
    end if;


    -- ========================================================================
    -- 7. RESTORE PARENT QUOTATION
    -- ========================================================================

    update public.quotations
    set
        quotation_status =
            'Sent',

        current_revision_id =
            null,

        rejected_at =
            null,

        rejected_by =
            null,

        rejection_reason =
            null,

        cancelled_at =
            null,

        cancelled_by =
            null,

        cancellation_reason =
            null,

        updated_by =
            v_user_id

    where quotation_id =
          v_quotation_id
      and quotation_status in (
          'Sent',
          'Revised'
      )
      and current_revision_id =
          p_revision_id
      and accepted_revision_id is null
      and accepted_at is null
      and accepted_by is null
      and is_active = true
      and is_deleted = false;

    if not found then
        raise exception
            'Parent quotation could not be restored because its workflow state changed.';
    end if;


    -- ========================================================================
    -- 8. FINAL CONSISTENCY CHECK
    -- ========================================================================

    if not exists (
        select 1
        from public.quotation_revisions qr
        where qr.revision_id =
              p_revision_id
          and qr.revision_status =
              'Cancelled'
          and qr.cancelled_at =
              v_cancelled_at
          and qr.cancelled_by =
              v_user_id
          and qr.cancellation_reason =
              v_reason
          and qr.is_active = true
          and qr.is_deleted = false
    ) then
        raise exception
            'Revision cancellation consistency check failed.';
    end if;

    if not exists (
        select 1
        from public.quotations q
        where q.quotation_id =
              v_quotation_id
          and q.quotation_status =
              'Sent'
          and q.current_revision_id is null
          and q.accepted_revision_id is null
          and q.is_active = true
          and q.is_deleted = false
    ) then
        raise exception
            'Parent quotation restoration consistency check failed.';
    end if;


    -- ========================================================================
    -- 9. RETURN RESULT
    -- ========================================================================

    return jsonb_build_object(
        'quotation_id',
            v_quotation_id,

        'quotation_no',
            v_quotation_no,

        'previous_quotation_status',
            v_quotation_status,

        'quotation_status',
            'Sent',

        'revision_id',
            p_revision_id,

        'revision_no',
            v_revision_no,

        'previous_revision_status',
            v_revision_status,

        'revision_status',
            'Cancelled',

        'cancelled_at',
            v_cancelled_at,

        'cancelled_by',
            v_user_id,

        'cancellation_reason',
            v_reason,

        'current_revision_id',
            null
    );
end;
$$;


ALTER FUNCTION "public"."cancel_quotation_revision_atomic"("p_revision_id" "uuid", "p_cancellation_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_stock_issue_atomic"("p_stock_issue_id" "uuid", "p_reason" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
    v_issue public.stock_issues%rowtype;
begin
    if not public.has_permission('stock_issues.cancel') then
        raise exception 'Permission denied: stock_issues.cancel.';
    end if;

    if nullif(btrim(p_reason), '') is null then
        raise exception 'Cancellation reason is required.';
    end if;

    select *
    into v_issue
    from public.stock_issues
    where stock_issue_id = p_stock_issue_id
      and is_deleted = false
    for update;

    if not found then
        raise exception 'Stock Issue was not found.';
    end if;

    if v_issue.issue_status not in ('Draft', 'Prepared') then
        raise exception
            'Only Draft or Prepared Stock Issues can be cancelled before stock posting.';
    end if;

    if exists (
        select 1
        from public.stock_issue_allocations a
        join public.stock_issue_lines l
          on l.stock_issue_line_id = a.stock_issue_line_id
        where l.stock_issue_id = p_stock_issue_id
          and a.is_deleted = false
          and a.stock_movement_id is not null
    ) then
        raise exception
            'Stock Issue cannot be cancelled because a Stock Movement has already been posted.';
    end if;

    update public.stock_issue_allocations
    set
        allocation_status = 'Cancelled',
        updated_at = now(),
        updated_by = auth.uid()
    where stock_issue_line_id in (
        select stock_issue_line_id
        from public.stock_issue_lines
        where stock_issue_id = p_stock_issue_id
          and is_deleted = false
    )
      and is_deleted = false;

    update public.stock_issue_lines
    set
        line_status = 'Cancelled',
        updated_at = now(),
        updated_by = auth.uid()
    where stock_issue_id = p_stock_issue_id
      and is_deleted = false;

    update public.stock_issues
    set
        issue_status = 'Cancelled',
        cancellation_reason = btrim(p_reason),
        cancelled_at = now(),
        cancelled_by = auth.uid(),
        updated_at = now(),
        updated_by = auth.uid()
    where stock_issue_id = p_stock_issue_id;

    return p_stock_issue_id;
end;
$$;


ALTER FUNCTION "public"."cancel_stock_issue_atomic"("p_stock_issue_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_stock_issue_receipt_draft"("p_stock_issue_receipt_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
    v_receipt public.stock_issue_receipts%rowtype;
begin
    if not public.has_permission('stock_issues.confirm_receipt') then
        raise exception
            'Permission denied: stock_issues.confirm_receipt.';
    end if;

    select *
    into v_receipt
    from public.stock_issue_receipts
    where stock_issue_receipt_id = p_stock_issue_receipt_id
      and is_deleted = false
    for update;

    if not found then
        raise exception 'Stock Issue receipt was not found.';
    end if;

    if v_receipt.receipt_status <> 'Draft' then
        raise exception
            'Only a Draft receipt can be cancelled.';
    end if;

    if exists (
        select 1
        from public.stock_issue_receipt_lines
        where stock_issue_receipt_id = p_stock_issue_receipt_id
          and is_deleted = false
    ) then
        raise exception
            'Draft receipt cannot be cancelled after receipt lines have been recorded.';
    end if;

    update public.inventory_transaction_photos
    set
        is_active = false,
        is_deleted = true,
        deleted_at = now(),
        updated_at = now(),
        updated_by = auth.uid()
    where source_type = 'StockIssueReceipt'
      and source_id = p_stock_issue_receipt_id
      and is_deleted = false;

    update public.stock_issue_receipts
    set
        is_active = false,
        is_deleted = true,
        deleted_at = now(),
        updated_at = now(),
        updated_by = auth.uid()
    where stock_issue_receipt_id = p_stock_issue_receipt_id;

    return p_stock_issue_receipt_id;
end;
$$;


ALTER FUNCTION "public"."cancel_stock_issue_receipt_draft"("p_stock_issue_receipt_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_tool_loan_atomic"("p_tool_loan_id" "uuid", "p_reason" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
    v_loan public.tool_loans%rowtype;
begin
    if not public.has_permission('tool_loans.cancel') then
        raise exception 'Permission denied: tool_loans.cancel.';
    end if;

    if nullif(btrim(p_reason), '') is null then
        raise exception 'Cancellation reason is required.';
    end if;

    select *
    into v_loan
    from public.tool_loans
    where tool_loan_id = p_tool_loan_id
      and is_deleted = false
    for update;

    if not found then
        raise exception 'Tool Loan was not found.';
    end if;

    if v_loan.loan_status not in (
        'Draft',
        'Submitted',
        'UnderReview',
        'Approved',
        'Prepared'
    ) then
        raise exception
            'Tool Loan cannot be cancelled after it has been issued.';
    end if;

    update public.tool_loan_items
    set
        item_status = 'Cancelled',
        updated_at = now(),
        updated_by = auth.uid()
    where tool_loan_id = p_tool_loan_id
      and is_deleted = false;

    update public.tool_loans
    set
        loan_status = 'Cancelled',
        cancellation_reason = btrim(p_reason),
        cancelled_at = now(),
        cancelled_by = auth.uid(),
        updated_at = now(),
        updated_by = auth.uid()
    where tool_loan_id = p_tool_loan_id;

    return p_tool_loan_id;
end;
$$;


ALTER FUNCTION "public"."cancel_tool_loan_atomic"("p_tool_loan_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_variation_atomic"("p_variation_id" "uuid", "p_cancellation_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    v_user_id uuid := auth.uid();
    v_variation public.variations%rowtype;
    v_reason text;
begin
    if v_user_id is null then
        raise exception 'Authentication is required.';
    end if;

    if not public.has_permission('variations.cancel') then
        raise exception 'Permission denied: variations.cancel is required.';
    end if;

    v_reason := nullif(btrim(p_cancellation_reason), '');
    if v_reason is null then
        raise exception 'Cancellation reason is required.';
    end if;

    select *
    into v_variation
    from public.variations
    where variation_id = p_variation_id
      and is_active = true
      and is_deleted = false
    for update;

    if not found then
        raise exception 'Variation was not found, is inactive, or is archived.';
    end if;

    if v_variation.variation_status not in ('Draft', 'Sent') then
        raise exception 'Only a Draft or Sent Variation can be cancelled. Current status: %.', v_variation.variation_status;
    end if;

    if exists (
        select 1 from public.material_requirements mr
        where mr.source_variation_id = p_variation_id
          and mr.is_deleted = false
    ) then
        raise exception 'Variation cannot be cancelled because an active Material Requirement references it.';
    end if;

    update public.variations
    set
        variation_status = 'Cancelled',
        cancelled_at = now(),
        cancelled_by = v_user_id,
        cancellation_reason = v_reason,
        rejected_at = null,
        rejected_by = null,
        rejection_reason = null,
        updated_by = v_user_id
    where variation_id = p_variation_id
      and variation_status in ('Draft', 'Sent');

    return jsonb_build_object(
        'variation_id', p_variation_id,
        'variation_no', v_variation.variation_no,
        'variation_status', 'Cancelled',
        'cancellation_reason', v_reason
    );
end;
$$;


ALTER FUNCTION "public"."cancel_variation_atomic"("p_variation_id" "uuid", "p_cancellation_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."confirm_purchase_order_atomic"("p_purchase_order_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
    v_auth_user_id uuid := auth.uid();
    v_po public.purchase_orders%rowtype;
begin
    if v_auth_user_id is null then
        raise exception 'Authentication is required.';
    end if;

    if not public.has_permission('purchase_orders.confirm') then
        raise exception 'You do not have permission to confirm purchase orders.';
    end if;

    select *
    into v_po
    from public.purchase_orders
    where purchase_order_id = p_purchase_order_id
      and is_deleted = false
    for update;

    if not found then
        raise exception 'Purchase Order was not found.';
    end if;

    if v_po.order_status <> 'Submitted' then
        raise exception 'Only a Submitted purchase order can be confirmed.';
    end if;

    update public.purchase_orders
    set
        order_status = 'Confirmed',
        confirmed_at = now(),
        confirmed_by = v_auth_user_id,
        updated_at = now(),
        updated_by = v_auth_user_id
    where purchase_order_id = p_purchase_order_id;

    return jsonb_build_object(
        'purchase_order_id', p_purchase_order_id,
        'purchase_order_no', v_po.purchase_order_no,
        'order_status', 'Confirmed'
    );
end;
$$;


ALTER FUNCTION "public"."confirm_purchase_order_atomic"("p_purchase_order_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."confirm_stock_issue_receipt_atomic"("p_stock_issue_receipt_id" "uuid", "p_lines" "jsonb", "p_received_at" timestamp with time zone DEFAULT "now"(), "p_receipt_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
    v_receipt public.stock_issue_receipts%rowtype;
    v_issue public.stock_issues%rowtype;
    v_line jsonb;
    v_issue_line public.stock_issue_lines%rowtype;

    v_receipt_line_no integer := 0;
    v_received numeric(18,6);
    v_damaged numeric(18,6);
    v_short numeric(18,6);
    v_session_total numeric(18,6);
    v_prior_recorded numeric(18,6);
    v_outstanding numeric(18,6);

    v_any_damage boolean := false;
    v_any_short boolean := false;
    v_any_outstanding boolean;
    v_receipt_status text;
    v_issue_status text;
    v_photo_count integer;
begin
    if not public.has_permission('stock_issues.confirm_receipt') then
        raise exception
            'Permission denied: stock_issues.confirm_receipt.';
    end if;

    if p_lines is null
       or jsonb_typeof(p_lines) <> 'array'
       or jsonb_array_length(p_lines) = 0 then
        raise exception
            'At least one receipt line is required.';
    end if;

    select *
    into v_receipt
    from public.stock_issue_receipts
    where stock_issue_receipt_id = p_stock_issue_receipt_id
      and is_deleted = false
    for update;

    if not found then
        raise exception 'Stock Issue receipt was not found.';
    end if;

    if v_receipt.receipt_status <> 'Draft' then
        raise exception
            'Only a Draft Stock Issue receipt can be confirmed.';
    end if;

    select *
    into v_issue
    from public.stock_issues
    where stock_issue_id = v_receipt.stock_issue_id
      and is_deleted = false
    for update;

    if not found then
        raise exception 'Stock Issue was not found.';
    end if;

    if v_issue.issue_status not in (
        'Delivered',
        'PartiallyReceived'
    ) then
        raise exception
            'Stock Issue status % does not allow receipt confirmation.',
            v_issue.issue_status;
    end if;

    select count(*)
    into v_photo_count
    from public.inventory_transaction_photos
    where source_type = 'StockIssueReceipt'
      and source_id = p_stock_issue_receipt_id
      and is_deleted = false;

    if v_photo_count < 1 then
        raise exception
            'At least one receipt photo is required before confirmation.';
    end if;

    for v_line in
        select value
        from jsonb_array_elements(p_lines)
    loop
        v_receipt_line_no := v_receipt_line_no + 1;

        select *
        into v_issue_line
        from public.stock_issue_lines
        where stock_issue_line_id =
              nullif(v_line->>'stock_issue_line_id', '')::uuid
          and stock_issue_id = v_issue.stock_issue_id
          and is_deleted = false
        for update;

        if not found then
            raise exception
                'Stock Issue line % was not found.',
                v_receipt_line_no;
        end if;

        v_received :=
            coalesce(
                nullif(v_line->>'received_base_quantity', '')::numeric,
                0
            );

        v_damaged :=
            coalesce(
                nullif(v_line->>'damaged_base_quantity', '')::numeric,
                0
            );

        v_short :=
            coalesce(
                nullif(v_line->>'short_base_quantity', '')::numeric,
                0
            );

        if v_received < 0 or v_damaged < 0 or v_short < 0 then
            raise exception
                'Receipt quantities cannot be negative on line %.',
                v_receipt_line_no;
        end if;

        v_session_total :=
            round(v_received + v_damaged + v_short, 6);

        if v_session_total <= 0 then
            raise exception
                'Receipt line % must record a quantity.',
                v_receipt_line_no;
        end if;

        select coalesce(
            sum(
                rl.received_base_quantity
                + rl.damaged_base_quantity
                + rl.short_base_quantity
            ),
            0
        )
        into v_prior_recorded
        from public.stock_issue_receipt_lines rl
        join public.stock_issue_receipts rh
          on rh.stock_issue_receipt_id = rl.stock_issue_receipt_id
        where rl.stock_issue_line_id =
              v_issue_line.stock_issue_line_id
          and rl.is_deleted = false
          and rh.is_deleted = false
          and rh.receipt_status <> 'Draft';

        v_outstanding :=
            round(
                v_issue_line.issue_base_quantity
                - v_prior_recorded,
                6
            );

        if v_session_total > v_outstanding then
            raise exception
                'Receipt quantity exceeds outstanding quantity on Stock Issue line %. Outstanding: % %, submitted: % %.',
                v_issue_line.line_no,
                v_outstanding,
                v_issue_line.base_uom_code,
                v_session_total,
                v_issue_line.base_uom_code;
        end if;

        if (v_damaged > 0 or v_short > 0)
           and nullif(btrim(v_line->>'notes'), '') is null then
            raise exception
                'Notes are required for short or damaged quantity on Stock Issue line %.',
                v_issue_line.line_no;
        end if;

        if v_damaged > 0 then
            v_any_damage := true;
        end if;

        if v_short > 0 then
            v_any_short := true;
        end if;

        insert into public.stock_issue_receipt_lines (
            stock_issue_receipt_id,
            stock_issue_line_id,
            line_no,
            received_base_quantity,
            damaged_base_quantity,
            short_base_quantity,
            condition_status,
            notes,
            is_active,
            is_deleted
        )
        values (
            p_stock_issue_receipt_id,
            v_issue_line.stock_issue_line_id,
            v_receipt_line_no,
            v_received,
            v_damaged,
            v_short,
            coalesce(
                nullif(v_line->>'condition_status', ''),
                case
                    when v_damaged > 0 then 'Damaged'
                    when v_short > 0 then 'Short'
                    when v_session_total < v_outstanding then 'Partial'
                    else 'Good'
                end
            ),
            nullif(btrim(v_line->>'notes'), ''),
            true,
            false
        );
    end loop;

    if v_any_short
       and not exists (
            select 1
            from public.inventory_transaction_photos
            where source_type = 'StockIssueReceipt'
              and source_id = p_stock_issue_receipt_id
              and photo_type = 'ShortSupplied'
              and is_deleted = false
       ) then
        raise exception
            'A ShortSupplied photo is required when short quantity is recorded.';
    end if;

    if v_any_damage
       and not exists (
            select 1
            from public.inventory_transaction_photos
            where source_type = 'StockIssueReceipt'
              and source_id = p_stock_issue_receipt_id
              and photo_type = 'DamagedOnDelivery'
              and is_deleted = false
       ) then
        raise exception
            'A DamagedOnDelivery photo is required when damaged quantity is recorded.';
    end if;

    -- Roll up every Stock Issue line from all confirmed receipt sessions.
    update public.stock_issue_lines sil
    set
        received_base_quantity = totals.received_qty,
        damaged_base_quantity = totals.damaged_qty,
        short_base_quantity = totals.short_qty,
        line_status = case
            when totals.recorded_qty < sil.issue_base_quantity
                then 'PartiallyReceived'
            when totals.damaged_qty > 0
                then 'Damaged'
            when totals.short_qty > 0
                then 'Short'
            else 'Received'
        end,
        receipt_notes = coalesce(
            nullif(btrim(p_receipt_notes), ''),
            sil.receipt_notes
        ),
        updated_at = now(),
        updated_by = auth.uid()
    from (
        select
            issue_line.stock_issue_line_id,
            coalesce(sum(receipt_line.received_base_quantity), 0)
                as received_qty,
            coalesce(sum(receipt_line.damaged_base_quantity), 0)
                as damaged_qty,
            coalesce(sum(receipt_line.short_base_quantity), 0)
                as short_qty,
            coalesce(sum(
                receipt_line.received_base_quantity
                + receipt_line.damaged_base_quantity
                + receipt_line.short_base_quantity
            ), 0) as recorded_qty
        from public.stock_issue_lines issue_line
        left join public.stock_issue_receipt_lines receipt_line
          on receipt_line.stock_issue_line_id =
             issue_line.stock_issue_line_id
         and receipt_line.is_deleted = false
        left join public.stock_issue_receipts receipt_header
          on receipt_header.stock_issue_receipt_id =
             receipt_line.stock_issue_receipt_id
         and receipt_header.is_deleted = false
        where issue_line.stock_issue_id = v_issue.stock_issue_id
          and issue_line.is_deleted = false
          and (
              receipt_header.stock_issue_receipt_id is null
              or receipt_header.receipt_status <> 'Draft'
              or receipt_header.stock_issue_receipt_id =
                 p_stock_issue_receipt_id
          )
        group by issue_line.stock_issue_line_id
    ) totals
    where sil.stock_issue_line_id = totals.stock_issue_line_id;

    select exists (
        select 1
        from public.stock_issue_lines
        where stock_issue_id = v_issue.stock_issue_id
          and is_deleted = false
          and (
              received_base_quantity
              + damaged_base_quantity
              + short_base_quantity
          ) < issue_base_quantity
    )
    into v_any_outstanding;

    if v_any_damage then
        v_receipt_status := 'Damaged';
    elsif v_any_short then
        v_receipt_status := 'Short';
    elsif v_any_outstanding then
        v_receipt_status := 'Partial';
    else
        v_receipt_status := 'Received';
    end if;

    if v_any_outstanding then
        v_issue_status := 'PartiallyReceived';
    else
        v_issue_status := 'Received';
    end if;

    update public.stock_issue_receipts
    set
        receipt_status = v_receipt_status,
        received_at = coalesce(p_received_at, now()),
        confirmed_at = now(),
        confirmed_by = auth.uid(),
        receipt_notes = coalesce(
            nullif(btrim(p_receipt_notes), ''),
            receipt_notes
        ),
        updated_at = now(),
        updated_by = auth.uid()
    where stock_issue_receipt_id = p_stock_issue_receipt_id;

    update public.stock_issues
    set
        issue_status = v_issue_status,
        received_at = case
            when v_issue_status = 'Received'
                then coalesce(p_received_at, now())
            else received_at
        end,
        received_by = case
            when v_issue_status = 'Received'
                then auth.uid()
            else received_by
        end,
        updated_at = now(),
        updated_by = auth.uid()
    where stock_issue_id = v_issue.stock_issue_id;

    return jsonb_build_object(
        'stock_issue_id', v_issue.stock_issue_id,
        'stock_issue_receipt_id', p_stock_issue_receipt_id,
        'receipt_no', v_receipt.receipt_no,
        'receipt_status', v_receipt_status,
        'issue_status', v_issue_status,
        'photo_count', v_photo_count
    );
end;
$$;


ALTER FUNCTION "public"."confirm_stock_issue_receipt_atomic"("p_stock_issue_receipt_id" "uuid", "p_lines" "jsonb", "p_received_at" timestamp with time zone, "p_receipt_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_credit_note_atomic"("p_original_invoice_id" "uuid", "p_reason" "text", "p_lines" "jsonb", "p_notes" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    v_original public.customer_invoices%rowtype;
    v_invoice_id uuid;
    v_payload jsonb;
begin
    perform public.assert_invoice_permission('invoices.create_credit_note');

    if nullif(btrim(p_reason), '') is null then
        raise exception 'Credit Note reason is required.';
    end if;

    select *
    into v_original
    from public.customer_invoices
    where customer_invoice_id = p_original_invoice_id
      and is_deleted = false
    for update;

    if not found then
        raise exception 'Original Invoice not found.';
    end if;

    if v_original.document_status <> 'Issued' then
        raise exception 'Credit Notes can only reference an Issued Invoice.';
    end if;

    v_payload := jsonb_build_object(
        'customer_id', v_original.customer_id,
        'project_id', v_original.project_id,
        'project_site_id', v_original.project_site_id,
        'invoice_type', 'Standard',
        'invoice_date', current_date,
        'due_date', current_date,
        'currency_code', v_original.currency_code,
        'customer_reference', v_original.invoice_no,
        'notes', p_notes
    );

    -- Create as validated Standard draft, then convert atomically.
    v_invoice_id := public._create_invoice_atomic_core(
        v_payload,
        p_lines,
        '[]'::jsonb
    );

    update public.customer_invoices
    set
        invoice_type = 'Credit Note',
        original_invoice_id = p_original_invoice_id,
        credit_note_reason = btrim(p_reason),
        updated_by = auth.uid()
    where customer_invoice_id = v_invoice_id;

    return v_invoice_id;
end;
$$;


ALTER FUNCTION "public"."create_credit_note_atomic"("p_original_invoice_id" "uuid", "p_reason" "text", "p_lines" "jsonb", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_invoice_atomic"("p_invoice" "jsonb", "p_lines" "jsonb", "p_sources" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    v_invoice_type text;
begin
    perform public.assert_invoice_permission('invoices.create');

    if p_invoice is null or jsonb_typeof(p_invoice) <> 'object' then
        raise exception 'Invoice header must be a JSON object.';
    end if;

    v_invoice_type :=
        coalesce(
            nullif(btrim(p_invoice ->> 'invoice_type'), ''),
            'Standard'
        );

    if v_invoice_type in ('Credit Note', 'Retention Release') then
        raise exception
            'Use the dedicated Credit Note or Retention Release RPC.';
    end if;

    return public._create_invoice_atomic_core(
        p_invoice,
        p_lines,
        p_sources
    );
end;
$$;


ALTER FUNCTION "public"."create_invoice_atomic"("p_invoice" "jsonb", "p_lines" "jsonb", "p_sources" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_product_atomic"("p_product" "jsonb", "p_uom_conversions" "jsonb" DEFAULT '[]'::"jsonb", "p_coverages" "jsonb" DEFAULT '[]'::"jsonb", "p_attributes" "jsonb" DEFAULT '[]'::"jsonb") RETURNS TABLE("product_id" "uuid", "product_code" "text", "product_name" "text", "variant_code" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
    if not public.can_manage_products_strict() then
        raise exception
            'Only Admin can create Products.';
    end if;

    return query
    select result_row.*
    from public.create_product_atomic_internal(
        p_product,
        p_uom_conversions,
        p_coverages,
        p_attributes
    ) as result_row;
end;
$$;


ALTER FUNCTION "public"."create_product_atomic"("p_product" "jsonb", "p_uom_conversions" "jsonb", "p_coverages" "jsonb", "p_attributes" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_product_atomic"("p_product" "jsonb", "p_uom_conversions" "jsonb", "p_coverages" "jsonb", "p_attributes" "jsonb") IS 'Strict Admin-only public Product creation RPC. Validates the caller before invoking the internal atomic Product transaction.';



CREATE OR REPLACE FUNCTION "public"."create_product_atomic_internal"("p_product" "jsonb", "p_uom_conversions" "jsonb" DEFAULT '[]'::"jsonb", "p_coverages" "jsonb" DEFAULT '[]'::"jsonb", "p_attributes" "jsonb" DEFAULT '[]'::"jsonb") RETURNS TABLE("product_id" "uuid", "product_code" "text", "product_name" "text", "variant_code" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
    v_product_id uuid;
    v_product_code text;
    v_generated record;
    v_registry_id uuid;

    v_product_name text;
    v_product_type text;
    v_category_id uuid;

    v_base_uom_code text;
    v_default_purchase_uom_code text;
    v_default_request_uom_code text;
    v_default_sales_uom_code text;

    v_variant_name text;
    v_variant_description text;

    v_is_stock_item boolean;
    v_is_service_item boolean;
    v_uses_coverage boolean;
    v_default_waste_percent numeric;
    v_is_active boolean;

    v_conversion jsonb;
    v_coverage jsonb;
    v_attribute jsonb;

    v_attribute_value_id uuid;
    v_option_id_text text;

    v_from_uom_code text;
    v_conversion_factor numeric;

    v_attribute_id uuid;
    v_selected_option_id uuid;

    v_option_ids jsonb;

    v_generated_by uuid;
begin
    -- ========================================================
    -- 1. Strict Admin only
    -- ========================================================

    if not (
        public.is_strict_admin_role()
        or current_user in (
            'postgres',
            'service_role',
            'supabase_admin'
        )
    ) then
        raise exception
            'Only Admin can create Products.';
    end if;


    if p_product is null
       or jsonb_typeof(p_product) <> 'object' then
        raise exception
            'Product data is required.';
    end if;


    if coalesce(jsonb_typeof(p_uom_conversions), 'null') <> 'array' then
        raise exception
            'UOM Conversions must be supplied as a JSON array.';
    end if;

    if coalesce(jsonb_typeof(p_coverages), 'null') <> 'array' then
        raise exception
            'Product Coverages must be supplied as a JSON array.';
    end if;

    if coalesce(jsonb_typeof(p_attributes), 'null') <> 'array' then
        raise exception
            'Product Attributes must be supplied as a JSON array.';
    end if;


    -- ========================================================
    -- 2. Product Core values
    -- ========================================================

    v_product_name :=
        nullif(btrim(p_product ->> 'product_name'), '');

    if v_product_name is null then
        raise exception 'Product Name is required.';
    end if;


    v_product_type :=
        nullif(btrim(p_product ->> 'product_type'), '');

    if v_product_type not in (
        'Material',
        'Consumable',
        'Tool',
        'Equipment',
        'Service'
    ) then
        raise exception
            'Product Type must be Material, Consumable, Tool, Equipment or Service.';
    end if;


    begin
        v_category_id :=
            nullif(p_product ->> 'category_id', '')::uuid;
    exception
        when invalid_text_representation then
            raise exception 'Product Category is invalid.';
    end;

    if v_category_id is null then
        raise exception 'Product Category is required.';
    end if;


    if not exists (
        select 1
        from public.product_categories category_row
        where category_row.category_id = v_category_id
          and category_row.is_active = true
          and category_row.is_deleted = false
    ) then
        raise exception
            'The selected Product Category is inactive or does not exist.';
    end if;


    v_base_uom_code :=
        nullif(btrim(p_product ->> 'base_uom_code'), '');

    if v_base_uom_code is null then
        raise exception 'Base UOM is required.';
    end if;


    if not exists (
        select 1
        from public.units_of_measure uom
        where uom.uom_code = v_base_uom_code
          and uom.is_active = true
          and uom.is_deleted = false
    ) then
        raise exception
            'Base UOM % is inactive or does not exist.',
            v_base_uom_code;
    end if;


    v_default_purchase_uom_code :=
        nullif(btrim(p_product ->> 'default_purchase_uom_code'), '');

    v_default_request_uom_code :=
        nullif(btrim(p_product ->> 'default_request_uom_code'), '');

    v_default_sales_uom_code :=
        nullif(btrim(p_product ->> 'default_sales_uom_code'), '');


    -- หากไม่ส่ง Default UOM ให้ใช้ Base UOM
    v_default_purchase_uom_code :=
        coalesce(
            v_default_purchase_uom_code,
            v_base_uom_code
        );

    v_default_request_uom_code :=
        coalesce(
            v_default_request_uom_code,
            v_base_uom_code
        );

    v_default_sales_uom_code :=
        coalesce(
            v_default_sales_uom_code,
            v_base_uom_code
        );


    v_variant_name :=
        nullif(btrim(p_product ->> 'variant_name'), '');

    if v_variant_name is null then
        raise exception 'Variant Name is required.';
    end if;

    if char_length(v_variant_name) < 2
       or char_length(v_variant_name) > 120 then
        raise exception
            'Variant Name must contain between 2 and 120 characters.';
    end if;


    v_variant_description :=
        nullif(
            btrim(p_product ->> 'variant_description'),
            ''
        );

    if v_variant_description is not null
       and char_length(v_variant_description) > 500 then
        raise exception
            'Variant Description cannot exceed 500 characters.';
    end if;


    v_is_stock_item :=
        coalesce(
            (p_product ->> 'is_stock_item')::boolean,
            v_product_type <> 'Service'
        );

    v_is_service_item :=
        coalesce(
            (p_product ->> 'is_service_item')::boolean,
            v_product_type = 'Service'
        );

    if v_product_type = 'Service' then
        v_is_stock_item := false;
        v_is_service_item := true;
    else
        v_is_service_item := false;
    end if;


    v_uses_coverage :=
        coalesce(
            (p_product ->> 'uses_coverage')::boolean,
            false
        );

    v_default_waste_percent :=
        coalesce(
            nullif(
                p_product ->> 'default_waste_percent',
                ''
            )::numeric,
            0
        );

    if v_default_waste_percent < 0
       or v_default_waste_percent > 100 then
        raise exception
            'Default Waste Percent must be between 0 and 100.';
    end if;


    v_is_active :=
        coalesce(
            (p_product ->> 'is_active')::boolean,
            true
        );

    v_generated_by := auth.uid();


    -- ========================================================
    -- 3. Generate and reserve Admin-selected Variant Code
    --
    -- หากขั้นตอนภายหลังล้มเหลว Registry INSERT นี้จะ Rollback
    -- ========================================================

    select generated.*
    into v_generated
    from public.generate_product_code_variant(
        nullif(
            p_product ->> 'product_code_category_variant_id',
            ''
        )::uuid,

        nullif(
            p_product ->> 'product_code_type_id',
            ''
        )::uuid,

        nullif(
            p_product ->> 'product_code_size_rule_id',
            ''
        )::uuid,

        nullif(
            p_product ->> 'product_colour_id',
            ''
        )::uuid,

        nullif(
            p_product ->> 'first_size_value',
            ''
        )::integer,

        nullif(
            p_product ->> 'second_size_value',
            ''
        )::integer,

        nullif(
            p_product ->> 'product_code_variant_number',
            ''
        )::smallint,

        v_variant_name,
        v_variant_description
    ) as generated;


    if v_generated.generated_product_code is null then
        raise exception
            'Unable to generate the Product Code.';
    end if;

    v_product_code :=
        v_generated.generated_product_code;


    -- ========================================================
    -- 4. Insert Product
    --
    -- ใส่ Default UOM เป็น Base UOM ชั่วคราว
    -- เพื่อให้ Trigger Validation ผ่านก่อนสร้าง Conversion
    -- ========================================================

    insert into public.products (
        product_code,
        product_name,
        category_id,
        unit,
        description,

        is_stock_item,
        is_service_item,

        cost_price,
        default_sell_price,

        is_active,
        is_deleted,

        created_by,
        updated_by,

        product_type,
        search_keywords,

        base_uom_code,
        default_purchase_uom_code,
        default_request_uom_code,
        default_sales_uom_code,

        uses_coverage,
        default_waste_percent,

        product_code_category_variant_id,
        product_code_type_id,
        product_code_size_rule_id,
        product_colour_id,
        product_code_size_token,
        product_code_variant_number,
        product_code_generated_at,
        product_code_generated_by,

        variant_name,
        variant_description
    )
    values (
        v_product_code,
        v_product_name,
        v_category_id,
        v_base_uom_code,

        nullif(
            btrim(p_product ->> 'description'),
            ''
        ),

        v_is_stock_item,
        v_is_service_item,

        null,
        null,

        v_is_active,
        false,

        v_generated_by,
        v_generated_by,

        v_product_type,

        nullif(
            btrim(p_product ->> 'search_keywords'),
            ''
        ),

        v_base_uom_code,

        -- ชั่วคราวใช้ Base UOM
        v_base_uom_code,
        v_base_uom_code,
        v_base_uom_code,

        v_uses_coverage,
        v_default_waste_percent,

        nullif(
            p_product ->> 'product_code_category_variant_id',
            ''
        )::uuid,

        nullif(
            p_product ->> 'product_code_type_id',
            ''
        )::uuid,

        nullif(
            p_product ->> 'product_code_size_rule_id',
            ''
        )::uuid,

        nullif(
            p_product ->> 'product_colour_id',
            ''
        )::uuid,

        v_generated.size_token,
        v_generated.variant_number,
        v_generated.generated_at,
        v_generated_by,

        v_variant_name,
        v_variant_description
    )
    returning products.product_id
    into v_product_id;


    -- ========================================================
    -- 5. Link Variant Registry to Product
    -- ========================================================

    select registry.product_code_variant_registry_id
    into v_registry_id
    from public.product_code_variant_registry registry
    where registry.full_product_code = v_product_code
      and registry.product_id is null
    for update;


    if v_registry_id is null then
        raise exception
            'Unable to locate the reserved Product Variant Registry record.';
    end if;


    update public.product_code_variant_registry
    set product_id = v_product_id
    where product_code_variant_registry_id = v_registry_id;


    -- ========================================================
    -- 6. Insert UOM Conversions
    -- ========================================================

    for v_conversion in
        select value
        from jsonb_array_elements(p_uom_conversions)
    loop
        v_from_uom_code :=
            nullif(
                btrim(v_conversion ->> 'from_uom_code'),
                ''
            );

        if v_from_uom_code is null then
            raise exception
                'Transaction UOM is required for every conversion.';
        end if;


        if v_from_uom_code = v_base_uom_code then
            raise exception
                'A conversion is not required for Base UOM %.',
                v_base_uom_code;
        end if;


        if not exists (
            select 1
            from public.units_of_measure uom
            where uom.uom_code = v_from_uom_code
              and uom.is_active = true
              and uom.is_deleted = false
        ) then
            raise exception
                'Transaction UOM % is inactive or does not exist.',
                v_from_uom_code;
        end if;


        v_conversion_factor :=
            nullif(
                v_conversion ->> 'conversion_factor',
                ''
            )::numeric;

        if v_conversion_factor is null
           or v_conversion_factor <= 0 then
            raise exception
                'Conversion Factor for UOM % must be greater than zero.',
                v_from_uom_code;
        end if;


        insert into public.product_uom_conversions (
            product_id,
            from_uom_code,
            to_uom_code,
            conversion_factor,
            allow_fractional_quantity,
            sort_order,
            is_active,
            is_deleted,
            created_by,
            updated_by
        )
        values (
            v_product_id,
            v_from_uom_code,
            v_base_uom_code,
            v_conversion_factor,

            coalesce(
                (v_conversion ->>
                    'allow_fractional_quantity')::boolean,
                false
            ),

            coalesce(
                nullif(
                    v_conversion ->> 'sort_order',
                    ''
                )::integer,
                10
            ),

            coalesce(
                (v_conversion ->> 'is_active')::boolean,
                true
            ),

            false,
            v_generated_by,
            v_generated_by
        );
    end loop;


    -- ========================================================
    -- 7. Apply real Default UOM values
    --
    -- Trigger จะตรวจว่า UOM ต่างจาก Base มี Conversion แล้ว
    -- ========================================================

    update public.products
    set
        default_purchase_uom_code =
            v_default_purchase_uom_code,
        default_request_uom_code =
            v_default_request_uom_code,
        default_sales_uom_code =
            v_default_sales_uom_code,
        updated_by = v_generated_by
    where products.product_id = v_product_id;


    -- ========================================================
    -- 8. Insert Coverage
    -- ========================================================

    if jsonb_array_length(p_coverages) > 0
       and v_uses_coverage = false then
        raise exception
            'Uses Coverage must be enabled before Coverage rows can be added.';
    end if;


    for v_coverage in
        select value
        from jsonb_array_elements(p_coverages)
    loop
        insert into public.product_coverages (
            product_id,

            source_quantity,
            source_uom_code,

            coverage_quantity,
            coverage_uom_code,

            minimum_coverage,
            maximum_coverage,

            is_estimate,
            is_default,

            notes,
            sort_order,

            is_active,
            is_deleted,

            created_by,
            updated_by
        )
        values (
            v_product_id,

            coalesce(
                nullif(
                    v_coverage ->> 'source_quantity',
                    ''
                )::numeric,
                1
            ),

            nullif(
                btrim(v_coverage ->> 'source_uom_code'),
                ''
            ),

            nullif(
                v_coverage ->> 'coverage_quantity',
                ''
            )::numeric,

            nullif(
                btrim(v_coverage ->> 'coverage_uom_code'),
                ''
            ),

            nullif(
                v_coverage ->> 'minimum_coverage',
                ''
            )::numeric,

            nullif(
                v_coverage ->> 'maximum_coverage',
                ''
            )::numeric,

            coalesce(
                (v_coverage ->> 'is_estimate')::boolean,
                true
            ),

            coalesce(
                (v_coverage ->> 'is_default')::boolean,
                false
            ),

            nullif(
                btrim(v_coverage ->> 'notes'),
                ''
            ),

            coalesce(
                nullif(
                    v_coverage ->> 'sort_order',
                    ''
                )::integer,
                10
            ),

            coalesce(
                (v_coverage ->> 'is_active')::boolean,
                true
            ),

            false,
            v_generated_by,
            v_generated_by
        );
    end loop;


    -- ========================================================
    -- 9. Insert Dynamic Attribute Values
    -- ========================================================

    for v_attribute in
        select value
        from jsonb_array_elements(p_attributes)
    loop
        begin
            v_attribute_id :=
                nullif(
                    v_attribute ->> 'attribute_id',
                    ''
                )::uuid;
        exception
            when invalid_text_representation then
                raise exception
                    'A Product Attribute ID is invalid.';
        end;


        if v_attribute_id is null then
            raise exception
                'Attribute ID is required.';
        end if;


        if not exists (
            select 1
            from public.product_category_attributes mapping
            join public.product_attribute_definitions definition
              on definition.attribute_id =
                 mapping.attribute_id
            where mapping.category_id = v_category_id
              and mapping.attribute_id = v_attribute_id
              and mapping.is_active = true
              and mapping.is_deleted = false
              and mapping.is_hidden = false
              and definition.is_active = true
              and definition.is_deleted = false
        ) then
            raise exception
                'Attribute % is not available for the selected Product Category.',
                v_attribute_id;
        end if;


        v_selected_option_id :=
            nullif(
                v_attribute ->> 'selected_option_id',
                ''
            )::uuid;


        insert into public.product_attribute_values (
            product_id,
            attribute_id,

            value_text,
            value_number,
            value_boolean,
            value_date,
            selected_option_id,

            is_deleted,
            created_by,
            updated_by
        )
        values (
            v_product_id,
            v_attribute_id,

            nullif(
                btrim(v_attribute ->> 'value_text'),
                ''
            ),

            nullif(
                v_attribute ->> 'value_number',
                ''
            )::numeric,

            case
                when v_attribute ? 'value_boolean'
                     and v_attribute ->>
                         'value_boolean' is not null
                then
                    (v_attribute ->>
                        'value_boolean')::boolean
                else null
            end,

            nullif(
                v_attribute ->> 'value_date',
                ''
            )::date,

            v_selected_option_id,

            false,
            v_generated_by,
            v_generated_by
        )
        returning
            product_attribute_value_id
        into v_attribute_value_id;


        -- ----------------------------------------------------
        -- Multi-select options
        -- ----------------------------------------------------

        v_option_ids :=
            coalesce(
                v_attribute -> 'option_ids',
                '[]'::jsonb
            );

        if jsonb_typeof(v_option_ids) <> 'array' then
            raise exception
                'Attribute option_ids must be a JSON array.';
        end if;


        for v_option_id_text in
            select jsonb_array_elements_text(v_option_ids)
        loop
            if not exists (
                select 1
                from public.product_attribute_options option_row
                where option_row.attribute_option_id =
                      v_option_id_text::uuid
                  and option_row.attribute_id =
                      v_attribute_id
                  and option_row.is_active = true
                  and option_row.is_deleted = false
            ) then
                raise exception
                    'Attribute Option % is invalid for Attribute %.',
                    v_option_id_text,
                    v_attribute_id;
            end if;


            insert into
                public.product_attribute_value_options (
                    product_attribute_value_id,
                    attribute_option_id,
                    created_by
                )
            values (
                v_attribute_value_id,
                v_option_id_text::uuid,
                v_generated_by
            );
        end loop;
    end loop;


    -- ========================================================
    -- 10. Return created Product
    -- ========================================================

    return query
    select
        v_product_id,
        v_product_code,
        v_product_name,
        lpad(
            v_generated.variant_number::text,
            2,
            '0'
        );

end;
$$;


ALTER FUNCTION "public"."create_product_atomic_internal"("p_product" "jsonb", "p_uom_conversions" "jsonb", "p_coverages" "jsonb", "p_attributes" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_product_atomic_internal"("p_product" "jsonb", "p_uom_conversions" "jsonb", "p_coverages" "jsonb", "p_attributes" "jsonb") IS 'Strict Admin-only atomic Product creation. Reserves an Admin-controlled Variant Code, creates the Product, links the registry and saves UOM conversions, coverage and dynamic attributes in one transaction.';



CREATE OR REPLACE FUNCTION "public"."create_project_area_atomic"("p_site_id" "uuid", "p_area_name" "text", "p_area_type" "text" DEFAULT NULL::"text", "p_estimated_quantity" numeric DEFAULT NULL::numeric, "p_unit_of_measure" "text" DEFAULT 'sqm'::"text", "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    v_actor uuid;

    v_site public.project_sites%rowtype;
    v_project public.projects%rowtype;
    v_area public.project_areas%rowtype;

    v_area_name text;
    v_area_type text;
    v_unit_of_measure text;
    v_notes text;
begin
    -- ========================================================
    -- 1. AUTHENTICATION AND PERMISSION
    -- ========================================================

    v_actor := auth.uid();

    if v_actor is null then
        raise exception
            'Authentication is required.';
    end if;

    if not public.has_permission(
        'project_areas.create'
    ) then
        raise exception
            'Permission denied: project_areas.create is required.';
    end if;


    -- ========================================================
    -- 2. NORMALIZE INPUTS
    -- ========================================================

    v_area_name :=
        nullif(
            btrim(p_area_name),
            ''
        );

    v_area_type :=
        nullif(
            btrim(p_area_type),
            ''
        );

    v_unit_of_measure :=
        coalesce(
            nullif(
                btrim(p_unit_of_measure),
                ''
            ),
            'sqm'
        );

    v_notes :=
        nullif(
            btrim(p_notes),
            ''
        );


    -- ========================================================
    -- 3. VALIDATE INPUTS
    -- ========================================================

    if p_site_id is null then
        raise exception
            'Project Site ID is required.';
    end if;

    if v_area_name is null then
        raise exception
            'Area Name is required.';
    end if;

    if p_estimated_quantity is not null
       and p_estimated_quantity < 0 then
        raise exception
            'Estimated Quantity cannot be negative.';
    end if;


    -- ========================================================
    -- 4. LOCK AND VALIDATE SITE
    -- ========================================================

    select ps.*
    into v_site
    from public.project_sites ps
    where ps.site_id = p_site_id
      and ps.is_deleted = false
      and ps.is_active = true
    for update;

    if not found then
        raise exception
            'Project Site was not found, is inactive, or has been deleted.';
    end if;

    if v_site.project_id is null then
        raise exception
            'Project Site does not have a Project.';
    end if;

    if v_site.site_status not in (
        'Quotation',
        'Active'
    ) then
        raise exception
            'A Project Area can only be added while the Site status is Quotation or Active. Current status: %.',
            v_site.site_status;
    end if;


    -- ========================================================
    -- 5. LOCK AND VALIDATE PROJECT
    -- ========================================================

    select pr.*
    into v_project
    from public.projects pr
    where pr.project_id = v_site.project_id
      and pr.is_deleted = false
      and pr.is_active = true
    for update;

    if not found then
        raise exception
            'Project linked to the Site was not found, is inactive, or has been deleted.';
    end if;


    -- ========================================================
    -- 6. CREATE PROVISIONAL AREA
    --
    -- area_code:
    --   Generated by column default / trigger.
    --
    -- project_id:
    --   Resolved from the locked Site, never trusted from client.
    --
    -- area_status:
    --   Always Quotation until accepted through a commercial source.
    -- ========================================================

    insert into public.project_areas (
        project_id,
        site_id,
        area_name,
        area_type,
        estimated_quantity,
        unit_of_measure,
        notes,
        area_status,
        is_active,
        is_deleted,
        created_by,
        updated_by
    )
    values (
        v_site.project_id,
        v_site.site_id,
        v_area_name,
        v_area_type,
        p_estimated_quantity,
        v_unit_of_measure,
        v_notes,
        'Quotation',
        true,
        false,
        v_actor,
        v_actor
    )
    returning *
    into v_area;


    -- ========================================================
    -- 7. RETURN CREATED AREA AND COMMERCIAL CONTEXT
    -- ========================================================

    return jsonb_build_object(
        'area',
            to_jsonb(v_area),

        'area_id',
            v_area.area_id,

        'area_code',
            v_area.area_code,

        'area_name',
            v_area.area_name,

        'area_status',
            v_area.area_status,

        'project_id',
            v_area.project_id,

        'site_id',
            v_area.site_id,

        'site_status',
            v_site.site_status,

        'required_commercial_workflow',
            case
                when v_site.site_status = 'Active'
                    then 'Variation'
                else 'Quotation'
            end
    );
end;
$$;


ALTER FUNCTION "public"."create_project_area_atomic"("p_site_id" "uuid", "p_area_name" "text", "p_area_type" "text", "p_estimated_quantity" numeric, "p_unit_of_measure" "text", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_purchase_order_atomic"("p_purchase_order" "jsonb", "p_lines" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
    v_auth_user_id uuid := auth.uid();
    v_supplier public.suppliers%rowtype;
    v_purchase_order_id uuid;
    v_purchase_order_no text;
    v_supplier_id uuid;
    v_project_id uuid;
    v_site_id uuid;
    v_stock_location_id uuid;
    v_order_date date;
    v_expected_delivery_date date;
    v_supplier_quote_date date;
    v_source_type text;
    v_currency_code text;
    v_payment_terms_type text;
    v_payment_terms_days integer;
    v_default_tax_type text;
    v_delivery_destination_type text;
    v_supplier_contact_snapshot jsonb;
    v_supplier_address_snapshot jsonb;
    v_line_result jsonb;
begin
    if v_auth_user_id is null then
        raise exception 'Authentication is required.';
    end if;

    if not public.has_permission('purchase_orders.create') then
        raise exception 'You do not have permission to create purchase orders.';
    end if;

    if p_purchase_order is null
       or jsonb_typeof(p_purchase_order) <> 'object' then
        raise exception 'Purchase order header is required.';
    end if;

    begin
        v_supplier_id :=
            nullif(btrim(p_purchase_order ->> 'supplier_id'), '')::uuid;
        v_project_id :=
            nullif(btrim(p_purchase_order ->> 'project_id'), '')::uuid;
        v_site_id :=
            nullif(btrim(p_purchase_order ->> 'site_id'), '')::uuid;
        v_stock_location_id :=
            nullif(btrim(p_purchase_order ->> 'stock_location_id'), '')::uuid;
        v_order_date := coalesce(
            nullif(p_purchase_order ->> 'order_date', '')::date,
            current_date
        );
        v_expected_delivery_date :=
            nullif(p_purchase_order ->> 'expected_delivery_date', '')::date;
        v_supplier_quote_date :=
            nullif(p_purchase_order ->> 'supplier_quote_date', '')::date;
    exception
        when invalid_text_representation then
            raise exception 'Invalid purchase order header value.';
    end;

    if v_supplier_id is null then
        raise exception 'Supplier is required.';
    end if;

    select *
    into v_supplier
    from public.suppliers
    where supplier_id = v_supplier_id
      and is_deleted = false
      and is_active = true;

    if not found then
        raise exception 'Active supplier was not found.';
    end if;

    if v_project_id is not null
       and not exists (
           select 1
           from public.projects project_row
           where project_row.project_id = v_project_id
             and project_row.is_deleted = false
       ) then
        raise exception 'Project was not found.';
    end if;

    if v_site_id is not null
       and (
           v_project_id is null
           or not exists (
               select 1
               from public.project_sites site_row
               where site_row.site_id = v_site_id
                 and site_row.project_id = v_project_id
                 and site_row.is_deleted = false
           )
       ) then
        raise exception 'Selected Site does not belong to the selected Project.';
    end if;

    if v_expected_delivery_date is not null
       and v_expected_delivery_date < v_order_date then
        raise exception 'Expected delivery date cannot be before order date.';
    end if;

    v_source_type := coalesce(
        nullif(btrim(p_purchase_order ->> 'source_type'), ''),
        'Manual'
    );

    if v_source_type not in (
        'Manual',
        'StockRequest',
        'MaterialRequirement',
        'Mixed'
    ) then
        raise exception 'Invalid Purchase Order source type.';
    end if;

    v_currency_code := coalesce(
        nullif(btrim(p_purchase_order ->> 'currency_code'), ''),
        v_supplier.default_currency,
        'AUD'
    );
    v_payment_terms_type := coalesce(
        nullif(btrim(p_purchase_order ->> 'payment_terms_type'), ''),
        v_supplier.payment_terms_type
    );

    begin
        v_payment_terms_days := coalesce(
            nullif(p_purchase_order ->> 'payment_terms_days', '')::integer,
            v_supplier.payment_terms_days
        );
    exception
        when invalid_text_representation then
            raise exception 'Invalid payment terms days.';
    end;

    v_default_tax_type := coalesce(
        nullif(btrim(p_purchase_order ->> 'default_tax_type'), ''),
        v_supplier.default_tax_type
    );
    v_delivery_destination_type := coalesce(
        nullif(btrim(p_purchase_order ->> 'delivery_destination_type'), ''),
        case when v_stock_location_id is not null then 'Warehouse' else 'Site' end
    );

    if v_delivery_destination_type not in (
        'Warehouse',
        'Site',
        'DirectDelivery',
        'Other'
    ) then
        raise exception 'Invalid delivery destination type.';
    end if;

    if v_delivery_destination_type = 'Warehouse'
       and v_stock_location_id is null then
        raise exception 'Stock Location is required for Warehouse delivery.';
    end if;

    if v_stock_location_id is not null
       and not exists (
           select 1
           from public.stock_locations location_row
           where location_row.stock_location_id = v_stock_location_id
             and location_row.is_deleted = false
             and location_row.is_active = true
       ) then
        raise exception 'Active Stock Location was not found.';
    end if;

    select to_jsonb(contact_row)
    into v_supplier_contact_snapshot
    from public.supplier_contacts contact_row
    where contact_row.supplier_id = v_supplier_id
      and contact_row.is_deleted = false
      and contact_row.is_active = true
    order by contact_row.is_primary desc, contact_row.created_at
    limit 1;

    select to_jsonb(address_row)
    into v_supplier_address_snapshot
    from public.supplier_addresses address_row
    where address_row.supplier_id = v_supplier_id
      and address_row.is_deleted = false
      and address_row.is_active = true
    order by address_row.is_primary desc, address_row.created_at
    limit 1;

    insert into public.purchase_orders (
        purchase_order_no,
        supplier_id,
        project_id,
        site_id,
        order_date,
        expected_delivery_date,
        order_status,
        subtotal_amount,
        tax_amount,
        total_amount,
        notes,
        is_deleted,
        created_by,
        updated_by,
        source_type,
        supplier_reference,
        supplier_quote_no,
        supplier_quote_date,
        currency_code,
        payment_terms_type,
        payment_terms_days,
        default_tax_type,
        delivery_destination_type,
        stock_location_id,
        supplier_contact_snapshot,
        supplier_address_snapshot,
        delivery_address_snapshot,
        delivery_contact_name,
        delivery_contact_phone,
        delivery_method,
        delivery_instructions,
        supplier_notes,
        internal_notes
    )
    values (
        null,
        v_supplier_id,
        v_project_id,
        v_site_id,
        v_order_date,
        v_expected_delivery_date,
        'Draft',
        0,
        0,
        0,
        nullif(btrim(p_purchase_order ->> 'notes'), ''),
        false,
        v_auth_user_id,
        v_auth_user_id,
        v_source_type,
        nullif(btrim(p_purchase_order ->> 'supplier_reference'), ''),
        nullif(btrim(p_purchase_order ->> 'supplier_quote_no'), ''),
        v_supplier_quote_date,
        v_currency_code,
        v_payment_terms_type,
        v_payment_terms_days,
        v_default_tax_type,
        v_delivery_destination_type,
        v_stock_location_id,
        v_supplier_contact_snapshot,
        v_supplier_address_snapshot,
        p_purchase_order -> 'delivery_address_snapshot',
        nullif(btrim(p_purchase_order ->> 'delivery_contact_name'), ''),
        nullif(btrim(p_purchase_order ->> 'delivery_contact_phone'), ''),
        nullif(btrim(p_purchase_order ->> 'delivery_method'), ''),
        nullif(btrim(p_purchase_order ->> 'delivery_instructions'), ''),
        nullif(btrim(p_purchase_order ->> 'supplier_notes'), ''),
        nullif(btrim(p_purchase_order ->> 'internal_notes'), '')
    )
    returning purchase_order_id, purchase_order_no
    into v_purchase_order_id, v_purchase_order_no;

    v_line_result := public._replace_purchase_order_lines_atomic(
        v_purchase_order_id,
        v_supplier_id,
        v_project_id,
        v_site_id,
        p_lines
    );

    update public.purchase_orders po
    set
        subtotal_amount = totals.subtotal_amount,
        tax_amount = totals.tax_amount,
        total_amount = totals.total_amount,
        updated_at = now(),
        updated_by = v_auth_user_id
    from (
        select
            coalesce(sum(line_subtotal), 0)::numeric(14,2) as subtotal_amount,
            coalesce(sum(tax_amount), 0)::numeric(14,2) as tax_amount,
            coalesce(sum(line_total), 0)::numeric(14,2) as total_amount
        from public.purchase_order_lines
        where purchase_order_id = v_purchase_order_id
          and is_deleted = false
    ) totals
    where po.purchase_order_id = v_purchase_order_id;

    return jsonb_build_object(
        'purchase_order_id', v_purchase_order_id,
        'purchase_order_no', v_purchase_order_no,
        'order_status', 'Draft',
        'created_line_count', v_line_result -> 'created_line_count'
    );
end;
$$;


ALTER FUNCTION "public"."create_purchase_order_atomic"("p_purchase_order" "jsonb", "p_lines" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_quotation_atomic"("p_quotation" "jsonb", "p_lines" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    v_user_id uuid;

    v_quotation_id uuid;
    v_quotation_no text;

    v_customer_id uuid;
    v_project_site_id uuid;
    v_project_id uuid;
    v_project_customer_id uuid;
    v_price_book_id uuid;

    v_quotation_segment text;
    v_quotation_source text;
    v_issue_date date;
    v_valid_until date;
    v_notes text;
    v_internal_notes text;

    v_site_status text;

    v_line jsonb;
    v_line_no integer := 0;
    v_line_count integer := 0;

    v_product_id uuid;
    v_project_area_id uuid;
    v_description text;

    v_sales_uom_code text;
    v_base_uom_code text;
    v_conversion_factor numeric(18,6);
    v_allow_fractional boolean;

    v_quantity numeric(12,2);
    v_base_quantity numeric(18,6);
    v_unit_price numeric(12,2);
    v_discount_percent numeric(5,2);
    v_discount_amount numeric(12,2);
    v_tax_rate numeric(5,2);
    v_tax_amount numeric(12,2);
    v_line_subtotal numeric(14,2);
    v_line_total numeric(14,2);

    v_cost_price numeric(12,2);
    v_margin_amount numeric(12,2);
    v_margin_percent numeric(5,2);

    v_line_notes text;
    v_is_optional boolean;

    v_subtotal_amount numeric(14,2) := 0;
    v_total_discount_amount numeric(14,2) := 0;
    v_total_tax_amount numeric(14,2) := 0;
    v_total_amount numeric(14,2) := 0;
begin
    -- =====================================================
    -- 1. AUTHENTICATION AND PERMISSION
    -- =====================================================

    v_user_id := auth.uid();

    if v_user_id is null then
        raise exception
            'Authentication is required.';
    end if;

    if not public.has_permission(
        'quotations.create'
    ) then
        raise exception
            'Permission denied: quotations.create is required.';
    end if;


    -- =====================================================
    -- 2. INPUT STRUCTURE
    -- =====================================================

    if p_quotation is null
       or jsonb_typeof(p_quotation) <> 'object' then
        raise exception
            'Quotation header must be a JSON object.';
    end if;

    if p_lines is null
       or jsonb_typeof(p_lines) <> 'array' then
        raise exception
            'Quotation lines must be a JSON array.';
    end if;

    v_line_count := jsonb_array_length(p_lines);

    if v_line_count = 0 then
        raise exception
            'At least one quotation line is required.';
    end if;


    -- =====================================================
    -- 3. HEADER VALUES
    -- =====================================================

    begin
        v_customer_id :=
            nullif(
                btrim(p_quotation ->> 'customer_id'),
                ''
            )::uuid;
    exception
        when invalid_text_representation then
            raise exception
                'Invalid customer_id.';
    end;

    begin
        v_project_site_id :=
            nullif(
                btrim(
                    p_quotation ->> 'project_site_id'
                ),
                ''
            )::uuid;
    exception
        when invalid_text_representation then
            raise exception
                'Invalid project_site_id.';
    end;

    begin
        v_price_book_id :=
            nullif(
                btrim(
                    p_quotation ->> 'price_book_id'
                ),
                ''
            )::uuid;
    exception
        when invalid_text_representation then
            raise exception
                'Invalid price_book_id.';
    end;

    v_quotation_segment :=
        nullif(
            btrim(
                p_quotation ->> 'quotation_segment'
            ),
            ''
        );

    v_quotation_source :=
        nullif(
            btrim(
                p_quotation ->> 'quotation_source'
            ),
            ''
        );

    begin
        v_issue_date :=
            nullif(
                btrim(p_quotation ->> 'issue_date'),
                ''
            )::date;
    exception
        when others then
            raise exception
                'Invalid issue_date.';
    end;

    begin
        v_valid_until :=
            nullif(
                btrim(
                    p_quotation ->> 'valid_until'
                ),
                ''
            )::date;
    exception
        when others then
            raise exception
                'Invalid valid_until.';
    end;

    v_notes :=
        nullif(
            btrim(p_quotation ->> 'notes'),
            ''
        );

    v_internal_notes :=
        nullif(
            btrim(
                p_quotation ->> 'internal_notes'
            ),
            ''
        );


    -- =====================================================
    -- 4. HEADER VALIDATION
    -- =====================================================

    if v_customer_id is null then
        raise exception
            'Customer is required.';
    end if;

    if v_project_site_id is null then
        raise exception
            'Project Site is required for an official quotation.';
    end if;

    if v_quotation_segment is null then
        raise exception
            'Quotation Segment is required.';
    end if;

    if v_quotation_segment not in (
        'Retail',
        'Builder',
        'Commercial',
        'VIP',
        'Promotion'
    ) then
        raise exception
            'Invalid Quotation Segment: %.',
            v_quotation_segment;
    end if;

    if v_issue_date is not null
       and v_valid_until is not null
       and v_valid_until < v_issue_date then
        raise exception
            'Valid Until cannot be earlier than Issue Date.';
    end if;


    -- =====================================================
    -- 5. LOCK AND VALIDATE SITE/PROJECT HIERARCHY
    -- =====================================================

    select
        ps.project_id,
        ps.site_status,
        p.customer_id
    into
        v_project_id,
        v_site_status,
        v_project_customer_id
    from public.project_sites ps
    join public.projects p
      on p.project_id = ps.project_id
    where ps.site_id = v_project_site_id
      and ps.is_deleted = false
      and ps.is_active = true
      and p.is_deleted = false
      and p.is_active = true
    for update of ps, p;

    if not found then
        raise exception
            'Project Site or its Project does not exist, is inactive, or is deleted.';
    end if;

    if v_project_customer_id <>
       v_customer_id then
        raise exception
            'Quotation Customer must match the Project Customer.';
    end if;

    if v_site_status <> 'Quotation' then
        raise exception
            'A new base quotation can only be created for a Site with Quotation status. Current status: %.',
            v_site_status;
    end if;

    if exists (
        select 1
        from public.quotations q
        where q.project_site_id =
              v_project_site_id
          and q.quotation_status =
              'Accepted'
          and q.is_deleted = false
    ) then
        raise exception
            'This Project Site already has an accepted base quotation. Use a Variation for contract changes.';
    end if;


    -- =====================================================
    -- 6. OPTIONAL PRICE BOOK VALIDATION
    -- =====================================================

    if v_price_book_id is not null
       and not exists (
            select 1
            from public.price_books pb
            where pb.price_book_id =
                  v_price_book_id
       ) then
        raise exception
            'Selected Price Book does not exist.';
    end if;


    -- =====================================================
    -- 7. CREATE QUOTATION HEADER
    --
    -- quotation_no is generated by trg_set_quotation_no.
    -- Totals are initially zero and updated after all lines.
    -- =====================================================

    insert into public.quotations (
        quotation_no,
        customer_id,
        project_site_id,
        price_book_id,
        quotation_segment,
        quotation_source,
        quotation_status,
        revision_no,
        issue_date,
        valid_until,
        subtotal_amount,
        discount_amount,
        tax_amount,
        total_amount,
        notes,
        internal_notes,
        is_active,
        is_deleted,
        created_by,
        updated_by
    )
    values (
        null,
        v_customer_id,
        v_project_site_id,
        v_price_book_id,
        v_quotation_segment,
        v_quotation_source,
        'Draft',
        0,
        v_issue_date,
        v_valid_until,
        0,
        0,
        0,
        0,
        v_notes,
        v_internal_notes,
        true,
        false,
        v_user_id,
        v_user_id
    )
    returning
        quotation_id,
        quotation_no
    into
        v_quotation_id,
        v_quotation_no;


    -- =====================================================
    -- 8. CREATE AND CALCULATE QUOTATION LINES
    -- =====================================================

    for v_line in
        select value
        from jsonb_array_elements(p_lines)
    loop
        v_line_no := v_line_no + 1;

        if jsonb_typeof(v_line) <> 'object' then
            raise exception
                'Quotation line % must be a JSON object.',
                v_line_no;
        end if;

        -- -----------------------------------------------
        -- IDs
        -- -----------------------------------------------

        begin
            v_product_id :=
                nullif(
                    btrim(v_line ->> 'product_id'),
                    ''
                )::uuid;
        exception
            when invalid_text_representation then
                raise exception
                    'Line % has an invalid product_id.',
                    v_line_no;
        end;

        begin
            v_project_area_id :=
                nullif(
                    btrim(
                        v_line ->> 'project_area_id'
                    ),
                    ''
                )::uuid;
        exception
            when invalid_text_representation then
                raise exception
                    'Line % has an invalid project_area_id.',
                    v_line_no;
        end;


        -- -----------------------------------------------
        -- Description
        -- -----------------------------------------------

        v_description :=
            nullif(
                btrim(v_line ->> 'description'),
                ''
            );

        if v_description is null then
            raise exception
                'Description is required for line %.',
                v_line_no;
        end if;


        -- -----------------------------------------------
        -- UOM snapshot
        -- -----------------------------------------------

        v_sales_uom_code :=
            nullif(
                btrim(
                    v_line ->> 'sales_uom_code'
                ),
                ''
            );

        v_base_uom_code :=
            nullif(
                btrim(
                    v_line ->> 'base_uom_code'
                ),
                ''
            );

        if v_sales_uom_code is null then
            raise exception
                'Sales UOM is required for line %.',
                v_line_no;
        end if;

        if v_base_uom_code is null then
            raise exception
                'Base UOM is required for line %.',
                v_line_no;
        end if;

        if not exists (
            select 1
            from public.units_of_measure u
            where u.uom_code =
                  v_sales_uom_code
        ) then
            raise exception
                'Sales UOM % on line % does not exist.',
                v_sales_uom_code,
                v_line_no;
        end if;

        if not exists (
            select 1
            from public.units_of_measure u
            where u.uom_code =
                  v_base_uom_code
        ) then
            raise exception
                'Base UOM % on line % does not exist.',
                v_base_uom_code,
                v_line_no;
        end if;


        -- -----------------------------------------------
        -- Numeric input
        -- -----------------------------------------------

        begin
            v_quantity :=
                coalesce(
                    nullif(
                        btrim(
                            v_line ->> 'quantity'
                        ),
                        ''
                    )::numeric,
                    0
                );

            v_conversion_factor :=
                coalesce(
                    nullif(
                        btrim(
                            v_line
                            ->> 'conversion_factor'
                        ),
                        ''
                    )::numeric,
                    1
                );

            v_unit_price :=
                coalesce(
                    nullif(
                        btrim(
                            v_line ->> 'unit_price'
                        ),
                        ''
                    )::numeric,
                    0
                );

            v_discount_percent :=
                coalesce(
                    nullif(
                        btrim(
                            v_line
                            ->> 'discount_percent'
                        ),
                        ''
                    )::numeric,
                    0
                );

            v_tax_rate :=
                coalesce(
                    nullif(
                        btrim(
                            v_line ->> 'tax_rate'
                        ),
                        ''
                    )::numeric,
                    0
                );

            v_cost_price :=
                nullif(
                    btrim(
                        v_line ->> 'cost_price'
                    ),
                    ''
                )::numeric;
        exception
            when invalid_text_representation
              or numeric_value_out_of_range then
                raise exception
                    'Line % contains an invalid numeric value.',
                    v_line_no;
        end;


        -- -----------------------------------------------
        -- Boolean input
        -- -----------------------------------------------

        begin
            v_allow_fractional :=
                coalesce(
                    nullif(
                        btrim(
                            v_line
                            ->> 'allow_fractional_quantity'
                        ),
                        ''
                    )::boolean,
                    true
                );

            v_is_optional :=
                coalesce(
                    nullif(
                        btrim(
                            v_line ->> 'is_optional'
                        ),
                        ''
                    )::boolean,
                    false
                );
        exception
            when invalid_text_representation then
                raise exception
                    'Line % contains an invalid boolean value.',
                    v_line_no;
        end;


        -- -----------------------------------------------
        -- Numeric validation
        -- -----------------------------------------------

        if v_quantity <= 0 then
            raise exception
                'Quantity must be greater than zero on line %.',
                v_line_no;
        end if;

        if not v_allow_fractional
           and v_quantity <> trunc(v_quantity) then
            raise exception
                'Line % does not allow fractional quantity.',
                v_line_no;
        end if;

        if v_conversion_factor <= 0 then
            raise exception
                'Conversion Factor must be greater than zero on line %.',
                v_line_no;
        end if;

        if v_unit_price < 0 then
            raise exception
                'Unit Price cannot be negative on line %.',
                v_line_no;
        end if;

        if v_discount_percent < 0
           or v_discount_percent > 100 then
            raise exception
                'Discount Percent must be between 0 and 100 on line %.',
                v_line_no;
        end if;

        if v_tax_rate < 0 then
            raise exception
                'Tax Rate cannot be negative on line %.',
                v_line_no;
        end if;

        if v_cost_price is not null
           and v_cost_price < 0 then
            raise exception
                'Cost Price cannot be negative on line %.',
                v_line_no;
        end if;


        -- -----------------------------------------------
        -- Product validation
        -- -----------------------------------------------

        if v_product_id is not null
           and not exists (
                select 1
                from public.products pr
                where pr.product_id =
                      v_product_id
                  and pr.is_deleted = false
                  and pr.is_active = true
           ) then
            raise exception
                'Product on line % does not exist or is inactive.',
                v_line_no;
        end if;


        -- -----------------------------------------------
        -- Project Area relationship validation
        -- -----------------------------------------------

        if v_project_area_id is not null
           and not exists (
                select 1
                from public.project_areas pa
                where pa.area_id =
                      v_project_area_id
                  and pa.site_id =
                      v_project_site_id
                  and pa.project_id =
                      v_project_id
                  and pa.is_deleted = false
                  and pa.is_active = true
                  and pa.area_status =
                      'Quotation'
           ) then
            raise exception
                'Project Area on line % does not belong to the selected Project Site or is not available for quotation.',
                v_line_no;
        end if;


        -- -----------------------------------------------
        -- Server-side calculations
        -- -----------------------------------------------

        v_base_quantity :=
            round(
                v_quantity *
                v_conversion_factor,
                6
            );

        v_line_subtotal :=
            round(
                v_quantity *
                v_unit_price,
                2
            );

        v_discount_amount :=
            round(
                v_line_subtotal *
                v_discount_percent /
                100,
                2
            );

        v_tax_amount :=
            round(
                (
                    v_line_subtotal -
                    v_discount_amount
                ) *
                v_tax_rate /
                100,
                2
            );

        v_line_total :=
            round(
                v_line_subtotal -
                v_discount_amount +
                v_tax_amount,
                2
            );

        if v_cost_price is null then
            v_margin_amount := null;
            v_margin_percent := null;
        else
            v_margin_amount :=
                round(
                    (
                        v_unit_price -
                        v_cost_price
                    ) *
                    v_quantity -
                    v_discount_amount,
                    2
                );

            if (
                v_line_subtotal -
                v_discount_amount
            ) > 0 then
                v_margin_percent :=
                    round(
                        v_margin_amount /
                        (
                            v_line_subtotal -
                            v_discount_amount
                        ) *
                        100,
                        2
                    );
            else
                v_margin_percent := null;
            end if;
        end if;

        v_line_notes :=
            nullif(
                btrim(v_line ->> 'notes'),
                ''
            );


        -- -----------------------------------------------
        -- Insert line
        -- -----------------------------------------------

        insert into public.quotation_lines (
            quotation_id,
            product_id,
            project_area_id,
            line_no,
            description,
            unit_of_measure,
            quantity,
            unit_price,
            discount_percent,
            discount_amount,
            tax_rate,
            tax_amount,
            line_total,
            cost_price,
            margin_amount,
            margin_percent,
            notes,
            is_optional,
            is_deleted,
            created_by,
            updated_by,
            sales_uom_code,
            base_uom_code,
            conversion_factor,
            base_quantity,
            allow_fractional_quantity
        )
        values (
            v_quotation_id,
            v_product_id,
            v_project_area_id,
            v_line_no,
            v_description,
            v_sales_uom_code,
            v_quantity,
            v_unit_price,
            v_discount_percent,
            v_discount_amount,
            v_tax_rate,
            v_tax_amount,
            v_line_total,
            v_cost_price,
            v_margin_amount,
            v_margin_percent,
            v_line_notes,
            v_is_optional,
            false,
            v_user_id,
            v_user_id,
            v_sales_uom_code,
            v_base_uom_code,
            v_conversion_factor,
            v_base_quantity,
            v_allow_fractional
        );


        -- -----------------------------------------------
        -- Accumulate header totals
        -- Optional lines are displayed but excluded from
        -- the base quotation total until selected later.
        -- -----------------------------------------------

        if not v_is_optional then
            v_subtotal_amount :=
                v_subtotal_amount +
                v_line_subtotal;

            v_total_discount_amount :=
                v_total_discount_amount +
                v_discount_amount;

            v_total_tax_amount :=
                v_total_tax_amount +
                v_tax_amount;

            v_total_amount :=
                v_total_amount +
                v_line_total;
        end if;
    end loop;


    -- =====================================================
    -- 9. UPDATE HEADER TOTALS
    -- =====================================================

    update public.quotations
    set
        subtotal_amount =
            round(v_subtotal_amount, 2),
        discount_amount =
            round(
                v_total_discount_amount,
                2
            ),
        tax_amount =
            round(v_total_tax_amount, 2),
        total_amount =
            round(v_total_amount, 2),
        updated_by =
            v_user_id
    where quotation_id =
          v_quotation_id;


    -- =====================================================
    -- 10. UPDATE PROJECT LIFECYCLE
    -- =====================================================

    update public.projects
    set
        project_status = case
            when project_status = 'Draft'
                then 'Quoted'
            else project_status
        end,
        price_book_id =
            coalesce(
                v_price_book_id,
                price_book_id
            ),
        updated_by =
            v_user_id
    where project_id =
          v_project_id
      and is_deleted = false;


    -- =====================================================
    -- 11. RETURN RESULT
    -- =====================================================

    return jsonb_build_object(
        'quotation_id',
        v_quotation_id,
        'quotation_no',
        v_quotation_no,
        'quotation_status',
        'Draft',
        'line_count',
        v_line_count,
        'subtotal_amount',
        round(v_subtotal_amount, 2),
        'discount_amount',
        round(
            v_total_discount_amount,
            2
        ),
        'tax_amount',
        round(v_total_tax_amount, 2),
        'total_amount',
        round(v_total_amount, 2)
    );
end;
$$;


ALTER FUNCTION "public"."create_quotation_atomic"("p_quotation" "jsonb", "p_lines" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_quotation_atomic"("p_quotation" "jsonb", "p_lines" "jsonb") IS 'Creates a Draft quotation and all quotation lines atomically. Validates permission, customer/site/project hierarchy, project areas, UOM snapshots, quantities and server-calculated totals.';



CREATE OR REPLACE FUNCTION "public"."create_quotation_revision_atomic"("p_quotation_id" "uuid", "p_revision_reason" "text" DEFAULT NULL::"text", "p_revision_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    v_user_id uuid;

    v_quotation public.quotations%rowtype;
    v_current_revision public.quotation_revisions%rowtype;

    v_new_revision_id uuid;
    v_new_revision_no integer;
    v_source_revision_id uuid;

    v_customer_id uuid;
    v_project_site_id uuid;
    v_price_book_id uuid;
    v_quotation_segment text;
    v_quotation_source text;
    v_issue_date date;
    v_valid_until date;
    v_notes text;
    v_internal_notes text;

    v_subtotal_amount numeric;
    v_discount_amount numeric;
    v_tax_amount numeric;
    v_total_amount numeric;

    v_line_count integer;
begin
    -- ========================================================
    -- 1. AUTHENTICATION AND PERMISSION
    -- ========================================================

    v_user_id := auth.uid();

    if v_user_id is null then
        raise exception
            'Authentication is required.';
    end if;

    if not public.has_permission(
        'quotations.create_revision'
    ) then
        raise exception
            'Permission denied: quotations.create_revision is required.';
    end if;


    -- ========================================================
    -- 2. LOCK AND LOAD QUOTATION
    -- ========================================================

    select q.*
    into v_quotation
    from public.quotations q
    where q.quotation_id = p_quotation_id
      and q.is_deleted = false
    for update;

    if not found then
        raise exception
            'Quotation not found.';
    end if;

    if not v_quotation.is_active then
        raise exception
            'Inactive quotation cannot be revised.';
    end if;

    if v_quotation.quotation_status not in (
        'Sent',
        'Revised'
    ) then
        raise exception
            'Only Sent or Revised quotations can create a revision. Current status: %.',
            v_quotation.quotation_status;
    end if;

    if v_quotation.accepted_at is not null
       or v_quotation.accepted_by is not null
       or v_quotation.accepted_revision_id is not null then
        raise exception
            'Accepted quotation cannot create another revision. Use a Variation for contract changes.';
    end if;


    -- ========================================================
    -- 3. PREVENT MULTIPLE DRAFT REVISIONS
    -- ========================================================

    if exists (
        select 1
        from public.quotation_revisions qr
        where qr.quotation_id = p_quotation_id
          and qr.revision_status = 'Draft'
          and qr.is_active = true
          and qr.is_deleted = false
    ) then
        raise exception
            'This quotation already has a Draft revision. Update or send the existing Draft revision first.';
    end if;


    -- ========================================================
    -- 4. RESOLVE SOURCE SNAPSHOT
    -- ========================================================

    if v_quotation.quotation_status = 'Sent' then
        -- ----------------------------------------------------
        -- First revision: copy the base quotation.
        -- ----------------------------------------------------

        if v_quotation.current_revision_id is not null then
            raise exception
                'Sent quotation unexpectedly contains a current revision pointer.';
        end if;

        v_source_revision_id := null;

        v_customer_id :=
            v_quotation.customer_id;

        v_project_site_id :=
            v_quotation.project_site_id;

        v_price_book_id :=
            v_quotation.price_book_id;

        v_quotation_segment :=
            v_quotation.quotation_segment;

        v_quotation_source :=
            v_quotation.quotation_source;

        v_issue_date :=
            v_quotation.issue_date;

        v_valid_until :=
            v_quotation.valid_until;

        v_notes :=
            v_quotation.notes;

        v_internal_notes :=
            v_quotation.internal_notes;

        v_subtotal_amount :=
            v_quotation.subtotal_amount;

        v_discount_amount :=
            v_quotation.discount_amount;

        v_tax_amount :=
            v_quotation.tax_amount;

        v_total_amount :=
            v_quotation.total_amount;

    else
        -- ----------------------------------------------------
        -- Later revision: copy the current Sent revision.
        -- ----------------------------------------------------

        if v_quotation.current_revision_id is null then
            raise exception
                'Revised quotation does not have a current revision.';
        end if;

        select qr.*
        into v_current_revision
        from public.quotation_revisions qr
        where qr.revision_id =
              v_quotation.current_revision_id
          and qr.quotation_id =
              v_quotation.quotation_id
          and qr.is_active = true
          and qr.is_deleted = false
        for update;

        if not found then
            raise exception
                'Current revision was not found or does not belong to this quotation.';
        end if;

        if v_current_revision.revision_status <> 'Sent' then
            raise exception
                'A new revision can only be created from the current Sent revision. Current revision status: %.',
                v_current_revision.revision_status;
        end if;

        v_source_revision_id :=
            v_current_revision.revision_id;

        v_customer_id :=
            v_current_revision.customer_id;

        v_project_site_id :=
            v_current_revision.project_site_id;

        v_price_book_id :=
            v_current_revision.price_book_id;

        v_quotation_segment :=
            v_current_revision.quotation_segment;

        v_quotation_source :=
            v_current_revision.quotation_source;

        v_issue_date :=
            v_current_revision.issue_date;

        v_valid_until :=
            v_current_revision.valid_until;

        v_notes :=
            v_current_revision.notes;

        v_internal_notes :=
            v_current_revision.internal_notes;

        v_subtotal_amount :=
            v_current_revision.subtotal_amount;

        v_discount_amount :=
            v_current_revision.discount_amount;

        v_tax_amount :=
            v_current_revision.tax_amount;

        v_total_amount :=
            v_current_revision.total_amount;
    end if;


    -- ========================================================
    -- 5. CALCULATE NEXT REVISION NUMBER
    --
    -- Parent quotation row is already locked, preventing two
    -- sessions from generating the next number concurrently.
    -- ========================================================

    select
        coalesce(max(qr.revision_no), 0) + 1
    into v_new_revision_no
    from public.quotation_revisions qr
    where qr.quotation_id = p_quotation_id;


    -- ========================================================
    -- 6. CREATE REVISION HEADER
    -- ========================================================

    insert into public.quotation_revisions (
        quotation_id,
        revision_no,
        revision_reason,
        revision_notes,

        subtotal_amount,
        discount_amount,
        tax_amount,
        total_amount,

        revision_status,
        issued_at,
        issued_by,

        customer_id,
        project_site_id,
        price_book_id,

        quotation_segment,
        quotation_source,
        issue_date,
        valid_until,

        notes,
        internal_notes,

        created_by,
        updated_by
    )
    values (
        p_quotation_id,
        v_new_revision_no,
        nullif(btrim(p_revision_reason), ''),
        nullif(btrim(p_revision_notes), ''),

        v_subtotal_amount,
        v_discount_amount,
        v_tax_amount,
        v_total_amount,

        'Draft',
        null,
        null,

        v_customer_id,
        v_project_site_id,
        v_price_book_id,

        v_quotation_segment,
        v_quotation_source,
        v_issue_date,
        v_valid_until,

        v_notes,
        v_internal_notes,

        v_user_id,
        v_user_id
    )
    returning revision_id
    into v_new_revision_id;


    -- ========================================================
    -- 7. COPY SOURCE LINES
    -- ========================================================

    if v_source_revision_id is null then
        -- ----------------------------------------------------
        -- Copy from base quotation lines.
        -- ----------------------------------------------------

        insert into public.quotation_revision_lines (
            revision_id,
            quotation_line_id,
            line_no,

            product_id,
            project_area_id,
            description,
            unit_of_measure,

            quantity,
            unit_price,
            discount_percent,
            discount_amount,
            tax_rate,
            tax_amount,
            line_total,

            cost_price,
            margin_amount,
            margin_percent,

            notes,

            sales_uom_code,
            base_uom_code,
            conversion_factor,
            base_quantity,
            allow_fractional_quantity,

            is_optional,
            is_deleted,

            created_by,
            updated_by
        )
        select
            v_new_revision_id,
            ql.quotation_line_id,
            ql.line_no,

            ql.product_id,
            ql.project_area_id,
            ql.description,
            ql.unit_of_measure,

            ql.quantity,
            ql.unit_price,
            ql.discount_percent,
            ql.discount_amount,
            ql.tax_rate,
            ql.tax_amount,
            ql.line_total,

            ql.cost_price,
            ql.margin_amount,
            ql.margin_percent,

            ql.notes,

            ql.sales_uom_code,
            ql.base_uom_code,
            ql.conversion_factor,
            ql.base_quantity,
            ql.allow_fractional_quantity,

            ql.is_optional,
            false,

            v_user_id,
            v_user_id

        from public.quotation_lines ql

        where ql.quotation_id = p_quotation_id
          and ql.is_deleted = false

        order by ql.line_no;

    else
        -- ----------------------------------------------------
        -- Copy from the current revision lines.
        -- quotation_line_id is retained where the line
        -- originated from a base quotation line.
        -- ----------------------------------------------------

        insert into public.quotation_revision_lines (
            revision_id,
            quotation_line_id,
            line_no,

            product_id,
            project_area_id,
            description,
            unit_of_measure,

            quantity,
            unit_price,
            discount_percent,
            discount_amount,
            tax_rate,
            tax_amount,
            line_total,

            cost_price,
            margin_amount,
            margin_percent,

            notes,

            sales_uom_code,
            base_uom_code,
            conversion_factor,
            base_quantity,
            allow_fractional_quantity,

            is_optional,
            is_deleted,

            created_by,
            updated_by
        )
        select
            v_new_revision_id,
            qrl.quotation_line_id,
            qrl.line_no,

            qrl.product_id,
            qrl.project_area_id,
            qrl.description,
            qrl.unit_of_measure,

            qrl.quantity,
            qrl.unit_price,
            qrl.discount_percent,
            qrl.discount_amount,
            qrl.tax_rate,
            qrl.tax_amount,
            qrl.line_total,

            qrl.cost_price,
            qrl.margin_amount,
            qrl.margin_percent,

            qrl.notes,

            qrl.sales_uom_code,
            qrl.base_uom_code,
            qrl.conversion_factor,
            qrl.base_quantity,
            qrl.allow_fractional_quantity,

            qrl.is_optional,
            false,

            v_user_id,
            v_user_id

        from public.quotation_revision_lines qrl

        where qrl.revision_id = v_source_revision_id
          and qrl.is_deleted = false

        order by qrl.line_no;
    end if;


    get diagnostics
        v_line_count = row_count;

    if v_line_count = 0 then
        raise exception
            'The source quotation or revision does not contain any active lines.';
    end if;


    -- ========================================================
    -- 8. UPDATE QUOTATION REVISION POINTER
    --
    -- Quotation status remains Sent or Revised.
    -- It changes to Revised only when the revision is sent.
    -- ========================================================

    update public.quotations
    set
        current_revision_id =
            v_new_revision_id,

        revision_no =
            v_new_revision_no,

        updated_by =
            v_user_id

    where quotation_id =
          p_quotation_id;


    -- Validate deferred revision pointer immediately.

    set constraints all immediate;


    -- ========================================================
    -- 9. RETURN RESULT
    -- ========================================================

    return jsonb_build_object(
        'quotation_id',
            p_quotation_id,

        'quotation_no',
            v_quotation.quotation_no,

        'revision_id',
            v_new_revision_id,

        'revision_no',
            v_new_revision_no,

        'revision_status',
            'Draft',

        'source_revision_id',
            v_source_revision_id,

        'line_count',
            v_line_count,

        'subtotal_amount',
            v_subtotal_amount,

        'discount_amount',
            v_discount_amount,

        'tax_amount',
            v_tax_amount,

        'total_amount',
            v_total_amount
    );
end;
$$;


ALTER FUNCTION "public"."create_quotation_revision_atomic"("p_quotation_id" "uuid", "p_revision_reason" "text", "p_revision_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_retention_release_invoice_atomic"("p_site_id" "uuid", "p_release_amount" numeric, "p_notes" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    v_customer_id uuid;
    v_project_id uuid;
    v_available numeric(18,2);
    v_invoice_id uuid;
    v_payload jsonb;
    v_lines jsonb;
begin
    perform public.assert_invoice_permission('invoices.release_retention');
    perform public.assert_invoice_permission('retention.release');

    if p_release_amount is null or p_release_amount <= 0 then
        raise exception 'Retention release amount must be greater than zero.';
    end if;

    select
        p.customer_id,
        ps.project_id
    into
        v_customer_id,
        v_project_id
    from public.project_sites ps
    join public.projects p
        on p.project_id = ps.project_id
    where ps.site_id = p_site_id
      and ps.is_deleted = false
      and ps.is_active = true
      and p.is_deleted = false
      and p.is_active = true;

    if v_customer_id is null then
        raise exception 'Project Site is missing, inactive, or deleted.';
    end if;

    select coalesce(sum(
        case ledger_entry_type
            when 'Retained' then amount
            when 'Adjustment Increase' then amount
            when 'Released' then -amount
            when 'Adjustment Decrease' then -amount
            when 'Reversal' then -amount
            else 0
        end
    ), 0)
    into v_available
    from public.retention_ledger
    where site_id = p_site_id;

    if p_release_amount > v_available then
        raise exception
            'Retention release amount exceeds available retained balance (%).',
            v_available;
    end if;

    v_payload := jsonb_build_object(
        'customer_id', v_customer_id,
        'project_id', v_project_id,
        'project_site_id', p_site_id,
        'invoice_type', 'Standard',
        'invoice_date', current_date,
        'due_date', public.invoice_due_date_from_terms(v_customer_id, current_date),
        'notes', p_notes
    );

    v_lines := jsonb_build_array(
        jsonb_build_object(
            'line_no', 1,
            'description', 'Retention Release',
            'quantity', 1,
            'unit_price', p_release_amount,
            'tax_rate', 0
        )
    );

    v_invoice_id := public._create_invoice_atomic_core(
        v_payload,
        v_lines,
        '[]'::jsonb
    );

    update public.customer_invoices
    set
        invoice_type = 'Retention Release',
        retention_release_amount = p_release_amount,
        updated_by = auth.uid()
    where customer_invoice_id = v_invoice_id;

    insert into public.retention_ledger (
        site_id,
        customer_invoice_id,
        ledger_entry_type,
        amount,
        entry_date,
        description,
        reference_no,
        created_by
    )
    values (
        p_site_id,
        v_invoice_id,
        'Released',
        p_release_amount,
        current_date,
        'Retention release invoice created',
        (
            select invoice_no
            from public.customer_invoices
            where customer_invoice_id = v_invoice_id
        ),
        auth.uid()
    );

    return v_invoice_id;
end;
$$;


ALTER FUNCTION "public"."create_retention_release_invoice_atomic"("p_site_id" "uuid", "p_release_amount" numeric, "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_site_goods_receiving_atomic"("p_supplier_delivery_id" "uuid", "p_site_id" "uuid", "p_stock_location_id" "uuid", "p_items" "jsonb", "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
    v_result jsonb;
    v_receipt_id uuid;
    v_delivery public.supplier_deliveries%rowtype;
    v_receipt public.supplier_delivery_receipts%rowtype;

    v_purchase_order_no text;
    v_supplier_code text;
    v_supplier_name text;
    v_project_no text;
    v_project_name text;
    v_site_code text;
    v_site_name text;
    v_stock_location_code text;
    v_stock_location_name text;
    v_employee_code text;
    v_employee_name text;

    v_updated_count integer;
begin
    if auth.uid() is null then
        raise exception
            'Authentication is required to receive supplier deliveries.';
    end if;

    if not public.has_permission('site_goods_receiving.receive') then
        raise exception
            'You do not have permission to receive goods at a project site.';
    end if;

    v_result := public.create_supplier_delivery_receipt(
        p_supplier_delivery_id := p_supplier_delivery_id,
        p_site_id := p_site_id,
        p_stock_location_id := p_stock_location_id,
        p_items := p_items,
        p_notes := p_notes
    );

    v_receipt_id := nullif(
        trim(v_result ->> 'supplier_delivery_receipt_id'),
        ''
    )::uuid;

    if v_receipt_id is null then
        raise exception
            'The receiving engine did not return a receipt ID.';
    end if;

    select *
    into v_delivery
    from public.supplier_deliveries
    where supplier_delivery_id = p_supplier_delivery_id
      and is_deleted = false;

    if not found then
        raise exception
            'Supplier delivery was not found after receiving.';
    end if;

    select *
    into v_receipt
    from public.supplier_delivery_receipts
    where supplier_delivery_receipt_id = v_receipt_id
      and is_deleted = false;

    if not found then
        raise exception
            'Supplier delivery receipt was not found after receiving.';
    end if;

    select purchase_order_no
    into v_purchase_order_no
    from public.purchase_orders
    where purchase_order_id = v_delivery.purchase_order_id
      and is_deleted = false;

    select supplier_code, supplier_name
    into v_supplier_code, v_supplier_name
    from public.suppliers
    where supplier_id = v_delivery.supplier_id
      and is_deleted = false;

    select project_no, project_name
    into v_project_no, v_project_name
    from public.projects
    where project_id = v_receipt.project_id
      and is_deleted = false;

    select site_code, site_name
    into v_site_code, v_site_name
    from public.project_sites
    where site_id = v_receipt.site_id
      and is_deleted = false;

    select location_code, location_name
    into v_stock_location_code, v_stock_location_name
    from public.stock_locations
    where stock_location_id = p_stock_location_id
      and is_deleted = false;

    select
        employee.employee_code,
        coalesce(
            nullif(trim(employee.display_name), ''),
            nullif(
                trim(
                    coalesce(employee.first_name, '')
                    || ' '
                    || coalesce(employee.last_name, '')
                ),
                ''
            ),
            employee.employee_code,
            'Unknown employee'
        )
    into
        v_employee_code,
        v_employee_name
    from public.employees employee
    where employee.employee_id = v_receipt.received_by_employee_id
      and employee.is_deleted = false;

    update public.notification_events event
    set payload = coalesce(event.payload, '{}'::jsonb)
        || jsonb_build_object(
            'delivery_no', v_delivery.delivery_no,
            'supplier_delivery_note_no',
                v_delivery.supplier_delivery_note_no,
            'purchase_order_no', v_purchase_order_no,
            'supplier_code', v_supplier_code,
            'supplier_name', v_supplier_name,
            'project_no', v_project_no,
            'project_name', v_project_name,
            'site_code', v_site_code,
            'site_name', v_site_name,
            'stock_location_code', v_stock_location_code,
            'stock_location_name', v_stock_location_name,
            'received_by_employee_code', v_employee_code,
            'received_by_employee_name', v_employee_name,
            'received_at', v_receipt.received_at
        )
    where event.event_key = 'site_goods_receiving:' || v_receipt_id::text
      and event.source_table = 'supplier_delivery_receipts'
      and event.source_id = v_receipt_id;

    get diagnostics v_updated_count = row_count;

    if v_updated_count <> 1 then
        raise exception
            'Expected one queued site receiving notification event, but updated %.',
            v_updated_count;
    end if;

    return v_result || jsonb_build_object(
        'delivery_no', v_delivery.delivery_no,
        'purchase_order_no', v_purchase_order_no,
        'supplier_name', v_supplier_name,
        'project_name', v_project_name,
        'site_name', v_site_name,
        'stock_location_name', v_stock_location_name,
        'received_by_employee_name', v_employee_name,
        'received_at', v_receipt.received_at
    );
end;
$$;


ALTER FUNCTION "public"."create_site_goods_receiving_atomic"("p_supplier_delivery_id" "uuid", "p_site_id" "uuid", "p_stock_location_id" "uuid", "p_items" "jsonb", "p_notes" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_site_goods_receiving_atomic"("p_supplier_delivery_id" "uuid", "p_site_id" "uuid", "p_stock_location_id" "uuid", "p_items" "jsonb", "p_notes" "text") IS 'Permission-checked supplier receiving gateway that enriches the queued Telegram payload with readable delivery, PO, supplier, project, site, stock-location and employee values.';



CREATE OR REPLACE FUNCTION "public"."create_stock_issue_atomic"("p_header" "jsonb", "p_lines" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
    v_request public.stock_requests%rowtype;
    v_issue_id uuid;
    v_issue_line_id uuid;
    v_line jsonb;
    v_allocation jsonb;
    v_request_item public.stock_request_items%rowtype;
    v_product public.products%rowtype;
    v_lot public.stock_lots%rowtype;

    v_line_no integer := 0;
    v_issue_quantity numeric(18,6);
    v_issue_base_quantity numeric(18,6);
    v_conversion_factor numeric(18,6);
    v_issue_uom_code text;
    v_issued_product_id uuid;
    v_allocated_total numeric(18,6);
begin
    if not public.has_permission('stock_issues.create') then
        raise exception 'Permission denied: stock_issues.create.';
    end if;

    if p_header is null or jsonb_typeof(p_header) <> 'object' then
        raise exception 'Stock Issue header is required.';
    end if;

    if p_lines is null
       or jsonb_typeof(p_lines) <> 'array'
       or jsonb_array_length(p_lines) = 0 then
        raise exception 'At least one Stock Issue line is required.';
    end if;

    select *
    into v_request
    from public.stock_requests
    where stock_request_id =
          nullif(p_header->>'stock_request_id', '')::uuid
      and is_deleted = false
    for update;

    if not found then
        raise exception 'Source Stock Request was not found.';
    end if;

    if v_request.request_status not in (
        'Approved',
        'Partially Reserved',
        'Reserved',
        'Partially Issued',
        'Partially Approved'
    ) then
        raise exception
            'Stock Request status % does not allow Stock Issue creation.',
            v_request.request_status;
    end if;

    insert into public.stock_issues (
        stock_issue_no,
        stock_request_id,
        project_id,
        site_id,
        area_id,
        work_order_id,
        from_stock_location_id,
        to_stock_location_id,
        delivery_method,
        issue_status,
        priority,
        issue_date,
        required_date,
        recipient_auth_user_id,
        recipient_employee_id,
        recipient_name,
        vehicle_reference,
        dispatch_reference,
        notes,
        is_deleted
    )
    values (
        null,
        v_request.stock_request_id,
        v_request.project_id,
        v_request.site_id,
        v_request.area_id,
        v_request.work_order_id,
        nullif(p_header->>'from_stock_location_id', '')::uuid,
        nullif(p_header->>'to_stock_location_id', '')::uuid,
        coalesce(nullif(p_header->>'delivery_method', ''), 'SiteDelivery'),
        'Draft',
        coalesce(nullif(p_header->>'priority', ''), 'Normal'),
        coalesce(
            nullif(p_header->>'issue_date', '')::date,
            current_date
        ),
        nullif(p_header->>'required_date', '')::date,
        nullif(p_header->>'recipient_auth_user_id', '')::uuid,
        nullif(p_header->>'recipient_employee_id', '')::uuid,
        nullif(btrim(p_header->>'recipient_name'), ''),
        nullif(btrim(p_header->>'vehicle_reference'), ''),
        nullif(btrim(p_header->>'dispatch_reference'), ''),
        nullif(btrim(p_header->>'notes'), ''),
        false
    )
    returning stock_issue_id
    into v_issue_id;

    for v_line in
        select value
        from jsonb_array_elements(p_lines)
    loop
        v_line_no := v_line_no + 1;

        select *
        into v_request_item
        from public.stock_request_items
        where stock_request_item_id =
              nullif(v_line->>'stock_request_item_id', '')::uuid
          and stock_request_id = v_request.stock_request_id
          and is_deleted = false
        for update;

        if not found then
            raise exception
                'Stock Request item for line % was not found.',
                v_line_no;
        end if;

        if coalesce(v_request_item.fulfilment_method, 'Issue') <> 'Issue' then
            raise exception
                'Stock Request item line % is not routed for Issue.',
                v_line_no;
        end if;

        if coalesce(v_request_item.approved_base_quantity, 0) <= 0 then
            raise exception
                'Stock Request item line % has no approved quantity.',
                v_line_no;
        end if;

        v_issued_product_id :=
            coalesce(
                nullif(v_line->>'issued_product_id', '')::uuid,
                v_request_item.product_id
            );

        select *
        into v_product
        from public.products
        where product_id = v_issued_product_id
          and is_deleted = false
          and is_active = true;

        if not found then
            raise exception
                'Issued product for line % was not found or is inactive.',
                v_line_no;
        end if;

        if v_product.product_type not in ('Material', 'Consumable') then
            raise exception
                'Stock Issue line % must use a Material or Consumable product.',
                v_line_no;
        end if;

        v_issue_uom_code :=
            coalesce(
                nullif(v_line->>'issue_uom_code', ''),
                v_request_item.request_uom_code,
                v_request_item.unit_of_measure,
                v_product.base_uom_code
            );

        if v_issue_uom_code = v_product.base_uom_code then
            v_conversion_factor := 1;
        else
            select conversion_factor
            into v_conversion_factor
            from public.product_uom_conversions
            where product_id = v_issued_product_id
              and from_uom_code = v_issue_uom_code
              and to_uom_code = v_product.base_uom_code
              and is_active = true
              and is_deleted = false
            order by sort_order, created_at
            limit 1;

            if not found then
                raise exception
                    'No active UOM conversion exists for Stock Issue line %.',
                    v_line_no;
            end if;
        end if;

        v_issue_quantity :=
            nullif(v_line->>'issue_quantity', '')::numeric;

        if v_issue_quantity is null or v_issue_quantity <= 0 then
            raise exception
                'Issue quantity for line % must be greater than zero.',
                v_line_no;
        end if;

        v_issue_base_quantity :=
            round(v_issue_quantity * v_conversion_factor, 6);

        if v_issue_base_quantity >
           v_request_item.approved_base_quantity then
            raise exception
                'Issue quantity for line % exceeds the approved quantity.',
                v_line_no;
        end if;

        if v_issued_product_id <> v_request_item.product_id
           and nullif(btrim(v_line->>'substitution_reason'), '') is null then
            raise exception
                'Substitution reason is required for line %.',
                v_line_no;
        end if;

        insert into public.stock_issue_lines (
            stock_issue_id,
            stock_request_item_id,
            line_no,
            requested_product_id,
            issued_product_id,
            description,
            issue_uom_code,
            base_uom_code,
            conversion_factor_to_base,
            allow_fractional_quantity,
            approved_quantity,
            approved_base_quantity,
            issue_quantity,
            issue_base_quantity,
            line_status,
            substitution_reason,
            preparation_notes,
            issue_notes,
            is_deleted
        )
        values (
            v_issue_id,
            v_request_item.stock_request_item_id,
            v_line_no,
            v_request_item.product_id,
            v_issued_product_id,
            coalesce(
                nullif(btrim(v_line->>'description'), ''),
                v_request_item.description,
                v_product.product_name
            ),
            v_issue_uom_code,
            v_product.base_uom_code,
            v_conversion_factor,
            coalesce(v_request_item.allow_fractional_quantity, true),
            coalesce(
                v_request_item.approved_quantity,
                v_issue_quantity
            ),
            v_request_item.approved_base_quantity,
            v_issue_quantity,
            v_issue_base_quantity,
            'Draft',
            nullif(btrim(v_line->>'substitution_reason'), ''),
            nullif(btrim(v_line->>'preparation_notes'), ''),
            nullif(btrim(v_line->>'issue_notes'), ''),
            false
        )
        returning stock_issue_line_id
        into v_issue_line_id;

        if not (v_line ? 'allocations')
           or jsonb_typeof(v_line->'allocations') <> 'array'
           or jsonb_array_length(v_line->'allocations') = 0 then
            raise exception
                'At least one Stock Lot allocation is required for line %.',
                v_line_no;
        end if;

        v_allocated_total := 0;

        for v_allocation in
            select value
            from jsonb_array_elements(v_line->'allocations')
        loop
            select *
            into v_lot
            from public.stock_lots
            where stock_lot_id =
                  nullif(v_allocation->>'stock_lot_id', '')::uuid
              and is_deleted = false
              and is_active = true
            for update;

            if not found then
                raise exception
                    'Active Stock Lot for line % was not found.',
                    v_line_no;
            end if;

            if v_lot.product_id <> v_issued_product_id then
                raise exception
                    'Stock Lot product does not match line % issued product.',
                    v_line_no;
            end if;

            if v_lot.stock_location_id <>
               nullif(p_header->>'from_stock_location_id', '')::uuid then
                raise exception
                    'Stock Lot for line % is not in the selected source location.',
                    v_line_no;
            end if;

            if v_lot.base_uom_code <> v_product.base_uom_code then
                raise exception
                    'Stock Lot Base UOM does not match line %.',
                    v_line_no;
            end if;

            if nullif(
                v_allocation->>'allocated_base_quantity',
                ''
            )::numeric <= 0 then
                raise exception
                    'Allocation quantity for line % must be greater than zero.',
                    v_line_no;
            end if;

            v_allocated_total :=
                v_allocated_total
                + nullif(
                    v_allocation->>'allocated_base_quantity',
                    ''
                  )::numeric;

            insert into public.stock_issue_allocations (
                stock_issue_line_id,
                stock_lot_id,
                allocated_base_quantity,
                issued_base_quantity,
                allocation_status,
                notes,
                is_deleted
            )
            values (
                v_issue_line_id,
                v_lot.stock_lot_id,
                nullif(
                    v_allocation->>'allocated_base_quantity',
                    ''
                )::numeric,
                0,
                'Allocated',
                nullif(btrim(v_allocation->>'notes'), ''),
                false
            );
        end loop;

        if round(v_allocated_total, 6) <>
           round(v_issue_base_quantity, 6) then
            raise exception
                'Allocation total for line % must equal its Issue Base Quantity.',
                v_line_no;
        end if;
    end loop;

    return v_issue_id;
end;
$$;


ALTER FUNCTION "public"."create_stock_issue_atomic"("p_header" "jsonb", "p_lines" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_stock_issue_receipt_draft"("p_stock_issue_id" "uuid", "p_received_by_auth_user_id" "uuid" DEFAULT NULL::"uuid", "p_received_by_employee_id" "uuid" DEFAULT NULL::"uuid", "p_received_by_name" "text" DEFAULT NULL::"text", "p_receipt_notes" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
    v_issue public.stock_issues%rowtype;
    v_receipt_id uuid;
    v_receipt_no integer;
begin
    if not public.has_permission('stock_issues.confirm_receipt') then
        raise exception
            'Permission denied: stock_issues.confirm_receipt.';
    end if;

    select *
    into v_issue
    from public.stock_issues
    where stock_issue_id = p_stock_issue_id
      and is_deleted = false
    for update;

    if not found then
        raise exception 'Stock Issue was not found.';
    end if;

    if v_issue.issue_status not in (
        'Delivered',
        'PartiallyReceived'
    ) then
        raise exception
            'A receipt can only be created for a Delivered or Partially Received Stock Issue.';
    end if;

    if p_received_by_auth_user_id is null
       and p_received_by_employee_id is null
       and nullif(btrim(p_received_by_name), '') is null then
        raise exception
            'A receiving person is required.';
    end if;

    if exists (
        select 1
        from public.stock_issue_receipts
        where stock_issue_id = p_stock_issue_id
          and receipt_status = 'Draft'
          and is_deleted = false
    ) then
        raise exception
            'This Stock Issue already has an active Draft receipt.';
    end if;

    select coalesce(max(receipt_no), 0) + 1
    into v_receipt_no
    from public.stock_issue_receipts
    where stock_issue_id = p_stock_issue_id
      and is_deleted = false;

    insert into public.stock_issue_receipts (
        stock_issue_id,
        receipt_no,
        receipt_status,
        received_at,
        received_by_auth_user_id,
        received_by_employee_id,
        received_by_name,
        receipt_notes,
        is_active,
        is_deleted
    )
    values (
        p_stock_issue_id,
        v_receipt_no,
        'Draft',
        null,
        p_received_by_auth_user_id,
        p_received_by_employee_id,
        nullif(btrim(p_received_by_name), ''),
        nullif(btrim(p_receipt_notes), ''),
        true,
        false
    )
    returning stock_issue_receipt_id
    into v_receipt_id;

    return v_receipt_id;
end;
$$;


ALTER FUNCTION "public"."create_stock_issue_receipt_draft"("p_stock_issue_id" "uuid", "p_received_by_auth_user_id" "uuid", "p_received_by_employee_id" "uuid", "p_received_by_name" "text", "p_receipt_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_supplier_delivery_from_purchase_order_atomic"("p_purchase_order_id" "uuid", "p_delivery_date" "date", "p_supplier_delivery_note_no" "text" DEFAULT NULL::"text", "p_notes" "text" DEFAULT NULL::"text", "p_items" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
    v_auth_user_id uuid;
    v_purchase_order public.purchase_orders%rowtype;
    v_delivery_id uuid;
    v_delivery_no text;
    v_item_json jsonb;
    v_po_line public.purchase_order_lines%rowtype;
    v_received_quantity numeric(18,6);
    v_existing_delivery_quantity numeric(18,6);
    v_outstanding_quantity numeric(18,6);
    v_received_uom_code text;
    v_conversion_factor numeric(18,6);
    v_payload_count integer;
    v_distinct_line_count integer;
    v_created_item_count integer := 0;
begin
    v_auth_user_id := auth.uid();

    if v_auth_user_id is null then
        raise exception 'Authentication is required to create a supplier delivery.';
    end if;

    if not public.has_permission('supplier_deliveries.create') then
        raise exception 'You do not have permission to create supplier deliveries.';
    end if;

    if p_purchase_order_id is null then
        raise exception 'Purchase order is required.';
    end if;

    if p_delivery_date is null then
        raise exception 'Delivery date is required.';
    end if;

    if p_items is null
       or jsonb_typeof(p_items) <> 'array'
       or jsonb_array_length(p_items) = 0 then
        raise exception 'At least one purchase order line must be selected.';
    end if;

    select
        count(*),
        count(distinct nullif(trim(item.value ->> 'purchase_order_line_id'), ''))
    into
        v_payload_count,
        v_distinct_line_count
    from jsonb_array_elements(p_items) item(value);

    if v_payload_count <> v_distinct_line_count then
        raise exception 'Duplicate or missing purchase order line IDs were found.';
    end if;

    select *
    into v_purchase_order
    from public.purchase_orders
    where purchase_order_id = p_purchase_order_id
      and is_deleted = false
    for update;

    if not found then
        raise exception 'Purchase order not found.';
    end if;

    if v_purchase_order.order_status not in (
        'Confirmed',
        'Partially Delivered'
    ) then
        raise exception
            'Supplier Delivery can be created only from a Confirmed or Partially Delivered Purchase Order.';
    end if;

    insert into public.supplier_deliveries (
        delivery_no,
        purchase_order_id,
        supplier_id,
        project_id,
        site_id,
        delivery_date,
        received_by,
        delivery_status,
        supplier_delivery_note_no,
        notes,
        telegram_notified,
        is_deleted,
        created_by,
        updated_by
    )
    values (
        null,
        v_purchase_order.purchase_order_id,
        v_purchase_order.supplier_id,
        v_purchase_order.project_id,
        v_purchase_order.site_id,
        p_delivery_date,
        null,
        'Pending',
        nullif(trim(p_supplier_delivery_note_no), ''),
        nullif(trim(p_notes), ''),
        false,
        false,
        v_auth_user_id,
        v_auth_user_id
    )
    returning supplier_delivery_id, delivery_no
    into v_delivery_id, v_delivery_no;

    for v_item_json in
        select item.value
        from jsonb_array_elements(p_items) item(value)
    loop
        begin
            select *
            into v_po_line
            from public.purchase_order_lines
            where purchase_order_line_id =
                  (v_item_json ->> 'purchase_order_line_id')::uuid
              and purchase_order_id = p_purchase_order_id
              and is_deleted = false
            for update;
        exception
            when invalid_text_representation then
                raise exception 'Invalid purchase order line ID.';
        end;

        if not found then
            raise exception 'Selected purchase order line was not found.';
        end if;

        begin
            v_received_quantity :=
                (v_item_json ->> 'received_quantity')::numeric;
        exception
            when invalid_text_representation then
                raise exception 'Invalid delivery quantity on PO line %.', v_po_line.line_no;
        end;

        if v_received_quantity is null or v_received_quantity <= 0 then
            raise exception 'Delivery quantity must be greater than zero on PO line %.', v_po_line.line_no;
        end if;

        select coalesce(sum(delivery_item.received_quantity), 0)
        into v_existing_delivery_quantity
        from public.supplier_delivery_items delivery_item
        join public.supplier_deliveries delivery
          on delivery.supplier_delivery_id = delivery_item.supplier_delivery_id
         and delivery.is_deleted = false
         and delivery.delivery_status <> 'Cancelled'
        where delivery_item.purchase_order_line_id = v_po_line.purchase_order_line_id
          and delivery_item.is_deleted = false;

        v_outstanding_quantity := round(
            coalesce(v_po_line.quantity, 0)
            - coalesce(v_existing_delivery_quantity, 0),
            6
        );

        if v_outstanding_quantity <= 0 then
            raise exception 'PO line % has no outstanding quantity.', v_po_line.line_no;
        end if;

        if round(v_received_quantity, 6) > round(v_outstanding_quantity, 6) then
            raise exception
                'Delivery quantity exceeds the outstanding quantity on PO line %. Ordered: %, already placed on deliveries: %, outstanding: %, entering now: %.',
                v_po_line.line_no,
                v_po_line.quantity,
                v_existing_delivery_quantity,
                v_outstanding_quantity,
                v_received_quantity;
        end if;

        v_received_uom_code := coalesce(
            nullif(trim(v_item_json ->> 'received_uom_code'), ''),
            nullif(trim(v_po_line.purchase_uom_code), ''),
            nullif(trim(v_po_line.unit_of_measure), '')
        );

        if v_received_uom_code is null then
            raise exception 'Received UOM is missing on PO line %.', v_po_line.line_no;
        end if;

        v_conversion_factor := coalesce(v_po_line.conversion_factor_to_base, 1);

        if v_conversion_factor <= 0 then
            raise exception 'Invalid UOM conversion factor on PO line %.', v_po_line.line_no;
        end if;

        insert into public.supplier_delivery_items (
            supplier_delivery_id,
            purchase_order_line_id,
            product_id,
            material_supplier_link_id,
            line_no,
            received_quantity,
            received_uom_code,
            conversion_factor_to_base,
            received_base_quantity,
            accepted_quantity,
            damaged_quantity,
            rejected_quantity,
            unit_cost,
            notes,
            is_deleted,
            created_by,
            updated_by,
            project_id,
            site_id,
            area_id,
            stock_request_item_id
        )
        values (
            v_delivery_id,
            v_po_line.purchase_order_line_id,
            v_po_line.product_id,
            v_po_line.material_supplier_link_id,
            v_po_line.line_no,
            round(v_received_quantity, 6),
            v_received_uom_code,
            round(v_conversion_factor, 6),
            0,
            0,
            0,
            0,
            v_po_line.unit_cost,
            nullif(trim(v_item_json ->> 'notes'), ''),
            false,
            v_auth_user_id,
            v_auth_user_id,
            coalesce(v_po_line.project_id, v_purchase_order.project_id),
            coalesce(v_po_line.site_id, v_purchase_order.site_id),
            v_po_line.area_id,
            v_po_line.stock_request_item_id
        );

        v_created_item_count := v_created_item_count + 1;
    end loop;

    return jsonb_build_object(
        'supplier_delivery_id', v_delivery_id,
        'delivery_no', v_delivery_no,
        'purchase_order_id', v_purchase_order.purchase_order_id,
        'purchase_order_no', v_purchase_order.purchase_order_no,
        'supplier_id', v_purchase_order.supplier_id,
        'project_id', v_purchase_order.project_id,
        'site_id', v_purchase_order.site_id,
        'delivery_date', p_delivery_date,
        'delivery_status', 'Pending',
        'created_item_count', v_created_item_count
    );
end;
$$;


ALTER FUNCTION "public"."create_supplier_delivery_from_purchase_order_atomic"("p_purchase_order_id" "uuid", "p_delivery_date" "date", "p_supplier_delivery_note_no" "text", "p_notes" "text", "p_items" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_supplier_delivery_from_purchase_order_atomic"("p_purchase_order_id" "uuid", "p_delivery_date" "date", "p_supplier_delivery_note_no" "text", "p_notes" "text", "p_items" "jsonb") IS 'Creates a Pending supplier delivery header and selected delivery items atomically from purchase order lines. Requires supplier_deliveries.create. Actual goods receiving is performed separately through create_site_goods_receiving_atomic.';



CREATE OR REPLACE FUNCTION "public"."create_supplier_delivery_receipt"("p_supplier_delivery_id" "uuid", "p_site_id" "uuid", "p_stock_location_id" "uuid", "p_items" "jsonb", "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
    v_auth_user_id uuid;
    v_employee_id uuid;

    v_delivery public.supplier_deliveries%rowtype;
    v_site public.project_sites%rowtype;
    v_location public.stock_locations%rowtype;

    v_receipt_id uuid;
    v_receipt_item_id uuid;
    v_claim_id uuid;

    v_item_json jsonb;
    v_delivery_item public.supplier_delivery_items%rowtype;
    v_product public.products%rowtype;

    -- Document/legacy quantities
    v_received_now numeric(18, 6);
    v_accepted_now numeric(18, 6);
    v_damaged_now numeric(18, 6);
    v_rejected_now numeric(18, 6);

    -- Detailed damage in another UOM, normally plank
    v_damage_detail_quantity numeric(18, 6);
    v_damage_detail_uom_code text;
    v_damage_detail_conversion numeric(18, 6);
    v_damage_detail_base_quantity numeric(18, 6);
    v_damage_description text;
    v_replacement_required boolean;

    -- Base quantities
    v_document_conversion numeric(18, 6);
    v_received_base_quantity numeric(18, 6);
    v_document_accepted_base_quantity numeric(18, 6);
    v_usable_accepted_base_quantity numeric(18, 6);

    v_existing_processed numeric(18, 6);
    v_new_processed numeric(18, 6);

    v_base_unit_cost numeric(18, 4);

    v_stock_lot_id uuid;
    v_stock_movement_id uuid;

    v_lot_no text;
    v_expiry_date date;
    v_item_notes text;

    v_delivery_status text;
    v_purchase_order_status text;

    v_all_delivery_items_complete boolean;
    v_any_delivery_item_processed boolean;
    v_all_delivery_items_rejected boolean;

    v_all_po_lines_delivered boolean;
    v_any_po_quantity_delivered boolean;

    v_payload_count integer;
    v_distinct_item_count integer;
    v_processed_item_count integer := 0;
    v_claim_item_count integer := 0;
begin
    -- ========================================================
    -- 1. AUTHENTICATED EMPLOYEE
    -- ========================================================

    v_auth_user_id := auth.uid();

    if v_auth_user_id is null then
        raise exception
            'Authentication is required to receive supplier deliveries.';
    end if;

    select e.employee_id
    into v_employee_id
    from public.employees e
    where e.auth_user_id = v_auth_user_id
      and e.is_active = true
      and e.is_deleted = false
    limit 1;

    if v_employee_id is null then
        raise exception
            'The signed-in account is not linked to an active employee.';
    end if;


    -- ========================================================
    -- 2. PAYLOAD VALIDATION
    -- ========================================================

    if p_supplier_delivery_id is null then
        raise exception 'Supplier delivery is required.';
    end if;

    if p_site_id is null then
        raise exception 'Project site is required.';
    end if;

    if p_stock_location_id is null then
        raise exception 'Stock location is required.';
    end if;

    if p_items is null
       or jsonb_typeof(p_items) <> 'array'
       or jsonb_array_length(p_items) = 0 then
        raise exception
            'At least one supplier delivery item must be selected.';
    end if;

    select
        count(*),
        count(
            distinct nullif(
                trim(item.value ->> 'supplier_delivery_item_id'),
                ''
            )
        )
    into
        v_payload_count,
        v_distinct_item_count
    from jsonb_array_elements(p_items) as item(value);

    if v_payload_count <> v_distinct_item_count then
        raise exception
            'Duplicate or missing supplier delivery item IDs were found.';
    end if;


    -- ========================================================
    -- 3. LOCK DELIVERY
    -- ========================================================

    select *
    into v_delivery
    from public.supplier_deliveries
    where supplier_delivery_id = p_supplier_delivery_id
      and is_deleted = false
    for update;

    if not found then
        raise exception 'Supplier delivery not found.';
    end if;

    if v_delivery.delivery_status in ('Rejected', 'Cancelled') then
        raise exception
            'Supplier delivery status % does not allow receiving.',
            v_delivery.delivery_status;
    end if;


    -- ========================================================
    -- 4. VALIDATE SITE
    -- ========================================================

    select *
    into v_site
    from public.project_sites
    where site_id = p_site_id
      and is_active = true
      and is_deleted = false;

    if not found then
        raise exception 'Active project site not found.';
    end if;


    -- ========================================================
    -- 5. VALIDATE STOCK LOCATION
    -- ========================================================

    select *
    into v_location
    from public.stock_locations
    where stock_location_id = p_stock_location_id
      and is_active = true
      and is_deleted = false;

    if not found then
        raise exception 'Active stock location not found.';
    end if;

    if v_location.site_id is distinct from p_site_id then
        raise exception
            'The selected stock location does not belong to the selected site.';
    end if;

    if v_location.project_id is not null
       and v_location.project_id is distinct from v_site.project_id then
        raise exception
            'The stock location project does not match the selected site project.';
    end if;


    -- ========================================================
    -- 6. CREATE RECEIPT SESSION
    -- ========================================================

    insert into public.supplier_delivery_receipts (
        supplier_delivery_id,
        project_id,
        site_id,
        received_by_employee_id,
        received_at,
        receipt_status,
        notes,
        is_deleted,
        created_by,
        updated_by
    )
    values (
        v_delivery.supplier_delivery_id,
        v_site.project_id,
        v_site.site_id,
        v_employee_id,
        now(),
        'Confirmed',
        nullif(trim(p_notes), ''),
        false,
        v_auth_user_id,
        v_auth_user_id
    )
    returning supplier_delivery_receipt_id
    into v_receipt_id;


    -- ========================================================
    -- 7. PROCESS SELECTED ITEMS
    -- ========================================================

    for v_item_json in
        select item.value
        from jsonb_array_elements(p_items) as item(value)
    loop
        v_receipt_item_id := null;
        v_stock_lot_id := null;
        v_stock_movement_id := null;

        v_damage_detail_quantity := 0;
        v_damage_detail_uom_code := null;
        v_damage_detail_conversion := null;
        v_damage_detail_base_quantity := 0;
        v_damage_description := null;
        v_replacement_required := false;

        -- ====================================================
        -- 7A. FIND AND LOCK DELIVERY ITEM
        -- ====================================================

        if nullif(
            trim(v_item_json ->> 'supplier_delivery_item_id'),
            ''
        ) is null then
            raise exception
                'Supplier delivery item ID is required.';
        end if;

        begin
            select *
            into v_delivery_item
            from public.supplier_delivery_items
            where supplier_delivery_item_id =
                  (
                      v_item_json
                      ->> 'supplier_delivery_item_id'
                  )::uuid
              and supplier_delivery_id = p_supplier_delivery_id
              and is_deleted = false
            for update;
        exception
            when invalid_text_representation then
                raise exception
                    'Invalid supplier delivery item ID.';
        end;

        if not found then
            raise exception
                'Selected supplier delivery item was not found.';
        end if;

        if v_delivery_item.site_id is null then
            raise exception
                'Delivery item line % does not have a destination site.',
                v_delivery_item.line_no;
        end if;

        if v_delivery_item.site_id <> p_site_id then
            raise exception
                'Delivery item line % belongs to another site.',
                v_delivery_item.line_no;
        end if;

        if v_delivery_item.project_id is not null
           and v_delivery_item.project_id <> v_site.project_id then
            raise exception
                'Delivery item line % belongs to another project.',
                v_delivery_item.line_no;
        end if;


        -- ====================================================
        -- 7B. READ DOCUMENT QUANTITIES
        -- ====================================================

        begin
            v_received_now :=
                (v_item_json ->> 'received_quantity')::numeric;

            v_accepted_now :=
                coalesce(
                    nullif(
                        trim(v_item_json ->> 'accepted_quantity'),
                        ''
                    )::numeric,
                    0
                );

            v_damaged_now :=
                coalesce(
                    nullif(
                        trim(v_item_json ->> 'damaged_quantity'),
                        ''
                    )::numeric,
                    0
                );

            v_rejected_now :=
                coalesce(
                    nullif(
                        trim(v_item_json ->> 'rejected_quantity'),
                        ''
                    )::numeric,
                    0
                );

            v_damage_detail_quantity :=
                coalesce(
                    nullif(
                        trim(
                            v_item_json
                            ->> 'damage_detail_quantity'
                        ),
                        ''
                    )::numeric,
                    0
                );
        exception
            when invalid_text_representation then
                raise exception
                    'Invalid quantity on delivery item line %.',
                    v_delivery_item.line_no;
        end;

        if v_received_now is null or v_received_now <= 0 then
            raise exception
                'Received quantity must be greater than zero on line %.',
                v_delivery_item.line_no;
        end if;

        if v_accepted_now < 0
           or v_damaged_now < 0
           or v_rejected_now < 0
           or v_damage_detail_quantity < 0 then
            raise exception
                'Receipt quantities cannot be negative on line %.',
                v_delivery_item.line_no;
        end if;

        if round(
            v_accepted_now
            + v_damaged_now
            + v_rejected_now,
            6
        ) <> round(v_received_now, 6) then
            raise exception
                'Accepted + damaged + rejected must equal received quantity on line %.',
                v_delivery_item.line_no;
        end if;


        -- ====================================================
        -- 7C. PREVENT DOCUMENT OVER-RECEIVING
        -- ====================================================

        v_existing_processed :=
            coalesce(v_delivery_item.accepted_quantity, 0)
            + coalesce(v_delivery_item.damaged_quantity, 0)
            + coalesce(v_delivery_item.rejected_quantity, 0);

        v_new_processed :=
            round(v_existing_processed + v_received_now, 6);

        if v_new_processed >
           round(v_delivery_item.received_quantity, 6) then
            raise exception
                'Receiving quantity exceeds the outstanding quantity on line %. Document quantity: %, already processed: %, receiving now: %.',
                v_delivery_item.line_no,
                v_delivery_item.received_quantity,
                v_existing_processed,
                v_received_now;
        end if;


        -- ====================================================
        -- 7D. PRODUCT AND DOCUMENT UOM
        -- ====================================================

        select *
        into v_product
        from public.products
        where product_id = v_delivery_item.product_id
          and is_active = true
          and is_deleted = false;

        if not found then
            raise exception
                'Active product not found for delivery item line %.',
                v_delivery_item.line_no;
        end if;

        if v_delivery_item.received_uom_code is null
           or trim(v_delivery_item.received_uom_code) = '' then
            raise exception
                'Received UOM is missing on delivery item line %.',
                v_delivery_item.line_no;
        end if;

        if v_product.base_uom_code is null
           or trim(v_product.base_uom_code) = '' then
            raise exception
                'Base UOM is missing for product %.',
                v_product.product_code;
        end if;

        v_document_conversion :=
            v_delivery_item.conversion_factor_to_base;

        if v_document_conversion is null
           or v_document_conversion <= 0 then
            raise exception
                'Invalid conversion factor on delivery item line %.',
                v_delivery_item.line_no;
        end if;

        v_received_base_quantity :=
            round(
                v_received_now * v_document_conversion,
                6
            );

        v_document_accepted_base_quantity :=
            round(
                v_accepted_now * v_document_conversion,
                6
            );


        -- ====================================================
        -- 7E. OPTIONAL DAMAGE DETAIL
        -- ====================================================

        if v_damage_detail_quantity > 0 then
            v_damage_detail_uom_code :=
                nullif(
                    trim(
                        v_item_json
                        ->> 'damage_detail_uom_code'
                    ),
                    ''
                );

            v_damage_description :=
                nullif(
                    trim(
                        v_item_json
                        ->> 'damage_description'
                    ),
                    ''
                );

            v_replacement_required :=
                coalesce(
                    nullif(
                        trim(
                            v_item_json
                            ->> 'replacement_required'
                        ),
                        ''
                    )::boolean,
                    true
                );

            if v_damage_detail_uom_code is null then
                raise exception
                    'Damage detail UOM is required on line %.',
                    v_delivery_item.line_no;
            end if;

            if v_damage_description is null then
                raise exception
                    'Damage description is required on line %.',
                    v_delivery_item.line_no;
            end if;

            select pu.conversion_to_base
            into v_damage_detail_conversion
            from public.product_units pu
            where pu.product_id = v_delivery_item.product_id
              and lower(pu.uom_code) =
                  lower(v_damage_detail_uom_code)
              and pu.is_active = true
              and pu.is_deleted = false
            limit 1;

            if v_damage_detail_conversion is null
               or v_damage_detail_conversion <= 0 then
                raise exception
                    'Product % does not have an active conversion for damage UOM %.',
                    v_product.product_code,
                    v_damage_detail_uom_code;
            end if;

            v_damage_detail_base_quantity :=
                round(
                    v_damage_detail_quantity
                    * v_damage_detail_conversion,
                    6
                );

            if v_damage_detail_base_quantity >
               v_document_accepted_base_quantity then
                raise exception
                    'Damage quantity exceeds the accepted quantity on line %.',
                    v_delivery_item.line_no;
            end if;

            if not v_replacement_required then
                raise exception
                    'Detailed supplier damage must require replacement in the Phase 1 workflow on line %.',
                    v_delivery_item.line_no;
            end if;
        end if;


        -- ====================================================
        -- 7F. USABLE STOCK QUANTITY
        -- ====================================================

        v_usable_accepted_base_quantity :=
            round(
                v_document_accepted_base_quantity
                - v_damage_detail_base_quantity,
                6
            );

        if v_usable_accepted_base_quantity < 0 then
            raise exception
                'Usable stock quantity cannot be negative on line %.',
                v_delivery_item.line_no;
        end if;

        v_item_notes :=
            nullif(trim(v_item_json ->> 'notes'), '');

        begin
            v_expiry_date :=
                nullif(
                    trim(v_item_json ->> 'expiry_date'),
                    ''
                )::date;
        exception
            when invalid_datetime_format then
                raise exception
                    'Invalid expiry date on delivery item line %.',
                    v_delivery_item.line_no;
        end;


        -- ====================================================
        -- 7G. CREATE STOCK FOR USABLE QUANTITY ONLY
        -- ====================================================

        if v_usable_accepted_base_quantity > 0
           and coalesce(v_product.is_stock_item, false) then
            v_lot_no :=
                coalesce(
                    nullif(
                        trim(v_item_json ->> 'lot_no'),
                        ''
                    ),
                    v_delivery.delivery_no
                    || '-R'
                    || upper(
                        substring(v_receipt_id::text, 1, 8)
                    )
                    || '-L'
                    || lpad(
                        v_delivery_item.line_no::text,
                        3,
                        '0'
                    )
                );

            if v_delivery_item.unit_cost is null then
                v_base_unit_cost := null;
            else
                v_base_unit_cost :=
                    round(
                        v_delivery_item.unit_cost
                        / v_document_conversion,
                        4
                    );
            end if;

            insert into public.stock_lots (
                lot_no,
                product_id,
                stock_location_id,
                supplier_id,
                supplier_delivery_item_id,
                base_uom_code,
                received_quantity,
                remaining_quantity,
                reserved_quantity,
                damaged_quantity,
                average_unit_cost,
                received_date,
                expiry_date,
                lot_status,
                notes,
                is_active,
                is_deleted,
                created_by,
                updated_by
            )
            values (
                v_lot_no,
                v_delivery_item.product_id,
                v_location.stock_location_id,
                v_delivery.supplier_id,
                v_delivery_item.supplier_delivery_item_id,
                v_product.base_uom_code,
                v_usable_accepted_base_quantity,
                v_usable_accepted_base_quantity,
                0,
                0,
                v_base_unit_cost,
                current_date,
                v_expiry_date,
                'Available',
                v_item_notes,
                true,
                false,
                v_auth_user_id,
                v_auth_user_id
            )
            returning stock_lot_id
            into v_stock_lot_id;

            insert into public.stock_movements (
                stock_lot_id,
                product_id,
                movement_type,
                movement_date,
                quantity,
                base_uom_code,
                from_location_id,
                to_location_id,
                stock_request_item_id,
                supplier_delivery_item_id,
                reference_no,
                reason,
                notes,
                unit_cost,
                total_cost,
                created_by,
                updated_by,
                is_deleted
            )
            values (
                v_stock_lot_id,
                v_delivery_item.product_id,
                'Receive',
                current_date,
                v_usable_accepted_base_quantity,
                v_product.base_uom_code,
                null,
                v_location.stock_location_id,
                v_delivery_item.stock_request_item_id,
                v_delivery_item.supplier_delivery_item_id,
                v_delivery.delivery_no,
                case
                    when v_damage_detail_quantity > 0
                        then 'Supplier delivery receipt — usable quantity after damage inspection'
                    else 'Supplier delivery receipt'
                end,
                v_item_notes,
                v_base_unit_cost,
                case
                    when v_base_unit_cost is null then null
                    else round(
                        v_usable_accepted_base_quantity
                        * v_base_unit_cost,
                        4
                    )
                end,
                v_auth_user_id,
                v_auth_user_id,
                false
            )
            returning stock_movement_id
            into v_stock_movement_id;
        end if;


        -- ====================================================
        -- 7H. CREATE RECEIPT ITEM
        -- ====================================================

        insert into public.supplier_delivery_receipt_items (
            supplier_delivery_receipt_id,
            supplier_delivery_item_id,

            received_quantity,
            accepted_quantity,
            damaged_quantity,
            rejected_quantity,
            received_uom_code,
            conversion_factor_to_base,
            accepted_base_quantity,

            received_input_quantity,
            received_input_uom_code,
            received_base_quantity,

            accepted_input_quantity,
            accepted_input_uom_code,

            damaged_input_quantity,
            damaged_input_uom_code,
            damaged_base_quantity,

            rejected_input_quantity,
            rejected_input_uom_code,
            rejected_base_quantity,

            replacement_required_quantity,
            replacement_required_uom_code,
            replacement_received_quantity,

            stock_location_id,
            stock_lot_id,
            stock_movement_id,
            notes,
            is_deleted,
            created_by,
            updated_by
        )
        values (
            v_receipt_id,
            v_delivery_item.supplier_delivery_item_id,

            v_received_now,
            v_accepted_now,
            v_damaged_now,
            v_rejected_now,
            v_delivery_item.received_uom_code,
            v_document_conversion,
            v_usable_accepted_base_quantity,

            v_received_now,
            v_delivery_item.received_uom_code,
            v_received_base_quantity,

            v_accepted_now,
            v_delivery_item.received_uom_code,

            case
                when v_damage_detail_quantity > 0
                    then v_damage_detail_quantity
                else v_damaged_now
            end,
            case
                when v_damage_detail_quantity > 0
                    then v_damage_detail_uom_code
                else v_delivery_item.received_uom_code
            end,
            case
                when v_damage_detail_quantity > 0
                    then v_damage_detail_base_quantity
                else round(
                    v_damaged_now * v_document_conversion,
                    6
                )
            end,

            v_rejected_now,
            v_delivery_item.received_uom_code,
            round(
                v_rejected_now * v_document_conversion,
                6
            ),

            case
                when v_damage_detail_quantity > 0
                    then v_damage_detail_quantity
                else null
            end,
            case
                when v_damage_detail_quantity > 0
                    then v_damage_detail_uom_code
                else null
            end,
            0,

            case
                when v_usable_accepted_base_quantity > 0
                     and coalesce(v_product.is_stock_item, false)
                    then v_location.stock_location_id
                else null
            end,
            v_stock_lot_id,
            v_stock_movement_id,
            v_item_notes,
            false,
            v_auth_user_id,
            v_auth_user_id
        )
        returning supplier_delivery_receipt_item_id
        into v_receipt_item_id;


        -- ====================================================
        -- 7I. CREATE REPLACEMENT CLAIM WHEN DAMAGE EXISTS
        -- ====================================================

        if v_damage_detail_quantity > 0 then
            if v_claim_id is null then
                insert into public.supplier_replacement_claims (
                    supplier_id,
                    purchase_order_id,
                    supplier_delivery_id,
                    site_id,
                    claim_status,
                    opened_at,
                    opened_by_employee_id,
                    payment_hold_required,
                    payment_hold_note,
                    notes,
                    is_active,
                    is_deleted,
                    created_by,
                    updated_by
                )
                values (
                    v_delivery.supplier_id,
                    v_delivery.purchase_order_id,
                    v_delivery.supplier_delivery_id,
                    v_site.site_id,
                    'Replacement Pending',
                    now(),
                    v_employee_id,
                    true,
                    'Payment hold: damaged supplier goods are awaiting replacement.',
                    nullif(trim(p_notes), ''),
                    true,
                    false,
                    v_auth_user_id,
                    v_auth_user_id
                )
                returning supplier_replacement_claim_id
                into v_claim_id;
            end if;

            insert into public.supplier_replacement_claim_items (
                supplier_replacement_claim_id,
                supplier_delivery_receipt_item_id,
                supplier_delivery_item_id,
                product_id,
                replacement_uom_code,
                replacement_required_quantity,
                replacement_received_quantity,
                replacement_required_base_quantity,
                replacement_received_base_quantity,
                item_status,
                damage_description,
                notes,
                is_deleted,
                created_by,
                updated_by
            )
            values (
                v_claim_id,
                v_receipt_item_id,
                v_delivery_item.supplier_delivery_item_id,
                v_delivery_item.product_id,
                v_damage_detail_uom_code,
                v_damage_detail_quantity,
                0,
                v_damage_detail_base_quantity,
                0,
                'Pending',
                v_damage_description,
                v_item_notes,
                false,
                v_auth_user_id,
                v_auth_user_id
            );

            v_claim_item_count := v_claim_item_count + 1;
        end if;


        -- ====================================================
        -- 7J. UPDATE DELIVERY ITEM DOCUMENT TOTALS
        -- ====================================================

        update public.supplier_delivery_items
        set
            accepted_quantity =
                coalesce(accepted_quantity, 0)
                + v_accepted_now,

            damaged_quantity =
                coalesce(damaged_quantity, 0)
                + v_damaged_now,

            rejected_quantity =
                coalesce(rejected_quantity, 0)
                + v_rejected_now,

            received_base_quantity =
                round(
                    (
                        coalesce(accepted_quantity, 0)
                        + v_accepted_now
                        + coalesce(damaged_quantity, 0)
                        + v_damaged_now
                        + coalesce(rejected_quantity, 0)
                        + v_rejected_now
                    )
                    * v_document_conversion,
                    6
                ),

            updated_at = now(),
            updated_by = v_auth_user_id

        where supplier_delivery_item_id =
              v_delivery_item.supplier_delivery_item_id;

        v_processed_item_count := v_processed_item_count + 1;
    end loop;


    if v_processed_item_count = 0 then
        raise exception
            'No supplier delivery items were processed.';
    end if;


    -- ========================================================
    -- 8. UPDATE DELIVERY STATUS
    -- ========================================================

    select
        coalesce(
            bool_and(
                round(
                    coalesce(item.accepted_quantity, 0)
                    + coalesce(item.damaged_quantity, 0)
                    + coalesce(item.rejected_quantity, 0),
                    6
                )
                >= round(item.received_quantity, 6)
            ),
            false
        ),

        coalesce(
            bool_or(
                coalesce(item.accepted_quantity, 0)
                + coalesce(item.damaged_quantity, 0)
                + coalesce(item.rejected_quantity, 0) > 0
            ),
            false
        ),

        coalesce(
            bool_and(
                coalesce(item.rejected_quantity, 0)
                >= item.received_quantity
                and coalesce(item.accepted_quantity, 0) = 0
                and coalesce(item.damaged_quantity, 0) = 0
            ),
            false
        )
    into
        v_all_delivery_items_complete,
        v_any_delivery_item_processed,
        v_all_delivery_items_rejected
    from public.supplier_delivery_items item
    where item.supplier_delivery_id = p_supplier_delivery_id
      and item.is_deleted = false;

    if v_all_delivery_items_rejected then
        v_delivery_status := 'Rejected';
    elsif v_all_delivery_items_complete then
        v_delivery_status := 'Received';
    elsif v_any_delivery_item_processed then
        v_delivery_status := 'Partial';
    else
        v_delivery_status := 'Pending';
    end if;

    update public.supplier_deliveries
    set
        delivery_status = v_delivery_status,
        updated_at = now(),
        updated_by = v_auth_user_id
    where supplier_delivery_id = p_supplier_delivery_id;


    -- ========================================================
    -- 9. UPDATE PURCHASE ORDER STATUS
    -- ========================================================

    if v_delivery.purchase_order_id is not null then
        with po_line_progress as (
            select
                po_line.purchase_order_line_id,
                po_line.quantity as ordered_quantity,

                coalesce(
                    sum(delivery_item.accepted_quantity)
                    filter (
                        where delivery_item.is_deleted = false
                    ),
                    0
                ) as accepted_quantity

            from public.purchase_order_lines po_line

            left join public.supplier_delivery_items delivery_item
                on delivery_item.purchase_order_line_id =
                   po_line.purchase_order_line_id
               and delivery_item.is_deleted = false

            where po_line.purchase_order_id =
                  v_delivery.purchase_order_id
              and po_line.is_deleted = false

            group by
                po_line.purchase_order_line_id,
                po_line.quantity
        )
        select
            coalesce(
                bool_and(
                    accepted_quantity >= ordered_quantity
                ),
                false
            ),
            coalesce(
                bool_or(accepted_quantity > 0),
                false
            )
        into
            v_all_po_lines_delivered,
            v_any_po_quantity_delivered
        from po_line_progress;

        if v_all_po_lines_delivered then
            v_purchase_order_status := 'Delivered';
        elsif v_any_po_quantity_delivered then
            v_purchase_order_status := 'Partially Delivered';
        else
            v_purchase_order_status := null;
        end if;

        if v_purchase_order_status is not null then
            update public.purchase_orders
            set
                order_status = v_purchase_order_status,
                updated_at = now(),
                updated_by = v_auth_user_id
            where purchase_order_id =
                  v_delivery.purchase_order_id
              and order_status <> 'Cancelled';
        end if;
    end if;



    -- ========================================================
    -- 10. QUEUE PHASE 1 TELEGRAM NOTIFICATION
    -- ========================================================

    perform public.enqueue_notification_event(
        p_event_code :=
            case
                when v_delivery_status = 'Rejected'
                     or exists (
                         select 1
                         from public.supplier_delivery_receipt_items receipt_item
                         where receipt_item.supplier_delivery_receipt_id = v_receipt_id
                           and receipt_item.is_deleted = false
                           and (
                               coalesce(receipt_item.damaged_quantity, 0) > 0
                               or coalesce(receipt_item.rejected_quantity, 0) > 0
                               or coalesce(receipt_item.replacement_required_quantity, 0) > 0
                           )
                     )
                    then 'site_goods_receiving_issue'
                when v_delivery_status = 'Partial'
                    then 'site_goods_receiving_partial'
                else 'site_goods_receiving_completed'
            end,
        p_source_table := 'supplier_delivery_receipts',
        p_source_id := v_receipt_id,
        p_event_key := 'site_goods_receiving:'
            || v_receipt_id::text,
        p_payload := jsonb_build_object(
            'supplier_delivery_receipt_id', v_receipt_id,
            'supplier_delivery_id', p_supplier_delivery_id,
            'project_id', v_site.project_id,
            'site_id', p_site_id,
            'stock_location_id', p_stock_location_id,
            'received_by_employee_id', v_employee_id,
            'received_at', now(),
            'processed_item_count', v_processed_item_count,
            'replacement_claim_item_count', v_claim_item_count,
            'payment_hold_required', (v_claim_id is not null),
            'delivery_status', v_delivery_status,
            'purchase_order_status', v_purchase_order_status,
            'notes', nullif(trim(p_notes), '')
        ),
        p_created_by := v_auth_user_id
    );


    -- ========================================================
    -- 11. RESULT
    -- ========================================================

    return jsonb_build_object(
        'supplier_delivery_receipt_id',
        v_receipt_id,
        'supplier_replacement_claim_id',
        v_claim_id,
        'supplier_delivery_id',
        p_supplier_delivery_id,
        'project_id',
        v_site.project_id,
        'site_id',
        p_site_id,
        'stock_location_id',
        p_stock_location_id,
        'received_by_employee_id',
        v_employee_id,
        'created_by',
        v_auth_user_id,
        'processed_item_count',
        v_processed_item_count,
        'replacement_claim_item_count',
        v_claim_item_count,
        'payment_hold_required',
        (v_claim_id is not null),
        'delivery_status',
        v_delivery_status,
        'purchase_order_status',
        v_purchase_order_status
    );
end;
$$;


ALTER FUNCTION "public"."create_supplier_delivery_receipt"("p_supplier_delivery_id" "uuid", "p_site_id" "uuid", "p_stock_location_id" "uuid", "p_items" "jsonb", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_tool_loan_atomic"("p_header" "jsonb", "p_items" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
    v_request public.stock_requests%rowtype;
    v_item jsonb;
    v_request_item public.stock_request_items%rowtype;
    v_product public.products%rowtype;
    v_tool_loan_id uuid;
    v_line_no integer := 0;
    v_quantity numeric(18,6);
    v_base_quantity numeric(18,6);
    v_uom_code text;
    v_base_uom_code text;
    v_conversion numeric(18,6);
begin
    if not public.has_permission('tool_loans.create') then
        raise exception 'Permission denied: tool_loans.create.';
    end if;

    if p_header is null or jsonb_typeof(p_header) <> 'object' then
        raise exception 'Tool Loan header is required.';
    end if;

    if p_items is null
       or jsonb_typeof(p_items) <> 'array'
       or jsonb_array_length(p_items) = 0 then
        raise exception 'At least one Tool Loan item is required.';
    end if;

    select *
    into v_request
    from public.stock_requests
    where stock_request_id =
          nullif(p_header->>'stock_request_id', '')::uuid
      and is_deleted = false
    for update;

    if not found then
        raise exception 'Approved source Stock Request was not found.';
    end if;

    if v_request.request_status not in (
        'Approved',
        'Partially Approved',
        'Partially Reserved',
        'Reserved',
        'Partially Issued'
    ) then
        raise exception
            'Source Stock Request is not approved for Tool Loan creation.';
    end if;

    if nullif(p_header->>'from_stock_location_id', '') is null then
        raise exception 'Source Stock Location is required.';
    end if;

    if nullif(p_header->>'borrower_employee_id', '') is null
       and nullif(p_header->>'borrower_auth_user_id', '') is null then
        raise exception 'Borrower is required.';
    end if;

    insert into public.tool_loans (
        tool_loan_no,
        stock_request_id,
        project_id,
        site_id,
        area_id,
        work_order_id,
        from_stock_location_id,
        borrower_auth_user_id,
        borrower_employee_id,
        loan_date,
        due_date,
        loan_status,
        priority,
        notes,
        created_by,
        updated_by
    )
    values (
        '',
        v_request.stock_request_id,
        v_request.project_id,
        v_request.site_id,
        v_request.area_id,
        v_request.work_order_id,
        nullif(p_header->>'from_stock_location_id', '')::uuid,
        nullif(p_header->>'borrower_auth_user_id', '')::uuid,
        nullif(p_header->>'borrower_employee_id', '')::uuid,
        coalesce(
            nullif(p_header->>'loan_date', '')::date,
            current_date
        ),
        nullif(p_header->>'due_date', '')::date,
        'Draft',
        coalesce(nullif(p_header->>'priority', ''), 'Normal'),
        nullif(btrim(p_header->>'notes'), ''),
        auth.uid(),
        auth.uid()
    )
    returning tool_loan_id
    into v_tool_loan_id;

    for v_item in
        select value
        from jsonb_array_elements(p_items)
    loop
        v_line_no := v_line_no + 1;

        select *
        into v_request_item
        from public.stock_request_items
        where stock_request_item_id =
              nullif(v_item->>'stock_request_item_id', '')::uuid
          and stock_request_id = v_request.stock_request_id
          and is_deleted = false
        for update;

        if not found then
            raise exception
                'Source Stock Request item for Tool Loan line % was not found.',
                v_line_no;
        end if;

        if coalesce(v_request_item.fulfilment_method, '') <> 'Loan' then
            raise exception
                'Stock Request item line % is not routed for Loan.',
                v_line_no;
        end if;

        if coalesce(v_request_item.approved_base_quantity, 0) <= 0 then
            raise exception
                'Stock Request item line % has no approved quantity.',
                v_line_no;
        end if;

        select *
        into v_product
        from public.products
        where product_id = v_request_item.product_id
          and is_deleted = false
          and is_active = true;

        if not found then
            raise exception
                'Tool or Equipment product for line % was not found.',
                v_line_no;
        end if;

        if v_product.product_type not in ('Tool', 'Equipment') then
            raise exception
                'Tool Loan line % must use a Tool or Equipment product.',
                v_line_no;
        end if;

        v_quantity :=
            coalesce(
                nullif(v_item->>'approved_quantity', '')::numeric,
                v_request_item.approved_quantity
            );

        if v_quantity is null or v_quantity <= 0 then
            raise exception
                'Approved quantity for Tool Loan line % must be greater than zero.',
                v_line_no;
        end if;

        if v_quantity > coalesce(v_request_item.approved_quantity, 0) then
            raise exception
                'Tool Loan line % exceeds the Stock Request approved quantity.',
                v_line_no;
        end if;

        v_uom_code :=
            coalesce(
                nullif(v_item->>'loan_uom_code', ''),
                v_request_item.request_uom_code,
                v_request_item.unit_of_measure,
                v_product.base_uom_code
            );

        v_base_uom_code :=
            coalesce(
                v_request_item.base_uom_code,
                v_product.base_uom_code
            );

        v_conversion :=
            coalesce(
                v_request_item.conversion_factor_to_base,
                1
            );

        if v_conversion <= 0 then
            raise exception
                'Invalid UOM conversion for Tool Loan line %.',
                v_line_no;
        end if;

        v_base_quantity := round(v_quantity * v_conversion, 6);

        if v_base_quantity >
           coalesce(v_request_item.approved_base_quantity, 0) then
            raise exception
                'Tool Loan line % exceeds approved Base Quantity.',
                v_line_no;
        end if;

        insert into public.tool_loan_items (
            tool_loan_id,
            stock_request_item_id,
            line_no,
            product_id,
            asset_reference,
            serial_number,
            description,
            loan_uom_code,
            base_uom_code,
            conversion_factor_to_base,
            allow_fractional_quantity,
            approved_quantity,
            approved_base_quantity,
            issued_quantity,
            issued_base_quantity,
            returned_quantity,
            returned_base_quantity,
            damaged_quantity,
            lost_quantity,
            condition_before,
            condition_notes_before,
            item_status,
            notes,
            created_by,
            updated_by
        )
        values (
            v_tool_loan_id,
            v_request_item.stock_request_item_id,
            v_line_no,
            v_request_item.product_id,
            nullif(btrim(v_item->>'asset_reference'), ''),
            nullif(btrim(v_item->>'serial_number'), ''),
            coalesce(
                nullif(btrim(v_item->>'description'), ''),
                v_request_item.description,
                v_product.product_name
            ),
            v_uom_code,
            v_base_uom_code,
            v_conversion,
            coalesce(v_request_item.allow_fractional_quantity, false),
            v_quantity,
            v_base_quantity,
            0,
            0,
            0,
            0,
            0,
            0,
            nullif(v_item->>'condition_before', ''),
            nullif(btrim(v_item->>'condition_notes_before'), ''),
            'Draft',
            nullif(btrim(v_item->>'notes'), ''),
            auth.uid(),
            auth.uid()
        );
    end loop;

    return v_tool_loan_id;
end;
$$;


ALTER FUNCTION "public"."create_tool_loan_atomic"("p_header" "jsonb", "p_items" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_variation_atomic"("p_variation" "jsonb", "p_lines" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    v_user_id uuid := auth.uid();
    v_quotation public.quotations%rowtype;
    v_site public.project_sites%rowtype;

    v_variation_id uuid;
    v_variation_no text;
    v_reason text;
    v_notes text;
    v_issue_date date;
    v_valid_until date;

    v_line jsonb;
    v_line_no integer := 0;
    v_line_count integer;

    v_product_id uuid;
    v_area_id uuid;
    v_description text;
    v_sales_uom text;
    v_base_uom text;
    v_quantity numeric(18,6);
    v_conversion numeric(18,6);
    v_base_quantity numeric(18,6);
    v_allow_fractional boolean;
    v_unit_price numeric(18,2);
    v_discount_percent numeric(9,4);
    v_discount_amount numeric(18,2);
    v_tax_rate numeric(9,4);
    v_tax_amount numeric(18,2);
    v_cost_price numeric(18,2);
    v_margin_amount numeric(18,2);
    v_margin_percent numeric(9,4);
    v_line_subtotal numeric(18,2);
    v_line_total numeric(18,2);
    v_line_notes text;
    v_is_optional boolean;

    v_subtotal numeric(18,2) := 0;
    v_total_discount numeric(18,2) := 0;
    v_total_tax numeric(18,2) := 0;
    v_total numeric(18,2) := 0;
begin
    if v_user_id is null then
        raise exception 'Authentication is required.';
    end if;

    if not public.has_permission('variations.create') then
        raise exception 'Permission denied: variations.create is required.';
    end if;

    if p_variation is null or jsonb_typeof(p_variation) <> 'object' then
        raise exception 'Variation header must be a JSON object.';
    end if;

    if p_lines is null or jsonb_typeof(p_lines) <> 'array' then
        raise exception 'Variation lines must be a JSON array.';
    end if;

    v_line_count := jsonb_array_length(p_lines);
    if v_line_count = 0 then
        raise exception 'At least one Variation line is required.';
    end if;

    begin
        select q.*
        into v_quotation
        from public.quotations q
        where q.quotation_id =
              nullif(btrim(p_variation ->> 'quotation_id'), '')::uuid
          and q.quotation_status = 'Accepted'
          and q.is_active = true
          and q.is_deleted = false
        for update;
    exception
        when invalid_text_representation then
            raise exception 'Invalid quotation_id.';
    end;

    if not found then
        raise exception 'Variation requires an active Accepted quotation.';
    end if;

    select ps.*
    into v_site
    from public.project_sites ps
    where ps.site_id = v_quotation.project_site_id
      and ps.site_status = 'Active'
      and ps.is_active = true
      and ps.is_deleted = false
    for update;

    if not found then
        raise exception 'The Accepted quotation Site is not Active.';
    end if;

    v_reason := nullif(btrim(p_variation ->> 'variation_reason'), '');
    if v_reason is null then
        raise exception 'Variation reason is required.';
    end if;

    begin
        v_issue_date := coalesce(
            nullif(btrim(p_variation ->> 'issue_date'), '')::date,
            current_date
        );
        v_valid_until :=
            nullif(btrim(p_variation ->> 'valid_until'), '')::date;
    exception
        when others then
            raise exception 'Invalid Variation date.';
    end;

    if v_valid_until is not null and v_valid_until < v_issue_date then
        raise exception 'Valid Until cannot be earlier than Issue Date.';
    end if;

    v_notes := nullif(btrim(p_variation ->> 'notes'), '');

    insert into public.variations (
        variation_no,
        quotation_id,
        accepted_revision_id,
        customer_id,
        project_id,
        project_site_id,
        variation_status,
        variation_reason,
        notes,
        issue_date,
        valid_until,
        subtotal,
        discount_amount,
        tax_amount,
        total_amount,
        is_active,
        is_deleted,
        created_by,
        updated_by
    )
    values (
        null,
        v_quotation.quotation_id,
        v_quotation.accepted_revision_id,
        v_quotation.customer_id,
        v_site.project_id,
        v_site.site_id,
        'Draft',
        v_reason,
        v_notes,
        v_issue_date,
        v_valid_until,
        0, 0, 0, 0,
        true,
        false,
        v_user_id,
        v_user_id
    )
    returning variation_id, variation_no
    into v_variation_id, v_variation_no;

    for v_line in
        select value from jsonb_array_elements(p_lines)
    loop
        v_line_no := v_line_no + 1;

        if jsonb_typeof(v_line) <> 'object' then
            raise exception 'Variation line % must be a JSON object.', v_line_no;
        end if;

        begin
            v_product_id :=
                nullif(btrim(v_line ->> 'product_id'), '')::uuid;
            v_area_id :=
                nullif(btrim(v_line ->> 'project_area_id'), '')::uuid;
        exception
            when invalid_text_representation then
                raise exception 'Variation line % contains an invalid UUID.', v_line_no;
        end;

        v_description := nullif(btrim(v_line ->> 'description'), '');
        if v_description is null then
            raise exception 'Description is required for Variation line %.', v_line_no;
        end if;

        v_sales_uom := nullif(btrim(v_line ->> 'sales_uom_code'), '');
        v_base_uom := nullif(btrim(v_line ->> 'base_uom_code'), '');

        if v_sales_uom is null or v_base_uom is null then
            raise exception 'Sales UOM and Base UOM are required for Variation line %.', v_line_no;
        end if;

        if not exists (
            select 1 from public.units_of_measure u
            where u.uom_code = v_sales_uom
        ) then
            raise exception 'Sales UOM % does not exist on Variation line %.', v_sales_uom, v_line_no;
        end if;

        if not exists (
            select 1 from public.units_of_measure u
            where u.uom_code = v_base_uom
        ) then
            raise exception 'Base UOM % does not exist on Variation line %.', v_base_uom, v_line_no;
        end if;

        begin
            v_quantity := coalesce(nullif(btrim(v_line ->> 'quantity'), '')::numeric, 0);
            v_conversion := coalesce(nullif(btrim(v_line ->> 'conversion_factor'), '')::numeric, 1);
            v_unit_price := coalesce(nullif(btrim(v_line ->> 'unit_price'), '')::numeric, 0);
            v_discount_percent := coalesce(nullif(btrim(v_line ->> 'discount_percent'), '')::numeric, 0);
            v_tax_rate := coalesce(nullif(btrim(v_line ->> 'tax_rate'), '')::numeric, 0);
            v_cost_price := coalesce(nullif(btrim(v_line ->> 'cost_price'), '')::numeric, 0);
            v_allow_fractional := coalesce(nullif(btrim(v_line ->> 'allow_fractional_quantity'), '')::boolean, true);
            v_is_optional := coalesce(nullif(btrim(v_line ->> 'is_optional'), '')::boolean, false);
        exception
            when invalid_text_representation or numeric_value_out_of_range then
                raise exception 'Variation line % contains an invalid numeric or boolean value.', v_line_no;
        end;

        if v_quantity <= 0 then
            raise exception 'Quantity must be greater than zero on Variation line %.', v_line_no;
        end if;

        if not v_allow_fractional and v_quantity <> trunc(v_quantity) then
            raise exception 'Variation line % does not allow fractional quantity.', v_line_no;
        end if;

        if v_conversion <= 0 then
            raise exception 'Conversion factor must be greater than zero on Variation line %.', v_line_no;
        end if;

        if v_unit_price < 0 or v_cost_price < 0 then
            raise exception 'Prices cannot be negative on Variation line %.', v_line_no;
        end if;

        if v_discount_percent < 0 or v_discount_percent > 100 then
            raise exception 'Discount Percent must be between 0 and 100 on Variation line %.', v_line_no;
        end if;

        if v_tax_rate < 0 or v_tax_rate > 100 then
            raise exception 'Tax Rate must be between 0 and 100 on Variation line %.', v_line_no;
        end if;

        if v_product_id is not null and not exists (
            select 1 from public.products p
            where p.product_id = v_product_id
              and p.is_active = true
              and p.is_deleted = false
        ) then
            raise exception 'Product on Variation line % is inactive or unavailable.', v_line_no;
        end if;

        if v_area_id is not null and not exists (
            select 1 from public.project_areas pa
            where pa.area_id = v_area_id
              and pa.project_id = v_site.project_id
              and pa.site_id = v_site.site_id
              and pa.area_status in ('Quotation', 'Active')
              and pa.is_active = true
              and pa.is_deleted = false
        ) then
            raise exception 'Area on Variation line % does not belong to the Variation Project/Site or is unavailable.', v_line_no;
        end if;

        v_base_quantity := round(v_quantity * v_conversion, 6);
        v_line_subtotal := round(v_quantity * v_unit_price, 2);
        v_discount_amount := round(v_line_subtotal * v_discount_percent / 100, 2);
        v_tax_amount := round((v_line_subtotal - v_discount_amount) * v_tax_rate / 100, 2);
        v_line_total := round(v_line_subtotal - v_discount_amount + v_tax_amount, 2);
        v_margin_amount := round((v_unit_price - v_cost_price) * v_quantity - v_discount_amount, 2);

        if (v_line_subtotal - v_discount_amount) > 0 then
            v_margin_percent := round(v_margin_amount / (v_line_subtotal - v_discount_amount) * 100, 4);
        else
            v_margin_percent := 0;
        end if;

        v_line_notes := nullif(btrim(v_line ->> 'notes'), '');

        insert into public.variation_lines (
            variation_id,
            line_no,
            product_id,
            project_area_id,
            description,
            quantity,
            unit_of_measure,
            sales_uom_code,
            base_uom_code,
            conversion_factor,
            base_quantity,
            allow_fractional_quantity,
            unit_price,
            discount_percent,
            discount_amount,
            tax_rate,
            tax_amount,
            line_total,
            cost_price,
            margin_amount,
            margin_percent,
            notes,
            is_optional,
            is_active,
            is_deleted,
            created_by,
            updated_by
        )
        values (
            v_variation_id,
            v_line_no,
            v_product_id,
            v_area_id,
            v_description,
            v_quantity,
            v_sales_uom,
            v_sales_uom,
            v_base_uom,
            v_conversion,
            v_base_quantity,
            v_allow_fractional,
            v_unit_price,
            v_discount_percent,
            v_discount_amount,
            v_tax_rate,
            v_tax_amount,
            v_line_total,
            v_cost_price,
            v_margin_amount,
            v_margin_percent,
            v_line_notes,
            v_is_optional,
            true,
            false,
            v_user_id,
            v_user_id
        );

        if not v_is_optional then
            v_subtotal := v_subtotal + v_line_subtotal;
            v_total_discount := v_total_discount + v_discount_amount;
            v_total_tax := v_total_tax + v_tax_amount;
            v_total := v_total + v_line_total;
        end if;
    end loop;

    update public.variations
    set
        subtotal = round(v_subtotal, 2),
        discount_amount = round(v_total_discount, 2),
        tax_amount = round(v_total_tax, 2),
        total_amount = round(v_total, 2),
        updated_by = v_user_id
    where variation_id = v_variation_id;

    return jsonb_build_object(
        'variation_id', v_variation_id,
        'variation_no', v_variation_no,
        'variation_status', 'Draft',
        'line_count', v_line_count,
        'subtotal', round(v_subtotal, 2),
        'discount_amount', round(v_total_discount, 2),
        'tax_amount', round(v_total_tax, 2),
        'total_amount', round(v_total, 2)
    );
end;
$$;


ALTER FUNCTION "public"."create_variation_atomic"("p_variation" "jsonb", "p_lines" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_work_assignment"("p_employee_id" "uuid", "p_project_id" "uuid", "p_site_id" "uuid", "p_area_id" "uuid", "p_work_order_id" "uuid", "p_notes" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_work_assignment_id uuid;
begin
  if exists (
    select 1
    from public.work_assignments
    where employee_id = p_employee_id
      and work_order_id = p_work_order_id
      and ended_at is null
      and is_deleted = false
  ) then
    raise exception 'This worker is already actively assigned to this work order.';
  end if;

  insert into public.work_assignments (
    employee_id,
    project_id,
    site_id,
    area_id,
    work_order_id,
    assigned_at,
    notes,
    is_deleted
  )
  values (
    p_employee_id,
    p_project_id,
    p_site_id,
    p_area_id,
    p_work_order_id,
    now(),
    p_notes,
    false
  )
  returning work_assignment_id into v_work_assignment_id;

  return v_work_assignment_id;
end;
$$;


ALTER FUNCTION "public"."create_work_assignment"("p_employee_id" "uuid", "p_project_id" "uuid", "p_site_id" "uuid", "p_area_id" "uuid", "p_work_order_id" "uuid", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."current_app_role"() RETURNS "text"
    LANGUAGE "plpgsql" STABLE
    AS $$
begin
  return coalesce(
    auth.jwt() ->> 'app_role',
    auth.jwt() -> 'app_metadata' ->> 'app_role',
    'viewer'
  );
end;
$$;


ALTER FUNCTION "public"."current_app_role"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."current_app_user_status"() RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
    SELECT COALESCE(
        (
            SELECT au.account_status
            FROM public.app_users au
            WHERE au.auth_user_id = auth.uid()
            LIMIT 1
        ),
        'Unregistered'
    );
$$;


ALTER FUNCTION "public"."current_app_user_status"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."current_employee_id"() RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
    select e.employee_id
    from public.employees e
    where e.auth_user_id = auth.uid()
      and e.is_active = true
      and e.is_deleted = false
    limit 1;
$$;


ALTER FUNCTION "public"."current_employee_id"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."deliver_stock_issue_atomic"("p_stock_issue_id" "uuid", "p_delivered_at" timestamp with time zone DEFAULT "now"(), "p_notes" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
    v_issue public.stock_issues%rowtype;
begin
    if not public.has_permission('stock_issues.dispatch') then
        raise exception
            'Permission denied: stock_issues.dispatch.';
    end if;

    select *
    into v_issue
    from public.stock_issues
    where stock_issue_id = p_stock_issue_id
      and is_deleted = false
    for update;

    if not found then
        raise exception 'Stock Issue was not found.';
    end if;

    if v_issue.issue_status <> 'Dispatched' then
        raise exception
            'Only Dispatched Stock Issues can be marked Delivered.';
    end if;

    update public.stock_issue_lines
    set
        line_status = 'Delivered',
        updated_at = now(),
        updated_by = auth.uid()
    where stock_issue_id = p_stock_issue_id
      and is_deleted = false
      and line_status = 'Dispatched';

    update public.stock_issues
    set
        issue_status = 'Delivered',
        delivered_at = coalesce(p_delivered_at, now()),
        delivered_by = auth.uid(),
        notes = coalesce(
            nullif(btrim(p_notes), ''),
            notes
        ),
        updated_at = now(),
        updated_by = auth.uid()
    where stock_issue_id = p_stock_issue_id;

    return p_stock_issue_id;
end;
$$;


ALTER FUNCTION "public"."deliver_stock_issue_atomic"("p_stock_issue_id" "uuid", "p_delivered_at" timestamp with time zone, "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."disconnect_user_telegram_channel"("p_auth_user_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
    if auth.uid() is null then
        raise exception 'Authentication is required.';
    end if;

    if not public.has_permission('telegram_notifications.manage') then
        raise exception
            'Permission denied: telegram_notifications.manage';
    end if;

    update public.notification_user_channels
    set
        connection_status = 'Disconnected',
        is_enabled = false,
        disconnected_at = now(),
        disconnected_by = auth.uid(),
        connection_notes = coalesce(
            nullif(trim(p_reason), ''),
            connection_notes
        ),
        updated_at = now(),
        updated_by = auth.uid()
    where auth_user_id = p_auth_user_id
      and channel_type = 'Telegram'
      and is_deleted = false;

    if not found then
        raise exception
            'Telegram channel is not configured for this user.';
    end if;
end;
$$;


ALTER FUNCTION "public"."disconnect_user_telegram_channel"("p_auth_user_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."dispatch_stock_issue_atomic"("p_stock_issue_id" "uuid", "p_dispatch_reference" "text" DEFAULT NULL::"text", "p_vehicle_reference" "text" DEFAULT NULL::"text", "p_notes" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
    v_issue public.stock_issues%rowtype;
begin
    if not public.has_permission('stock_issues.dispatch') then
        raise exception 'Permission denied: stock_issues.dispatch.';
    end if;

    select *
    into v_issue
    from public.stock_issues
    where stock_issue_id = p_stock_issue_id
      and is_deleted = false
    for update;

    if not found then
        raise exception 'Stock Issue was not found.';
    end if;

    if v_issue.issue_status <> 'Issued' then
        raise exception
            'Only Issued Stock Issues can be dispatched.';
    end if;

    update public.stock_issue_lines
    set
        line_status = 'Dispatched',
        updated_at = now(),
        updated_by = auth.uid()
    where stock_issue_id = p_stock_issue_id
      and is_deleted = false;

    update public.stock_issues
    set
        issue_status = 'Dispatched',
        dispatched_at = now(),
        dispatched_by = auth.uid(),
        dispatch_reference = coalesce(
            nullif(btrim(p_dispatch_reference), ''),
            dispatch_reference
        ),
        vehicle_reference = coalesce(
            nullif(btrim(p_vehicle_reference), ''),
            vehicle_reference
        ),
        notes = coalesce(
            nullif(btrim(p_notes), ''),
            notes
        ),
        updated_at = now(),
        updated_by = auth.uid()
    where stock_issue_id = p_stock_issue_id;

    return p_stock_issue_id;
end;
$$;


ALTER FUNCTION "public"."dispatch_stock_issue_atomic"("p_stock_issue_id" "uuid", "p_dispatch_reference" "text", "p_vehicle_reference" "text", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."end_work_assignment"("p_work_assignment_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  update public.work_assignments
  set ended_at = now()
  where work_assignment_id = p_work_assignment_id
    and is_deleted = false
    and ended_at is null;
end;
$$;


ALTER FUNCTION "public"."end_work_assignment"("p_work_assignment_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_notification_event"("p_event_code" "text", "p_source_table" "text", "p_source_id" "uuid", "p_event_key" "text", "p_payload" "jsonb" DEFAULT '{}'::"jsonb", "p_created_by" "uuid" DEFAULT "auth"."uid"()) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
    v_event_type public.notification_event_types%rowtype;
    v_notification_event_id uuid;
begin
    if nullif(trim(p_event_code), '') is null then
        raise exception 'Notification event code is required.';
    end if;

    if nullif(trim(p_source_table), '') is null then
        raise exception 'Notification source table is required.';
    end if;

    if p_source_id is null then
        raise exception 'Notification source ID is required.';
    end if;

    if nullif(trim(p_event_key), '') is null then
        raise exception 'Notification event key is required.';
    end if;

    select *
    into v_event_type
    from public.notification_event_types
    where event_code = p_event_code
      and is_active = true
      and telegram_enabled = true;

    if not found then
        raise exception
            'Active Telegram notification event type % was not found.',
            p_event_code;
    end if;

    insert into public.notification_events (
        event_code,
        event_key,
        source_table,
        source_id,
        severity,
        payload,
        event_status,
        attempt_count,
        next_attempt_at,
        created_by
    )
    values (
        v_event_type.event_code,
        trim(p_event_key),
        trim(p_source_table),
        p_source_id,
        v_event_type.default_severity,
        coalesce(p_payload, '{}'::jsonb),
        'Pending',
        0,
        now(),
        p_created_by
    )
    on conflict (event_key) do nothing
    returning notification_event_id
    into v_notification_event_id;

    if v_notification_event_id is null then
        select notification_event_id
        into v_notification_event_id
        from public.notification_events
        where event_key = trim(p_event_key);
    end if;

    return v_notification_event_id;
end;
$$;


ALTER FUNCTION "public"."enqueue_notification_event"("p_event_code" "text", "p_source_table" "text", "p_source_id" "uuid", "p_event_key" "text", "p_payload" "jsonb", "p_created_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."exclude_material_requirement_line"("p_material_requirement_line_id" "uuid", "p_exclusion_reason" "text", "p_adjustment_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_actor uuid;

    v_header public.material_requirements%ROWTYPE;
    v_before public.material_requirement_lines%ROWTYPE;
    v_after public.material_requirement_lines%ROWTYPE;

    v_adjustment_id uuid;
    v_next_adjustment_no integer;

    v_exclusion_reason text;
    v_adjustment_reason text;
BEGIN
    v_actor := auth.uid();

    IF v_actor IS NULL THEN
        RAISE EXCEPTION
            'Authentication is required.';
    END IF;

    IF NOT public.has_permission(
        'material_requirements.adjust'
    ) THEN
        RAISE EXCEPTION
            'Permission denied: material_requirements.adjust is required.';
    END IF;

    IF p_material_requirement_line_id IS NULL THEN
        RAISE EXCEPTION
            'Material Requirement Line ID is required.';
    END IF;

    v_exclusion_reason :=
        NULLIF(
            btrim(p_exclusion_reason),
            ''
        );

    v_adjustment_reason :=
        NULLIF(
            btrim(p_adjustment_reason),
            ''
        );

    IF v_exclusion_reason IS NULL THEN
        RAISE EXCEPTION
            'Exclusion reason is required.';
    END IF;

    IF v_adjustment_reason IS NULL THEN
        RAISE EXCEPTION
            'Adjustment reason is required.';
    END IF;

    SELECT line_row.*
    INTO v_before
    FROM public.material_requirement_lines line_row
    WHERE line_row.material_requirement_line_id =
              p_material_requirement_line_id
      AND line_row.is_active = true
      AND line_row.is_deleted = false
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'Active Material Requirement Line was not found.';
    END IF;

    SELECT header_row.*
    INTO v_header
    FROM public.material_requirements header_row
    WHERE header_row.material_requirement_id =
              v_before.material_requirement_id
      AND header_row.is_active = true
      AND header_row.is_deleted = false
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'Active Material Requirement Header was not found.';
    END IF;

    IF v_header.requirement_status <> 'Draft' THEN
        RAISE EXCEPTION
            'Lines may currently be excluded only while the Material Requirement is Draft. Current status: %.',
            v_header.requirement_status;
    END IF;

    IF v_before.line_status = 'Excluded' THEN
        RAISE EXCEPTION
            'Material Requirement Line is already Excluded.';
    END IF;

    IF v_before.line_status IN (
        'Cancelled',
        'Fulfilled'
    ) THEN
        RAISE EXCEPTION
            'Line status % cannot be excluded.',
            v_before.line_status;
    END IF;

    UPDATE public.material_requirement_lines
    SET
        line_status = 'Excluded',
        exclusion_reason = v_exclusion_reason,
        updated_at = now(),
        updated_by = v_actor
    WHERE material_requirement_line_id =
          p_material_requirement_line_id
    RETURNING *
    INTO v_after;

    SELECT COALESCE(
        max(adj.adjustment_no),
        0
    ) + 1
    INTO v_next_adjustment_no
    FROM public.material_requirement_line_adjustments adj
    WHERE adj.material_requirement_line_id =
          p_material_requirement_line_id;

    INSERT INTO public.material_requirement_line_adjustments (
        material_requirement_line_id,
        adjustment_no,
        adjustment_type,
        adjustment_reason,
        before_snapshot,
        after_snapshot,
        base_quantity_change,
        commercial_impact,
        variation_required,
        approval_required,
        approval_status,
        created_by
    )
    VALUES (
        p_material_requirement_line_id,
        v_next_adjustment_no,
        'Exclude',
        v_adjustment_reason,
        to_jsonb(v_before),
        to_jsonb(v_after),
        -v_before.required_base_quantity,
        v_after.commercial_impact,
        v_after.variation_required,
        CASE
            WHEN v_after.commercial_impact IN (
                'CustomerCharge',
                'CustomerCredit',
                'PendingReview'
            )
            THEN true
            ELSE false
        END,
        CASE
            WHEN v_after.commercial_impact IN (
                'CustomerCharge',
                'CustomerCredit',
                'PendingReview'
            )
            THEN 'Pending'
            ELSE 'NotRequired'
        END,
        v_actor
    )
    RETURNING material_requirement_line_adjustment_id
    INTO v_adjustment_id;

    UPDATE public.material_requirements
    SET
        updated_at = now(),
        updated_by = v_actor
    WHERE material_requirement_id =
          v_before.material_requirement_id;

    RETURN jsonb_build_object(
        'material_requirement_id',
            v_before.material_requirement_id,
        'material_requirement_line_id',
            p_material_requirement_line_id,
        'adjustment_id',
            v_adjustment_id,
        'adjustment_no',
            v_next_adjustment_no,
        'adjustment_type',
            'Exclude',
        'previous_line_status',
            v_before.line_status,
        'new_line_status',
            v_after.line_status,
        'exclusion_reason',
            v_after.exclusion_reason,
        'base_quantity_change',
            -v_before.required_base_quantity,
        'line',
            to_jsonb(v_after)
    );
END;
$$;


ALTER FUNCTION "public"."exclude_material_requirement_line"("p_material_requirement_line_id" "uuid", "p_exclusion_reason" "text", "p_adjustment_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_document_number"("p_document_type" "text", "p_prefix" "text", "p_reset_monthly" boolean DEFAULT true) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_year_month TEXT;
  v_next_number INTEGER;
  v_document_no TEXT;
BEGIN
  IF p_reset_monthly THEN
    v_year_month := to_char(now(), 'YYMM');
  ELSE
    v_year_month := NULL;
  END IF;

  INSERT INTO document_sequences (
    document_type,
    prefix,
    year_month,
    current_number,
    reset_monthly
  )
  VALUES (
    p_document_type,
    p_prefix,
    v_year_month,
    1,
    p_reset_monthly
  )
  ON CONFLICT (document_type, year_month)
  DO UPDATE SET
    current_number = document_sequences.current_number + 1,
    updated_at = now()
  RETURNING current_number INTO v_next_number;

  IF p_reset_monthly THEN
    v_document_no :=
      p_prefix || v_year_month || '-' || lpad(v_next_number::TEXT, 5, '0');
  ELSE
    v_document_no :=
      p_prefix || '-' || lpad(v_next_number::TEXT, 5, '0');
  END IF;

  RETURN v_document_no;
END;
$$;


ALTER FUNCTION "public"."generate_document_number"("p_document_type" "text", "p_prefix" "text", "p_reset_monthly" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_employee_code"() RETURNS "text"
    LANGUAGE "plpgsql"
    AS $$
declare
  v_next_number bigint;
begin
  v_next_number := nextval('public.employee_code_seq');

  if v_next_number > 999 then
    raise exception
      'Employee code limit reached. Maximum code is EMP-999.';
  end if;

  return
    'EMP-' || lpad(v_next_number::text, 3, '0');
end;
$$;


ALTER FUNCTION "public"."generate_employee_code"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_material_requirement_from_accepted_quotation"("p_quotation_id" "uuid", "p_required_by_date" "date" DEFAULT NULL::"date", "p_delivery_stock_location_id" "uuid" DEFAULT NULL::"uuid", "p_responsible_auth_user_id" "uuid" DEFAULT NULL::"uuid", "p_notes" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    v_user_id uuid;
    v_quotation public.quotations%rowtype;
    v_project_id uuid;
    v_site_id uuid;
    v_material_requirement_id uuid;
    v_source_type text;
    v_inserted_line_count integer;
begin
    v_user_id := auth.uid();

    if v_user_id is null then
        raise exception 'Authentication is required.';
    end if;

    if not public.has_permission('material_requirements.create') then
        raise exception 'Permission denied: material_requirements.create';
    end if;

    select q.*
    into v_quotation
    from public.quotations q
    where q.quotation_id = p_quotation_id
      and q.is_deleted = false
    for update;

    if not found then
        raise exception 'Quotation not found.';
    end if;

    if v_quotation.quotation_status <> 'Accepted' then
        raise exception 'Material Requirement can only be generated from an Accepted quotation.';
    end if;

    if v_quotation.project_site_id is null then
        raise exception 'Accepted quotation does not have a Project Site.';
    end if;

    select ps.site_id, ps.project_id
    into v_site_id, v_project_id
    from public.project_sites ps
    where ps.site_id = v_quotation.project_site_id
      and ps.is_deleted = false;

    if not found then
        raise exception 'Project Site linked to the quotation was not found or has been deleted.';
    end if;

    if v_project_id is null then
        raise exception 'The linked Project Site does not have a Project.';
    end if;

    if v_quotation.accepted_revision_id is null then
        v_source_type := 'AcceptedQuotation';

        if exists (
            select 1
            from public.material_requirements mr
            where mr.source_type = 'AcceptedQuotation'
              and mr.quotation_id = p_quotation_id
              and mr.is_deleted = false
        ) then
            raise exception 'An active Material Requirement already exists for this accepted quotation.';
        end if;
    else
        v_source_type := 'AcceptedRevision';

        if not exists (
            select 1
            from public.quotation_revisions qr
            where qr.revision_id = v_quotation.accepted_revision_id
              and qr.quotation_id = v_quotation.quotation_id
              and qr.revision_status = 'Accepted'
        ) then
            raise exception 'Accepted revision does not belong to this quotation or is not Accepted.';
        end if;

        if exists (
            select 1
            from public.material_requirements mr
            where mr.source_type = 'AcceptedRevision'
              and mr.accepted_revision_id = v_quotation.accepted_revision_id
              and mr.is_deleted = false
        ) then
            raise exception 'An active Material Requirement already exists for this accepted revision.';
        end if;
    end if;

    insert into public.material_requirements (
        material_requirement_no,
        source_type,
        quotation_id,
        accepted_revision_id,
        project_id,
        site_id,
        requirement_date,
        required_by_date,
        requirement_status,
        delivery_destination_type,
        delivery_stock_location_id,
        responsible_auth_user_id,
        notes,
        created_by
    )
    values (
        null,
        v_source_type,
        v_quotation.quotation_id,
        v_quotation.accepted_revision_id,
        v_project_id,
        v_site_id,
        current_date,
        p_required_by_date,
        'Draft',
        case
            when p_delivery_stock_location_id is null then 'Site'
            else 'Warehouse'
        end,
        p_delivery_stock_location_id,
        p_responsible_auth_user_id,
        p_notes,
        v_user_id
    )
    returning material_requirement_id
    into v_material_requirement_id;

    if v_source_type = 'AcceptedQuotation' then
        insert into public.material_requirement_lines (
            material_requirement_id,
            line_no,
            line_origin,
            source_quotation_line_id,
            source_revision_line_id,
            project_area_id,
            source_product_id,
            source_product_code,
            source_product_name,
            source_description,
            source_uom_code,
            source_quantity,
            source_base_uom_code,
            source_conversion_factor,
            source_base_quantity,
            source_allow_fractional_quantity,
            source_is_optional,
            product_id,
            description,
            requirement_uom_code,
            requirement_quantity,
            base_uom_code,
            conversion_factor_to_base,
            allow_fractional_quantity,
            waste_percent,
            required_by_date,
            line_status,
            commercial_impact,
            variation_required,
            variation_status,
            created_by
        )
        select
            v_material_requirement_id,
            row_number() over (order by ql.line_no, ql.quotation_line_id)::integer,
            'CommercialSource',
            ql.quotation_line_id,
            null::uuid,
            ql.project_area_id,
            ql.product_id,
            p.product_code,
            p.product_name,
            ql.description,
            coalesce(ql.sales_uom_code, ql.unit_of_measure),
            ql.quantity,
            coalesce(ql.base_uom_code, ql.sales_uom_code, ql.unit_of_measure),
            coalesce(ql.conversion_factor, 1),
            coalesce(ql.base_quantity, ql.quantity * coalesce(ql.conversion_factor, 1)),
            coalesce(ql.allow_fractional_quantity, true),
            coalesce(ql.is_optional, false),
            ql.product_id,
            ql.description,
            coalesce(ql.sales_uom_code, ql.unit_of_measure),
            ql.quantity,
            coalesce(ql.base_uom_code, ql.sales_uom_code, ql.unit_of_measure),
            coalesce(ql.conversion_factor, 1),
            coalesce(ql.allow_fractional_quantity, true),
            0,
            p_required_by_date,
            'Required',
            'None',
            false,
            'NotRequired',
            v_user_id
        from public.quotation_lines ql
        left join public.products p
          on p.product_id = ql.product_id
        where ql.quotation_id = p_quotation_id
          and ql.is_deleted = false
          and coalesce(ql.is_optional, false) = false
          and (
              ql.product_id is null
              or coalesce(p.is_service_item, false) = false
          );

        get diagnostics v_inserted_line_count = row_count;
    else
        insert into public.material_requirement_lines (
            material_requirement_id,
            line_no,
            line_origin,
            source_quotation_line_id,
            source_revision_line_id,
            project_area_id,
            source_product_id,
            source_product_code,
            source_product_name,
            source_description,
            source_uom_code,
            source_quantity,
            source_base_uom_code,
            source_conversion_factor,
            source_base_quantity,
            source_allow_fractional_quantity,
            source_is_optional,
            product_id,
            description,
            requirement_uom_code,
            requirement_quantity,
            base_uom_code,
            conversion_factor_to_base,
            allow_fractional_quantity,
            waste_percent,
            required_by_date,
            line_status,
            commercial_impact,
            variation_required,
            variation_status,
            created_by
        )
        select
            v_material_requirement_id,
            row_number() over (order by qrl.line_no, qrl.revision_line_id)::integer,
            'CommercialSource',
            null::uuid,
            qrl.revision_line_id,
            qrl.project_area_id,
            qrl.product_id,
            p.product_code,
            p.product_name,
            qrl.description,
            coalesce(qrl.sales_uom_code, qrl.unit_of_measure),
            qrl.quantity,
            coalesce(qrl.base_uom_code, qrl.sales_uom_code, qrl.unit_of_measure),
            coalesce(qrl.conversion_factor, 1),
            coalesce(qrl.base_quantity, qrl.quantity * coalesce(qrl.conversion_factor, 1)),
            coalesce(qrl.allow_fractional_quantity, true),
            coalesce(qrl.is_optional, false),
            qrl.product_id,
            qrl.description,
            coalesce(qrl.sales_uom_code, qrl.unit_of_measure),
            qrl.quantity,
            coalesce(qrl.base_uom_code, qrl.sales_uom_code, qrl.unit_of_measure),
            coalesce(qrl.conversion_factor, 1),
            coalesce(qrl.allow_fractional_quantity, true),
            0,
            p_required_by_date,
            'Required',
            'None',
            false,
            'NotRequired',
            v_user_id
        from public.quotation_revision_lines qrl
        left join public.products p
          on p.product_id = qrl.product_id
        where qrl.revision_id = v_quotation.accepted_revision_id
          and qrl.is_deleted = false
          and coalesce(qrl.is_optional, false) = false
          and (
              qrl.product_id is null
              or coalesce(p.is_service_item, false) = false
          );

        get diagnostics v_inserted_line_count = row_count;
    end if;

    if v_inserted_line_count = 0 then
        raise exception 'No eligible non-optional, non-service lines were found for Material Requirement generation.';
    end if;

    return v_material_requirement_id;
end;
$$;


ALTER FUNCTION "public"."generate_material_requirement_from_accepted_quotation"("p_quotation_id" "uuid", "p_required_by_date" "date", "p_delivery_stock_location_id" "uuid", "p_responsible_auth_user_id" "uuid", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_material_requirement_from_accepted_variation"("p_variation_id" "uuid", "p_required_by_date" "date" DEFAULT NULL::"date", "p_delivery_stock_location_id" "uuid" DEFAULT NULL::"uuid", "p_responsible_auth_user_id" "uuid" DEFAULT NULL::"uuid", "p_notes" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    v_user_id uuid := auth.uid();
    v_variation public.variations%rowtype;
    v_mr_id uuid;
    v_inserted integer;
begin
    if v_user_id is null then
        raise exception 'Authentication is required.';
    end if;

    if not public.has_permission('material_requirements.create') then
        raise exception 'Permission denied: material_requirements.create is required.';
    end if;

    select *
    into v_variation
    from public.variations
    where variation_id = p_variation_id
      and variation_status = 'Accepted'
      and is_active = true
      and is_deleted = false
    for update;

    if not found then
        raise exception 'Material Requirement can only be generated from an Accepted Variation.';
    end if;

    if exists (
        select 1
        from public.material_requirements mr
        where mr.source_type = 'AcceptedVariation'
          and mr.source_variation_id = p_variation_id
          and mr.is_deleted = false
    ) then
        raise exception 'An active Material Requirement already exists for this Accepted Variation.';
    end if;

    insert into public.material_requirements (
        material_requirement_no,
        source_type,
        quotation_id,
        accepted_revision_id,
        source_variation_id,
        project_id,
        site_id,
        requirement_date,
        required_by_date,
        requirement_status,
        delivery_destination_type,
        delivery_stock_location_id,
        responsible_auth_user_id,
        notes,
        is_active,
        is_deleted,
        created_by,
        updated_by
    )
    values (
        null,
        'AcceptedVariation',
        v_variation.quotation_id,
        v_variation.accepted_revision_id,
        v_variation.variation_id,
        v_variation.project_id,
        v_variation.project_site_id,
        current_date,
        p_required_by_date,
        'Draft',
        case when p_delivery_stock_location_id is null then 'Site' else 'Warehouse' end,
        p_delivery_stock_location_id,
        p_responsible_auth_user_id,
        p_notes,
        true,
        false,
        v_user_id,
        v_user_id
    )
    returning material_requirement_id into v_mr_id;

    insert into public.material_requirement_lines (
        material_requirement_id,
        line_no,
        line_origin,
        source_quotation_line_id,
        source_revision_line_id,
        source_variation_line_id,
        project_area_id,
        source_product_id,
        source_product_code,
        source_product_name,
        source_description,
        source_uom_code,
        source_quantity,
        source_base_uom_code,
        source_conversion_factor,
        source_base_quantity,
        source_allow_fractional_quantity,
        source_is_optional,
        product_id,
        description,
        requirement_uom_code,
        requirement_quantity,
        base_uom_code,
        conversion_factor_to_base,
        allow_fractional_quantity,
        waste_percent,
        required_by_date,
        line_status,
        commercial_impact,
        variation_required,
        variation_status,
        created_by,
        updated_by
    )
    select
        v_mr_id,
        row_number() over (order by vl.line_no, vl.variation_line_id)::integer,
        'CommercialSource',
        null,
        null,
        vl.variation_line_id,
        vl.project_area_id,
        vl.product_id,
        p.product_code,
        p.product_name,
        vl.description,
        coalesce(vl.sales_uom_code, vl.unit_of_measure),
        vl.quantity,
        coalesce(vl.base_uom_code, vl.sales_uom_code, vl.unit_of_measure),
        coalesce(vl.conversion_factor, 1),
        coalesce(vl.base_quantity, vl.quantity * coalesce(vl.conversion_factor, 1)),
        coalesce(vl.allow_fractional_quantity, true),
        coalesce(vl.is_optional, false),
        vl.product_id,
        vl.description,
        coalesce(vl.sales_uom_code, vl.unit_of_measure),
        vl.quantity,
        coalesce(vl.base_uom_code, vl.sales_uom_code, vl.unit_of_measure),
        coalesce(vl.conversion_factor, 1),
        coalesce(vl.allow_fractional_quantity, true),
        0,
        p_required_by_date,
        'Required',
        'None',
        false,
        'NotRequired',
        v_user_id,
        v_user_id
    from public.variation_lines vl
    left join public.products p
      on p.product_id = vl.product_id
    where vl.variation_id = p_variation_id
      and vl.is_deleted = false
      and coalesce(vl.is_optional, false) = false
      and (
          vl.product_id is null
          or coalesce(p.is_service_item, false) = false
      );

    get diagnostics v_inserted = row_count;

    if v_inserted = 0 then
        raise exception 'No eligible non-optional, non-service Variation lines were found for Material Requirement generation.';
    end if;

    return v_mr_id;
end;
$$;


ALTER FUNCTION "public"."generate_material_requirement_from_accepted_variation"("p_variation_id" "uuid", "p_required_by_date" "date", "p_delivery_stock_location_id" "uuid", "p_responsible_auth_user_id" "uuid", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_product_code"("p_category_variant_id" "uuid", "p_product_code_type_id" "uuid", "p_size_rule_id" "uuid", "p_colour_id" "uuid", "p_first_value" integer DEFAULT NULL::integer, "p_second_value" integer DEFAULT NULL::integer) RETURNS TABLE("generated_product_code" "text", "full_category_code" "text", "type_code" "text", "size_token" "text", "colour_code" "text", "variant_number" smallint, "variant_code" "text", "generated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
    v_context record;
    v_variant smallint;
    v_inserted_variant smallint;
begin
    if not (
        public.is_admin_role()
        or public.is_project_role()
        or current_user in (
            'postgres',
            'service_role',
            'supabase_admin'
        )
    ) then
        raise exception
            'You do not have permission to generate Product Codes.';
    end if;

    select context_record.*
    into v_context
    from public.get_product_code_context(
        p_category_variant_id,
        p_product_code_type_id,
        p_size_rule_id,
        p_colour_id,
        p_first_value,
        p_second_value
    ) as context_record;

    -- First request for this exact combination starts at 01.
    --
    -- ON CONFLICT has no column target intentionally.
    -- This prevents PL/pgSQL output-column variables such as
    -- full_category_code and type_code from becoming ambiguous.
    insert into public.product_code_sequences (
        full_category_code,
        type_code,
        size_token,
        colour_code,
        last_variant_number
    )
    values (
        v_context.full_category_code,
        v_context.type_code,
        v_context.size_token,
        v_context.colour_code,
        1
    )
    on conflict do nothing
    returning
        product_code_sequences.last_variant_number
    into v_inserted_variant;

    if v_inserted_variant is not null then
        v_variant := v_inserted_variant;
    else
        -- Lock the existing row so concurrent requests cannot
        -- receive the same Variant Running Number.
        select
            sequence_record.last_variant_number
        into v_variant
        from public.product_code_sequences as sequence_record
        where sequence_record.full_category_code =
              v_context.full_category_code
          and sequence_record.type_code =
              v_context.type_code
          and sequence_record.size_token =
              v_context.size_token
          and sequence_record.colour_code =
              v_context.colour_code
        for update;

        if v_variant is null then
            raise exception
                'Unable to locate or lock the Product Code sequence.';
        end if;

        if v_variant >= 99 then
            raise exception
                'No Variant Running Number remains for %-%-%-%.',
                v_context.full_category_code,
                v_context.type_code,
                v_context.size_token,
                v_context.colour_code;
        end if;

        v_variant := v_variant + 1;

        update public.product_code_sequences as sequence_record
        set
            last_variant_number = v_variant
        where sequence_record.full_category_code =
              v_context.full_category_code
          and sequence_record.type_code =
              v_context.type_code
          and sequence_record.size_token =
              v_context.size_token
          and sequence_record.colour_code =
              v_context.colour_code;
    end if;

    return query
    select
        (
            v_context.full_category_code
            || '-' || v_context.type_code
            || '-' || v_context.size_token
            || '-' || v_context.colour_code
            || '-' || lpad(v_variant::text, 2, '0')
        )::text,
        v_context.full_category_code::text,
        v_context.type_code::text,
        v_context.size_token::text,
        v_context.colour_code::text,
        v_variant::smallint,
        lpad(v_variant::text, 2, '0')::text,
        now();
end;
$$;


ALTER FUNCTION "public"."generate_product_code"("p_category_variant_id" "uuid", "p_product_code_type_id" "uuid", "p_size_rule_id" "uuid", "p_colour_id" "uuid", "p_first_value" integer, "p_second_value" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."generate_product_code"("p_category_variant_id" "uuid", "p_product_code_type_id" "uuid", "p_size_rule_id" "uuid", "p_colour_id" "uuid", "p_first_value" integer, "p_second_value" integer) IS 'Atomically allocates and permanently consumes the next VV segment for a validated Product Code combination.';



CREATE OR REPLACE FUNCTION "public"."generate_product_code_variant"("p_category_variant_id" "uuid", "p_product_code_type_id" "uuid", "p_size_rule_id" "uuid", "p_colour_id" "uuid", "p_first_value" integer DEFAULT NULL::integer, "p_second_value" integer DEFAULT NULL::integer, "p_variant_number" smallint DEFAULT NULL::smallint, "p_variant_name" "text" DEFAULT NULL::"text", "p_variant_description" "text" DEFAULT NULL::"text") RETURNS TABLE("generated_product_code" "text", "full_category_code" "text", "type_code" "text", "size_token" "text", "colour_code" "text", "variant_number" smallint, "variant_code" "text", "variant_name" "text", "variant_description" "text", "generated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
    v_context record;
    v_variant_code text;
    v_variant_name text;
    v_variant_description text;
    v_full_product_code text;
    v_reserved_at timestamptz;
begin
    if not public.can_manage_products_strict() then
        raise exception
            'Only Admin can assign a Product Variant Code.';
    end if;

    if p_variant_number is null
       or p_variant_number < 1
       or p_variant_number > 99 then
        raise exception
            'Variant Code must be between 01 and 99.';
    end if;

    v_variant_name := nullif(btrim(p_variant_name), '');

    if v_variant_name is null then
        raise exception
            'Variant Name is required.';
    end if;

    if char_length(v_variant_name) < 2
       or char_length(v_variant_name) > 120 then
        raise exception
            'Variant Name must contain between 2 and 120 characters.';
    end if;

    v_variant_description :=
        nullif(btrim(p_variant_description), '');

    if v_variant_description is not null
       and (
           char_length(v_variant_description) < 2
           or char_length(v_variant_description) > 500
       ) then
        raise exception
            'Variant Description must contain between 2 and 500 characters.';
    end if;

    select context_record.*
    into v_context
    from public.get_product_code_context(
        p_category_variant_id,
        p_product_code_type_id,
        p_size_rule_id,
        p_colour_id,
        p_first_value,
        p_second_value
    ) as context_record;

    v_variant_code := lpad(p_variant_number::text, 2, '0');

    v_full_product_code :=
        v_context.full_category_code
        || '-' || v_context.type_code
        || '-' || v_context.size_token
        || '-' || v_context.colour_code
        || '-' || v_variant_code;

    begin
        insert into public.product_code_variant_registry (
            full_category_code,
            type_code,
            size_token,
            colour_code,
            variant_number,
            variant_code,
            variant_name,
            variant_description,
            full_product_code,
            reserved_by
        )
        values (
            v_context.full_category_code,
            v_context.type_code,
            v_context.size_token,
            v_context.colour_code,
            p_variant_number,
            v_variant_code,
            v_variant_name,
            v_variant_description,
            v_full_product_code,
            auth.uid()
        )
        returning reserved_at
        into v_reserved_at;

    exception
        when unique_violation then
            raise exception
                'Variant Code % has already been used for Product Code base %-%-%-%.',
                v_variant_code,
                v_context.full_category_code,
                v_context.type_code,
                v_context.size_token,
                v_context.colour_code;
    end;

    return query
    select
        v_full_product_code::text,
        v_context.full_category_code::text,
        v_context.type_code::text,
        v_context.size_token::text,
        v_context.colour_code::text,
        p_variant_number::smallint,
        v_variant_code::text,
        v_variant_name,
        v_variant_description,
        v_reserved_at;
end;
$$;


ALTER FUNCTION "public"."generate_product_code_variant"("p_category_variant_id" "uuid", "p_product_code_type_id" "uuid", "p_size_rule_id" "uuid", "p_colour_id" "uuid", "p_first_value" integer, "p_second_value" integer, "p_variant_number" smallint, "p_variant_name" "text", "p_variant_description" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_project_area_code"() RETURNS "text"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    v_next_number bigint;
begin
    v_next_number :=
        nextval('public.project_area_code_seq');

    if v_next_number > 999 then
        raise exception
            'Project area code limit reached. Maximum code is AREA-999.';
    end if;

    return
        'AREA-' ||
        lpad(v_next_number::text, 3, '0');
end;
$$;


