CREATE OR REPLACE FUNCTION "public"."generate_work_order_no"("p_created_at" timestamp with time zone DEFAULT "now"()) RETURNS "text"
    LANGUAGE "plpgsql"
    AS $_$
declare
  v_period text;
  v_prefix text;
  v_next_number integer;
  v_work_order_no text;
begin
  -- Australia/Sydney document period
  -- Example: 2026-07 => 2607
  v_period := to_char(p_created_at at time zone 'Australia/Sydney', 'YYMM');

  -- Final prefix example: WO2607
  v_prefix := 'WO' || v_period;

  -- Prevent duplicate numbers if two users create work orders at the same time.
  perform pg_advisory_xact_lock(hashtext('work_order_no_' || v_prefix));

  select coalesce(
    max(substring(work_order_no from 8 for 5)::integer),
    0
  ) + 1
  into v_next_number
  from public.work_orders
  where work_order_no ~ ('^' || v_prefix || '-[0-9]{5}$');

  v_work_order_no := v_prefix || '-' || lpad(v_next_number::text, 5, '0');

  return v_work_order_no;
end;
$_$;


