CREATE OR REPLACE FUNCTION "public"."get_customer_financial_profile"("p_customer_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    v_base public._customer_profile_base%rowtype;
    v_readiness public._customer_xero_readiness%rowtype;
    v_can_view_xero boolean;
begin
    perform public.assert_invoice_permission('invoices.view');

    select *
    into v_base
    from public._customer_profile_base
    where customer_id = p_customer_id;

    if not found then
        raise exception 'Customer not found.';
    end if;

    select *
    into v_readiness
    from public._customer_xero_readiness
    where customer_id = p_customer_id;

    v_can_view_xero :=
        public.has_permission('xero.customer_profile_view');

    return jsonb_build_object(
        'customer', jsonb_build_object(
            'customer_id', v_base.customer_id,
            'customer_code', v_base.customer_code,
            'customer_name', v_base.customer_name,
            'customer_type', v_base.customer_type,
            'price_book_id', v_base.price_book_id,
            'phone', v_base.phone,
            'email', v_base.email,
            'abn', v_base.abn,
            'notes', v_base.notes,
            'is_active', v_base.is_active
        ),

        'primary_contact', jsonb_build_object(
            'contact_id', v_base.primary_contact_id,
            'contact_name', v_base.primary_contact_name,
            'position', v_base.primary_contact_position,
            'phone', coalesce(
                v_base.primary_contact_phone,
                v_base.phone
            ),
            'email', coalesce(
                v_base.primary_contact_email,
                v_base.email
            )
        ),

        'contacts', v_base.contacts,

        'primary_address', jsonb_build_object(
            'address_id', v_base.primary_address_id,
            'address_type', v_base.primary_address_type,
            'address_line1', v_base.primary_address_line1,
            'address_line2', v_base.primary_address_line2,
            'suburb', v_base.primary_address_suburb,
            'state', v_base.primary_address_state,
            'postcode', v_base.primary_address_postcode,
            'country', v_base.primary_address_country
        ),

        'addresses', v_base.addresses,

        'financial_settings', jsonb_build_object(
            'has_financial_settings',
                v_base.has_financial_settings,
            'default_currency',
                v_base.default_currency,
            'default_sales_account_code',
                v_base.default_sales_account_code,
            'default_tax_type',
                v_base.default_tax_type,
            'line_amount_type',
                v_base.line_amount_type,
            'discount_percent',
                v_base.discount_percent,
            'payment_terms_type',
                v_base.payment_terms_type,
            'payment_terms_days',
                v_base.payment_terms_days,
            'credit_limit',
                v_base.credit_limit,
            'is_account_on_hold',
                v_base.is_account_on_hold,
            'account_hold_reason',
                v_base.account_hold_reason,
            'invoice_delivery_method',
                v_base.invoice_delivery_method,
            'statement_delivery_method',
                v_base.statement_delivery_method
        ),

        'management_summary', jsonb_build_object(
            'project_count',
                v_base.project_count,
            'active_project_count',
                v_base.active_project_count,
            'completed_project_count',
                v_base.completed_project_count,
            'draft_invoice_count',
                v_base.draft_invoice_count,
            'issued_invoice_count',
                v_base.issued_invoice_count,
            'overdue_invoice_count',
                v_base.overdue_invoice_count,
            'total_invoiced',
                v_base.total_invoiced,
            'total_paid',
                v_base.total_paid,
            'total_outstanding',
                v_base.total_outstanding,
            'current_outstanding',
                v_base.current_outstanding,
            'overdue_outstanding',
                v_base.overdue_outstanding,
            'recorded_payment_total',
                v_base.recorded_payment_total,
            'unallocated_credit',
                v_base.unallocated_credit,
            'available_credit',
                v_base.available_credit,
            'maximum_days_overdue',
                v_base.maximum_days_overdue
        ),

        'aging', jsonb_build_object(
            'current', v_base.aging_current,
            'days_1_30', v_base.aging_1_30,
            'days_31_60', v_base.aging_31_60,
            'days_61_90', v_base.aging_61_90,
            'days_90_plus', v_base.aging_90_plus,
            'oldest_due_date', v_base.oldest_due_date,
            'maximum_days_overdue',
                v_base.maximum_days_overdue
        ),

        'projects', v_base.projects,

        'recent_invoices', coalesce((
            select jsonb_agg(to_jsonb(invoice_row))
            from (
                select
                    i.customer_invoice_id,
                    i.invoice_no,
                    i.invoice_type,
                    i.document_status,
                    i.payment_status,
                    i.invoice_date,
                    i.due_date,
                    i.total_amount,
                    i.paid_amount,
                    i.balance_amount,
                    i.currency_code,
                    i.customer_reference,
                    i.project_id,
                    p.project_no,
                    p.project_name
                from public.customer_invoices i
                left join public.projects p
                  on p.project_id = i.project_id
                where i.customer_id = p_customer_id
                  and i.is_deleted = false
                order by
                    i.invoice_date desc,
                    i.invoice_no desc
                limit 20
            ) invoice_row
        ), '[]'::jsonb),

        'recent_payments', coalesce((
            select jsonb_agg(to_jsonb(payment_row))
            from (
                select
                    p.customer_payment_id,
                    p.payment_no,
                    p.payment_date,
                    p.payment_method,
                    p.amount,
                    p.currency_code,
                    p.reference_no,
                    p.payment_status,
                    public._payment_allocated_amount(
                        p.customer_payment_id
                    ) as allocated_amount,
                    greatest(
                        p.amount
                        - public._payment_allocated_amount(
                            p.customer_payment_id
                        ),
                        0
                    ) as unallocated_amount
                from public.customer_payments p
                where p.customer_id = p_customer_id
                  and p.is_deleted = false
                order by
                    p.payment_date desc,
                    p.payment_no desc
                limit 20
            ) payment_row
        ), '[]'::jsonb),

        'retention_summary', coalesce((
            select jsonb_build_object(
                'retained_amount',
                    coalesce(sum(s.retained_amount), 0),
                'released_amount',
                    coalesce(sum(s.released_amount), 0),
                'available_retention_balance',
                    coalesce(
                        sum(s.available_retention_balance),
                        0
                    ),
                'site_count',
                    count(*)
            )
            from public._site_retention_summary s
            where s.customer_id = p_customer_id
        ), jsonb_build_object(
            'retained_amount', 0,
            'released_amount', 0,
            'available_retention_balance', 0,
            'site_count', 0
        )),

        'xero', case
            when v_can_view_xero then
                jsonb_build_object(
                    'xero_contact_id',
                        v_base.xero_contact_id,
                    'xero_contact_name',
                        v_base.xero_contact_name,
                    'xero_contact_number',
                        v_base.xero_contact_number,
                    'xero_status',
                        v_base.xero_status,
                    'xero_last_synced_at',
                        v_base.xero_last_synced_at,
                    'xero_sync_error',
                        v_base.xero_sync_error,
                    'xero_branding_theme_id',
                        v_base.xero_branding_theme_id,
                    'xero_branding_theme_name',
                        v_base.xero_branding_theme_name,
                    'xero_export_count',
                        v_base.xero_export_count,
                    'xero_export_success_count',
                        v_base.xero_export_success_count,
                    'xero_export_failed_count',
                        v_base.xero_export_failed_count,
                    'last_xero_export_at',
                        v_base.last_xero_export_at,
                    'last_xero_export_status',
                        v_base.last_xero_export_status,
                    'last_xero_export_error',
                        v_base.last_xero_export_error,
                    'export_history',
                        v_base.xero_export_history,
                    'readiness',
                        to_jsonb(v_readiness)
                        - 'customer_id'
                        - 'customer_code'
                        - 'customer_name'
                )
            else null
        end
    );
end;
$$;


