COMMENT ON FUNCTION "public"."get_customer_financial_profile"("p_customer_id" "uuid") IS 'Complete Customer workspace read model: overview, contacts, addresses, financial settings, projects, invoices, payments, retention, aging and masked Xero information.';



CREATE OR REPLACE FUNCTION "public"."get_customer_invoice_detail"("p_invoice_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    v_result jsonb;
begin
    perform public.assert_invoice_permission('invoices.view');

    select jsonb_build_object(
        'invoice', to_jsonb(base),

        'lines', coalesce((
            select jsonb_agg(
                jsonb_build_object(
                    'customer_invoice_item_id',
                        li.customer_invoice_item_id,
                    'line_no',
                        li.line_no,
                    'description',
                        li.description,
                    'quantity',
                        li.quantity,
                    'unit_price',
                        li.unit_price,
                    'tax_rate',
                        li.tax_rate,
                    'tax_amount',
                        li.tax_amount,
                    'line_total',
                        li.line_total
                )
                order by li.line_no
            )
            from public.customer_invoice_items li
            where li.customer_invoice_id = base.customer_invoice_id
              and li.is_deleted = false
        ), '[]'::jsonb),

        'sources', coalesce((
            select jsonb_agg(
                jsonb_build_object(
                    'invoice_source_id',
                        s.invoice_source_id,
                    'source_type',
                        s.source_type,
                    'source_id',
                        s.source_id,
                    'source_amount',
                        s.source_amount,
                    'source_reference',
                        case
                            when s.source_type = 'Quotation'
                            then (
                                select q.quotation_no
                                from public.quotations q
                                where q.quotation_id = s.source_id
                            )

                            when s.source_type = 'Variation'
                            then (
                                select v.variation_no
                                from public.variations v
                                where v.variation_id = s.source_id
                            )

                            else null
                        end
                )
                order by s.created_at
            )
            from public.invoice_sources s
            where s.customer_invoice_id = base.customer_invoice_id
              and s.is_deleted = false
        ), '[]'::jsonb),

        'payments', coalesce((
            select jsonb_agg(
                jsonb_build_object(
                    'customer_payment_allocation_id',
                        a.customer_payment_allocation_id,
                    'customer_payment_id',
                        p.customer_payment_id,
                    'payment_no',
                        p.payment_no,
                    'payment_date',
                        p.payment_date,
                    'payment_method',
                        p.payment_method,
                    'reference_no',
                        p.reference_no,
                    'allocated_amount',
                        a.allocated_amount,
                    'currency_code',
                        p.currency_code
                )
                order by p.payment_date, p.payment_no
            )
            from public.customer_payment_allocations a
            join public.customer_payments p
              on p.customer_payment_id = a.customer_payment_id
            where a.customer_invoice_id = base.customer_invoice_id
              and a.is_deleted = false
              and a.reversed_at is null
              and p.is_deleted = false
              and p.payment_status = 'Recorded'
        ), '[]'::jsonb),

        'retention_ledger', coalesce((
            select jsonb_agg(
                jsonb_build_object(
                    'retention_ledger_id',
                        rl.retention_ledger_id,
                    'ledger_entry_type',
                        rl.ledger_entry_type,
                    'amount',
                        rl.amount,
                    'entry_date',
                        rl.entry_date,
                    'description',
                        rl.description,
                    'reference_no',
                        rl.reference_no
                )
                order by rl.entry_date, rl.created_at
            )
            from public.retention_ledger rl
            where rl.source_invoice_id = base.customer_invoice_id
               or rl.customer_invoice_id = base.customer_invoice_id
        ), '[]'::jsonb)

    )
    into v_result
    from public._invoice_reporting_base base
    where base.customer_invoice_id = p_invoice_id;

    if v_result is null then
        raise exception 'Invoice not found.';
    end if;

    return v_result;
end;
$$;


