CREATE OR REPLACE FUNCTION "public"."get_customer_payment_detail"("p_payment_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    v_result jsonb;
begin
    perform public.assert_invoice_permission('payments.view');

    select jsonb_build_object(
        'payment', to_jsonb(base),

        'allocations', coalesce((
            select jsonb_agg(
                jsonb_build_object(
                    'customer_payment_allocation_id',
                        a.customer_payment_allocation_id,
                    'customer_invoice_id',
                        i.customer_invoice_id,
                    'invoice_no',
                        i.invoice_no,
                    'invoice_date',
                        i.invoice_date,
                    'due_date',
                        i.due_date,
                    'invoice_total',
                        i.total_amount,
                    'allocated_amount',
                        a.allocated_amount,
                    'allocation_reversed_at',
                        a.reversed_at,
                    'allocation_reversal_reason',
                        a.reversal_reason
                )
                order by i.invoice_no
            )
            from public.customer_payment_allocations a
            join public.customer_invoices i
              on i.customer_invoice_id = a.customer_invoice_id
            where a.customer_payment_id = base.customer_payment_id
              and a.is_deleted = false
        ), '[]'::jsonb)

    )
    into v_result
    from public._payment_reporting_base base
    where base.customer_payment_id = p_payment_id;

    if v_result is null then
        raise exception 'Customer Payment not found.';
    end if;

    return v_result;
end;
$$;


