COMMENT ON FUNCTION "public"."get_customer_payment_detail"("p_payment_id" "uuid") IS 'Returns Customer Payment header and allocation history as JSON.';



CREATE OR REPLACE FUNCTION "public"."get_customer_xero_contact_payload"("p_customer_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    v_base public._customer_profile_base%rowtype;
    v_readiness public._customer_xero_readiness%rowtype;
begin
    if not public.has_permission(
        'xero.customer_payload_view'
    ) then
        raise exception
            'Permission denied: xero.customer_payload_view is required.';
    end if;

    select *
    into v_base
    from public._customer_profile_base
    where customer_id = p_customer_id;

    if not found then
        raise exception 'Customer not found.';
    end if;

    select *
    into v_readiness
    from public._customer_xero_readiness
    where customer_id = p_customer_id;

    return jsonb_build_object(
        'ContactID',
            v_base.xero_contact_id,
        'ContactNumber',
            coalesce(
                v_base.xero_contact_number,
                v_base.customer_code
            ),
        'Name',
            coalesce(
                v_base.xero_contact_name,
                v_base.customer_name
            ),
        'AccountNumber',
            v_base.customer_code,
        'TaxNumber',
            v_base.abn,
        'EmailAddress',
            coalesce(
                v_base.primary_contact_email,
                v_base.email
            ),
        'Phones', jsonb_build_array(
            jsonb_build_object(
                'PhoneType', 'DEFAULT',
                'PhoneNumber',
                    coalesce(
                        v_base.primary_contact_phone,
                        v_base.phone
                    )
            )
        ),
        'ContactPersons',
            v_base.contacts,
        'Addresses',
            v_base.addresses,
        'DefaultCurrency',
            v_base.default_currency,
        'SalesDefaultAccountCode',
            v_base.default_sales_account_code,
        'SalesDefaultTaxType',
            v_base.default_tax_type,
        'Discount',
            v_base.discount_percent,
        'PaymentTerms', jsonb_build_object(
            'Bills', jsonb_build_object(
                'Day',
                    v_base.payment_terms_days,
                'Type',
                    v_base.payment_terms_type
            )
        ),
        'BrandingThemeID',
            v_base.xero_branding_theme_id,
        'IsAccountOnHold',
            v_base.is_account_on_hold,
        'REDSMetadata', jsonb_build_object(
            'customer_id',
                v_base.customer_id,
            'customer_code',
                v_base.customer_code,
            'customer_type',
                v_base.customer_type,
            'invoice_delivery_method',
                v_base.invoice_delivery_method,
            'statement_delivery_method',
                v_base.statement_delivery_method,
            'line_amount_type',
                v_base.line_amount_type,
            'xero_status',
                v_base.xero_status,
            'is_xero_minimum_ready',
                v_readiness.is_xero_minimum_ready,
            'is_xero_accounting_ready',
                v_readiness.is_xero_accounting_ready,
            'readiness_issues',
                v_readiness.readiness_issues,
            'schema_limitations',
                jsonb_build_array(
                    'Customer bank account fields are not present.',
                    'A separate xero_sync_logs table is not present; xero_export_logs is used.'
                )
        )
    );
end;
$$;


