COMMENT ON FUNCTION "public"."get_customer_xero_contact_payload"("p_customer_id" "uuid") IS 'Admin/Manager/Accounts-only Xero-ready Customer Contact payload with readiness and schema limitation metadata.';



CREATE OR REPLACE FUNCTION "public"."get_effective_notification_permission"("p_auth_user_id" "uuid", "p_event_code" "text") RETURNS TABLE("auth_user_id" "uuid", "event_code" "text", "override_value" "text", "role_default_enabled" boolean, "effective_enabled" boolean, "permission_source" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
    with user_override as (
        select override_row.override_value
        from public.notification_user_event_overrides override_row
        where override_row.auth_user_id = p_auth_user_id
          and override_row.event_code = p_event_code
        limit 1
    ),
    role_default as (
        select coalesce(bool_or(default_row.is_enabled), false) as is_enabled
        from public.app_user_roles user_role
        join public.app_roles role
          on role.role_id = user_role.role_id
         and role.is_active = true
        left join public.notification_role_event_defaults default_row
          on default_row.role_id = role.role_id
         and default_row.event_code = p_event_code
        where user_role.auth_user_id = p_auth_user_id
          and user_role.is_active = true
          and user_role.ended_at is null
    )
    select
        p_auth_user_id,
        p_event_code,
        user_override.override_value,
        coalesce(role_default.is_enabled, false),
        case
            when user_override.override_value = 'Allow' then true
            when user_override.override_value = 'Deny' then false
            else coalesce(role_default.is_enabled, false)
        end,
        case
            when user_override.override_value = 'Allow' then 'User Allow'
            when user_override.override_value = 'Deny' then 'User Deny'
            else 'Role Default'
        end
    from role_default
    left join user_override on true;
$$;


ALTER FUNCTION "public"."get_effective_notification_permission"("p_auth_user_id" "uuid", "p_event_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_effective_product_category_attributes"("p_category_id" "uuid") RETURNS TABLE("category_attribute_id" "uuid", "source_category_id" "uuid", "source_category_name" "text", "source_depth" integer, "attribute_id" "uuid", "attribute_code" "text", "attribute_name" "text", "effective_label" "text", "description" "text", "data_type" "text", "unit_uom_code" "text", "unit_name" "text", "unit_symbol" "text", "section_name" "text", "effective_help_text" "text", "effective_default_value" "jsonb", "validation_rules" "jsonb", "is_required" boolean, "is_searchable" boolean, "is_filterable" boolean, "sort_order" integer)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
    with ancestors as (
        select *
        from public.get_product_category_ancestors(p_category_id)
    ),
    candidates as (
        select
            ca.category_attribute_id,
            ca.category_id as source_category_id,
            a.category_name as source_category_name,
            a.category_depth as source_depth,

            ca.attribute_id,
            d.attribute_code,
            d.attribute_name,
            coalesce(
                nullif(btrim(ca.display_label_override), ''),
                d.attribute_name
            ) as effective_label,
            d.description,
            d.data_type,

            d.unit_uom_code,
            u.uom_name as unit_name,
            u.uom_symbol as unit_symbol,

            ca.section_name,
            coalesce(
                nullif(btrim(ca.help_text_override), ''),
                d.help_text
            ) as effective_help_text,
            coalesce(
                ca.default_value_override,
                d.default_value
            ) as effective_default_value,

            d.validation_rules,
            ca.is_required,
            d.is_searchable,
            d.is_filterable,

            ca.sort_order,
            ca.is_hidden,

            row_number() over (
                partition by ca.attribute_id
                order by
                    a.category_depth asc,
                    ca.updated_at desc,
                    ca.category_attribute_id
            ) as winner_rank
        from ancestors a
        join public.product_category_attributes ca
          on ca.category_id = a.category_id
         and ca.is_deleted = false
         and ca.is_active = true
        join public.product_attribute_definitions d
          on d.attribute_id = ca.attribute_id
         and d.is_deleted = false
         and d.is_active = true
        left join public.units_of_measure u
          on u.uom_code = d.unit_uom_code
         and u.is_deleted = false
        where
            a.category_depth = 0
            or ca.is_inherited = true
    )
    select
        category_attribute_id,
        source_category_id,
        source_category_name,
        source_depth,

        attribute_id,
        attribute_code,
        attribute_name,
        effective_label,
        description,
        data_type,

        unit_uom_code,
        unit_name,
        unit_symbol,

        section_name,
        effective_help_text,
        effective_default_value,

        validation_rules,
        is_required,
        is_searchable,
        is_filterable,

        sort_order
    from candidates
    where winner_rank = 1
      and is_hidden = false
    order by
        section_name,
        sort_order,
        effective_label;
$$;


ALTER FUNCTION "public"."get_effective_product_category_attributes"("p_category_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_effective_product_category_attributes"("p_category_id" "uuid") IS 'Returns effective active attributes for a category. The nearest child mapping wins; child mappings can override or hide inherited fields.';



