CREATE OR REPLACE FUNCTION "public"."get_missing_required_product_attributes"("p_product_id" "uuid") RETURNS TABLE("attribute_id" "uuid", "attribute_code" "text", "attribute_label" "text", "data_type" "text", "section_name" "text")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
    with selected_product as (
        select
            p.product_id,
            p.category_id
        from public.products p
        where p.product_id = p_product_id
          and p.is_deleted = false
    ),
    required_attributes as (
        select effective.*
        from selected_product p
        cross join lateral
            public.get_effective_product_category_attributes(
                p.category_id
            ) effective
        where effective.is_required = true
    )
    select
        required_attributes.attribute_id,
        required_attributes.attribute_code,
        required_attributes.effective_label,
        required_attributes.data_type,
        required_attributes.section_name
    from required_attributes
    left join public.product_attribute_values value_row
      on value_row.product_id = p_product_id
     and value_row.attribute_id =
         required_attributes.attribute_id
     and value_row.is_deleted = false
    where
        value_row.product_attribute_value_id is null

        or (
            required_attributes.data_type = 'multi_select'
            and not exists (
                select 1
                from public.product_attribute_value_options selected
                where selected.product_attribute_value_id =
                      value_row.product_attribute_value_id
            )
        )
    order by
        required_attributes.section_name,
        required_attributes.sort_order,
        required_attributes.effective_label;
$$;


