CREATE OR REPLACE FUNCTION "public"."get_next_available_product_variant_number"("p_full_category_code" "text", "p_type_code" "text", "p_size_token" "text", "p_colour_code" "text") RETURNS smallint
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
declare
    v_next smallint;
begin
    select candidate.variant_number::smallint
    into v_next
    from generate_series(1, 99) as candidate(variant_number)
    where not exists (
        select 1
        from public.product_code_variant_registry registry
        where registry.full_category_code = p_full_category_code
          and registry.type_code = p_type_code
          and registry.size_token = p_size_token
          and registry.colour_code = p_colour_code
          and registry.variant_number = candidate.variant_number
    )
    order by candidate.variant_number
    limit 1;

    if v_next is null then
        raise exception
            'No Product Variant Code remains for %-%-%-%.',
            p_full_category_code,
            p_type_code,
            p_size_token,
            p_colour_code;
    end if;

    return v_next;
end;
$$;


ALTER FUNCTION "public"."get_next_available_product_variant_number"("p_full_category_code" "text", "p_type_code" "text", "p_size_token" "text", "p_colour_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_product_category_ancestors"("p_category_id" "uuid") RETURNS TABLE("category_id" "uuid", "parent_category_id" "uuid", "category_name" "text", "category_depth" integer)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
    with recursive category_chain as (
        select
            c.category_id,
            c.parent_category_id,
            c.category_name,
            0::integer as category_depth,
            array[c.category_id]::uuid[] as visited_ids
        from public.product_categories c
        where c.category_id = p_category_id
          and c.is_deleted = false

        union all

        select
            parent.category_id,
            parent.parent_category_id,
            parent.category_name,
            child.category_depth + 1,
            child.visited_ids || parent.category_id
        from category_chain child
        join public.product_categories parent
          on parent.category_id = child.parent_category_id
         and parent.is_deleted = false
        where not parent.category_id = any(child.visited_ids)
    )
    select
        category_id,
        parent_category_id,
        category_name,
        category_depth
    from category_chain;
$$;


ALTER FUNCTION "public"."get_product_category_ancestors"("p_category_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_product_category_ancestors"("p_category_id" "uuid") IS 'Returns selected product category at depth 0 followed by its parents. Includes cycle protection.';



CREATE OR REPLACE FUNCTION "public"."get_product_code_context"("p_category_variant_id" "uuid", "p_product_code_type_id" "uuid", "p_size_rule_id" "uuid", "p_colour_id" "uuid", "p_first_value" integer DEFAULT NULL::integer, "p_second_value" integer DEFAULT NULL::integer) RETURNS TABLE("full_category_code" "text", "category_variant_name" "text", "family_code" "text", "family_name" "text", "type_code" "text", "type_name" "text", "size_token" "text", "size_rule_name" "text", "colour_code" "text", "colour_name" "text")
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
declare
    v_variant public.product_code_category_variants%rowtype;
    v_family public.product_code_families%rowtype;
    v_type public.product_code_types%rowtype;
    v_colour public.product_colours%rowtype;
    v_effective_size_rule_id uuid;
    v_effective_colour_mode text;
begin
    select *
    into v_variant
    from public.product_code_category_variants
    where product_code_category_variant_id = p_category_variant_id
      and is_deleted = false
      and is_active = true
      and status = 'active';

    if not found then
        raise exception
            'The selected Category Variant is not active or does not exist.';
    end if;

    select *
    into v_family
    from public.product_code_families
    where product_code_family_id = v_variant.product_code_family_id
      and is_deleted = false
      and is_active = true
      and status = 'active';

    if not found then
        raise exception
            'The Product Family for the selected Category Variant is not active.';
    end if;

    select *
    into v_type
    from public.product_code_types
    where product_code_type_id = p_product_code_type_id
      and is_deleted = false
      and is_active = true
      and status = 'active';

    if not found then
        raise exception
            'The selected Product Type Code is not active or does not exist.';
    end if;

    if not exists (
        select 1
        from public.product_code_family_types allowed_type
        where allowed_type.product_code_family_id =
              v_family.product_code_family_id
          and allowed_type.product_code_type_id =
              p_product_code_type_id
          and allowed_type.is_deleted = false
          and allowed_type.is_active = true
    ) then
        raise exception
            'Product Type % is not allowed for Product Family %.',
            v_type.type_code,
            v_family.family_code;
    end if;

    v_effective_size_rule_id := coalesce(
        p_size_rule_id,
        v_variant.size_rule_id,
        v_family.default_size_rule_id
    );

    if v_effective_size_rule_id is null then
        raise exception
            'No Product Code Size Rule is configured for Product Family %.',
            v_family.family_code;
    end if;

    select *
    into v_colour
    from public.product_colours
    where product_colour_id = p_colour_id
      and is_deleted = false
      and is_active = true
      and status = 'active';

    if not found then
        raise exception
            'The selected Product Colour is not active or does not exist.';
    end if;

    v_effective_colour_mode := coalesce(
        v_variant.colour_mode_override,
        v_family.colour_mode
    );

    if v_effective_colour_mode = 'not_applicable'
       and v_colour.colour_code <> 'XXX' then
        raise exception
            'Product Family % requires Colour XXX (Not Applicable).',
            v_family.family_code;
    end if;

    if v_effective_colour_mode = 'required'
       and v_colour.colour_code = 'XXX' then
        raise exception
            'A Product Colour is required for Product Family %.',
            v_family.family_code;
    end if;

    return query
    select
        v_variant.full_category_code,
        v_variant.variant_name,
        v_family.family_code,
        v_family.family_name,
        v_type.type_code,
        v_type.type_name,
        public.build_product_code_size_token(
            v_effective_size_rule_id,
            p_first_value,
            p_second_value
        ),
        size_rule.size_rule_name,
        v_colour.colour_code,
        v_colour.colour_name
    from public.product_code_size_rules size_rule
    where size_rule.product_code_size_rule_id =
          v_effective_size_rule_id
      and size_rule.is_deleted = false
      and size_rule.is_active = true
      and size_rule.status = 'active';
end;
$$;


ALTER FUNCTION "public"."get_product_code_context"("p_category_variant_id" "uuid", "p_product_code_type_id" "uuid", "p_size_rule_id" "uuid", "p_colour_id" "uuid", "p_first_value" integer, "p_second_value" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_quotation_detail"("p_quotation_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    v_user_id uuid;

    v_can_view_internal boolean;
    v_can_view_cost boolean;
    v_can_view_margin boolean;

    v_result jsonb;
begin
    -- ========================================================================
    -- 1. AUTHENTICATION AND PERMISSION
    -- ========================================================================

    v_user_id := auth.uid();

    if v_user_id is null then
        raise exception
            'Authentication is required.';
    end if;

    if not public.has_permission(
        'quotations.view'
    ) then
        raise exception
            'Permission denied: quotations.view is required.';
    end if;

    v_can_view_internal :=
        public.has_permission(
            'quotations.view_internal'
        );

    v_can_view_cost :=
        public.has_permission(
            'quotations.view_cost'
        );

    v_can_view_margin :=
        public.has_permission(
            'quotations.view_margin'
        );


    -- ========================================================================
    -- 2. INPUT VALIDATION
    -- ========================================================================

    if p_quotation_id is null then
        raise exception
            'Quotation ID is required.';
    end if;


    -- ========================================================================
    -- 3. BUILD DETAIL RESPONSE
    -- ========================================================================

    select jsonb_build_object(
        'permissions',
            jsonb_build_object(
                'view',
                    true,

                'view_internal',
                    v_can_view_internal,

                'view_cost',
                    v_can_view_cost,

                'view_margin',
                    v_can_view_margin
            ),

        'quotation',
            jsonb_build_object(
                'quotation_id',
                    q.quotation_id,

                'quotation_no',
                    q.quotation_no,

                'quotation_status',
                    q.quotation_status,

                'revision_no',
                    q.revision_no,

                'customer_id',
                    q.customer_id,

                'project_site_id',
                    q.project_site_id,

                'price_book_id',
                    q.price_book_id,

                'quotation_segment',
                    q.quotation_segment,

                'quotation_source',
                    q.quotation_source,

                'issue_date',
                    q.issue_date,

                'valid_until',
                    q.valid_until,

                'subtotal_amount',
                    q.subtotal_amount,

                'discount_amount',
                    q.discount_amount,

                'tax_amount',
                    q.tax_amount,

                'total_amount',
                    q.total_amount,

                'notes',
                    q.notes,

                'internal_notes',
                    case
                        when v_can_view_internal
                            then q.internal_notes
                        else null
                    end,

                'current_revision_id',
                    q.current_revision_id,

                'accepted_revision_id',
                    q.accepted_revision_id,

                'sent_at',
                    q.sent_at,

                'accepted_at',
                    q.accepted_at,

                'acceptance_notes',
                    q.acceptance_notes,

                'rejected_at',
                    q.rejected_at,

                'rejection_reason',
                    case
                        when v_can_view_internal
                            then q.rejection_reason
                        else null
                    end,

                'cancelled_at',
                    q.cancelled_at,

                'cancellation_reason',
                    case
                        when v_can_view_internal
                            then q.cancellation_reason
                        else null
                    end,

                'created_at',
                    q.created_at,

                'updated_at',
                    q.updated_at
            ),

        'context',
            jsonb_build_object(
                'customer',
                    jsonb_build_object(
                        'customer_id',
                            c.customer_id,

                        'customer_code',
                            c.customer_code,

                        'customer_name',
                            c.customer_name
                    ),

                'project',
                    jsonb_build_object(
                        'project_id',
                            p.project_id,

                        'project_name',
                            p.project_name,

                        'project_status',
                            p.project_status
                    ),

                'site',
                    jsonb_build_object(
                        'site_id',
                            ps.site_id,

                        'site_code',
                            ps.site_code,

                        'site_name',
                            ps.site_name,

                        'site_status',
                            ps.site_status,

                        'postcode',
                            ps.postcode,

                        'contact_name',
                            ps.contact_name
                    )
            ),

        'current_version',
            case
                when current_qr.revision_id is null then
                    jsonb_build_object(
                        'version_type',
                            'BaseQuotation',

                        'quotation_id',
                            q.quotation_id,

                        'revision_id',
                            null,

                        'revision_no',
                            0,

                        'status',
                            q.quotation_status,

                        'subtotal_amount',
                            q.subtotal_amount,

                        'discount_amount',
                            q.discount_amount,

                        'tax_amount',
                            q.tax_amount,

                        'total_amount',
                            q.total_amount
                    )
                else
                    jsonb_build_object(
                        'version_type',
                            'Revision',

                        'quotation_id',
                            q.quotation_id,

                        'revision_id',
                            current_qr.revision_id,

                        'revision_no',
                            current_qr.revision_no,

                        'status',
                            current_qr.revision_status,

                        'subtotal_amount',
                            current_qr.subtotal_amount,

                        'discount_amount',
                            current_qr.discount_amount,

                        'tax_amount',
                            current_qr.tax_amount,

                        'total_amount',
                            current_qr.total_amount
                    )
            end,

        'base_lines',
            coalesce(
                (
                    select jsonb_agg(
                        jsonb_build_object(
                            'quotation_line_id',
                                ql.quotation_line_id,

                            'line_no',
                                ql.line_no,

                            'product_id',
                                ql.product_id,

                            'product_code',
                                product.product_code,

                            'product_name',
                                product.product_name,

                            'project_area_id',
                                ql.project_area_id,

                            'area_code',
                                area.area_code,

                            'area_name',
                                area.area_name,

                            'description',
                                ql.description,

                            'sales_uom_code',
                                ql.sales_uom_code,

                            'base_uom_code',
                                ql.base_uom_code,

                            'quantity',
                                ql.quantity,

                            'conversion_factor',
                                ql.conversion_factor,

                            'base_quantity',
                                ql.base_quantity,

                            'allow_fractional_quantity',
                                ql.allow_fractional_quantity,

                            'unit_price',
                                ql.unit_price,

                            'discount_percent',
                                ql.discount_percent,

                            'discount_amount',
                                ql.discount_amount,

                            'tax_rate',
                                ql.tax_rate,

                            'tax_amount',
                                ql.tax_amount,

                            'line_total',
                                ql.line_total,

                            'cost_price',
                                case
                                    when v_can_view_cost
                                        then ql.cost_price
                                    else null
                                end,

                            'margin_amount',
                                case
                                    when v_can_view_margin
                                        then ql.margin_amount
                                    else null
                                end,

                            'margin_percent',
                                case
                                    when v_can_view_margin
                                        then ql.margin_percent
                                    else null
                                end,

                            'notes',
                                ql.notes,

                            'is_optional',
                                ql.is_optional
                        )
                        order by ql.line_no
                    )

                    from public.quotation_lines ql

                    left join public.products product
                      on product.product_id =
                         ql.product_id

                    left join public.project_areas area
                      on area.area_id =
                         ql.project_area_id

                    where ql.quotation_id =
                          q.quotation_id
                      and ql.is_deleted = false
                ),
                '[]'::jsonb
            ),

        'revisions',
            coalesce(
                (
                    select jsonb_agg(
                        jsonb_build_object(
                            'revision_id',
                                qr.revision_id,

                            'revision_no',
                                qr.revision_no,

                            'revision_status',
                                qr.revision_status,

                            'is_current',
                                q.current_revision_id =
                                qr.revision_id,

                            'is_accepted',
                                q.accepted_revision_id =
                                qr.revision_id,

                            'revision_reason',
                                qr.revision_reason,

                            'revision_notes',
                                case
                                    when v_can_view_internal
                                        then qr.revision_notes
                                    else null
                                end,

                            'customer_id',
                                qr.customer_id,

                            'project_site_id',
                                qr.project_site_id,

                            'price_book_id',
                                qr.price_book_id,

                            'quotation_segment',
                                qr.quotation_segment,

                            'quotation_source',
                                qr.quotation_source,

                            'issue_date',
                                qr.issue_date,

                            'valid_until',
                                qr.valid_until,

                            'subtotal_amount',
                                qr.subtotal_amount,

                            'discount_amount',
                                qr.discount_amount,

                            'tax_amount',
                                qr.tax_amount,

                            'total_amount',
                                qr.total_amount,

                            'notes',
                                qr.notes,

                            'internal_notes',
                                case
                                    when v_can_view_internal
                                        then qr.internal_notes
                                    else null
                                end,

                            'issued_at',
                                qr.issued_at,

                            'rejected_at',
                                qr.rejected_at,

                            'rejection_reason',
                                case
                                    when v_can_view_internal
                                        then qr.rejection_reason
                                    else null
                                end,

                            'cancelled_at',
                                qr.cancelled_at,

                            'cancellation_reason',
                                case
                                    when v_can_view_internal
                                        then qr.cancellation_reason
                                    else null
                                end,

                            'created_at',
                                qr.created_at,

                            'updated_at',
                                qr.updated_at,

                            'lines',
                                coalesce(
                                    (
                                        select jsonb_agg(
                                            jsonb_build_object(
                                                'revision_line_id',
                                                    qrl.revision_line_id,

                                                'quotation_line_id',
                                                    qrl.quotation_line_id,

                                                'line_no',
                                                    qrl.line_no,

                                                'product_id',
                                                    qrl.product_id,

                                                'product_code',
                                                    revision_product.product_code,

                                                'product_name',
                                                    revision_product.product_name,

                                                'project_area_id',
                                                    qrl.project_area_id,

                                                'area_code',
                                                    revision_area.area_code,

                                                'area_name',
                                                    revision_area.area_name,

                                                'description',
                                                    qrl.description,

                                                'sales_uom_code',
                                                    qrl.sales_uom_code,

                                                'base_uom_code',
                                                    qrl.base_uom_code,

                                                'quantity',
                                                    qrl.quantity,

                                                'conversion_factor',
                                                    qrl.conversion_factor,

                                                'base_quantity',
                                                    qrl.base_quantity,

                                                'allow_fractional_quantity',
                                                    qrl.allow_fractional_quantity,

                                                'unit_price',
                                                    qrl.unit_price,

                                                'discount_percent',
                                                    qrl.discount_percent,

                                                'discount_amount',
                                                    qrl.discount_amount,

                                                'tax_rate',
                                                    qrl.tax_rate,

                                                'tax_amount',
                                                    qrl.tax_amount,

                                                'line_total',
                                                    qrl.line_total,

                                                'cost_price',
                                                    case
                                                        when v_can_view_cost
                                                            then qrl.cost_price
                                                        else null
                                                    end,

                                                'margin_amount',
                                                    case
                                                        when v_can_view_margin
                                                            then qrl.margin_amount
                                                        else null
                                                    end,

                                                'margin_percent',
                                                    case
                                                        when v_can_view_margin
                                                            then qrl.margin_percent
                                                        else null
                                                    end,

                                                'notes',
                                                    qrl.notes,

                                                'is_optional',
                                                    qrl.is_optional
                                            )
                                            order by qrl.line_no
                                        )

                                        from public.quotation_revision_lines qrl

                                        left join public.products revision_product
                                          on revision_product.product_id =
                                             qrl.product_id

                                        left join public.project_areas revision_area
                                          on revision_area.area_id =
                                             qrl.project_area_id

                                        where qrl.revision_id =
                                              qr.revision_id
                                          and qrl.is_deleted = false
                                    ),
                                    '[]'::jsonb
                                )
                        )
                        order by qr.revision_no
                    )

                    from public.quotation_revisions qr

                    where qr.quotation_id =
                          q.quotation_id
                      and qr.is_deleted = false
                ),
                '[]'::jsonb
            )

    )
    into v_result

    from public.quotations q

    left join public.customers c
      on c.customer_id =
         q.customer_id

    left join public.project_sites ps
      on ps.site_id =
         q.project_site_id

    left join public.projects p
      on p.project_id =
         ps.project_id

    left join public.quotation_revisions current_qr
      on current_qr.revision_id =
         q.current_revision_id
     and current_qr.quotation_id =
         q.quotation_id
     and current_qr.is_active = true
     and current_qr.is_deleted = false

    where q.quotation_id =
          p_quotation_id
      and q.is_deleted = false;


    -- ========================================================================
    -- 4. NOT FOUND
    -- ========================================================================

    if v_result is null then
        raise exception
            'Quotation was not found or is archived.';
    end if;


    -- ========================================================================
    -- 5. RETURN
    -- ========================================================================

    return v_result;
end;
$$;


ALTER FUNCTION "public"."get_quotation_detail"("p_quotation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_role_permission_matrix"("p_role_id" "uuid") RETURNS TABLE("role_id" "uuid", "role_code" "text", "role_name" "text", "permission_id" "uuid", "permission_code" "text", "permission_name" "text", "module_code" "text", "action_code" "text", "description" "text", "sort_order" integer, "is_system_permission" boolean, "permission_is_active" boolean, "role_permission_id" "uuid", "is_allowed" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
    if not (
        public.has_permission('permissions.view')
        or public.can_manage_permissions()
    ) then
        raise exception
            'Permission denied: permissions.view';
    end if;

    if not exists (
        select 1
        from public.app_roles r
        where r.role_id = p_role_id
    ) then
        raise exception 'Role was not found.';
    end if;

    return query
    select
        r.role_id,
        r.role_code,
        r.role_name,

        p.permission_id,
        p.permission_code,
        p.permission_name,

        p.module_code,
        p.action_code,
        p.description,

        p.sort_order,
        p.is_system_permission,
        p.is_active,

        rp.role_permission_id,
        coalesce(rp.is_allowed, false)

    from public.app_roles r
    cross join public.app_permissions p

    left join public.app_role_permissions rp
      on rp.role_id = r.role_id
     and rp.permission_id = p.permission_id

    where r.role_id = p_role_id

    order by
        p.module_code,
        p.sort_order,
        p.permission_code;
end;
$$;


ALTER FUNCTION "public"."get_role_permission_matrix"("p_role_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_user_permission_matrix"("p_auth_user_id" "uuid") RETURNS TABLE("auth_user_id" "uuid", "account_status" "text", "role_id" "uuid", "role_code" "text", "role_name" "text", "permission_id" "uuid", "permission_code" "text", "permission_name" "text", "module_code" "text", "action_code" "text", "description" "text", "sort_order" integer, "role_is_allowed" boolean, "override_is_allowed" boolean, "override_is_active" boolean, "override_reason" "text", "effective_is_allowed" boolean, "permission_source" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
    if not (
        public.has_permission('permissions.view')
        or public.has_permission(
            'users.manage_permission_overrides'
        )
        or public.can_manage_permissions()
    ) then
        raise exception
            'Permission denied: permissions.view';
    end if;

    if not exists (
        select 1
        from public.app_users au
        where au.auth_user_id = p_auth_user_id
    ) then
        raise exception
            'Application user was not found.';
    end if;

    return query
    with active_role as (
        select
            ur.role_id,
            r.role_code,
            r.role_name
        from public.app_user_roles ur
        join public.app_roles r
          on r.role_id = ur.role_id
         and r.is_active = true
        where ur.auth_user_id = p_auth_user_id
          and ur.is_active = true
          and ur.ended_at is null
        order by ur.assigned_at desc
        limit 1
    )

    select
        au.auth_user_id,
        au.account_status,

        ar.role_id,
        ar.role_code,
        ar.role_name,

        p.permission_id,
        p.permission_code,
        p.permission_name,

        p.module_code,
        p.action_code,
        p.description,
        p.sort_order,

        coalesce(rp.is_allowed, false),

        upo.is_allowed,
        coalesce(upo.is_active, false),
        upo.reason,

        case
            when au.account_status <> 'Active'
                then false
            when upo.is_active = true
                then upo.is_allowed
            else coalesce(rp.is_allowed, false)
        end,

        case
            when au.account_status <> 'Active'
                then 'Account Inactive'
            when upo.is_active = true
                 and upo.is_allowed = true
                then 'User Allow'
            when upo.is_active = true
                 and upo.is_allowed = false
                then 'User Deny'
            when coalesce(rp.is_allowed, false) = true
                then 'Role Allow'
            else 'Role Deny'
        end

    from public.app_users au

    left join active_role ar
      on true

    cross join public.app_permissions p

    left join public.app_role_permissions rp
      on rp.role_id = ar.role_id
     and rp.permission_id = p.permission_id

    left join public.app_user_permission_overrides upo
      on upo.auth_user_id = au.auth_user_id
     and upo.permission_id = p.permission_id

    where au.auth_user_id = p_auth_user_id
      and p.is_active = true

    order by
        p.module_code,
        p.sort_order,
        p.permission_code;
end;
$$;


ALTER FUNCTION "public"."get_user_permission_matrix"("p_auth_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_user_telegram_notification_settings"("p_auth_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
    v_result jsonb;
begin
    if not public.has_permission('telegram_notifications.view') then
        raise exception
            'Permission denied: telegram_notifications.view';
    end if;

    select jsonb_build_object(
        'auth_user_id', app_user.auth_user_id,
        'email', app_user.email,
        'display_name', coalesce(
            employee.display_name,
            nullif(concat_ws(' ', employee.first_name, employee.last_name), ''),
            app_user.display_name,
            app_user.email
        ),
        'account_status', app_user.account_status,
        'employee_id', employee.employee_id,
        'employee_code', employee.employee_code,
        'roles', coalesce(role_data.roles, '[]'::jsonb),
        'channel', case
            when channel.notification_user_channel_id is null then null
            else jsonb_build_object(
                'notification_user_channel_id',
                    channel.notification_user_channel_id,
                'notification_destination_id',
                    channel.notification_destination_id,
                'destination_name',
                    destination.destination_name,
                'telegram_chat_id',
                    destination.telegram_chat_id,
                'connection_status',
                    channel.connection_status,
                'is_enabled',
                    channel.is_enabled,
                'connected_at',
                    channel.connected_at,
                'connection_notes',
                    channel.connection_notes
            )
        end,
        'events', (
            select jsonb_agg(
                jsonb_build_object(
                    'event_code', event_type.event_code,
                    'event_name', event_type.event_name,
                    'category', case
                        when event_type.event_code =
                             'daily_report_submitted'
                            then 'Daily Report'
                        else 'Goods Receiving'
                    end,
                    'role_default_enabled',
                        permission.role_default_enabled,
                    'override_value',
                        permission.override_value,
                    'effective_enabled',
                        permission.effective_enabled,
                    'permission_source',
                        permission.permission_source
                )
                order by
                    case event_type.event_code
                        when 'daily_report_submitted' then 10
                        when 'site_goods_receiving_completed' then 20
                        when 'site_goods_receiving_partial' then 30
                        when 'site_goods_receiving_issue' then 40
                        else 100
                    end
            )
            from public.notification_event_types event_type
            cross join lateral
                public.get_effective_notification_permission(
                    app_user.auth_user_id,
                    event_type.event_code
                ) permission
            where event_type.event_code in (
                'daily_report_submitted',
                'site_goods_receiving_completed',
                'site_goods_receiving_partial',
                'site_goods_receiving_issue'
            )
        )
    )
    into v_result
    from public.app_users app_user
    left join public.employees employee
      on employee.auth_user_id = app_user.auth_user_id
     and employee.is_deleted = false
    left join public.notification_user_channels channel
      on channel.auth_user_id = app_user.auth_user_id
     and channel.channel_type = 'Telegram'
     and channel.is_deleted = false
    left join public.notification_destinations destination
      on destination.notification_destination_id =
         channel.notification_destination_id
    left join lateral (
        select jsonb_agg(
            jsonb_build_object(
                'role_id', role.role_id,
                'role_code', role.role_code,
                'role_name', role.role_name
            )
            order by role.sort_order, role.role_code
        ) as roles
        from public.app_user_roles user_role
        join public.app_roles role
          on role.role_id = user_role.role_id
         and role.is_active = true
        where user_role.auth_user_id = app_user.auth_user_id
          and user_role.is_active = true
          and user_role.ended_at is null
    ) role_data on true
    where app_user.auth_user_id = p_auth_user_id;

    if v_result is null then
        raise exception 'App user not found.';
    end if;

    return v_result;
end;
$$;


ALTER FUNCTION "public"."get_user_telegram_notification_settings"("p_auth_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_new_auth_user"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
    v_display_name text;
    v_phone text;
BEGIN
    v_display_name :=
        NULLIF(
            btrim(
                COALESCE(
                    NEW.raw_user_meta_data ->> 'display_name',
                    NEW.raw_user_meta_data ->> 'full_name',
                    ''
                )
            ),
            ''
        );

    v_phone :=
        NULLIF(
            btrim(
                COALESCE(
                    NEW.raw_user_meta_data ->> 'phone',
                    NEW.phone,
                    ''
                )
            ),
            ''
        );

    INSERT INTO public.app_users (
        auth_user_id,
        email,
        display_name,
        phone,
        account_status,
        created_by,
        updated_by
    )
    VALUES (
        NEW.id,
        COALESCE(NEW.email, ''),
        v_display_name,
        v_phone,
        'Pending',
        NEW.id,
        NEW.id
    )
    ON CONFLICT (auth_user_id)
    DO UPDATE SET
        email = EXCLUDED.email,
        display_name = COALESCE(
            public.app_users.display_name,
            EXCLUDED.display_name
        ),
        phone = COALESCE(
            public.app_users.phone,
            EXCLUDED.phone
        ),
        updated_at = now();

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."handle_new_auth_user"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."has_active_app_access"() RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
    SELECT EXISTS (
        SELECT 1
        FROM public.app_users au
        WHERE au.auth_user_id = auth.uid()
          AND au.account_status = 'Active'
    );
$$;


ALTER FUNCTION "public"."has_active_app_access"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."has_active_app_access"() IS 'Returns true only when the authenticated user has an Active REDS application account.';



CREATE OR REPLACE FUNCTION "public"."has_permission"("p_permission_code" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_user_id uuid;
    v_permission_id uuid;
    v_override boolean;
BEGIN
    v_user_id := auth.uid();

    IF v_user_id IS NULL THEN
        RETURN false;
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM public.app_users au
        WHERE au.auth_user_id = v_user_id
          AND au.account_status = 'Active'
    ) THEN
        RETURN false;
    END IF;

    SELECT p.permission_id
    INTO v_permission_id
    FROM public.app_permissions p
    WHERE p.permission_code = p_permission_code
      AND p.is_active = true;

    IF v_permission_id IS NULL THEN
        RETURN false;
    END IF;

    SELECT upo.is_allowed
    INTO v_override
    FROM public.app_user_permission_overrides upo
    WHERE upo.auth_user_id = v_user_id
      AND upo.permission_id = v_permission_id
      AND upo.is_active = true
    LIMIT 1;

    IF FOUND THEN
        RETURN v_override;
    END IF;

    RETURN EXISTS (
        SELECT 1
        FROM public.app_user_roles ur
        JOIN public.app_roles r
          ON r.role_id = ur.role_id
         AND r.is_active = true
        JOIN public.app_role_permissions rp
          ON rp.role_id = r.role_id
         AND rp.permission_id = v_permission_id
         AND rp.is_allowed = true
        WHERE ur.auth_user_id = v_user_id
          AND ur.is_active = true
    );
END;
$$;


ALTER FUNCTION "public"."has_permission"("p_permission_code" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."has_permission"("p_permission_code" "text") IS 'Returns the current authenticated user effective permission. User override takes precedence over role grants; otherwise deny.';



CREATE OR REPLACE FUNCTION "public"."invoice_due_date_from_terms"("p_customer_id" "uuid", "p_invoice_date" "date") RETURNS "date"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    v_type text;
    v_days integer;
begin
    select
        cfs.payment_terms_type,
        cfs.payment_terms_days
    into
        v_type,
        v_days
    from public.customer_financial_settings cfs
    where cfs.customer_id = p_customer_id;

    v_type := coalesce(v_type, 'Days After Bill');
    v_days := coalesce(v_days, 14);

    case v_type
        when 'Days After Bill' then
            return p_invoice_date + v_days;

        when 'Days After Bill Month' then
            return (
                date_trunc('month', p_invoice_date)::date
                + interval '1 month'
                + (v_days || ' days')::interval
            )::date;

        when 'Day of Current Month' then
            return least(
                (
                    date_trunc('month', p_invoice_date)::date
                    + (v_days - 1)
                ),
                (
                    date_trunc('month', p_invoice_date)::date
                    + interval '1 month - 1 day'
                )::date
            );

        when 'Day of Following Month' then
            return least(
                (
                    date_trunc('month', p_invoice_date)::date
                    + interval '1 month'
                    + (v_days - 1)
                )::date,
                (
                    date_trunc('month', p_invoice_date)::date
                    + interval '2 months - 1 day'
                )::date
            );

        else
            return p_invoice_date + 14;
    end case;
end;
$$;


ALTER FUNCTION "public"."invoice_due_date_from_terms"("p_customer_id" "uuid", "p_invoice_date" "date") OWNER TO "postgres";


