CREATE OR REPLACE FUNCTION "public"."issue_invoice_atomic"("p_invoice_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    v_invoice public.customer_invoices%rowtype;
begin
    perform public.assert_invoice_permission('invoices.issue');

    select *
    into v_invoice
    from public.customer_invoices
    where customer_invoice_id = p_invoice_id
      and is_deleted = false
    for update;

    if not found then
        raise exception 'Invoice not found.';
    end if;

    if v_invoice.document_status <> 'Approved' then
        raise exception 'Only Approved Invoices can be issued.';
    end if;

    update public.customer_invoices
    set
        document_status = 'Issued',
        issued_at = now(),
        issued_by = auth.uid(),
        updated_by = auth.uid()
    where customer_invoice_id = p_invoice_id;

    return p_invoice_id;
end;
$$;


