CREATE OR REPLACE FUNCTION "public"."issue_stock_issue_atomic"("p_stock_issue_id" "uuid", "p_movement_date" "date" DEFAULT CURRENT_DATE, "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
    v_issue public.stock_issues%rowtype;
    v_allocation record;
    v_lot public.stock_lots%rowtype;
    v_movement_id uuid;
    v_new_remaining numeric(18,6);
    v_new_reserved numeric(18,6);
    v_new_status text;
    v_movement_count integer := 0;
begin
    if not public.has_permission('stock_issues.issue') then
        raise exception 'Permission denied: stock_issues.issue.';
    end if;

    select *
    into v_issue
    from public.stock_issues
    where stock_issue_id = p_stock_issue_id
      and is_deleted = false
    for update;

    if not found then
        raise exception 'Stock Issue was not found.';
    end if;

    if v_issue.issue_status <> 'Prepared' then
        raise exception
            'Only Prepared Stock Issues can be issued.';
    end if;

    if exists (
        select 1
        from public.stock_issue_allocations a
        join public.stock_issue_lines l
          on l.stock_issue_line_id = a.stock_issue_line_id
        where l.stock_issue_id = p_stock_issue_id
          and l.is_deleted = false
          and a.is_deleted = false
          and a.stock_movement_id is not null
    ) then
        raise exception
            'This Stock Issue already contains posted Stock Movements.';
    end if;

    for v_allocation in
        select
            a.*,
            l.stock_request_item_id,
            l.issued_product_id,
            l.base_uom_code,
            l.stock_issue_line_id
        from public.stock_issue_allocations a
        join public.stock_issue_lines l
          on l.stock_issue_line_id = a.stock_issue_line_id
        where l.stock_issue_id = p_stock_issue_id
          and l.is_deleted = false
          and a.is_deleted = false
        order by l.line_no, a.created_at
    loop
        select *
        into v_lot
        from public.stock_lots
        where stock_lot_id = v_allocation.stock_lot_id
          and is_deleted = false
          and is_active = true
        for update;

        if not found then
            raise exception 'Allocated Stock Lot was not found or is inactive.';
        end if;

        if v_lot.product_id <> v_allocation.issued_product_id then
            raise exception 'Allocated Stock Lot product mismatch.';
        end if;

        if v_lot.base_uom_code <> v_allocation.base_uom_code then
            raise exception 'Allocated Stock Lot Base UOM mismatch.';
        end if;

        if v_allocation.allocated_base_quantity >
           (v_lot.remaining_quantity - v_lot.reserved_quantity) then
            raise exception
                'Insufficient available stock in lot %.',
                v_lot.lot_no;
        end if;

        v_new_remaining :=
            v_lot.remaining_quantity
            - v_allocation.allocated_base_quantity;

        v_new_reserved := v_lot.reserved_quantity;

        if v_new_remaining = 0 then
            v_new_status := 'Exhausted';
        elsif v_new_reserved = v_new_remaining then
            v_new_status := 'Reserved';
        elsif v_new_remaining < v_lot.received_quantity then
            v_new_status := 'Partially Issued';
        else
            v_new_status := 'Available';
        end if;

        update public.stock_lots
        set
            remaining_quantity = v_new_remaining,
            reserved_quantity = v_new_reserved,
            lot_status = v_new_status,
            updated_at = now(),
            updated_by = auth.uid()
        where stock_lot_id = v_lot.stock_lot_id;

        insert into public.stock_movements (
            stock_lot_id,
            product_id,
            movement_type,
            movement_date,
            quantity,
            base_uom_code,
            from_location_id,
            to_location_id,
            stock_request_item_id,
            supplier_delivery_item_id,
            stock_issue_id,
            stock_issue_allocation_id,
            reference_no,
            reason,
            notes,
            unit_cost,
            total_cost,
            created_by,
            updated_by,
            is_deleted
        )
        values (
            v_lot.stock_lot_id,
            v_lot.product_id,
            'Issue',
            coalesce(p_movement_date, current_date),
            v_allocation.allocated_base_quantity,
            v_lot.base_uom_code,
            v_lot.stock_location_id,
            null,
            v_allocation.stock_request_item_id,
            null,
            p_stock_issue_id,
            v_allocation.stock_issue_allocation_id,
            v_issue.stock_issue_no,
            'Stock Issue',
            coalesce(
                nullif(btrim(p_notes), ''),
                v_allocation.notes
            ),
            v_lot.average_unit_cost,
            case
                when v_lot.average_unit_cost is null then null
                else round(
                    v_allocation.allocated_base_quantity
                    * v_lot.average_unit_cost,
                    4
                )
            end,
            auth.uid(),
            auth.uid(),
            false
        )
        returning stock_movement_id
        into v_movement_id;

        update public.stock_issue_allocations
        set
            issued_base_quantity = allocated_base_quantity,
            allocation_status = 'Issued',
            stock_movement_id = v_movement_id,
            updated_at = now(),
            updated_by = auth.uid()
        where stock_issue_allocation_id =
              v_allocation.stock_issue_allocation_id;

        v_movement_count := v_movement_count + 1;
    end loop;

    if v_movement_count = 0 then
        raise exception 'Stock Issue has no active allocations.';
    end if;

    update public.stock_issue_lines
    set
        line_status = 'Issued',
        updated_at = now(),
        updated_by = auth.uid()
    where stock_issue_id = p_stock_issue_id
      and is_deleted = false;

    update public.stock_issues
    set
        issue_status = 'Issued',
        issued_at = now(),
        issued_by = auth.uid(),
        updated_at = now(),
        updated_by = auth.uid()
    where stock_issue_id = p_stock_issue_id;

    perform public.refresh_stock_request_issue_progress(
        v_issue.stock_request_id
    );

    return jsonb_build_object(
        'stock_issue_id', p_stock_issue_id,
        'stock_issue_no', v_issue.stock_issue_no,
        'movement_count', v_movement_count,
        'issue_status', 'Issued'
    );
end;
$$;


ALTER FUNCTION "public"."issue_stock_issue_atomic"("p_stock_issue_id" "uuid", "p_movement_date" "date", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."issue_stock_request_item"("p_stock_request_item_id" "uuid", "p_stock_lot_id" "uuid", "p_quantity" numeric, "p_movement_date" "date" DEFAULT CURRENT_DATE, "p_notes" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
    v_request_item public.stock_request_items%rowtype;
    v_request public.stock_requests%rowtype;
    v_lot public.stock_lots%rowtype;
    v_product public.products%rowtype;

    v_request_uom_code text;
    v_base_uom_code text;
    v_conversion_factor numeric(18, 6);
    v_allow_fractional_quantity boolean;
    v_base_quantity numeric(18, 6);

    v_lot_reserved_remaining numeric(18, 6);

    v_has_missing_conversion boolean;
    v_all_fully_reserved boolean;
    v_any_reserved boolean;
    v_all_fully_issued boolean;
    v_any_issued boolean;

    v_stock_movement_id uuid;
    v_new_request_status text;
begin
    if not public.is_admin_role() then
        raise exception
            'Only an Admin can issue stock request items.';
    end if;

    if p_stock_request_item_id is null then
        raise exception
            'Stock request item is required.';
    end if;

    if p_stock_lot_id is null then
        raise exception
            'Stock lot is required.';
    end if;

    if p_quantity is null or p_quantity <= 0 then
        raise exception
            'Issue quantity must be greater than zero.';
    end if;

    select *
    into v_request_item
    from public.stock_request_items
    where stock_request_item_id = p_stock_request_item_id
      and is_deleted = false
    for update;

    if not found then
        raise exception
            'Stock request item not found.';
    end if;

    select *
    into v_request
    from public.stock_requests
    where stock_request_id = v_request_item.stock_request_id
      and is_deleted = false
    for update;

    if not found then
        raise exception
            'Stock request not found.';
    end if;

    if v_request.request_status not in (
        'Partially Reserved',
        'Reserved',
        'Partially Issued'
    ) then
        raise exception
            'Stock request status % does not allow stock issue.',
            v_request.request_status;
    end if;

    if v_request_item.approved_quantity is null
       or v_request_item.approved_quantity <= 0 then
        raise exception
            'Approved quantity must be greater than zero before stock can be issued.';
    end if;

    select *
    into v_product
    from public.products
    where product_id = v_request_item.product_id
      and is_deleted = false;

    if not found then
        raise exception
            'Product not found.';
    end if;

    select *
    into v_lot
    from public.stock_lots
    where stock_lot_id = p_stock_lot_id
      and is_deleted = false
      and is_active = true
    for update;

    if not found then
        raise exception
            'Active stock lot not found.';
    end if;

    if v_lot.product_id <> v_request_item.product_id then
        raise exception
            'The stock lot product does not match the stock request item product.';
    end if;

    v_request_uom_code :=
        nullif(trim(v_request_item.unit_of_measure), '');

    v_base_uom_code :=
        nullif(trim(v_product.base_uom_code), '');

    if v_request_uom_code is null then
        raise exception
            'Request unit of measure is missing.';
    end if;

    if v_base_uom_code is null then
        raise exception
            'Product base unit of measure is missing.';
    end if;

    if v_lot.base_uom_code <> v_base_uom_code then
        raise exception
            'Stock lot base UOM % does not match product base UOM %.',
            v_lot.base_uom_code,
            v_base_uom_code;
    end if;

    if v_request_uom_code = v_base_uom_code then
        v_conversion_factor := 1;
        v_allow_fractional_quantity := true;
    else
        select
            puc.conversion_factor,
            puc.allow_fractional_quantity
        into
            v_conversion_factor,
            v_allow_fractional_quantity
        from public.product_uom_conversions puc
        where puc.product_id = v_request_item.product_id
          and puc.from_uom_code = v_request_uom_code
          and puc.to_uom_code = v_base_uom_code
          and puc.is_active = true
          and puc.is_deleted = false
        order by
            puc.sort_order,
            puc.created_at
        limit 1;

        if not found then
            raise exception
                'No active UOM conversion exists for product % from % to %.',
                v_product.product_code,
                v_request_uom_code,
                v_base_uom_code;
        end if;
    end if;

    if v_conversion_factor is null
       or v_conversion_factor <= 0 then
        raise exception
            'UOM conversion factor must be greater than zero.';
    end if;

    if coalesce(v_allow_fractional_quantity, true) = false
       and p_quantity <> trunc(p_quantity) then
        raise exception
            'Fractional quantities are not allowed for UOM %.',
            v_request_uom_code;
    end if;

    v_base_quantity :=
        round(p_quantity * v_conversion_factor, 6);

    select coalesce(
        sum(
            case
                when sm.movement_type = 'Reserve'
                    then sm.quantity
                when sm.movement_type = 'Release Reservation'
                    then -sm.quantity
                when sm.movement_type = 'Issue'
                    then -sm.quantity
                else 0
            end
        ),
        0
    )
    into v_lot_reserved_remaining
    from public.stock_movements sm
    where sm.stock_request_item_id =
              v_request_item.stock_request_item_id
      and sm.stock_lot_id =
              p_stock_lot_id
      and sm.is_deleted = false
      and sm.movement_type in (
          'Reserve',
          'Release Reservation',
          'Issue'
      );

    if v_lot_reserved_remaining <= 0 then
        raise exception
            'No remaining reservation exists for this stock request item and stock lot.';
    end if;

    if v_base_quantity > v_lot_reserved_remaining then
        raise exception
            'Issue quantity exceeds the remaining reservation. Reserved remaining: % %, requested issue: % % (% %).',
            v_lot_reserved_remaining,
            v_base_uom_code,
            p_quantity,
            v_request_uom_code,
            v_base_quantity,
            v_base_uom_code;
    end if;

    v_stock_movement_id :=
        public.record_stock_movement(
            p_stock_lot_id =>
                p_stock_lot_id,
            p_movement_type =>
                'Issue',
            p_quantity =>
                v_base_quantity,
            p_movement_date =>
                coalesce(p_movement_date, current_date),
            p_stock_request_item_id =>
                p_stock_request_item_id,
            p_supplier_delivery_item_id =>
                null,
            p_reference_no =>
                v_request.stock_request_no,
            p_reason =>
                'Stock Request Issue',
            p_notes =>
                nullif(trim(p_notes), '')
        );

    with item_progress as (
        select
            sri.stock_request_item_id,

            round(
                sri.approved_quantity *
                case
                    when sri.unit_of_measure = p.base_uom_code
                        then 1
                    else conv.conversion_factor
                end,
                6
            ) as approved_base_quantity,

            coalesce(
                sum(
                    case
                        when sm.movement_type = 'Reserve'
                            then sm.quantity
                        when sm.movement_type = 'Release Reservation'
                            then -sm.quantity
                        when sm.movement_type = 'Issue'
                            then -sm.quantity
                        else 0
                    end
                ),
                0
            ) as reserved_remaining_base_quantity,

            coalesce(
                sum(
                    case
                        when sm.movement_type = 'Issue'
                            then sm.quantity
                        else 0
                    end
                ),
                0
            ) as issued_base_quantity,

            case
                when sri.unit_of_measure = p.base_uom_code
                    then false
                when conv.conversion_factor is null
                    then true
                else false
            end as missing_conversion
        from public.stock_request_items sri
        join public.products p
            on p.product_id = sri.product_id
           and p.is_deleted = false

        left join lateral (
            select puc.conversion_factor
            from public.product_uom_conversions puc
            where puc.product_id = sri.product_id
              and puc.from_uom_code = sri.unit_of_measure
              and puc.to_uom_code = p.base_uom_code
              and puc.is_active = true
              and puc.is_deleted = false
            order by
                puc.sort_order,
                puc.created_at
            limit 1
        ) conv on true

        left join public.stock_movements sm
            on sm.stock_request_item_id =
               sri.stock_request_item_id
           and sm.is_deleted = false
           and sm.movement_type in (
               'Reserve',
               'Release Reservation',
               'Issue'
           )

        where sri.stock_request_id =
                  v_request.stock_request_id
          and sri.is_deleted = false
          and sri.approved_quantity > 0

        group by
            sri.stock_request_item_id,
            sri.approved_quantity,
            sri.unit_of_measure,
            p.base_uom_code,
            conv.conversion_factor
    )
    select
        coalesce(bool_or(missing_conversion), false),

        coalesce(
            bool_and(
                reserved_remaining_base_quantity +
                issued_base_quantity >=
                approved_base_quantity
            ),
            false
        ),

        coalesce(
            bool_or(
                reserved_remaining_base_quantity > 0
            ),
            false
        ),

        coalesce(
            bool_and(
                issued_base_quantity >=
                approved_base_quantity
            ),
            false
        ),

        coalesce(
            bool_or(issued_base_quantity > 0),
            false
        )
    into
        v_has_missing_conversion,
        v_all_fully_reserved,
        v_any_reserved,
        v_all_fully_issued,
        v_any_issued
    from item_progress;

    if v_has_missing_conversion then
        raise exception
            'One or more stock request items do not have a valid conversion to their product base UOM.';
    end if;

    if v_all_fully_issued then
        v_new_request_status := 'Issued';

    elsif v_any_issued then
        v_new_request_status := 'Partially Issued';

    elsif v_all_fully_reserved then
        v_new_request_status := 'Reserved';

    elsif v_any_reserved then
        v_new_request_status := 'Partially Reserved';

    else
        v_new_request_status := 'Approved';
    end if;

    update public.stock_requests
    set
        request_status = v_new_request_status,
        updated_at = now(),
        updated_by = auth.uid()
    where stock_request_id =
          v_request.stock_request_id;

    return v_stock_movement_id;
end;
$$;


ALTER FUNCTION "public"."issue_stock_request_item"("p_stock_request_item_id" "uuid", "p_stock_lot_id" "uuid", "p_quantity" numeric, "p_movement_date" "date", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."issue_tool_loan_atomic"("p_tool_loan_id" "uuid", "p_allocations" "jsonb", "p_notes" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
    v_loan public.tool_loans%rowtype;
    v_allocation jsonb;
    v_item public.tool_loan_items%rowtype;
    v_lot public.stock_lots%rowtype;
    v_item_id uuid;
    v_lot_id uuid;
    v_quantity numeric(18,6);
    v_movement_id uuid;
    v_new_remaining numeric(18,6);
    v_new_reserved numeric(18,6);
    v_new_status text;
    v_reference_no text;
begin
    if not public.has_permission('tool_loans.issue') then
        raise exception 'Permission denied: tool_loans.issue.';
    end if;

    if p_tool_loan_id is null then
        raise exception 'Tool Loan ID is required.';
    end if;

    if p_allocations is null
       or jsonb_typeof(p_allocations) <> 'array'
       or jsonb_array_length(p_allocations) = 0 then
        raise exception 'At least one Stock Lot allocation is required.';
    end if;

    select *
    into v_loan
    from public.tool_loans
    where tool_loan_id = p_tool_loan_id
      and is_deleted = false
    for update;

    if not found then
        raise exception 'Tool Loan was not found.';
    end if;

    if v_loan.loan_status <> 'Prepared' then
        raise exception
            'Only Prepared Tool Loans can be issued. Current status: %.',
            v_loan.loan_status;
    end if;

    if exists (
        select 1
        from public.tool_loan_issue_postings
        where tool_loan_id = p_tool_loan_id
          and is_deleted = false
    ) then
        raise exception
            'Tool Loan already has active issue postings and cannot be issued again.';
    end if;

    if not exists (
        select 1
        from public.tool_loan_items
        where tool_loan_id = p_tool_loan_id
          and is_deleted = false
    ) then
        raise exception 'Tool Loan has no active items.';
    end if;

    -- Validate allocation JSON and item totals before any stock mutation.
    if exists (
        select 1
        from jsonb_array_elements(p_allocations) a(value)
        where nullif(a.value->>'tool_loan_item_id', '') is null
           or nullif(a.value->>'stock_lot_id', '') is null
           or nullif(a.value->>'issue_base_quantity', '') is null
           or (a.value->>'issue_base_quantity')::numeric <= 0
    ) then
        raise exception
            'Every allocation requires tool_loan_item_id, stock_lot_id and a positive issue_base_quantity.';
    end if;

    if exists (
        select 1
        from public.tool_loan_items tli
        where tli.tool_loan_id = p_tool_loan_id
          and tli.is_deleted = false
          and coalesce((
              select round(sum((a.value->>'issue_base_quantity')::numeric), 6)
              from jsonb_array_elements(p_allocations) a(value)
              where (a.value->>'tool_loan_item_id')::uuid =
                    tli.tool_loan_item_id
          ), 0) <> round(tli.approved_base_quantity, 6)
    ) then
        raise exception
            'B1 requires full issue: allocation total for every item must exactly equal Approved Base Quantity.';
    end if;

    if exists (
        select 1
        from jsonb_array_elements(p_allocations) a(value)
        left join public.tool_loan_items tli
          on tli.tool_loan_item_id =
             (a.value->>'tool_loan_item_id')::uuid
         and tli.tool_loan_id = p_tool_loan_id
         and tli.is_deleted = false
        where tli.tool_loan_item_id is null
    ) then
        raise exception
            'An allocation references an item outside this Tool Loan.';
    end if;

    v_reference_no := v_loan.tool_loan_no;

    for v_allocation in
        select value
        from jsonb_array_elements(p_allocations)
    loop
        v_item_id :=
            (v_allocation->>'tool_loan_item_id')::uuid;
        v_lot_id :=
            (v_allocation->>'stock_lot_id')::uuid;
        v_quantity :=
            round(
                (v_allocation->>'issue_base_quantity')::numeric,
                6
            );

        select *
        into v_item
        from public.tool_loan_items
        where tool_loan_item_id = v_item_id
          and tool_loan_id = p_tool_loan_id
          and is_deleted = false
        for update;

        if not found then
            raise exception 'Tool Loan item % was not found.', v_item_id;
        end if;

        if v_item.item_status <> 'Prepared' then
            raise exception
                'Tool Loan item line % is not Prepared.',
                v_item.line_no;
        end if;

        select *
        into v_lot
        from public.stock_lots
        where stock_lot_id = v_lot_id
          and is_deleted = false
          and is_active = true
        for update;

        if not found then
            raise exception
                'Stock Lot % was not found or is inactive.',
                v_lot_id;
        end if;

        if v_lot.product_id <> v_item.product_id then
            raise exception
                'Stock Lot product does not match Tool Loan line %.',
                v_item.line_no;
        end if;

        if v_lot.stock_location_id <>
           v_loan.from_stock_location_id then
            raise exception
                'Stock Lot location does not match Tool Loan source location for line %.',
                v_item.line_no;
        end if;

        if v_lot.base_uom_code <> v_item.base_uom_code then
            raise exception
                'Stock Lot Base UOM does not match Tool Loan line %.',
                v_item.line_no;
        end if;

        if v_lot.lot_status in (
            'Quarantine',
            'Damaged',
            'Closed',
            'Exhausted'
        ) then
            raise exception
                'Stock Lot % is not available for issue. Status: %.',
                v_lot.lot_no,
                v_lot.lot_status;
        end if;

        if v_quantity >
           (v_lot.remaining_quantity - v_lot.reserved_quantity) then
            raise exception
                'Insufficient unreserved quantity in Stock Lot %.',
                v_lot.lot_no;
        end if;

        v_new_remaining :=
            round(v_lot.remaining_quantity - v_quantity, 6);
        v_new_reserved := v_lot.reserved_quantity;

        if v_new_remaining = 0 then
            v_new_status := 'Exhausted';
        elsif v_new_reserved = v_new_remaining then
            v_new_status := 'Reserved';
        elsif v_new_remaining < v_lot.received_quantity then
            v_new_status := 'Partially Issued';
        else
            v_new_status := 'Available';
        end if;

        update public.stock_lots
        set
            remaining_quantity = v_new_remaining,
            lot_status = v_new_status,
            updated_at = now(),
            updated_by = auth.uid()
        where stock_lot_id = v_lot.stock_lot_id;

        insert into public.stock_movements (
            stock_lot_id,
            product_id,
            movement_type,
            movement_date,
            quantity,
            base_uom_code,
            from_location_id,
            to_location_id,
            stock_request_item_id,
            supplier_delivery_item_id,
            reference_no,
            reason,
            notes,
            unit_cost,
            total_cost,
            created_by,
            updated_by,
            is_deleted
        )
        values (
            v_lot.stock_lot_id,
            v_lot.product_id,
            'Issue',
            current_date,
            v_quantity,
            v_lot.base_uom_code,
            v_lot.stock_location_id,
            null,
            v_item.stock_request_item_id,
            null,
            v_reference_no,
            'Tool Loan Issue',
            coalesce(
                nullif(btrim(p_notes), ''),
                format(
                    'Issued for Tool Loan %s, line %s.',
                    v_loan.tool_loan_no,
                    v_item.line_no
                )
            ),
            v_lot.average_unit_cost,
            case
                when v_lot.average_unit_cost is null then null
                else round(v_quantity * v_lot.average_unit_cost, 4)
            end,
            auth.uid(),
            auth.uid(),
            false
        )
        returning stock_movement_id
        into v_movement_id;

        insert into public.tool_loan_issue_postings (
            tool_loan_id,
            tool_loan_item_id,
            stock_lot_id,
            stock_movement_id,
            issued_base_quantity,
            base_uom_code,
            issued_at,
            issued_by,
            notes,
            created_by,
            updated_by
        )
        values (
            p_tool_loan_id,
            v_item.tool_loan_item_id,
            v_lot.stock_lot_id,
            v_movement_id,
            v_quantity,
            v_lot.base_uom_code,
            now(),
            auth.uid(),
            nullif(btrim(p_notes), ''),
            auth.uid(),
            auth.uid()
        );
    end loop;

    update public.tool_loan_items tli
    set
        issued_base_quantity = tli.approved_base_quantity,
        issued_quantity = round(
            tli.approved_base_quantity /
            nullif(tli.conversion_factor_to_base, 0),
            6
        ),
        item_status = 'Issued',
        updated_at = now(),
        updated_by = auth.uid()
    where tli.tool_loan_id = p_tool_loan_id
      and tli.is_deleted = false;

    update public.tool_loans
    set
        loan_status = 'Issued',
        issued_at = now(),
        issued_by = auth.uid(),
        notes = coalesce(nullif(btrim(p_notes), ''), notes),
        updated_at = now(),
        updated_by = auth.uid()
    where tool_loan_id = p_tool_loan_id;

    return p_tool_loan_id;
end;
$$;


ALTER FUNCTION "public"."issue_tool_loan_atomic"("p_tool_loan_id" "uuid", "p_allocations" "jsonb", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_access_control_audit"("p_target_auth_user_id" "uuid" DEFAULT NULL::"uuid", "p_target_role_id" "uuid" DEFAULT NULL::"uuid", "p_permission_code" "text" DEFAULT NULL::"text", "p_change_type" "text" DEFAULT NULL::"text", "p_date_from" "date" DEFAULT NULL::"date", "p_date_to" "date" DEFAULT NULL::"date", "p_limit" integer DEFAULT 100, "p_offset" integer DEFAULT 0) RETURNS TABLE("access_control_audit_id" "uuid", "target_auth_user_id" "uuid", "target_user_email" "text", "target_user_name" "text", "target_role_id" "uuid", "target_role_code" "text", "target_role_name" "text", "permission_id" "uuid", "permission_code" "text", "change_type" "text", "old_value" "jsonb", "new_value" "jsonb", "reason" "text", "changed_by" "uuid", "changed_by_email" "text", "changed_by_name" "text", "changed_at" timestamp with time zone, "total_row_count" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
    if not (
        public.has_permission('permissions.view')
        or public.can_manage_permissions()
    ) then
        raise exception
            'Permission denied: permissions.view';
    end if;

    return query
    select
        a.access_control_audit_id,

        a.target_auth_user_id,
        target_user.email,
        target_user.display_name,

        a.target_role_id,
        r.role_code,
        r.role_name,

        a.permission_id,
        a.permission_code,

        a.change_type,
        a.old_value,
        a.new_value,
        a.reason,

        a.changed_by,
        actor.email,
        actor.display_name,

        a.changed_at,
        count(*) over ()

    from public.access_control_audit_log a

    left join public.app_users target_user
      on target_user.auth_user_id =
         a.target_auth_user_id

    left join public.app_roles r
      on r.role_id = a.target_role_id

    left join public.app_users actor
      on actor.auth_user_id = a.changed_by

    where (
        p_target_auth_user_id is null
        or a.target_auth_user_id =
           p_target_auth_user_id
    )
      and (
        p_target_role_id is null
        or a.target_role_id =
           p_target_role_id
      )
      and (
        nullif(btrim(p_permission_code), '')
            is null
        or a.permission_code =
           btrim(p_permission_code)
      )
      and (
        nullif(btrim(p_change_type), '')
            is null
        or a.change_type =
           btrim(p_change_type)
      )
      and (
        p_date_from is null
        or a.changed_at::date >= p_date_from
      )
      and (
        p_date_to is null
        or a.changed_at::date <= p_date_to
      )

    order by a.changed_at desc

    limit least(
        greatest(
            coalesce(p_limit, 100),
            1
        ),
        500
    )

    offset greatest(
        coalesce(p_offset, 0),
        0
    );
end;
$$;


ALTER FUNCTION "public"."list_access_control_audit"("p_target_auth_user_id" "uuid", "p_target_role_id" "uuid", "p_permission_code" "text", "p_change_type" "text", "p_date_from" "date", "p_date_to" "date", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_customer_account_summaries"("p_search" "text" DEFAULT NULL::"text", "p_customer_id" "uuid" DEFAULT NULL::"uuid", "p_only_with_balance" boolean DEFAULT false, "p_only_overdue" boolean DEFAULT false, "p_limit" integer DEFAULT 100, "p_offset" integer DEFAULT 0) RETURNS TABLE("customer_id" "uuid", "customer_code" "text", "customer_name" "text", "customer_type" "text", "default_currency" "text", "payment_terms_type" "text", "payment_terms_days" integer, "credit_limit" numeric, "is_account_on_hold" boolean, "account_hold_reason" "text", "draft_invoice_count" integer, "issued_invoice_count" integer, "overdue_invoice_count" integer, "total_invoiced" numeric, "total_paid" numeric, "total_outstanding" numeric, "current_outstanding" numeric, "overdue_outstanding" numeric, "recorded_payment_total" numeric, "unallocated_credit" numeric, "available_credit" numeric, "total_row_count" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
    perform public.assert_invoice_permission('invoices.view');

    if p_limit < 1 or p_limit > 500 then
        raise exception 'Limit must be between 1 and 500.';
    end if;

    if p_offset < 0 then
        raise exception 'Offset cannot be negative.';
    end if;

    return query
    select
        b.customer_id,
        b.customer_code,
        b.customer_name,
        b.customer_type,

        b.default_currency,
        b.payment_terms_type,
        b.payment_terms_days,
        b.credit_limit,
        b.is_account_on_hold,
        b.account_hold_reason,

        b.draft_invoice_count,
        b.issued_invoice_count,
        b.overdue_invoice_count,

        b.total_invoiced,
        b.total_paid,
        b.total_outstanding,
        b.current_outstanding,
        b.overdue_outstanding,

        b.recorded_payment_total,
        b.unallocated_credit,
        b.available_credit,

        count(*) over() as total_row_count

    from public._customer_account_summary b

    where (
        nullif(btrim(p_search), '') is null
        or b.customer_name ilike '%' || btrim(p_search) || '%'
        or b.customer_code ilike '%' || btrim(p_search) || '%'
    )
      and (
          p_customer_id is null
          or b.customer_id = p_customer_id
      )
      and (
          p_only_with_balance = false
          or b.total_outstanding > 0
      )
      and (
          p_only_overdue = false
          or b.overdue_outstanding > 0
      )

    order by
        b.overdue_outstanding desc,
        b.total_outstanding desc,
        b.customer_name

    limit p_limit
    offset p_offset;
end;
$$;


ALTER FUNCTION "public"."list_customer_account_summaries"("p_search" "text", "p_customer_id" "uuid", "p_only_with_balance" boolean, "p_only_overdue" boolean, "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."list_customer_account_summaries"("p_search" "text", "p_customer_id" "uuid", "p_only_with_balance" boolean, "p_only_overdue" boolean, "p_limit" integer, "p_offset" integer) IS 'Customer account summary with Invoice totals, outstanding, overdue, credit limit and unallocated Payment credit.';



CREATE OR REPLACE FUNCTION "public"."list_customer_financial_profiles"("p_search" "text" DEFAULT NULL::"text", "p_customer_type" "text" DEFAULT NULL::"text", "p_xero_status" "text" DEFAULT NULL::"text", "p_only_with_balance" boolean DEFAULT false, "p_only_overdue" boolean DEFAULT false, "p_only_attention" boolean DEFAULT false, "p_limit" integer DEFAULT 100, "p_offset" integer DEFAULT 0) RETURNS TABLE("customer_id" "uuid", "customer_code" "text", "customer_name" "text", "customer_type" "text", "primary_contact_name" "text", "primary_contact_phone" "text", "primary_contact_email" "text", "default_currency" "text", "payment_terms_type" "text", "payment_terms_days" integer, "credit_limit" numeric, "is_account_on_hold" boolean, "project_count" integer, "active_project_count" integer, "total_invoiced" numeric, "total_paid" numeric, "total_outstanding" numeric, "overdue_outstanding" numeric, "unallocated_credit" numeric, "available_credit" numeric, "xero_status" "text", "has_financial_settings" boolean, "is_xero_minimum_ready" boolean, "is_xero_accounting_ready" boolean, "readiness_issue_count" integer, "total_row_count" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    v_can_view_xero boolean;
begin
    perform public.assert_invoice_permission('invoices.view');

    v_can_view_xero :=
        public.has_permission('xero.customer_profile_view');

    if p_limit < 1 or p_limit > 500 then
        raise exception 'Limit must be between 1 and 500.';
    end if;

    if p_offset < 0 then
        raise exception 'Offset cannot be negative.';
    end if;

    if p_xero_status is not null
       and not v_can_view_xero then
        raise exception
            'Permission denied: xero.customer_profile_view is required to filter by Xero status.';
    end if;

    return query
    select
        b.customer_id,
        b.customer_code,
        b.customer_name,
        b.customer_type,

        b.primary_contact_name,
        coalesce(b.primary_contact_phone, b.phone),
        coalesce(b.primary_contact_email, b.email),

        b.default_currency,
        b.payment_terms_type,
        b.payment_terms_days,
        b.credit_limit,
        b.is_account_on_hold,

        b.project_count,
        b.active_project_count,

        b.total_invoiced,
        b.total_paid,
        b.total_outstanding,
        b.overdue_outstanding,
        b.unallocated_credit,
        b.available_credit,

        case
            when v_can_view_xero then b.xero_status
            else null
        end,

        b.has_financial_settings,
        r.is_xero_minimum_ready,
        r.is_xero_accounting_ready,
        coalesce(jsonb_array_length(r.readiness_issues), 0),

        count(*) over()

    from public._customer_profile_base b

    join public._customer_xero_readiness r
      on r.customer_id = b.customer_id

    where (
        nullif(btrim(p_search), '') is null
        or b.customer_code ilike '%' || btrim(p_search) || '%'
        or b.customer_name ilike '%' || btrim(p_search) || '%'
        or coalesce(b.primary_contact_name, '')
            ilike '%' || btrim(p_search) || '%'
        or coalesce(b.email, '')
            ilike '%' || btrim(p_search) || '%'
        or coalesce(b.phone, '')
            ilike '%' || btrim(p_search) || '%'
    )
      and (
          p_customer_type is null
          or b.customer_type = p_customer_type
      )
      and (
          p_xero_status is null
          or b.xero_status = p_xero_status
      )
      and (
          p_only_with_balance = false
          or b.total_outstanding > 0
      )
      and (
          p_only_overdue = false
          or b.overdue_outstanding > 0
      )
      and (
          p_only_attention = false
          or b.is_account_on_hold = true
          or b.overdue_outstanding > 0
          or r.is_xero_accounting_ready = false
          or (
              v_can_view_xero
              and b.xero_export_failed_count > 0
          )
      )

    order by
        case
            when b.is_account_on_hold then 0
            when b.overdue_outstanding > 0 then 1
            when r.is_xero_accounting_ready = false then 2
            else 3
        end,
        b.overdue_outstanding desc,
        b.total_outstanding desc,
        b.customer_name

    limit p_limit
    offset p_offset;
end;
$$;


ALTER FUNCTION "public"."list_customer_financial_profiles"("p_search" "text", "p_customer_type" "text", "p_xero_status" "text", "p_only_with_balance" boolean, "p_only_overdue" boolean, "p_only_attention" boolean, "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."list_customer_financial_profiles"("p_search" "text", "p_customer_type" "text", "p_xero_status" "text", "p_only_with_balance" boolean, "p_only_overdue" boolean, "p_only_attention" boolean, "p_limit" integer, "p_offset" integer) IS 'Customer workspace list with contact, project, accounts receivable, risk and Xero readiness summaries.';



CREATE OR REPLACE FUNCTION "public"."list_customer_invoices"("p_search" "text" DEFAULT NULL::"text", "p_document_status" "text" DEFAULT NULL::"text", "p_payment_status" "text" DEFAULT NULL::"text", "p_invoice_type" "text" DEFAULT NULL::"text", "p_customer_id" "uuid" DEFAULT NULL::"uuid", "p_project_id" "uuid" DEFAULT NULL::"uuid", "p_project_site_id" "uuid" DEFAULT NULL::"uuid", "p_date_from" "date" DEFAULT NULL::"date", "p_date_to" "date" DEFAULT NULL::"date", "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS TABLE("customer_invoice_id" "uuid", "invoice_no" "text", "invoice_type" "text", "document_status" "text", "payment_status" "text", "due_status" "text", "customer_id" "uuid", "customer_code" "text", "customer_name" "text", "project_id" "uuid", "project_no" "text", "project_name" "text", "project_site_id" "uuid", "site_code" "text", "site_name" "text", "invoice_date" "date", "due_date" "date", "subtotal_amount" numeric, "tax_amount" numeric, "total_amount" numeric, "paid_amount" numeric, "balance_amount" numeric, "currency_code" "text", "customer_reference" "text", "active_line_count" integer, "active_source_count" integer, "source_types" "jsonb", "days_overdue" integer, "aging_bucket" "text", "total_row_count" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
    perform public.assert_invoice_permission('invoices.view');

    if p_limit < 1 or p_limit > 500 then
        raise exception 'Limit must be between 1 and 500.';
    end if;

    if p_offset < 0 then
        raise exception 'Offset cannot be negative.';
    end if;

    return query
    select
        b.customer_invoice_id,
        b.invoice_no,
        b.invoice_type,
        b.document_status,
        b.payment_status,
        b.due_status,

        b.customer_id,
        b.customer_code,
        b.customer_name,

        b.project_id,
        b.project_no,
        b.project_name,

        b.project_site_id,
        b.site_code,
        b.site_name,

        b.invoice_date,
        b.due_date,

        b.subtotal_amount,
        b.tax_amount,
        b.total_amount,
        b.paid_amount,
        b.balance_amount,
        b.currency_code,

        b.customer_reference,
        b.active_line_count,
        b.active_source_count,
        b.source_types,

        b.days_overdue,
        b.aging_bucket,

        count(*) over() as total_row_count

    from public._invoice_reporting_base b

    where (
        nullif(btrim(p_search), '') is null
        or b.invoice_no ilike '%' || btrim(p_search) || '%'
        or b.customer_name ilike '%' || btrim(p_search) || '%'
        or b.customer_code ilike '%' || btrim(p_search) || '%'
        or coalesce(b.project_no, '') ilike '%' || btrim(p_search) || '%'
        or coalesce(b.project_name, '') ilike '%' || btrim(p_search) || '%'
        or coalesce(b.site_code, '') ilike '%' || btrim(p_search) || '%'
        or coalesce(b.site_name, '') ilike '%' || btrim(p_search) || '%'
        or coalesce(b.customer_reference, '') ilike '%' || btrim(p_search) || '%'
    )
      and (
          p_document_status is null
          or b.document_status = p_document_status
      )
      and (
          p_payment_status is null
          or b.payment_status = p_payment_status
      )
      and (
          p_invoice_type is null
          or b.invoice_type = p_invoice_type
      )
      and (
          p_customer_id is null
          or b.customer_id = p_customer_id
      )
      and (
          p_project_id is null
          or b.project_id = p_project_id
      )
      and (
          p_project_site_id is null
          or b.project_site_id = p_project_site_id
      )
      and (
          p_date_from is null
          or b.invoice_date >= p_date_from
      )
      and (
          p_date_to is null
          or b.invoice_date <= p_date_to
      )

    order by
        b.invoice_date desc,
        b.invoice_no desc

    limit p_limit
    offset p_offset;
end;
$$;


