CREATE OR REPLACE FUNCTION "public"."list_customer_payments"("p_search" "text" DEFAULT NULL::"text", "p_payment_status" "text" DEFAULT NULL::"text", "p_payment_method" "text" DEFAULT NULL::"text", "p_customer_id" "uuid" DEFAULT NULL::"uuid", "p_date_from" "date" DEFAULT NULL::"date", "p_date_to" "date" DEFAULT NULL::"date", "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS TABLE("customer_payment_id" "uuid", "payment_no" "text", "customer_id" "uuid", "customer_code" "text", "customer_name" "text", "payment_date" "date", "payment_method" "text", "amount" numeric, "allocated_amount" numeric, "unallocated_amount" numeric, "currency_code" "text", "reference_no" "text", "payment_status" "text", "active_allocation_count" integer, "allocated_invoices" "jsonb", "reversed_at" timestamp with time zone, "reversal_reason" "text", "total_row_count" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
    perform public.assert_invoice_permission('payments.view');

    if p_limit < 1 or p_limit > 500 then
        raise exception 'Limit must be between 1 and 500.';
    end if;

    if p_offset < 0 then
        raise exception 'Offset cannot be negative.';
    end if;

    return query
    select
        b.customer_payment_id,
        b.payment_no,
        b.customer_id,
        b.customer_code,
        b.customer_name,

        b.payment_date,
        b.payment_method,
        b.amount,
        b.allocated_amount,
        b.unallocated_amount,
        b.currency_code,

        b.reference_no,
        b.payment_status,
        b.active_allocation_count,
        b.allocated_invoices,

        b.reversed_at,
        b.reversal_reason,

        count(*) over() as total_row_count

    from public._payment_reporting_base b

    where (
        nullif(btrim(p_search), '') is null
        or b.payment_no ilike '%' || btrim(p_search) || '%'
        or b.customer_name ilike '%' || btrim(p_search) || '%'
        or b.customer_code ilike '%' || btrim(p_search) || '%'
        or coalesce(b.reference_no, '') ilike '%' || btrim(p_search) || '%'
    )
      and (
          p_payment_status is null
          or b.payment_status = p_payment_status
      )
      and (
          p_payment_method is null
          or b.payment_method = p_payment_method
      )
      and (
          p_customer_id is null
          or b.customer_id = p_customer_id
      )
      and (
          p_date_from is null
          or b.payment_date >= p_date_from
      )
      and (
          p_date_to is null
          or b.payment_date <= p_date_to
      )

    order by
        b.payment_date desc,
        b.payment_no desc

    limit p_limit
    offset p_offset;
end;
$$;


ALTER FUNCTION "public"."list_customer_payments"("p_search" "text", "p_payment_status" "text", "p_payment_method" "text", "p_customer_id" "uuid", "p_date_from" "date", "p_date_to" "date", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."list_customer_payments"("p_search" "text", "p_payment_status" "text", "p_payment_method" "text", "p_customer_id" "uuid", "p_date_from" "date", "p_date_to" "date", "p_limit" integer, "p_offset" integer) IS 'Permission-aware paginated Customer Payment list with allocated and unallocated amounts.';



CREATE OR REPLACE FUNCTION "public"."list_invoice_aging"("p_customer_id" "uuid" DEFAULT NULL::"uuid", "p_only_overdue" boolean DEFAULT false, "p_limit" integer DEFAULT 100, "p_offset" integer DEFAULT 0) RETURNS TABLE("customer_id" "uuid", "customer_code" "text", "customer_name" "text", "currency_code" "text", "open_invoice_count" integer, "total_outstanding" numeric, "current_amount" numeric, "days_1_30" numeric, "days_31_60" numeric, "days_61_90" numeric, "days_90_plus" numeric, "oldest_due_date" "date", "maximum_days_overdue" integer, "total_row_count" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
    perform public.assert_invoice_permission('invoices.view');

    if p_limit < 1 or p_limit > 500 then
        raise exception 'Limit must be between 1 and 500.';
    end if;

    if p_offset < 0 then
        raise exception 'Offset cannot be negative.';
    end if;

    return query
    select
        b.customer_id,
        b.customer_code,
        b.customer_name,
        b.currency_code,

        b.open_invoice_count,
        b.total_outstanding,
        coalesce(b.current_amount, 0),
        coalesce(b.days_1_30, 0),
        coalesce(b.days_31_60, 0),
        coalesce(b.days_61_90, 0),
        coalesce(b.days_90_plus, 0),

        b.oldest_due_date,
        b.maximum_days_overdue,

        count(*) over() as total_row_count

    from public._invoice_aging_summary b

    where (
        p_customer_id is null
        or b.customer_id = p_customer_id
    )
      and (
          p_only_overdue = false
          or (
              coalesce(b.days_1_30, 0)
              + coalesce(b.days_31_60, 0)
              + coalesce(b.days_61_90, 0)
              + coalesce(b.days_90_plus, 0)
          ) > 0
      )

    order by
        (
            coalesce(b.days_1_30, 0)
            + coalesce(b.days_31_60, 0)
            + coalesce(b.days_61_90, 0)
            + coalesce(b.days_90_plus, 0)
        ) desc,
        b.customer_name

    limit p_limit
    offset p_offset;
end;
$$;


ALTER FUNCTION "public"."list_invoice_aging"("p_customer_id" "uuid", "p_only_overdue" boolean, "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


