CREATE OR REPLACE FUNCTION "public"."list_project_financial_summaries"("p_search" "text" DEFAULT NULL::"text", "p_customer_id" "uuid" DEFAULT NULL::"uuid", "p_project_id" "uuid" DEFAULT NULL::"uuid", "p_only_with_outstanding" boolean DEFAULT false, "p_limit" integer DEFAULT 100, "p_offset" integer DEFAULT 0) RETURNS TABLE("project_id" "uuid", "project_no" "text", "project_name" "text", "project_status" "text", "customer_id" "uuid", "customer_code" "text", "customer_name" "text", "original_contract_value" numeric, "approved_variations" numeric, "revised_contract_value" numeric, "total_invoiced" numeric, "total_paid" numeric, "total_outstanding" numeric, "overdue_outstanding" numeric, "available_retention" numeric, "invoice_count" integer, "open_invoice_count" integer, "total_row_count" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
    perform public.assert_invoice_permission(
        'project_profitability.view'
    );

    if p_limit < 1 or p_limit > 500 then
        raise exception 'Limit must be between 1 and 500.';
    end if;

    if p_offset < 0 then
        raise exception 'Offset cannot be negative.';
    end if;

    return query
    select
        b.project_id,
        b.project_no,
        b.project_name,
        b.project_status,

        b.customer_id,
        b.customer_code,
        b.customer_name,

        b.original_contract_value,
        b.approved_variations,
        b.revised_contract_value,

        b.total_invoiced,
        b.total_paid,
        b.total_outstanding,
        b.overdue_outstanding,
        b.available_retention,

        b.invoice_count,
        b.open_invoice_count,

        count(*) over() as total_row_count

    from public._project_financial_summary b

    where (
        nullif(btrim(p_search), '') is null
        or b.project_no ilike '%' || btrim(p_search) || '%'
        or b.project_name ilike '%' || btrim(p_search) || '%'
        or b.customer_code ilike '%' || btrim(p_search) || '%'
        or b.customer_name ilike '%' || btrim(p_search) || '%'
    )
      and (
          p_customer_id is null
          or b.customer_id = p_customer_id
      )
      and (
          p_project_id is null
          or b.project_id = p_project_id
      )
      and (
          p_only_with_outstanding = false
          or b.total_outstanding > 0
      )

    order by
        b.overdue_outstanding desc,
        b.total_outstanding desc,
        b.project_no

    limit p_limit
    offset p_offset;
end;
$$;


ALTER FUNCTION "public"."list_project_financial_summaries"("p_search" "text", "p_customer_id" "uuid", "p_project_id" "uuid", "p_only_with_outstanding" boolean, "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."list_project_financial_summaries"("p_search" "text", "p_customer_id" "uuid", "p_project_id" "uuid", "p_only_with_outstanding" boolean, "p_limit" integer, "p_offset" integer) IS 'Project contract, Accepted Variation, Invoice, Payment, outstanding and Retention summary.';



CREATE OR REPLACE FUNCTION "public"."list_quotations"("p_search" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    v_user_id uuid;

    v_can_view_internal boolean;
    v_can_view_cost boolean;
    v_can_view_margin boolean;

    v_search text;
    v_status text;
    v_limit integer;
    v_offset integer;

    v_total_count bigint;
    v_rows jsonb;
begin
    -- ========================================================================
    -- 1. AUTHENTICATION AND PERMISSION
    -- ========================================================================

    v_user_id := auth.uid();

    if v_user_id is null then
        raise exception
            'Authentication is required.';
    end if;

    if not public.has_permission(
        'quotations.view'
    ) then
        raise exception
            'Permission denied: quotations.view is required.';
    end if;

    v_can_view_internal :=
        public.has_permission(
            'quotations.view_internal'
        );

    v_can_view_cost :=
        public.has_permission(
            'quotations.view_cost'
        );

    v_can_view_margin :=
        public.has_permission(
            'quotations.view_margin'
        );


    -- ========================================================================
    -- 2. NORMALISE PARAMETERS
    -- ========================================================================

    v_search :=
        nullif(
            lower(
                btrim(p_search)
            ),
            ''
        );

    v_status :=
        nullif(
            btrim(p_status),
            ''
        );

    v_limit :=
        greatest(
            1,
            least(
                coalesce(p_limit, 50),
                200
            )
        );

    v_offset :=
        greatest(
            coalesce(p_offset, 0),
            0
        );


    -- ========================================================================
    -- 3. VALIDATE STATUS FILTER
    -- ========================================================================

    if v_status is not null
       and v_status not in (
            'Draft',
            'Sent',
            'Revised',
            'Accepted',
            'Rejected',
            'Cancelled',
            'Expired'
       ) then
        raise exception
            'Invalid quotation status filter: %.',
            v_status;
    end if;


    -- ========================================================================
    -- 4. TOTAL MATCH COUNT
    -- ========================================================================

    select count(*)
    into v_total_count
    from public.quotations q

    left join public.customers c
      on c.customer_id =
         q.customer_id

    left join public.project_sites ps
      on ps.site_id =
         q.project_site_id

    left join public.projects p
      on p.project_id =
         ps.project_id

    where q.is_deleted = false
      and (
            v_status is null
            or q.quotation_status =
               v_status
          )
      and (
            v_search is null
            or lower(
                concat_ws(
                    ' ',
                    q.quotation_no,
                    c.customer_code,
                    c.customer_name,
                    p.project_name,
                    ps.site_code,
                    ps.site_name
                )
            ) like
                '%' || v_search || '%'
          );


    -- ========================================================================
    -- 5. RETURN PAGE
    --
    -- Current commercial totals come from:
    --   - current active revision when current_revision_id exists
    --   - otherwise the base quotation
    -- ========================================================================

    select coalesce(
        jsonb_agg(
            jsonb_build_object(
                'quotation_id',
                    page.quotation_id,

                'quotation_no',
                    page.quotation_no,

                'quotation_status',
                    page.quotation_status,

                'revision_no',
                    page.revision_no,

                'current_revision_id',
                    page.current_revision_id,

                'current_revision_no',
                    page.current_revision_no,

                'current_revision_status',
                    page.current_revision_status,

                'current_version_type',
                    case
                        when page.current_revision_id is null
                            then 'BaseQuotation'
                        else 'Revision'
                    end,

                'customer',
                    jsonb_build_object(
                        'customer_id',
                            page.customer_id,

                        'customer_code',
                            page.customer_code,

                        'customer_name',
                            page.customer_name
                    ),

                'project',
                    jsonb_build_object(
                        'project_id',
                            page.project_id,

                        'project_name',
                            page.project_name
                    ),

                'site',
                    jsonb_build_object(
                        'site_id',
                            page.project_site_id,

                        'site_code',
                            page.site_code,

                        'site_name',
                            page.site_name,

                        'postcode',
                            page.postcode
                    ),

                'quotation_segment',
                    page.quotation_segment,

                'quotation_source',
                    page.quotation_source,

                'issue_date',
                    page.current_issue_date,

                'valid_until',
                    page.current_valid_until,

                'subtotal_amount',
                    page.current_subtotal_amount,

                'discount_amount',
                    page.current_discount_amount,

                'tax_amount',
                    page.current_tax_amount,

                'total_amount',
                    page.current_total_amount,

                'total_cost_amount',
                    case
                        when v_can_view_cost
                            then page.total_cost_amount
                        else null
                    end,

                'total_margin_amount',
                    case
                        when v_can_view_margin
                            then page.total_margin_amount
                        else null
                    end,

                'internal_notes',
                    case
                        when v_can_view_internal
                            then page.current_internal_notes
                        else null
                    end,

                'sent_at',
                    page.sent_at,

                'accepted_at',
                    page.accepted_at,

                'rejected_at',
                    page.rejected_at,

                'rejection_reason',
                    case
                        when v_can_view_internal
                            then page.rejection_reason
                        else null
                    end,

                'cancelled_at',
                    page.cancelled_at,

                'cancellation_reason',
                    case
                        when v_can_view_internal
                            then page.cancellation_reason
                        else null
                    end,

                'created_at',
                    page.created_at,

                'updated_at',
                    page.updated_at
            )
            order by
                page.created_at desc,
                page.quotation_no desc
        ),
        '[]'::jsonb
    )
    into v_rows
    from (
        select
            q.quotation_id,
            q.quotation_no,
            q.quotation_status,
            q.revision_no,

            q.customer_id,
            c.customer_code,
            c.customer_name,

            ps.project_id,
            p.project_name,

            q.project_site_id,
            ps.site_code,
            ps.site_name,
            ps.postcode,

            q.quotation_segment,
            q.quotation_source,

            q.current_revision_id,
            qr.revision_no as current_revision_no,
            qr.revision_status as current_revision_status,

            coalesce(
                qr.issue_date,
                q.issue_date
            ) as current_issue_date,

            coalesce(
                qr.valid_until,
                q.valid_until
            ) as current_valid_until,

            coalesce(
                qr.subtotal_amount,
                q.subtotal_amount
            ) as current_subtotal_amount,

            coalesce(
                qr.discount_amount,
                q.discount_amount
            ) as current_discount_amount,

            coalesce(
                qr.tax_amount,
                q.tax_amount
            ) as current_tax_amount,

            coalesce(
                qr.total_amount,
                q.total_amount
            ) as current_total_amount,

            coalesce(
                qr.internal_notes,
                q.internal_notes
            ) as current_internal_notes,

            metrics.total_cost_amount,
            metrics.total_margin_amount,

            q.sent_at,
            q.accepted_at,

            q.rejected_at,
            q.rejection_reason,

            q.cancelled_at,
            q.cancellation_reason,

            q.created_at,
            q.updated_at

        from public.quotations q

        left join public.customers c
          on c.customer_id =
             q.customer_id

        left join public.project_sites ps
          on ps.site_id =
             q.project_site_id

        left join public.projects p
          on p.project_id =
             ps.project_id

        left join public.quotation_revisions qr
          on qr.revision_id =
             q.current_revision_id
         and qr.quotation_id =
             q.quotation_id
         and qr.is_active = true
         and qr.is_deleted = false

        left join lateral (
            select
                round(
                    coalesce(
                        sum(
                            source_lines.cost_price *
                            source_lines.quantity
                        ),
                        0
                    ),
                    2
                ) as total_cost_amount,

                round(
                    coalesce(
                        sum(
                            source_lines.margin_amount
                        ),
                        0
                    ),
                    2
                ) as total_margin_amount

            from (
                select
                    qrl.cost_price,
                    qrl.quantity,
                    qrl.margin_amount

                from public.quotation_revision_lines qrl

                where q.current_revision_id is not null
                  and qrl.revision_id =
                      q.current_revision_id
                  and qrl.is_deleted = false
                  and qrl.is_optional = false

                union all

                select
                    ql.cost_price,
                    ql.quantity,
                    ql.margin_amount

                from public.quotation_lines ql

                where q.current_revision_id is null
                  and ql.quotation_id =
                      q.quotation_id
                  and ql.is_deleted = false
                  and ql.is_optional = false
            ) source_lines
        ) metrics
          on true

        where q.is_deleted = false
          and (
                v_status is null
                or q.quotation_status =
                   v_status
              )
          and (
                v_search is null
                or lower(
                    concat_ws(
                        ' ',
                        q.quotation_no,
                        c.customer_code,
                        c.customer_name,
                        p.project_name,
                        ps.site_code,
                        ps.site_name
                    )
                ) like
                    '%' || v_search || '%'
              )

        order by
            q.created_at desc,
            q.quotation_no desc

        limit v_limit
        offset v_offset
    ) page;


    -- ========================================================================
    -- 6. RETURN RESULT
    -- ========================================================================

    return jsonb_build_object(
        'permissions',
            jsonb_build_object(
                'view',
                    true,

                'view_internal',
                    v_can_view_internal,

                'view_cost',
                    v_can_view_cost,

                'view_margin',
                    v_can_view_margin
            ),

        'pagination',
            jsonb_build_object(
                'total_count',
                    v_total_count,

                'limit',
                    v_limit,

                'offset',
                    v_offset,

                'returned_count',
                    jsonb_array_length(v_rows)
            ),

        'rows',
            v_rows
    );
end;
$$;


ALTER FUNCTION "public"."list_quotations"("p_search" "text", "p_status" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_site_retention_summaries"("p_customer_id" "uuid" DEFAULT NULL::"uuid", "p_project_id" "uuid" DEFAULT NULL::"uuid", "p_site_id" "uuid" DEFAULT NULL::"uuid", "p_only_with_balance" boolean DEFAULT false, "p_limit" integer DEFAULT 100, "p_offset" integer DEFAULT 0) RETURNS TABLE("site_id" "uuid", "site_code" "text", "site_name" "text", "project_id" "uuid", "project_no" "text", "project_name" "text", "customer_id" "uuid", "customer_code" "text", "customer_name" "text", "is_enabled" boolean, "retention_method" "text", "retention_percent" numeric, "retention_fixed_amount" numeric, "retention_cap_amount" numeric, "retained_amount" numeric, "released_amount" numeric, "adjustment_increase_amount" numeric, "adjustment_decrease_amount" numeric, "reversal_amount" numeric, "available_retention_balance" numeric, "ledger_entry_count" integer, "last_entry_date" "date", "total_row_count" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
    perform public.assert_invoice_permission('retention.view');

    if p_limit < 1 or p_limit > 500 then
        raise exception 'Limit must be between 1 and 500.';
    end if;

    if p_offset < 0 then
        raise exception 'Offset cannot be negative.';
    end if;

    return query
    select
        b.site_id,
        b.site_code,
        b.site_name,

        b.project_id,
        b.project_no,
        b.project_name,

        b.customer_id,
        b.customer_code,
        b.customer_name,

        b.is_enabled,
        b.retention_method,
        b.retention_percent,
        b.retention_fixed_amount,
        b.retention_cap_amount,

        b.retained_amount,
        b.released_amount,
        b.adjustment_increase_amount,
        b.adjustment_decrease_amount,
        b.reversal_amount,
        b.available_retention_balance,

        b.ledger_entry_count,
        b.last_entry_date,

        count(*) over() as total_row_count

    from public._site_retention_summary b

    where (
        p_customer_id is null
        or b.customer_id = p_customer_id
    )
      and (
          p_project_id is null
          or b.project_id = p_project_id
      )
      and (
          p_site_id is null
          or b.site_id = p_site_id
      )
      and (
          p_only_with_balance = false
          or b.available_retention_balance <> 0
      )

    order by
        b.available_retention_balance desc,
        b.project_no,
        b.site_code

    limit p_limit
    offset p_offset;
end;
$$;


