COMMENT ON FUNCTION "public"."list_site_retention_summaries"("p_customer_id" "uuid", "p_project_id" "uuid", "p_site_id" "uuid", "p_only_with_balance" boolean, "p_limit" integer, "p_offset" integer) IS 'Retention configuration and ledger balance grouped by Project Site.';



CREATE OR REPLACE FUNCTION "public"."list_telegram_notification_users"("p_search" "text" DEFAULT NULL::"text", "p_connection_status" "text" DEFAULT NULL::"text") RETURNS TABLE("auth_user_id" "uuid", "email" "text", "display_name" "text", "employee_id" "uuid", "employee_code" "text", "role_codes" "text"[], "account_status" "text", "telegram_connected" boolean, "telegram_enabled" boolean, "telegram_chat_id_masked" "text", "notification_destination_id" "uuid", "connected_at" timestamp with time zone, "daily_report_enabled" boolean, "daily_report_source" "text", "goods_receiving_enabled" boolean, "goods_receiving_source" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
    if not public.has_permission('telegram_notifications.view') then
        raise exception
            'Permission denied: telegram_notifications.view';
    end if;

    return query
    with base_users as (
        select
            app_user.auth_user_id,
            app_user.email,
            coalesce(
                employee.display_name,
                nullif(concat_ws(' ', employee.first_name, employee.last_name), ''),
                app_user.display_name,
                app_user.email
            ) as display_name,
            employee.employee_id,
            employee.employee_code,
            app_user.account_status,
            coalesce(
                array_agg(distinct role.role_code)
                    filter (where role.role_code is not null),
                array[]::text[]
            ) as role_codes
        from public.app_users app_user
        left join public.employees employee
          on employee.auth_user_id = app_user.auth_user_id
         and employee.is_deleted = false
        left join public.app_user_roles user_role
          on user_role.auth_user_id = app_user.auth_user_id
         and user_role.is_active = true
         and user_role.ended_at is null
        left join public.app_roles role
          on role.role_id = user_role.role_id
         and role.is_active = true
        group by
            app_user.auth_user_id,
            app_user.email,
            app_user.display_name,
            app_user.account_status,
            employee.employee_id,
            employee.employee_code,
            employee.display_name,
            employee.first_name,
            employee.last_name
    )
    select
        base_user.auth_user_id,
        base_user.email,
        base_user.display_name,
        base_user.employee_id,
        base_user.employee_code,
        base_user.role_codes,
        base_user.account_status,
        (
            channel.connection_status = 'Connected'
            and destination.notification_destination_id is not null
        ),
        coalesce(channel.is_enabled, false),
        case
            when destination.telegram_chat_id is null then null
            when length(destination.telegram_chat_id) <= 6
                then repeat('•', length(destination.telegram_chat_id))
            else
                left(destination.telegram_chat_id, 4)
                || repeat(
                    '•',
                    greatest(length(destination.telegram_chat_id) - 7, 1)
                )
                || right(destination.telegram_chat_id, 3)
        end,
        destination.notification_destination_id,
        channel.connected_at,
        daily_permission.effective_enabled,
        daily_permission.permission_source,
        (
            completed_permission.effective_enabled
            or partial_permission.effective_enabled
            or issue_permission.effective_enabled
        ),
        case
            when completed_permission.permission_source <> 'Role Default'
              or partial_permission.permission_source <> 'Role Default'
              or issue_permission.permission_source <> 'Role Default'
                then 'User Override'
            else 'Role Default'
        end
    from base_users base_user
    left join public.notification_user_channels channel
      on channel.auth_user_id = base_user.auth_user_id
     and channel.channel_type = 'Telegram'
     and channel.is_deleted = false
    left join public.notification_destinations destination
      on destination.notification_destination_id =
         channel.notification_destination_id
     and destination.is_deleted = false
    cross join lateral public.get_effective_notification_permission(
        base_user.auth_user_id,
        'daily_report_submitted'
    ) daily_permission
    cross join lateral public.get_effective_notification_permission(
        base_user.auth_user_id,
        'site_goods_receiving_completed'
    ) completed_permission
    cross join lateral public.get_effective_notification_permission(
        base_user.auth_user_id,
        'site_goods_receiving_partial'
    ) partial_permission
    cross join lateral public.get_effective_notification_permission(
        base_user.auth_user_id,
        'site_goods_receiving_issue'
    ) issue_permission
    where (
        nullif(trim(p_search), '') is null
        or base_user.display_name ilike '%' || trim(p_search) || '%'
        or base_user.email ilike '%' || trim(p_search) || '%'
        or coalesce(base_user.employee_code, '')
            ilike '%' || trim(p_search) || '%'
    )
      and (
        nullif(trim(p_connection_status), '') is null
        or (
            p_connection_status = 'Connected'
            and channel.connection_status = 'Connected'
        )
        or (
            p_connection_status = 'NotConnected'
            and coalesce(channel.connection_status, 'Disconnected')
                <> 'Connected'
        )
        or (
            p_connection_status = 'Enabled'
            and channel.connection_status = 'Connected'
            and channel.is_enabled = true
        )
        or (
            p_connection_status = 'Disabled'
            and (
                channel.notification_user_channel_id is null
                or channel.is_enabled = false
                or channel.connection_status <> 'Connected'
            )
        )
      )
    order by base_user.display_name, base_user.email;
end;
$$;


ALTER FUNCTION "public"."list_telegram_notification_users"("p_search" "text", "p_connection_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalise_stock_request_item_approval_snapshot"("p_stock_request_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
    v_item record;
    v_request_uom text;
    v_base_uom text;
    v_conversion numeric(18,6);
    v_updated integer := 0;
begin
    if p_stock_request_id is null then
        raise exception 'Stock Request ID is required.';
    end if;

    for v_item in
        select
            sri.stock_request_item_id,
            sri.product_id,
            sri.requested_quantity,
            sri.approved_quantity,
            sri.unit_of_measure,
            sri.request_uom_code,
            sri.base_uom_code,
            sri.conversion_factor_to_base,
            sri.allow_fractional_quantity,
            p.base_uom_code as product_base_uom_code,
            p.default_request_uom_code,
            p.is_active as product_is_active,
            p.is_deleted as product_is_deleted
        from public.stock_request_items sri
        join public.products p
          on p.product_id = sri.product_id
        where sri.stock_request_id = p_stock_request_id
          and sri.is_deleted = false
        order by sri.line_no
        for update of sri
    loop
        if v_item.product_is_deleted or not v_item.product_is_active then
            raise exception
                'Stock Request item % uses an inactive or deleted product.',
                v_item.stock_request_item_id;
        end if;

        v_base_uom := coalesce(
            v_item.base_uom_code,
            v_item.product_base_uom_code
        );

        if v_base_uom is null then
            raise exception
                'Base UOM is missing for Stock Request item %.',
                v_item.stock_request_item_id;
        end if;

        v_request_uom := coalesce(
            v_item.request_uom_code,
            nullif(v_item.unit_of_measure, ''),
            v_item.default_request_uom_code,
            v_base_uom
        );

        if v_request_uom = v_base_uom then
            v_conversion := 1;
        else
            select puc.conversion_factor
            into v_conversion
            from public.product_uom_conversions puc
            where puc.product_id = v_item.product_id
              and puc.from_uom_code = v_request_uom
              and puc.to_uom_code = v_base_uom
              and puc.is_active = true
              and puc.is_deleted = false
            order by puc.sort_order, puc.created_at
            limit 1;

            if v_conversion is null then
                raise exception
                    'No active UOM conversion exists from % to % for Stock Request item %.',
                    v_request_uom,
                    v_base_uom,
                    v_item.stock_request_item_id;
            end if;
        end if;

        update public.stock_request_items
        set
            line_status = case
                when coalesce(approved_quantity, 0) <= 0
                    then 'Rejected'
                when approved_quantity < requested_quantity
                    then 'PartiallyApproved'
                else 'Approved'
            end,
            request_uom_code = v_request_uom,
            base_uom_code = v_base_uom,
            conversion_factor_to_base = v_conversion,
            requested_base_quantity =
                round(requested_quantity * v_conversion, 6),
            approved_base_quantity =
                round(coalesce(approved_quantity, 0) * v_conversion, 6),
            allow_fractional_quantity = coalesce(
                allow_fractional_quantity,
                true
            ),
            updated_at = now(),
            updated_by = coalesce(auth.uid(), updated_by)
        where stock_request_item_id =
              v_item.stock_request_item_id;

        v_updated := v_updated + 1;
    end loop;

    return v_updated;
end;
$$;


ALTER FUNCTION "public"."normalise_stock_request_item_approval_snapshot"("p_stock_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."post_stock_transfer_receipt_to_destination"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
    v_issue public.stock_issues%rowtype;
    v_receipt_line record;
    v_allocation record;
    v_source_lot public.stock_lots%rowtype;

    v_remaining_good numeric(18,6);
    v_already_posted numeric(18,6);
    v_allocation_available numeric(18,6);
    v_post_quantity numeric(18,6);

    v_destination_lot_id uuid;
    v_destination_movement_id uuid;
    v_destination_lot_no text;
    v_post_sequence integer;

    v_total_cost numeric(18,4);
begin
    -- Only act on the confirmation transition.
    if old.receipt_status <> 'Draft'
       or new.receipt_status = 'Draft'
       or new.is_deleted = true then
        return new;
    end if;

    select *
    into v_issue
    from public.stock_issues
    where stock_issue_id = new.stock_issue_id
      and is_deleted = false
    for update;

    if not found then
        raise exception
            'Stock Transfer receipt source Stock Issue was not found.';
    end if;

    if v_issue.delivery_method <> 'StockTransfer' then
        return new;
    end if;

    if v_issue.to_stock_location_id is null then
        raise exception
            'Stock Transfer receipt requires a destination Stock Location.';
    end if;

    if v_issue.from_stock_location_id =
       v_issue.to_stock_location_id then
        raise exception
            'Stock Transfer source and destination locations must differ.';
    end if;

    for v_receipt_line in
        select
            receipt_line.stock_issue_receipt_line_id,
            receipt_line.stock_issue_line_id,
            receipt_line.line_no as receipt_line_no,
            receipt_line.received_base_quantity,
            issue_line.line_no as issue_line_no,
            issue_line.issued_product_id,
            issue_line.base_uom_code,
            issue_line.stock_request_item_id
        from public.stock_issue_receipt_lines receipt_line
        join public.stock_issue_lines issue_line
          on issue_line.stock_issue_line_id =
             receipt_line.stock_issue_line_id
        where receipt_line.stock_issue_receipt_id =
              new.stock_issue_receipt_id
          and receipt_line.is_deleted = false
          and issue_line.is_deleted = false
        order by receipt_line.line_no
    loop
        v_remaining_good :=
            round(
                coalesce(
                    v_receipt_line.received_base_quantity,
                    0
                ),
                6
            );

        -- Damaged and short quantities are intentionally excluded.
        if v_remaining_good <= 0 then
            continue;
        end if;

        v_post_sequence := 0;

        for v_allocation in
            select
                allocation.stock_issue_allocation_id,
                allocation.stock_lot_id,
                allocation.issued_base_quantity,
                allocation.created_at
            from public.stock_issue_allocations allocation
            where allocation.stock_issue_line_id =
                  v_receipt_line.stock_issue_line_id
              and allocation.is_deleted = false
              and allocation.allocation_status = 'Issued'
              and allocation.issued_base_quantity > 0
            order by
                allocation.created_at,
                allocation.stock_issue_allocation_id::text
        loop
            exit when v_remaining_good <= 0;

            select coalesce(
                sum(posting.posted_base_quantity),
                0
            )
            into v_already_posted
            from public.stock_transfer_receipt_postings posting
            where posting.source_stock_issue_allocation_id =
                  v_allocation.stock_issue_allocation_id
              and posting.is_deleted = false;

            v_allocation_available :=
                round(
                    v_allocation.issued_base_quantity
                    - v_already_posted,
                    6
                );

            if v_allocation_available <= 0 then
                continue;
            end if;

            v_post_quantity :=
                least(
                    v_remaining_good,
                    v_allocation_available
                );

            select *
            into v_source_lot
            from public.stock_lots
            where stock_lot_id = v_allocation.stock_lot_id
              and is_deleted = false;

            if not found then
                raise exception
                    'Source Stock Lot for transfer posting was not found.';
            end if;

            if v_source_lot.stock_location_id <>
               v_issue.from_stock_location_id then
                raise exception
                    'Source Stock Lot location does not match the Stock Transfer source location.';
            end if;

            if v_source_lot.product_id <>
               v_receipt_line.issued_product_id then
                raise exception
                    'Source Stock Lot product does not match the Stock Issue line.';
            end if;

            if v_source_lot.base_uom_code <>
               v_receipt_line.base_uom_code then
                raise exception
                    'Source Stock Lot Base UOM does not match the Stock Issue line.';
            end if;

            v_post_sequence := v_post_sequence + 1;

            v_destination_lot_no :=
                'TR-'
                || regexp_replace(
                    v_issue.stock_issue_no,
                    '[^A-Za-z0-9-]',
                    '',
                    'g'
                )
                || '-R'
                || new.receipt_no::text
                || '-L'
                || v_receipt_line.issue_line_no::text
                || '-'
                || v_post_sequence::text;

            -- Deterministic lot number plus receipt-line identity fallback.
            if exists (
                select 1
                from public.stock_lots
                where lot_no = v_destination_lot_no
                  and is_deleted = false
            ) then
                v_destination_lot_no :=
                    v_destination_lot_no
                    || '-'
                    || left(
                        v_receipt_line
                            .stock_issue_receipt_line_id::text,
                        8
                    );
            end if;

            insert into public.stock_lots (
                lot_no,
                product_id,
                stock_location_id,
                supplier_id,
                supplier_delivery_item_id,
                received_date,
                expiry_date,
                base_uom_code,
                received_quantity,
                remaining_quantity,
                reserved_quantity,
                damaged_quantity,
                average_unit_cost,
                lot_status,
                notes,
                is_active,
                is_deleted,
                created_by,
                updated_by
            )
            values (
                v_destination_lot_no,
                v_source_lot.product_id,
                v_issue.to_stock_location_id,
                v_source_lot.supplier_id,
                v_source_lot.supplier_delivery_item_id,
                coalesce(new.received_at::date, current_date),
                v_source_lot.expiry_date,
                v_source_lot.base_uom_code,
                v_post_quantity,
                v_post_quantity,
                0,
                0,
                v_source_lot.average_unit_cost,
                'Available',
                format(
                    'Transferred from lot %s via Stock Issue %s, Receipt %s.',
                    v_source_lot.lot_no,
                    v_issue.stock_issue_no,
                    new.receipt_no
                ),
                true,
                false,
                auth.uid(),
                auth.uid()
            )
            returning stock_lot_id
            into v_destination_lot_id;

            v_total_cost :=
                case
                    when v_source_lot.average_unit_cost is null
                        then null
                    else round(
                        v_post_quantity
                        * v_source_lot.average_unit_cost,
                        4
                    )
                end;

            insert into public.stock_movements (
                stock_lot_id,
                product_id,
                movement_type,
                movement_date,
                quantity,
                base_uom_code,
                from_location_id,
                to_location_id,
                stock_request_item_id,
                supplier_delivery_item_id,
                stock_issue_id,
                stock_issue_allocation_id,
                stock_issue_receipt_id,
                stock_issue_receipt_line_id,
                reference_no,
                reason,
                notes,
                unit_cost,
                total_cost,
                created_by,
                updated_by,
                is_deleted
            )
            values (
                v_destination_lot_id,
                v_source_lot.product_id,
                'Transfer',
                coalesce(new.received_at::date, current_date),
                v_post_quantity,
                v_source_lot.base_uom_code,
                v_issue.from_stock_location_id,
                v_issue.to_stock_location_id,
                v_receipt_line.stock_request_item_id,
                null,
                v_issue.stock_issue_id,
                null,
                new.stock_issue_receipt_id,
                v_receipt_line.stock_issue_receipt_line_id,
                v_issue.stock_issue_no,
                'Stock Transfer Receipt',
                format(
                    'Destination receipt from source lot %s.',
                    v_source_lot.lot_no
                ),
                v_source_lot.average_unit_cost,
                v_total_cost,
                auth.uid(),
                auth.uid(),
                false
            )
            returning stock_movement_id
            into v_destination_movement_id;

            insert into public.stock_transfer_receipt_postings (
                stock_issue_id,
                stock_issue_receipt_id,
                stock_issue_receipt_line_id,
                stock_issue_line_id,
                source_stock_issue_allocation_id,
                source_stock_lot_id,
                destination_stock_lot_id,
                destination_stock_movement_id,
                posted_base_quantity,
                base_uom_code,
                unit_cost,
                total_cost,
                posted_at,
                posted_by,
                notes,
                is_active,
                is_deleted
            )
            values (
                v_issue.stock_issue_id,
                new.stock_issue_receipt_id,
                v_receipt_line.stock_issue_receipt_line_id,
                v_receipt_line.stock_issue_line_id,
                v_allocation.stock_issue_allocation_id,
                v_source_lot.stock_lot_id,
                v_destination_lot_id,
                v_destination_movement_id,
                v_post_quantity,
                v_source_lot.base_uom_code,
                v_source_lot.average_unit_cost,
                v_total_cost,
                now(),
                auth.uid(),
                'Automatic destination stock posting.',
                true,
                false
            );

            v_remaining_good :=
                round(
                    v_remaining_good - v_post_quantity,
                    6
                );
        end loop;

        if v_remaining_good > 0 then
            raise exception
                'Unable to map % % of received Stock Transfer quantity to issued source allocations.',
                v_remaining_good,
                v_receipt_line.base_uom_code;
        end if;
    end loop;

    return new;
end;
$$;


ALTER FUNCTION "public"."post_stock_transfer_receipt_to_destination"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prepare_stock_issue_atomic"("p_stock_issue_id" "uuid", "p_notes" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
    v_issue public.stock_issues%rowtype;
    v_missing_photos integer;
begin
    if not public.has_permission('stock_issues.prepare') then
        raise exception 'Permission denied: stock_issues.prepare.';
    end if;

    select *
    into v_issue
    from public.stock_issues
    where stock_issue_id = p_stock_issue_id
      and is_deleted = false
    for update;

    if not found then
        raise exception 'Stock Issue was not found.';
    end if;

    if v_issue.issue_status <> 'Draft' then
        raise exception
            'Only Draft Stock Issues can be prepared.';
    end if;

    if not exists (
        select 1
        from public.stock_issue_lines
        where stock_issue_id = p_stock_issue_id
          and is_deleted = false
    ) then
        raise exception 'Stock Issue has no active lines.';
    end if;

    if exists (
        select 1
        from public.stock_issue_allocations a
        join public.stock_issue_lines l
          on l.stock_issue_line_id = a.stock_issue_line_id
        join public.stock_lots lot
          on lot.stock_lot_id = a.stock_lot_id
        where l.stock_issue_id = p_stock_issue_id
          and l.is_deleted = false
          and a.is_deleted = false
          and (
              lot.is_deleted = true
              or lot.is_active = false
              or a.allocated_base_quantity >
                 (lot.remaining_quantity - lot.reserved_quantity)
          )
    ) then
        raise exception
            'One or more Stock Issue allocations are no longer available.';
    end if;

    select count(*)
    into v_missing_photos
    from public.inventory_transaction_photos
    where source_type = 'StockIssue'
      and source_id = p_stock_issue_id
      and photo_type = 'Prepared'
      and is_deleted = false;

    -- Prepared photos are recommended, not mandatory.
    update public.stock_issue_lines
    set
        line_status = 'Prepared',
        preparation_notes = coalesce(
            nullif(btrim(p_notes), ''),
            preparation_notes
        ),
        updated_at = now(),
        updated_by = auth.uid()
    where stock_issue_id = p_stock_issue_id
      and is_deleted = false;

    update public.stock_issues
    set
        issue_status = 'Prepared',
        prepared_at = now(),
        prepared_by = auth.uid(),
        updated_at = now(),
        updated_by = auth.uid()
    where stock_issue_id = p_stock_issue_id;

    return p_stock_issue_id;
end;
$$;


ALTER FUNCTION "public"."prepare_stock_issue_atomic"("p_stock_issue_id" "uuid", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prepare_tool_loan_atomic"("p_tool_loan_id" "uuid", "p_notes" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
    v_loan public.tool_loans%rowtype;
begin
    if not public.has_permission('tool_loans.prepare') then
        raise exception 'Permission denied: tool_loans.prepare.';
    end if;

    select *
    into v_loan
    from public.tool_loans
    where tool_loan_id = p_tool_loan_id
      and is_deleted = false
    for update;

    if not found then
        raise exception 'Tool Loan was not found.';
    end if;

    if v_loan.loan_status <> 'Approved' then
        raise exception 'Only Approved Tool Loans can be prepared.';
    end if;

    if exists (
        select 1
        from public.tool_loan_items
        where tool_loan_id = p_tool_loan_id
          and is_deleted = false
          and condition_before is null
    ) then
        raise exception
            'Condition Before Issue is required for every Tool Loan item.';
    end if;

    update public.tool_loan_items
    set
        item_status = 'Prepared',
        updated_at = now(),
        updated_by = auth.uid()
    where tool_loan_id = p_tool_loan_id
      and is_deleted = false;

    update public.tool_loans
    set
        loan_status = 'Prepared',
        prepared_at = now(),
        prepared_by = auth.uid(),
        notes = coalesce(nullif(btrim(p_notes), ''), notes),
        updated_at = now(),
        updated_by = auth.uid()
    where tool_loan_id = p_tool_loan_id;

    return p_tool_loan_id;
end;
$$;


