CREATE OR REPLACE FUNCTION "public"."prevent_locked_variation_line_change"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    v_variation_id uuid;
    v_status text;
begin
    if tg_op = 'DELETE' then
        v_variation_id := old.variation_id;
    else
        v_variation_id := new.variation_id;
    end if;

    select v.variation_status
    into v_status
    from public.variations v
    where v.variation_id = v_variation_id;

    if not found then
        raise exception
            'Variation header was not found.';
    end if;

    if v_status <> 'Draft' then
        raise exception
            'Variation lines are immutable after the Variation leaves Draft.';
    end if;

    if tg_op = 'DELETE' then
        return old;
    end if;

    return new;
end;
$$;


