CREATE OR REPLACE FUNCTION "public"."prevent_locked_variation_update"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
    if old.variation_status <> 'Draft' then
        if new.quotation_id is distinct from old.quotation_id
           or new.accepted_revision_id is distinct from old.accepted_revision_id
           or new.customer_id is distinct from old.customer_id
           or new.project_id is distinct from old.project_id
           or new.project_site_id is distinct from old.project_site_id
           or new.variation_reason is distinct from old.variation_reason
           or new.issue_date is distinct from old.issue_date
           or new.valid_until is distinct from old.valid_until
           or new.subtotal is distinct from old.subtotal
           or new.discount_amount is distinct from old.discount_amount
           or new.tax_amount is distinct from old.tax_amount
           or new.total_amount is distinct from old.total_amount
        then
            raise exception
                'Commercial fields of a non-Draft Variation are immutable.';
        end if;
    end if;

    return new;
end;
$$;


