CREATE OR REPLACE FUNCTION "public"."prevent_product_code_change"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
    -- --------------------------------------------------------
    -- Product Code ห้ามแก้หลังสร้างทุกกรณี
    -- --------------------------------------------------------
    if old.product_code is distinct from new.product_code then
        raise exception
            'Product Code cannot be changed after the Product has been created.';
    end if;


    -- --------------------------------------------------------
    -- เมื่อ Product Code ถูกสร้างและ Assign แล้ว
    -- Identity fields ทั้งชุดห้ามแก้
    -- --------------------------------------------------------
    if old.product_code_generated_at is not null then

        if old.product_code_category_variant_id
              is distinct from new.product_code_category_variant_id
           or old.product_code_type_id
              is distinct from new.product_code_type_id
           or old.product_code_size_rule_id
              is distinct from new.product_code_size_rule_id
           or old.product_colour_id
              is distinct from new.product_colour_id
           or old.product_code_size_token
              is distinct from new.product_code_size_token
           or old.product_code_variant_number
              is distinct from new.product_code_variant_number
           or old.product_code_generated_at
              is distinct from new.product_code_generated_at
           or old.product_code_generated_by
              is distinct from new.product_code_generated_by
        then
            raise exception
                'Generated Product Code identity cannot be changed after assignment.';
        end if;

    end if;


    return new;
end;
$$;


ALTER FUNCTION "public"."prevent_product_code_change"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."prevent_product_code_change"() IS 'Prevents Product Code changes after creation and locks all generated Product Code identity fields after product_code_generated_at has been assigned.';



CREATE OR REPLACE FUNCTION "public"."prevent_product_code_master_code_change"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
    old_row jsonb := to_jsonb(old);
    new_row jsonb := to_jsonb(new);
begin
    if tg_table_name = 'product_code_ranges' then
        if old_row ->> 'range_code'
           is distinct from new_row ->> 'range_code' then
            raise exception
                'Product Code Range code cannot be changed.';
        end if;

    elsif tg_table_name = 'product_code_types' then
        if old_row ->> 'type_code'
           is distinct from new_row ->> 'type_code' then
            raise exception
                'Product Type Code cannot be changed.';
        end if;

    elsif tg_table_name = 'product_code_size_rules' then
        if old_row ->> 'size_rule_code'
           is distinct from new_row ->> 'size_rule_code' then
            raise exception
                'Product Size Rule code cannot be changed.';
        end if;

    elsif tg_table_name = 'product_colours' then
        if old_row ->> 'colour_code'
           is distinct from new_row ->> 'colour_code' then
            raise exception
                'Product Colour Code cannot be changed.';
        end if;

    elsif tg_table_name = 'product_code_families' then
        if old_row ->> 'family_code'
           is distinct from new_row ->> 'family_code' then
            raise exception
                'Product Family Code cannot be changed.';
        end if;

    elsif tg_table_name = 'product_code_category_variants' then
        if old_row ->> 'variant_digit'
               is distinct from new_row ->> 'variant_digit'
           or old_row ->> 'product_code_family_id'
               is distinct from new_row ->> 'product_code_family_id' then
            raise exception
                'Product Category Variant code cannot be changed.';
        end if;
    end if;

    return new;
end;
$$;


ALTER FUNCTION "public"."prevent_product_code_master_code_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prevent_product_code_variant_registry_change"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
    if tg_op = 'DELETE' then
        raise exception
            'Used Product Code Variant Codes cannot be deleted or reused.';
    end if;


    if tg_op = 'UPDATE' then

        -- Identity ของ Registry ห้ามเปลี่ยน
        if old.full_category_code
              is distinct from new.full_category_code
           or old.type_code
              is distinct from new.type_code
           or old.size_token
              is distinct from new.size_token
           or old.colour_code
              is distinct from new.colour_code
           or old.variant_number
              is distinct from new.variant_number
           or old.variant_code
              is distinct from new.variant_code
           or old.full_product_code
              is distinct from new.full_product_code
           or old.variant_name
              is distinct from new.variant_name
           or old.variant_description
              is distinct from new.variant_description
           or old.reserved_at
              is distinct from new.reserved_at
           or old.reserved_by
              is distinct from new.reserved_by
        then
            raise exception
                'Used Product Code Variant identity cannot be changed.';
        end if;


        -- product_id เติมได้จาก NULL เป็น Product จริงเพียงครั้งเดียว
        if old.product_id is not null
           and old.product_id is distinct from new.product_id
        then
            raise exception
                'The Product linked to a Product Variant Code cannot be changed.';
        end if;


        -- ไม่อนุญาตให้ล้าง Product ที่เชื่อมแล้ว
        if old.product_id is not null
           and new.product_id is null
        then
            raise exception
                'The Product linked to a Product Variant Code cannot be removed.';
        end if;

    end if;


    return new;
end;
$$;


ALTER FUNCTION "public"."prevent_product_code_variant_registry_change"() OWNER TO "postgres";


