CREATE OR REPLACE FUNCTION "public"."prevent_referenced_quotation_revision_archive"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
    if old.is_deleted = false
       and new.is_deleted = true then

        if exists (
            select 1
            from public.quotations q
            where q.current_revision_id =
                  old.revision_id
               or q.accepted_revision_id =
                  old.revision_id
        ) then
            raise exception
                'Quotation revision cannot be archived while referenced by its parent quotation.';
        end if;

        if exists (
            select 1
            from public.material_requirements mr
            where mr.accepted_revision_id =
                  old.revision_id
              and mr.is_deleted = false
        ) then
            raise exception
                'Quotation revision cannot be archived because it is referenced by a Material Requirement.';
        end if;
    end if;

    return new;
end;
$$;


