CREATE OR REPLACE FUNCTION "public"."preview_product_code"("p_category_variant_id" "uuid", "p_product_code_type_id" "uuid", "p_size_rule_id" "uuid", "p_colour_id" "uuid", "p_first_value" integer DEFAULT NULL::integer, "p_second_value" integer DEFAULT NULL::integer) RETURNS TABLE("product_code_preview" "text", "full_category_code" "text", "category_variant_name" "text", "family_code" "text", "family_name" "text", "type_code" "text", "type_name" "text", "size_token" "text", "size_rule_name" "text", "colour_code" "text", "colour_name" "text", "next_variant_number" smallint, "variant_preview" "text", "warning_text" "text")
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
declare
    v_context record;
    v_next smallint;
begin
    select *
    into v_context
    from public.get_product_code_context(
        p_category_variant_id,
        p_product_code_type_id,
        p_size_rule_id,
        p_colour_id,
        p_first_value,
        p_second_value
    );

    select coalesce(sequence_record.last_variant_number, 0) + 1
    into v_next
    from (
        select 1 as placeholder
    ) base
    left join public.product_code_sequences sequence_record
      on sequence_record.full_category_code =
         v_context.full_category_code
     and sequence_record.type_code = v_context.type_code
     and sequence_record.size_token = v_context.size_token
     and sequence_record.colour_code = v_context.colour_code;

    if v_next > 99 then
        raise exception
            'No Variant Running Number remains for %-%-%-%.',
            v_context.full_category_code,
            v_context.type_code,
            v_context.size_token,
            v_context.colour_code;
    end if;

    return query
    select
        v_context.full_category_code
        || '-' || v_context.type_code
        || '-' || v_context.size_token
        || '-' || v_context.colour_code
        || '-' || lpad(v_next::text, 2, '0'),

        v_context.full_category_code,
        v_context.category_variant_name,
        v_context.family_code,
        v_context.family_name,
        v_context.type_code,
        v_context.type_name,
        v_context.size_token,
        v_context.size_rule_name,
        v_context.colour_code,
        v_context.colour_name,
        v_next,
        lpad(v_next::text, 2, '0'),
        'Preview only. The final Variant Number is allocated when the Product is saved.'::text;
end;
$$;


ALTER FUNCTION "public"."preview_product_code"("p_category_variant_id" "uuid", "p_product_code_type_id" "uuid", "p_size_rule_id" "uuid", "p_colour_id" "uuid", "p_first_value" integer, "p_second_value" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."preview_product_code"("p_category_variant_id" "uuid", "p_product_code_type_id" "uuid", "p_size_rule_id" "uuid", "p_colour_id" "uuid", "p_first_value" integer, "p_second_value" integer) IS 'Returns a non-consuming Product Code preview and readable segment meanings.';



CREATE OR REPLACE FUNCTION "public"."preview_product_code_variant"("p_category_variant_id" "uuid", "p_product_code_type_id" "uuid", "p_size_rule_id" "uuid", "p_colour_id" "uuid", "p_first_value" integer DEFAULT NULL::integer, "p_second_value" integer DEFAULT NULL::integer, "p_variant_number" smallint DEFAULT NULL::smallint, "p_variant_name" "text" DEFAULT NULL::"text", "p_variant_description" "text" DEFAULT NULL::"text") RETURNS TABLE("product_code_preview" "text", "full_category_code" "text", "category_variant_name" "text", "family_code" "text", "family_name" "text", "type_code" "text", "type_name" "text", "size_token" "text", "size_rule_name" "text", "colour_code" "text", "colour_name" "text", "selected_variant_number" smallint, "variant_code" "text", "variant_name" "text", "variant_description" "text", "is_variant_available" boolean, "warning_text" "text")
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
declare
    v_context record;
    v_variant smallint;
    v_variant_name text;
    v_variant_description text;
    v_available boolean;
begin
    select context_record.*
    into v_context
    from public.get_product_code_context(
        p_category_variant_id,
        p_product_code_type_id,
        p_size_rule_id,
        p_colour_id,
        p_first_value,
        p_second_value
    ) as context_record;

    if p_variant_number is null then
        v_variant :=
            public.get_next_available_product_variant_number(
                v_context.full_category_code,
                v_context.type_code,
                v_context.size_token,
                v_context.colour_code
            );
    else
        if p_variant_number < 1 or p_variant_number > 99 then
            raise exception
                'Variant Code must be between 01 and 99.';
        end if;

        v_variant := p_variant_number;
    end if;

    v_variant_name := nullif(btrim(p_variant_name), '');

    if v_variant_name is null then
        raise exception
            'Variant Name is required.';
    end if;

    if char_length(v_variant_name) < 2
       or char_length(v_variant_name) > 120 then
        raise exception
            'Variant Name must contain between 2 and 120 characters.';
    end if;

    v_variant_description :=
        nullif(btrim(p_variant_description), '');

    if v_variant_description is not null
       and (
           char_length(v_variant_description) < 2
           or char_length(v_variant_description) > 500
       ) then
        raise exception
            'Variant Description must contain between 2 and 500 characters.';
    end if;

    select not exists (
        select 1
        from public.product_code_variant_registry registry
        where registry.full_category_code =
              v_context.full_category_code
          and registry.type_code =
              v_context.type_code
          and registry.size_token =
              v_context.size_token
          and registry.colour_code =
              v_context.colour_code
          and registry.variant_number =
              v_variant
    )
    into v_available;

    return query
    select
        (
            v_context.full_category_code
            || '-' || v_context.type_code
            || '-' || v_context.size_token
            || '-' || v_context.colour_code
            || '-' || lpad(v_variant::text, 2, '0')
        )::text,

        v_context.full_category_code::text,
        v_context.category_variant_name::text,
        v_context.family_code::text,
        v_context.family_name::text,
        v_context.type_code::text,
        v_context.type_name::text,
        v_context.size_token::text,
        v_context.size_rule_name::text,
        v_context.colour_code::text,
        v_context.colour_name::text,

        v_variant::smallint,
        lpad(v_variant::text, 2, '0')::text,
        v_variant_name,
        v_variant_description,
        v_available,

        case
            when v_available then
                'Preview only. This Variant Code is currently available.'
            else
                'This Variant Code has already been used for the same Product Code base.'
        end::text;
end;
$$;


ALTER FUNCTION "public"."preview_product_code_variant"("p_category_variant_id" "uuid", "p_product_code_type_id" "uuid", "p_size_rule_id" "uuid", "p_colour_id" "uuid", "p_first_value" integer, "p_second_value" integer, "p_variant_number" smallint, "p_variant_name" "text", "p_variant_description" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."queue_daily_report_submitted_notification"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
    v_transition_timestamp timestamptz;
begin
    if new.approval_status is distinct from 'Submitted' then
        return new;
    end if;

    if tg_op = 'UPDATE'
       and old.approval_status is not distinct from 'Submitted' then
        return new;
    end if;

    v_transition_timestamp :=
        coalesce(new.updated_at, new.created_at, now());

    perform public.enqueue_notification_event(
        p_event_code := 'daily_report_submitted',
        p_source_table := 'daily_reports',
        p_source_id := new.report_id,
        p_event_key := 'daily_report_submitted:'
            || new.report_id::text
            || ':'
            || extract(epoch from v_transition_timestamp)::bigint::text,
        p_payload := jsonb_build_object(
            'report_id', new.report_id,
            'project_id', new.project_id,
            'site_id', new.site_id,
            'area_id', new.area_id,
            'work_order_id', new.work_order_id,
            'report_date', new.report_date,
            'weather_condition', new.weather_condition,
            'workers_count', new.workers_count,
            'completed_quantity', new.completed_quantity,
            'progress_percent', new.progress_percent,
            'approval_status', new.approval_status,
            'work_completed', new.work_completed,
            'issues_found', new.issues_found,
            'next_actions', new.next_actions,
            'notes', new.notes,
            'submitted_at', v_transition_timestamp
        ),
        p_created_by := coalesce(new.updated_by, new.created_by, auth.uid())
    );

    return new;
end;
$$;


ALTER FUNCTION "public"."queue_daily_report_submitted_notification"() OWNER TO "postgres";


