ALTER FUNCTION "public"."reactivate_app_user_atomic"("p_auth_user_id" "uuid", "p_role_code" "text", "p_admin_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."receive_customer_payment_atomic"("p_payment" "jsonb", "p_allocations" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    v_payment_id uuid;
    v_customer_id uuid;
    v_payment_date date;
    v_payment_method text;
    v_amount numeric(18,2);
    v_currency text;
begin
    perform public.assert_invoice_permission('payments.receive');

    if p_payment is null or jsonb_typeof(p_payment) <> 'object' then
        raise exception 'Payment must be a JSON object.';
    end if;

    if p_allocations is null or jsonb_typeof(p_allocations) <> 'array' then
        raise exception 'Payment allocations must be a JSON array.';
    end if;

    if jsonb_array_length(p_allocations) > 0 then
        perform public.assert_invoice_permission('payments.allocate');
    end if;

    v_customer_id := nullif(p_payment ->> 'customer_id', '')::uuid;
    v_payment_date := coalesce(
        nullif(p_payment ->> 'payment_date', '')::date,
        current_date
    );
    v_payment_method := coalesce(
        nullif(btrim(p_payment ->> 'payment_method'), ''),
        'Bank Transfer'
    );
    v_amount := coalesce(
        nullif(p_payment ->> 'amount', '')::numeric,
        0
    );

    if v_customer_id is null then
        raise exception 'Customer is required.';
    end if;

    if not exists (
        select 1
        from public.customers c
        where c.customer_id = v_customer_id
          and c.is_deleted = false
          and c.is_active = true
    ) then
        raise exception 'Customer is missing, inactive, or deleted.';
    end if;

    if v_amount <= 0 then
        raise exception 'Payment amount must be greater than zero.';
    end if;

    select coalesce(
        nullif(btrim(p_payment ->> 'currency_code'), ''),
        cfs.default_currency,
        'AUD'
    )
    into v_currency
    from (select 1) x
    left join public.customer_financial_settings cfs
      on cfs.customer_id = v_customer_id;

    insert into public.customer_payments (
        customer_id,
        payment_date,
        payment_method,
        amount,
        reference_no,
        notes,
        payment_status,
        currency_code,
        created_by,
        updated_by
    )
    values (
        v_customer_id,
        v_payment_date,
        v_payment_method,
        v_amount,
        nullif(btrim(p_payment ->> 'reference_no'), ''),
        nullif(btrim(p_payment ->> 'notes'), ''),
        'Recorded',
        v_currency,
        auth.uid(),
        auth.uid()
    )
    returning customer_payment_id into v_payment_id;

    if jsonb_array_length(p_allocations) > 0 then
        perform public.allocate_customer_payment_atomic(v_payment_id, p_allocations);
    end if;

    return v_payment_id;
end;
$$;


ALTER FUNCTION "public"."receive_customer_payment_atomic"("p_payment" "jsonb", "p_allocations" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."receive_supplier_delivery_item_to_stock"("p_supplier_delivery_item_id" "uuid", "p_stock_location_id" "uuid", "p_lot_no" "text" DEFAULT NULL::"text", "p_expiry_date" "date" DEFAULT NULL::"date", "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
    v_item public.supplier_delivery_items%rowtype;
    v_delivery public.supplier_deliveries%rowtype;
    v_product public.products%rowtype;
    v_location public.stock_locations%rowtype;

    v_stock_lot_id uuid;
    v_stock_movement_id uuid;

    v_lot_no text;
    v_accepted_base_quantity numeric(18, 6);
    v_base_unit_cost numeric(18, 4);
begin
    if not public.is_admin_role() then
        raise exception
            'Only an Admin can receive supplier delivery items into stock.';
    end if;

    select *
    into v_item
    from public.supplier_delivery_items
    where supplier_delivery_item_id =
          p_supplier_delivery_item_id
      and is_deleted = false
    for update;

    if not found then
        raise exception 'Supplier delivery item not found.';
    end if;

    select *
    into v_delivery
    from public.supplier_deliveries
    where supplier_delivery_id =
          v_item.supplier_delivery_id
      and is_deleted = false;

    if not found then
        raise exception 'Supplier delivery not found.';
    end if;

    if v_delivery.delivery_status not in (
        'Received',
        'Partial'
    ) then
        raise exception
            'Delivery status must be Received or Partial before stock receipt.';
    end if;

    select *
    into v_product
    from public.products
    where product_id = v_item.product_id
      and is_deleted = false
      and is_active = true;

    if not found then
        raise exception 'Active product not found.';
    end if;

    if not v_product.is_stock_item then
        raise exception
            'The selected product is not configured as a stock item.';
    end if;

    if v_product.base_uom_code is null then
        raise exception
            'The product does not have a Base UOM.';
    end if;

    select *
    into v_location
    from public.stock_locations
    where stock_location_id = p_stock_location_id
      and is_deleted = false
      and is_active = true;

    if not found then
        raise exception 'Active stock location not found.';
    end if;

    if v_item.accepted_quantity <= 0 then
        raise exception
            'Accepted quantity must be greater than zero.';
    end if;

    if v_item.conversion_factor_to_base <= 0 then
        raise exception
            'Conversion factor to Base UOM must be greater than zero.';
    end if;

    if exists (
        select 1
        from public.stock_lots
        where supplier_delivery_item_id =
              p_supplier_delivery_item_id
          and is_deleted = false
    ) then
        raise exception
            'This supplier delivery item has already been received into stock.';
    end if;

    v_accepted_base_quantity :=
        round(
            v_item.accepted_quantity
            * v_item.conversion_factor_to_base,
            6
        );

    if v_item.unit_cost is null then
        v_base_unit_cost := null;
    else
        v_base_unit_cost :=
            round(
                v_item.unit_cost
                / v_item.conversion_factor_to_base,
                4
            );
    end if;

    v_lot_no := coalesce(
        nullif(trim(p_lot_no), ''),
        v_delivery.delivery_no
        || '-L'
        || lpad(v_item.line_no::text, 3, '0')
    );

    insert into public.stock_lots (
        lot_no,
        product_id,
        stock_location_id,
        supplier_id,
        supplier_delivery_item_id,
        base_uom_code,
        received_quantity,
        remaining_quantity,
        reserved_quantity,
        damaged_quantity,
        average_unit_cost,
        received_date,
        expiry_date,
        lot_status,
        notes,
        is_active,
        is_deleted,
        created_by,
        updated_by
    )
    values (
        v_lot_no,
        v_item.product_id,
        p_stock_location_id,
        v_delivery.supplier_id,
        v_item.supplier_delivery_item_id,
        v_product.base_uom_code,
        v_accepted_base_quantity,
        0,
        0,
        0,
        v_base_unit_cost,
        v_delivery.delivery_date,
        p_expiry_date,
        'Exhausted',
        nullif(trim(p_notes), ''),
        true,
        false,
        auth.uid(),
        auth.uid()
    )
    returning stock_lot_id
    into v_stock_lot_id;

    v_stock_movement_id :=
        public.record_stock_movement(
            p_stock_lot_id :=
                v_stock_lot_id,
            p_movement_type :=
                'Receive',
            p_quantity :=
                v_accepted_base_quantity,
            p_movement_date :=
                v_delivery.delivery_date,
            p_supplier_delivery_item_id :=
                v_item.supplier_delivery_item_id,
            p_reference_no :=
                v_delivery.delivery_no,
            p_reason :=
                'Supplier delivery receipt',
            p_notes :=
                nullif(trim(p_notes), '')
        );

    return jsonb_build_object(
        'stock_lot_id',
        v_stock_lot_id,
        'stock_movement_id',
        v_stock_movement_id,
        'lot_no',
        v_lot_no,
        'received_base_quantity',
        v_accepted_base_quantity,
        'base_uom_code',
        v_product.base_uom_code,
        'base_unit_cost',
        v_base_unit_cost
    );
end;
$$;


ALTER FUNCTION "public"."receive_supplier_delivery_item_to_stock"("p_supplier_delivery_item_id" "uuid", "p_stock_location_id" "uuid", "p_lot_no" "text", "p_expiry_date" "date", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."receive_supplier_replacement"("p_supplier_replacement_claim_id" "uuid", "p_site_id" "uuid", "p_stock_location_id" "uuid", "p_supplier_replacement_note_no" "text", "p_items" "jsonb", "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
    v_auth_user_id uuid;
    v_employee_id uuid;

    v_claim public.supplier_replacement_claims%rowtype;
    v_site public.project_sites%rowtype;
    v_location public.stock_locations%rowtype;

    v_receipt_id uuid;
    v_item_json jsonb;

    v_claim_item public.supplier_replacement_claim_items%rowtype;
    v_product public.products%rowtype;

    v_received_quantity numeric(18, 6);
    v_conversion_factor numeric(18, 6);
    v_received_base_quantity numeric(18, 6);

    v_new_received_quantity numeric(18, 6);
    v_new_received_base_quantity numeric(18, 6);

    v_stock_lot_id uuid;
    v_stock_movement_id uuid;

    v_lot_no text;
    v_item_notes text;

    v_all_items_completed boolean;
    v_any_item_received boolean;

    v_processed_item_count integer := 0;
    v_payload_count integer;
    v_distinct_item_count integer;
begin
    -- ========================================================
    -- 1. AUTHENTICATED EMPLOYEE
    -- ========================================================

    v_auth_user_id := auth.uid();

    if v_auth_user_id is null then
        raise exception
            'Authentication is required to receive replacement goods.';
    end if;

    select employee.employee_id
    into v_employee_id
    from public.employees employee
    where employee.auth_user_id = v_auth_user_id
      and employee.is_active = true
      and employee.is_deleted = false
    limit 1;

    if v_employee_id is null then
        raise exception
            'The signed-in account is not linked to an active employee.';
    end if;


    -- ========================================================
    -- 2. PAYLOAD VALIDATION
    -- ========================================================

    if p_supplier_replacement_claim_id is null then
        raise exception 'Replacement claim is required.';
    end if;

    if p_site_id is null then
        raise exception 'Project site is required.';
    end if;

    if p_stock_location_id is null then
        raise exception 'Stock location is required.';
    end if;

    if p_items is null
       or jsonb_typeof(p_items) <> 'array'
       or jsonb_array_length(p_items) = 0 then
        raise exception
            'At least one replacement claim item must be selected.';
    end if;

    select
        count(*),
        count(
            distinct nullif(
                trim(
                    item.value
                    ->> 'supplier_replacement_claim_item_id'
                ),
                ''
            )
        )
    into
        v_payload_count,
        v_distinct_item_count
    from jsonb_array_elements(p_items) item(value);

    if v_payload_count <> v_distinct_item_count then
        raise exception
            'Duplicate or missing replacement claim item IDs were found.';
    end if;


    -- ========================================================
    -- 3. LOCK CLAIM
    -- ========================================================

    select *
    into v_claim
    from public.supplier_replacement_claims
    where supplier_replacement_claim_id =
          p_supplier_replacement_claim_id
      and is_deleted = false
    for update;

    if not found then
        raise exception 'Replacement claim not found.';
    end if;

    if v_claim.claim_status in (
        'Replacement Completed',
        'Cancelled'
    ) then
        raise exception
            'Replacement claim status % does not allow receiving.',
            v_claim.claim_status;
    end if;

    if v_claim.site_id <> p_site_id then
        raise exception
            'Replacement claim belongs to another site.';
    end if;


    -- ========================================================
    -- 4. VALIDATE SITE AND STOCK LOCATION
    -- ========================================================

    select *
    into v_site
    from public.project_sites
    where site_id = p_site_id
      and is_active = true
      and is_deleted = false;

    if not found then
        raise exception 'Active project site not found.';
    end if;

    select *
    into v_location
    from public.stock_locations
    where stock_location_id = p_stock_location_id
      and is_active = true
      and is_deleted = false;

    if not found then
        raise exception 'Active stock location not found.';
    end if;

    if v_location.site_id is distinct from p_site_id then
        raise exception
            'The stock location does not belong to the selected site.';
    end if;

    if v_location.project_id is not null
       and v_location.project_id is distinct from v_site.project_id then
        raise exception
            'The stock location project does not match the selected site project.';
    end if;


    -- ========================================================
    -- 5. CREATE REPLACEMENT RECEIPT
    -- ========================================================

    insert into public.supplier_replacement_receipts (
        supplier_replacement_claim_id,
        project_id,
        site_id,
        supplier_id,
        supplier_replacement_note_no,
        received_by_employee_id,
        received_at,
        receipt_status,
        notes,
        is_deleted,
        created_by,
        updated_by
    )
    values (
        v_claim.supplier_replacement_claim_id,
        v_site.project_id,
        v_site.site_id,
        v_claim.supplier_id,
        nullif(trim(p_supplier_replacement_note_no), ''),
        v_employee_id,
        now(),
        'Confirmed',
        nullif(trim(p_notes), ''),
        false,
        v_auth_user_id,
        v_auth_user_id
    )
    returning supplier_replacement_receipt_id
    into v_receipt_id;


    -- ========================================================
    -- 6. PROCESS CLAIM ITEMS
    -- ========================================================

    for v_item_json in
        select item.value
        from jsonb_array_elements(p_items) item(value)
    loop
        begin
            select *
            into v_claim_item
            from public.supplier_replacement_claim_items
            where supplier_replacement_claim_item_id =
                  (
                      v_item_json
                      ->> 'supplier_replacement_claim_item_id'
                  )::uuid
              and supplier_replacement_claim_id =
                  p_supplier_replacement_claim_id
              and is_deleted = false
            for update;
        exception
            when invalid_text_representation then
                raise exception
                    'Invalid replacement claim item ID.';
        end;

        if not found then
            raise exception
                'Replacement claim item not found.';
        end if;

        if v_claim_item.item_status in (
            'Completed',
            'Cancelled'
        ) then
            raise exception
                'Replacement claim item status % does not allow receiving.',
                v_claim_item.item_status;
        end if;

        begin
            v_received_quantity :=
                (
                    v_item_json
                    ->> 'received_quantity'
                )::numeric;
        exception
            when invalid_text_representation then
                raise exception
                    'Invalid replacement quantity.';
        end;

        if v_received_quantity is null
           or v_received_quantity <= 0 then
            raise exception
                'Replacement received quantity must be greater than zero.';
        end if;

        v_new_received_quantity :=
            round(
                coalesce(
                    v_claim_item.replacement_received_quantity,
                    0
                )
                + v_received_quantity,
                6
            );

        if v_new_received_quantity >
           round(
               v_claim_item.replacement_required_quantity,
               6
           ) then
            raise exception
                'Replacement quantity exceeds the outstanding claim quantity. Required: %, already received: %, receiving now: %.',
                v_claim_item.replacement_required_quantity,
                v_claim_item.replacement_received_quantity,
                v_received_quantity;
        end if;


        -- ====================================================
        -- 6A. PRODUCT UOM CONVERSION
        -- ====================================================

        select *
        into v_product
        from public.products
        where product_id = v_claim_item.product_id
          and is_active = true
          and is_deleted = false;

        if not found then
            raise exception
                'Active product not found for replacement claim item.';
        end if;

        select product_unit.conversion_to_base
        into v_conversion_factor
        from public.product_units product_unit
        where product_unit.product_id =
              v_claim_item.product_id
          and lower(product_unit.uom_code) =
              lower(v_claim_item.replacement_uom_code)
          and product_unit.is_active = true
          and product_unit.is_deleted = false
        limit 1;

        if v_conversion_factor is null
           or v_conversion_factor <= 0 then
            raise exception
                'Product % does not have an active conversion for replacement UOM %.',
                v_product.product_code,
                v_claim_item.replacement_uom_code;
        end if;

        v_received_base_quantity :=
            round(
                v_received_quantity
                * v_conversion_factor,
                6
            );

        v_new_received_base_quantity :=
            round(
                coalesce(
                    v_claim_item.replacement_received_base_quantity,
                    0
                )
                + v_received_base_quantity,
                6
            );

        if v_claim_item.replacement_required_base_quantity
           is not null
           and v_new_received_base_quantity >
               round(
                   v_claim_item.replacement_required_base_quantity,
                   6
               ) then
            raise exception
                'Replacement base quantity exceeds the required quantity.';
        end if;


        -- ====================================================
        -- 6B. STOCK LOT AND RECEIVE MOVEMENT
        -- ====================================================

        v_item_notes :=
            nullif(
                trim(v_item_json ->> 'notes'),
                ''
            );

        v_stock_lot_id := null;
        v_stock_movement_id := null;

        if coalesce(v_product.is_stock_item, false) then
            v_lot_no :=
                coalesce(
                    nullif(
                        trim(v_item_json ->> 'lot_no'),
                        ''
                    ),
                    'RPL-'
                    || upper(
                        substring(v_receipt_id::text, 1, 8)
                    )
                    || '-'
                    || upper(
                        substring(
                            v_claim_item
                                .supplier_replacement_claim_item_id::text,
                            1,
                            8
                        )
                    )
                );

            insert into public.stock_lots (
                lot_no,
                product_id,
                stock_location_id,
                supplier_id,
                supplier_delivery_item_id,
                base_uom_code,
                received_quantity,
                remaining_quantity,
                reserved_quantity,
                damaged_quantity,
                average_unit_cost,
                received_date,
                expiry_date,
                lot_status,
                notes,
                is_active,
                is_deleted,
                created_by,
                updated_by
            )
            values (
                v_lot_no,
                v_claim_item.product_id,
                v_location.stock_location_id,
                v_claim.supplier_id,
                v_claim_item.supplier_delivery_item_id,
                v_product.base_uom_code,
                v_received_base_quantity,
                v_received_base_quantity,
                0,
                0,
                0,
                current_date,
                null,
                'Available',
                coalesce(
                    v_item_notes,
                    'Supplier replacement goods received at no additional purchase cost.'
                ),
                true,
                false,
                v_auth_user_id,
                v_auth_user_id
            )
            returning stock_lot_id
            into v_stock_lot_id;

            insert into public.stock_movements (
                stock_lot_id,
                product_id,
                movement_type,
                movement_date,
                quantity,
                base_uom_code,
                from_location_id,
                to_location_id,
                stock_request_item_id,
                supplier_delivery_item_id,
                reference_no,
                reason,
                notes,
                unit_cost,
                total_cost,
                created_by,
                updated_by,
                is_deleted
            )
            values (
                v_stock_lot_id,
                v_claim_item.product_id,
                'Receive',
                current_date,
                v_received_base_quantity,
                v_product.base_uom_code,
                null,
                v_location.stock_location_id,
                null,
                v_claim_item.supplier_delivery_item_id,
                coalesce(
                    nullif(trim(p_supplier_replacement_note_no), ''),
                    v_claim.claim_no
                ),
                'Supplier replacement receipt',
                v_item_notes,
                0,
                0,
                v_auth_user_id,
                v_auth_user_id,
                false
            )
            returning stock_movement_id
            into v_stock_movement_id;
        end if;


        -- ====================================================
        -- 6C. REPLACEMENT RECEIPT ITEM
        -- ====================================================

        insert into public.supplier_replacement_receipt_items (
            supplier_replacement_receipt_id,
            supplier_replacement_claim_item_id,
            product_id,
            received_quantity,
            received_uom_code,
            conversion_factor_to_base,
            received_base_quantity,
            stock_location_id,
            stock_lot_id,
            stock_movement_id,
            notes,
            is_deleted,
            created_by,
            updated_by
        )
        values (
            v_receipt_id,
            v_claim_item.supplier_replacement_claim_item_id,
            v_claim_item.product_id,
            v_received_quantity,
            v_claim_item.replacement_uom_code,
            v_conversion_factor,
            v_received_base_quantity,
            case
                when coalesce(v_product.is_stock_item, false)
                    then v_location.stock_location_id
                else null
            end,
            v_stock_lot_id,
            v_stock_movement_id,
            v_item_notes,
            false,
            v_auth_user_id,
            v_auth_user_id
        );


        -- ====================================================
        -- 6D. UPDATE CLAIM ITEM
        -- ====================================================

        update public.supplier_replacement_claim_items
        set
            replacement_received_quantity =
                v_new_received_quantity,

            replacement_received_base_quantity =
                v_new_received_base_quantity,

            item_status =
                case
                    when v_new_received_quantity >=
                         replacement_required_quantity
                        then 'Completed'
                    else 'Partially Received'
                end,

            updated_at = now(),
            updated_by = v_auth_user_id

        where supplier_replacement_claim_item_id =
              v_claim_item.supplier_replacement_claim_item_id;


        -- Sync summary fields retained on original receipt item
        update public.supplier_delivery_receipt_items
        set
            replacement_received_quantity =
                v_new_received_quantity,
            updated_at = now(),
            updated_by = v_auth_user_id
        where supplier_delivery_receipt_item_id =
              v_claim_item.supplier_delivery_receipt_item_id;

        v_processed_item_count :=
            v_processed_item_count + 1;
    end loop;


    -- ========================================================
    -- 7. UPDATE CLAIM HEADER AND RELEASE PAYMENT HOLD
    -- ========================================================

    select
        coalesce(
            bool_and(
                claim_item.item_status in (
                    'Completed',
                    'Cancelled'
                )
            ),
            false
        ),
        coalesce(
            bool_or(
                claim_item.replacement_received_quantity > 0
            ),
            false
        )
    into
        v_all_items_completed,
        v_any_item_received
    from public.supplier_replacement_claim_items claim_item
    where claim_item.supplier_replacement_claim_id =
          p_supplier_replacement_claim_id
      and claim_item.is_deleted = false;

    if v_all_items_completed then
        update public.supplier_replacement_claims
        set
            claim_status = 'Replacement Completed',
            completed_at = now(),
            completed_by_employee_id = v_employee_id,
            replacement_delivery_note_no =
                coalesce(
                    nullif(
                        trim(p_supplier_replacement_note_no),
                        ''
                    ),
                    replacement_delivery_note_no
                ),
            payment_hold_required = false,
            updated_at = now(),
            updated_by = v_auth_user_id
        where supplier_replacement_claim_id =
              p_supplier_replacement_claim_id;

    elsif v_any_item_received then
        update public.supplier_replacement_claims
        set
            claim_status =
                'Replacement Partially Received',
            replacement_delivery_note_no =
                coalesce(
                    nullif(
                        trim(p_supplier_replacement_note_no),
                        ''
                    ),
                    replacement_delivery_note_no
                ),
            payment_hold_required = true,
            updated_at = now(),
            updated_by = v_auth_user_id
        where supplier_replacement_claim_id =
              p_supplier_replacement_claim_id;
    end if;


    -- ========================================================
    -- 8. RESULT
    -- ========================================================

    return jsonb_build_object(
        'supplier_replacement_receipt_id',
        v_receipt_id,
        'supplier_replacement_claim_id',
        p_supplier_replacement_claim_id,
        'processed_item_count',
        v_processed_item_count,
        'replacement_completed',
        v_all_items_completed,
        'payment_hold_required',
        not v_all_items_completed,
        'received_by_employee_id',
        v_employee_id,
        'site_id',
        p_site_id,
        'stock_location_id',
        p_stock_location_id
    );
end;
$$;


ALTER FUNCTION "public"."receive_supplier_replacement"("p_supplier_replacement_claim_id" "uuid", "p_site_id" "uuid", "p_stock_location_id" "uuid", "p_supplier_replacement_note_no" "text", "p_items" "jsonb", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_stock_issue_event"("p_stock_issue_id" "uuid", "p_event_code" "text", "p_event_name" "text", "p_event_severity" "text", "p_event_key" "text", "p_old_status" "text" DEFAULT NULL::"text", "p_new_status" "text" DEFAULT NULL::"text", "p_stock_issue_receipt_id" "uuid" DEFAULT NULL::"uuid", "p_stock_transfer_receipt_posting_id" "uuid" DEFAULT NULL::"uuid", "p_payload" "jsonb" DEFAULT '{}'::"jsonb", "p_notes" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
    v_issue public.stock_issues%rowtype;
    v_existing_audit_id uuid;
    v_audit_event_id uuid;
    v_notification_event_id uuid;
    v_payload jsonb;
    v_queue_error text;
    v_notification_queued boolean := false;
begin
    select stock_issue_audit_event_id
    into v_existing_audit_id
    from public.stock_issue_audit_events
    where event_key = btrim(p_event_key);

    if v_existing_audit_id is not null then
        return v_existing_audit_id;
    end if;

    select *
    into v_issue
    from public.stock_issues
    where stock_issue_id = p_stock_issue_id
      and is_deleted = false;

    if not found then
        raise exception
            'Stock Issue for audit event was not found.';
    end if;

    if nullif(btrim(p_event_code), '') is null
       or nullif(btrim(p_event_name), '') is null
       or nullif(btrim(p_event_key), '') is null then
        raise exception
            'Audit event code, name and key are required.';
    end if;

    if p_event_severity not in (
        'Info',
        'Warning',
        'Critical'
    ) then
        raise exception
            'Invalid Stock Issue audit event severity %.',
            p_event_severity;
    end if;

    v_payload :=
        coalesce(p_payload, '{}'::jsonb)
        || jsonb_build_object(
            'stock_issue_id', v_issue.stock_issue_id,
            'stock_issue_no', v_issue.stock_issue_no,
            'stock_request_id', v_issue.stock_request_id,
            'project_id', v_issue.project_id,
            'site_id', v_issue.site_id,
            'area_id', v_issue.area_id,
            'work_order_id', v_issue.work_order_id,
            'delivery_method', v_issue.delivery_method,
            'from_stock_location_id',
                v_issue.from_stock_location_id,
            'to_stock_location_id',
                v_issue.to_stock_location_id,
            'stock_issue_receipt_id',
                p_stock_issue_receipt_id,
            'stock_transfer_receipt_posting_id',
                p_stock_transfer_receipt_posting_id,
            'old_status', p_old_status,
            'new_status', p_new_status,
            'event_at', now()
        );

    begin
        v_notification_event_id :=
            public.enqueue_notification_event(
                btrim(p_event_code),
                'stock_issues',
                v_issue.stock_issue_id,
                btrim(p_event_key),
                v_payload,
                auth.uid()
            );

        v_notification_queued :=
            v_notification_event_id is not null;
    exception
        when others then
            get stacked diagnostics
                v_queue_error = message_text;

            v_notification_event_id := null;
            v_notification_queued := false;

            raise warning
                'Stock Issue notification enqueue failed for event %: %',
                p_event_key,
                v_queue_error;
    end;

    insert into public.stock_issue_audit_events (
        stock_issue_id,
        stock_issue_receipt_id,
        stock_transfer_receipt_posting_id,
        notification_event_id,
        notification_queued,
        notification_queue_error,
        event_code,
        event_name,
        event_severity,
        old_status,
        new_status,
        actor_auth_user_id,
        event_at,
        event_key,
        project_id,
        site_id,
        area_id,
        work_order_id,
        stock_request_id,
        payload,
        notes,
        created_by
    )
    values (
        v_issue.stock_issue_id,
        p_stock_issue_receipt_id,
        p_stock_transfer_receipt_posting_id,
        v_notification_event_id,
        v_notification_queued,
        v_queue_error,
        btrim(p_event_code),
        btrim(p_event_name),
        p_event_severity,
        p_old_status,
        p_new_status,
        auth.uid(),
        now(),
        btrim(p_event_key),
        v_issue.project_id,
        v_issue.site_id,
        v_issue.area_id,
        v_issue.work_order_id,
        v_issue.stock_request_id,
        v_payload,
        nullif(btrim(p_notes), ''),
        auth.uid()
    )
    on conflict (event_key) do nothing
    returning stock_issue_audit_event_id
    into v_audit_event_id;

    if v_audit_event_id is null then
        select stock_issue_audit_event_id
        into v_audit_event_id
        from public.stock_issue_audit_events
        where event_key = btrim(p_event_key);
    end if;

    return v_audit_event_id;
end;
$$;


ALTER FUNCTION "public"."record_stock_issue_event"("p_stock_issue_id" "uuid", "p_event_code" "text", "p_event_name" "text", "p_event_severity" "text", "p_event_key" "text", "p_old_status" "text", "p_new_status" "text", "p_stock_issue_receipt_id" "uuid", "p_stock_transfer_receipt_posting_id" "uuid", "p_payload" "jsonb", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_stock_movement"("p_stock_lot_id" "uuid", "p_movement_type" "text", "p_quantity" numeric, "p_movement_date" "date" DEFAULT CURRENT_DATE, "p_stock_request_item_id" "uuid" DEFAULT NULL::"uuid", "p_supplier_delivery_item_id" "uuid" DEFAULT NULL::"uuid", "p_reference_no" "text" DEFAULT NULL::"text", "p_reason" "text" DEFAULT NULL::"text", "p_notes" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
    v_lot public.stock_lots%rowtype;
    v_stock_movement_id uuid;
    v_new_remaining numeric(18, 6);
    v_new_reserved numeric(18, 6);
    v_new_damaged numeric(18, 6);
    v_new_status text;
begin
    if not public.is_admin_role() then
        raise exception 'Only an Admin can record stock movements.';
    end if;

    if p_quantity is null or p_quantity <= 0 then
        raise exception 'Movement quantity must be greater than zero.';
    end if;

    if p_movement_type not in (
        'Receive',
        'Reserve',
        'Release Reservation',
        'Issue',
        'Return',
        'Damage',
        'Write-off',
        'Adjustment In',
        'Adjustment Out'
    ) then
        raise exception 'Unsupported stock movement type: %', p_movement_type;
    end if;

    select *
    into v_lot
    from public.stock_lots
    where stock_lot_id = p_stock_lot_id
      and is_deleted = false
    for update;

    if not found then
        raise exception 'Stock lot not found.';
    end if;

    v_new_remaining := v_lot.remaining_quantity;
    v_new_reserved := v_lot.reserved_quantity;
    v_new_damaged := v_lot.damaged_quantity;

    case p_movement_type
        when 'Receive' then
            v_new_remaining := v_new_remaining + p_quantity;

            if v_new_remaining > v_lot.received_quantity then
                raise exception
                    'Remaining quantity cannot exceed received quantity. Update the lot received quantity first.';
            end if;

        when 'Reserve' then
            if p_quantity > (v_new_remaining - v_new_reserved) then
                raise exception 'Insufficient available quantity to reserve.';
            end if;

            v_new_reserved := v_new_reserved + p_quantity;

        when 'Release Reservation' then
            if p_quantity > v_new_reserved then
                raise exception 'Release quantity exceeds reserved quantity.';
            end if;

            v_new_reserved := v_new_reserved - p_quantity;

        when 'Issue' then
            if p_quantity > v_new_remaining then
                raise exception 'Issue quantity exceeds remaining quantity.';
            end if;

            v_new_remaining := v_new_remaining - p_quantity;

            if p_quantity <= v_new_reserved then
                v_new_reserved := v_new_reserved - p_quantity;
            else
                v_new_reserved := 0;
            end if;

        when 'Return' then
            v_new_remaining := v_new_remaining + p_quantity;

            if v_new_remaining > v_lot.received_quantity then
                raise exception
                    'Return would make remaining quantity exceed received quantity.';
            end if;

        when 'Damage' then
            if p_quantity > v_new_remaining then
                raise exception 'Damage quantity exceeds remaining quantity.';
            end if;

            v_new_remaining := v_new_remaining - p_quantity;
            v_new_damaged := v_new_damaged + p_quantity;

            if v_new_reserved > v_new_remaining then
                v_new_reserved := v_new_remaining;
            end if;

        when 'Write-off' then
            if p_quantity > v_new_remaining then
                raise exception 'Write-off quantity exceeds remaining quantity.';
            end if;

            v_new_remaining := v_new_remaining - p_quantity;

            if v_new_reserved > v_new_remaining then
                v_new_reserved := v_new_remaining;
            end if;

        when 'Adjustment In' then
            v_new_remaining := v_new_remaining + p_quantity;

            if v_new_remaining > v_lot.received_quantity then
                raise exception
                    'Adjustment In cannot make remaining quantity exceed received quantity.';
            end if;

        when 'Adjustment Out' then
            if p_quantity > v_new_remaining then
                raise exception 'Adjustment Out quantity exceeds remaining quantity.';
            end if;

            v_new_remaining := v_new_remaining - p_quantity;

            if v_new_reserved > v_new_remaining then
                v_new_reserved := v_new_remaining;
            end if;
    end case;

    if v_new_remaining = 0
       and v_new_damaged = v_lot.received_quantity
       and v_lot.received_quantity > 0 then
        v_new_status := 'Damaged';
    elsif v_new_remaining = 0 then
        v_new_status := 'Exhausted';
    elsif v_new_reserved = v_new_remaining then
        v_new_status := 'Reserved';
    elsif v_new_remaining < v_lot.received_quantity then
        v_new_status := 'Partially Issued';
    else
        v_new_status := 'Available';
    end if;

    update public.stock_lots
    set
        remaining_quantity = v_new_remaining,
        reserved_quantity = v_new_reserved,
        damaged_quantity = v_new_damaged,
        lot_status = v_new_status,
        updated_by = auth.uid()
    where stock_lot_id = p_stock_lot_id;

    insert into public.stock_movements (
        stock_lot_id,
        product_id,
        movement_type,
        movement_date,
        quantity,
        base_uom_code,
        from_location_id,
        to_location_id,
        stock_request_item_id,
        supplier_delivery_item_id,
        reference_no,
        reason,
        notes,
        unit_cost,
        total_cost,
        created_by,
        updated_by,
        is_deleted
    )
    values (
        v_lot.stock_lot_id,
        v_lot.product_id,
        p_movement_type,
        coalesce(p_movement_date, current_date),
        p_quantity,
        v_lot.base_uom_code,
        case
            when p_movement_type in (
                'Issue',
                'Damage',
                'Write-off',
                'Adjustment Out'
            )
            then v_lot.stock_location_id
            else null
        end,
        case
            when p_movement_type in (
                'Receive',
                'Return',
                'Adjustment In'
            )
            then v_lot.stock_location_id
            else null
        end,
        p_stock_request_item_id,
        p_supplier_delivery_item_id,
        nullif(trim(p_reference_no), ''),
        nullif(trim(p_reason), ''),
        nullif(trim(p_notes), ''),
        v_lot.average_unit_cost,
        case
            when v_lot.average_unit_cost is null then null
            else round(p_quantity * v_lot.average_unit_cost, 4)
        end,
        auth.uid(),
        auth.uid(),
        false
    )
    returning stock_movement_id
    into v_stock_movement_id;

    return v_stock_movement_id;
end;
$$;


ALTER FUNCTION "public"."record_stock_movement"("p_stock_lot_id" "uuid", "p_movement_type" "text", "p_quantity" numeric, "p_movement_date" "date", "p_stock_request_item_id" "uuid", "p_supplier_delivery_item_id" "uuid", "p_reference_no" "text", "p_reason" "text", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refresh_stock_request_issue_progress"("p_stock_request_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
    v_new_status text;
    v_any_issue boolean;
    v_all_issued boolean;
    v_any_reserved boolean;
    v_all_committed boolean;
begin
    if p_stock_request_id is null then
        raise exception 'Stock Request is required.';
    end if;

    with progress as (
        select
            sri.stock_request_item_id,
            coalesce(sri.approved_base_quantity, 0) as approved_base_quantity,
            coalesce(
                sum(sm.quantity) filter (
                    where sm.movement_type = 'Issue'
                      and sm.is_deleted = false
                ),
                0
            ) as issued_base_quantity,
            coalesce(
                sum(
                    case
                        when sm.movement_type = 'Reserve' then sm.quantity
                        when sm.movement_type = 'Release Reservation' then -sm.quantity
                        when sm.movement_type = 'Issue' then -sm.quantity
                        else 0
                    end
                ) filter (
                    where sm.is_deleted = false
                      and sm.movement_type in (
                          'Reserve',
                          'Release Reservation',
                          'Issue'
                      )
                ),
                0
            ) as reserved_remaining_base_quantity
        from public.stock_request_items sri
        left join public.stock_movements sm
          on sm.stock_request_item_id = sri.stock_request_item_id
        where sri.stock_request_id = p_stock_request_id
          and sri.is_deleted = false
          and coalesce(sri.approved_base_quantity, 0) > 0
          and coalesce(sri.fulfilment_method, 'Issue') = 'Issue'
        group by
            sri.stock_request_item_id,
            sri.approved_base_quantity
    )
    select
        coalesce(bool_or(issued_base_quantity > 0), false),
        coalesce(
            bool_and(
                issued_base_quantity >= approved_base_quantity
            ),
            false
        ),
        coalesce(
            bool_or(reserved_remaining_base_quantity > 0),
            false
        ),
        coalesce(
            bool_and(
                issued_base_quantity
                + reserved_remaining_base_quantity
                >= approved_base_quantity
            ),
            false
        )
    into
        v_any_issue,
        v_all_issued,
        v_any_reserved,
        v_all_committed
    from progress;

    if v_all_issued then
        v_new_status := 'Issued';
    elsif v_any_issue then
        v_new_status := 'Partially Issued';
    elsif v_all_committed then
        v_new_status := 'Reserved';
    elsif v_any_reserved then
        v_new_status := 'Partially Reserved';
    else
        v_new_status := 'Approved';
    end if;

    update public.stock_requests
    set
        request_status = v_new_status,
        updated_at = now(),
        updated_by = auth.uid()
    where stock_request_id = p_stock_request_id
      and is_deleted = false;

    return v_new_status;
end;
$$;


ALTER FUNCTION "public"."refresh_stock_request_issue_progress"("p_stock_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reject_app_user_atomic"("p_auth_user_id" "uuid", "p_reason" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_actor_id uuid;
    v_app_user_id uuid;
BEGIN
    v_actor_id := auth.uid();

    IF v_actor_id IS NULL THEN
        RAISE EXCEPTION 'Authentication required.';
    END IF;

    IF NOT public.has_permission('users.manage_accounts')
       AND NOT public.can_manage_permissions()
    THEN
        RAISE EXCEPTION
            'Permission denied: users.manage_accounts';
    END IF;

    IF p_auth_user_id = v_actor_id THEN
        RAISE EXCEPTION
            'You cannot reject your own account.';
    END IF;

    IF NULLIF(btrim(p_reason), '') IS NULL THEN
        RAISE EXCEPTION
            'Rejection reason is required.';
    END IF;

    SELECT au.app_user_id
    INTO v_app_user_id
    FROM public.app_users au
    WHERE au.auth_user_id = p_auth_user_id
    FOR UPDATE;

    IF v_app_user_id IS NULL THEN
        RAISE EXCEPTION
            'Application user was not found.';
    END IF;

    UPDATE public.app_user_roles
    SET
        is_active = false,
        ended_at = now(),
        ended_by = v_actor_id
    WHERE auth_user_id = p_auth_user_id
      AND is_active = true;

    UPDATE public.app_users
    SET
        account_status = 'Rejected',

        rejected_at = now(),
        rejected_by = v_actor_id,
        rejection_reason = btrim(p_reason),

        suspended_at = NULL,
        suspended_by = NULL,
        suspension_reason = NULL,

        updated_by = v_actor_id
    WHERE app_user_id = v_app_user_id;

    RETURN v_app_user_id;
END;
$$;


ALTER FUNCTION "public"."reject_app_user_atomic"("p_auth_user_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reject_quotation_atomic"("p_quotation_id" "uuid", "p_rejection_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    v_user_id uuid;

    v_quotation_no text;
    v_quotation_status text;

    v_current_revision_id uuid;
    v_accepted_revision_id uuid;
    v_accepted_at timestamptz;
    v_accepted_by uuid;

    v_reason text;
begin
    -- ------------------------------------------------------------------------
    -- Authentication and permission
    -- ------------------------------------------------------------------------

    v_user_id := auth.uid();

    if v_user_id is null then
        raise exception
            'Authentication is required.';
    end if;

    if not public.has_permission(
        'quotations.reject'
    ) then
        raise exception
            'Permission denied: quotations.reject is required.';
    end if;


    -- ------------------------------------------------------------------------
    -- Input validation
    -- ------------------------------------------------------------------------

    if p_quotation_id is null then
        raise exception
            'Quotation ID is required.';
    end if;

    v_reason :=
        nullif(
            btrim(p_rejection_reason),
            ''
        );

    if v_reason is null then
        raise exception
            'Rejection reason is required.';
    end if;


    -- ------------------------------------------------------------------------
    -- Lock quotation
    -- ------------------------------------------------------------------------

    select
        q.quotation_no,
        q.quotation_status,
        q.current_revision_id,
        q.accepted_revision_id,
        q.accepted_at,
        q.accepted_by

    into
        v_quotation_no,
        v_quotation_status,
        v_current_revision_id,
        v_accepted_revision_id,
        v_accepted_at,
        v_accepted_by

    from public.quotations q

    where q.quotation_id =
          p_quotation_id
      and q.is_active = true
      and q.is_deleted = false

    for update;

    if not found then
        raise exception
            'Quotation was not found, is inactive, or is archived.';
    end if;


    -- ------------------------------------------------------------------------
    -- Workflow validation
    -- ------------------------------------------------------------------------

    if v_quotation_status = 'Accepted'
       or v_accepted_revision_id is not null
       or v_accepted_at is not null
       or v_accepted_by is not null then
        raise exception
            'Accepted quotation cannot be rejected. Use a Variation for commercial changes.';
    end if;

    if v_quotation_status <> 'Sent' then
        raise exception
            'Only a Sent base quotation can be rejected. Current status: %.',
            v_quotation_status;
    end if;

    if v_current_revision_id is not null then
        raise exception
            'Base quotation cannot be rejected while a current revision exists. Reject or cancel the current revision first.';
    end if;


    -- ------------------------------------------------------------------------
    -- Reject quotation
    -- ------------------------------------------------------------------------

    update public.quotations
    set
        quotation_status =
            'Rejected',

        rejected_at =
            now(),

        rejected_by =
            v_user_id,

        rejection_reason =
            v_reason,

        cancelled_at =
            null,

        cancelled_by =
            null,

        cancellation_reason =
            null,

        updated_by =
            v_user_id

    where quotation_id =
          p_quotation_id
      and quotation_status =
          'Sent'
      and is_active = true
      and is_deleted = false;

    if not found then
        raise exception
            'Quotation could not be rejected because its workflow state changed.';
    end if;


    -- ------------------------------------------------------------------------
    -- Return
    -- ------------------------------------------------------------------------

    return jsonb_build_object(
        'quotation_id',
            p_quotation_id,

        'quotation_no',
            v_quotation_no,

        'quotation_status',
            'Rejected',

        'rejected_at',
            now(),

        'rejected_by',
            v_user_id,

        'rejection_reason',
            v_reason
    );
end;
$$;


ALTER FUNCTION "public"."reject_quotation_atomic"("p_quotation_id" "uuid", "p_rejection_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reject_quotation_revision_atomic"("p_revision_id" "uuid", "p_rejection_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    v_user_id uuid;

    v_quotation_id uuid;
    v_revision_no integer;
    v_revision_status text;

    v_quotation_no text;
    v_quotation_status text;
    v_current_revision_id uuid;
    v_accepted_revision_id uuid;
    v_accepted_at timestamptz;
    v_accepted_by uuid;

    v_reason text;
    v_rejected_at timestamptz;
begin
    -- ------------------------------------------------------------------------
    -- Authentication and permission
    -- ------------------------------------------------------------------------

    v_user_id := auth.uid();

    if v_user_id is null then
        raise exception
            'Authentication is required.';
    end if;

    if not public.has_permission(
        'quotations.reject'
    ) then
        raise exception
            'Permission denied: quotations.reject is required.';
    end if;


    -- ------------------------------------------------------------------------
    -- Input validation
    -- ------------------------------------------------------------------------

    if p_revision_id is null then
        raise exception
            'Quotation Revision ID is required.';
    end if;

    v_reason :=
        nullif(
            btrim(p_rejection_reason),
            ''
        );

    if v_reason is null then
        raise exception
            'Rejection reason is required.';
    end if;

    v_rejected_at := now();


    -- ------------------------------------------------------------------------
    -- Lock revision
    -- ------------------------------------------------------------------------

    select
        qr.quotation_id,
        qr.revision_no,
        qr.revision_status

    into
        v_quotation_id,
        v_revision_no,
        v_revision_status

    from public.quotation_revisions qr

    where qr.revision_id =
          p_revision_id
      and qr.is_active = true
      and qr.is_deleted = false

    for update;

    if not found then
        raise exception
            'Quotation revision was not found, is inactive, or is archived.';
    end if;


    -- ------------------------------------------------------------------------
    -- Lock parent quotation
    -- ------------------------------------------------------------------------

    select
        q.quotation_no,
        q.quotation_status,
        q.current_revision_id,
        q.accepted_revision_id,
        q.accepted_at,
        q.accepted_by

    into
        v_quotation_no,
        v_quotation_status,
        v_current_revision_id,
        v_accepted_revision_id,
        v_accepted_at,
        v_accepted_by

    from public.quotations q

    where q.quotation_id =
          v_quotation_id
      and q.is_active = true
      and q.is_deleted = false

    for update;

    if not found then
        raise exception
            'Parent quotation was not found, is inactive, or is archived.';
    end if;


    -- ------------------------------------------------------------------------
    -- Workflow validation
    -- ------------------------------------------------------------------------

    if v_revision_status = 'Accepted'
       or v_quotation_status = 'Accepted'
       or v_accepted_revision_id is not null
       or v_accepted_at is not null
       or v_accepted_by is not null then
        raise exception
            'Accepted quotation revision cannot be rejected. Use a Variation for commercial changes.';
    end if;

    if v_revision_status <> 'Sent' then
        raise exception
            'Only a Sent quotation revision can be rejected. Current revision status: %.',
            v_revision_status;
    end if;

    if v_quotation_status <> 'Revised' then
        raise exception
            'Parent quotation must have Revised status before its current revision can be rejected. Current status: %.',
            v_quotation_status;
    end if;

    if v_current_revision_id is distinct from
       p_revision_id then
        raise exception
            'Only the current quotation revision can be rejected.';
    end if;


    -- ------------------------------------------------------------------------
    -- Reject revision first
    --
    -- Parent still points to the revision during this update, which is allowed
    -- because the revision remains active and is not archived.
    -- ------------------------------------------------------------------------

    update public.quotation_revisions
    set
        revision_status =
            'Rejected',

        rejected_at =
            v_rejected_at,

        rejected_by =
            v_user_id,

        rejection_reason =
            v_reason,

        cancelled_at =
            null,

        cancelled_by =
            null,

        cancellation_reason =
            null,

        updated_by =
            v_user_id

    where revision_id =
          p_revision_id
      and revision_status =
          'Sent'
      and is_active = true
      and is_deleted = false;

    if not found then
        raise exception
            'Quotation revision could not be rejected because its workflow state changed.';
    end if;


    -- ------------------------------------------------------------------------
    -- Restore parent quotation to the last issued base quotation
    -- ------------------------------------------------------------------------

    update public.quotations
    set
        quotation_status =
            'Sent',

        current_revision_id =
            null,

        rejected_at =
            null,

        rejected_by =
            null,

        rejection_reason =
            null,

        cancelled_at =
            null,

        cancelled_by =
            null,

        cancellation_reason =
            null,

        updated_by =
            v_user_id

    where quotation_id =
          v_quotation_id
      and quotation_status =
          'Revised'
      and current_revision_id =
          p_revision_id
      and accepted_revision_id is null
      and accepted_at is null
      and accepted_by is null
      and is_active = true
      and is_deleted = false;

    if not found then
        raise exception
            'Parent quotation could not be restored because its workflow state changed.';
    end if;


    -- ------------------------------------------------------------------------
    -- Return
    -- ------------------------------------------------------------------------

    return jsonb_build_object(
        'quotation_id',
            v_quotation_id,

        'quotation_no',
            v_quotation_no,

        'quotation_status',
            'Sent',

        'revision_id',
            p_revision_id,

        'revision_no',
            v_revision_no,

        'revision_status',
            'Rejected',

        'rejected_at',
            v_rejected_at,

        'rejected_by',
            v_user_id,

        'rejection_reason',
            v_reason,

        'current_revision_id',
            null
    );
end;
$$;


ALTER FUNCTION "public"."reject_quotation_revision_atomic"("p_revision_id" "uuid", "p_rejection_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reject_stock_request"("p_stock_request_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
    v_request public.stock_requests%rowtype;
begin
    if not public.is_admin_role() then
        raise exception
            'Only an Admin or Manager can reject stock requests.';
    end if;

    if p_stock_request_id is null then
        raise exception 'Stock request is required.';
    end if;

    select *
    into v_request
    from public.stock_requests
    where stock_request_id = p_stock_request_id
      and is_deleted = false
    for update;

    if not found then
        raise exception 'Stock request not found.';
    end if;

    if v_request.request_status <> 'Submitted' then
        raise exception
            'Only a Submitted stock request can be rejected. Current status: %.',
            v_request.request_status;
    end if;

    update public.stock_requests
    set
        request_status = 'Rejected',
        updated_at = now(),
        updated_by = auth.uid()
    where stock_request_id = p_stock_request_id;
end;
$$;


ALTER FUNCTION "public"."reject_stock_request"("p_stock_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reject_variation_atomic"("p_variation_id" "uuid", "p_rejection_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    v_user_id uuid := auth.uid();
    v_variation public.variations%rowtype;
    v_reason text;
begin
    if v_user_id is null then
        raise exception 'Authentication is required.';
    end if;

    if not public.has_permission('variations.reject') then
        raise exception 'Permission denied: variations.reject is required.';
    end if;

    v_reason := nullif(btrim(p_rejection_reason), '');
    if v_reason is null then
        raise exception 'Rejection reason is required.';
    end if;

    select *
    into v_variation
    from public.variations
    where variation_id = p_variation_id
      and is_active = true
      and is_deleted = false
    for update;

    if not found then
        raise exception 'Variation was not found, is inactive, or is archived.';
    end if;

    if v_variation.variation_status <> 'Sent' then
        raise exception 'Only a Sent Variation can be rejected. Current status: %.', v_variation.variation_status;
    end if;

    update public.variations
    set
        variation_status = 'Rejected',
        rejected_at = now(),
        rejected_by = v_user_id,
        rejection_reason = v_reason,
        cancelled_at = null,
        cancelled_by = null,
        cancellation_reason = null,
        updated_by = v_user_id
    where variation_id = p_variation_id
      and variation_status = 'Sent';

    return jsonb_build_object(
        'variation_id', p_variation_id,
        'variation_no', v_variation.variation_no,
        'variation_status', 'Rejected',
        'rejection_reason', v_reason
    );
end;
$$;


ALTER FUNCTION "public"."reject_variation_atomic"("p_variation_id" "uuid", "p_rejection_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."remove_mistaken_work_assignment"("p_work_assignment_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_assignment public.work_assignments%rowtype;
  v_has_time_logs boolean;
  v_has_daily_report_workers boolean;
begin
  select *
  into v_assignment
  from public.work_assignments
  where work_assignment_id = p_work_assignment_id
    and coalesce(is_deleted, false) = false;

  if not found then
    raise exception 'Assignment not found or already removed.';
  end if;

  -- If assignment has already been ended, treat it as history.
  -- Do not allow Remove. User must keep it as historical record.
  if v_assignment.ended_at is not null then
    raise exception 'This assignment has already ended. It is history and cannot be removed.';
  end if;

  -- Check time logs directly linked to this assignment.
  select exists (
    select 1
    from public.work_time_logs
    where work_assignment_id = p_work_assignment_id
       or replaces_work_assignment_id = p_work_assignment_id
  )
  into v_has_time_logs;

  if v_has_time_logs then
    raise exception 'This assignment already has time logs. Use End Assignment instead.';
  end if;

  -- Check daily report worker rows directly linked to this assignment.
  select exists (
    select 1
    from public.daily_report_workers
    where work_assignment_id = p_work_assignment_id
  )
  into v_has_daily_report_workers;

  if v_has_daily_report_workers then
    raise exception 'This assignment already has daily report records. Use End Assignment instead.';
  end if;

  -- Safe soft delete only when no work history exists.
  update public.work_assignments
  set
    is_deleted = true,
    updated_at = now()
  where work_assignment_id = p_work_assignment_id
    and coalesce(is_deleted, false) = false;

  if not found then
    raise exception 'Assignment not found or already removed.';
  end if;
end;
$$;


ALTER FUNCTION "public"."remove_mistaken_work_assignment"("p_work_assignment_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reserve_stock_request_item"("p_stock_request_item_id" "uuid", "p_stock_lot_id" "uuid", "p_quantity" numeric, "p_movement_date" "date" DEFAULT CURRENT_DATE, "p_notes" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
    v_request_item public.stock_request_items%rowtype;
    v_request public.stock_requests%rowtype;
    v_lot public.stock_lots%rowtype;
    v_product public.products%rowtype;

    v_request_uom_code text;
    v_base_uom_code text;
    v_conversion_factor numeric(18, 6);
    v_allow_fractional_quantity boolean;
    v_base_quantity numeric(18, 6);
    v_approved_base_quantity numeric(18, 6);
    v_committed_base_quantity numeric(18, 6);

    v_has_missing_conversion boolean;
    v_all_fully_reserved boolean;
    v_any_reserved boolean;
    v_all_fully_issued boolean;
    v_any_issued boolean;

    v_stock_movement_id uuid;
    v_new_request_status text;
begin
    if not public.is_admin_role() then
        raise exception
            'Only an Admin can reserve stock request items.';
    end if;

    if p_stock_request_item_id is null then
        raise exception
            'Stock request item is required.';
    end if;

    if p_stock_lot_id is null then
        raise exception
            'Stock lot is required.';
    end if;

    if p_quantity is null or p_quantity <= 0 then
        raise exception
            'Reserve quantity must be greater than zero.';
    end if;

    select *
    into v_request_item
    from public.stock_request_items
    where stock_request_item_id = p_stock_request_item_id
      and is_deleted = false
    for update;

    if not found then
        raise exception
            'Stock request item not found.';
    end if;

    select *
    into v_request
    from public.stock_requests
    where stock_request_id = v_request_item.stock_request_id
      and is_deleted = false
    for update;

    if not found then
        raise exception
            'Stock request not found.';
    end if;

    if v_request.request_status not in (
        'Approved',
        'Partially Reserved',
        'Reserved',
        'Partially Issued'
    ) then
        raise exception
            'Stock request status % does not allow reservation.',
            v_request.request_status;
    end if;

    if exists (
        select 1
        from public.stock_request_items sri
        where sri.stock_request_id = v_request.stock_request_id
          and sri.is_deleted = false
          and sri.approved_quantity is null
    ) then
        raise exception
            'All active stock request items must have an approved quantity before stock can be reserved.';
    end if;

    if v_request_item.approved_quantity is null then
        raise exception
            'Approved quantity has not been set for this stock request item.';
    end if;

    if v_request_item.approved_quantity <= 0 then
        raise exception
            'Approved quantity must be greater than zero before stock can be reserved.';
    end if;

    select *
    into v_product
    from public.products
    where product_id = v_request_item.product_id
      and is_deleted = false;

    if not found then
        raise exception
            'Product not found.';
    end if;

    select *
    into v_lot
    from public.stock_lots
    where stock_lot_id = p_stock_lot_id
      and is_deleted = false
      and is_active = true
    for update;

    if not found then
        raise exception
            'Active stock lot not found.';
    end if;

    if v_lot.product_id <> v_request_item.product_id then
        raise exception
            'The stock lot product does not match the stock request item product.';
    end if;

    v_request_uom_code :=
        nullif(trim(v_request_item.unit_of_measure), '');

    v_base_uom_code :=
        nullif(trim(v_product.base_uom_code), '');

    if v_request_uom_code is null then
        raise exception
            'Request unit of measure is missing.';
    end if;

    if v_base_uom_code is null then
        raise exception
            'Product base unit of measure is missing.';
    end if;

    if v_lot.base_uom_code <> v_base_uom_code then
        raise exception
            'Stock lot base UOM % does not match product base UOM %.',
            v_lot.base_uom_code,
            v_base_uom_code;
    end if;

    if v_request_uom_code = v_base_uom_code then
        v_conversion_factor := 1;
        v_allow_fractional_quantity := true;
    else
        select
            puc.conversion_factor,
            puc.allow_fractional_quantity
        into
            v_conversion_factor,
            v_allow_fractional_quantity
        from public.product_uom_conversions puc
        where puc.product_id = v_request_item.product_id
          and puc.from_uom_code = v_request_uom_code
          and puc.to_uom_code = v_base_uom_code
          and puc.is_active = true
          and puc.is_deleted = false
        order by
            puc.sort_order,
            puc.created_at
        limit 1;

        if not found then
            raise exception
                'No active UOM conversion exists for product % from % to %.',
                v_product.product_code,
                v_request_uom_code,
                v_base_uom_code;
        end if;
    end if;

    if v_conversion_factor is null
       or v_conversion_factor <= 0 then
        raise exception
            'UOM conversion factor must be greater than zero.';
    end if;

    if coalesce(v_allow_fractional_quantity, true) = false
       and p_quantity <> trunc(p_quantity) then
        raise exception
            'Fractional quantities are not allowed for UOM %.',
            v_request_uom_code;
    end if;

    v_base_quantity :=
        round(p_quantity * v_conversion_factor, 6);

    v_approved_base_quantity :=
        round(
            v_request_item.approved_quantity *
            v_conversion_factor,
            6
        );

    select coalesce(
        sum(
            case
                when sm.movement_type = 'Reserve'
                    then sm.quantity
                when sm.movement_type = 'Release Reservation'
                    then -sm.quantity
                else 0
            end
        ),
        0
    )
    into v_committed_base_quantity
    from public.stock_movements sm
    where sm.stock_request_item_id =
              v_request_item.stock_request_item_id
      and sm.is_deleted = false
      and sm.movement_type in (
          'Reserve',
          'Release Reservation'
      );

    if v_committed_base_quantity + v_base_quantity >
       v_approved_base_quantity then
        raise exception
            'Reserve quantity exceeds the remaining approved quantity. Approved: % % (% %), already committed: % %, requested reserve: % % (% %).',
            v_request_item.approved_quantity,
            v_request_uom_code,
            v_approved_base_quantity,
            v_base_uom_code,
            v_committed_base_quantity,
            v_base_uom_code,
            p_quantity,
            v_request_uom_code,
            v_base_quantity,
            v_base_uom_code;
    end if;

    v_stock_movement_id :=
        public.record_stock_movement(
            p_stock_lot_id =>
                p_stock_lot_id,
            p_movement_type =>
                'Reserve',
            p_quantity =>
                v_base_quantity,
            p_movement_date =>
                coalesce(p_movement_date, current_date),
            p_stock_request_item_id =>
                p_stock_request_item_id,
            p_supplier_delivery_item_id =>
                null,
            p_reference_no =>
                v_request.stock_request_no,
            p_reason =>
                'Stock Request Reservation',
            p_notes =>
                nullif(trim(p_notes), '')
        );

    with item_progress as (
        select
            sri.stock_request_item_id,

            round(
                sri.approved_quantity *
                case
                    when sri.unit_of_measure = p.base_uom_code
                        then 1
                    else conv.conversion_factor
                end,
                6
            ) as approved_base_quantity,

            coalesce(
                sum(
                    case
                        when sm.movement_type = 'Reserve'
                            then sm.quantity
                        when sm.movement_type = 'Release Reservation'
                            then -sm.quantity
                        else 0
                    end
                ),
                0
            ) as committed_base_quantity,

            coalesce(
                sum(
                    case
                        when sm.movement_type = 'Issue'
                            then sm.quantity
                        else 0
                    end
                ),
                0
            ) as issued_base_quantity,

            case
                when sri.unit_of_measure = p.base_uom_code
                    then false
                when conv.conversion_factor is null
                    then true
                else false
            end as missing_conversion
        from public.stock_request_items sri
        join public.products p
            on p.product_id = sri.product_id
           and p.is_deleted = false

        left join lateral (
            select puc.conversion_factor
            from public.product_uom_conversions puc
            where puc.product_id = sri.product_id
              and puc.from_uom_code = sri.unit_of_measure
              and puc.to_uom_code = p.base_uom_code
              and puc.is_active = true
              and puc.is_deleted = false
            order by
                puc.sort_order,
                puc.created_at
            limit 1
        ) conv on true

        left join public.stock_movements sm
            on sm.stock_request_item_id =
               sri.stock_request_item_id
           and sm.is_deleted = false
           and sm.movement_type in (
               'Reserve',
               'Release Reservation',
               'Issue'
           )

        where sri.stock_request_id =
                  v_request.stock_request_id
          and sri.is_deleted = false
          and sri.approved_quantity > 0

        group by
            sri.stock_request_item_id,
            sri.approved_quantity,
            sri.unit_of_measure,
            p.base_uom_code,
            conv.conversion_factor
    )
    select
        coalesce(bool_or(missing_conversion), false),

        coalesce(
            bool_and(
                committed_base_quantity >=
                approved_base_quantity
            ),
            false
        ),

        coalesce(
            bool_or(committed_base_quantity > 0),
            false
        ),

        coalesce(
            bool_and(
                issued_base_quantity >=
                approved_base_quantity
            ),
            false
        ),

        coalesce(
            bool_or(issued_base_quantity > 0),
            false
        )
    into
        v_has_missing_conversion,
        v_all_fully_reserved,
        v_any_reserved,
        v_all_fully_issued,
        v_any_issued
    from item_progress;

    if v_has_missing_conversion then
        raise exception
            'One or more stock request items do not have a valid conversion to their product base UOM.';
    end if;

    if v_all_fully_issued then
        v_new_request_status := 'Issued';

    elsif v_any_issued then
        v_new_request_status := 'Partially Issued';

    elsif v_all_fully_reserved then
        v_new_request_status := 'Reserved';

    elsif v_any_reserved then
        v_new_request_status := 'Partially Reserved';

    else
        v_new_request_status := 'Approved';
    end if;

    update public.stock_requests
    set
        request_status = v_new_request_status,
        updated_at = now(),
        updated_by = auth.uid()
    where stock_request_id =
          v_request.stock_request_id;

    return v_stock_movement_id;
end;
$$;


ALTER FUNCTION "public"."reserve_stock_request_item"("p_stock_request_item_id" "uuid", "p_stock_lot_id" "uuid", "p_quantity" numeric, "p_movement_date" "date", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reset_user_notification_overrides"("p_auth_user_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
    v_deleted_count integer;
begin
    if auth.uid() is null then
        raise exception 'Authentication is required.';
    end if;

    if not public.has_permission('telegram_notifications.manage') then
        raise exception
            'Permission denied: telegram_notifications.manage';
    end if;

    delete from public.notification_user_event_overrides
    where auth_user_id = p_auth_user_id
      and event_code in (
          'daily_report_submitted',
          'site_goods_receiving_completed',
          'site_goods_receiving_partial',
          'site_goods_receiving_issue'
      );

    get diagnostics v_deleted_count = row_count;

    return v_deleted_count;
end;
$$;


ALTER FUNCTION "public"."reset_user_notification_overrides"("p_auth_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reset_user_permission_overrides_atomic"("p_auth_user_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    v_actor_id uuid;
    v_old_values jsonb;
begin
    if auth.uid() is null then
        raise exception 'Authentication required.';
    end if;

    if not (
        public.has_permission(
            'users.manage_permission_overrides'
        )
        or public.can_manage_permissions()
    ) then
        raise exception
            'Permission denied: users.manage_permission_overrides';
    end if;

    v_actor_id := auth.uid();

    if p_auth_user_id = v_actor_id
       and public._active_permission_admin_count(
           p_auth_user_id
       ) < 1
    then
        raise exception
            'You cannot reset the final permission administrator.';
    end if;

    select coalesce(
        jsonb_agg(
            jsonb_build_object(
                'permission_id',
                    upo.permission_id,
                'permission_code',
                    p.permission_code,
                'is_allowed',
                    upo.is_allowed
            )
        ),
        '[]'::jsonb
    )
    into v_old_values
    from public.app_user_permission_overrides upo
    join public.app_permissions p
      on p.permission_id = upo.permission_id
    where upo.auth_user_id = p_auth_user_id
      and upo.is_active = true;

    update public.app_user_permission_overrides
    set
        is_active = false,
        reason = nullif(btrim(p_reason), ''),
        updated_by = v_actor_id
    where auth_user_id = p_auth_user_id
      and is_active = true;

    if found then
        insert into public.access_control_audit_log (
            target_auth_user_id,
            change_type,
            old_value,
            new_value,
            reason,
            changed_by
        )
        values (
            p_auth_user_id,
            'User Overrides Reset',
            v_old_values,
            jsonb_build_object(
                'active_override_count',
                0
            ),
            nullif(btrim(p_reason), ''),
            v_actor_id
        );
    end if;

    if public._active_permission_admin_count() < 1 then
        raise exception
            'At least one active permission administrator must remain.';
    end if;

    return p_auth_user_id;
end;
$$;


ALTER FUNCTION "public"."reset_user_permission_overrides_atomic"("p_auth_user_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_telegram_notification_recipients"("p_event_code" "text", "p_project_id" "uuid" DEFAULT NULL::"uuid", "p_site_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("auth_user_id" "uuid", "display_name" "text", "email" "text", "role_codes" "text"[], "notification_destination_id" "uuid", "destination_name" "text", "telegram_chat_id" "text", "permission_source" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
    with active_users as (
        select
            app_user.auth_user_id,
            coalesce(
                employee.display_name,
                nullif(concat_ws(' ', employee.first_name, employee.last_name), ''),
                app_user.display_name,
                app_user.email
            ) as display_name,
            app_user.email
        from public.app_users app_user
        left join public.employees employee
          on employee.auth_user_id = app_user.auth_user_id
         and employee.is_active = true
         and employee.is_deleted = false
        where app_user.account_status = 'Active'
    ),
    user_role_summary as (
        select
            active_user.auth_user_id,
            active_user.display_name,
            active_user.email,
            coalesce(
                array_agg(distinct role.role_code)
                    filter (where role.role_code is not null),
                array[]::text[]
            ) as role_codes
        from active_users active_user
        left join public.app_user_roles user_role
          on user_role.auth_user_id = active_user.auth_user_id
         and user_role.is_active = true
         and user_role.ended_at is null
        left join public.app_roles role
          on role.role_id = user_role.role_id
         and role.is_active = true
        group by
            active_user.auth_user_id,
            active_user.display_name,
            active_user.email
    )
    select
        user_summary.auth_user_id,
        user_summary.display_name,
        user_summary.email,
        user_summary.role_codes,
        channel.notification_destination_id,
        destination.destination_name,
        destination.telegram_chat_id,
        permission.permission_source
    from user_role_summary user_summary
    join public.notification_user_channels channel
      on channel.auth_user_id = user_summary.auth_user_id
     and channel.channel_type = 'Telegram'
     and channel.connection_status = 'Connected'
     and channel.is_enabled = true
     and channel.is_deleted = false
    join public.notification_destinations destination
      on destination.notification_destination_id =
         channel.notification_destination_id
     and destination.channel_type = 'Telegram'
     and destination.is_active = true
     and destination.is_deleted = false
     and nullif(trim(destination.telegram_chat_id), '') is not null
    cross join lateral public.get_effective_notification_permission(
        user_summary.auth_user_id,
        p_event_code
    ) permission
    where permission.effective_enabled = true
    order by user_summary.display_name, user_summary.auth_user_id;
$$;


ALTER FUNCTION "public"."resolve_telegram_notification_recipients"("p_event_code" "text", "p_project_id" "uuid", "p_site_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."restore_material_requirement_line"("p_material_requirement_line_id" "uuid", "p_adjustment_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_actor uuid;

    v_header public.material_requirements%ROWTYPE;
    v_before public.material_requirement_lines%ROWTYPE;
    v_after public.material_requirement_lines%ROWTYPE;

    v_adjustment_id uuid;
    v_next_adjustment_no integer;
    v_adjustment_reason text;
BEGIN
    v_actor := auth.uid();

    IF v_actor IS NULL THEN
        RAISE EXCEPTION
            'Authentication is required.';
    END IF;

    IF NOT public.has_permission(
        'material_requirements.adjust'
    ) THEN
        RAISE EXCEPTION
            'Permission denied: material_requirements.adjust is required.';
    END IF;

    IF p_material_requirement_line_id IS NULL THEN
        RAISE EXCEPTION
            'Material Requirement Line ID is required.';
    END IF;

    v_adjustment_reason :=
        NULLIF(
            btrim(p_adjustment_reason),
            ''
        );

    IF v_adjustment_reason IS NULL THEN
        RAISE EXCEPTION
            'Adjustment reason is required.';
    END IF;

    SELECT line_row.*
    INTO v_before
    FROM public.material_requirement_lines line_row
    WHERE line_row.material_requirement_line_id =
              p_material_requirement_line_id
      AND line_row.is_active = true
      AND line_row.is_deleted = false
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'Active Material Requirement Line was not found.';
    END IF;

    SELECT header_row.*
    INTO v_header
    FROM public.material_requirements header_row
    WHERE header_row.material_requirement_id =
              v_before.material_requirement_id
      AND header_row.is_active = true
      AND header_row.is_deleted = false
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'Active Material Requirement Header was not found.';
    END IF;

    IF v_header.requirement_status <> 'Draft' THEN
        RAISE EXCEPTION
            'Lines may currently be restored only while the Material Requirement is Draft. Current status: %.',
            v_header.requirement_status;
    END IF;

    IF v_before.line_status <> 'Excluded' THEN
        RAISE EXCEPTION
            'Only an Excluded line may be restored. Current status: %.',
            v_before.line_status;
    END IF;

    UPDATE public.material_requirement_lines
    SET
        line_status = 'Required',
        exclusion_reason = NULL,
        updated_at = now(),
        updated_by = v_actor
    WHERE material_requirement_line_id =
          p_material_requirement_line_id
    RETURNING *
    INTO v_after;

    SELECT COALESCE(
        max(adj.adjustment_no),
        0
    ) + 1
    INTO v_next_adjustment_no
    FROM public.material_requirement_line_adjustments adj
    WHERE adj.material_requirement_line_id =
          p_material_requirement_line_id;

    INSERT INTO public.material_requirement_line_adjustments (
        material_requirement_line_id,
        adjustment_no,
        adjustment_type,
        adjustment_reason,
        before_snapshot,
        after_snapshot,
        base_quantity_change,
        commercial_impact,
        variation_required,
        approval_required,
        approval_status,
        created_by
    )
    VALUES (
        p_material_requirement_line_id,
        v_next_adjustment_no,
        'Restore',
        v_adjustment_reason,
        to_jsonb(v_before),
        to_jsonb(v_after),
        v_after.required_base_quantity,
        v_after.commercial_impact,
        v_after.variation_required,
        CASE
            WHEN v_after.commercial_impact IN (
                'CustomerCharge',
                'CustomerCredit',
                'PendingReview'
            )
            THEN true
            ELSE false
        END,
        CASE
            WHEN v_after.commercial_impact IN (
                'CustomerCharge',
                'CustomerCredit',
                'PendingReview'
            )
            THEN 'Pending'
            ELSE 'NotRequired'
        END,
        v_actor
    )
    RETURNING material_requirement_line_adjustment_id
    INTO v_adjustment_id;

    UPDATE public.material_requirements
    SET
        updated_at = now(),
        updated_by = v_actor
    WHERE material_requirement_id =
          v_before.material_requirement_id;

    RETURN jsonb_build_object(
        'material_requirement_id',
            v_before.material_requirement_id,
        'material_requirement_line_id',
            p_material_requirement_line_id,
        'adjustment_id',
            v_adjustment_id,
        'adjustment_no',
            v_next_adjustment_no,
        'adjustment_type',
            'Restore',
        'previous_line_status',
            v_before.line_status,
        'new_line_status',
            v_after.line_status,
        'base_quantity_change',
            v_after.required_base_quantity,
        'line',
            to_jsonb(v_after)
    );
END;
$$;


ALTER FUNCTION "public"."restore_material_requirement_line"("p_material_requirement_line_id" "uuid", "p_adjustment_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reverse_customer_payment_atomic"("p_payment_id" "uuid", "p_reason" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    v_payment public.customer_payments%rowtype;
    v_invoice_id uuid;
    v_invoice_ids uuid[];
begin
    perform public.assert_invoice_permission('payments.reverse');

    if nullif(btrim(p_reason), '') is null then
        raise exception 'Payment reversal reason is required.';
    end if;

    select *
    into v_payment
    from public.customer_payments
    where customer_payment_id = p_payment_id
      and is_deleted = false
    for update;

    if not found then
        raise exception 'Customer Payment not found.';
    end if;

    if v_payment.payment_status <> 'Recorded' then
        raise exception 'Only Recorded Customer Payments can be reversed.';
    end if;

    select array_agg(
        source.customer_invoice_id
        order by source.customer_invoice_id::text
    )
    into v_invoice_ids
    from (
        select distinct
            a.customer_invoice_id
        from public.customer_payment_allocations a
        where a.customer_payment_id = p_payment_id
          and a.is_deleted = false
          and a.reversed_at is null
    ) source;

    if v_invoice_ids is not null then
        perform 1
        from public.customer_invoices i
        where i.customer_invoice_id = any(v_invoice_ids)
        order by i.customer_invoice_id::text
        for update;
    end if;

    update public.customer_payment_allocations
    set
        reversed_at = now(),
        reversed_by = auth.uid(),
        reversal_reason = btrim(p_reason),
        updated_by = auth.uid()
    where customer_payment_id = p_payment_id
      and is_deleted = false
      and reversed_at is null;

    update public.customer_payments
    set
        payment_status = 'Reversed',
        reversed_at = now(),
        reversed_by = auth.uid(),
        reversal_reason = btrim(p_reason),
        updated_by = auth.uid()
    where customer_payment_id = p_payment_id;

    if v_invoice_ids is not null then
        foreach v_invoice_id in array v_invoice_ids
        loop
            perform public._recalculate_invoice_payment_state(
                v_invoice_id
            );
        end loop;
    end if;

    return p_payment_id;
end;
$$;


ALTER FUNCTION "public"."reverse_customer_payment_atomic"("p_payment_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_product_flooring_spec"("p_product_id" "uuid", "p_dimension_type" "text", "p_plank_width_mm" numeric, "p_plank_length_mm" numeric, "p_plank_thickness_mm" numeric, "p_minimum_length_mm" numeric, "p_maximum_length_mm" numeric, "p_planks_per_box" integer, "p_declared_sqm_per_box" numeric, "p_coverage_method" "text", "p_manufacturer_name" "text" DEFAULT NULL::"text", "p_manufacturer_product_code" "text" DEFAULT NULL::"text", "p_manufacturer_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
    v_auth_user_id uuid;
    v_product public.products%rowtype;

    v_spec_id uuid;

    v_calculated_sqm_per_plank numeric(18, 6);
    v_calculated_sqm_per_box numeric(18, 6);

    v_effective_sqm_per_box numeric(18, 6);
    v_effective_sqm_per_plank numeric(18, 6);

    v_box_unit_id uuid;
    v_plank_unit_id uuid;
begin
    -- ========================================================
    -- 1. AUTH / PERMISSION
    -- ========================================================

    v_auth_user_id := auth.uid();

    if v_auth_user_id is null then
        raise exception 'Authentication is required.';
    end if;

    if not public.is_admin_role() then
        raise exception
            'Only administrators may manage flooring specifications.';
    end if;


    -- ========================================================
    -- 2. PRODUCT
    -- ========================================================

    select *
    into v_product
    from public.products
    where product_id = p_product_id
      and is_deleted = false
    for update;

    if not found then
        raise exception 'Product not found.';
    end if;


    -- ========================================================
    -- 3. VALIDATE GENERAL INPUT
    -- ========================================================

    if p_dimension_type not in (
        'Fixed Size',
        'Random Length',
        'Mixed Sizes',
        'Not Applicable'
    ) then
        raise exception 'Invalid dimension type.';
    end if;

    if p_coverage_method not in (
        'Calculated from Dimensions',
        'Manufacturer Declared'
    ) then
        raise exception 'Invalid coverage method.';
    end if;

    if p_planks_per_box is null
       or p_planks_per_box <= 0 then
        raise exception
            'Planks per box must be greater than zero.';
    end if;


    -- ========================================================
    -- 4. CALCULATE COVERAGE
    -- ========================================================

    if p_dimension_type = 'Fixed Size' then
        if p_plank_width_mm is null
           or p_plank_width_mm <= 0
           or p_plank_length_mm is null
           or p_plank_length_mm <= 0 then
            raise exception
                'Width and length are required for fixed-size flooring.';
        end if;

        v_calculated_sqm_per_plank :=
            round(
                (
                    p_plank_width_mm
                    * p_plank_length_mm
                ) / 1000000.0,
                6
            );

        v_calculated_sqm_per_box :=
            round(
                v_calculated_sqm_per_plank
                * p_planks_per_box,
                6
            );

    elsif p_dimension_type in (
        'Random Length',
        'Mixed Sizes'
    ) then
        if p_plank_width_mm is null
           or p_plank_width_mm <= 0 then
            raise exception
                'Width is required for random or mixed-length flooring.';
        end if;

        if p_minimum_length_mm is null
           or p_maximum_length_mm is null
           or p_minimum_length_mm <= 0
           or p_maximum_length_mm <= 0
           or p_maximum_length_mm < p_minimum_length_mm then
            raise exception
                'A valid minimum and maximum length are required.';
        end if;

        if p_declared_sqm_per_box is null
           or p_declared_sqm_per_box <= 0 then
            raise exception
                'Manufacturer-declared square metres per box are required.';
        end if;

        v_calculated_sqm_per_plank := null;
        v_calculated_sqm_per_box := null;

    else
        raise exception
            'Not Applicable cannot be used for a flooring specification.';
    end if;


    -- ========================================================
    -- 5. EFFECTIVE COVERAGE
    -- ========================================================

    if p_coverage_method = 'Manufacturer Declared' then
        if p_declared_sqm_per_box is null
           or p_declared_sqm_per_box <= 0 then
            raise exception
                'Manufacturer-declared square metres per box are required.';
        end if;

        v_effective_sqm_per_box :=
            round(p_declared_sqm_per_box, 6);

    else
        if p_dimension_type <> 'Fixed Size' then
            raise exception
                'Calculated coverage is supported only for fixed-size flooring.';
        end if;

        v_effective_sqm_per_box :=
            v_calculated_sqm_per_box;
    end if;

    v_effective_sqm_per_plank :=
        round(
            v_effective_sqm_per_box
            / p_planks_per_box,
            6
        );

    if v_effective_sqm_per_box <= 0
       or v_effective_sqm_per_plank <= 0 then
        raise exception
            'Calculated product coverage must be greater than zero.';
    end if;


    -- ========================================================
    -- 6. UPSERT SPECIFICATION
    -- ========================================================

    select spec.product_flooring_spec_id
    into v_spec_id
    from public.product_flooring_specs spec
    where spec.product_id = p_product_id
      and spec.is_deleted = false
    for update;

    if v_spec_id is null then
        insert into public.product_flooring_specs (
            product_id,
            dimension_type,
            plank_width_mm,
            plank_length_mm,
            plank_thickness_mm,
            minimum_length_mm,
            maximum_length_mm,
            planks_per_box,
            declared_sqm_per_box,
            coverage_method,
            manufacturer_name,
            manufacturer_product_code,
            manufacturer_notes,
            is_active,
            is_deleted,
            created_by,
            updated_by
        )
        values (
            p_product_id,
            p_dimension_type,
            p_plank_width_mm,
            p_plank_length_mm,
            p_plank_thickness_mm,
            p_minimum_length_mm,
            p_maximum_length_mm,
            p_planks_per_box,
            p_declared_sqm_per_box,
            p_coverage_method,
            nullif(trim(p_manufacturer_name), ''),
            nullif(trim(p_manufacturer_product_code), ''),
            nullif(trim(p_manufacturer_notes), ''),
            true,
            false,
            v_auth_user_id,
            v_auth_user_id
        )
        returning product_flooring_spec_id
        into v_spec_id;

    else
        update public.product_flooring_specs
        set
            dimension_type = p_dimension_type,
            plank_width_mm = p_plank_width_mm,
            plank_length_mm = p_plank_length_mm,
            plank_thickness_mm = p_plank_thickness_mm,
            minimum_length_mm = p_minimum_length_mm,
            maximum_length_mm = p_maximum_length_mm,
            planks_per_box = p_planks_per_box,
            declared_sqm_per_box = p_declared_sqm_per_box,
            coverage_method = p_coverage_method,
            manufacturer_name =
                nullif(trim(p_manufacturer_name), ''),
            manufacturer_product_code =
                nullif(trim(p_manufacturer_product_code), ''),
            manufacturer_notes =
                nullif(trim(p_manufacturer_notes), ''),
            is_active = true,
            updated_at = now(),
            updated_by = v_auth_user_id
        where product_flooring_spec_id = v_spec_id;
    end if;


    -- ========================================================
    -- 7. SYNC BOX PRODUCT UNIT
    -- ========================================================

    select pu.product_unit_id
    into v_box_unit_id
    from public.product_units pu
    where pu.product_id = p_product_id
      and lower(pu.uom_code) = 'box'
      and pu.is_deleted = false
    for update;

    if v_box_unit_id is null then
        insert into public.product_units (
            product_id,
            uom_code,
            conversion_to_base,
            is_base_unit,
            is_purchase_unit,
            is_stock_unit,
            is_request_unit,
            is_sales_unit,
            coverage_basis_quantity,
            coverage_quantity,
            coverage_uom_code,
            coverage_notes,
            sort_order,
            is_active,
            is_deleted,
            created_by,
            updated_by
        )
        values (
            p_product_id,
            'box',
            v_effective_sqm_per_box,
            false,
            true,
            false,
            true,
            false,
            1,
            v_effective_sqm_per_box,
            'sqm',
            'Automatically synchronized from flooring specification.',
            20,
            true,
            false,
            v_auth_user_id,
            v_auth_user_id
        );
    else
        update public.product_units
        set
            conversion_to_base = v_effective_sqm_per_box,
            coverage_basis_quantity = 1,
            coverage_quantity = v_effective_sqm_per_box,
            coverage_uom_code = 'sqm',
            coverage_notes =
                'Automatically synchronized from flooring specification.',
            is_purchase_unit = true,
            is_request_unit = true,
            is_active = true,
            updated_at = now(),
            updated_by = v_auth_user_id
        where product_unit_id = v_box_unit_id;
    end if;


    -- ========================================================
    -- 8. SYNC PLANK PRODUCT UNIT
    -- ========================================================

    select pu.product_unit_id
    into v_plank_unit_id
    from public.product_units pu
    where pu.product_id = p_product_id
      and lower(pu.uom_code) = 'plank'
      and pu.is_deleted = false
    for update;

    if v_plank_unit_id is null then
        insert into public.product_units (
            product_id,
            uom_code,
            conversion_to_base,
            is_base_unit,
            is_purchase_unit,
            is_stock_unit,
            is_request_unit,
            is_sales_unit,
            coverage_basis_quantity,
            coverage_quantity,
            coverage_uom_code,
            coverage_notes,
            sort_order,
            is_active,
            is_deleted,
            created_by,
            updated_by
        )
        values (
            p_product_id,
            'plank',
            v_effective_sqm_per_plank,
            false,
            false,
            false,
            false,
            false,
            1,
            v_effective_sqm_per_plank,
            'sqm',
            'Automatically synchronized from flooring specification.',
            15,
            true,
            false,
            v_auth_user_id,
            v_auth_user_id
        );
    else
        update public.product_units
        set
            conversion_to_base =
                v_effective_sqm_per_plank,
            coverage_basis_quantity = 1,
            coverage_quantity =
                v_effective_sqm_per_plank,
            coverage_uom_code = 'sqm',
            coverage_notes =
                'Automatically synchronized from flooring specification.',
            is_active = true,
            updated_at = now(),
            updated_by = v_auth_user_id
        where product_unit_id = v_plank_unit_id;
    end if;


    -- ========================================================
    -- 9. SYNC PRODUCT DEFAULT UOMS
    -- ========================================================

    update public.products
    set
        base_uom_code = 'sqm',
        default_purchase_uom_code = 'box',
        default_request_uom_code = 'box',
        updated_at = now(),
        updated_by = v_auth_user_id
    where product_id = p_product_id;


    -- ========================================================
    -- 10. RESULT
    -- ========================================================

    return jsonb_build_object(
        'product_id', p_product_id,
        'product_flooring_spec_id', v_spec_id,
        'dimension_type', p_dimension_type,
        'coverage_method', p_coverage_method,
        'planks_per_box', p_planks_per_box,
        'calculated_sqm_per_plank',
            v_calculated_sqm_per_plank,
        'calculated_sqm_per_box',
            v_calculated_sqm_per_box,
        'effective_sqm_per_plank',
            v_effective_sqm_per_plank,
        'effective_sqm_per_box',
            v_effective_sqm_per_box
    );
end;
$$;


ALTER FUNCTION "public"."save_product_flooring_spec"("p_product_id" "uuid", "p_dimension_type" "text", "p_plank_width_mm" numeric, "p_plank_length_mm" numeric, "p_plank_thickness_mm" numeric, "p_minimum_length_mm" numeric, "p_maximum_length_mm" numeric, "p_planks_per_box" integer, "p_declared_sqm_per_box" numeric, "p_coverage_method" "text", "p_manufacturer_name" "text", "p_manufacturer_product_code" "text", "p_manufacturer_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."send_quotation_atomic"("p_quotation_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    v_user_id uuid;

    v_quotation public.quotations%rowtype;

    v_project_id uuid;
    v_project_customer_id uuid;
    v_site_status text;

    v_line_count integer;
begin
    -- ========================================================
    -- 1. AUTHENTICATION AND PERMISSION
    -- ========================================================

    v_user_id := auth.uid();

    if v_user_id is null then
        raise exception
            'Authentication is required.';
    end if;

    if not public.has_permission(
        'quotations.send'
    ) then
        raise exception
            'Permission denied: quotations.send is required.';
    end if;


    -- ========================================================
    -- 2. LOCK AND LOAD QUOTATION
    -- ========================================================

    select q.*
    into v_quotation
    from public.quotations q
    where q.quotation_id = p_quotation_id
      and q.is_deleted = false
    for update;

    if not found then
        raise exception
            'Quotation not found.';
    end if;

    if v_quotation.is_active = false then
        raise exception
            'Inactive quotation cannot be sent.';
    end if;


    -- ========================================================
    -- 3. WORKFLOW VALIDATION
    -- ========================================================

    if v_quotation.quotation_status <> 'Draft' then
        raise exception
            'Only a Draft quotation can be sent. Current status: %.',
            v_quotation.quotation_status;
    end if;

    if v_quotation.revision_no <> 0 then
        raise exception
            'This is not a base quotation. Use the quotation revision send workflow.';
    end if;

    if v_quotation.current_revision_id is not null then
        raise exception
            'This quotation already has a current revision. Use the quotation revision workflow.';
    end if;

    if v_quotation.accepted_revision_id is not null then
        raise exception
            'Quotation already has an accepted revision pointer.';
    end if;

    if v_quotation.accepted_at is not null
       or v_quotation.accepted_by is not null then
        raise exception
            'Quotation already contains acceptance information.';
    end if;

    if v_quotation.project_site_id is null then
        raise exception
            'Project Site is required before sending the quotation.';
    end if;


    -- ========================================================
    -- 4. VALIDATE PROJECT / SITE / CUSTOMER
    -- ========================================================

    select
        ps.project_id,
        ps.site_status,
        pr.customer_id
    into
        v_project_id,
        v_site_status,
        v_project_customer_id
    from public.project_sites ps
    join public.projects pr
      on pr.project_id = ps.project_id
    where ps.site_id = v_quotation.project_site_id
      and ps.is_deleted = false
      and ps.is_active = true
      and pr.is_deleted = false
      and pr.is_active = true
    for update of ps, pr;

    if not found then
        raise exception
            'Project Site or its Project does not exist, is inactive, or is deleted.';
    end if;

    if v_project_customer_id <> v_quotation.customer_id then
        raise exception
            'Quotation Customer does not match the Project Customer.';
    end if;

    if v_site_status <> 'Quotation' then
        raise exception
            'A base quotation can only be sent while the Project Site status is Quotation. Current status: %.',
            v_site_status;
    end if;


    -- ========================================================
    -- 5. VALIDATE QUOTATION DATES
    -- ========================================================

    if v_quotation.issue_date is null then
        raise exception
            'Issue Date is required before sending the quotation.';
    end if;

    if v_quotation.valid_until is not null
       and v_quotation.valid_until < v_quotation.issue_date then
        raise exception
            'Valid Until cannot be earlier than Issue Date.';
    end if;


    -- ========================================================
    -- 6. VALIDATE ACTIVE QUOTATION LINES
    -- ========================================================

    select count(*)
    into v_line_count
    from public.quotation_lines ql
    where ql.quotation_id = p_quotation_id
      and ql.is_deleted = false;

    if v_line_count = 0 then
        raise exception
            'At least one active quotation line is required before sending.';
    end if;

    if exists (
        select 1
        from public.quotation_lines ql
        where ql.quotation_id = p_quotation_id
          and ql.is_deleted = false
          and (
              ql.description is null
              or btrim(ql.description) = ''
              or ql.quantity <= 0
              or ql.sales_uom_code is null
              or ql.base_uom_code is null
              or ql.conversion_factor <= 0
              or ql.base_quantity <= 0
          )
    ) then
        raise exception
            'Quotation contains an incomplete or invalid active line.';
    end if;


    -- ========================================================
    -- 7. SEND QUOTATION
    -- ========================================================

    update public.quotations
    set
        quotation_status = 'Sent',
        sent_at = now(),
        sent_by = v_user_id,
        updated_by = v_user_id
    where quotation_id = p_quotation_id;


    -- ========================================================
    -- 8. RETURN RESULT
    -- ========================================================

    return jsonb_build_object(
        'quotation_id',
        v_quotation.quotation_id,
        'quotation_no',
        v_quotation.quotation_no,
        'quotation_status',
        'Sent',
        'sent_at',
        (
            select q.sent_at
            from public.quotations q
            where q.quotation_id = p_quotation_id
        ),
        'sent_by',
        v_user_id,
        'line_count',
        v_line_count
    );
end;
$$;


ALTER FUNCTION "public"."send_quotation_atomic"("p_quotation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."send_quotation_revision_atomic"("p_revision_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    v_user_id uuid;

    v_revision public.quotation_revisions%rowtype;
    v_quotation public.quotations%rowtype;

    v_project_id uuid;
    v_project_customer_id uuid;
    v_site_status text;

    v_line_count integer;
begin
    -- ========================================================
    -- 1. AUTHENTICATION AND PERMISSION
    -- ========================================================

    v_user_id := auth.uid();

    if v_user_id is null then
        raise exception
            'Authentication is required.';
    end if;

    if not public.has_permission(
        'quotations.send_revision'
    ) then
        raise exception
            'Permission denied: quotations.send_revision is required.';
    end if;


    -- ========================================================
    -- 2. LOCK AND LOAD REVISION
    -- ========================================================

    select qr.*
    into v_revision
    from public.quotation_revisions qr
    where qr.revision_id = p_revision_id
    for update;

    if not found then
        raise exception
            'Quotation revision not found.';
    end if;


    -- ========================================================
    -- 3. LOCK AND LOAD PARENT QUOTATION
    -- ========================================================

    select q.*
    into v_quotation
    from public.quotations q
    where q.quotation_id = v_revision.quotation_id
      and q.is_deleted = false
    for update;

    if not found then
        raise exception
            'Parent quotation does not exist or has been deleted.';
    end if;

    if not v_quotation.is_active then
        raise exception
            'Inactive quotation revision cannot be sent.';
    end if;


    -- ========================================================
    -- 4. WORKFLOW VALIDATION
    -- ========================================================

    if v_revision.revision_status <> 'Draft' then
        raise exception
            'Only a Draft revision can be sent. Current revision status: %.',
            v_revision.revision_status;
    end if;

    if v_quotation.quotation_status not in (
        'Sent',
        'Revised'
    ) then
        raise exception
            'Revision can only be sent while the parent quotation is Sent or Revised. Current quotation status: %.',
            v_quotation.quotation_status;
    end if;

    if v_quotation.current_revision_id is null then
        raise exception
            'Parent quotation does not have a current revision.';
    end if;

    if v_quotation.current_revision_id <>
       v_revision.revision_id then
        raise exception
            'Only the current quotation revision can be sent.';
    end if;

    if v_quotation.revision_no <>
       v_revision.revision_no then
        raise exception
            'Quotation revision number does not match the current revision.';
    end if;

    if v_quotation.accepted_revision_id is not null
       or v_quotation.accepted_at is not null
       or v_quotation.accepted_by is not null then
        raise exception
            'Accepted quotation cannot send another revision. Use a Variation for contract changes.';
    end if;


    -- ========================================================
    -- 5. VALIDATE REVISION SNAPSHOT
    -- ========================================================

    if v_revision.customer_id <>
       v_quotation.customer_id then
        raise exception
            'Revision Customer does not match the parent quotation.';
    end if;

    if v_revision.project_site_id is distinct from
       v_quotation.project_site_id then
        raise exception
            'Revision Project Site does not match the parent quotation.';
    end if;

    if v_revision.project_site_id is null then
        raise exception
            'Project Site is required before sending a revision.';
    end if;


    -- ========================================================
    -- 6. VALIDATE PROJECT / SITE / CUSTOMER
    -- ========================================================

    select
        ps.project_id,
        ps.site_status,
        pr.customer_id
    into
        v_project_id,
        v_site_status,
        v_project_customer_id
    from public.project_sites ps
    join public.projects pr
      on pr.project_id = ps.project_id
    where ps.site_id = v_revision.project_site_id
      and ps.is_deleted = false
      and ps.is_active = true
      and pr.is_deleted = false
      and pr.is_active = true
    for update of ps, pr;

    if not found then
        raise exception
            'Project Site or its Project does not exist, is inactive, or is deleted.';
    end if;

    if v_project_customer_id <>
       v_revision.customer_id then
        raise exception
            'Revision Customer does not match the Project Customer.';
    end if;

    if v_site_status <> 'Quotation' then
        raise exception
            'A quotation revision can only be sent while the Project Site status is Quotation. Current status: %.',
            v_site_status;
    end if;


    -- ========================================================
    -- 7. VALIDATE DATES
    -- ========================================================

    if v_revision.issue_date is null then
        raise exception
            'Issue Date is required before sending the revision.';
    end if;

    if v_revision.valid_until is not null
       and v_revision.valid_until <
           v_revision.issue_date then
        raise exception
            'Valid Until cannot be earlier than Issue Date.';
    end if;


    -- ========================================================
    -- 8. VALIDATE ACTIVE REVISION LINES
    -- ========================================================

    select count(*)
    into v_line_count
    from public.quotation_revision_lines qrl
    where qrl.revision_id = p_revision_id
      and qrl.is_deleted = false;

    if v_line_count = 0 then
        raise exception
            'At least one active revision line is required before sending.';
    end if;

    if exists (
        select 1
        from public.quotation_revision_lines qrl
        where qrl.revision_id = p_revision_id
          and qrl.is_deleted = false
          and (
              qrl.description is null
              or btrim(qrl.description) = ''
              or qrl.quantity <= 0
              or qrl.sales_uom_code is null
              or qrl.base_uom_code is null
              or qrl.conversion_factor is null
              or qrl.conversion_factor <= 0
              or qrl.base_quantity is null
              or qrl.base_quantity <= 0
          )
    ) then
        raise exception
            'Revision contains an incomplete or invalid active line.';
    end if;


    -- ========================================================
    -- 9. SEND REVISION
    -- ========================================================

    update public.quotation_revisions
    set
        revision_status = 'Sent',
        issued_at = now(),
        issued_by = v_user_id,
        updated_by = v_user_id
    where revision_id = p_revision_id;


    -- ========================================================
    -- 10. UPDATE PARENT QUOTATION
    -- ========================================================

    update public.quotations
    set
        quotation_status = 'Revised',
        revision_no = v_revision.revision_no,
        current_revision_id = v_revision.revision_id,
        updated_by = v_user_id
    where quotation_id = v_revision.quotation_id;


    -- Validate deferred revision pointer before returning.

    set constraints all immediate;


    -- ========================================================
    -- 11. RETURN RESULT
    -- ========================================================

    return jsonb_build_object(
        'quotation_id',
            v_quotation.quotation_id,

        'quotation_no',
            v_quotation.quotation_no,

        'quotation_status',
            'Revised',

        'revision_id',
            v_revision.revision_id,

        'revision_no',
            v_revision.revision_no,

        'revision_status',
            'Sent',

        'issued_at',
            (
                select qr.issued_at
                from public.quotation_revisions qr
                where qr.revision_id = p_revision_id
            ),

        'issued_by',
            v_user_id,

        'line_count',
            v_line_count
    );
end;
$$;


ALTER FUNCTION "public"."send_quotation_revision_atomic"("p_revision_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."send_variation_atomic"("p_variation_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    v_user_id uuid := auth.uid();
    v_variation public.variations%rowtype;
    v_line_count integer;
begin
    if v_user_id is null then
        raise exception 'Authentication is required.';
    end if;

    if not public.has_permission('variations.send') then
        raise exception 'Permission denied: variations.send is required.';
    end if;

    select *
    into v_variation
    from public.variations
    where variation_id = p_variation_id
      and is_active = true
      and is_deleted = false
    for update;

    if not found then
        raise exception 'Variation was not found, is inactive, or is archived.';
    end if;

    if v_variation.variation_status <> 'Draft' then
        raise exception 'Only a Draft Variation can be sent. Current status: %.', v_variation.variation_status;
    end if;

    if v_variation.issue_date is null then
        raise exception 'Issue Date is required before sending.';
    end if;

    if v_variation.valid_until is not null
       and v_variation.valid_until < v_variation.issue_date then
        raise exception 'Valid Until cannot be earlier than Issue Date.';
    end if;

    select count(*)
    into v_line_count
    from public.variation_lines
    where variation_id = p_variation_id
      and is_deleted = false;

    if v_line_count = 0 then
        raise exception 'At least one active Variation line is required before sending.';
    end if;

    update public.variations
    set
        variation_status = 'Sent',
        sent_at = now(),
        sent_by = v_user_id,
        rejected_at = null,
        rejected_by = null,
        rejection_reason = null,
        cancelled_at = null,
        cancelled_by = null,
        cancellation_reason = null,
        updated_by = v_user_id
    where variation_id = p_variation_id
      and variation_status = 'Draft';

    if not found then
        raise exception 'Variation could not be sent because its workflow state changed.';
    end if;

    return jsonb_build_object(
        'variation_id', p_variation_id,
        'variation_no', v_variation.variation_no,
        'variation_status', 'Sent',
        'line_count', v_line_count
    );
end;
$$;


ALTER FUNCTION "public"."send_variation_atomic"("p_variation_id" "uuid") OWNER TO "postgres";


