CREATE OR REPLACE FUNCTION "public"."set_product_code_category_variant_code"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  family_code_value text;
  family_variant_meaning text;
begin
  select family_code, variant_meaning
  into family_code_value, family_variant_meaning
  from public.product_code_families
  where product_code_family_id = new.product_code_family_id
    and is_deleted = false;

  if family_code_value is null then
    raise exception 'Selected Product Code Family does not exist.';
  end if;

  new.full_category_code := family_code_value || new.variant_digit;

  if new.thickness_mm is not null and family_variant_meaning <> 'thickness' then
    raise exception 'Thickness is allowed only for a Family using thickness variants.';
  end if;

  return new;
end;
$$;


