CREATE OR REPLACE FUNCTION "public"."set_stock_request_item_routing_defaults"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    v_product_type text;
begin
    select p.product_type
      into v_product_type
      from public.products p
     where p.product_id = new.product_id
       and p.is_deleted = false;

    if v_product_type is null then
        raise exception 'Product % is missing, inactive for this operation, or deleted.', new.product_id;
    end if;

    if new.request_line_type is null then
        new.request_line_type := case
            when v_product_type in ('Material', 'Consumable', 'Tool', 'Equipment')
                then v_product_type
            else null
        end;
    end if;

    if new.request_line_type is null then
        raise exception 'Product type % cannot be used in a Stock Request.', v_product_type;
    end if;

    if new.fulfilment_method is null then
        new.fulfilment_method := case
            when new.request_line_type in ('Tool', 'Equipment') then 'Loan'
            else 'Issue'
        end;
    end if;

    if new.request_line_type in ('Tool', 'Equipment')
       and new.fulfilment_method = 'Issue' then
        raise exception 'Tool and Equipment request lines must use Loan, Purchase, or DirectDelivery fulfilment.';
    end if;

    if new.request_line_type in ('Material', 'Consumable')
       and new.fulfilment_method = 'Loan' then
        raise exception 'Material and Consumable request lines cannot use Loan fulfilment.';
    end if;

    return new;
end;
$$;


ALTER FUNCTION "public"."set_stock_request_item_routing_defaults"() OWNER TO "postgres";


