CREATE OR REPLACE FUNCTION "public"."set_user_notification_override"("p_auth_user_id" "uuid", "p_event_code" "text", "p_override_value" "text", "p_reason" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
    if auth.uid() is null then
        raise exception 'Authentication is required.';
    end if;

    if not public.has_permission('telegram_notifications.manage') then
        raise exception
            'Permission denied: telegram_notifications.manage';
    end if;

    if p_override_value is null
       or p_override_value not in ('Default', 'Allow', 'Deny') then
        raise exception
            'Override value must be Default, Allow, or Deny.';
    end if;

    if not exists (
        select 1
        from public.app_users app_user
        where app_user.auth_user_id = p_auth_user_id
    ) then
        raise exception 'App user not found.';
    end if;

    if not exists (
        select 1
        from public.notification_event_types event_type
        where event_type.event_code = p_event_code
          and event_type.event_code in (
              'daily_report_submitted',
              'site_goods_receiving_completed',
              'site_goods_receiving_partial',
              'site_goods_receiving_issue'
          )
    ) then
        raise exception
            'Unsupported Phase 1 notification event.';
    end if;

    if p_override_value = 'Default' then
        delete from public.notification_user_event_overrides
        where auth_user_id = p_auth_user_id
          and event_code = p_event_code;

        return;
    end if;

    insert into public.notification_user_event_overrides (
        auth_user_id,
        event_code,
        override_value,
        override_reason,
        created_by,
        updated_by
    )
    values (
        p_auth_user_id,
        p_event_code,
        p_override_value,
        nullif(trim(p_reason), ''),
        auth.uid(),
        auth.uid()
    )
    on conflict (auth_user_id, event_code) do update
    set
        override_value = excluded.override_value,
        override_reason = excluded.override_reason,
        updated_at = now(),
        updated_by = auth.uid();
end;
$$;


ALTER FUNCTION "public"."set_user_notification_override"("p_auth_user_id" "uuid", "p_event_code" "text", "p_override_value" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_user_telegram_channel_enabled"("p_auth_user_id" "uuid", "p_is_enabled" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
    if auth.uid() is null then
        raise exception 'Authentication is required.';
    end if;

    if not public.has_permission('telegram_notifications.manage') then
        raise exception
            'Permission denied: telegram_notifications.manage';
    end if;

    update public.notification_user_channels
    set
        is_enabled = p_is_enabled,
        connection_status = case
            when p_is_enabled then 'Connected'
            else 'Disabled'
        end,
        connected_at = case
            when p_is_enabled then coalesce(connected_at, now())
            else connected_at
        end,
        updated_at = now(),
        updated_by = auth.uid()
    where auth_user_id = p_auth_user_id
      and channel_type = 'Telegram'
      and is_deleted = false;

    if not found then
        raise exception
            'Telegram channel is not configured for this user.';
    end if;
end;
$$;


ALTER FUNCTION "public"."set_user_telegram_channel_enabled"("p_auth_user_id" "uuid", "p_is_enabled" boolean) OWNER TO "postgres";


