CREATE OR REPLACE FUNCTION "public"."soft_delete_customer_payment_atomic"("p_payment_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    v_payment public.customer_payments%rowtype;
begin
    perform public.assert_invoice_permission('payments.soft_delete');

    select *
    into v_payment
    from public.customer_payments
    where customer_payment_id = p_payment_id
      and is_deleted = false
    for update;

    if not found then
        raise exception 'Customer Payment not found.';
    end if;

    if exists (
        select 1
        from public.customer_payment_allocations a
        where a.customer_payment_id = p_payment_id
          and a.is_deleted = false
          and a.reversed_at is null
    ) then
        raise exception 'Customer Payment with active allocations cannot be archived.';
    end if;

    update public.customer_payments
    set
        is_deleted = true,
        deleted_at = now(),
        updated_by = auth.uid()
    where customer_payment_id = p_payment_id;

    update public.customer_payment_allocations
    set
        is_deleted = true,
        deleted_at = now(),
        updated_by = auth.uid()
    where customer_payment_id = p_payment_id
      and is_deleted = false;

    return p_payment_id;
end;
$$;


ALTER FUNCTION "public"."soft_delete_customer_payment_atomic"("p_payment_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."soft_delete_invoice_atomic"("p_invoice_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    v_status text;
begin
    perform public.assert_invoice_permission('invoices.soft_delete');

    select document_status
    into v_status
    from public.customer_invoices
    where customer_invoice_id = p_invoice_id
      and is_deleted = false
    for update;

    if not found then
        raise exception 'Invoice not found.';
    end if;

    if v_status not in ('Draft', 'Cancelled') then
        raise exception 'Only Draft or Cancelled Invoices can be archived.';
    end if;

    update public.customer_invoices
    set
        is_deleted = true,
        deleted_at = now(),
        updated_by = auth.uid()
    where customer_invoice_id = p_invoice_id;

    update public.customer_invoice_items
    set
        is_deleted = true,
        deleted_at = now(),
        updated_by = auth.uid()
    where customer_invoice_id = p_invoice_id
      and is_deleted = false;

    update public.invoice_sources
    set
        is_deleted = true,
        deleted_at = now(),
        updated_by = auth.uid()
    where customer_invoice_id = p_invoice_id
      and is_deleted = false;

    return p_invoice_id;
end;
$$;


ALTER FUNCTION "public"."soft_delete_invoice_atomic"("p_invoice_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."soft_delete_quotation_atomic"("p_quotation_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    v_user_id uuid;
    v_deleted_at timestamptz;

    v_quotation_no text;
    v_quotation_status text;
    v_project_site_id uuid;

    v_current_revision_id uuid;
    v_accepted_revision_id uuid;
    v_accepted_at timestamptz;
    v_accepted_by uuid;

    v_project_id uuid;
    v_project_status text;
    v_site_status text;

    v_deleted_line_count integer := 0;
    v_project_restored boolean := false;
begin
    -- ========================================================================
    -- 1. AUTHENTICATION AND PERMISSION
    -- ========================================================================

    v_user_id := auth.uid();

    if v_user_id is null then
        raise exception
            'Authentication is required.';
    end if;

    if not public.has_permission(
        'quotations.soft_delete'
    ) then
        raise exception
            'Permission denied: quotations.soft_delete is required.';
    end if;


    -- ========================================================================
    -- 2. INPUT VALIDATION
    -- ========================================================================

    if p_quotation_id is null then
        raise exception
            'Quotation ID is required.';
    end if;

    v_deleted_at := now();


    -- ========================================================================
    -- 3. LOCK QUOTATION
    -- ========================================================================

    select
        q.quotation_no,
        q.quotation_status,
        q.project_site_id,
        q.current_revision_id,
        q.accepted_revision_id,
        q.accepted_at,
        q.accepted_by

    into
        v_quotation_no,
        v_quotation_status,
        v_project_site_id,
        v_current_revision_id,
        v_accepted_revision_id,
        v_accepted_at,
        v_accepted_by

    from public.quotations q

    where q.quotation_id =
          p_quotation_id
      and q.is_active = true
      and q.is_deleted = false

    for update;

    if not found then
        raise exception
            'Quotation was not found, is inactive, or is already archived.';
    end if;


    -- ========================================================================
    -- 4. WORKFLOW VALIDATION
    -- ========================================================================

    if v_quotation_status <> 'Draft' then
        raise exception
            'Only a Draft quotation can be archived. Current status: %.',
            v_quotation_status;
    end if;

    if v_current_revision_id is not null then
        raise exception
            'Draft quotation cannot be archived while current_revision_id is populated.';
    end if;

    if v_accepted_revision_id is not null
       or v_accepted_at is not null
       or v_accepted_by is not null then
        raise exception
            'Accepted quotation cannot be archived.';
    end if;

    if exists (
        select 1
        from public.quotation_revisions qr
        where qr.quotation_id =
              p_quotation_id
    ) then
        raise exception
            'Quotation cannot be archived because revision history exists.';
    end if;

    if exists (
        select 1
        from public.material_requirements mr
        where mr.quotation_id =
              p_quotation_id
          and mr.is_deleted = false
    ) then
        raise exception
            'Quotation cannot be archived because an active Material Requirement references it.';
    end if;


    -- ========================================================================
    -- 5. LOCK PROJECT/SITE HIERARCHY
    -- ========================================================================

    if v_project_site_id is null then
        raise exception
            'Draft quotation does not have a Project Site.';
    end if;

    select
        ps.project_id,
        ps.site_status,
        p.project_status

    into
        v_project_id,
        v_site_status,
        v_project_status

    from public.project_sites ps
    join public.projects p
      on p.project_id =
         ps.project_id

    where ps.site_id =
          v_project_site_id
      and ps.is_deleted = false
      and p.is_deleted = false

    for update of ps, p;

    if not found then
        raise exception
            'Project Site or Project was not found.';
    end if;

    if v_site_status <> 'Quotation' then
        raise exception
            'Draft quotation can only be archived while the Site status is Quotation. Current status: %.',
            v_site_status;
    end if;

    if v_project_status not in (
        'Draft',
        'Quoted'
    ) then
        raise exception
            'Draft quotation cannot be archived while the Project status is %. Expected Draft or Quoted.',
            v_project_status;
    end if;


    -- ========================================================================
    -- 6. LOCK AND SOFT-DELETE QUOTATION LINES
    -- ========================================================================

    perform 1
    from public.quotation_lines ql
    where ql.quotation_id =
          p_quotation_id
    for update;

    update public.quotation_lines
    set
        is_deleted =
            true,

        deleted_at =
            v_deleted_at,

        updated_at =
            v_deleted_at,

        updated_by =
            v_user_id

    where quotation_id =
          p_quotation_id
      and is_deleted = false;

    get diagnostics
        v_deleted_line_count = row_count;


    -- ========================================================================
    -- 7. SOFT-DELETE QUOTATION HEADER
    -- ========================================================================

    update public.quotations
    set
        is_active =
            false,

        is_deleted =
            true,

        deleted_at =
            v_deleted_at,

        updated_by =
            v_user_id

    where quotation_id =
          p_quotation_id
      and quotation_status =
          'Draft'
      and is_active = true
      and is_deleted = false
      and current_revision_id is null
      and accepted_revision_id is null
      and accepted_at is null
      and accepted_by is null;

    if not found then
        raise exception
            'Quotation could not be archived because its workflow state changed.';
    end if;


    -- ========================================================================
    -- 8. RESTORE PROJECT LIFECYCLE WHEN THIS WAS THE LAST QUOTATION
    --
    -- Existing Project price_book_id is retained because it is project
    -- configuration and may have been set independently of this quotation.
    -- ========================================================================

    if v_project_status = 'Quoted'
       and not exists (
            select 1
            from public.quotations q
            join public.project_sites ps
              on ps.site_id =
                 q.project_site_id
            where ps.project_id =
                  v_project_id
              and q.is_deleted = false
       ) then

        update public.projects
        set
            project_status =
                'Draft',

            updated_at =
                v_deleted_at,

            updated_by =
                v_user_id

        where project_id =
              v_project_id
          and project_status =
              'Quoted'
          and is_deleted = false;

        v_project_restored := found;
    end if;


    -- ========================================================================
    -- 9. FINAL CONSISTENCY CHECK
    -- ========================================================================

    if not exists (
        select 1
        from public.quotations q
        where q.quotation_id =
              p_quotation_id
          and q.quotation_status =
              'Draft'
          and q.is_active = false
          and q.is_deleted = true
          and q.deleted_at =
              v_deleted_at
    ) then
        raise exception
            'Quotation archive consistency check failed.';
    end if;

    if exists (
        select 1
        from public.quotation_lines ql
        where ql.quotation_id =
              p_quotation_id
          and ql.is_deleted = false
    ) then
        raise exception
            'Quotation archive consistency check failed: active quotation lines remain.';
    end if;


    -- ========================================================================
    -- 10. RETURN RESULT
    -- ========================================================================

    return jsonb_build_object(
        'quotation_id',
            p_quotation_id,

        'quotation_no',
            v_quotation_no,

        'quotation_status',
            'Draft',

        'is_active',
            false,

        'is_deleted',
            true,

        'deleted_at',
            v_deleted_at,

        'deleted_by',
            v_user_id,

        'deleted_line_count',
            v_deleted_line_count,

        'project_id',
            v_project_id,

        'project_status_restored_to_draft',
            v_project_restored
    );
end;
$$;


ALTER FUNCTION "public"."soft_delete_quotation_atomic"("p_quotation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."soft_delete_quotation_revision_atomic"("p_revision_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    v_user_id uuid;
    v_deleted_at timestamptz;

    v_quotation_id uuid;
    v_revision_no integer;
    v_revision_status text;

    v_quotation_no text;
    v_quotation_status text;
    v_current_revision_id uuid;
    v_accepted_revision_id uuid;
    v_accepted_at timestamptz;
    v_accepted_by uuid;

    v_previous_sent_revision_id uuid;
    v_previous_sent_revision_no integer;

    v_restored_quotation_status text;
    v_deleted_line_count integer := 0;
begin
    -- ========================================================================
    -- 1. AUTHENTICATION AND PERMISSION
    -- ========================================================================

    v_user_id := auth.uid();

    if v_user_id is null then
        raise exception
            'Authentication is required.';
    end if;

    if not public.has_permission(
        'quotations.soft_delete'
    ) then
        raise exception
            'Permission denied: quotations.soft_delete is required.';
    end if;


    -- ========================================================================
    -- 2. INPUT VALIDATION
    -- ========================================================================

    if p_revision_id is null then
        raise exception
            'Quotation Revision ID is required.';
    end if;

    v_deleted_at := now();


    -- ========================================================================
    -- 3. LOCK REVISION
    -- ========================================================================

    select
        qr.quotation_id,
        qr.revision_no,
        qr.revision_status

    into
        v_quotation_id,
        v_revision_no,
        v_revision_status

    from public.quotation_revisions qr

    where qr.revision_id =
          p_revision_id
      and qr.is_active = true
      and qr.is_deleted = false

    for update;

    if not found then
        raise exception
            'Quotation revision was not found, is inactive, or is already archived.';
    end if;

    if v_revision_status <> 'Draft' then
        raise exception
            'Only a Draft quotation revision can be archived. Current status: %.',
            v_revision_status;
    end if;


    -- ========================================================================
    -- 4. LOCK PARENT QUOTATION
    -- ========================================================================

    select
        q.quotation_no,
        q.quotation_status,
        q.current_revision_id,
        q.accepted_revision_id,
        q.accepted_at,
        q.accepted_by

    into
        v_quotation_no,
        v_quotation_status,
        v_current_revision_id,
        v_accepted_revision_id,
        v_accepted_at,
        v_accepted_by

    from public.quotations q

    where q.quotation_id =
          v_quotation_id
      and q.is_active = true
      and q.is_deleted = false

    for update;

    if not found then
        raise exception
            'Parent quotation was not found, is inactive, or is archived.';
    end if;


    -- ========================================================================
    -- 5. VALIDATE WORKFLOW
    -- ========================================================================

    if v_current_revision_id is distinct from
       p_revision_id then
        raise exception
            'Only the current Draft quotation revision can be archived.';
    end if;

    if v_quotation_status not in (
        'Sent',
        'Revised'
    ) then
        raise exception
            'Parent quotation must be Sent or Revised. Current status: %.',
            v_quotation_status;
    end if;

    if v_accepted_revision_id is not null
       or v_accepted_at is not null
       or v_accepted_by is not null then
        raise exception
            'A revision belonging to an Accepted quotation cannot be archived.';
    end if;

    if exists (
        select 1
        from public.material_requirements mr
        where mr.accepted_revision_id =
              p_revision_id
          and mr.is_deleted = false
    ) then
        raise exception
            'Quotation revision cannot be archived because an active Material Requirement references it.';
    end if;


    -- ========================================================================
    -- 6. RESOLVE PREVIOUS ACTIVE SENT REVISION
    --
    -- The highest prior Sent revision is the commercial version that was
    -- current before this Draft revision was created.
    -- ========================================================================

    select
        qr.revision_id,
        qr.revision_no

    into
        v_previous_sent_revision_id,
        v_previous_sent_revision_no

    from public.quotation_revisions qr

    where qr.quotation_id =
          v_quotation_id
      and qr.revision_no <
          v_revision_no
      and qr.revision_status =
          'Sent'
      and qr.is_active = true
      and qr.is_deleted = false

    order by
        qr.revision_no desc

    limit 1

    for update;


    if v_quotation_status = 'Revised'
       and v_previous_sent_revision_id is null then
        raise exception
            'Revised parent quotation does not have a previous active Sent revision to restore.';
    end if;

    if v_previous_sent_revision_id is null then
        v_restored_quotation_status :=
            'Sent';
    else
        v_restored_quotation_status :=
            'Revised';
    end if;


    -- ========================================================================
    -- 7. RESTORE PARENT POINTER BEFORE ARCHIVING REVISION
    --
    -- This order is required by:
    -- trg_prevent_referenced_quotation_revision_archive
    -- ========================================================================

    update public.quotations
    set
        quotation_status =
            v_restored_quotation_status,

        current_revision_id =
            v_previous_sent_revision_id,

        updated_by =
            v_user_id

    where quotation_id =
          v_quotation_id
      and current_revision_id =
          p_revision_id
      and quotation_status in (
          'Sent',
          'Revised'
      )
      and accepted_revision_id is null
      and accepted_at is null
      and accepted_by is null
      and is_active = true
      and is_deleted = false;

    if not found then
        raise exception
            'Parent quotation could not be restored because its workflow state changed.';
    end if;


    -- ========================================================================
    -- 8. SOFT-DELETE REVISION LINES
    -- ========================================================================

    perform 1
    from public.quotation_revision_lines qrl
    where qrl.revision_id =
          p_revision_id
    for update;

    update public.quotation_revision_lines
    set
        is_deleted =
            true,

        deleted_at =
            v_deleted_at,

        updated_at =
            v_deleted_at,

        updated_by =
            v_user_id

    where revision_id =
          p_revision_id
      and is_deleted = false;

    get diagnostics
        v_deleted_line_count = row_count;


    -- ========================================================================
    -- 9. SOFT-DELETE REVISION HEADER
    --
    -- revision_status intentionally remains Draft to preserve its historical
    -- workflow state and satisfy quotation_revisions_deleted_status_check.
    -- ========================================================================

    update public.quotation_revisions
    set
        is_active =
            false,

        is_deleted =
            true,

        deleted_at =
            v_deleted_at,

        updated_by =
            v_user_id

    where revision_id =
          p_revision_id
      and revision_status =
          'Draft'
      and is_active = true
      and is_deleted = false;

    if not found then
        raise exception
            'Quotation revision could not be archived because its workflow state changed.';
    end if;


    -- Validate deferred parent revision pointer now.

    set constraints all immediate;


    -- ========================================================================
    -- 10. FINAL CONSISTENCY CHECK
    -- ========================================================================

    if not exists (
        select 1
        from public.quotation_revisions qr
        where qr.revision_id =
              p_revision_id
          and qr.revision_status =
              'Draft'
          and qr.is_active = false
          and qr.is_deleted = true
          and qr.deleted_at =
              v_deleted_at
    ) then
        raise exception
            'Quotation revision archive consistency check failed.';
    end if;

    if exists (
        select 1
        from public.quotation_revision_lines qrl
        where qrl.revision_id =
              p_revision_id
          and qrl.is_deleted = false
    ) then
        raise exception
            'Quotation revision archive consistency check failed: active lines remain.';
    end if;

    if not exists (
        select 1
        from public.quotations q
        where q.quotation_id =
              v_quotation_id
          and q.quotation_status =
              v_restored_quotation_status
          and q.current_revision_id is not distinct from
              v_previous_sent_revision_id
          and q.accepted_revision_id is null
          and q.is_active = true
          and q.is_deleted = false
    ) then
        raise exception
            'Parent quotation restoration consistency check failed.';
    end if;


    -- ========================================================================
    -- 11. RETURN RESULT
    -- ========================================================================

    return jsonb_build_object(
        'quotation_id',
            v_quotation_id,

        'quotation_no',
            v_quotation_no,

        'quotation_status',
            v_restored_quotation_status,

        'revision_id',
            p_revision_id,

        'revision_no',
            v_revision_no,

        'revision_status',
            'Draft',

        'is_active',
            false,

        'is_deleted',
            true,

        'deleted_at',
            v_deleted_at,

        'deleted_by',
            v_user_id,

        'deleted_line_count',
            v_deleted_line_count,

        'restored_current_revision_id',
            v_previous_sent_revision_id,

        'restored_current_revision_no',
            v_previous_sent_revision_no
    );
end;
$$;


ALTER FUNCTION "public"."soft_delete_quotation_revision_atomic"("p_revision_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_purchase_order_atomic"("p_purchase_order_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
    v_auth_user_id uuid := auth.uid();
    v_po public.purchase_orders%rowtype;
    v_line_count integer;
begin
    if v_auth_user_id is null then
        raise exception 'Authentication is required.';
    end if;

    if not public.has_permission('purchase_orders.submit') then
        raise exception 'You do not have permission to submit purchase orders.';
    end if;

    select *
    into v_po
    from public.purchase_orders
    where purchase_order_id = p_purchase_order_id
      and is_deleted = false
    for update;

    if not found then
        raise exception 'Purchase Order was not found.';
    end if;

    if v_po.order_status <> 'Draft' then
        raise exception 'Only a Draft purchase order can be submitted.';
    end if;

    select count(*)
    into v_line_count
    from public.purchase_order_lines
    where purchase_order_id = p_purchase_order_id
      and is_deleted = false;

    if v_line_count = 0 then
        raise exception 'Purchase Order must contain at least one active line.';
    end if;

    update public.purchase_orders
    set
        order_status = 'Submitted',
        submitted_at = now(),
        submitted_by = v_auth_user_id,
        updated_at = now(),
        updated_by = v_auth_user_id
    where purchase_order_id = p_purchase_order_id;

    return jsonb_build_object(
        'purchase_order_id', p_purchase_order_id,
        'purchase_order_no', v_po.purchase_order_no,
        'order_status', 'Submitted'
    );
end;
$$;


ALTER FUNCTION "public"."submit_purchase_order_atomic"("p_purchase_order_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_tool_loan_atomic"("p_tool_loan_id" "uuid", "p_notes" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
    v_loan public.tool_loans%rowtype;
begin
    if not public.has_permission('tool_loans.create') then
        raise exception 'Permission denied: tool_loans.create.';
    end if;

    select *
    into v_loan
    from public.tool_loans
    where tool_loan_id = p_tool_loan_id
      and is_deleted = false
    for update;

    if not found then
        raise exception 'Tool Loan was not found.';
    end if;

    if v_loan.loan_status <> 'Draft' then
        raise exception 'Only Draft Tool Loans can be submitted.';
    end if;

    if not exists (
        select 1
        from public.tool_loan_items
        where tool_loan_id = p_tool_loan_id
          and is_deleted = false
    ) then
        raise exception 'Tool Loan has no active items.';
    end if;

    update public.tool_loan_items
    set
        item_status = 'Approved',
        updated_at = now(),
        updated_by = auth.uid()
    where tool_loan_id = p_tool_loan_id
      and is_deleted = false;

    update public.tool_loans
    set
        loan_status = 'Submitted',
        notes = coalesce(nullif(btrim(p_notes), ''), notes),
        updated_at = now(),
        updated_by = auth.uid()
    where tool_loan_id = p_tool_loan_id;

    return p_tool_loan_id;
end;
$$;


ALTER FUNCTION "public"."submit_tool_loan_atomic"("p_tool_loan_id" "uuid", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."substitute_material_requirement_line_product"("p_material_requirement_line_id" "uuid", "p_product_id" "uuid", "p_description" "text", "p_requirement_uom_code" "text", "p_requirement_quantity" numeric, "p_base_uom_code" "text", "p_conversion_factor_to_base" numeric, "p_allow_fractional_quantity" boolean, "p_waste_percent" numeric, "p_adjustment_reason" "text", "p_preferred_supplier_id" "uuid" DEFAULT NULL::"uuid", "p_commercial_impact" "text" DEFAULT 'None'::"text", "p_variation_required" boolean DEFAULT false, "p_variation_status" "text" DEFAULT 'NotRequired'::"text", "p_variation_reference" "text" DEFAULT NULL::"text", "p_commercial_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_actor uuid;

    v_header public.material_requirements%ROWTYPE;
    v_before public.material_requirement_lines%ROWTYPE;
    v_after public.material_requirement_lines%ROWTYPE;

    v_adjustment_id uuid;
    v_next_adjustment_no integer;

    v_description text;
    v_adjustment_reason text;
    v_variation_reference text;
    v_commercial_notes text;

    v_base_quantity_change numeric;
    v_approval_required boolean;
    v_approval_status text;
BEGIN
    -- ================================================================
    -- Authentication and permission
    -- ================================================================

    v_actor := auth.uid();

    IF v_actor IS NULL THEN
        RAISE EXCEPTION
            'Authentication is required.';
    END IF;

    IF NOT public.has_permission(
        'material_requirements.adjust'
    ) THEN
        RAISE EXCEPTION
            'Permission denied: material_requirements.adjust is required.';
    END IF;


    -- ================================================================
    -- Normalize inputs
    -- ================================================================

    v_description :=
        NULLIF(
            btrim(p_description),
            ''
        );

    v_adjustment_reason :=
        NULLIF(
            btrim(p_adjustment_reason),
            ''
        );

    v_variation_reference :=
        NULLIF(
            btrim(p_variation_reference),
            ''
        );

    v_commercial_notes :=
        NULLIF(
            btrim(p_commercial_notes),
            ''
        );


    -- ================================================================
    -- Required input validation
    -- ================================================================

    IF p_material_requirement_line_id IS NULL THEN
        RAISE EXCEPTION
            'Material Requirement Line ID is required.';
    END IF;

    IF p_product_id IS NULL THEN
        RAISE EXCEPTION
            'Substitute Product ID is required.';
    END IF;

    IF v_description IS NULL THEN
        RAISE EXCEPTION
            'Substitute Product description is required.';
    END IF;

    IF v_adjustment_reason IS NULL THEN
        RAISE EXCEPTION
            'Adjustment reason is required.';
    END IF;

    IF NULLIF(
        btrim(p_requirement_uom_code),
        ''
    ) IS NULL THEN
        RAISE EXCEPTION
            'Requirement UOM is required.';
    END IF;

    IF NULLIF(
        btrim(p_base_uom_code),
        ''
    ) IS NULL THEN
        RAISE EXCEPTION
            'Base UOM is required.';
    END IF;

    IF p_requirement_quantity IS NULL
       OR p_requirement_quantity < 0 THEN
        RAISE EXCEPTION
            'Requirement quantity must be zero or greater.';
    END IF;

    IF p_conversion_factor_to_base IS NULL
       OR p_conversion_factor_to_base <= 0 THEN
        RAISE EXCEPTION
            'Conversion factor to Base UOM must be greater than zero.';
    END IF;

    IF p_waste_percent IS NULL
       OR p_waste_percent < 0 THEN
        RAISE EXCEPTION
            'Waste percent must be zero or greater.';
    END IF;


    -- ================================================================
    -- Commercial and Variation validation
    -- ================================================================

    IF p_commercial_impact NOT IN (
        'None',
        'Internal',
        'CustomerCharge',
        'CustomerCredit',
        'PendingReview'
    ) THEN
        RAISE EXCEPTION
            'Invalid commercial impact: %.',
            p_commercial_impact;
    END IF;

    IF p_variation_status NOT IN (
        'NotRequired',
        'Required',
        'Pending',
        'Approved',
        'Rejected',
        'Cancelled'
    ) THEN
        RAISE EXCEPTION
            'Invalid variation status: %.',
            p_variation_status;
    END IF;

    IF p_variation_required = false
       AND p_variation_status <> 'NotRequired' THEN
        RAISE EXCEPTION
            'Variation status must be NotRequired when variation_required is false.';
    END IF;

    IF p_variation_required = true
       AND p_variation_status = 'NotRequired' THEN
        RAISE EXCEPTION
            'Variation status cannot be NotRequired when variation_required is true.';
    END IF;

    IF p_commercial_impact IN (
        'CustomerCharge',
        'CustomerCredit'
    )
       AND p_variation_required = false THEN
        RAISE EXCEPTION
            'Customer Charge or Customer Credit requires a Variation.';
    END IF;


    -- ================================================================
    -- Validate Product, UOM and Supplier
    -- ================================================================

    IF NOT EXISTS (
        SELECT 1
        FROM public.products product_row
        WHERE product_row.product_id = p_product_id
    ) THEN
        RAISE EXCEPTION
            'Substitute Product was not found.';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM public.units_of_measure uom
        WHERE uom.uom_code =
              btrim(p_requirement_uom_code)
    ) THEN
        RAISE EXCEPTION
            'Requirement UOM was not found: %.',
            p_requirement_uom_code;
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM public.units_of_measure uom
        WHERE uom.uom_code =
              btrim(p_base_uom_code)
    ) THEN
        RAISE EXCEPTION
            'Base UOM was not found: %.',
            p_base_uom_code;
    END IF;

    IF p_preferred_supplier_id IS NOT NULL
       AND NOT EXISTS (
           SELECT 1
           FROM public.suppliers supplier_row
           WHERE supplier_row.supplier_id =
                 p_preferred_supplier_id
       ) THEN
        RAISE EXCEPTION
            'Preferred Supplier was not found.';
    END IF;


    -- ================================================================
    -- Lock current line
    -- ================================================================

    SELECT line_row.*
    INTO v_before
    FROM public.material_requirement_lines line_row
    WHERE line_row.material_requirement_line_id =
              p_material_requirement_line_id
      AND line_row.is_active = true
      AND line_row.is_deleted = false
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'Active Material Requirement Line was not found.';
    END IF;


    -- ================================================================
    -- Lock parent Header
    -- ================================================================

    SELECT header_row.*
    INTO v_header
    FROM public.material_requirements header_row
    WHERE header_row.material_requirement_id =
              v_before.material_requirement_id
      AND header_row.is_active = true
      AND header_row.is_deleted = false
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'Active Material Requirement Header was not found.';
    END IF;

    IF v_header.requirement_status <> 'Draft' THEN
        RAISE EXCEPTION
            'Product substitution is currently allowed only while the Material Requirement is Draft. Current status: %.',
            v_header.requirement_status;
    END IF;

    IF v_before.line_status IN (
        'Excluded',
        'Cancelled',
        'Fulfilled'
    ) THEN
        RAISE EXCEPTION
            'Line status % cannot be substituted.',
            v_before.line_status;
    END IF;


    -- ================================================================
    -- Reject a no-op substitution
    -- ================================================================

    IF v_before.product_id
           IS NOT DISTINCT FROM p_product_id
       AND v_before.description
           IS NOT DISTINCT FROM v_description
       AND v_before.requirement_uom_code
           IS NOT DISTINCT FROM btrim(p_requirement_uom_code)
       AND v_before.requirement_quantity
           IS NOT DISTINCT FROM p_requirement_quantity
       AND v_before.base_uom_code
           IS NOT DISTINCT FROM btrim(p_base_uom_code)
       AND v_before.conversion_factor_to_base
           IS NOT DISTINCT FROM p_conversion_factor_to_base
       AND v_before.allow_fractional_quantity
           IS NOT DISTINCT FROM p_allow_fractional_quantity
       AND v_before.waste_percent
           IS NOT DISTINCT FROM p_waste_percent
       AND v_before.preferred_supplier_id
           IS NOT DISTINCT FROM p_preferred_supplier_id
       AND v_before.commercial_impact
           IS NOT DISTINCT FROM p_commercial_impact
       AND v_before.variation_required
           IS NOT DISTINCT FROM p_variation_required
       AND v_before.variation_status
           IS NOT DISTINCT FROM p_variation_status
       AND v_before.variation_reference
           IS NOT DISTINCT FROM v_variation_reference
       AND v_before.commercial_notes
           IS NOT DISTINCT FROM v_commercial_notes THEN
        RAISE EXCEPTION
            'No Product substitution change was detected.';
    END IF;


    -- ================================================================
    -- Update Operational Current State
    --
    -- Source snapshot columns are intentionally untouched.
    -- Existing quantity trigger recalculates Base Quantity and Waste.
    -- ================================================================

    UPDATE public.material_requirement_lines
    SET
        product_id =
            p_product_id,

        description =
            v_description,

        requirement_uom_code =
            btrim(p_requirement_uom_code),

        requirement_quantity =
            p_requirement_quantity,

        base_uom_code =
            btrim(p_base_uom_code),

        conversion_factor_to_base =
            p_conversion_factor_to_base,

        allow_fractional_quantity =
            p_allow_fractional_quantity,

        waste_percent =
            p_waste_percent,

        preferred_supplier_id =
            p_preferred_supplier_id,

        line_status =
            'Substituted',

        exclusion_reason =
            NULL,

        commercial_impact =
            p_commercial_impact,

        variation_required =
            p_variation_required,

        variation_status =
            p_variation_status,

        variation_reference =
            v_variation_reference,

        commercial_notes =
            v_commercial_notes,

        updated_at =
            now(),

        updated_by =
            v_actor

    WHERE material_requirement_line_id =
          p_material_requirement_line_id

    RETURNING *
    INTO v_after;


    -- ================================================================
    -- Allocate next Adjustment number
    -- ================================================================

    SELECT COALESCE(
        max(adjustment.adjustment_no),
        0
    ) + 1
    INTO v_next_adjustment_no
    FROM public.material_requirement_line_adjustments adjustment
    WHERE adjustment.material_requirement_line_id =
          p_material_requirement_line_id;


    v_base_quantity_change :=
        v_after.required_base_quantity
        - v_before.required_base_quantity;


    v_approval_required :=
        p_commercial_impact IN (
            'CustomerCharge',
            'CustomerCredit',
            'PendingReview'
        );

    v_approval_status :=
        CASE
            WHEN v_approval_required
                THEN 'Pending'
            ELSE 'NotRequired'
        END;


    -- ================================================================
    -- Insert append-only Ledger event
    -- ================================================================

    INSERT INTO public.material_requirement_line_adjustments (
        material_requirement_line_id,
        adjustment_no,
        adjustment_type,
        adjustment_reason,

        before_snapshot,
        after_snapshot,

        base_quantity_change,

        commercial_impact,
        variation_required,

        approval_required,
        approval_status,

        created_by
    )
    VALUES (
        p_material_requirement_line_id,
        v_next_adjustment_no,
        'SubstituteProduct',
        v_adjustment_reason,

        to_jsonb(v_before),
        to_jsonb(v_after),

        v_base_quantity_change,

        v_after.commercial_impact,
        v_after.variation_required,

        v_approval_required,
        v_approval_status,

        v_actor
    )
    RETURNING material_requirement_line_adjustment_id
    INTO v_adjustment_id;


    -- ================================================================
    -- Update Header audit information
    -- ================================================================

    UPDATE public.material_requirements
    SET
        updated_at = now(),
        updated_by = v_actor
    WHERE material_requirement_id =
          v_before.material_requirement_id;


    -- ================================================================
    -- Return result
    -- ================================================================

    RETURN jsonb_build_object(
        'material_requirement_id',
            v_before.material_requirement_id,

        'material_requirement_line_id',
            p_material_requirement_line_id,

        'adjustment_id',
            v_adjustment_id,

        'adjustment_no',
            v_next_adjustment_no,

        'adjustment_type',
            'SubstituteProduct',

        'previous_product_id',
            v_before.product_id,

        'new_product_id',
            v_after.product_id,

        'previous_description',
            v_before.description,

        'new_description',
            v_after.description,

        'previous_line_status',
            v_before.line_status,

        'new_line_status',
            v_after.line_status,

        'previous_required_base_quantity',
            v_before.required_base_quantity,

        'new_required_base_quantity',
            v_after.required_base_quantity,

        'base_quantity_change',
            v_base_quantity_change,

        'line',
            to_jsonb(v_after)
    );
END;
$$;


