CREATE OR REPLACE FUNCTION "public"."suspend_app_user_atomic"("p_auth_user_id" "uuid", "p_reason" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_actor_id uuid;
    v_app_user_id uuid;
BEGIN
    v_actor_id := auth.uid();

    IF v_actor_id IS NULL THEN
        RAISE EXCEPTION 'Authentication required.';
    END IF;

    IF NOT public.has_permission('users.manage_accounts')
       AND NOT public.can_manage_permissions()
    THEN
        RAISE EXCEPTION
            'Permission denied: users.manage_accounts';
    END IF;

    IF p_auth_user_id = v_actor_id THEN
        RAISE EXCEPTION
            'You cannot suspend your own account.';
    END IF;

    IF NULLIF(btrim(p_reason), '') IS NULL THEN
        RAISE EXCEPTION
            'Suspension reason is required.';
    END IF;

    SELECT au.app_user_id
    INTO v_app_user_id
    FROM public.app_users au
    WHERE au.auth_user_id = p_auth_user_id
    FOR UPDATE;

    IF v_app_user_id IS NULL THEN
        RAISE EXCEPTION
            'Application user was not found.';
    END IF;

    UPDATE public.app_user_roles
    SET
        is_active = false,
        ended_at = now(),
        ended_by = v_actor_id
    WHERE auth_user_id = p_auth_user_id
      AND is_active = true;

    UPDATE public.app_users
    SET
        account_status = 'Suspended',

        suspended_at = now(),
        suspended_by = v_actor_id,
        suspension_reason = btrim(p_reason),

        rejected_at = NULL,
        rejected_by = NULL,
        rejection_reason = NULL,

        updated_by = v_actor_id
    WHERE app_user_id = v_app_user_id;

    RETURN v_app_user_id;
END;
$$;


ALTER FUNCTION "public"."suspend_app_user_atomic"("p_auth_user_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_auth_user_to_app_user"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
    v_display_name text;
    v_phone text;
BEGIN
    v_display_name :=
        NULLIF(
            btrim(
                COALESCE(
                    NEW.raw_user_meta_data ->> 'display_name',
                    NEW.raw_user_meta_data ->> 'full_name',
                    ''
                )
            ),
            ''
        );

    v_phone :=
        NULLIF(
            btrim(
                COALESCE(
                    NEW.raw_user_meta_data ->> 'phone',
                    NEW.phone,
                    ''
                )
            ),
            ''
        );

    UPDATE public.app_users
    SET
        email = COALESCE(NEW.email, email),
        display_name = COALESCE(display_name, v_display_name),
        phone = COALESCE(phone, v_phone),
        updated_at = now()
    WHERE auth_user_id = NEW.id;

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."sync_auth_user_to_app_user"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_customer_invoice_statuses"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
    -- --------------------------------------------------------
    -- Legacy invoice_status
    --
    -- รักษาความเข้ากันได้กับ Views เดิม:
    -- Draft / Approved    -> Draft
    -- Issued + Unpaid     -> Issued หรือ Overdue
    -- Partially Paid      -> Partially Paid
    -- Paid / Overpaid     -> Paid
    -- Voided / Cancelled  -> Cancelled
    -- --------------------------------------------------------

    if new.document_status in (
        'Cancelled',
        'Voided'
    ) then
        new.invoice_status := 'Cancelled';

    elsif new.document_status in (
        'Draft',
        'Approved'
    ) then
        new.invoice_status := 'Draft';

    elsif new.payment_status in (
        'Paid',
        'Overpaid'
    ) then
        new.invoice_status := 'Paid';

    elsif new.payment_status = 'Partially Paid' then
        new.invoice_status := 'Partially Paid';

    elsif new.document_status = 'Issued'
      and new.payment_status = 'Unpaid'
      and new.due_date < current_date then
        new.invoice_status := 'Overdue';

    else
        new.invoice_status := 'Issued';
    end if;


    -- --------------------------------------------------------
    -- Due status
    --
    -- Invoice จะเริ่มมีสถานะกำหนดชำระหลัง Issued เท่านั้น
    -- --------------------------------------------------------

    if new.document_status <> 'Issued' then
        new.due_status := 'Not Applicable';

    elsif new.payment_status in (
        'Paid',
        'Overpaid'
    ) then
        new.due_status := 'Settled';

    elsif new.due_date < current_date then
        new.due_status := 'Overdue';

    elsif new.due_date = current_date then
        new.due_status := 'Due Today';

    elsif new.due_date <= current_date + 3 then
        new.due_status := 'Due Soon';

    else
        new.due_status := 'Not Due';
    end if;


    return new;
end;
$$;


ALTER FUNCTION "public"."sync_customer_invoice_statuses"() OWNER TO "postgres";


