CREATE OR REPLACE FUNCTION "public"."transition_material_requirement_status"("p_material_requirement_id" "uuid", "p_action" "text", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_actor uuid;
    v_header public.material_requirements%ROWTYPE;

    v_action text;
    v_reason text;
    v_required_permission text;

    v_previous_status text;
    v_new_status text;
BEGIN
    -- ================================================================
    -- Authentication
    -- ================================================================

    v_actor := auth.uid();

    IF v_actor IS NULL THEN
        RAISE EXCEPTION
            'Authentication is required.';
    END IF;

    IF p_material_requirement_id IS NULL THEN
        RAISE EXCEPTION
            'Material Requirement ID is required.';
    END IF;

    v_action :=
        NULLIF(
            btrim(p_action),
            ''
        );

    v_reason :=
        NULLIF(
            btrim(p_reason),
            ''
        );

    IF v_action IS NULL THEN
        RAISE EXCEPTION
            'Workflow action is required.';
    END IF;


    -- ================================================================
    -- Permission mapping
    -- ================================================================

    v_required_permission :=
        CASE v_action
            WHEN 'SubmitForReview'
                THEN 'material_requirements.review'

            WHEN 'ReturnToDraft'
                THEN 'material_requirements.review'

            WHEN 'Approve'
                THEN 'material_requirements.approve'

            WHEN 'StartPreparation'
                THEN 'material_requirements.update'

            WHEN 'MarkReady'
                THEN 'material_requirements.mark_ready'

            WHEN 'Complete'
                THEN 'material_requirements.update'

            WHEN 'Cancel'
                THEN 'material_requirements.update'

            ELSE NULL
        END;

    IF v_required_permission IS NULL THEN
        RAISE EXCEPTION
            'Unsupported Material Requirement workflow action: %.',
            v_action;
    END IF;

    IF NOT public.has_permission(v_required_permission) THEN
        RAISE EXCEPTION
            'Permission denied: % is required.',
            v_required_permission;
    END IF;


    -- ================================================================
    -- Lock Header
    -- ================================================================

    SELECT mr.*
    INTO v_header
    FROM public.material_requirements mr
    WHERE mr.material_requirement_id =
              p_material_requirement_id
      AND mr.is_active = true
      AND mr.is_deleted = false
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'Active Material Requirement was not found.';
    END IF;

    v_previous_status := v_header.requirement_status;


    -- ================================================================
    -- Submit Draft for Review
    -- ================================================================

    IF v_action = 'SubmitForReview' THEN
        IF v_previous_status <> 'Draft' THEN
            RAISE EXCEPTION
                'Only a Draft Material Requirement may be submitted for review. Current status: %.',
                v_previous_status;
        END IF;

        IF NOT EXISTS (
            SELECT 1
            FROM public.material_requirement_lines line_row
            WHERE line_row.material_requirement_id =
                      p_material_requirement_id
              AND line_row.is_active = true
              AND line_row.is_deleted = false
              AND line_row.line_status NOT IN (
                  'Excluded',
                  'Cancelled'
              )
        ) THEN
            RAISE EXCEPTION
                'Material Requirement cannot be submitted without at least one active required line.';
        END IF;

        v_new_status := 'UnderReview';

        UPDATE public.material_requirements
        SET
            requirement_status = v_new_status,
            updated_at = now(),
            updated_by = v_actor
        WHERE material_requirement_id =
              p_material_requirement_id;


    -- ================================================================
    -- Return Under Review to Draft
    -- ================================================================

    ELSIF v_action = 'ReturnToDraft' THEN
        IF v_previous_status <> 'UnderReview' THEN
            RAISE EXCEPTION
                'Only an UnderReview Material Requirement may be returned to Draft. Current status: %.',
                v_previous_status;
        END IF;

        IF v_reason IS NULL THEN
            RAISE EXCEPTION
                'A reason is required when returning a Material Requirement to Draft.';
        END IF;

        v_new_status := 'Draft';

        UPDATE public.material_requirements
        SET
            requirement_status = v_new_status,
            reviewed_at = NULL,
            reviewed_by = NULL,
            updated_at = now(),
            updated_by = v_actor,
            notes =
                concat_ws(
                    E'\n',
                    NULLIF(btrim(notes), ''),
                    '[Returned to Draft] ' || v_reason
                )
        WHERE material_requirement_id =
              p_material_requirement_id;


    -- ================================================================
    -- Approve
    -- ================================================================

    ELSIF v_action = 'Approve' THEN
        IF v_previous_status <> 'UnderReview' THEN
            RAISE EXCEPTION
                'Only an UnderReview Material Requirement may be approved. Current status: %.',
                v_previous_status;
        END IF;

        IF NOT EXISTS (
            SELECT 1
            FROM public.material_requirement_lines line_row
            WHERE line_row.material_requirement_id =
                      p_material_requirement_id
              AND line_row.is_active = true
              AND line_row.is_deleted = false
              AND line_row.line_status NOT IN (
                  'Excluded',
                  'Cancelled'
              )
        ) THEN
            RAISE EXCEPTION
                'Material Requirement cannot be approved without at least one active required line.';
        END IF;

        v_new_status := 'Approved';

        UPDATE public.material_requirements
        SET
            requirement_status = v_new_status,
            reviewed_at = now(),
            reviewed_by = v_actor,
            approved_at = now(),
            approved_by = v_actor,
            updated_at = now(),
            updated_by = v_actor
        WHERE material_requirement_id =
              p_material_requirement_id;


    -- ================================================================
    -- Start Preparation
    -- ================================================================

    ELSIF v_action = 'StartPreparation' THEN
        IF v_previous_status <> 'Approved' THEN
            RAISE EXCEPTION
                'Only an Approved Material Requirement may enter preparation. Current status: %.',
                v_previous_status;
        END IF;

        v_new_status := 'InPreparation';

        UPDATE public.material_requirements
        SET
            requirement_status = v_new_status,
            updated_at = now(),
            updated_by = v_actor
        WHERE material_requirement_id =
              p_material_requirement_id;


    -- ================================================================
    -- Mark Ready
    -- ================================================================

    ELSIF v_action = 'MarkReady' THEN
        IF v_previous_status NOT IN (
            'InPreparation',
            'PartiallyReady'
        ) THEN
            RAISE EXCEPTION
                'Only an InPreparation or PartiallyReady Material Requirement may be marked Ready. Current status: %.',
                v_previous_status;
        END IF;

        v_new_status := 'Ready';

        UPDATE public.material_requirements
        SET
            requirement_status = v_new_status,
            ready_at = now(),
            ready_by = v_actor,
            updated_at = now(),
            updated_by = v_actor
        WHERE material_requirement_id =
              p_material_requirement_id;


    -- ================================================================
    -- Complete
    -- ================================================================

    ELSIF v_action = 'Complete' THEN
        IF v_previous_status <> 'Ready' THEN
            RAISE EXCEPTION
                'Only a Ready Material Requirement may be completed. Current status: %.',
                v_previous_status;
        END IF;

        v_new_status := 'Completed';

        UPDATE public.material_requirements
        SET
            requirement_status = v_new_status,
            updated_at = now(),
            updated_by = v_actor
        WHERE material_requirement_id =
              p_material_requirement_id;


    -- ================================================================
    -- Cancel
    -- ================================================================

    ELSIF v_action = 'Cancel' THEN
        IF v_previous_status IN (
            'Completed',
            'Cancelled'
        ) THEN
            RAISE EXCEPTION
                'A % Material Requirement cannot be cancelled.',
                v_previous_status;
        END IF;

        IF v_reason IS NULL THEN
            RAISE EXCEPTION
                'Cancellation reason is required.';
        END IF;

        v_new_status := 'Cancelled';

        UPDATE public.material_requirements
        SET
            requirement_status = v_new_status,
            cancellation_reason = v_reason,
            cancelled_at = now(),
            cancelled_by = v_actor,
            updated_at = now(),
            updated_by = v_actor
        WHERE material_requirement_id =
              p_material_requirement_id;
    END IF;


    -- ================================================================
    -- Reload and return current Header
    -- ================================================================

    SELECT mr.*
    INTO STRICT v_header
    FROM public.material_requirements mr
    WHERE mr.material_requirement_id =
          p_material_requirement_id;

    RETURN jsonb_build_object(
        'material_requirement_id',
            v_header.material_requirement_id,

        'material_requirement_no',
            v_header.material_requirement_no,

        'action',
            v_action,

        'previous_status',
            v_previous_status,

        'new_status',
            v_header.requirement_status,

        'required_permission',
            v_required_permission,

        'performed_by',
            v_actor,

        'performed_at',
            now(),

        'header',
            to_jsonb(v_header)
    );
END;
$$;


ALTER FUNCTION "public"."transition_material_requirement_status"("p_material_requirement_id" "uuid", "p_action" "text", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."transition_material_requirement_status"("p_material_requirement_id" "uuid", "p_action" "text", "p_reason" "text") IS 'Atomic state machine for Material Requirement workflow transitions: SubmitForReview, ReturnToDraft, Approve, StartPreparation, MarkReady, Complete and Cancel.';



CREATE OR REPLACE FUNCTION "public"."trigger_normalise_approved_stock_request_item"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
    v_request_status text;
    v_product_base_uom text;
    v_default_request_uom text;
    v_request_uom text;
    v_base_uom text;
    v_conversion numeric(18,6);
begin
    -- Do nothing for deleted rows or unrelated updates.
    if new.is_deleted then
        return new;
    end if;

    select sr.request_status
    into v_request_status
    from public.stock_requests sr
    where sr.stock_request_id = new.stock_request_id
      and sr.is_deleted = false;

    if v_request_status is null
       or v_request_status not in (
           'Approved',
           'Partially Approved',
           'Partially Reserved',
           'Reserved',
           'Partially Issued'
       ) then
        return new;
    end if;

    -- Only recalculate when an approval/UOM input changed or a snapshot is
    -- incomplete. This avoids unnecessary writes.
    if not (
        old.approved_quantity is distinct from new.approved_quantity
        or old.request_uom_code is distinct from new.request_uom_code
        or old.base_uom_code is distinct from new.base_uom_code
        or old.conversion_factor_to_base is distinct from
           new.conversion_factor_to_base
        or new.request_uom_code is null
        or new.base_uom_code is null
        or new.conversion_factor_to_base is null
        or new.requested_base_quantity is null
        or new.approved_base_quantity is null
    ) then
        return new;
    end if;

    select
        p.base_uom_code,
        p.default_request_uom_code
    into
        v_product_base_uom,
        v_default_request_uom
    from public.products p
    where p.product_id = new.product_id
      and p.is_active = true
      and p.is_deleted = false;

    if not found then
        raise exception
            'Active product % was not found for Stock Request item %.',
            new.product_id,
            new.stock_request_item_id;
    end if;

    v_base_uom := coalesce(
        new.base_uom_code,
        v_product_base_uom
    );

    if v_base_uom is null then
        raise exception
            'Base UOM is missing for Stock Request item %.',
            new.stock_request_item_id;
    end if;

    v_request_uom := coalesce(
        new.request_uom_code,
        nullif(new.unit_of_measure, ''),
        v_default_request_uom,
        v_base_uom
    );

    if v_request_uom = v_base_uom then
        v_conversion := 1;
    else
        select puc.conversion_factor
        into v_conversion
        from public.product_uom_conversions puc
        where puc.product_id = new.product_id
          and puc.from_uom_code = v_request_uom
          and puc.to_uom_code = v_base_uom
          and puc.is_active = true
          and puc.is_deleted = false
        order by puc.sort_order, puc.created_at
        limit 1;

        if v_conversion is null then
            raise exception
                'No active UOM conversion exists from % to % for Stock Request item %.',
                v_request_uom,
                v_base_uom,
                new.stock_request_item_id;
        end if;
    end if;

    new.line_status := case
        when coalesce(new.approved_quantity, 0) <= 0
            then 'Rejected'
        when new.approved_quantity < new.requested_quantity
            then 'PartiallyApproved'
        else 'Approved'
    end;

    new.request_uom_code := v_request_uom;
    new.base_uom_code := v_base_uom;
    new.conversion_factor_to_base := v_conversion;
    new.requested_base_quantity :=
        round(new.requested_quantity * v_conversion, 6);
    new.approved_base_quantity :=
        round(coalesce(new.approved_quantity, 0) * v_conversion, 6);
    new.allow_fractional_quantity :=
        coalesce(new.allow_fractional_quantity, true);
    new.updated_at := now();
    new.updated_by := coalesce(auth.uid(), new.updated_by);

    return new;
end;
$$;


ALTER FUNCTION "public"."trigger_normalise_approved_stock_request_item"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."trigger_normalise_stock_request_approval"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
    if new.is_deleted = false
       and new.request_status in (
           'Approved',
           'Partially Approved',
           'Partially Reserved',
           'Reserved',
           'Partially Issued'
       )
       and (
           old.request_status is distinct from new.request_status
           or exists (
               select 1
               from public.stock_request_items sri
               where sri.stock_request_id = new.stock_request_id
                 and sri.is_deleted = false
                 and (
                     sri.line_status in ('Draft', 'Submitted', 'UnderReview')
                     or sri.request_uom_code is null
                     or sri.base_uom_code is null
                     or sri.conversion_factor_to_base is null
                     or sri.approved_base_quantity is null
                 )
           )
       ) then
        perform public.normalise_stock_request_item_approval_snapshot(
            new.stock_request_id
        );
    end if;

    return new;
end;
$$;


ALTER FUNCTION "public"."trigger_normalise_stock_request_approval"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_draft_invoice_atomic"("p_invoice_id" "uuid", "p_invoice" "jsonb", "p_lines" "jsonb", "p_sources" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    v_existing public.customer_invoices%rowtype;
    v_new_id uuid;
begin
    perform public.assert_invoice_permission(
        'invoices.update_draft'
    );

    select *
    into v_existing
    from public.customer_invoices
    where customer_invoice_id = p_invoice_id
      and is_deleted = false
    for update;

    if not found then
        raise exception 'Invoice not found.';
    end if;

    if v_existing.document_status <> 'Draft' then
        raise exception
            'Only Draft Invoices can be updated.';
    end if;

    update public.customer_invoice_items
    set
        is_deleted = true,
        deleted_at = now(),
        updated_by = auth.uid()
    where customer_invoice_id = p_invoice_id
      and is_deleted = false;

    update public.invoice_sources
    set
        is_deleted = true,
        deleted_at = now(),
        updated_by = auth.uid()
    where customer_invoice_id = p_invoice_id
      and is_deleted = false;

    v_new_id := public._create_invoice_atomic_core(
        p_invoice,
        p_lines,
        p_sources
    );

    update public.customer_invoices target
    set
        customer_id = source.customer_id,
        project_id = source.project_id,
        project_site_id = source.project_site_id,
        price_book_id = source.price_book_id,
        invoice_date = source.invoice_date,
        due_date = source.due_date,
        invoice_type = source.invoice_type,
        subtotal_amount = source.subtotal_amount,
        discount_amount = source.discount_amount,
        tax_amount = source.tax_amount,
        total_amount = source.total_amount,
        paid_amount = 0,
        balance_amount = source.total_amount,
        currency_code = source.currency_code,
        payment_terms_type = source.payment_terms_type,
        payment_terms_days = source.payment_terms_days,
        line_amount_type = source.line_amount_type,
        customer_reference = source.customer_reference,
        notes = source.notes,
        updated_by = auth.uid()
    from public.customer_invoices source
    where target.customer_invoice_id = p_invoice_id
      and source.customer_invoice_id = v_new_id;

    update public.customer_invoice_items
    set customer_invoice_id = p_invoice_id
    where customer_invoice_id = v_new_id;

    update public.invoice_sources
    set customer_invoice_id = p_invoice_id
    where customer_invoice_id = v_new_id;

    delete from public.customer_invoices
    where customer_invoice_id = v_new_id;

    return p_invoice_id;
end;
$$;


ALTER FUNCTION "public"."update_draft_invoice_atomic"("p_invoice_id" "uuid", "p_invoice" "jsonb", "p_lines" "jsonb", "p_sources" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_draft_purchase_order_atomic"("p_purchase_order_id" "uuid", "p_purchase_order" "jsonb", "p_lines" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
    v_auth_user_id uuid := auth.uid();
    v_existing public.purchase_orders%rowtype;
    v_supplier public.suppliers%rowtype;
    v_supplier_id uuid;
    v_project_id uuid;
    v_site_id uuid;
    v_stock_location_id uuid;
    v_order_date date;
    v_expected_delivery_date date;
    v_supplier_quote_date date;
    v_line_result jsonb;
begin
    if v_auth_user_id is null then
        raise exception 'Authentication is required.';
    end if;

    if not public.has_permission('purchase_orders.update_draft') then
        raise exception 'You do not have permission to update Draft purchase orders.';
    end if;

    if p_purchase_order is null
       or jsonb_typeof(p_purchase_order) <> 'object' then
        raise exception 'Purchase order header is required.';
    end if;

    select *
    into v_existing
    from public.purchase_orders
    where purchase_order_id = p_purchase_order_id
      and is_deleted = false
    for update;

    if not found then
        raise exception 'Purchase Order was not found.';
    end if;

    if v_existing.order_status <> 'Draft' then
        raise exception 'Only a Draft purchase order can be updated.';
    end if;

    begin
        v_supplier_id := coalesce(
            nullif(btrim(p_purchase_order ->> 'supplier_id'), '')::uuid,
            v_existing.supplier_id
        );

        v_project_id := case
            when p_purchase_order ? 'project_id'
            then nullif(btrim(p_purchase_order ->> 'project_id'), '')::uuid
            else v_existing.project_id
        end;

        v_site_id := case
            when p_purchase_order ? 'site_id'
            then nullif(btrim(p_purchase_order ->> 'site_id'), '')::uuid
            else v_existing.site_id
        end;

        v_stock_location_id := case
            when p_purchase_order ? 'stock_location_id'
            then nullif(btrim(p_purchase_order ->> 'stock_location_id'), '')::uuid
            else v_existing.stock_location_id
        end;

        v_order_date := coalesce(
            nullif(p_purchase_order ->> 'order_date', '')::date,
            v_existing.order_date
        );

        v_expected_delivery_date := case
            when p_purchase_order ? 'expected_delivery_date'
            then nullif(p_purchase_order ->> 'expected_delivery_date', '')::date
            else v_existing.expected_delivery_date
        end;

        v_supplier_quote_date := case
            when p_purchase_order ? 'supplier_quote_date'
            then nullif(p_purchase_order ->> 'supplier_quote_date', '')::date
            else v_existing.supplier_quote_date
        end;
    exception
        when invalid_text_representation then
            raise exception 'Invalid purchase order header value.';
    end;

    select *
    into v_supplier
    from public.suppliers
    where supplier_id = v_supplier_id
      and is_deleted = false
      and is_active = true;

    if not found then
        raise exception 'Active supplier was not found.';
    end if;

    if v_site_id is not null
       and (
           v_project_id is null
           or not exists (
               select 1
               from public.project_sites site_row
               where site_row.site_id = v_site_id
                 and site_row.project_id = v_project_id
                 and site_row.is_deleted = false
           )
       ) then
        raise exception 'Selected Site does not belong to the selected Project.';
    end if;

    if v_expected_delivery_date is not null
       and v_expected_delivery_date < v_order_date then
        raise exception 'Expected delivery date cannot be before order date.';
    end if;

    update public.purchase_orders
    set
        supplier_id = v_supplier_id,
        project_id = v_project_id,
        site_id = v_site_id,
        order_date = v_order_date,
        expected_delivery_date = v_expected_delivery_date,
        notes = case
            when p_purchase_order ? 'notes'
            then nullif(btrim(p_purchase_order ->> 'notes'), '')
            else notes
        end,
        source_type = coalesce(
            nullif(btrim(p_purchase_order ->> 'source_type'), ''),
            source_type
        ),
        supplier_reference = case
            when p_purchase_order ? 'supplier_reference'
            then nullif(btrim(p_purchase_order ->> 'supplier_reference'), '')
            else supplier_reference
        end,
        supplier_quote_no = case
            when p_purchase_order ? 'supplier_quote_no'
            then nullif(btrim(p_purchase_order ->> 'supplier_quote_no'), '')
            else supplier_quote_no
        end,
        supplier_quote_date = v_supplier_quote_date,
        currency_code = coalesce(
            nullif(btrim(p_purchase_order ->> 'currency_code'), ''),
            currency_code,
            v_supplier.default_currency,
            'AUD'
        ),
        payment_terms_type = coalesce(
            nullif(btrim(p_purchase_order ->> 'payment_terms_type'), ''),
            payment_terms_type,
            v_supplier.payment_terms_type
        ),
        payment_terms_days = coalesce(
            nullif(p_purchase_order ->> 'payment_terms_days', '')::integer,
            payment_terms_days,
            v_supplier.payment_terms_days
        ),
        default_tax_type = coalesce(
            nullif(btrim(p_purchase_order ->> 'default_tax_type'), ''),
            default_tax_type,
            v_supplier.default_tax_type
        ),
        delivery_destination_type = coalesce(
            nullif(btrim(p_purchase_order ->> 'delivery_destination_type'), ''),
            delivery_destination_type
        ),
        stock_location_id = v_stock_location_id,
        delivery_address_snapshot = case
            when p_purchase_order ? 'delivery_address_snapshot'
            then p_purchase_order -> 'delivery_address_snapshot'
            else delivery_address_snapshot
        end,
        delivery_contact_name = case
            when p_purchase_order ? 'delivery_contact_name'
            then nullif(btrim(p_purchase_order ->> 'delivery_contact_name'), '')
            else delivery_contact_name
        end,
        delivery_contact_phone = case
            when p_purchase_order ? 'delivery_contact_phone'
            then nullif(btrim(p_purchase_order ->> 'delivery_contact_phone'), '')
            else delivery_contact_phone
        end,
        delivery_method = case
            when p_purchase_order ? 'delivery_method'
            then nullif(btrim(p_purchase_order ->> 'delivery_method'), '')
            else delivery_method
        end,
        delivery_instructions = case
            when p_purchase_order ? 'delivery_instructions'
            then nullif(btrim(p_purchase_order ->> 'delivery_instructions'), '')
            else delivery_instructions
        end,
        supplier_notes = case
            when p_purchase_order ? 'supplier_notes'
            then nullif(btrim(p_purchase_order ->> 'supplier_notes'), '')
            else supplier_notes
        end,
        internal_notes = case
            when p_purchase_order ? 'internal_notes'
            then nullif(btrim(p_purchase_order ->> 'internal_notes'), '')
            else internal_notes
        end,
        updated_at = now(),
        updated_by = v_auth_user_id
    where purchase_order_id = p_purchase_order_id;

    v_line_result := public._replace_purchase_order_lines_atomic(
        p_purchase_order_id,
        v_supplier_id,
        v_project_id,
        v_site_id,
        p_lines
    );

    update public.purchase_orders po
    set
        subtotal_amount = totals.subtotal_amount,
        tax_amount = totals.tax_amount,
        total_amount = totals.total_amount,
        updated_at = now(),
        updated_by = v_auth_user_id
    from (
        select
            coalesce(sum(line_subtotal), 0)::numeric(14,2) as subtotal_amount,
            coalesce(sum(tax_amount), 0)::numeric(14,2) as tax_amount,
            coalesce(sum(line_total), 0)::numeric(14,2) as total_amount
        from public.purchase_order_lines
        where purchase_order_id = p_purchase_order_id
          and is_deleted = false
    ) totals
    where po.purchase_order_id = p_purchase_order_id;

    return jsonb_build_object(
        'purchase_order_id', p_purchase_order_id,
        'purchase_order_no', v_existing.purchase_order_no,
        'order_status', 'Draft',
        'created_line_count', v_line_result -> 'created_line_count'
    );
end;
$$;


ALTER FUNCTION "public"."update_draft_purchase_order_atomic"("p_purchase_order_id" "uuid", "p_purchase_order" "jsonb", "p_lines" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_draft_quotation_atomic"("p_quotation_id" "uuid", "p_quotation" "jsonb", "p_lines" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    -- --------------------------------------------------------
    -- Authentication
    -- --------------------------------------------------------

    v_user_id uuid;


    -- --------------------------------------------------------
    -- Existing quotation identity and status
    -- --------------------------------------------------------

    v_quotation_no text;
    v_existing_customer_id uuid;
    v_existing_project_site_id uuid;
    v_existing_price_book_id uuid;
    v_existing_status text;

    v_existing_segment text;
    v_existing_source text;
    v_existing_issue_date date;
    v_existing_valid_until date;
    v_existing_notes text;
    v_existing_internal_notes text;


    -- --------------------------------------------------------
    -- Updated header values
    -- --------------------------------------------------------

    v_requested_customer_id uuid;
    v_requested_project_site_id uuid;

    v_price_book_id uuid;
    v_quotation_segment text;
    v_quotation_source text;
    v_issue_date date;
    v_valid_until date;
    v_notes text;
    v_internal_notes text;


    -- --------------------------------------------------------
    -- Project hierarchy
    -- --------------------------------------------------------

    v_project_id uuid;
    v_project_customer_id uuid;
    v_project_status text;
    v_site_status text;


    -- --------------------------------------------------------
    -- Lines
    -- --------------------------------------------------------

    v_line jsonb;
    v_line_no integer := 0;
    v_line_count integer := 0;
    v_replaced_line_count integer := 0;

    v_product_id uuid;
    v_project_area_id uuid;
    v_description text;

    v_sales_uom_code text;
    v_base_uom_code text;
    v_conversion_factor numeric(18,6);
    v_allow_fractional boolean;

    v_quantity numeric(12,2);
    v_base_quantity numeric(18,6);

    v_unit_price numeric(12,2);
    v_discount_percent numeric(5,2);
    v_discount_amount numeric(12,2);

    v_tax_rate numeric(5,2);
    v_tax_amount numeric(12,2);

    v_line_subtotal numeric(14,2);
    v_line_total numeric(14,2);

    v_cost_price numeric(12,2);
    v_margin_amount numeric(12,2);
    v_margin_percent numeric(5,2);

    v_line_notes text;
    v_is_optional boolean;


    -- --------------------------------------------------------
    -- Header totals
    -- --------------------------------------------------------

    v_subtotal_amount numeric(14,2) := 0;
    v_total_discount_amount numeric(14,2) := 0;
    v_total_tax_amount numeric(14,2) := 0;
    v_total_amount numeric(14,2) := 0;
begin
    -- ========================================================
    -- 1. AUTHENTICATION AND PERMISSION
    -- ========================================================

    v_user_id := auth.uid();

    if v_user_id is null then
        raise exception
            'Authentication is required.';
    end if;

    if not public.has_permission(
        'quotations.update_draft'
    ) then
        raise exception
            'Permission denied: quotations.update_draft is required.';
    end if;


    -- ========================================================
    -- 2. INPUT STRUCTURE
    -- ========================================================

    if p_quotation_id is null then
        raise exception
            'Quotation ID is required.';
    end if;

    if p_quotation is null
       or jsonb_typeof(p_quotation) <> 'object' then
        raise exception
            'Quotation header must be a JSON object.';
    end if;

    if p_lines is null
       or jsonb_typeof(p_lines) <> 'array' then
        raise exception
            'Quotation lines must be a JSON array.';
    end if;

    v_line_count := jsonb_array_length(p_lines);

    if v_line_count = 0 then
        raise exception
            'At least one quotation line is required.';
    end if;


    -- ========================================================
    -- 3. LOCK EXISTING QUOTATION HEADER
    -- ========================================================

    select
        q.quotation_no,
        q.customer_id,
        q.project_site_id,
        q.price_book_id,
        q.quotation_status,
        q.quotation_segment,
        q.quotation_source,
        q.issue_date,
        q.valid_until,
        q.notes,
        q.internal_notes
    into
        v_quotation_no,
        v_existing_customer_id,
        v_existing_project_site_id,
        v_existing_price_book_id,
        v_existing_status,
        v_existing_segment,
        v_existing_source,
        v_existing_issue_date,
        v_existing_valid_until,
        v_existing_notes,
        v_existing_internal_notes
    from public.quotations q
    where q.quotation_id = p_quotation_id
      and q.is_active = true
      and q.is_deleted = false
    for update;

    if not found then
        raise exception
            'Quotation does not exist, is inactive, or is deleted.';
    end if;

    if v_existing_status <> 'Draft' then
        raise exception
            'Only a Draft quotation can be updated. Current status: %.',
            v_existing_status;
    end if;

    if v_existing_project_site_id is null then
        raise exception
            'The Draft quotation does not have a Project Site.';
    end if;


    -- ========================================================
    -- 4. LOCK EXISTING QUOTATION LINES
    --
    -- PERFORM is valid even when the quotation currently has
    -- no active lines.
    -- ========================================================

    perform 1
    from public.quotation_lines ql
    where ql.quotation_id = p_quotation_id
    for update;


    -- ========================================================
    -- 5. VALIDATE IMMUTABLE CUSTOMER AND SITE IDENTITY
    --
    -- The client may omit customer_id/project_site_id.
    -- If supplied, they must match the existing quotation.
    -- ========================================================

    if p_quotation ? 'customer_id' then
        begin
            v_requested_customer_id :=
                nullif(
                    btrim(
                        p_quotation ->> 'customer_id'
                    ),
                    ''
                )::uuid;
        exception
            when invalid_text_representation then
                raise exception
                    'Invalid customer_id.';
        end;

        if v_requested_customer_id is null then
            raise exception
                'Customer cannot be removed from the quotation.';
        end if;

        if v_requested_customer_id is distinct from
           v_existing_customer_id then
            raise exception
                'Quotation Customer cannot be changed after the quotation is created.';
        end if;
    end if;

    if p_quotation ? 'project_site_id' then
        begin
            v_requested_project_site_id :=
                nullif(
                    btrim(
                        p_quotation ->> 'project_site_id'
                    ),
                    ''
                )::uuid;
        exception
            when invalid_text_representation then
                raise exception
                    'Invalid project_site_id.';
        end;

        if v_requested_project_site_id is null then
            raise exception
                'Project Site cannot be removed from the quotation.';
        end if;

        if v_requested_project_site_id is distinct from
           v_existing_project_site_id then
            raise exception
                'Project Site cannot be changed after the quotation is created.';
        end if;
    end if;


    -- ========================================================
    -- 6. LOCK AND VALIDATE PROJECT/SITE HIERARCHY
    -- ========================================================

    select
        ps.project_id,
        ps.site_status,
        p.customer_id,
        p.project_status
    into
        v_project_id,
        v_site_status,
        v_project_customer_id,
        v_project_status
    from public.project_sites ps
    join public.projects p
      on p.project_id = ps.project_id
    where ps.site_id = v_existing_project_site_id
      and ps.is_active = true
      and ps.is_deleted = false
      and p.is_active = true
      and p.is_deleted = false
    for update of ps, p;

    if not found then
        raise exception
            'Project Site or its Project does not exist, is inactive, or is deleted.';
    end if;

    if v_project_customer_id is distinct from
       v_existing_customer_id then
        raise exception
            'Quotation Customer does not match the Project Customer.';
    end if;

    if v_site_status <> 'Quotation' then
        raise exception
            'A Draft quotation can only be updated while the Site has Quotation status. Current status: %.',
            v_site_status;
    end if;

    if v_project_status not in (
        'Draft',
        'Quoted'
    ) then
        raise exception
            'A Draft quotation cannot be updated for a Project with status %. Expected Draft or Quoted.',
            v_project_status;
    end if;


    -- ========================================================
    -- 7. READ UPDATED HEADER VALUES
    --
    -- Rules:
    --   Key omitted       = preserve existing value
    --   Key supplied null = clear nullable value
    -- ========================================================


    -- --------------------------------------------------------
    -- Price Book
    -- --------------------------------------------------------

    if p_quotation ? 'price_book_id' then
        begin
            v_price_book_id :=
                nullif(
                    btrim(
                        p_quotation ->> 'price_book_id'
                    ),
                    ''
                )::uuid;
        exception
            when invalid_text_representation then
                raise exception
                    'Invalid price_book_id.';
        end;
    else
        v_price_book_id := v_existing_price_book_id;
    end if;


    -- --------------------------------------------------------
    -- Quotation Segment
    -- --------------------------------------------------------

    if p_quotation ? 'quotation_segment' then
        v_quotation_segment :=
            nullif(
                btrim(
                    p_quotation ->> 'quotation_segment'
                ),
                ''
            );
    else
        v_quotation_segment := v_existing_segment;
    end if;


    -- --------------------------------------------------------
    -- Source
    -- --------------------------------------------------------

    if p_quotation ? 'quotation_source' then
        v_quotation_source :=
            nullif(
                btrim(
                    p_quotation ->> 'quotation_source'
                ),
                ''
            );
    else
        v_quotation_source := v_existing_source;
    end if;


    -- --------------------------------------------------------
    -- Issue Date
    -- --------------------------------------------------------

    if p_quotation ? 'issue_date' then
        begin
            v_issue_date :=
                nullif(
                    btrim(
                        p_quotation ->> 'issue_date'
                    ),
                    ''
                )::date;
        exception
            when others then
                raise exception
                    'Invalid issue_date.';
        end;
    else
        v_issue_date := v_existing_issue_date;
    end if;


    -- --------------------------------------------------------
    -- Valid Until
    -- --------------------------------------------------------

    if p_quotation ? 'valid_until' then
        begin
            v_valid_until :=
                nullif(
                    btrim(
                        p_quotation ->> 'valid_until'
                    ),
                    ''
                )::date;
        exception
            when others then
                raise exception
                    'Invalid valid_until.';
        end;
    else
        v_valid_until := v_existing_valid_until;
    end if;


    -- --------------------------------------------------------
    -- Notes
    -- --------------------------------------------------------

    if p_quotation ? 'notes' then
        v_notes :=
            nullif(
                btrim(
                    p_quotation ->> 'notes'
                ),
                ''
            );
    else
        v_notes := v_existing_notes;
    end if;


    -- --------------------------------------------------------
    -- Internal Notes
    -- --------------------------------------------------------

    if p_quotation ? 'internal_notes' then
        v_internal_notes :=
            nullif(
                btrim(
                    p_quotation ->> 'internal_notes'
                ),
                ''
            );
    else
        v_internal_notes :=
            v_existing_internal_notes;
    end if;


    -- ========================================================
    -- 8. VALIDATE UPDATED HEADER
    -- ========================================================

    if v_quotation_segment is null then
        raise exception
            'Quotation Segment is required.';
    end if;

    if v_quotation_segment not in (
        'Retail',
        'Builder',
        'Commercial',
        'VIP',
        'Promotion'
    ) then
        raise exception
            'Invalid Quotation Segment: %.',
            v_quotation_segment;
    end if;

    if v_issue_date is not null
       and v_valid_until is not null
       and v_valid_until < v_issue_date then
        raise exception
            'Valid Until cannot be earlier than Issue Date.';
    end if;

    if v_price_book_id is not null
       and not exists (
            select 1
            from public.price_books pb
            where pb.price_book_id =
                  v_price_book_id
       ) then
        raise exception
            'Selected Price Book does not exist.';
    end if;


    -- ========================================================
    -- 9. VALIDATE AND PREPARE REPLACEMENT LINES
    --
    -- Existing lines are not changed until all replacement
    -- lines have passed validation and calculation.
    --
    -- Temporary table exists only inside this RPC call.
    -- ========================================================

    create temporary table if not exists
        pg_temp.update_draft_quotation_lines_stage (
            line_no integer not null,
            product_id uuid,
            project_area_id uuid,
            description text not null,
            unit_of_measure text not null,
            quantity numeric(12,2) not null,
            unit_price numeric(12,2) not null,
            discount_percent numeric(5,2) not null,
            discount_amount numeric(12,2) not null,
            tax_rate numeric(5,2) not null,
            tax_amount numeric(12,2) not null,
            line_total numeric(14,2) not null,
            cost_price numeric(12,2),
            margin_amount numeric(12,2),
            margin_percent numeric(5,2),
            notes text,
            is_optional boolean not null,
            sales_uom_code text not null,
            base_uom_code text not null,
            conversion_factor numeric(18,6) not null,
            base_quantity numeric(18,6) not null,
            allow_fractional_quantity boolean not null
        )
        on commit drop;

    truncate table
        pg_temp.update_draft_quotation_lines_stage;


    -- ========================================================
    -- 10. VALIDATE AND CALCULATE EACH REPLACEMENT LINE
    -- ========================================================

    for v_line in
        select value
        from jsonb_array_elements(p_lines)
    loop
        v_line_no := v_line_no + 1;

        if jsonb_typeof(v_line) <> 'object' then
            raise exception
                'Quotation line % must be a JSON object.',
                v_line_no;
        end if;


        -- ----------------------------------------------------
        -- IDs
        -- ----------------------------------------------------

        begin
            v_product_id :=
                nullif(
                    btrim(
                        v_line ->> 'product_id'
                    ),
                    ''
                )::uuid;
        exception
            when invalid_text_representation then
                raise exception
                    'Line % has an invalid product_id.',
                    v_line_no;
        end;

        begin
            v_project_area_id :=
                nullif(
                    btrim(
                        v_line ->> 'project_area_id'
                    ),
                    ''
                )::uuid;
        exception
            when invalid_text_representation then
                raise exception
                    'Line % has an invalid project_area_id.',
                    v_line_no;
        end;


        -- ----------------------------------------------------
        -- Description
        -- ----------------------------------------------------

        v_description :=
            nullif(
                btrim(
                    v_line ->> 'description'
                ),
                ''
            );

        if v_description is null then
            raise exception
                'Description is required for line %.',
                v_line_no;
        end if;


        -- ----------------------------------------------------
        -- UOM snapshot input
        -- ----------------------------------------------------

        v_sales_uom_code :=
            nullif(
                btrim(
                    v_line ->> 'sales_uom_code'
                ),
                ''
            );

        v_base_uom_code :=
            nullif(
                btrim(
                    v_line ->> 'base_uom_code'
                ),
                ''
            );

        if v_sales_uom_code is null then
            raise exception
                'Sales UOM is required for line %.',
                v_line_no;
        end if;

        if v_base_uom_code is null then
            raise exception
                'Base UOM is required for line %.',
                v_line_no;
        end if;

        if not exists (
            select 1
            from public.units_of_measure u
            where u.uom_code = v_sales_uom_code
        ) then
            raise exception
                'Sales UOM % on line % does not exist.',
                v_sales_uom_code,
                v_line_no;
        end if;

        if not exists (
            select 1
            from public.units_of_measure u
            where u.uom_code = v_base_uom_code
        ) then
            raise exception
                'Base UOM % on line % does not exist.',
                v_base_uom_code,
                v_line_no;
        end if;


        -- ----------------------------------------------------
        -- Numeric input
        -- ----------------------------------------------------

        begin
            v_quantity :=
                coalesce(
                    nullif(
                        btrim(
                            v_line ->> 'quantity'
                        ),
                        ''
                    )::numeric,
                    0
                );

            v_conversion_factor :=
                coalesce(
                    nullif(
                        btrim(
                            v_line
                            ->> 'conversion_factor'
                        ),
                        ''
                    )::numeric,
                    1
                );

            v_unit_price :=
                coalesce(
                    nullif(
                        btrim(
                            v_line ->> 'unit_price'
                        ),
                        ''
                    )::numeric,
                    0
                );

            v_discount_percent :=
                coalesce(
                    nullif(
                        btrim(
                            v_line
                            ->> 'discount_percent'
                        ),
                        ''
                    )::numeric,
                    0
                );

            v_tax_rate :=
                coalesce(
                    nullif(
                        btrim(
                            v_line ->> 'tax_rate'
                        ),
                        ''
                    )::numeric,
                    0
                );

            v_cost_price :=
                nullif(
                    btrim(
                        v_line ->> 'cost_price'
                    ),
                    ''
                )::numeric;
        exception
            when invalid_text_representation
              or numeric_value_out_of_range then
                raise exception
                    'Line % contains an invalid numeric value.',
                    v_line_no;
        end;


        -- ----------------------------------------------------
        -- Boolean input
        -- ----------------------------------------------------

        begin
            v_allow_fractional :=
                coalesce(
                    nullif(
                        btrim(
                            v_line
                            ->> 'allow_fractional_quantity'
                        ),
                        ''
                    )::boolean,
                    true
                );

            v_is_optional :=
                coalesce(
                    nullif(
                        btrim(
                            v_line ->> 'is_optional'
                        ),
                        ''
                    )::boolean,
                    false
                );
        exception
            when invalid_text_representation then
                raise exception
                    'Line % contains an invalid boolean value.',
                    v_line_no;
        end;


        -- ----------------------------------------------------
        -- Numeric validation
        -- ----------------------------------------------------

        if v_quantity <= 0 then
            raise exception
                'Quantity must be greater than zero on line %.',
                v_line_no;
        end if;

        if not v_allow_fractional
           and v_quantity <> trunc(v_quantity) then
            raise exception
                'Line % does not allow fractional quantity.',
                v_line_no;
        end if;

        if v_conversion_factor <= 0 then
            raise exception
                'Conversion Factor must be greater than zero on line %.',
                v_line_no;
        end if;

        if v_unit_price < 0 then
            raise exception
                'Unit Price cannot be negative on line %.',
                v_line_no;
        end if;

        if v_discount_percent < 0
           or v_discount_percent > 100 then
            raise exception
                'Discount Percent must be between 0 and 100 on line %.',
                v_line_no;
        end if;

        if v_tax_rate < 0 then
            raise exception
                'Tax Rate cannot be negative on line %.',
                v_line_no;
        end if;

        if v_cost_price is not null
           and v_cost_price < 0 then
            raise exception
                'Cost Price cannot be negative on line %.',
                v_line_no;
        end if;


        -- ----------------------------------------------------
        -- Product validation
        -- ----------------------------------------------------

        if v_product_id is not null
           and not exists (
                select 1
                from public.products pr
                where pr.product_id =
                      v_product_id
                  and pr.is_active = true
                  and pr.is_deleted = false
           ) then
            raise exception
                'Product on line % does not exist or is inactive.',
                v_line_no;
        end if;


        -- ----------------------------------------------------
        -- Project Area relationship validation
        -- ----------------------------------------------------

        if v_project_area_id is not null
           and not exists (
                select 1
                from public.project_areas pa
                where pa.area_id =
                      v_project_area_id
                  and pa.site_id =
                      v_existing_project_site_id
                  and pa.project_id =
                      v_project_id
                  and pa.is_active = true
                  and pa.is_deleted = false
                  and pa.area_status =
                      'Quotation'
           ) then
            raise exception
                'Project Area on line % does not belong to the selected Project Site or is not available for quotation.',
                v_line_no;
        end if;


        -- ----------------------------------------------------
        -- Server calculations
        -- ----------------------------------------------------

        v_base_quantity :=
            round(
                v_quantity *
                v_conversion_factor,
                6
            );

        v_line_subtotal :=
            round(
                v_quantity *
                v_unit_price,
                2
            );

        v_discount_amount :=
            round(
                v_line_subtotal *
                v_discount_percent /
                100,
                2
            );

        v_tax_amount :=
            round(
                (
                    v_line_subtotal -
                    v_discount_amount
                ) *
                v_tax_rate /
                100,
                2
            );

        v_line_total :=
            round(
                v_line_subtotal -
                v_discount_amount +
                v_tax_amount,
                2
            );

        if v_cost_price is null then
            v_margin_amount := null;
            v_margin_percent := null;
        else
            v_margin_amount :=
                round(
                    (
                        v_unit_price -
                        v_cost_price
                    ) *
                    v_quantity -
                    v_discount_amount,
                    2
                );

            if (
                v_line_subtotal -
                v_discount_amount
            ) > 0 then
                v_margin_percent :=
                    round(
                        v_margin_amount /
                        (
                            v_line_subtotal -
                            v_discount_amount
                        ) *
                        100,
                        2
                    );
            else
                v_margin_percent := null;
            end if;
        end if;

        v_line_notes :=
            nullif(
                btrim(
                    v_line ->> 'notes'
                ),
                ''
            );


        -- ----------------------------------------------------
        -- Stage validated line
        -- ----------------------------------------------------

        insert into
            pg_temp.update_draft_quotation_lines_stage (
                line_no,
                product_id,
                project_area_id,
                description,
                unit_of_measure,
                quantity,
                unit_price,
                discount_percent,
                discount_amount,
                tax_rate,
                tax_amount,
                line_total,
                cost_price,
                margin_amount,
                margin_percent,
                notes,
                is_optional,
                sales_uom_code,
                base_uom_code,
                conversion_factor,
                base_quantity,
                allow_fractional_quantity
            )
        values (
            v_line_no,
            v_product_id,
            v_project_area_id,
            v_description,
            v_sales_uom_code,
            v_quantity,
            v_unit_price,
            v_discount_percent,
            v_discount_amount,
            v_tax_rate,
            v_tax_amount,
            v_line_total,
            v_cost_price,
            v_margin_amount,
            v_margin_percent,
            v_line_notes,
            v_is_optional,
            v_sales_uom_code,
            v_base_uom_code,
            v_conversion_factor,
            v_base_quantity,
            v_allow_fractional
        );


        -- ----------------------------------------------------
        -- Accumulate Header totals
        -- ----------------------------------------------------

        if not v_is_optional then
            v_subtotal_amount :=
                v_subtotal_amount +
                v_line_subtotal;

            v_total_discount_amount :=
                v_total_discount_amount +
                v_discount_amount;

            v_total_tax_amount :=
                v_total_tax_amount +
                v_tax_amount;

            v_total_amount :=
                v_total_amount +
                v_line_total;
        end if;
    end loop;


    -- ========================================================
    -- 11. SOFT-DELETE EXISTING LINES
    -- ========================================================

    update public.quotation_lines
    set
        is_deleted = true,
        deleted_at = now(),
        updated_at = now(),
        updated_by = v_user_id
    where quotation_id = p_quotation_id
      and is_deleted = false;

    get diagnostics
        v_replaced_line_count = row_count;


    -- ========================================================
    -- 12. INSERT REPLACEMENT LINES
    -- ========================================================

    insert into public.quotation_lines (
        quotation_id,
        product_id,
        project_area_id,
        line_no,
        description,
        unit_of_measure,
        quantity,
        unit_price,
        discount_percent,
        discount_amount,
        tax_rate,
        tax_amount,
        line_total,
        cost_price,
        margin_amount,
        margin_percent,
        notes,
        is_optional,
        is_deleted,
        created_by,
        updated_by,
        sales_uom_code,
        base_uom_code,
        conversion_factor,
        base_quantity,
        allow_fractional_quantity
    )
    select
        p_quotation_id,
        s.product_id,
        s.project_area_id,
        s.line_no,
        s.description,
        s.unit_of_measure,
        s.quantity,
        s.unit_price,
        s.discount_percent,
        s.discount_amount,
        s.tax_rate,
        s.tax_amount,
        s.line_total,
        s.cost_price,
        s.margin_amount,
        s.margin_percent,
        s.notes,
        s.is_optional,
        false,
        v_user_id,
        v_user_id,
        s.sales_uom_code,
        s.base_uom_code,
        s.conversion_factor,
        s.base_quantity,
        s.allow_fractional_quantity
    from
        pg_temp.update_draft_quotation_lines_stage s
    order by
        s.line_no;


    -- ========================================================
    -- 13. UPDATE QUOTATION HEADER AND TOTALS
    -- ========================================================

    update public.quotations
    set
        price_book_id =
            v_price_book_id,
        quotation_segment =
            v_quotation_segment,
        quotation_source =
            v_quotation_source,
        issue_date =
            v_issue_date,
        valid_until =
            v_valid_until,
        subtotal_amount =
            round(
                v_subtotal_amount,
                2
            ),
        discount_amount =
            round(
                v_total_discount_amount,
                2
            ),
        tax_amount =
            round(
                v_total_tax_amount,
                2
            ),
        total_amount =
            round(
                v_total_amount,
                2
            ),
        notes =
            v_notes,
        internal_notes =
            v_internal_notes,
        updated_at =
            now(),
        updated_by =
            v_user_id
    where quotation_id =
          p_quotation_id;


    -- ========================================================
    -- 14. KEEP PROJECT LIFECYCLE CONSISTENT
    -- ========================================================

    update public.projects
    set
        project_status = case
            when project_status = 'Draft'
                then 'Quoted'
            else project_status
        end,
        price_book_id =
            coalesce(
                v_price_book_id,
                price_book_id
            ),
        updated_at =
            now(),
        updated_by =
            v_user_id
    where project_id =
          v_project_id
      and is_deleted = false;


    -- ========================================================
    -- 15. RETURN RESULT
    -- ========================================================

    return jsonb_build_object(
        'quotation_id',
        p_quotation_id,

        'quotation_no',
        v_quotation_no,

        'quotation_status',
        'Draft',

        'line_count',
        v_line_count,

        'replaced_line_count',
        v_replaced_line_count,

        'subtotal_amount',
        round(
            v_subtotal_amount,
            2
        ),

        'discount_amount',
        round(
            v_total_discount_amount,
            2
        ),

        'tax_amount',
        round(
            v_total_tax_amount,
            2
        ),

        'total_amount',
        round(
            v_total_amount,
            2
        )
    );
end;
$$;


ALTER FUNCTION "public"."update_draft_quotation_atomic"("p_quotation_id" "uuid", "p_quotation" "jsonb", "p_lines" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_draft_quotation_atomic"("p_quotation_id" "uuid", "p_quotation" "jsonb", "p_lines" "jsonb") IS 'Atomically updates an existing active Draft quotation. Requires quotations.update_draft. Locks the quotation, project, site and existing lines; validates all replacement lines before changing stored data; soft-deletes previous lines; inserts replacement lines; and recalculates totals, tax, margin and base quantity on the server. Customer and Project Site cannot be changed.';



CREATE OR REPLACE FUNCTION "public"."update_draft_quotation_revision_atomic"("p_revision_id" "uuid", "p_revision" "jsonb", "p_lines" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    -- ------------------------------------------------------------------------
    -- Authentication
    -- ------------------------------------------------------------------------

    v_user_id uuid;


    -- ------------------------------------------------------------------------
    -- Existing revision identity and snapshot
    -- ------------------------------------------------------------------------

    v_quotation_id uuid;
    v_revision_no integer;
    v_existing_revision_status text;

    v_existing_customer_id uuid;
    v_existing_project_site_id uuid;
    v_existing_price_book_id uuid;

    v_existing_segment text;
    v_existing_source text;
    v_existing_issue_date date;
    v_existing_valid_until date;

    v_existing_notes text;
    v_existing_internal_notes text;
    v_existing_revision_reason text;
    v_existing_revision_notes text;


    -- ------------------------------------------------------------------------
    -- Parent quotation
    -- ------------------------------------------------------------------------

    v_parent_quotation_no text;
    v_parent_status text;
    v_parent_customer_id uuid;
    v_parent_project_site_id uuid;
    v_parent_current_revision_id uuid;
    v_parent_accepted_revision_id uuid;
    v_parent_accepted_at timestamptz;
    v_parent_accepted_by uuid;


    -- ------------------------------------------------------------------------
    -- Requested immutable values
    -- ------------------------------------------------------------------------

    v_requested_customer_id uuid;
    v_requested_project_site_id uuid;


    -- ------------------------------------------------------------------------
    -- Updated revision header values
    -- ------------------------------------------------------------------------

    v_price_book_id uuid;
    v_quotation_segment text;
    v_quotation_source text;

    v_issue_date date;
    v_valid_until date;

    v_notes text;
    v_internal_notes text;
    v_revision_reason text;
    v_revision_notes text;


    -- ------------------------------------------------------------------------
    -- Project hierarchy
    -- ------------------------------------------------------------------------

    v_project_id uuid;
    v_project_customer_id uuid;
    v_project_status text;
    v_site_status text;


    -- ------------------------------------------------------------------------
    -- Replacement lines
    -- ------------------------------------------------------------------------

    v_line jsonb;
    v_line_no integer := 0;
    v_line_count integer := 0;
    v_replaced_line_count integer := 0;

    v_quotation_line_id uuid;
    v_product_id uuid;
    v_project_area_id uuid;

    v_description text;

    v_sales_uom_code text;
    v_base_uom_code text;
    v_conversion_factor numeric(18,6);
    v_allow_fractional boolean;

    v_quantity numeric(12,2);
    v_base_quantity numeric(18,6);

    v_unit_price numeric(12,2);
    v_discount_percent numeric(5,2);
    v_discount_amount numeric(12,2);

    v_tax_rate numeric(5,2);
    v_tax_amount numeric(12,2);

    v_line_subtotal numeric(14,2);
    v_line_total numeric(14,2);

    v_cost_price numeric(12,2);
    v_margin_amount numeric(12,2);
    v_margin_percent numeric(5,2);

    v_line_notes text;
    v_is_optional boolean;


    -- ------------------------------------------------------------------------
    -- Revision totals
    -- ------------------------------------------------------------------------

    v_subtotal_amount numeric(14,2) := 0;
    v_total_discount_amount numeric(14,2) := 0;
    v_total_tax_amount numeric(14,2) := 0;
    v_total_amount numeric(14,2) := 0;
begin
    -- ========================================================================
    -- 1. AUTHENTICATION AND PERMISSION
    -- ========================================================================

    v_user_id := auth.uid();

    if v_user_id is null then
        raise exception
            'Authentication is required.';
    end if;

    if not public.has_permission(
        'quotations.update_revision'
    ) then
        raise exception
            'Permission denied: quotations.update_revision is required.';
    end if;


    -- ========================================================================
    -- 2. INPUT STRUCTURE
    -- ========================================================================

    if p_revision_id is null then
        raise exception
            'Quotation Revision ID is required.';
    end if;

    if p_revision is null
       or jsonb_typeof(p_revision) <> 'object' then
        raise exception
            'Quotation revision header must be a JSON object.';
    end if;

    if p_lines is null
       or jsonb_typeof(p_lines) <> 'array' then
        raise exception
            'Quotation revision lines must be a JSON array.';
    end if;

    v_line_count := jsonb_array_length(p_lines);

    if v_line_count = 0 then
        raise exception
            'At least one quotation revision line is required.';
    end if;


    -- ========================================================================
    -- 3. LOCK AND LOAD REVISION
    -- ========================================================================

    select
        qr.quotation_id,
        qr.revision_no,
        qr.revision_status,

        qr.customer_id,
        qr.project_site_id,
        qr.price_book_id,

        qr.quotation_segment,
        qr.quotation_source,
        qr.issue_date,
        qr.valid_until,

        qr.notes,
        qr.internal_notes,
        qr.revision_reason,
        qr.revision_notes

    into
        v_quotation_id,
        v_revision_no,
        v_existing_revision_status,

        v_existing_customer_id,
        v_existing_project_site_id,
        v_existing_price_book_id,

        v_existing_segment,
        v_existing_source,
        v_existing_issue_date,
        v_existing_valid_until,

        v_existing_notes,
        v_existing_internal_notes,
        v_existing_revision_reason,
        v_existing_revision_notes

    from public.quotation_revisions qr
    where qr.revision_id = p_revision_id
    for update;

    if not found then
        raise exception
            'Quotation revision was not found.';
    end if;

    if v_existing_revision_status <> 'Draft' then
        raise exception
            'Only a Draft quotation revision can be updated. Current status: %.',
            v_existing_revision_status;
    end if;

    if v_existing_project_site_id is null then
        raise exception
            'The Draft quotation revision does not have a Project Site.';
    end if;


    -- ========================================================================
    -- 4. LOCK AND VALIDATE PARENT QUOTATION
    -- ========================================================================

    select
        q.quotation_no,
        q.quotation_status,
        q.customer_id,
        q.project_site_id,
        q.current_revision_id,
        q.accepted_revision_id,
        q.accepted_at,
        q.accepted_by

    into
        v_parent_quotation_no,
        v_parent_status,
        v_parent_customer_id,
        v_parent_project_site_id,
        v_parent_current_revision_id,
        v_parent_accepted_revision_id,
        v_parent_accepted_at,
        v_parent_accepted_by

    from public.quotations q
    where q.quotation_id = v_quotation_id
      and q.is_active = true
      and q.is_deleted = false
    for update;

    if not found then
        raise exception
            'Parent quotation does not exist, is inactive, or is deleted.';
    end if;

    if v_parent_status not in (
        'Sent',
        'Revised'
    ) then
        raise exception
            'A Draft revision can only be updated while the parent quotation is Sent or Revised. Current status: %.',
            v_parent_status;
    end if;

    if v_parent_current_revision_id is null then
        raise exception
            'Parent quotation does not have a current revision.';
    end if;

    if v_parent_current_revision_id is distinct from
       p_revision_id then
        raise exception
            'Only the current Draft quotation revision can be updated.';
    end if;

    if v_parent_accepted_revision_id is not null
       or v_parent_accepted_at is not null
       or v_parent_accepted_by is not null then
        raise exception
            'Accepted quotation cannot be updated. Use a Variation for commercial changes.';
    end if;

    if v_parent_customer_id is distinct from
       v_existing_customer_id then
        raise exception
            'Revision Customer does not match the parent quotation.';
    end if;

    if v_parent_project_site_id is distinct from
       v_existing_project_site_id then
        raise exception
            'Revision Project Site does not match the parent quotation.';
    end if;


    -- ========================================================================
    -- 5. LOCK EXISTING REVISION LINES
    -- ========================================================================

    perform 1
    from public.quotation_revision_lines qrl
    where qrl.revision_id = p_revision_id
    for update;


    -- ========================================================================
    -- 6. VALIDATE IMMUTABLE CUSTOMER AND SITE
    --
    -- The client may omit these keys.
    -- If supplied, the values must match the existing revision.
    -- ========================================================================

    if p_revision ? 'customer_id' then
        begin
            v_requested_customer_id :=
                nullif(
                    btrim(
                        p_revision ->> 'customer_id'
                    ),
                    ''
                )::uuid;
        exception
            when invalid_text_representation then
                raise exception
                    'Invalid customer_id.';
        end;

        if v_requested_customer_id is null then
            raise exception
                'Customer cannot be removed from the revision.';
        end if;

        if v_requested_customer_id is distinct from
           v_existing_customer_id then
            raise exception
                'Revision Customer cannot be changed.';
        end if;
    end if;

    if p_revision ? 'project_site_id' then
        begin
            v_requested_project_site_id :=
                nullif(
                    btrim(
                        p_revision ->> 'project_site_id'
                    ),
                    ''
                )::uuid;
        exception
            when invalid_text_representation then
                raise exception
                    'Invalid project_site_id.';
        end;

        if v_requested_project_site_id is null then
            raise exception
                'Project Site cannot be removed from the revision.';
        end if;

        if v_requested_project_site_id is distinct from
           v_existing_project_site_id then
            raise exception
                'Revision Project Site cannot be changed.';
        end if;
    end if;


    -- ========================================================================
    -- 7. LOCK AND VALIDATE PROJECT / SITE HIERARCHY
    -- ========================================================================

    select
        ps.project_id,
        ps.site_status,
        pr.customer_id,
        pr.project_status

    into
        v_project_id,
        v_site_status,
        v_project_customer_id,
        v_project_status

    from public.project_sites ps
    join public.projects pr
      on pr.project_id = ps.project_id

    where ps.site_id = v_existing_project_site_id
      and ps.is_active = true
      and ps.is_deleted = false
      and pr.is_active = true
      and pr.is_deleted = false

    for update of ps, pr;

    if not found then
        raise exception
            'Project Site or its Project does not exist, is inactive, or is deleted.';
    end if;

    if v_project_customer_id is distinct from
       v_existing_customer_id then
        raise exception
            'Revision Customer does not match the Project Customer.';
    end if;

    if v_site_status <> 'Quotation' then
        raise exception
            'A Draft revision can only be updated while the Project Site status is Quotation. Current status: %.',
            v_site_status;
    end if;

    if v_project_status not in (
        'Draft',
        'Quoted'
    ) then
        raise exception
            'A Draft revision cannot be updated for a Project with status %. Expected Draft or Quoted.',
            v_project_status;
    end if;


    -- ========================================================================
    -- 8. READ UPDATED HEADER VALUES
    --
    -- Key omitted       = preserve existing value
    -- Key supplied null = clear nullable value
    -- ========================================================================

    if p_revision ? 'price_book_id' then
        begin
            v_price_book_id :=
                nullif(
                    btrim(
                        p_revision ->> 'price_book_id'
                    ),
                    ''
                )::uuid;
        exception
            when invalid_text_representation then
                raise exception
                    'Invalid price_book_id.';
        end;
    else
        v_price_book_id :=
            v_existing_price_book_id;
    end if;


    if p_revision ? 'quotation_segment' then
        v_quotation_segment :=
            nullif(
                btrim(
                    p_revision ->> 'quotation_segment'
                ),
                ''
            );
    else
        v_quotation_segment :=
            v_existing_segment;
    end if;


    if p_revision ? 'quotation_source' then
        v_quotation_source :=
            nullif(
                btrim(
                    p_revision ->> 'quotation_source'
                ),
                ''
            );
    else
        v_quotation_source :=
            v_existing_source;
    end if;


    if p_revision ? 'issue_date' then
        begin
            v_issue_date :=
                nullif(
                    btrim(
                        p_revision ->> 'issue_date'
                    ),
                    ''
                )::date;
        exception
            when others then
                raise exception
                    'Invalid issue_date.';
        end;
    else
        v_issue_date :=
            v_existing_issue_date;
    end if;


    if p_revision ? 'valid_until' then
        begin
            v_valid_until :=
                nullif(
                    btrim(
                        p_revision ->> 'valid_until'
                    ),
                    ''
                )::date;
        exception
            when others then
                raise exception
                    'Invalid valid_until.';
        end;
    else
        v_valid_until :=
            v_existing_valid_until;
    end if;


    if p_revision ? 'notes' then
        v_notes :=
            nullif(
                btrim(
                    p_revision ->> 'notes'
                ),
                ''
            );
    else
        v_notes :=
            v_existing_notes;
    end if;


    if p_revision ? 'internal_notes' then
        v_internal_notes :=
            nullif(
                btrim(
                    p_revision ->> 'internal_notes'
                ),
                ''
            );
    else
        v_internal_notes :=
            v_existing_internal_notes;
    end if;


    if p_revision ? 'revision_reason' then
        v_revision_reason :=
            nullif(
                btrim(
                    p_revision ->> 'revision_reason'
                ),
                ''
            );
    else
        v_revision_reason :=
            v_existing_revision_reason;
    end if;


    if p_revision ? 'revision_notes' then
        v_revision_notes :=
            nullif(
                btrim(
                    p_revision ->> 'revision_notes'
                ),
                ''
            );
    else
        v_revision_notes :=
            v_existing_revision_notes;
    end if;


    -- ========================================================================
    -- 9. VALIDATE UPDATED HEADER
    -- ========================================================================

    if v_quotation_segment is null then
        raise exception
            'Quotation Segment is required.';
    end if;

    if v_quotation_segment not in (
        'Retail',
        'Builder',
        'Commercial',
        'VIP',
        'Promotion'
    ) then
        raise exception
            'Invalid Quotation Segment: %.',
            v_quotation_segment;
    end if;

    if v_issue_date is not null
       and v_valid_until is not null
       and v_valid_until < v_issue_date then
        raise exception
            'Valid Until cannot be earlier than Issue Date.';
    end if;

    if v_price_book_id is not null
       and not exists (
            select 1
            from public.price_books pb
            where pb.price_book_id =
                  v_price_book_id
       ) then
        raise exception
            'Selected Price Book does not exist.';
    end if;


    -- ========================================================================
    -- 10. CREATE REPLACEMENT-LINE STAGING TABLE
    --
    -- Existing lines remain unchanged until every incoming line has passed
    -- validation and calculation.
    -- ========================================================================

    drop table if exists
        pg_temp.update_draft_quotation_revision_lines_stage;

    create temporary table
        pg_temp.update_draft_quotation_revision_lines_stage (
            line_no integer not null,

            quotation_line_id uuid,
            product_id uuid,
            project_area_id uuid,

            description text not null,
            unit_of_measure text not null,

            quantity numeric(12,2) not null,
            unit_price numeric(12,2) not null,

            discount_percent numeric(5,2) not null,
            discount_amount numeric(12,2) not null,

            tax_rate numeric(5,2) not null,
            tax_amount numeric(12,2) not null,

            line_total numeric(14,2) not null,

            cost_price numeric(12,2),
            margin_amount numeric(12,2),
            margin_percent numeric(5,2),

            notes text,

            sales_uom_code text not null,
            base_uom_code text not null,
            conversion_factor numeric(18,6) not null,
            base_quantity numeric(18,6) not null,
            allow_fractional_quantity boolean not null,

            is_optional boolean not null
        )
        on commit drop;


    -- ========================================================================
    -- 11. VALIDATE AND CALCULATE EACH REPLACEMENT LINE
    -- ========================================================================

    for v_line in
        select value
        from jsonb_array_elements(p_lines)
    loop
        v_line_no := v_line_no + 1;

        if jsonb_typeof(v_line) <> 'object' then
            raise exception
                'Quotation revision line % must be a JSON object.',
                v_line_no;
        end if;


        -- --------------------------------------------------------------------
        -- quotation_line_id lineage
        --
        -- Every line must explicitly include this key:
        --   copied base line -> UUID
        --   new revision line -> null
        -- --------------------------------------------------------------------

        if not (
            v_line ? 'quotation_line_id'
        ) then
            raise exception
                'quotation_line_id must be supplied for revision line %. Use null for a new revision-only line.',
                v_line_no;
        end if;

        begin
            v_quotation_line_id :=
                nullif(
                    btrim(
                        v_line ->> 'quotation_line_id'
                    ),
                    ''
                )::uuid;
        exception
            when invalid_text_representation then
                raise exception
                    'Line % has an invalid quotation_line_id.',
                    v_line_no;
        end;

        if v_quotation_line_id is not null
           and not exists (
                select 1
                from public.quotation_lines ql
                where ql.quotation_line_id =
                      v_quotation_line_id
                  and ql.quotation_id =
                      v_quotation_id
                  and ql.is_deleted = false
           ) then
            raise exception
                'quotation_line_id on revision line % does not belong to the parent quotation or has been deleted.',
                v_line_no;
        end if;


        -- --------------------------------------------------------------------
        -- Product and Project Area
        -- --------------------------------------------------------------------

        begin
            v_product_id :=
                nullif(
                    btrim(
                        v_line ->> 'product_id'
                    ),
                    ''
                )::uuid;
        exception
            when invalid_text_representation then
                raise exception
                    'Line % has an invalid product_id.',
                    v_line_no;
        end;

        begin
            v_project_area_id :=
                nullif(
                    btrim(
                        v_line ->> 'project_area_id'
                    ),
                    ''
                )::uuid;
        exception
            when invalid_text_representation then
                raise exception
                    'Line % has an invalid project_area_id.',
                    v_line_no;
        end;


        -- --------------------------------------------------------------------
        -- Description
        -- --------------------------------------------------------------------

        v_description :=
            nullif(
                btrim(
                    v_line ->> 'description'
                ),
                ''
            );

        if v_description is null then
            raise exception
                'Description is required for revision line %.',
                v_line_no;
        end if;


        -- --------------------------------------------------------------------
        -- UOM snapshot
        -- --------------------------------------------------------------------

        v_sales_uom_code :=
            nullif(
                btrim(
                    v_line ->> 'sales_uom_code'
                ),
                ''
            );

        v_base_uom_code :=
            nullif(
                btrim(
                    v_line ->> 'base_uom_code'
                ),
                ''
            );

        if v_sales_uom_code is null then
            raise exception
                'Sales UOM is required for revision line %.',
                v_line_no;
        end if;

        if v_base_uom_code is null then
            raise exception
                'Base UOM is required for revision line %.',
                v_line_no;
        end if;

        if not exists (
            select 1
            from public.units_of_measure u
            where u.uom_code =
                  v_sales_uom_code
        ) then
            raise exception
                'Sales UOM % on revision line % does not exist.',
                v_sales_uom_code,
                v_line_no;
        end if;

        if not exists (
            select 1
            from public.units_of_measure u
            where u.uom_code =
                  v_base_uom_code
        ) then
            raise exception
                'Base UOM % on revision line % does not exist.',
                v_base_uom_code,
                v_line_no;
        end if;


        -- --------------------------------------------------------------------
        -- Numeric input
        -- --------------------------------------------------------------------

        begin
            v_quantity :=
                coalesce(
                    nullif(
                        btrim(
                            v_line ->> 'quantity'
                        ),
                        ''
                    )::numeric,
                    0
                );

            v_conversion_factor :=
                coalesce(
                    nullif(
                        btrim(
                            v_line
                            ->> 'conversion_factor'
                        ),
                        ''
                    )::numeric,
                    1
                );

            v_unit_price :=
                coalesce(
                    nullif(
                        btrim(
                            v_line ->> 'unit_price'
                        ),
                        ''
                    )::numeric,
                    0
                );

            v_discount_percent :=
                coalesce(
                    nullif(
                        btrim(
                            v_line
                            ->> 'discount_percent'
                        ),
                        ''
                    )::numeric,
                    0
                );

            v_tax_rate :=
                coalesce(
                    nullif(
                        btrim(
                            v_line ->> 'tax_rate'
                        ),
                        ''
                    )::numeric,
                    0
                );

            v_cost_price :=
                nullif(
                    btrim(
                        v_line ->> 'cost_price'
                    ),
                    ''
                )::numeric;

        exception
            when invalid_text_representation
              or numeric_value_out_of_range then
                raise exception
                    'Revision line % contains an invalid numeric value.',
                    v_line_no;
        end;


        -- --------------------------------------------------------------------
        -- Boolean input
        -- --------------------------------------------------------------------

        begin
            v_allow_fractional :=
                coalesce(
                    nullif(
                        btrim(
                            v_line
                            ->> 'allow_fractional_quantity'
                        ),
                        ''
                    )::boolean,
                    true
                );

            v_is_optional :=
                coalesce(
                    nullif(
                        btrim(
                            v_line ->> 'is_optional'
                        ),
                        ''
                    )::boolean,
                    false
                );

        exception
            when invalid_text_representation then
                raise exception
                    'Revision line % contains an invalid boolean value.',
                    v_line_no;
        end;


        -- --------------------------------------------------------------------
        -- Numeric validation
        -- --------------------------------------------------------------------

        if v_quantity <= 0 then
            raise exception
                'Quantity must be greater than zero on revision line %.',
                v_line_no;
        end if;

        if not v_allow_fractional
           and v_quantity <> trunc(v_quantity) then
            raise exception
                'Revision line % does not allow fractional quantity.',
                v_line_no;
        end if;

        if v_conversion_factor <= 0 then
            raise exception
                'Conversion Factor must be greater than zero on revision line %.',
                v_line_no;
        end if;

        if v_unit_price < 0 then
            raise exception
                'Unit Price cannot be negative on revision line %.',
                v_line_no;
        end if;

        if v_discount_percent < 0
           or v_discount_percent > 100 then
            raise exception
                'Discount Percent must be between 0 and 100 on revision line %.',
                v_line_no;
        end if;

        if v_tax_rate < 0 then
            raise exception
                'Tax Rate cannot be negative on revision line %.',
                v_line_no;
        end if;

        if v_cost_price is not null
           and v_cost_price < 0 then
            raise exception
                'Cost Price cannot be negative on revision line %.',
                v_line_no;
        end if;


        -- --------------------------------------------------------------------
        -- Product validation
        -- --------------------------------------------------------------------

        if v_product_id is not null
           and not exists (
                select 1
                from public.products pr
                where pr.product_id =
                      v_product_id
                  and pr.is_active = true
                  and pr.is_deleted = false
           ) then
            raise exception
                'Product on revision line % does not exist or is inactive.',
                v_line_no;
        end if;


        -- --------------------------------------------------------------------
        -- Project Area validation
        -- --------------------------------------------------------------------

        if v_project_area_id is not null
           and not exists (
                select 1
                from public.project_areas pa
                where pa.area_id =
                      v_project_area_id
                  and pa.site_id =
                      v_existing_project_site_id
                  and pa.project_id =
                      v_project_id
                  and pa.is_active = true
                  and pa.is_deleted = false
                  and pa.area_status =
                      'Quotation'
           ) then
            raise exception
                'Project Area on revision line % does not belong to the selected Project Site or is not available for quotation.',
                v_line_no;
        end if;


        -- --------------------------------------------------------------------
        -- Server calculations
        -- --------------------------------------------------------------------

        v_base_quantity :=
            round(
                v_quantity *
                v_conversion_factor,
                6
            );

        v_line_subtotal :=
            round(
                v_quantity *
                v_unit_price,
                2
            );

        v_discount_amount :=
            round(
                v_line_subtotal *
                v_discount_percent /
                100,
                2
            );

        v_tax_amount :=
            round(
                (
                    v_line_subtotal -
                    v_discount_amount
                ) *
                v_tax_rate /
                100,
                2
            );

        v_line_total :=
            round(
                v_line_subtotal -
                v_discount_amount +
                v_tax_amount,
                2
            );

        if v_cost_price is null then
            v_margin_amount := null;
            v_margin_percent := null;
        else
            v_margin_amount :=
                round(
                    (
                        v_unit_price -
                        v_cost_price
                    ) *
                    v_quantity -
                    v_discount_amount,
                    2
                );

            if (
                v_line_subtotal -
                v_discount_amount
            ) > 0 then
                v_margin_percent :=
                    round(
                        v_margin_amount /
                        (
                            v_line_subtotal -
                            v_discount_amount
                        ) *
                        100,
                        2
                    );
            else
                v_margin_percent := null;
            end if;
        end if;

        v_line_notes :=
            nullif(
                btrim(
                    v_line ->> 'notes'
                ),
                ''
            );


        -- --------------------------------------------------------------------
        -- Stage validated replacement line
        -- --------------------------------------------------------------------

        insert into
            pg_temp.update_draft_quotation_revision_lines_stage (
                line_no,
                quotation_line_id,
                product_id,
                project_area_id,
                description,
                unit_of_measure,
                quantity,
                unit_price,
                discount_percent,
                discount_amount,
                tax_rate,
                tax_amount,
                line_total,
                cost_price,
                margin_amount,
                margin_percent,
                notes,
                sales_uom_code,
                base_uom_code,
                conversion_factor,
                base_quantity,
                allow_fractional_quantity,
                is_optional
            )
        values (
            v_line_no,
            v_quotation_line_id,
            v_product_id,
            v_project_area_id,
            v_description,
            v_sales_uom_code,
            v_quantity,
            v_unit_price,
            v_discount_percent,
            v_discount_amount,
            v_tax_rate,
            v_tax_amount,
            v_line_total,
            v_cost_price,
            v_margin_amount,
            v_margin_percent,
            v_line_notes,
            v_sales_uom_code,
            v_base_uom_code,
            v_conversion_factor,
            v_base_quantity,
            v_allow_fractional,
            v_is_optional
        );


        -- --------------------------------------------------------------------
        -- Accumulate revision header totals
        --
        -- Optional lines do not contribute to commercial header totals.
        -- --------------------------------------------------------------------

        if not v_is_optional then
            v_subtotal_amount :=
                v_subtotal_amount +
                v_line_subtotal;

            v_total_discount_amount :=
                v_total_discount_amount +
                v_discount_amount;

            v_total_tax_amount :=
                v_total_tax_amount +
                v_tax_amount;

            v_total_amount :=
                v_total_amount +
                v_line_total;
        end if;
    end loop;


    -- ========================================================================
    -- 12. SOFT-DELETE EXISTING REVISION LINES
    -- ========================================================================

    update public.quotation_revision_lines
    set
        is_deleted = true,
        deleted_at = now(),
        updated_by = v_user_id
    where revision_id = p_revision_id
      and is_deleted = false;

    get diagnostics
        v_replaced_line_count = row_count;


    -- ========================================================================
    -- 13. INSERT REPLACEMENT REVISION LINES
    -- ========================================================================

    insert into public.quotation_revision_lines (
        revision_id,
        quotation_line_id,
        line_no,

        product_id,
        project_area_id,
        description,
        unit_of_measure,

        quantity,
        unit_price,
        discount_percent,
        discount_amount,
        tax_rate,
        tax_amount,
        line_total,

        cost_price,
        margin_amount,
        margin_percent,

        notes,

        sales_uom_code,
        base_uom_code,
        conversion_factor,
        base_quantity,
        allow_fractional_quantity,

        is_optional,
        is_deleted,

        created_by,
        updated_by
    )
    select
        p_revision_id,
        s.quotation_line_id,
        s.line_no,

        s.product_id,
        s.project_area_id,
        s.description,
        s.unit_of_measure,

        s.quantity,
        s.unit_price,
        s.discount_percent,
        s.discount_amount,
        s.tax_rate,
        s.tax_amount,
        s.line_total,

        s.cost_price,
        s.margin_amount,
        s.margin_percent,

        s.notes,

        s.sales_uom_code,
        s.base_uom_code,
        s.conversion_factor,
        s.base_quantity,
        s.allow_fractional_quantity,

        s.is_optional,
        false,

        v_user_id,
        v_user_id

    from
        pg_temp.update_draft_quotation_revision_lines_stage s

    order by
        s.line_no;


    -- ========================================================================
    -- 14. UPDATE REVISION HEADER AND TOTALS
    -- ========================================================================

    update public.quotation_revisions
    set
        revision_reason =
            v_revision_reason,

        revision_notes =
            v_revision_notes,

        price_book_id =
            v_price_book_id,

        quotation_segment =
            v_quotation_segment,

        quotation_source =
            v_quotation_source,

        issue_date =
            v_issue_date,

        valid_until =
            v_valid_until,

        subtotal_amount =
            round(
                v_subtotal_amount,
                2
            ),

        discount_amount =
            round(
                v_total_discount_amount,
                2
            ),

        tax_amount =
            round(
                v_total_tax_amount,
                2
            ),

        total_amount =
            round(
                v_total_amount,
                2
            ),

        notes =
            v_notes,

        internal_notes =
            v_internal_notes,

        updated_by =
            v_user_id

    where revision_id =
          p_revision_id
      and revision_status =
          'Draft';

    if not found then
        raise exception
            'Draft quotation revision could not be updated.';
    end if;


    -- ========================================================================
    -- 15. VALIDATE CURRENT REVISION POINTER BEFORE RETURN
    -- ========================================================================

    if not exists (
        select 1
        from public.quotations q
        where q.quotation_id =
              v_quotation_id
          and q.current_revision_id =
              p_revision_id
          and q.quotation_status in (
              'Sent',
              'Revised'
          )
          and q.accepted_revision_id is null
          and q.accepted_at is null
          and q.accepted_by is null
          and q.is_active = true
          and q.is_deleted = false
    ) then
        raise exception
            'Parent quotation revision pointer or workflow status changed during the update.';
    end if;


    -- ========================================================================
    -- 16. RETURN RESULT
    -- ========================================================================

    return jsonb_build_object(
        'quotation_id',
            v_quotation_id,

        'quotation_no',
            v_parent_quotation_no,

        'quotation_status',
            v_parent_status,

        'revision_id',
            p_revision_id,

        'revision_no',
            v_revision_no,

        'revision_status',
            'Draft',

        'line_count',
            v_line_count,

        'replaced_line_count',
            v_replaced_line_count,

        'subtotal_amount',
            round(
                v_subtotal_amount,
                2
            ),

        'discount_amount',
            round(
                v_total_discount_amount,
                2
            ),

        'tax_amount',
            round(
                v_total_tax_amount,
                2
            ),

        'total_amount',
            round(
                v_total_amount,
                2
            )
    );
end;
$$;


ALTER FUNCTION "public"."update_draft_quotation_revision_atomic"("p_revision_id" "uuid", "p_revision" "jsonb", "p_lines" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_draft_stock_issue_atomic"("p_stock_issue_id" "uuid", "p_header" "jsonb", "p_lines" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
    v_issue public.stock_issues%rowtype;
    v_request public.stock_requests%rowtype;
    v_issue_line_id uuid;
    v_line jsonb;
    v_allocation jsonb;
    v_request_item public.stock_request_items%rowtype;
    v_product public.products%rowtype;
    v_lot public.stock_lots%rowtype;

    v_line_no integer := 0;
    v_issue_quantity numeric(18,6);
    v_issue_base_quantity numeric(18,6);
    v_conversion_factor numeric(18,6);
    v_issue_uom_code text;
    v_issued_product_id uuid;
    v_allocated_total numeric(18,6);
    v_from_stock_location_id uuid;
    v_to_stock_location_id uuid;
    v_delivery_method text;
begin
    if not public.has_permission('stock_issues.update_draft') then
        raise exception 'Permission denied: stock_issues.update_draft.';
    end if;

    if p_stock_issue_id is null then
        raise exception 'Stock Issue ID is required.';
    end if;

    if p_header is null or jsonb_typeof(p_header) <> 'object' then
        raise exception 'Stock Issue header is required.';
    end if;

    if p_lines is null
       or jsonb_typeof(p_lines) <> 'array'
       or jsonb_array_length(p_lines) = 0 then
        raise exception 'At least one Stock Issue line is required.';
    end if;

    select *
    into v_issue
    from public.stock_issues
    where stock_issue_id = p_stock_issue_id
      and is_deleted = false
    for update;

    if not found then
        raise exception 'Stock Issue was not found.';
    end if;

    if v_issue.issue_status <> 'Draft' then
        raise exception 'Only Draft Stock Issues can be updated.';
    end if;

    select *
    into v_request
    from public.stock_requests
    where stock_request_id = v_issue.stock_request_id
      and is_deleted = false
    for update;

    if not found then
        raise exception 'Source Stock Request was not found.';
    end if;

    v_from_stock_location_id :=
        nullif(p_header->>'from_stock_location_id', '')::uuid;

    if v_from_stock_location_id is null then
        raise exception 'Source Stock Location is required.';
    end if;

    v_delivery_method :=
        coalesce(nullif(p_header->>'delivery_method', ''), 'SiteDelivery');

    if v_delivery_method not in ('SiteDelivery', 'Pickup', 'StockTransfer') then
        raise exception 'Invalid delivery method.';
    end if;

    v_to_stock_location_id :=
        nullif(p_header->>'to_stock_location_id', '')::uuid;

    if v_delivery_method = 'StockTransfer' then
        if v_to_stock_location_id is null then
            raise exception 'Destination Stock Location is required for Stock Transfer.';
        end if;

        if v_to_stock_location_id = v_from_stock_location_id then
            raise exception 'Source and destination Stock Locations must be different.';
        end if;
    else
        v_to_stock_location_id := null;
    end if;

    -- Soft-delete previous allocations before lines.
    update public.stock_issue_allocations allocation
    set
        is_active = false,
        is_deleted = true,
        allocation_status = 'Cancelled',
        deleted_at = now(),
        updated_at = now(),
        updated_by = auth.uid()
    from public.stock_issue_lines line
    where line.stock_issue_line_id = allocation.stock_issue_line_id
      and line.stock_issue_id = p_stock_issue_id
      and line.is_deleted = false
      and allocation.is_deleted = false;

    update public.stock_issue_lines
    set
        is_active = false,
        is_deleted = true,
        line_status = 'Cancelled',
        deleted_at = now(),
        updated_at = now(),
        updated_by = auth.uid()
    where stock_issue_id = p_stock_issue_id
      and is_deleted = false;

    update public.stock_issues
    set
        from_stock_location_id = v_from_stock_location_id,
        to_stock_location_id = v_to_stock_location_id,
        delivery_method = v_delivery_method,
        priority = coalesce(nullif(p_header->>'priority', ''), 'Normal'),
        issue_date = coalesce(
            nullif(p_header->>'issue_date', '')::date,
            issue_date
        ),
        required_date = nullif(p_header->>'required_date', '')::date,
        recipient_auth_user_id =
            nullif(p_header->>'recipient_auth_user_id', '')::uuid,
        recipient_employee_id =
            nullif(p_header->>'recipient_employee_id', '')::uuid,
        recipient_name =
            nullif(btrim(p_header->>'recipient_name'), ''),
        vehicle_reference =
            nullif(btrim(p_header->>'vehicle_reference'), ''),
        dispatch_reference =
            nullif(btrim(p_header->>'dispatch_reference'), ''),
        notes = nullif(btrim(p_header->>'notes'), ''),
        updated_at = now(),
        updated_by = auth.uid()
    where stock_issue_id = p_stock_issue_id;

    for v_line in
        select value
        from jsonb_array_elements(p_lines)
    loop
        v_line_no := v_line_no + 1;

        select *
        into v_request_item
        from public.stock_request_items
        where stock_request_item_id =
              nullif(v_line->>'stock_request_item_id', '')::uuid
          and stock_request_id = v_request.stock_request_id
          and is_deleted = false
        for update;

        if not found then
            raise exception
                'Stock Request item for line % was not found.',
                v_line_no;
        end if;

        if coalesce(v_request_item.fulfilment_method, 'Issue') <> 'Issue' then
            raise exception
                'Stock Request item line % is not routed for Issue.',
                v_line_no;
        end if;

        if coalesce(v_request_item.approved_base_quantity, 0) <= 0 then
            raise exception
                'Stock Request item line % has no approved quantity.',
                v_line_no;
        end if;

        v_issued_product_id :=
            coalesce(
                nullif(v_line->>'issued_product_id', '')::uuid,
                v_request_item.product_id
            );

        select *
        into v_product
        from public.products
        where product_id = v_issued_product_id
          and is_deleted = false
          and is_active = true;

        if not found then
            raise exception
                'Issued product for line % was not found or is inactive.',
                v_line_no;
        end if;

        if v_product.product_type not in ('Material', 'Consumable') then
            raise exception
                'Stock Issue line % must use a Material or Consumable product.',
                v_line_no;
        end if;

        v_issue_uom_code :=
            coalesce(
                nullif(v_line->>'issue_uom_code', ''),
                v_request_item.request_uom_code,
                v_request_item.unit_of_measure,
                v_product.base_uom_code
            );

        if v_issue_uom_code = v_product.base_uom_code then
            v_conversion_factor := 1;
        else
            select conversion_factor
            into v_conversion_factor
            from public.product_uom_conversions
            where product_id = v_issued_product_id
              and from_uom_code = v_issue_uom_code
              and to_uom_code = v_product.base_uom_code
              and is_active = true
              and is_deleted = false
            order by sort_order, created_at
            limit 1;

            if not found then
                raise exception
                    'No active UOM conversion exists for Stock Issue line %.',
                    v_line_no;
            end if;
        end if;

        v_issue_quantity :=
            nullif(v_line->>'issue_quantity', '')::numeric;

        if v_issue_quantity is null or v_issue_quantity <= 0 then
            raise exception
                'Issue quantity for line % must be greater than zero.',
                v_line_no;
        end if;

        v_issue_base_quantity :=
            round(v_issue_quantity * v_conversion_factor, 6);

        if v_issue_base_quantity >
           v_request_item.approved_base_quantity then
            raise exception
                'Issue quantity for line % exceeds the approved quantity.',
                v_line_no;
        end if;

        if v_issued_product_id <> v_request_item.product_id
           and nullif(btrim(v_line->>'substitution_reason'), '') is null then
            raise exception
                'Substitution reason is required for line %.',
                v_line_no;
        end if;

        insert into public.stock_issue_lines (
            stock_issue_id,
            stock_request_item_id,
            line_no,
            requested_product_id,
            issued_product_id,
            description,
            issue_uom_code,
            base_uom_code,
            conversion_factor_to_base,
            allow_fractional_quantity,
            approved_quantity,
            approved_base_quantity,
            issue_quantity,
            issue_base_quantity,
            line_status,
            substitution_reason,
            preparation_notes,
            issue_notes,
            is_deleted
        )
        values (
            p_stock_issue_id,
            v_request_item.stock_request_item_id,
            v_line_no,
            v_request_item.product_id,
            v_issued_product_id,
            coalesce(
                nullif(btrim(v_line->>'description'), ''),
                v_request_item.description,
                v_product.product_name
            ),
            v_issue_uom_code,
            v_product.base_uom_code,
            v_conversion_factor,
            coalesce(v_request_item.allow_fractional_quantity, true),
            coalesce(v_request_item.approved_quantity, v_issue_quantity),
            v_request_item.approved_base_quantity,
            v_issue_quantity,
            v_issue_base_quantity,
            'Draft',
            nullif(btrim(v_line->>'substitution_reason'), ''),
            nullif(btrim(v_line->>'preparation_notes'), ''),
            nullif(btrim(v_line->>'issue_notes'), ''),
            false
        )
        returning stock_issue_line_id
        into v_issue_line_id;

        if not (v_line ? 'allocations')
           or jsonb_typeof(v_line->'allocations') <> 'array'
           or jsonb_array_length(v_line->'allocations') = 0 then
            raise exception
                'At least one Stock Lot allocation is required for line %.',
                v_line_no;
        end if;

        v_allocated_total := 0;

        for v_allocation in
            select value
            from jsonb_array_elements(v_line->'allocations')
        loop
            select *
            into v_lot
            from public.stock_lots
            where stock_lot_id =
                  nullif(v_allocation->>'stock_lot_id', '')::uuid
              and is_deleted = false
              and is_active = true
            for update;

            if not found then
                raise exception
                    'Active Stock Lot for line % was not found.',
                    v_line_no;
            end if;

            if v_lot.product_id <> v_issued_product_id then
                raise exception
                    'Stock Lot product does not match line % issued product.',
                    v_line_no;
            end if;

            if v_lot.stock_location_id <> v_from_stock_location_id then
                raise exception
                    'Stock Lot for line % is not in the selected source location.',
                    v_line_no;
            end if;

            if v_lot.base_uom_code <> v_product.base_uom_code then
                raise exception
                    'Stock Lot Base UOM does not match line %.',
                    v_line_no;
            end if;

            if nullif(
                v_allocation->>'allocated_base_quantity',
                ''
            )::numeric <= 0 then
                raise exception
                    'Allocation quantity for line % must be greater than zero.',
                    v_line_no;
            end if;

            if nullif(
                v_allocation->>'allocated_base_quantity',
                ''
            )::numeric >
               (v_lot.remaining_quantity - v_lot.reserved_quantity) then
                raise exception
                    'Stock Lot availability is insufficient for line %.',
                    v_line_no;
            end if;

            v_allocated_total :=
                v_allocated_total
                + nullif(
                    v_allocation->>'allocated_base_quantity',
                    ''
                  )::numeric;

            insert into public.stock_issue_allocations (
                stock_issue_line_id,
                stock_lot_id,
                allocated_base_quantity,
                issued_base_quantity,
                allocation_status,
                notes,
                is_deleted
            )
            values (
                v_issue_line_id,
                v_lot.stock_lot_id,
                nullif(
                    v_allocation->>'allocated_base_quantity',
                    ''
                )::numeric,
                0,
                'Allocated',
                nullif(btrim(v_allocation->>'notes'), ''),
                false
            );
        end loop;

        if round(v_allocated_total, 6) <>
           round(v_issue_base_quantity, 6) then
            raise exception
                'Allocation total for line % must equal its Issue Base Quantity.',
                v_line_no;
        end if;
    end loop;

    return p_stock_issue_id;
end;
$$;


ALTER FUNCTION "public"."update_draft_stock_issue_atomic"("p_stock_issue_id" "uuid", "p_header" "jsonb", "p_lines" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_draft_tool_loan_atomic"("p_tool_loan_id" "uuid", "p_header" "jsonb", "p_items" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
    v_existing public.tool_loans%rowtype;
    v_request public.stock_requests%rowtype;
    v_item jsonb;
    v_request_item public.stock_request_items%rowtype;
    v_product public.products%rowtype;
    v_line_no integer := 0;
    v_quantity numeric(18,6);
    v_base_quantity numeric(18,6);
    v_uom_code text;
    v_base_uom_code text;
    v_conversion numeric(18,6);
begin
    if not public.has_permission('tool_loans.create') then
        raise exception 'Permission denied: tool_loans.create.';
    end if;

    select *
    into v_existing
    from public.tool_loans
    where tool_loan_id = p_tool_loan_id
      and is_deleted = false
    for update;

    if not found then
        raise exception 'Tool Loan was not found.';
    end if;

    if v_existing.loan_status <> 'Draft' then
        raise exception 'Only Draft Tool Loans can be edited.';
    end if;

    if p_items is null
       or jsonb_typeof(p_items) <> 'array'
       or jsonb_array_length(p_items) = 0 then
        raise exception 'At least one Tool Loan item is required.';
    end if;

    select *
    into v_request
    from public.stock_requests
    where stock_request_id = v_existing.stock_request_id
      and is_deleted = false
    for update;

    if not found then
        raise exception 'Source Stock Request was not found.';
    end if;

    if nullif(p_header->>'borrower_employee_id', '') is null
       and nullif(p_header->>'borrower_auth_user_id', '') is null then
        raise exception 'Borrower is required.';
    end if;

    update public.tool_loan_items
    set
        is_active = false,
        is_deleted = true,
        deleted_at = now(),
        item_status = 'Cancelled',
        updated_at = now(),
        updated_by = auth.uid()
    where tool_loan_id = p_tool_loan_id
      and is_deleted = false;

    update public.tool_loans
    set
        from_stock_location_id =
            nullif(p_header->>'from_stock_location_id', '')::uuid,
        borrower_auth_user_id =
            nullif(p_header->>'borrower_auth_user_id', '')::uuid,
        borrower_employee_id =
            nullif(p_header->>'borrower_employee_id', '')::uuid,
        loan_date =
            coalesce(
                nullif(p_header->>'loan_date', '')::date,
                loan_date
            ),
        due_date = nullif(p_header->>'due_date', '')::date,
        priority =
            coalesce(nullif(p_header->>'priority', ''), priority),
        notes = nullif(btrim(p_header->>'notes'), ''),
        updated_at = now(),
        updated_by = auth.uid()
    where tool_loan_id = p_tool_loan_id;

    for v_item in
        select value
        from jsonb_array_elements(p_items)
    loop
        v_line_no := v_line_no + 1;

        select *
        into v_request_item
        from public.stock_request_items
        where stock_request_item_id =
              nullif(v_item->>'stock_request_item_id', '')::uuid
          and stock_request_id = v_request.stock_request_id
          and is_deleted = false
        for update;

        if not found then
            raise exception
                'Source Stock Request item for line % was not found.',
                v_line_no;
        end if;

        if coalesce(v_request_item.fulfilment_method, '') <> 'Loan' then
            raise exception
                'Stock Request item line % is not routed for Loan.',
                v_line_no;
        end if;

        select *
        into v_product
        from public.products
        where product_id = v_request_item.product_id
          and is_deleted = false
          and is_active = true;

        if not found or v_product.product_type not in ('Tool', 'Equipment') then
            raise exception
                'Line % must use an active Tool or Equipment product.',
                v_line_no;
        end if;

        v_quantity :=
            coalesce(
                nullif(v_item->>'approved_quantity', '')::numeric,
                v_request_item.approved_quantity
            );

        if v_quantity is null
           or v_quantity <= 0
           or v_quantity > coalesce(v_request_item.approved_quantity, 0) then
            raise exception
                'Invalid approved quantity for Tool Loan line %.',
                v_line_no;
        end if;

        v_uom_code :=
            coalesce(
                nullif(v_item->>'loan_uom_code', ''),
                v_request_item.request_uom_code,
                v_request_item.unit_of_measure,
                v_product.base_uom_code
            );

        v_base_uom_code :=
            coalesce(
                v_request_item.base_uom_code,
                v_product.base_uom_code
            );

        v_conversion :=
            coalesce(
                v_request_item.conversion_factor_to_base,
                1
            );

        v_base_quantity := round(v_quantity * v_conversion, 6);

        if v_base_quantity >
           coalesce(v_request_item.approved_base_quantity, 0) then
            raise exception
                'Tool Loan line % exceeds approved Base Quantity.',
                v_line_no;
        end if;

        insert into public.tool_loan_items (
            tool_loan_id,
            stock_request_item_id,
            line_no,
            product_id,
            asset_reference,
            serial_number,
            description,
            loan_uom_code,
            base_uom_code,
            conversion_factor_to_base,
            allow_fractional_quantity,
            approved_quantity,
            approved_base_quantity,
            issued_quantity,
            issued_base_quantity,
            returned_quantity,
            returned_base_quantity,
            damaged_quantity,
            lost_quantity,
            condition_before,
            condition_notes_before,
            item_status,
            notes,
            created_by,
            updated_by
        )
        values (
            p_tool_loan_id,
            v_request_item.stock_request_item_id,
            v_line_no,
            v_request_item.product_id,
            nullif(btrim(v_item->>'asset_reference'), ''),
            nullif(btrim(v_item->>'serial_number'), ''),
            coalesce(
                nullif(btrim(v_item->>'description'), ''),
                v_request_item.description,
                v_product.product_name
            ),
            v_uom_code,
            v_base_uom_code,
            v_conversion,
            coalesce(v_request_item.allow_fractional_quantity, false),
            v_quantity,
            v_base_quantity,
            0,
            0,
            0,
            0,
            0,
            0,
            nullif(v_item->>'condition_before', ''),
            nullif(btrim(v_item->>'condition_notes_before'), ''),
            'Draft',
            nullif(btrim(v_item->>'notes'), ''),
            auth.uid(),
            auth.uid()
        );
    end loop;

    return p_tool_loan_id;
end;
$$;


ALTER FUNCTION "public"."update_draft_tool_loan_atomic"("p_tool_loan_id" "uuid", "p_header" "jsonb", "p_items" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_draft_variation_atomic"("p_variation_id" "uuid", "p_variation" "jsonb", "p_lines" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    v_user_id uuid := auth.uid();
    v_existing public.variations%rowtype;
    v_result jsonb;
    v_temp_id uuid;
begin
    if v_user_id is null then
        raise exception 'Authentication is required.';
    end if;

    if not public.has_permission('variations.update_draft') then
        raise exception 'Permission denied: variations.update_draft is required.';
    end if;

    select *
    into v_existing
    from public.variations
    where variation_id = p_variation_id
      and is_active = true
      and is_deleted = false
    for update;

    if not found then
        raise exception 'Variation was not found, is inactive, or is archived.';
    end if;

    if v_existing.variation_status <> 'Draft' then
        raise exception 'Only a Draft Variation can be updated. Current status: %.', v_existing.variation_status;
    end if;

    -- Validate the replacement payload by creating a temporary sibling
    -- inside this transaction, then copy its validated snapshot back.
    v_result := public.create_variation_atomic(
        jsonb_build_object(
            'quotation_id', v_existing.quotation_id,
            'variation_reason', p_variation ->> 'variation_reason',
            'issue_date', p_variation ->> 'issue_date',
            'valid_until', p_variation ->> 'valid_until',
            'notes', p_variation ->> 'notes'
        ),
        p_lines
    );

    v_temp_id := (v_result ->> 'variation_id')::uuid;

    update public.variation_lines
    set
        is_deleted = true,
        deleted_at = now(),
        updated_by = v_user_id
    where variation_id = p_variation_id
      and is_deleted = false;

    insert into public.variation_lines (
        variation_id, line_no, product_id, project_area_id,
        description, quantity, unit_of_measure,
        sales_uom_code, base_uom_code, conversion_factor,
        base_quantity, allow_fractional_quantity,
        unit_price, discount_percent, discount_amount,
        tax_rate, tax_amount, line_total,
        cost_price, margin_amount, margin_percent,
        notes, is_optional, is_active, is_deleted,
        created_by, updated_by
    )
    select
        p_variation_id, line_no, product_id, project_area_id,
        description, quantity, unit_of_measure,
        sales_uom_code, base_uom_code, conversion_factor,
        base_quantity, allow_fractional_quantity,
        unit_price, discount_percent, discount_amount,
        tax_rate, tax_amount, line_total,
        cost_price, margin_amount, margin_percent,
        notes, is_optional, is_active, false,
        v_user_id, v_user_id
    from public.variation_lines
    where variation_id = v_temp_id
      and is_deleted = false
    order by line_no;

    update public.variations v
    set
        variation_reason = t.variation_reason,
        notes = t.notes,
        issue_date = t.issue_date,
        valid_until = t.valid_until,
        subtotal = t.subtotal,
        discount_amount = t.discount_amount,
        tax_amount = t.tax_amount,
        total_amount = t.total_amount,
        updated_by = v_user_id
    from public.variations t
    where v.variation_id = p_variation_id
      and t.variation_id = v_temp_id;

    delete from public.variation_lines
    where variation_id = v_temp_id;

    delete from public.variations
    where variation_id = v_temp_id;

    return jsonb_build_object(
        'variation_id', p_variation_id,
        'variation_no', v_existing.variation_no,
        'variation_status', 'Draft',
        'line_count', jsonb_array_length(p_lines),
        'subtotal', (v_result ->> 'subtotal')::numeric,
        'discount_amount', (v_result ->> 'discount_amount')::numeric,
        'tax_amount', (v_result ->> 'tax_amount')::numeric,
        'total_amount', (v_result ->> 'total_amount')::numeric
    );
end;
$$;


ALTER FUNCTION "public"."update_draft_variation_atomic"("p_variation_id" "uuid", "p_variation" "jsonb", "p_lines" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_material_requirement_header"("p_material_requirement_id" "uuid", "p_site_id" "uuid", "p_required_by_date" "date", "p_delivery_destination_type" "text", "p_delivery_stock_location_id" "uuid", "p_notes" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_actor uuid;

    v_before public.material_requirements%ROWTYPE;
    v_after public.material_requirements%ROWTYPE;

    v_destination_type text;
    v_notes text;
BEGIN
    -- -----------------------------------------------------------------
    -- Authentication and permission
    -- -----------------------------------------------------------------

    v_actor := auth.uid();

    IF v_actor IS NULL THEN
        RAISE EXCEPTION
            'Authentication is required.';
    END IF;

    IF NOT public.has_permission(
        'material_requirements.update'
    ) THEN
        RAISE EXCEPTION
            'Permission denied: material_requirements.update is required.';
    END IF;

    IF p_material_requirement_id IS NULL THEN
        RAISE EXCEPTION
            'Material Requirement ID is required.';
    END IF;


    -- -----------------------------------------------------------------
    -- Normalize inputs
    -- -----------------------------------------------------------------

    v_destination_type :=
        NULLIF(
            btrim(p_delivery_destination_type),
            ''
        );

    v_notes :=
        NULLIF(
            btrim(p_notes),
            ''
        );


    -- -----------------------------------------------------------------
    -- Validate destination type
    -- -----------------------------------------------------------------

    IF v_destination_type IS NULL THEN
        RAISE EXCEPTION
            'Delivery Destination Type is required.';
    END IF;

    IF v_destination_type NOT IN (
        'Warehouse',
        'Site',
        'DirectDelivery',
        'Other'
    ) THEN
        RAISE EXCEPTION
            'Invalid Delivery Destination Type: %.',
            v_destination_type;
    END IF;


    -- -----------------------------------------------------------------
    -- Lock active Header
    -- -----------------------------------------------------------------

    SELECT header_row.*
    INTO v_before
    FROM public.material_requirements header_row
    WHERE header_row.material_requirement_id =
              p_material_requirement_id
      AND header_row.is_active = true
      AND header_row.is_deleted = false
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'Active Material Requirement was not found.';
    END IF;


    -- -----------------------------------------------------------------
    -- Workflow rule
    -- -----------------------------------------------------------------

    IF v_before.requirement_status <> 'Draft' THEN
        RAISE EXCEPTION
            'Material Requirement Header details may be changed only while Draft. Current status: %.',
            v_before.requirement_status;
    END IF;


    -- -----------------------------------------------------------------
    -- Required-by Date validation
    -- -----------------------------------------------------------------

    IF p_required_by_date IS NOT NULL
       AND p_required_by_date < v_before.requirement_date THEN
        RAISE EXCEPTION
            'Required-by Date cannot be earlier than Requirement Date (%).',
            v_before.requirement_date;
    END IF;


    -- -----------------------------------------------------------------
    -- Site validation
    -- -----------------------------------------------------------------

    IF p_site_id IS NOT NULL THEN
        IF NOT EXISTS (
            SELECT 1
            FROM public.project_sites site_row
            WHERE site_row.site_id = p_site_id
        ) THEN
            RAISE EXCEPTION
                'Selected Project Site was not found.';
        END IF;

        IF NOT EXISTS (
            SELECT 1
            FROM public.project_sites site_row
            WHERE site_row.site_id = p_site_id
              AND site_row.project_id =
                  v_before.project_id
        ) THEN
            RAISE EXCEPTION
                'Selected Project Site does not belong to the Material Requirement Project.';
        END IF;
    END IF;


    -- -----------------------------------------------------------------
    -- Destination validation
    -- -----------------------------------------------------------------

    IF v_destination_type IN (
        'Site',
        'DirectDelivery'
    )
       AND p_site_id IS NULL THEN
        RAISE EXCEPTION
            'A Project Site is required for % delivery.',
            v_destination_type;
    END IF;

    IF v_destination_type = 'Warehouse'
       AND p_delivery_stock_location_id IS NULL THEN
        RAISE EXCEPTION
            'A Stock Location is required for Warehouse delivery.';
    END IF;

    IF v_destination_type <> 'Warehouse'
       AND p_delivery_stock_location_id IS NOT NULL THEN
        RAISE EXCEPTION
            'Stock Location may be selected only for Warehouse delivery.';
    END IF;

    IF p_delivery_stock_location_id IS NOT NULL
       AND NOT EXISTS (
           SELECT 1
           FROM public.stock_locations location_row
           WHERE location_row.stock_location_id =
                 p_delivery_stock_location_id
       ) THEN
        RAISE EXCEPTION
            'Selected Stock Location was not found.';
    END IF;


    -- -----------------------------------------------------------------
    -- Reject no-op update
    -- -----------------------------------------------------------------

    IF v_before.site_id
           IS NOT DISTINCT FROM p_site_id
       AND v_before.required_by_date
           IS NOT DISTINCT FROM p_required_by_date
       AND v_before.delivery_destination_type
           IS NOT DISTINCT FROM v_destination_type
       AND v_before.delivery_stock_location_id
           IS NOT DISTINCT FROM
              p_delivery_stock_location_id
       AND v_before.notes
           IS NOT DISTINCT FROM v_notes THEN
        RAISE EXCEPTION
            'No Material Requirement Header change was detected.';
    END IF;


    -- -----------------------------------------------------------------
    -- Update Header
    -- updated_at is also maintained by the existing trigger.
    -- -----------------------------------------------------------------

    UPDATE public.material_requirements
    SET
        site_id =
            p_site_id,

        required_by_date =
            p_required_by_date,

        delivery_destination_type =
            v_destination_type,

        delivery_stock_location_id =
            p_delivery_stock_location_id,

        notes =
            v_notes,

        updated_by =
            v_actor
    WHERE material_requirement_id =
          p_material_requirement_id
    RETURNING *
    INTO v_after;


    RETURN jsonb_build_object(
        'material_requirement_id',
            v_after.material_requirement_id,

        'material_requirement_no',
            v_after.material_requirement_no,

        'previous_site_id',
            v_before.site_id,

        'new_site_id',
            v_after.site_id,

        'previous_required_by_date',
            v_before.required_by_date,

        'new_required_by_date',
            v_after.required_by_date,

        'previous_delivery_destination_type',
            v_before.delivery_destination_type,

        'new_delivery_destination_type',
            v_after.delivery_destination_type,

        'previous_delivery_stock_location_id',
            v_before.delivery_stock_location_id,

        'new_delivery_stock_location_id',
            v_after.delivery_stock_location_id,

        'previous_notes',
            v_before.notes,

        'new_notes',
            v_after.notes,

        'updated_by',
            v_after.updated_by,

        'updated_at',
            v_after.updated_at,

        'header',
            to_jsonb(v_after)
    );
END;
$$;


ALTER FUNCTION "public"."update_material_requirement_header"("p_material_requirement_id" "uuid", "p_site_id" "uuid", "p_required_by_date" "date", "p_delivery_destination_type" "text", "p_delivery_stock_location_id" "uuid", "p_notes" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_material_requirement_header"("p_material_requirement_id" "uuid", "p_site_id" "uuid", "p_required_by_date" "date", "p_delivery_destination_type" "text", "p_delivery_stock_location_id" "uuid", "p_notes" "text") IS 'Atomically updates editable Draft Material Requirement Header details and validates Project Site, Required-by Date and Delivery Destination consistency.';



CREATE OR REPLACE FUNCTION "public"."update_material_requirement_line_quantity"("p_material_requirement_line_id" "uuid", "p_requirement_quantity" numeric, "p_waste_percent" numeric, "p_adjustment_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_actor uuid;

    v_header public.material_requirements%ROWTYPE;
    v_before public.material_requirement_lines%ROWTYPE;
    v_after public.material_requirement_lines%ROWTYPE;

    v_adjustment_id uuid;
    v_next_adjustment_no integer;

    v_adjustment_reason text;
    v_adjustment_type text;

    v_quantity_changed boolean;
    v_waste_changed boolean;

    v_base_quantity_change numeric;
BEGIN
    -- ================================================================
    -- Authentication and permission
    -- ================================================================

    v_actor := auth.uid();

    IF v_actor IS NULL THEN
        RAISE EXCEPTION
            'Authentication is required.';
    END IF;

    IF NOT public.has_permission(
        'material_requirements.adjust'
    ) THEN
        RAISE EXCEPTION
            'Permission denied: material_requirements.adjust is required.';
    END IF;


    -- ================================================================
    -- Input validation
    -- ================================================================

    IF p_material_requirement_line_id IS NULL THEN
        RAISE EXCEPTION
            'Material Requirement Line ID is required.';
    END IF;

    IF p_requirement_quantity IS NULL
       OR p_requirement_quantity < 0 THEN
        RAISE EXCEPTION
            'Requirement quantity must be zero or greater.';
    END IF;

    IF p_waste_percent IS NULL
       OR p_waste_percent < 0 THEN
        RAISE EXCEPTION
            'Waste percent must be zero or greater.';
    END IF;

    v_adjustment_reason :=
        NULLIF(
            btrim(p_adjustment_reason),
            ''
        );

    IF v_adjustment_reason IS NULL THEN
        RAISE EXCEPTION
            'Adjustment reason is required.';
    END IF;


    -- ================================================================
    -- Lock line
    -- ================================================================

    SELECT line_row.*
    INTO v_before
    FROM public.material_requirement_lines line_row
    WHERE line_row.material_requirement_line_id =
              p_material_requirement_line_id
      AND line_row.is_deleted = false
      AND line_row.is_active = true
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'Active Material Requirement Line was not found.';
    END IF;


    -- ================================================================
    -- Lock parent header
    -- ================================================================

    SELECT header_row.*
    INTO v_header
    FROM public.material_requirements header_row
    WHERE header_row.material_requirement_id =
              v_before.material_requirement_id
      AND header_row.is_deleted = false
      AND header_row.is_active = true
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'Active Material Requirement Header was not found.';
    END IF;

    IF v_header.requirement_status <> 'Draft' THEN
        RAISE EXCEPTION
            'Quantity and Waste may currently be changed only while the Material Requirement is Draft. Current status: %.',
            v_header.requirement_status;
    END IF;

    IF v_before.line_status IN (
        'Excluded',
        'Cancelled',
        'Fulfilled'
    ) THEN
        RAISE EXCEPTION
            'Quantity cannot be changed while the Line status is %.',
            v_before.line_status;
    END IF;


    -- ================================================================
    -- Determine whether any real change was requested
    -- ================================================================

    v_quantity_changed :=
        v_before.requirement_quantity
        IS DISTINCT FROM p_requirement_quantity;

    v_waste_changed :=
        v_before.waste_percent
        IS DISTINCT FROM p_waste_percent;

    IF NOT v_quantity_changed
       AND NOT v_waste_changed THEN
        RAISE EXCEPTION
            'No Quantity or Waste change was detected.';
    END IF;


    -- ================================================================
    -- Determine adjustment type supported by existing constraint
    -- ================================================================

    IF v_quantity_changed THEN
        IF p_requirement_quantity >
           v_before.requirement_quantity THEN
            v_adjustment_type := 'IncreaseQuantity';
        ELSE
            v_adjustment_type := 'DecreaseQuantity';
        END IF;
    ELSE
        v_adjustment_type := 'ChangeWaste';
    END IF;


    -- ================================================================
    -- Update current operational state
    --
    -- Existing quantity trigger recalculates:
    --   required_base_quantity_before_waste
    --   waste_base_quantity
    --   required_base_quantity
    -- ================================================================

    UPDATE public.material_requirement_lines
    SET
        requirement_quantity =
            p_requirement_quantity,

        waste_percent =
            p_waste_percent,

        updated_at =
            now(),

        updated_by =
            v_actor
    WHERE material_requirement_line_id =
          p_material_requirement_line_id
    RETURNING *
    INTO v_after;


    -- ================================================================
    -- Allocate next adjustment number
    --
    -- Line lock serializes adjustments for this line.
    -- ================================================================

    SELECT COALESCE(
        max(adjustment.adjustment_no),
        0
    ) + 1
    INTO v_next_adjustment_no
    FROM public.material_requirement_line_adjustments adjustment
    WHERE adjustment.material_requirement_line_id =
          p_material_requirement_line_id;


    v_base_quantity_change :=
        v_after.required_base_quantity
        - v_before.required_base_quantity;


    -- ================================================================
    -- Insert append-only adjustment event
    -- ================================================================

    INSERT INTO public.material_requirement_line_adjustments (
        material_requirement_line_id,
        adjustment_no,
        adjustment_type,
        adjustment_reason,

        before_snapshot,
        after_snapshot,

        base_quantity_change,

        commercial_impact,
        variation_required,

        approval_required,
        approval_status,

        created_by
    )
    VALUES (
        p_material_requirement_line_id,
        v_next_adjustment_no,
        v_adjustment_type,
        v_adjustment_reason,

        to_jsonb(v_before),
        to_jsonb(v_after),

        v_base_quantity_change,

        v_after.commercial_impact,
        v_after.variation_required,

        CASE
            WHEN v_after.commercial_impact IN (
                'CustomerCharge',
                'CustomerCredit',
                'PendingReview'
            )
            THEN true
            ELSE false
        END,

        CASE
            WHEN v_after.commercial_impact IN (
                'CustomerCharge',
                'CustomerCredit',
                'PendingReview'
            )
            THEN 'Pending'
            ELSE 'NotRequired'
        END,

        v_actor
    )
    RETURNING material_requirement_line_adjustment_id
    INTO v_adjustment_id;


    -- ================================================================
    -- Update header audit information
    -- ================================================================

    UPDATE public.material_requirements
    SET
        updated_at = now(),
        updated_by = v_actor
    WHERE material_requirement_id =
          v_before.material_requirement_id;


    -- ================================================================
    -- Return result
    -- ================================================================

    RETURN jsonb_build_object(
        'material_requirement_id',
            v_before.material_requirement_id,

        'material_requirement_line_id',
            p_material_requirement_line_id,

        'adjustment_id',
            v_adjustment_id,

        'adjustment_no',
            v_next_adjustment_no,

        'adjustment_type',
            v_adjustment_type,

        'quantity_changed',
            v_quantity_changed,

        'waste_changed',
            v_waste_changed,

        'previous_requirement_quantity',
            v_before.requirement_quantity,

        'new_requirement_quantity',
            v_after.requirement_quantity,

        'previous_waste_percent',
            v_before.waste_percent,

        'new_waste_percent',
            v_after.waste_percent,

        'previous_required_base_quantity',
            v_before.required_base_quantity,

        'new_required_base_quantity',
            v_after.required_base_quantity,

        'base_quantity_change',
            v_base_quantity_change,

        'line',
            to_jsonb(v_after)
    );
END;
$$;


ALTER FUNCTION "public"."update_material_requirement_line_quantity"("p_material_requirement_line_id" "uuid", "p_requirement_quantity" numeric, "p_waste_percent" numeric, "p_adjustment_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_material_requirement_line_quantity"("p_material_requirement_line_id" "uuid", "p_requirement_quantity" numeric, "p_waste_percent" numeric, "p_adjustment_reason" "text") IS 'Atomically updates Quantity and Waste for an active Draft Material Requirement line and records an append-only adjustment event.';



CREATE OR REPLACE FUNCTION "public"."update_notification_role_default"("p_role_id" "uuid", "p_event_code" "text", "p_is_enabled" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
    if auth.uid() is null then
        raise exception 'Authentication is required.';
    end if;

    if not public.has_permission('telegram_notifications.manage') then
        raise exception
            'Permission denied: telegram_notifications.manage';
    end if;

    if not exists (
        select 1
        from public.app_roles role
        where role.role_id = p_role_id
          and role.is_active = true
    ) then
        raise exception 'Active app role not found.';
    end if;

    if not exists (
        select 1
        from public.notification_event_types event_type
        where event_type.event_code = p_event_code
          and event_type.event_code in (
              'daily_report_submitted',
              'site_goods_receiving_completed',
              'site_goods_receiving_partial',
              'site_goods_receiving_issue'
          )
    ) then
        raise exception
            'Unsupported Phase 1 notification event.';
    end if;

    insert into public.notification_role_event_defaults (
        role_id,
        event_code,
        is_enabled,
        created_by,
        updated_by
    )
    values (
        p_role_id,
        p_event_code,
        p_is_enabled,
        auth.uid(),
        auth.uid()
    )
    on conflict (role_id, event_code) do update
    set
        is_enabled = excluded.is_enabled,
        updated_at = now(),
        updated_by = auth.uid();
end;
$$;


ALTER FUNCTION "public"."update_notification_role_default"("p_role_id" "uuid", "p_event_code" "text", "p_is_enabled" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_product_atomic"("p_product_id" "uuid", "p_product" "jsonb", "p_uom_conversions" "jsonb" DEFAULT '[]'::"jsonb", "p_coverages" "jsonb" DEFAULT '[]'::"jsonb", "p_attributes" "jsonb" DEFAULT '[]'::"jsonb") RETURNS TABLE("product_id" "uuid", "product_code" "text", "product_name" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
    if not public.can_manage_products_strict() then
        raise exception
            'Only Admin can update Products.';
    end if;

    return query
    select result_row.*
    from public.update_product_atomic_internal(
        p_product_id,
        p_product,
        p_uom_conversions,
        p_coverages,
        p_attributes
    ) as result_row;
end;
$$;


ALTER FUNCTION "public"."update_product_atomic"("p_product_id" "uuid", "p_product" "jsonb", "p_uom_conversions" "jsonb", "p_coverages" "jsonb", "p_attributes" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_product_atomic"("p_product_id" "uuid", "p_product" "jsonb", "p_uom_conversions" "jsonb", "p_coverages" "jsonb", "p_attributes" "jsonb") IS 'Strict Admin-only atomic Product update RPC. Product Code and Product Code Builder identity cannot be changed.';



CREATE OR REPLACE FUNCTION "public"."update_product_atomic_internal"("p_product_id" "uuid", "p_product" "jsonb", "p_uom_conversions" "jsonb" DEFAULT '[]'::"jsonb", "p_coverages" "jsonb" DEFAULT '[]'::"jsonb", "p_attributes" "jsonb" DEFAULT '[]'::"jsonb") RETURNS TABLE("product_id" "uuid", "product_code" "text", "product_name" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
    v_existing_product public.products%rowtype;

    v_product_name text;
    v_product_type text;
    v_category_id uuid;

    v_base_uom_code text;
    v_default_purchase_uom_code text;
    v_default_request_uom_code text;
    v_default_sales_uom_code text;

    v_variant_name text;
    v_variant_description text;

    v_is_stock_item boolean;
    v_is_service_item boolean;
    v_uses_coverage boolean;
    v_default_waste_percent numeric;
    v_is_active boolean;

    v_has_transactions boolean := false;

    v_conversion jsonb;
    v_coverage jsonb;
    v_attribute jsonb;

    v_from_uom_code text;
    v_conversion_factor numeric;
    v_allow_fractional_quantity boolean;
    v_conversion_sort_order integer;
    v_conversion_is_active boolean;

    v_attribute_id uuid;
    v_selected_option_id uuid;
    v_attribute_value_id uuid;
    v_matching_attribute_value_id uuid;

    v_attribute_value_text text;
    v_attribute_value_number numeric;
    v_attribute_value_boolean boolean;
    v_attribute_value_date date;

    v_option_ids jsonb;
    v_normalized_option_ids jsonb;
    v_option_id_text text;

    v_updated_by uuid;
begin
    -- ========================================================
    -- 1. Validate caller
    -- ========================================================

    if not public.can_manage_products_strict() then
        raise exception
            'Only Admin can update Products.';
    end if;


    if p_product_id is null then
        raise exception
            'Product ID is required.';
    end if;


    if p_product is null
       or jsonb_typeof(p_product) <> 'object' then
        raise exception
            'Product data is required.';
    end if;


    if coalesce(
        jsonb_typeof(p_uom_conversions),
        'null'
    ) <> 'array' then
        raise exception
            'UOM Conversions must be supplied as a JSON array.';
    end if;


    if coalesce(
        jsonb_typeof(p_coverages),
        'null'
    ) <> 'array' then
        raise exception
            'Product Coverages must be supplied as a JSON array.';
    end if;


    if coalesce(
        jsonb_typeof(p_attributes),
        'null'
    ) <> 'array' then
        raise exception
            'Product Attributes must be supplied as a JSON array.';
    end if;


    -- Lock Product row during update
    select product_row.*
    into v_existing_product
    from public.products product_row
    where product_row.product_id = p_product_id
      and product_row.is_deleted = false
    for update;


    if not found then
        raise exception
            'Product does not exist or has been deleted.';
    end if;


    v_updated_by := auth.uid();


    -- ========================================================
    -- 2. Product Core values
    -- ========================================================

    v_product_name :=
        nullif(btrim(p_product ->> 'product_name'), '');

    if v_product_name is null then
        raise exception
            'Product Name is required.';
    end if;


    if char_length(v_product_name) > 200 then
        raise exception
            'Product Name cannot exceed 200 characters.';
    end if;


    v_product_type :=
        nullif(btrim(p_product ->> 'product_type'), '');

    if v_product_type not in (
        'Material',
        'Consumable',
        'Tool',
        'Equipment',
        'Service'
    ) then
        raise exception
            'Product Type must be Material, Consumable, Tool, Equipment or Service.';
    end if;


    begin
        v_category_id :=
            nullif(p_product ->> 'category_id', '')::uuid;
    exception
        when invalid_text_representation then
            raise exception
                'Product Category is invalid.';
    end;


    if v_category_id is null then
        raise exception
            'Product Category is required.';
    end if;


    if not exists (
        select 1
        from public.product_categories category_row
        where category_row.category_id = v_category_id
          and category_row.is_active = true
          and category_row.is_deleted = false
    ) then
        raise exception
            'The selected Product Category is inactive or does not exist.';
    end if;


    v_base_uom_code :=
        nullif(btrim(p_product ->> 'base_uom_code'), '');

    if v_base_uom_code is null then
        raise exception
            'Base UOM is required.';
    end if;


    if not exists (
        select 1
        from public.units_of_measure uom_row
        where uom_row.uom_code = v_base_uom_code
          and uom_row.is_active = true
          and uom_row.is_deleted = false
    ) then
        raise exception
            'Base UOM % is inactive or does not exist.',
            v_base_uom_code;
    end if;


    v_default_purchase_uom_code :=
        coalesce(
            nullif(
                btrim(
                    p_product ->> 'default_purchase_uom_code'
                ),
                ''
            ),
            v_base_uom_code
        );


    v_default_request_uom_code :=
        coalesce(
            nullif(
                btrim(
                    p_product ->> 'default_request_uom_code'
                ),
                ''
            ),
            v_base_uom_code
        );


    v_default_sales_uom_code :=
        coalesce(
            nullif(
                btrim(
                    p_product ->> 'default_sales_uom_code'
                ),
                ''
            ),
            v_base_uom_code
        );


    -- ตรวจว่า Default UOM ทุกตัวมีอยู่จริงและ Active
    if not exists (
        select 1
        from public.units_of_measure uom_row
        where uom_row.uom_code =
              v_default_purchase_uom_code
          and uom_row.is_active = true
          and uom_row.is_deleted = false
    ) then
        raise exception
            'Default Purchase UOM % is inactive or does not exist.',
            v_default_purchase_uom_code;
    end if;


    if not exists (
        select 1
        from public.units_of_measure uom_row
        where uom_row.uom_code =
              v_default_request_uom_code
          and uom_row.is_active = true
          and uom_row.is_deleted = false
    ) then
        raise exception
            'Default Request UOM % is inactive or does not exist.',
            v_default_request_uom_code;
    end if;


    if not exists (
        select 1
        from public.units_of_measure uom_row
        where uom_row.uom_code =
              v_default_sales_uom_code
          and uom_row.is_active = true
          and uom_row.is_deleted = false
    ) then
        raise exception
            'Default Sales UOM % is inactive or does not exist.',
            v_default_sales_uom_code;
    end if;


    v_variant_name :=
        nullif(btrim(p_product ->> 'variant_name'), '');

    if v_variant_name is null then
        raise exception
            'Variant Name is required.';
    end if;


    if char_length(v_variant_name) < 2
       or char_length(v_variant_name) > 120 then
        raise exception
            'Variant Name must contain between 2 and 120 characters.';
    end if;


    v_variant_description :=
        nullif(
            btrim(p_product ->> 'variant_description'),
            ''
        );


    if v_variant_description is not null
       and char_length(v_variant_description) > 500 then
        raise exception
            'Variant Description cannot exceed 500 characters.';
    end if;


    v_is_stock_item :=
        coalesce(
            (p_product ->> 'is_stock_item')::boolean,
            v_product_type <> 'Service'
        );


    v_is_service_item :=
        coalesce(
            (p_product ->> 'is_service_item')::boolean,
            v_product_type = 'Service'
        );


    if v_product_type = 'Service' then
        v_is_stock_item := false;
        v_is_service_item := true;
    else
        v_is_service_item := false;
    end if;


    v_uses_coverage :=
        coalesce(
            (p_product ->> 'uses_coverage')::boolean,
            false
        );


    v_default_waste_percent :=
        coalesce(
            nullif(
                p_product ->> 'default_waste_percent',
                ''
            )::numeric,
            0
        );


    if v_default_waste_percent < 0
       or v_default_waste_percent > 100 then
        raise exception
            'Default Waste Percent must be between 0 and 100.';
    end if;


    v_is_active :=
        coalesce(
            (p_product ->> 'is_active')::boolean,
            v_existing_product.is_active
        );


    -- ========================================================
    -- 3. Check whether Base UOM is locked
    -- ========================================================

    v_has_transactions :=
        exists (
            select 1
            from public.purchase_order_lines row_item
            where row_item.product_id = p_product_id
        )
        or exists (
            select 1
            from public.quotation_lines row_item
            where row_item.product_id = p_product_id
        )
        or exists (
            select 1
            from public.quotation_revision_lines row_item
            where row_item.product_id = p_product_id
        )
        or exists (
            select 1
            from public.stock_request_items row_item
            where row_item.product_id = p_product_id
        )
        or exists (
            select 1
            from public.supplier_delivery_items row_item
            where row_item.product_id = p_product_id
        )
        or exists (
            select 1
            from public.stock_lots row_item
            where row_item.product_id = p_product_id
        )
        or exists (
            select 1
            from public.stock_movements row_item
            where row_item.product_id = p_product_id
        )
        or exists (
            select 1
            from public.supplier_replacement_claim_items row_item
            where row_item.product_id = p_product_id
        )
        or exists (
            select 1
            from public.supplier_replacement_receipt_items row_item
            where row_item.product_id = p_product_id
        );


    if v_existing_product.base_uom_code
       is distinct from v_base_uom_code
       and v_has_transactions then
        raise exception
            'Base UOM cannot be changed because this Product has already been used in a transaction.';
    end if;


    -- ========================================================
    -- 4. Update Product Core
    --
    -- Temporarily set all Default UOMs to Base UOM.
    -- This allows Conversion rows to be rebuilt safely.
    --
    -- Product Code Identity columns are intentionally omitted.
    -- ========================================================

    update public.products
    set
        product_name = v_product_name,
        category_id = v_category_id,
        description = nullif(
            btrim(p_product ->> 'description'),
            ''
        ),

        is_stock_item = v_is_stock_item,
        is_service_item = v_is_service_item,

        product_type = v_product_type,
        search_keywords = nullif(
            btrim(p_product ->> 'search_keywords'),
            ''
        ),

        base_uom_code = v_base_uom_code,
        unit = v_base_uom_code,

        default_purchase_uom_code = v_base_uom_code,
        default_request_uom_code = v_base_uom_code,
        default_sales_uom_code = v_base_uom_code,

        uses_coverage = v_uses_coverage,
        default_waste_percent =
            v_default_waste_percent,

        variant_name = v_variant_name,
        variant_description =
            v_variant_description,

        is_active = v_is_active,

        updated_at = now(),
        updated_by = v_updated_by
    where products.product_id = p_product_id;


    -- ========================================================
    -- 5. Validate submitted UOM Conversions
    -- ========================================================

    if exists (
        select 1
        from (
            select
                nullif(
                    btrim(conversion_item ->> 'from_uom_code'),
                    ''
                ) as from_uom_code,
                count(*) as row_count
            from jsonb_array_elements(p_uom_conversions)
                as submitted_conversion(conversion_item)
            group by
                nullif(
                    btrim(conversion_item ->> 'from_uom_code'),
                    ''
                )
        ) duplicate_check
        where duplicate_check.from_uom_code is not null
          and duplicate_check.row_count > 1
    ) then
        raise exception
            'Each Transaction UOM may appear only once in UOM Conversions.';
    end if;


    for v_conversion in
        select value
        from jsonb_array_elements(p_uom_conversions)
    loop
        v_from_uom_code :=
            nullif(
                btrim(
                    v_conversion ->> 'from_uom_code'
                ),
                ''
            );


        if v_from_uom_code is null then
            raise exception
                'Transaction UOM is required for every conversion.';
        end if;


        if v_from_uom_code = v_base_uom_code then
            raise exception
                'A conversion is not required for Base UOM %.',
                v_base_uom_code;
        end if;


        if not exists (
            select 1
            from public.units_of_measure uom_row
            where uom_row.uom_code =
                  v_from_uom_code
              and uom_row.is_active = true
              and uom_row.is_deleted = false
        ) then
            raise exception
                'Transaction UOM % is inactive or does not exist.',
                v_from_uom_code;
        end if;


        begin
            v_conversion_factor :=
                nullif(
                    v_conversion ->> 'conversion_factor',
                    ''
                )::numeric;
        exception
            when invalid_text_representation then
                raise exception
                    'Conversion Factor for UOM % is invalid.',
                    v_from_uom_code;
        end;


        if v_conversion_factor is null
           or v_conversion_factor <= 0 then
            raise exception
                'Conversion Factor for UOM % must be greater than zero.',
                v_from_uom_code;
        end if;


        begin
            v_conversion_sort_order :=
                coalesce(
                    nullif(
                        v_conversion ->> 'sort_order',
                        ''
                    )::integer,
                    10
                );
        exception
            when invalid_text_representation then
                raise exception
                    'Sort Order for UOM % is invalid.',
                    v_from_uom_code;
        end;


        v_allow_fractional_quantity :=
            coalesce(
                (
                    v_conversion ->>
                    'allow_fractional_quantity'
                )::boolean,
                false
            );


        v_conversion_is_active :=
            coalesce(
                (
                    v_conversion ->>
                    'is_active'
                )::boolean,
                true
            );
    end loop;


    -- ========================================================
    -- 6. Reconcile UOM Conversions
    --
    -- Keep unchanged rows as-is.
    -- Archive only rows that were removed or changed.
    -- Insert only rows that are new or changed.
    -- ========================================================

    update public.product_uom_conversions as conversion_row
    set
        is_active = false,
        is_deleted = true,
        deleted_at = now(),
        updated_at = now(),
        updated_by = v_updated_by
    where conversion_row.product_id = p_product_id
      and conversion_row.is_deleted = false
      and not exists (
          select 1
          from jsonb_array_elements(p_uom_conversions)
              as submitted_conversion(conversion_item)
          where nullif(
                    btrim(
                        conversion_item ->> 'from_uom_code'
                    ),
                    ''
                ) = conversion_row.from_uom_code
            and conversion_row.to_uom_code =
                v_base_uom_code
            and conversion_row.conversion_factor =
                nullif(
                    conversion_item ->> 'conversion_factor',
                    ''
                )::numeric
            and conversion_row.allow_fractional_quantity =
                coalesce(
                    (
                        conversion_item ->>
                        'allow_fractional_quantity'
                    )::boolean,
                    false
                )
            and conversion_row.sort_order =
                coalesce(
                    nullif(
                        conversion_item ->> 'sort_order',
                        ''
                    )::integer,
                    10
                )
            and conversion_row.is_active =
                coalesce(
                    (
                        conversion_item ->>
                        'is_active'
                    )::boolean,
                    true
                )
      );


    for v_conversion in
        select value
        from jsonb_array_elements(p_uom_conversions)
    loop
        v_from_uom_code :=
            nullif(
                btrim(
                    v_conversion ->> 'from_uom_code'
                ),
                ''
            );

        v_conversion_factor :=
            nullif(
                v_conversion ->> 'conversion_factor',
                ''
            )::numeric;

        v_allow_fractional_quantity :=
            coalesce(
                (
                    v_conversion ->>
                    'allow_fractional_quantity'
                )::boolean,
                false
            );

        v_conversion_sort_order :=
            coalesce(
                nullif(
                    v_conversion ->> 'sort_order',
                    ''
                )::integer,
                10
            );

        v_conversion_is_active :=
            coalesce(
                (
                    v_conversion ->>
                    'is_active'
                )::boolean,
                true
            );


        if not exists (
            select 1
            from public.product_uom_conversions conversion_row
            where conversion_row.product_id = p_product_id
              and conversion_row.from_uom_code =
                  v_from_uom_code
              and conversion_row.to_uom_code =
                  v_base_uom_code
              and conversion_row.conversion_factor =
                  v_conversion_factor
              and conversion_row.allow_fractional_quantity =
                  v_allow_fractional_quantity
              and conversion_row.sort_order =
                  v_conversion_sort_order
              and conversion_row.is_active =
                  v_conversion_is_active
              and conversion_row.is_deleted = false
        ) then
            insert into public.product_uom_conversions (
                product_id,
                from_uom_code,
                to_uom_code,
                conversion_factor,
                allow_fractional_quantity,
                sort_order,
                is_active,
                is_deleted,
                created_by,
                updated_by
            )
            values (
                p_product_id,
                v_from_uom_code,
                v_base_uom_code,
                v_conversion_factor,
                v_allow_fractional_quantity,
                v_conversion_sort_order,
                v_conversion_is_active,
                false,
                v_updated_by,
                v_updated_by
            );
        end if;
    end loop;


    -- ========================================================
    -- 7. Apply actual Default UOM values
    --
    -- Product Trigger validates that every non-base default
    -- has an active Conversion.
    -- ========================================================

    update public.products
    set
        default_purchase_uom_code =
            v_default_purchase_uom_code,

        default_request_uom_code =
            v_default_request_uom_code,

        default_sales_uom_code =
            v_default_sales_uom_code,

        updated_at = now(),
        updated_by = v_updated_by
    where products.product_id = p_product_id;


    -- ========================================================
    -- 8. Validate submitted Coverage rows
    -- ========================================================

    if jsonb_array_length(p_coverages) > 0
       and v_uses_coverage = false then
        raise exception
            'Uses Coverage must be enabled before Coverage rows can be added.';
    end if;


    for v_coverage in
        select value
        from jsonb_array_elements(p_coverages)
    loop
        if nullif(
            btrim(v_coverage ->> 'source_uom_code'),
            ''
        ) is null then
            raise exception
                'Coverage Source UOM is required.';
        end if;


        if not exists (
            select 1
            from public.units_of_measure uom_row
            where uom_row.uom_code = nullif(
                      btrim(
                          v_coverage ->>
                          'source_uom_code'
                      ),
                      ''
                  )
              and uom_row.is_active = true
              and uom_row.is_deleted = false
        ) then
            raise exception
                'Coverage Source UOM % is inactive or does not exist.',
                nullif(
                    btrim(
                        v_coverage ->>
                        'source_uom_code'
                    ),
                    ''
                );
        end if;


        if nullif(
            btrim(v_coverage ->> 'coverage_uom_code'),
            ''
        ) is null then
            raise exception
                'Coverage UOM is required.';
        end if;


        if not exists (
            select 1
            from public.units_of_measure uom_row
            where uom_row.uom_code = nullif(
                      btrim(
                          v_coverage ->>
                          'coverage_uom_code'
                      ),
                      ''
                  )
              and uom_row.is_active = true
              and uom_row.is_deleted = false
        ) then
            raise exception
                'Coverage UOM % is inactive or does not exist.',
                nullif(
                    btrim(
                        v_coverage ->>
                        'coverage_uom_code'
                    ),
                    ''
                );
        end if;


        if coalesce(
            nullif(
                v_coverage ->> 'source_quantity',
                ''
            )::numeric,
            1
        ) <= 0 then
            raise exception
                'Coverage Source Quantity must be greater than zero.';
        end if;


        if nullif(
            v_coverage ->> 'coverage_quantity',
            ''
        )::numeric is null
        or nullif(
            v_coverage ->> 'coverage_quantity',
            ''
        )::numeric <= 0 then
            raise exception
                'Coverage Quantity must be greater than zero.';
        end if;


        if nullif(
            v_coverage ->> 'minimum_coverage',
            ''
        )::numeric is not null
        and nullif(
            v_coverage ->> 'minimum_coverage',
            ''
        )::numeric < 0 then
            raise exception
                'Minimum Coverage cannot be negative.';
        end if;


        if nullif(
            v_coverage ->> 'maximum_coverage',
            ''
        )::numeric is not null
        and nullif(
            v_coverage ->> 'maximum_coverage',
            ''
        )::numeric < 0 then
            raise exception
                'Maximum Coverage cannot be negative.';
        end if;


        if nullif(
            v_coverage ->> 'minimum_coverage',
            ''
        )::numeric is not null
        and nullif(
            v_coverage ->> 'maximum_coverage',
            ''
        )::numeric is not null
        and nullif(
            v_coverage ->> 'minimum_coverage',
            ''
        )::numeric > nullif(
            v_coverage ->> 'maximum_coverage',
            ''
        )::numeric then
            raise exception
                'Minimum Coverage cannot be greater than Maximum Coverage.';
        end if;
    end loop;


    -- ========================================================
    -- 9. Reconcile Coverage rows
    --
    -- Keep unchanged rows as-is.
    -- Archive only rows that were removed or changed.
    -- Insert only rows that are new or changed.
    -- ========================================================

    update public.product_coverages as coverage_row
    set
        is_active = false,
        is_deleted = true,
        deleted_at = now(),
        updated_at = now(),
        updated_by = v_updated_by
    where coverage_row.product_id = p_product_id
      and coverage_row.is_deleted = false
      and not exists (
          select 1
          from jsonb_array_elements(p_coverages)
              as submitted_coverage(coverage_item)
          where coverage_row.source_quantity =
                coalesce(
                    nullif(
                        coverage_item ->>
                        'source_quantity',
                        ''
                    )::numeric,
                    1
                )
            and coverage_row.source_uom_code =
                nullif(
                    btrim(
                        coverage_item ->>
                        'source_uom_code'
                    ),
                    ''
                )
            and coverage_row.coverage_quantity =
                nullif(
                    coverage_item ->>
                    'coverage_quantity',
                    ''
                )::numeric
            and coverage_row.coverage_uom_code =
                nullif(
                    btrim(
                        coverage_item ->>
                        'coverage_uom_code'
                    ),
                    ''
                )
            and coverage_row.minimum_coverage
                is not distinct from
                nullif(
                    coverage_item ->>
                    'minimum_coverage',
                    ''
                )::numeric
            and coverage_row.maximum_coverage
                is not distinct from
                nullif(
                    coverage_item ->>
                    'maximum_coverage',
                    ''
                )::numeric
            and coverage_row.is_estimate =
                coalesce(
                    (
                        coverage_item ->>
                        'is_estimate'
                    )::boolean,
                    true
                )
            and coverage_row.is_default =
                coalesce(
                    (
                        coverage_item ->>
                        'is_default'
                    )::boolean,
                    false
                )
            and coverage_row.notes
                is not distinct from
                nullif(
                    btrim(
                        coverage_item ->> 'notes'
                    ),
                    ''
                )
            and coverage_row.sort_order =
                coalesce(
                    nullif(
                        coverage_item ->>
                        'sort_order',
                        ''
                    )::integer,
                    10
                )
            and coverage_row.is_active =
                coalesce(
                    (
                        coverage_item ->>
                        'is_active'
                    )::boolean,
                    true
                )
      );


    for v_coverage in
        select value
        from jsonb_array_elements(p_coverages)
    loop
        if not exists (
            select 1
            from public.product_coverages coverage_row
            where coverage_row.product_id = p_product_id
              and coverage_row.is_deleted = false
              and coverage_row.source_quantity =
                  coalesce(
                      nullif(
                          v_coverage ->>
                          'source_quantity',
                          ''
                      )::numeric,
                      1
                  )
              and coverage_row.source_uom_code =
                  nullif(
                      btrim(
                          v_coverage ->>
                          'source_uom_code'
                      ),
                      ''
                  )
              and coverage_row.coverage_quantity =
                  nullif(
                      v_coverage ->>
                      'coverage_quantity',
                      ''
                  )::numeric
              and coverage_row.coverage_uom_code =
                  nullif(
                      btrim(
                          v_coverage ->>
                          'coverage_uom_code'
                      ),
                      ''
                  )
              and coverage_row.minimum_coverage
                  is not distinct from
                  nullif(
                      v_coverage ->>
                      'minimum_coverage',
                      ''
                  )::numeric
              and coverage_row.maximum_coverage
                  is not distinct from
                  nullif(
                      v_coverage ->>
                      'maximum_coverage',
                      ''
                  )::numeric
              and coverage_row.is_estimate =
                  coalesce(
                      (
                          v_coverage ->>
                          'is_estimate'
                      )::boolean,
                      true
                  )
              and coverage_row.is_default =
                  coalesce(
                      (
                          v_coverage ->>
                          'is_default'
                      )::boolean,
                      false
                  )
              and coverage_row.notes
                  is not distinct from
                  nullif(
                      btrim(
                          v_coverage ->> 'notes'
                      ),
                      ''
                  )
              and coverage_row.sort_order =
                  coalesce(
                      nullif(
                          v_coverage ->>
                          'sort_order',
                          ''
                      )::integer,
                      10
                  )
              and coverage_row.is_active =
                  coalesce(
                      (
                          v_coverage ->>
                          'is_active'
                      )::boolean,
                      true
                  )
        ) then
            insert into public.product_coverages (
                product_id,
                source_quantity,
                source_uom_code,
                coverage_quantity,
                coverage_uom_code,
                minimum_coverage,
                maximum_coverage,
                is_estimate,
                is_default,
                notes,
                sort_order,
                is_active,
                is_deleted,
                created_by,
                updated_by
            )
            values (
                p_product_id,

                coalesce(
                    nullif(
                        v_coverage ->>
                        'source_quantity',
                        ''
                    )::numeric,
                    1
                ),

                nullif(
                    btrim(
                        v_coverage ->>
                        'source_uom_code'
                    ),
                    ''
                ),

                nullif(
                    v_coverage ->>
                    'coverage_quantity',
                    ''
                )::numeric,

                nullif(
                    btrim(
                        v_coverage ->>
                        'coverage_uom_code'
                    ),
                    ''
                ),

                nullif(
                    v_coverage ->>
                    'minimum_coverage',
                    ''
                )::numeric,

                nullif(
                    v_coverage ->>
                    'maximum_coverage',
                    ''
                )::numeric,

                coalesce(
                    (
                        v_coverage ->>
                        'is_estimate'
                    )::boolean,
                    true
                ),

                coalesce(
                    (
                        v_coverage ->>
                        'is_default'
                    )::boolean,
                    false
                ),

                nullif(
                    btrim(
                        v_coverage ->> 'notes'
                    ),
                    ''
                ),

                coalesce(
                    nullif(
                        v_coverage ->>
                        'sort_order',
                        ''
                    )::integer,
                    10
                ),

                coalesce(
                    (
                        v_coverage ->>
                        'is_active'
                    )::boolean,
                    true
                ),

                false,
                v_updated_by,
                v_updated_by
            );
        end if;
    end loop;


    -- ========================================================
    -- 10. Validate and apply Attribute Value differences
    --
    -- Existing Attribute rows are preserved when every scalar
    -- value and the complete option set are unchanged.
    -- Changed rows are archived and replaced. Attributes omitted
    -- from the submitted payload are archived after this loop.
    -- ========================================================

    if exists (
        select 1
        from (
            select
                nullif(attribute_item ->> 'attribute_id', '')::uuid
                    as attribute_id,
                count(*) as item_count
            from jsonb_array_elements(p_attributes)
                as submitted(attribute_item)
            group by
                nullif(attribute_item ->> 'attribute_id', '')::uuid
            having count(*) > 1
        ) duplicate_rows
    ) then
        raise exception
            'Each Product Attribute may be submitted only once.';
    end if;


    for v_attribute in
        select value
        from jsonb_array_elements(p_attributes)
    loop
        begin
            v_attribute_id :=
                nullif(
                    v_attribute ->>
                    'attribute_id',
                    ''
                )::uuid;
        exception
            when invalid_text_representation then
                raise exception
                    'A Product Attribute ID is invalid.';
        end;


        if v_attribute_id is null then
            raise exception
                'Attribute ID is required.';
        end if;


        -- Validate against the effective Attribute set, not only direct
        -- mappings on the selected Category. This supports inherited
        -- Attributes from parent Categories and respects overrides/hiding.
        if not exists (
            select 1
            from public.get_effective_product_category_attributes(
                v_category_id
            ) as effective_attribute
            where effective_attribute.attribute_id =
                  v_attribute_id
        ) then
            raise exception
                'Attribute % is not available for the selected Product Category.',
                v_attribute_id;
        end if;


        begin
            v_selected_option_id :=
                nullif(
                    v_attribute ->>
                    'selected_option_id',
                    ''
                )::uuid;
        exception
            when invalid_text_representation then
                raise exception
                    'A selected Attribute Option ID is invalid.';
        end;


        if v_selected_option_id is not null
           and not exists (
               select 1
               from public.product_attribute_options option_row
               where option_row.attribute_option_id =
                     v_selected_option_id
                 and option_row.attribute_id =
                     v_attribute_id
                 and option_row.is_active = true
                 and option_row.is_deleted = false
           ) then
            raise exception
                'Selected Option is invalid for Attribute %.',
                v_attribute_id;
        end if;


        v_attribute_value_text :=
            nullif(
                btrim(
                    v_attribute ->>
                    'value_text'
                ),
                ''
            );


        begin
            v_attribute_value_number :=
                nullif(
                    v_attribute ->>
                    'value_number',
                    ''
                )::numeric;
        exception
            when invalid_text_representation then
                raise exception
                    'The numeric value for Attribute % is invalid.',
                    v_attribute_id;
        end;


        begin
            v_attribute_value_boolean :=
                case
                    when v_attribute ? 'value_boolean'
                         and v_attribute ->> 'value_boolean'
                             is not null
                    then
                        (
                            v_attribute ->>
                            'value_boolean'
                        )::boolean
                    else null
                end;
        exception
            when invalid_text_representation then
                raise exception
                    'The boolean value for Attribute % is invalid.',
                    v_attribute_id;
        end;


        begin
            v_attribute_value_date :=
                nullif(
                    v_attribute ->>
                    'value_date',
                    ''
                )::date;
        exception
            when invalid_text_representation
                 or datetime_field_overflow then
                raise exception
                    'The date value for Attribute % is invalid.',
                    v_attribute_id;
        end;


        v_option_ids :=
            coalesce(
                v_attribute -> 'option_ids',
                '[]'::jsonb
            );


        if jsonb_typeof(v_option_ids) <> 'array' then
            raise exception
                'Attribute option_ids must be a JSON array.';
        end if;


        for v_option_id_text in
            select jsonb_array_elements_text(
                v_option_ids
            )
        loop
            begin
                perform v_option_id_text::uuid;
            exception
                when invalid_text_representation then
                    raise exception
                        'Attribute Option % is not a valid UUID.',
                        v_option_id_text;
            end;


            if not exists (
                select 1
                from public.product_attribute_options option_row
                where option_row.attribute_option_id =
                      v_option_id_text::uuid
                  and option_row.attribute_id =
                      v_attribute_id
                  and option_row.is_active = true
                  and option_row.is_deleted = false
            ) then
                raise exception
                    'Attribute Option % is invalid for Attribute %.',
                    v_option_id_text,
                    v_attribute_id;
            end if;
        end loop;


        select coalesce(
            jsonb_agg(
                to_jsonb(normalized.option_id_text)
                order by normalized.option_id_text
            ),
            '[]'::jsonb
        )
        into v_normalized_option_ids
        from (
            select distinct option_id_text
            from jsonb_array_elements_text(v_option_ids)
                as submitted_options(option_id_text)
        ) normalized;


        v_matching_attribute_value_id := null;

        select attribute_value_row.product_attribute_value_id
        into v_matching_attribute_value_id
        from public.product_attribute_values attribute_value_row
        where attribute_value_row.product_id = p_product_id
          and attribute_value_row.attribute_id = v_attribute_id
          and attribute_value_row.is_deleted = false
          and attribute_value_row.value_text
                is not distinct from v_attribute_value_text
          and attribute_value_row.value_number
                is not distinct from v_attribute_value_number
          and attribute_value_row.value_boolean
                is not distinct from v_attribute_value_boolean
          and attribute_value_row.value_date
                is not distinct from v_attribute_value_date
          and attribute_value_row.selected_option_id
                is not distinct from v_selected_option_id
          and coalesce(
                (
                    select jsonb_agg(
                        to_jsonb(
                            option_link.attribute_option_id::text
                        )
                        order by
                            option_link.attribute_option_id::text
                    )
                    from public.product_attribute_value_options option_link
                    where option_link.product_attribute_value_id =
                          attribute_value_row.product_attribute_value_id
                ),
                '[]'::jsonb
              ) = v_normalized_option_ids
        order by attribute_value_row.created_at desc
        limit 1;


        if v_matching_attribute_value_id is not null then
            -- Preserve the unchanged active row. Archive any accidental
            -- duplicate active rows for the same Product Attribute.
            update public.product_attribute_values attribute_value_row
            set
                is_deleted = true,
                deleted_at = now(),
                updated_at = now(),
                updated_by = v_updated_by
            where attribute_value_row.product_id = p_product_id
              and attribute_value_row.attribute_id = v_attribute_id
              and attribute_value_row.is_deleted = false
              and attribute_value_row.product_attribute_value_id <>
                  v_matching_attribute_value_id;
        else
            -- The submitted value differs from the active value.
            update public.product_attribute_values attribute_value_row
            set
                is_deleted = true,
                deleted_at = now(),
                updated_at = now(),
                updated_by = v_updated_by
            where attribute_value_row.product_id = p_product_id
              and attribute_value_row.attribute_id = v_attribute_id
              and attribute_value_row.is_deleted = false;


            insert into public.product_attribute_values (
                product_id,
                attribute_id,
                value_text,
                value_number,
                value_boolean,
                value_date,
                selected_option_id,
                is_deleted,
                created_by,
                updated_by
            )
            values (
                p_product_id,
                v_attribute_id,
                v_attribute_value_text,
                v_attribute_value_number,
                v_attribute_value_boolean,
                v_attribute_value_date,
                v_selected_option_id,
                false,
                v_updated_by,
                v_updated_by
            )
            returning product_attribute_value_id
            into v_attribute_value_id;


            for v_option_id_text in
                select distinct option_id_text
                from jsonb_array_elements_text(v_option_ids)
                    as submitted_options(option_id_text)
            loop
                insert into public.product_attribute_value_options (
                    product_attribute_value_id,
                    attribute_option_id,
                    created_by
                )
                values (
                    v_attribute_value_id,
                    v_option_id_text::uuid,
                    v_updated_by
                );
            end loop;
        end if;
    end loop;


    -- Archive active Attribute values that were removed from the form.
    update public.product_attribute_values attribute_value_row
    set
        is_deleted = true,
        deleted_at = now(),
        updated_at = now(),
        updated_by = v_updated_by
    where attribute_value_row.product_id = p_product_id
      and attribute_value_row.is_deleted = false
      and not exists (
          select 1
          from jsonb_array_elements(p_attributes)
              as submitted(attribute_item)
          where nullif(
                    submitted.attribute_item ->>
                    'attribute_id',
                    ''
                )::uuid = attribute_value_row.attribute_id
      );


    -- ========================================================
    -- 12. Return updated Product
    -- ========================================================

    return query
    select
        product_row.product_id,
        product_row.product_code,
        product_row.product_name
    from public.products product_row
    where product_row.product_id =
          p_product_id;

end;
$$;


ALTER FUNCTION "public"."update_product_atomic_internal"("p_product_id" "uuid", "p_product" "jsonb", "p_uom_conversions" "jsonb", "p_coverages" "jsonb", "p_attributes" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_product_atomic_internal"("p_product_id" "uuid", "p_product" "jsonb", "p_uom_conversions" "jsonb", "p_coverages" "jsonb", "p_attributes" "jsonb") IS 'Internal atomic Product update. Product Code identity is immutable. Synchronises Product Core, UOM conversions, coverage and dynamic attributes.';



CREATE OR REPLACE FUNCTION "public"."update_role_permissions_atomic"("p_role_id" "uuid", "p_changes" "jsonb", "p_reason" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    v_actor_id uuid;
    v_role_code text;

    v_change jsonb;
    v_permission_id uuid;
    v_permission_code text;
    v_is_allowed boolean;
    v_old_allowed boolean;
begin
    perform public._assert_access_control_manager();

    v_actor_id := auth.uid();

    if p_role_id is null then
        raise exception 'Role is required.';
    end if;

    if p_changes is null
       or jsonb_typeof(p_changes) <> 'array'
    then
        raise exception
            'Role permission changes must be a JSON array.';
    end if;

    select r.role_code
    into v_role_code
    from public.app_roles r
    where r.role_id = p_role_id
      and r.is_active = true
    for update;

    if v_role_code is null then
        raise exception 'Active role was not found.';
    end if;

    for v_change in
        select value
        from jsonb_array_elements(p_changes)
    loop
        v_permission_id :=
            nullif(
                v_change ->> 'permission_id',
                ''
            )::uuid;

        if v_permission_id is null then
            raise exception
                'Each change requires permission_id.';
        end if;

        if not (v_change ? 'is_allowed') then
            raise exception
                'Each change requires is_allowed.';
        end if;

        v_is_allowed :=
            (v_change ->> 'is_allowed')::boolean;

        select
            p.permission_code,
            rp.is_allowed
        into
            v_permission_code,
            v_old_allowed
        from public.app_permissions p
        left join public.app_role_permissions rp
          on rp.role_id = p_role_id
         and rp.permission_id = p.permission_id
        where p.permission_id = v_permission_id
          and p.is_active = true;

        if v_permission_code is null then
            raise exception
                'Active permission % was not found.',
                v_permission_id;
        end if;

        if v_role_code = 'admin'
           and v_permission_code = 'permissions.manage'
           and v_is_allowed = false
        then
            raise exception
                'Administrator role must retain permissions.manage.';
        end if;

        insert into public.app_role_permissions (
            role_id,
            permission_id,
            is_allowed,
            created_by,
            updated_by
        )
        values (
            p_role_id,
            v_permission_id,
            v_is_allowed,
            v_actor_id,
            v_actor_id
        )
        on conflict (role_id, permission_id)
        do update
        set
            is_allowed = excluded.is_allowed,
            updated_by = v_actor_id;

        if v_old_allowed is distinct from v_is_allowed then
            insert into public.access_control_audit_log (
                target_role_id,
                permission_id,
                permission_code,
                change_type,
                old_value,
                new_value,
                reason,
                changed_by
            )
            values (
                p_role_id,
                v_permission_id,
                v_permission_code,
                case
                    when v_is_allowed
                        then 'Role Permission Allowed'
                    else 'Role Permission Denied'
                end,
                jsonb_build_object(
                    'is_allowed',
                    v_old_allowed
                ),
                jsonb_build_object(
                    'is_allowed',
                    v_is_allowed
                ),
                nullif(btrim(p_reason), ''),
                v_actor_id
            );
        end if;
    end loop;

    if public._active_permission_admin_count() < 1 then
        raise exception
            'At least one active permission administrator must remain.';
    end if;

    return p_role_id;
end;
$$;


ALTER FUNCTION "public"."update_role_permissions_atomic"("p_role_id" "uuid", "p_changes" "jsonb", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_user_permission_overrides_atomic"("p_auth_user_id" "uuid", "p_changes" "jsonb", "p_reason" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    v_actor_id uuid;

    v_change jsonb;
    v_permission_id uuid;
    v_permission_code text;
    v_mode text;

    v_old_allowed boolean;
    v_old_active boolean;

    v_new_allowed boolean;
begin
    if auth.uid() is null then
        raise exception 'Authentication required.';
    end if;

    if not (
        public.has_permission(
            'users.manage_permission_overrides'
        )
        or public.can_manage_permissions()
    ) then
        raise exception
            'Permission denied: users.manage_permission_overrides';
    end if;

    v_actor_id := auth.uid();

    if p_auth_user_id is null then
        raise exception 'Target user is required.';
    end if;

    if p_changes is null
       or jsonb_typeof(p_changes) <> 'array'
    then
        raise exception
            'User override changes must be a JSON array.';
    end if;

    if not exists (
        select 1
        from public.app_users au
        where au.auth_user_id = p_auth_user_id
        for update
    ) then
        raise exception
            'Application user was not found.';
    end if;

    for v_change in
        select value
        from jsonb_array_elements(p_changes)
    loop
        v_permission_id :=
            nullif(
                v_change ->> 'permission_id',
                ''
            )::uuid;

        v_mode :=
            initcap(
                lower(
                    btrim(
                        coalesce(
                            v_change ->> 'mode',
                            ''
                        )
                    )
                )
            );

        if v_permission_id is null then
            raise exception
                'Each change requires permission_id.';
        end if;

        if v_mode not in (
            'Default',
            'Allow',
            'Deny'
        ) then
            raise exception
                'Override mode must be Default, Allow or Deny.';
        end if;

        select p.permission_code
        into v_permission_code
        from public.app_permissions p
        where p.permission_id = v_permission_id
          and p.is_active = true;

        if v_permission_code is null then
            raise exception
                'Active permission % was not found.',
                v_permission_id;
        end if;

        select
            upo.is_allowed,
            upo.is_active
        into
            v_old_allowed,
            v_old_active
        from public.app_user_permission_overrides upo
        where upo.auth_user_id = p_auth_user_id
          and upo.permission_id = v_permission_id;

        if v_mode = 'Default' then
            update public.app_user_permission_overrides
            set
                is_active = false,
                reason = nullif(
                    btrim(p_reason),
                    ''
                ),
                updated_by = v_actor_id
            where auth_user_id = p_auth_user_id
              and permission_id = v_permission_id;

            if found
               and coalesce(v_old_active, false) = true
            then
                insert into public.access_control_audit_log (
                    target_auth_user_id,
                    permission_id,
                    permission_code,
                    change_type,
                    old_value,
                    new_value,
                    reason,
                    changed_by
                )
                values (
                    p_auth_user_id,
                    v_permission_id,
                    v_permission_code,
                    'User Override Reset',
                    jsonb_build_object(
                        'is_allowed',
                        v_old_allowed,
                        'is_active',
                        v_old_active
                    ),
                    jsonb_build_object(
                        'mode',
                        'Default',
                        'is_active',
                        false
                    ),
                    nullif(btrim(p_reason), ''),
                    v_actor_id
                );
            end if;

        else
            v_new_allowed :=
                (v_mode = 'Allow');

            if p_auth_user_id = v_actor_id
               and v_permission_code = 'permissions.manage'
               and v_new_allowed = false
            then
                raise exception
                    'You cannot deny your own permissions.manage permission.';
            end if;

            insert into public.app_user_permission_overrides (
                auth_user_id,
                permission_id,
                is_allowed,
                reason,
                is_active,
                created_by,
                updated_by
            )
            values (
                p_auth_user_id,
                v_permission_id,
                v_new_allowed,
                nullif(btrim(p_reason), ''),
                true,
                v_actor_id,
                v_actor_id
            )
            on conflict (
                auth_user_id,
                permission_id
            )
            do update
            set
                is_allowed =
                    excluded.is_allowed,
                reason =
                    excluded.reason,
                is_active = true,
                updated_by = v_actor_id;

            if v_old_allowed is distinct from v_new_allowed
               or coalesce(v_old_active, false) = false
            then
                insert into public.access_control_audit_log (
                    target_auth_user_id,
                    permission_id,
                    permission_code,
                    change_type,
                    old_value,
                    new_value,
                    reason,
                    changed_by
                )
                values (
                    p_auth_user_id,
                    v_permission_id,
                    v_permission_code,
                    case
                        when v_new_allowed
                            then 'User Override Allowed'
                        else 'User Override Denied'
                    end,
                    jsonb_build_object(
                        'is_allowed',
                        v_old_allowed,
                        'is_active',
                        v_old_active
                    ),
                    jsonb_build_object(
                        'is_allowed',
                        v_new_allowed,
                        'is_active',
                        true
                    ),
                    nullif(btrim(p_reason), ''),
                    v_actor_id
                );
            end if;
        end if;
    end loop;

    if public._active_permission_admin_count() < 1 then
        raise exception
            'At least one active permission administrator must remain.';
    end if;

    return p_auth_user_id;
end;
$$;


ALTER FUNCTION "public"."update_user_permission_overrides_atomic"("p_auth_user_id" "uuid", "p_changes" "jsonb", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_user_telegram_channel"("p_auth_user_id" "uuid", "p_telegram_chat_id" "text", "p_destination_name" "text" DEFAULT NULL::"text", "p_is_enabled" boolean DEFAULT true, "p_connection_notes" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
    v_actor_id uuid := auth.uid();
    v_destination_id uuid;
    v_current_channel_id uuid;
    v_display_name text;
begin
    if v_actor_id is null then
        raise exception 'Authentication is required.';
    end if;

    if not public.has_permission('telegram_notifications.manage') then
        raise exception
            'Permission denied: telegram_notifications.manage';
    end if;

    if p_auth_user_id is null then
        raise exception 'App user is required.';
    end if;

    if nullif(trim(p_telegram_chat_id), '') is null then
        raise exception 'Telegram Chat ID is required.';
    end if;

    select coalesce(
        employee.display_name,
        nullif(concat_ws(' ', employee.first_name, employee.last_name), ''),
        app_user.display_name,
        app_user.email
    )
    into v_display_name
    from public.app_users app_user
    left join public.employees employee
      on employee.auth_user_id = app_user.auth_user_id
     and employee.is_deleted = false
    where app_user.auth_user_id = p_auth_user_id;

    if not found then
        raise exception 'App user not found.';
    end if;

    select destination.notification_destination_id
    into v_destination_id
    from public.notification_destinations destination
    where destination.channel_type = 'Telegram'
      and destination.telegram_chat_id = trim(p_telegram_chat_id)
      and destination.is_deleted = false
    order by destination.created_at
    limit 1;

    if v_destination_id is not null
       and exists (
           select 1
           from public.notification_user_channels channel
           where channel.notification_destination_id = v_destination_id
             and channel.auth_user_id <> p_auth_user_id
             and channel.is_deleted = false
       ) then
        raise exception
            'This Telegram Chat ID is already linked to another REDS user.';
    end if;

    if v_destination_id is null then
        insert into public.notification_destinations (
            destination_name,
            channel_type,
            telegram_chat_id,
            destination_scope,
            metadata,
            is_active,
            is_deleted,
            created_by,
            updated_by
        )
        values (
            coalesce(
                nullif(trim(p_destination_name), ''),
                v_display_name || ' Telegram'
            ),
            'Telegram',
            trim(p_telegram_chat_id),
            'User',
            jsonb_build_object(
                'auth_user_id', p_auth_user_id,
                'managed_by', 'REDS Telegram Settings'
            ),
            true,
            false,
            v_actor_id,
            v_actor_id
        )
        returning notification_destination_id
        into v_destination_id;
    else
        update public.notification_destinations
        set
            destination_name = coalesce(
                nullif(trim(p_destination_name), ''),
                destination_name
            ),
            destination_scope = 'User',
            metadata = coalesce(metadata, '{}'::jsonb)
                || jsonb_build_object(
                    'auth_user_id', p_auth_user_id,
                    'managed_by', 'REDS Telegram Settings'
                ),
            is_active = true,
            updated_at = now(),
            updated_by = v_actor_id
        where notification_destination_id = v_destination_id;
    end if;

    select channel.notification_user_channel_id
    into v_current_channel_id
    from public.notification_user_channels channel
    where channel.auth_user_id = p_auth_user_id
      and channel.channel_type = 'Telegram'
      and channel.is_deleted = false
    limit 1;

    if v_current_channel_id is null then
        insert into public.notification_user_channels (
            auth_user_id,
            channel_type,
            notification_destination_id,
            connection_status,
            is_enabled,
            connected_at,
            connected_by,
            disconnected_at,
            disconnected_by,
            connection_notes,
            created_by,
            updated_by
        )
        values (
            p_auth_user_id,
            'Telegram',
            v_destination_id,
            'Connected',
            coalesce(p_is_enabled, true),
            now(),
            v_actor_id,
            null,
            null,
            nullif(trim(p_connection_notes), ''),
            v_actor_id,
            v_actor_id
        );
    else
        update public.notification_user_channels
        set
            notification_destination_id = v_destination_id,
            connection_status = 'Connected',
            is_enabled = coalesce(p_is_enabled, true),
            connected_at = now(),
            connected_by = v_actor_id,
            disconnected_at = null,
            disconnected_by = null,
            connection_notes = nullif(trim(p_connection_notes), ''),
            updated_at = now(),
            updated_by = v_actor_id
        where notification_user_channel_id = v_current_channel_id;
    end if;

    return v_destination_id;
end;
$$;


ALTER FUNCTION "public"."update_user_telegram_channel"("p_auth_user_id" "uuid", "p_telegram_chat_id" "text", "p_destination_name" "text", "p_is_enabled" boolean, "p_connection_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."user_has_permission"("p_auth_user_id" "uuid", "p_permission_code" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    v_permission_id uuid;
    v_override boolean;
begin
    if p_auth_user_id is null then
        return false;
    end if;

    if not exists (
        select 1
        from public.app_users au
        where au.auth_user_id = p_auth_user_id
          and au.account_status = 'Active'
    ) then
        return false;
    end if;

    select p.permission_id
    into v_permission_id
    from public.app_permissions p
    where p.permission_code = p_permission_code
      and p.is_active = true;

    if v_permission_id is null then
        return false;
    end if;

    select upo.is_allowed
    into v_override
    from public.app_user_permission_overrides upo
    where upo.auth_user_id = p_auth_user_id
      and upo.permission_id = v_permission_id
      and upo.is_active = true
    limit 1;

    if found then
        return v_override;
    end if;

    return exists (
        select 1
        from public.app_user_roles ur
        join public.app_roles r
          on r.role_id = ur.role_id
         and r.is_active = true
        join public.app_role_permissions rp
          on rp.role_id = r.role_id
         and rp.permission_id = v_permission_id
         and rp.is_allowed = true
        where ur.auth_user_id = p_auth_user_id
          and ur.is_active = true
          and ur.ended_at is null
    );
end;
$$;


ALTER FUNCTION "public"."user_has_permission"("p_auth_user_id" "uuid", "p_permission_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_inventory_transaction_photo"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
    if new.source_type = 'StockRequest' then
        if not exists (
            select 1
            from public.stock_requests sr
            where sr.stock_request_id = new.source_id
              and sr.is_deleted = false
        ) then
            raise exception 'Source Stock Request was not found.';
        end if;

        if new.photo_type not in (
            'RequestEvidence',
            'Delivered',
            'Received',
            'DamagedOnDelivery',
            'Other'
        ) then
            raise exception
                'Photo type % is not valid for Stock Request.',
                new.photo_type;
        end if;

    elsif new.source_type = 'StockIssue' then
        if not exists (
            select 1
            from public.stock_issues si
            where si.stock_issue_id = new.source_id
              and si.is_deleted = false
        ) then
            raise exception 'Source Stock Issue was not found.';
        end if;

        if new.photo_type not in (
            'Prepared',
            'Issued',
            'Dispatched',
            'Delivered',
            'ShortSupplied',
            'DamagedOnDelivery',
            'Other'
        ) then
            raise exception
                'Photo type % is not valid for Stock Issue.',
                new.photo_type;
        end if;

    elsif new.source_type = 'StockIssueReceipt' then
        if not exists (
            select 1
            from public.stock_issue_receipts sir
            where sir.stock_issue_receipt_id = new.source_id
              and sir.is_deleted = false
        ) then
            raise exception 'Source Stock Issue Receipt was not found.';
        end if;

        if new.photo_type not in (
            'Received',
            'ShortSupplied',
            'DamagedOnDelivery',
            'Other'
        ) then
            raise exception
                'Photo type % is not valid for Stock Issue Receipt.',
                new.photo_type;
        end if;

    elsif new.source_type = 'ToolLoan' then
        if not exists (
            select 1
            from public.tool_loans tl
            where tl.tool_loan_id = new.source_id
              and tl.is_deleted = false
        ) then
            raise exception 'Source Tool Loan was not found.';
        end if;

        if new.photo_type not in (
            'BeforeIssue',
            'AfterIssue',
            'InUse',
            'ConditionCheck',
            'Damaged',
            'Lost',
            'Other'
        ) then
            raise exception
                'Photo type % is not valid for Tool Loan.',
                new.photo_type;
        end if;

    elsif new.source_type = 'ToolLoanReturn' then
        if not exists (
            select 1
            from public.tool_loan_returns tlr
            where tlr.tool_loan_return_id = new.source_id
              and tlr.is_deleted = false
        ) then
            raise exception 'Source Tool Loan Return was not found.';
        end if;

        if new.photo_type not in (
            'BeforeReturn',
            'AfterReturn',
            'ConditionCheck',
            'Damaged',
            'Lost',
            'Other'
        ) then
            raise exception
                'Photo type % is not valid for Tool Loan Return.',
                new.photo_type;
        end if;
    end if;

    if new.is_primary = true then
        update public.inventory_transaction_photos
        set
            is_primary = false,
            updated_at = now(),
            updated_by = auth.uid()
        where source_type = new.source_type
          and source_id = new.source_id
          and inventory_transaction_photo_id <>
              new.inventory_transaction_photo_id
          and is_primary = true
          and is_deleted = false;
    end if;

    return new;
end;
$$;


ALTER FUNCTION "public"."validate_inventory_transaction_photo"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_invoice_context"("p_customer_id" "uuid", "p_project_id" "uuid", "p_project_site_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    v_project_customer_id uuid;
    v_site_project_id uuid;
begin
    if not exists (
        select 1
        from public.customers c
        where c.customer_id = p_customer_id
          and c.is_deleted = false
          and c.is_active = true
    ) then
        raise exception 'Customer is missing, inactive, or deleted.';
    end if;

    if p_project_id is not null then
        select p.customer_id
        into v_project_customer_id
        from public.projects p
        where p.project_id = p_project_id
          and p.is_deleted = false
          and p.is_active = true;

        if v_project_customer_id is null then
            raise exception 'Project is missing, inactive, or deleted.';
        end if;

        if v_project_customer_id <> p_customer_id then
            raise exception 'Project does not belong to the selected customer.';
        end if;
    end if;

    if p_project_site_id is not null then
        select ps.project_id
        into v_site_project_id
        from public.project_sites ps
        where ps.site_id = p_project_site_id
          and ps.is_deleted = false
          and ps.is_active = true;

        if v_site_project_id is null then
            raise exception 'Project Site is missing, inactive, or deleted.';
        end if;

        if p_project_id is null then
            raise exception 'Project is required when Project Site is supplied.';
        end if;

        if v_site_project_id <> p_project_id then
            raise exception 'Project Site does not belong to the selected Project.';
        end if;
    end if;
end;
$$;


ALTER FUNCTION "public"."validate_invoice_context"("p_customer_id" "uuid", "p_project_id" "uuid", "p_project_site_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_invoice_source_context"("p_customer_id" "uuid", "p_project_id" "uuid", "p_project_site_id" "uuid", "p_source_type" "text", "p_source_id" "uuid", "p_source_amount" numeric) RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    v_customer_id uuid;
    v_project_id uuid;
    v_site_id uuid;
    v_total numeric;
begin
    if p_source_type not in (
        'Quotation',
        'Variation',
        'Manual',
        'Labour',
        'Material'
    ) then
        raise exception 'Unsupported invoice source type: %', p_source_type;
    end if;

    if p_source_id is null then
        raise exception 'Source ID is required.';
    end if;

    if p_source_amount is null or p_source_amount < 0 then
        raise exception 'Source amount must be zero or greater.';
    end if;

    if p_source_type = 'Quotation' then
        select
            q.customer_id,
            ps.project_id,
            q.project_site_id,
            q.total_amount
        into
            v_customer_id,
            v_project_id,
            v_site_id,
            v_total
        from public.quotations q
        left join public.project_sites ps
            on ps.site_id = q.project_site_id
        where q.quotation_id = p_source_id
          and q.quotation_status = 'Accepted'
          and q.is_deleted = false
          and q.is_active = true;

        if v_customer_id is null then
            raise exception 'Quotation source must be an active Accepted Quotation.';
        end if;

        if v_customer_id <> p_customer_id
           or v_project_id is distinct from p_project_id
           or v_site_id is distinct from p_project_site_id then
            raise exception 'Quotation source context does not match Invoice context.';
        end if;

        if p_source_amount > v_total then
            raise exception 'Quotation source amount exceeds Accepted Quotation total.';
        end if;

    elsif p_source_type = 'Variation' then
        select
            v.customer_id,
            v.project_id,
            v.project_site_id,
            v.total_amount
        into
            v_customer_id,
            v_project_id,
            v_site_id,
            v_total
        from public.variations v
        where v.variation_id = p_source_id
          and v.variation_status = 'Accepted'
          and v.is_deleted = false
          and v.is_active = true;

        if v_customer_id is null then
            raise exception 'Variation source must be an active Accepted Variation.';
        end if;

        if v_customer_id <> p_customer_id
           or v_project_id <> p_project_id
           or v_site_id <> p_project_site_id then
            raise exception 'Variation source context does not match Invoice context.';
        end if;

        if p_source_amount > v_total then
            raise exception 'Variation source amount exceeds Accepted Variation total.';
        end if;
    end if;
end;
$$;


ALTER FUNCTION "public"."validate_invoice_source_context"("p_customer_id" "uuid", "p_project_id" "uuid", "p_project_site_id" "uuid", "p_source_type" "text", "p_source_id" "uuid", "p_source_amount" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_product_attribute_definition"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
    v_default_type text;
begin
    new.attribute_code := upper(btrim(new.attribute_code));
    new.attribute_name := btrim(new.attribute_name);

    if new.description is not null then
        new.description := nullif(btrim(new.description), '');
    end if;

    if new.placeholder is not null then
        new.placeholder := nullif(btrim(new.placeholder), '');
    end if;

    if new.help_text is not null then
        new.help_text := nullif(btrim(new.help_text), '');
    end if;

    if new.data_type in ('select', 'multi_select')
       and new.unit_uom_code is not null then
        raise exception
            'Select and multi-select attributes cannot use a numeric unit.';
    end if;

    if new.default_value is not null then
        v_default_type := jsonb_typeof(new.default_value);

        if new.data_type in ('text', 'long_text', 'date', 'select')
           and v_default_type <> 'string' then
            raise exception
                'Default value for % must be a JSON string.',
                new.data_type;
        end if;

        if new.data_type = 'number'
           and v_default_type <> 'number' then
            raise exception
                'Default value for number must be a JSON number.';
        end if;

        if new.data_type = 'boolean'
           and v_default_type <> 'boolean' then
            raise exception
                'Default value for boolean must be a JSON boolean.';
        end if;

        if new.data_type = 'multi_select'
           and v_default_type <> 'array' then
            raise exception
                'Default value for multi_select must be a JSON array of option codes.';
        end if;
    end if;

    if new.is_deleted and new.deleted_at is null then
        new.deleted_at := now();
    elsif not new.is_deleted then
        new.deleted_at := null;
    end if;

    return new;
end;
$$;


ALTER FUNCTION "public"."validate_product_attribute_definition"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_product_attribute_option"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
    v_data_type text;
begin
    new.option_code := upper(btrim(new.option_code));
    new.option_label := btrim(new.option_label);

    select d.data_type
      into v_data_type
      from public.product_attribute_definitions d
     where d.attribute_id = new.attribute_id
       and d.is_deleted = false;

    if v_data_type is null then
        raise exception
            'The selected attribute definition does not exist or is deleted.';
    end if;

    if v_data_type not in ('select', 'multi_select') then
        raise exception
            'Options can only be created for select or multi_select attributes.';
    end if;

    if new.is_deleted and new.deleted_at is null then
        new.deleted_at := now();
    elsif not new.is_deleted then
        new.deleted_at := null;
    end if;

    return new;
end;
$$;


ALTER FUNCTION "public"."validate_product_attribute_option"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_product_attribute_value"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
    v_data_type text;
    v_product_category_id uuid;
    v_attribute_allowed boolean;
    v_option_attribute_id uuid;
    v_non_null_value_count integer;
    v_rules jsonb;
    v_min numeric;
    v_max numeric;
    v_min_length integer;
    v_max_length integer;
begin
    select
        d.data_type,
        d.validation_rules
      into
        v_data_type,
        v_rules
      from public.product_attribute_definitions d
     where d.attribute_id = new.attribute_id
       and d.is_deleted = false
       and d.is_active = true;

    if v_data_type is null then
        raise exception
            'The selected product attribute is inactive, deleted or missing.';
    end if;

    select p.category_id
      into v_product_category_id
      from public.products p
     where p.product_id = new.product_id
       and p.is_deleted = false;

    if v_product_category_id is null then
        raise exception
            'The selected product does not exist or is deleted.';
    end if;

    select exists (
        select 1
          from public.get_effective_product_category_attributes(
              v_product_category_id
          ) effective
         where effective.attribute_id = new.attribute_id
    )
    into v_attribute_allowed;

    if not v_attribute_allowed then
        raise exception
            'This attribute is not available for the product category.';
    end if;

    v_non_null_value_count :=
        (case when new.value_text is not null then 1 else 0 end)
        +
        (case when new.value_number is not null then 1 else 0 end)
        +
        (case when new.value_boolean is not null then 1 else 0 end)
        +
        (case when new.value_date is not null then 1 else 0 end)
        +
        (case when new.selected_option_id is not null then 1 else 0 end);

    if v_data_type <> 'multi_select'
       and v_non_null_value_count <> 1 then
        raise exception
            'Exactly one typed value is required for attribute type %.',
            v_data_type;
    end if;

    if v_data_type = 'multi_select'
       and v_non_null_value_count <> 0 then
        raise exception
            'Multi-select values must be stored only in product_attribute_value_options.';
    end if;

    if v_data_type in ('text', 'long_text') then
        if new.value_text is null
           or btrim(new.value_text) = '' then
            raise exception
                'A text value is required for this attribute.';
        end if;

        new.value_text := btrim(new.value_text);

        if v_rules ? 'min_length' then
            v_min_length := (v_rules ->> 'min_length')::integer;

            if char_length(new.value_text) < v_min_length then
                raise exception
                    'Text value must contain at least % characters.',
                    v_min_length;
            end if;
        end if;

        if v_rules ? 'max_length' then
            v_max_length := (v_rules ->> 'max_length')::integer;

            if char_length(new.value_text) > v_max_length then
                raise exception
                    'Text value must contain no more than % characters.',
                    v_max_length;
            end if;
        end if;

        if v_rules ? 'pattern'
           and coalesce(v_rules ->> 'pattern', '') <> ''
           and new.value_text !~ (v_rules ->> 'pattern') then
            raise exception
                'Text value does not match the required format.';
        end if;

    elsif v_data_type = 'number' then
        if new.value_number is null then
            raise exception
                'A numeric value is required for this attribute.';
        end if;

        if v_rules ? 'min' then
            v_min := (v_rules ->> 'min')::numeric;

            if new.value_number < v_min then
                raise exception
                    'Numeric value cannot be less than %.',
                    v_min;
            end if;
        end if;

        if v_rules ? 'max' then
            v_max := (v_rules ->> 'max')::numeric;

            if new.value_number > v_max then
                raise exception
                    'Numeric value cannot be greater than %.',
                    v_max;
            end if;
        end if;

    elsif v_data_type = 'boolean' then
        if new.value_boolean is null then
            raise exception
                'A boolean value is required for this attribute.';
        end if;

    elsif v_data_type = 'date' then
        if new.value_date is null then
            raise exception
                'A date value is required for this attribute.';
        end if;

    elsif v_data_type = 'select' then
        if new.selected_option_id is null then
            raise exception
                'A selected option is required for this attribute.';
        end if;

        select o.attribute_id
          into v_option_attribute_id
          from public.product_attribute_options o
         where o.attribute_option_id = new.selected_option_id
           and o.is_deleted = false
           and o.is_active = true;

        if v_option_attribute_id is null then
            raise exception
                'The selected option is inactive, deleted or missing.';
        end if;

        if v_option_attribute_id <> new.attribute_id then
            raise exception
                'The selected option belongs to a different attribute.';
        end if;
    end if;

    if new.is_deleted and new.deleted_at is null then
        new.deleted_at := now();
    elsif not new.is_deleted then
        new.deleted_at := null;
    end if;

    return new;
end;
$$;


ALTER FUNCTION "public"."validate_product_attribute_value"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_product_attribute_value_option"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
    v_value_attribute_id uuid;
    v_data_type text;
    v_option_attribute_id uuid;
    v_option_active boolean;
begin
    select
        v.attribute_id,
        d.data_type
      into
        v_value_attribute_id,
        v_data_type
      from public.product_attribute_values v
      join public.product_attribute_definitions d
        on d.attribute_id = v.attribute_id
     where v.product_attribute_value_id =
           new.product_attribute_value_id
       and v.is_deleted = false;

    if v_value_attribute_id is null then
        raise exception
            'The product attribute value does not exist or is deleted.';
    end if;

    if v_data_type <> 'multi_select' then
        raise exception
            'Option links can only be used with multi_select attributes.';
    end if;

    select
        o.attribute_id,
        (o.is_active and not o.is_deleted)
      into
        v_option_attribute_id,
        v_option_active
      from public.product_attribute_options o
     where o.attribute_option_id = new.attribute_option_id;

    if v_option_attribute_id is null or not v_option_active then
        raise exception
            'The selected option is inactive, deleted or missing.';
    end if;

    if v_option_attribute_id <> v_value_attribute_id then
        raise exception
            'The selected option belongs to a different attribute.';
    end if;

    return new;
end;
$$;


ALTER FUNCTION "public"."validate_product_attribute_value_option"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_product_category_attribute"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
    v_category_exists boolean;
    v_attribute_exists boolean;
begin
    new.section_name := btrim(new.section_name);

    if new.display_label_override is not null then
        new.display_label_override :=
            nullif(btrim(new.display_label_override), '');
    end if;

    if new.help_text_override is not null then
        new.help_text_override :=
            nullif(btrim(new.help_text_override), '');
    end if;

    select exists (
        select 1
          from public.product_categories c
         where c.category_id = new.category_id
           and c.is_deleted = false
    )
    into v_category_exists;

    if not v_category_exists then
        raise exception
            'The selected product category does not exist or is deleted.';
    end if;

    select exists (
        select 1
          from public.product_attribute_definitions d
         where d.attribute_id = new.attribute_id
           and d.is_deleted = false
    )
    into v_attribute_exists;

    if not v_attribute_exists then
        raise exception
            'The selected product attribute does not exist or is deleted.';
    end if;

    if new.is_deleted and new.deleted_at is null then
        new.deleted_at := now();
    elsif not new.is_deleted then
        new.deleted_at := null;
    end if;

    return new;
end;
$$;


ALTER FUNCTION "public"."validate_product_category_attribute"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_product_code_family"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  family_number integer;
  range_row public.product_code_ranges%rowtype;
begin
  family_number := new.family_code::integer;

  select * into range_row
  from public.product_code_ranges
  where product_code_range_id = new.product_code_range_id
    and is_deleted = false;

  if not found then
    raise exception 'Selected Product Code Range does not exist.';
  end if;

  if family_number < range_row.start_family_number
     or family_number > range_row.end_family_number then
    raise exception 'Family Code % is outside range %.', new.family_code, range_row.range_code;
  end if;

  if family_number between 1 and 40 and new.product_domain <> 'flooring' then
    raise exception 'Product Family Codes 01-40 are locked for Flooring Products only.';
  end if;

  if family_number between 1 and 40 and range_row.product_domain <> 'flooring' then
    raise exception 'Range 01-40 must use product_domain = flooring.';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_product_code_family"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_product_code_range_overlap"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
  if new.is_deleted then return new; end if;

  if exists (
    select 1
    from public.product_code_ranges r
    where r.product_code_range_id <> coalesce(
      new.product_code_range_id,
      '00000000-0000-0000-0000-000000000000'::uuid
    )
      and r.is_deleted = false
      and int4range(r.start_family_number, r.end_family_number, '[]')
          && int4range(new.start_family_number, new.end_family_number, '[]')
  ) then
    raise exception 'Product Code Range % overlaps another range.', new.range_code;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_product_code_range_overlap"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_product_default_uoms"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
    v_default_uom text;
    v_default_name text;
begin
    if new.base_uom_code is null then
        raise exception 'Base UOM is required.';
    end if;


    -- --------------------------------------------------------
    -- Default Purchase UOM
    -- --------------------------------------------------------
    v_default_uom := new.default_purchase_uom_code;
    v_default_name := 'Default Purchase UOM';

    if v_default_uom is not null
       and v_default_uom <> new.base_uom_code
       and not exists (
            select 1
            from public.product_uom_conversions puc
            where puc.product_id = new.product_id
              and puc.from_uom_code = v_default_uom
              and puc.to_uom_code = new.base_uom_code
              and puc.is_active = true
              and puc.is_deleted = false
       )
    then
        raise exception
            '% (%) requires an active conversion to Base UOM (%).',
            v_default_name,
            v_default_uom,
            new.base_uom_code;
    end if;


    -- --------------------------------------------------------
    -- Default Request UOM
    -- --------------------------------------------------------
    v_default_uom := new.default_request_uom_code;
    v_default_name := 'Default Request UOM';

    if v_default_uom is not null
       and v_default_uom <> new.base_uom_code
       and not exists (
            select 1
            from public.product_uom_conversions puc
            where puc.product_id = new.product_id
              and puc.from_uom_code = v_default_uom
              and puc.to_uom_code = new.base_uom_code
              and puc.is_active = true
              and puc.is_deleted = false
       )
    then
        raise exception
            '% (%) requires an active conversion to Base UOM (%).',
            v_default_name,
            v_default_uom,
            new.base_uom_code;
    end if;


    -- --------------------------------------------------------
    -- Default Sales UOM
    -- --------------------------------------------------------
    v_default_uom := new.default_sales_uom_code;
    v_default_name := 'Default Sales UOM';

    if v_default_uom is not null
       and v_default_uom <> new.base_uom_code
       and not exists (
            select 1
            from public.product_uom_conversions puc
            where puc.product_id = new.product_id
              and puc.from_uom_code = v_default_uom
              and puc.to_uom_code = new.base_uom_code
              and puc.is_active = true
              and puc.is_deleted = false
       )
    then
        raise exception
            '% (%) requires an active conversion to Base UOM (%).',
            v_default_name,
            v_default_uom,
            new.base_uom_code;
    end if;

    return new;
end;
$$;


ALTER FUNCTION "public"."validate_product_default_uoms"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_product_uom_conversion"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
    v_base_uom_code text;
begin
    select p.base_uom_code
    into v_base_uom_code
    from public.products p
    where p.product_id = new.product_id
      and p.is_deleted = false;

    if v_base_uom_code is null then
        raise exception
            'The selected Product does not exist or does not have a Base UOM.';
    end if;

    if new.to_uom_code <> v_base_uom_code then
        raise exception
            'Conversion must convert directly to the Product Base UOM (%).',
            v_base_uom_code;
    end if;

    if new.from_uom_code = v_base_uom_code then
        raise exception
            'A conversion is not required when the Transaction UOM is already the Base UOM (%).',
            v_base_uom_code;
    end if;

    if new.conversion_factor <= 0 then
        raise exception
            'Conversion Factor must be greater than zero.';
    end if;

    return new;
end;
$$;


ALTER FUNCTION "public"."validate_product_uom_conversion"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_quotation_revision_pointers"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
    if new.current_revision_id is not null
       and not exists (
            select 1
            from public.quotation_revisions qr
            where qr.revision_id =
                  new.current_revision_id
              and qr.quotation_id =
                  new.quotation_id
              and qr.is_active = true
              and qr.is_deleted = false
       ) then
        raise exception
            'Current revision must belong to this quotation and must not be archived.';
    end if;

    if new.accepted_revision_id is not null
       and not exists (
            select 1
            from public.quotation_revisions qr
            where qr.revision_id =
                  new.accepted_revision_id
              and qr.quotation_id =
                  new.quotation_id
              and qr.revision_status =
                  'Accepted'
              and qr.is_active = true
              and qr.is_deleted = false
       ) then
        raise exception
            'Accepted revision must belong to this quotation, have Accepted status, and must not be archived.';
    end if;

    if new.accepted_revision_id is not null
       and new.current_revision_id is distinct from
           new.accepted_revision_id then
        raise exception
            'Accepted revision must also be the current revision.';
    end if;

    return new;
end;
$$;


ALTER FUNCTION "public"."validate_quotation_revision_pointers"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_quotation_revision_snapshot"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    v_customer_id uuid;
    v_project_site_id uuid;
begin
    select
        q.customer_id,
        q.project_site_id
    into
        v_customer_id,
        v_project_site_id
    from public.quotations q
    where q.quotation_id = new.quotation_id
      and q.is_deleted = false;

    if not found then
        raise exception
            'Parent quotation does not exist or is deleted.';
    end if;

    if new.customer_id <> v_customer_id then
        raise exception
            'Revision customer must match the parent quotation.';
    end if;

    if new.project_site_id is distinct from
       v_project_site_id then
        raise exception
            'Revision project site must match the parent quotation.';
    end if;

    return new;
end;
$$;


ALTER FUNCTION "public"."validate_quotation_revision_snapshot"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_quotation_site_customer"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    v_project_customer_id uuid;
begin
    if new.project_site_id is null then
        return new;
    end if;

    select p.customer_id
    into v_project_customer_id
    from public.project_sites ps
    join public.projects p
      on p.project_id = ps.project_id
    where ps.site_id = new.project_site_id
      and ps.is_deleted = false
      and p.is_deleted = false;

    if not found then
        raise exception
            'Project site does not exist or is inactive in the project hierarchy.';
    end if;

    if v_project_customer_id <> new.customer_id then
        raise exception
            'Quotation customer must match the project customer.';
    end if;

    return new;
end;
$$;


ALTER FUNCTION "public"."validate_quotation_site_customer"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_stock_issue_allocation"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
    v_line_product_id uuid;
    v_line_base_uom_code text;
    v_lot_product_id uuid;
    v_lot_base_uom_code text;
    v_lot_available numeric;
    v_other_active_allocated numeric;
begin
    select
        issued_product_id,
        base_uom_code
    into
        v_line_product_id,
        v_line_base_uom_code
    from public.stock_issue_lines
    where stock_issue_line_id = new.stock_issue_line_id
      and is_deleted = false;

    if v_line_product_id is null then
        raise exception 'Stock Issue line was not found or is deleted.';
    end if;

    select
        product_id,
        base_uom_code,
        greatest(remaining_quantity - reserved_quantity, 0)
    into
        v_lot_product_id,
        v_lot_base_uom_code,
        v_lot_available
    from public.stock_lots
    where stock_lot_id = new.stock_lot_id
      and is_deleted = false
      and is_active = true;

    if v_lot_product_id is null then
        raise exception 'Stock lot was not found, inactive or deleted.';
    end if;

    if v_lot_product_id <> v_line_product_id then
        raise exception 'Stock lot product does not match the Stock Issue line issued product.';
    end if;

    if v_lot_base_uom_code <> v_line_base_uom_code then
        raise exception 'Stock lot Base UOM does not match the Stock Issue line Base UOM.';
    end if;

    select coalesce(sum(allocation.allocated_base_quantity), 0)
    into v_other_active_allocated
    from public.stock_issue_allocations allocation
    where allocation.stock_lot_id = new.stock_lot_id
      and allocation.is_deleted = false
      and allocation.allocation_status in ('Allocated', 'PartiallyIssued')
      and allocation.stock_issue_allocation_id <> new.stock_issue_allocation_id;

    if new.allocated_base_quantity + v_other_active_allocated > v_lot_available then
        raise exception 'Stock Issue allocation exceeds currently available stock for the selected lot.';
    end if;

    return new;
end;
$$;


ALTER FUNCTION "public"."validate_stock_issue_allocation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_stock_issue_context"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
    v_request public.stock_requests%rowtype;
    v_work_order public.work_orders%rowtype;
begin
    select *
    into v_request
    from public.stock_requests
    where stock_request_id = new.stock_request_id
      and is_deleted = false;

    if not found then
        raise exception 'Stock Issue source Stock Request was not found or is deleted.';
    end if;

    if v_request.request_status not in (
        'Approved',
        'PartiallyApproved',
        'Partially Reserved',
        'Reserved',
        'Partially Issued',
        'Issued',
        'Ordered',
        'Partially Delivered',
        'Delivered'
    ) then
        raise exception 'Stock Issue can only be created from an approved or fulfilment-stage Stock Request.';
    end if;

    if new.project_id <> v_request.project_id then
        raise exception 'Stock Issue project does not match the source Stock Request.';
    end if;

    if new.site_id <> v_request.site_id then
        raise exception 'Stock Issue site does not match the source Stock Request.';
    end if;

    if new.area_id is distinct from v_request.area_id then
        raise exception 'Stock Issue area does not match the source Stock Request.';
    end if;

    if new.work_order_id is distinct from v_request.work_order_id then
        raise exception 'Stock Issue Work Order does not match the source Stock Request.';
    end if;

    if new.work_order_id is not null then
        select *
        into v_work_order
        from public.work_orders
        where work_order_id = new.work_order_id
          and is_deleted = false;

        if not found then
            raise exception 'Stock Issue Work Order was not found or is deleted.';
        end if;

        if v_work_order.project_id is distinct from new.project_id
           or v_work_order.site_id is distinct from new.site_id
           or v_work_order.area_id is distinct from new.area_id then
            raise exception 'Stock Issue context does not match the selected Work Order.';
        end if;
    end if;

    if new.delivery_method = 'StockTransfer'
       and new.to_stock_location_id is null then
        raise exception 'Stock Transfer requires a destination stock location.';
    end if;

    return new;
end;
$$;


ALTER FUNCTION "public"."validate_stock_issue_context"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_stock_issue_line_cumulative_quantity"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
    v_request_item public.stock_request_items%rowtype;
    v_existing_issue_commitment numeric(18,6);
    v_legacy_issued_quantity numeric(18,6);
    v_total_after_change numeric(18,6);
begin
    -- A cancelled or soft-deleted line contributes no active commitment.
    if new.is_deleted = true
       or new.line_status = 'Cancelled' then
        return new;
    end if;

    if new.stock_request_item_id is null then
        raise exception 'Stock Request item is required.';
    end if;

    -- Serialize all issue commitments for the same Stock Request Item.
    select *
    into v_request_item
    from public.stock_request_items
    where stock_request_item_id = new.stock_request_item_id
      and is_deleted = false
    for update;

    if not found then
        raise exception 'Stock Request item was not found.';
    end if;

    if coalesce(v_request_item.fulfilment_method, 'Issue') <> 'Issue' then
        raise exception
            'Stock Request item % is not routed for Stock Issue.',
            new.stock_request_item_id;
    end if;

    if coalesce(v_request_item.approved_base_quantity, 0) <= 0 then
        raise exception
            'Stock Request item % has no approved base quantity.',
            new.stock_request_item_id;
    end if;

    if new.issue_base_quantity is null
       or new.issue_base_quantity < 0 then
        raise exception
            'Stock Issue base quantity must be zero or greater.';
    end if;

    -- Existing active commitments from Stock Issue lines.
    -- Exclude the current row during UPDATE.
    select coalesce(sum(sil.issue_base_quantity), 0)
    into v_existing_issue_commitment
    from public.stock_issue_lines sil
    join public.stock_issues si
      on si.stock_issue_id = sil.stock_issue_id
    where sil.stock_request_item_id = new.stock_request_item_id
      and sil.is_deleted = false
      and sil.line_status <> 'Cancelled'
      and si.is_deleted = false
      and si.issue_status <> 'Cancelled'
      and sil.stock_issue_line_id <>
          coalesce(new.stock_issue_line_id, gen_random_uuid());

    -- Preserve issue quantities posted by the legacy workflow.
    -- Movements linked to a Stock Issue are already represented by
    -- stock_issue_lines and must not be counted twice.
    select coalesce(sum(sm.quantity), 0)
    into v_legacy_issued_quantity
    from public.stock_movements sm
    where sm.stock_request_item_id = new.stock_request_item_id
      and sm.movement_type = 'Issue'
      and sm.is_deleted = false
      and sm.stock_issue_id is null;

    v_total_after_change :=
        round(
            v_existing_issue_commitment
            + v_legacy_issued_quantity
            + new.issue_base_quantity,
            6
        );

    if v_total_after_change >
       round(v_request_item.approved_base_quantity, 6) then
        raise exception
            'Cumulative Stock Issue quantity exceeds the approved quantity. Approved: % %, existing Stock Issue commitment: % %, legacy issued: % %, requested line: % %, resulting total: % %.',
            v_request_item.approved_base_quantity,
            coalesce(v_request_item.base_uom_code, 'base UOM'),
            v_existing_issue_commitment,
            coalesce(v_request_item.base_uom_code, 'base UOM'),
            v_legacy_issued_quantity,
            coalesce(v_request_item.base_uom_code, 'base UOM'),
            new.issue_base_quantity,
            coalesce(v_request_item.base_uom_code, 'base UOM'),
            v_total_after_change,
            coalesce(v_request_item.base_uom_code, 'base UOM');
    end if;

    return new;
end;
$$;


ALTER FUNCTION "public"."validate_stock_issue_line_cumulative_quantity"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_stock_issue_line_source"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
    v_issue_request_id uuid;
    v_request_item public.stock_request_items%rowtype;
    v_requested_product_type text;
    v_issued_product_type text;
begin
    select stock_request_id
    into v_issue_request_id
    from public.stock_issues
    where stock_issue_id = new.stock_issue_id
      and is_deleted = false;

    if v_issue_request_id is null then
        raise exception 'Stock Issue header was not found or is deleted.';
    end if;

    select *
    into v_request_item
    from public.stock_request_items
    where stock_request_item_id = new.stock_request_item_id
      and is_deleted = false;

    if not found then
        raise exception 'Stock Request item was not found or is deleted.';
    end if;

    if v_request_item.stock_request_id <> v_issue_request_id then
        raise exception 'Stock Issue line does not belong to the source Stock Request.';
    end if;

    if v_request_item.fulfilment_method <> 'Issue' then
        raise exception 'Only Stock Request items routed to Issue may be added to a Stock Issue.';
    end if;

    if new.requested_product_id <> v_request_item.product_id then
        raise exception 'Stock Issue requested product does not match the source Stock Request item.';
    end if;

    select product_type
    into v_requested_product_type
    from public.products
    where product_id = new.requested_product_id
      and is_deleted = false;

    select product_type
    into v_issued_product_type
    from public.products
    where product_id = new.issued_product_id
      and is_deleted = false;

    if v_requested_product_type not in ('Material', 'Consumable') then
        raise exception 'Stock Issue requested product must be Material or Consumable.';
    end if;

    if v_issued_product_type not in ('Material', 'Consumable') then
        raise exception 'Stock Issue issued product must be Material or Consumable.';
    end if;

    return new;
end;
$$;


ALTER FUNCTION "public"."validate_stock_issue_line_source"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_stock_issue_receipt_line"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
    v_receipt_issue_id uuid;
    v_line_issue_id uuid;
    v_line_issue_base_quantity numeric;
    v_other_recorded numeric;
    v_new_recorded numeric;
begin
    select stock_issue_id
    into v_receipt_issue_id
    from public.stock_issue_receipts
    where stock_issue_receipt_id = new.stock_issue_receipt_id
      and is_deleted = false;

    select
        stock_issue_id,
        issue_base_quantity
    into
        v_line_issue_id,
        v_line_issue_base_quantity
    from public.stock_issue_lines
    where stock_issue_line_id = new.stock_issue_line_id
      and is_deleted = false;

    if v_receipt_issue_id is null or v_line_issue_id is null then
        raise exception 'Stock Issue receipt header or line was not found.';
    end if;

    if v_receipt_issue_id <> v_line_issue_id then
        raise exception 'Stock Issue receipt line does not belong to the receipt Stock Issue.';
    end if;

    select coalesce(sum(
        receipt_line.received_base_quantity
        + receipt_line.damaged_base_quantity
        + receipt_line.short_base_quantity
    ), 0)
    into v_other_recorded
    from public.stock_issue_receipt_lines receipt_line
    join public.stock_issue_receipts receipt
      on receipt.stock_issue_receipt_id = receipt_line.stock_issue_receipt_id
    where receipt_line.stock_issue_line_id = new.stock_issue_line_id
      and receipt_line.stock_issue_receipt_line_id <> new.stock_issue_receipt_line_id
      and receipt_line.is_deleted = false
      and receipt.is_deleted = false;

    v_new_recorded :=
        new.received_base_quantity
        + new.damaged_base_quantity
        + new.short_base_quantity;

    if v_other_recorded + v_new_recorded > v_line_issue_base_quantity then
        raise exception 'Stock Issue receipt quantities exceed the issued quantity.';
    end if;

    return new;
end;
$$;


ALTER FUNCTION "public"."validate_stock_issue_receipt_line"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_stock_request_context"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    v_wo_project_id uuid;
    v_wo_site_id uuid;
    v_wo_area_id uuid;
    v_mr_project_id uuid;
    v_mr_site_id uuid;
begin
    if new.work_order_id is not null then
        select wo.project_id, wo.site_id, wo.area_id
          into v_wo_project_id, v_wo_site_id, v_wo_area_id
          from public.work_orders wo
         where wo.work_order_id = new.work_order_id
           and wo.is_deleted = false;

        if v_wo_project_id is null then
            raise exception 'Selected Work Order is missing or deleted.';
        end if;

        if new.project_id <> v_wo_project_id then
            raise exception 'Stock Request project does not match the selected Work Order.';
        end if;

        if new.site_id <> v_wo_site_id then
            raise exception 'Stock Request site does not match the selected Work Order.';
        end if;

        if new.area_id is distinct from v_wo_area_id then
            raise exception 'Stock Request area does not match the selected Work Order.';
        end if;
    end if;

    if new.material_requirement_id is not null then
        select mr.project_id, mr.site_id
          into v_mr_project_id, v_mr_site_id
          from public.material_requirements mr
         where mr.material_requirement_id = new.material_requirement_id
           and mr.is_deleted = false;

        if v_mr_project_id is null then
            raise exception 'Selected Material Requirement is missing or deleted.';
        end if;

        if new.project_id <> v_mr_project_id then
            raise exception 'Stock Request project does not match the selected Material Requirement.';
        end if;

        if v_mr_site_id is not null and new.site_id <> v_mr_site_id then
            raise exception 'Stock Request site does not match the selected Material Requirement.';
        end if;
    end if;

    return new;
end;
$$;


ALTER FUNCTION "public"."validate_stock_request_context"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_stock_request_item_mr_link"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    v_item_request_id uuid;
    v_line_requirement_id uuid;
    v_header_requirement_id uuid;
begin
    if new.material_requirement_line_id is null then
        return new;
    end if;

    select mrl.material_requirement_id
      into v_line_requirement_id
      from public.material_requirement_lines mrl
     where mrl.material_requirement_line_id = new.material_requirement_line_id
       and mrl.is_deleted = false;

    if v_line_requirement_id is null then
        raise exception 'Selected Material Requirement line is missing or deleted.';
    end if;

    select sr.stock_request_id, sr.material_requirement_id
      into v_item_request_id, v_header_requirement_id
      from public.stock_requests sr
     where sr.stock_request_id = new.stock_request_id
       and sr.is_deleted = false;

    if v_item_request_id is null then
        raise exception 'Parent Stock Request is missing or deleted.';
    end if;

    if v_header_requirement_id is not null
       and v_header_requirement_id <> v_line_requirement_id then
        raise exception 'Stock Request item Material Requirement line does not belong to the header Material Requirement.';
    end if;

    return new;
end;
$$;


ALTER FUNCTION "public"."validate_stock_request_item_mr_link"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_tool_loan_context"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
    v_request public.stock_requests%rowtype;
    v_work_order public.work_orders%rowtype;
begin
    if new.stock_request_id is not null then
        select *
        into v_request
        from public.stock_requests
        where stock_request_id = new.stock_request_id
          and is_deleted = false;

        if not found then
            raise exception 'Source Stock Request was not found.';
        end if;

        if new.project_id is distinct from v_request.project_id then
            raise exception 'Tool Loan project does not match the source Stock Request.';
        end if;

        if new.site_id is distinct from v_request.site_id then
            raise exception 'Tool Loan site does not match the source Stock Request.';
        end if;

        if new.area_id is distinct from v_request.area_id then
            raise exception 'Tool Loan area does not match the source Stock Request.';
        end if;

        if new.work_order_id is distinct from v_request.work_order_id then
            raise exception 'Tool Loan Work Order does not match the source Stock Request.';
        end if;
    end if;

    if new.work_order_id is not null then
        select *
        into v_work_order
        from public.work_orders
        where work_order_id = new.work_order_id
          and is_deleted = false;

        if not found then
            raise exception 'Selected Work Order was not found.';
        end if;

        if new.project_id is distinct from v_work_order.project_id then
            raise exception 'Tool Loan project does not match the selected Work Order.';
        end if;

        if new.site_id is distinct from v_work_order.site_id then
            raise exception 'Tool Loan site does not match the selected Work Order.';
        end if;

        if new.area_id is distinct from v_work_order.area_id then
            raise exception 'Tool Loan area does not match the selected Work Order.';
        end if;
    end if;

    if new.borrower_employee_id is not null
       and new.borrower_auth_user_id is not null then
        if not exists (
            select 1
            from public.employees e
            where e.employee_id = new.borrower_employee_id
              and e.auth_user_id = new.borrower_auth_user_id
              and e.is_deleted = false
        ) then
            raise exception
                'Borrower employee does not match the selected application user.';
        end if;
    end if;

    return new;
end;
$$;


ALTER FUNCTION "public"."validate_tool_loan_context"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_tool_loan_item_source"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
    v_product_type text;
    v_request_item public.stock_request_items%rowtype;
    v_loan public.tool_loans%rowtype;
begin
    select product_type
    into v_product_type
    from public.products
    where product_id = new.product_id
      and is_deleted = false
      and is_active = true;

    if not found then
        raise exception 'Tool Loan product was not found or is inactive.';
    end if;

    if v_product_type not in ('Tool', 'Equipment') then
        raise exception
            'Tool Loan items must use a Tool or Equipment product.';
    end if;

    select *
    into v_loan
    from public.tool_loans
    where tool_loan_id = new.tool_loan_id
      and is_deleted = false;

    if not found then
        raise exception 'Parent Tool Loan was not found.';
    end if;

    if new.stock_request_item_id is not null then
        select *
        into v_request_item
        from public.stock_request_items
        where stock_request_item_id = new.stock_request_item_id
          and is_deleted = false;

        if not found then
            raise exception 'Source Stock Request item was not found.';
        end if;

        if v_loan.stock_request_id is null
           or v_request_item.stock_request_id <> v_loan.stock_request_id then
            raise exception
                'Tool Loan item does not belong to the source Stock Request.';
        end if;

        if v_request_item.product_id <> new.product_id then
            raise exception
                'Tool Loan product does not match the source Stock Request item.';
        end if;

        if coalesce(v_request_item.fulfilment_method, '') <> 'Loan' then
            raise exception
                'Source Stock Request item is not routed for Loan.';
        end if;
    end if;

    return new;
end;
$$;


ALTER FUNCTION "public"."validate_tool_loan_item_source"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_tool_loan_return_item"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
    v_return public.tool_loan_returns%rowtype;
    v_item public.tool_loan_items%rowtype;
    v_previous_returned numeric;
    v_previous_damaged numeric;
    v_previous_lost numeric;
begin
    select *
    into v_return
    from public.tool_loan_returns
    where tool_loan_return_id = new.tool_loan_return_id
      and is_deleted = false;

    if not found then
        raise exception 'Parent Tool Loan return was not found.';
    end if;

    select *
    into v_item
    from public.tool_loan_items
    where tool_loan_item_id = new.tool_loan_item_id
      and is_deleted = false;

    if not found then
        raise exception 'Tool Loan item was not found.';
    end if;

    if v_item.tool_loan_id <> v_return.tool_loan_id then
        raise exception
            'Tool Loan return item does not belong to the parent Tool Loan.';
    end if;

    select
        coalesce(sum(ri.returned_quantity), 0),
        coalesce(sum(ri.damaged_quantity), 0),
        coalesce(sum(ri.lost_quantity), 0)
    into
        v_previous_returned,
        v_previous_damaged,
        v_previous_lost
    from public.tool_loan_return_items ri
    join public.tool_loan_returns r
      on r.tool_loan_return_id = ri.tool_loan_return_id
    where ri.tool_loan_item_id = new.tool_loan_item_id
      and ri.is_deleted = false
      and r.is_deleted = false
      and ri.tool_loan_return_item_id <> new.tool_loan_return_item_id;

    if (
        v_previous_returned
        + v_previous_damaged
        + v_previous_lost
        + new.returned_quantity
        + new.damaged_quantity
        + new.lost_quantity
    ) > v_item.issued_quantity then
        raise exception
            'Tool Loan return quantities exceed the issued quantity.';
    end if;

    return new;
end;
$$;


ALTER FUNCTION "public"."validate_tool_loan_return_item"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_variation_line_context"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    v_variation public.variations%rowtype;
    v_area public.project_areas%rowtype;
begin
    select *
    into v_variation
    from public.variations
    where variation_id = new.variation_id
      and is_deleted = false;

    if not found then
        raise exception
            'Variation header was not found.';
    end if;

    if v_variation.variation_status <> 'Draft' then
        raise exception
            'Variation lines can only be changed while the Variation is Draft.';
    end if;

    if new.project_area_id is not null then
        select *
        into v_area
        from public.project_areas
        where area_id = new.project_area_id
          and is_active = true
          and is_deleted = false;

        if not found then
            raise exception
                'Variation area is unavailable.';
        end if;

        if v_area.project_id <> v_variation.project_id
           or v_area.site_id <> v_variation.project_site_id then
            raise exception
                'Variation area must belong to the same Project and Site.';
        end if;

        if v_area.area_status not in ('Quotation', 'Active') then
            raise exception
                'Variation area must be Quotation or Active.';
        end if;
    end if;

    return new;
end;
$$;


ALTER FUNCTION "public"."validate_variation_line_context"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_variation_source_context"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    v_quotation public.quotations%rowtype;
    v_site public.project_sites%rowtype;
begin
    select *
    into v_quotation
    from public.quotations
    where quotation_id = new.quotation_id
      and quotation_status = 'Accepted'
      and is_active = true
      and is_deleted = false;

    if not found then
        raise exception
            'Variation requires an active Accepted quotation.';
    end if;

    if v_quotation.customer_id <> new.customer_id then
        raise exception
            'Variation customer does not match the Accepted quotation.';
    end if;

    if v_quotation.project_site_id <> new.project_site_id then
        raise exception
            'Variation site does not match the Accepted quotation.';
    end if;

    select *
    into v_site
    from public.project_sites
    where site_id = new.project_site_id
      and is_active = true
      and is_deleted = false;

    if not found then
        raise exception
            'Variation site is not active or is unavailable.';
    end if;

    if v_site.project_id <> new.project_id then
        raise exception
            'Variation project does not match the selected site.';
    end if;

    if v_site.site_status <> 'Active' then
        raise exception
            'Variation can only be created for an Active site.';
    end if;

    if new.accepted_revision_id is distinct from
       v_quotation.accepted_revision_id then
        raise exception
            'Variation accepted revision does not match the Accepted quotation source.';
    end if;

    return new;
end;
$$;


ALTER FUNCTION "public"."validate_variation_source_context"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."void_invoice_atomic"("p_invoice_id" "uuid", "p_reason" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    v_invoice public.customer_invoices%rowtype;
begin
    perform public.assert_invoice_permission('invoices.void');

    if nullif(btrim(p_reason), '') is null then
        raise exception 'Void reason is required.';
    end if;

    select *
    into v_invoice
    from public.customer_invoices
    where customer_invoice_id = p_invoice_id
      and is_deleted = false
    for update;

    if not found then
        raise exception 'Invoice not found.';
    end if;

    if v_invoice.document_status <> 'Issued' then
        raise exception 'Only Issued Invoices can be voided.';
    end if;

    if v_invoice.paid_amount <> 0 then
        raise exception 'An Invoice with payments cannot be voided.';
    end if;

    update public.customer_invoices
    set
        document_status = 'Voided',
        voided_at = now(),
        voided_by = auth.uid(),
        void_reason = btrim(p_reason),
        updated_by = auth.uid()
    where customer_invoice_id = p_invoice_id;

    return p_invoice_id;
end;
$$;


ALTER FUNCTION "public"."void_invoice_atomic"("p_invoice_id" "uuid", "p_reason" "text") OWNER TO "postgres";

