CREATE TABLE IF NOT EXISTS "public"."customer_financial_settings" (
    "customer_financial_setting_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "customer_id" "uuid" NOT NULL,
    "default_currency" "text" DEFAULT 'AUD'::"text" NOT NULL,
    "default_sales_account_code" "text",
    "default_tax_type" "text",
    "line_amount_type" "text" DEFAULT 'Exclusive'::"text" NOT NULL,
    "discount_percent" numeric(5,2) DEFAULT 0 NOT NULL,
    "payment_terms_type" "text" DEFAULT 'Days After Bill'::"text" NOT NULL,
    "payment_terms_days" integer DEFAULT 14 NOT NULL,
    "credit_limit" numeric(14,2),
    "is_account_on_hold" boolean DEFAULT false NOT NULL,
    "account_hold_reason" "text",
    "invoice_delivery_method" "text" DEFAULT 'Email'::"text" NOT NULL,
    "statement_delivery_method" "text" DEFAULT 'Email'::"text" NOT NULL,
    "xero_contact_id" "uuid",
    "xero_contact_name" "text",
    "xero_contact_number" "text",
    "xero_status" "text" DEFAULT 'Not Connected'::"text" NOT NULL,
    "xero_last_synced_at" timestamp with time zone,
    "xero_sync_error" "text",
    "xero_branding_theme_id" "text",
    "xero_branding_theme_name" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_by" "uuid" DEFAULT "auth"."uid"(),
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_by" "uuid",
    CONSTRAINT "customer_financial_settings_account_hold_reason_chk" CHECK (((("is_account_on_hold" = false) AND ("account_hold_reason" IS NULL)) OR (("is_account_on_hold" = true) AND ("account_hold_reason" IS NOT NULL) AND ("btrim"("account_hold_reason") <> ''::"text")))),
    CONSTRAINT "customer_financial_settings_credit_limit_chk" CHECK ((("credit_limit" IS NULL) OR ("credit_limit" >= (0)::numeric))),
    CONSTRAINT "customer_financial_settings_default_currency_chk" CHECK (("default_currency" ~ '^[A-Z]{3}$'::"text")),
    CONSTRAINT "customer_financial_settings_default_sales_account_code_chk" CHECK ((("default_sales_account_code" IS NULL) OR ("btrim"("default_sales_account_code") <> ''::"text"))),
    CONSTRAINT "customer_financial_settings_default_tax_type_chk" CHECK ((("default_tax_type" IS NULL) OR ("btrim"("default_tax_type") <> ''::"text"))),
    CONSTRAINT "customer_financial_settings_discount_percent_chk" CHECK ((("discount_percent" >= (0)::numeric) AND ("discount_percent" <= (100)::numeric))),
    CONSTRAINT "customer_financial_settings_invoice_delivery_method_chk" CHECK (("invoice_delivery_method" = ANY (ARRAY['Email'::"text", 'Print'::"text", 'Both'::"text", 'Manual'::"text"]))),
    CONSTRAINT "customer_financial_settings_line_amount_type_chk" CHECK (("line_amount_type" = ANY (ARRAY['Exclusive'::"text", 'Inclusive'::"text", 'NoTax'::"text"]))),
    CONSTRAINT "customer_financial_settings_payment_terms_days_chk" CHECK (((("payment_terms_type" = ANY (ARRAY['Days After Bill'::"text", 'Days After Bill Month'::"text"])) AND (("payment_terms_days" >= 0) AND ("payment_terms_days" <= 365))) OR (("payment_terms_type" = ANY (ARRAY['Day of Current Month'::"text", 'Day of Following Month'::"text"])) AND (("payment_terms_days" >= 1) AND ("payment_terms_days" <= 31))))),
    CONSTRAINT "customer_financial_settings_payment_terms_type_chk" CHECK (("payment_terms_type" = ANY (ARRAY['Days After Bill'::"text", 'Days After Bill Month'::"text", 'Day of Current Month'::"text", 'Day of Following Month'::"text"]))),
    CONSTRAINT "customer_financial_settings_statement_delivery_method_chk" CHECK (("statement_delivery_method" = ANY (ARRAY['Email'::"text", 'Print'::"text", 'Both'::"text", 'Manual'::"text", 'None'::"text"]))),
    CONSTRAINT "customer_financial_settings_xero_branding_theme_id_chk" CHECK ((("xero_branding_theme_id" IS NULL) OR ("btrim"("xero_branding_theme_id") <> ''::"text"))),
    CONSTRAINT "customer_financial_settings_xero_branding_theme_name_chk" CHECK ((("xero_branding_theme_name" IS NULL) OR ("btrim"("xero_branding_theme_name") <> ''::"text"))),
    CONSTRAINT "customer_financial_settings_xero_contact_name_chk" CHECK ((("xero_contact_name" IS NULL) OR ("btrim"("xero_contact_name") <> ''::"text"))),
    CONSTRAINT "customer_financial_settings_xero_contact_number_chk" CHECK ((("xero_contact_number" IS NULL) OR ("btrim"("xero_contact_number") <> ''::"text"))),
    CONSTRAINT "customer_financial_settings_xero_status_chk" CHECK (("xero_status" = ANY (ARRAY['Not Connected'::"text", 'Ready'::"text", 'Synced'::"text", 'Error'::"text"])))
);


