    CONSTRAINT "customer_invoices_amounts_nonnegative_check" CHECK ((("subtotal_amount" >= (0)::numeric) AND ("discount_amount" >= (0)::numeric) AND ("tax_amount" >= (0)::numeric) AND ("total_amount" >= (0)::numeric) AND ("paid_amount" >= (0)::numeric) AND ("retention_release_amount" >= (0)::numeric))),
    CONSTRAINT "customer_invoices_cancel_audit_check" CHECK ((("document_status" <> 'Cancelled'::"text") OR (("cancelled_at" IS NOT NULL) AND ("cancelled_by" IS NOT NULL) AND ("cancellation_reason" IS NOT NULL) AND ("btrim"("cancellation_reason") <> ''::"text")))),
    CONSTRAINT "customer_invoices_credit_note_context_check" CHECK (((("invoice_type" <> 'Credit Note'::"text") AND ("original_invoice_id" IS NULL) AND ("credit_note_reason" IS NULL)) OR (("invoice_type" = 'Credit Note'::"text") AND ("original_invoice_id" IS NOT NULL) AND ("credit_note_reason" IS NOT NULL) AND ("btrim"("credit_note_reason") <> ''::"text")))),
    CONSTRAINT "customer_invoices_currency_code_check" CHECK (("currency_code" ~ '^[A-Z]{3}$'::"text")),
    CONSTRAINT "customer_invoices_discount_amount_check" CHECK (("discount_amount" >= (0)::numeric)),
    CONSTRAINT "customer_invoices_document_status_check" CHECK (("document_status" = ANY (ARRAY['Draft'::"text", 'Approved'::"text", 'Issued'::"text", 'Voided'::"text", 'Cancelled'::"text"]))),
    CONSTRAINT "customer_invoices_due_status_check" CHECK (("due_status" = ANY (ARRAY['Not Due'::"text", 'Due Soon'::"text", 'Due Today'::"text", 'Overdue'::"text", 'Settled'::"text", 'Not Applicable'::"text"]))),
    CONSTRAINT "customer_invoices_invoice_status_check" CHECK (("invoice_status" = ANY (ARRAY['Draft'::"text", 'Issued'::"text", 'Partially Paid'::"text", 'Paid'::"text", 'Overdue'::"text", 'Cancelled'::"text"]))),
    CONSTRAINT "customer_invoices_invoice_type_check" CHECK (("invoice_type" = ANY (ARRAY['Standard'::"text", 'Deposit'::"text", 'Progress'::"text", 'Variation'::"text", 'Final'::"text", 'Retention Release'::"text", 'Credit Note'::"text"]))),
    CONSTRAINT "customer_invoices_issue_audit_check" CHECK ((("document_status" <> ALL (ARRAY['Issued'::"text", 'Voided'::"text"])) OR (("issued_at" IS NOT NULL) AND ("issued_by" IS NOT NULL)))),
    CONSTRAINT "customer_invoices_line_amount_type_check" CHECK (("line_amount_type" = ANY (ARRAY['Exclusive'::"text", 'Inclusive'::"text", 'No Tax'::"text"]))),
    CONSTRAINT "customer_invoices_payment_status_check" CHECK (("payment_status" = ANY (ARRAY['Unpaid'::"text", 'Partially Paid'::"text", 'Paid'::"text", 'Overpaid'::"text"]))),
    CONSTRAINT "customer_invoices_payment_terms_days_check" CHECK ((("payment_terms_days" IS NULL) OR (("payment_terms_days" >= 0) AND ("payment_terms_days" <= 365)))),
    CONSTRAINT "customer_invoices_retention_release_context_check" CHECK (((("invoice_type" = 'Retention Release'::"text") AND ("retention_release_amount" > (0)::numeric) AND ("project_site_id" IS NOT NULL)) OR (("invoice_type" <> 'Retention Release'::"text") AND ("retention_release_amount" = (0)::numeric)))),
    CONSTRAINT "customer_invoices_void_audit_check" CHECK ((("document_status" <> 'Voided'::"text") OR (("voided_at" IS NOT NULL) AND ("voided_by" IS NOT NULL) AND ("void_reason" IS NOT NULL) AND ("btrim"("void_reason") <> ''::"text"))))
);


