CREATE OR REPLACE VIEW "public"."_customer_account_summary" WITH ("security_invoker"='false') AS
 SELECT "c"."customer_id",
    "c"."customer_code",
    "c"."customer_name",
    "c"."customer_type",
    "c"."abn",
    "c"."email",
    "c"."phone",
    COALESCE("cfs"."default_currency", 'AUD'::"text") AS "default_currency",
    "cfs"."payment_terms_type",
    "cfs"."payment_terms_days",
    "cfs"."credit_limit",
    "cfs"."is_account_on_hold",
    "cfs"."account_hold_reason",
    (COALESCE("inv"."draft_invoice_count", (0)::bigint))::integer AS "draft_invoice_count",
    (COALESCE("inv"."issued_invoice_count", (0)::bigint))::integer AS "issued_invoice_count",
    (COALESCE("inv"."overdue_invoice_count", (0)::bigint))::integer AS "overdue_invoice_count",
    (COALESCE("inv"."total_invoiced", (0)::numeric))::numeric(18,2) AS "total_invoiced",
    (COALESCE("inv"."total_paid", (0)::numeric))::numeric(18,2) AS "total_paid",
    (COALESCE("inv"."total_outstanding", (0)::numeric))::numeric(18,2) AS "total_outstanding",
    (COALESCE("inv"."current_outstanding", (0)::numeric))::numeric(18,2) AS "current_outstanding",
    (COALESCE("inv"."overdue_outstanding", (0)::numeric))::numeric(18,2) AS "overdue_outstanding",
    (COALESCE("pay"."recorded_payment_total", (0)::numeric))::numeric(18,2) AS "recorded_payment_total",
    (COALESCE("pay"."unallocated_credit", (0)::numeric))::numeric(18,2) AS "unallocated_credit",
    (
        CASE
            WHEN ("cfs"."credit_limit" IS NULL) THEN NULL::numeric
            ELSE GREATEST(("cfs"."credit_limit" - COALESCE("inv"."total_outstanding", (0)::numeric)), (0)::numeric)
        END)::numeric(18,2) AS "available_credit"
   FROM ((("public"."customers" "c"
     LEFT JOIN "public"."customer_financial_settings" "cfs" ON (("cfs"."customer_id" = "c"."customer_id")))
     LEFT JOIN LATERAL ( SELECT "count"(*) FILTER (WHERE ("i"."document_status" = 'Draft'::"text")) AS "draft_invoice_count",
            "count"(*) FILTER (WHERE ("i"."document_status" = 'Issued'::"text")) AS "issued_invoice_count",
            "count"(*) FILTER (WHERE (("i"."document_status" = 'Issued'::"text") AND ("i"."payment_status" <> ALL (ARRAY['Paid'::"text", 'Overpaid'::"text"])) AND ("i"."due_date" < CURRENT_DATE))) AS "overdue_invoice_count",
            "sum"("i"."total_amount") FILTER (WHERE (("i"."document_status" = 'Issued'::"text") AND ("i"."invoice_type" <> 'Credit Note'::"text"))) AS "total_invoiced",
            "sum"("i"."paid_amount") FILTER (WHERE (("i"."document_status" = 'Issued'::"text") AND ("i"."invoice_type" <> 'Credit Note'::"text"))) AS "total_paid",
            "sum"(GREATEST("i"."balance_amount", (0)::numeric)) FILTER (WHERE (("i"."document_status" = 'Issued'::"text") AND ("i"."invoice_type" <> 'Credit Note'::"text") AND ("i"."payment_status" <> ALL (ARRAY['Paid'::"text", 'Overpaid'::"text"])))) AS "total_outstanding",
            "sum"(GREATEST("i"."balance_amount", (0)::numeric)) FILTER (WHERE (("i"."document_status" = 'Issued'::"text") AND ("i"."invoice_type" <> 'Credit Note'::"text") AND ("i"."payment_status" <> ALL (ARRAY['Paid'::"text", 'Overpaid'::"text"])) AND ("i"."due_date" >= CURRENT_DATE))) AS "current_outstanding",
            "sum"(GREATEST("i"."balance_amount", (0)::numeric)) FILTER (WHERE (("i"."document_status" = 'Issued'::"text") AND ("i"."invoice_type" <> 'Credit Note'::"text") AND ("i"."payment_status" <> ALL (ARRAY['Paid'::"text", 'Overpaid'::"text"])) AND ("i"."due_date" < CURRENT_DATE))) AS "overdue_outstanding"
           FROM "public"."customer_invoices" "i"
          WHERE (("i"."customer_id" = "c"."customer_id") AND ("i"."is_deleted" = false))) "inv" ON (true))
     LEFT JOIN LATERAL ( SELECT "sum"("p"."amount") FILTER (WHERE ("p"."payment_status" = 'Recorded'::"text")) AS "recorded_payment_total",
            "sum"(GREATEST(("p"."amount" - COALESCE("public"."_payment_allocated_amount"("p"."customer_payment_id"), (0)::numeric)), (0)::numeric)) FILTER (WHERE ("p"."payment_status" = 'Recorded'::"text")) AS "unallocated_credit"
           FROM "public"."customer_payments" "p"
          WHERE (("p"."customer_id" = "c"."customer_id") AND ("p"."is_deleted" = false))) "pay" ON (true))
  WHERE ("c"."is_deleted" = false);


ALTER VIEW "public"."_customer_account_summary" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."_invoice_aging_summary" WITH ("security_invoker"='false') AS
 SELECT "i"."customer_id",
    "c"."customer_code",
    "c"."customer_name",
    "i"."currency_code",
    ("count"(*))::integer AS "open_invoice_count",
    ("sum"(GREATEST("i"."balance_amount", (0)::numeric)))::numeric(18,2) AS "total_outstanding",
    ("sum"(GREATEST("i"."balance_amount", (0)::numeric)) FILTER (WHERE ("i"."due_date" >= CURRENT_DATE)))::numeric(18,2) AS "current_amount",
    ("sum"(GREATEST("i"."balance_amount", (0)::numeric)) FILTER (WHERE (((CURRENT_DATE - "i"."due_date") >= 1) AND ((CURRENT_DATE - "i"."due_date") <= 30))))::numeric(18,2) AS "days_1_30",
    ("sum"(GREATEST("i"."balance_amount", (0)::numeric)) FILTER (WHERE (((CURRENT_DATE - "i"."due_date") >= 31) AND ((CURRENT_DATE - "i"."due_date") <= 60))))::numeric(18,2) AS "days_31_60",
    ("sum"(GREATEST("i"."balance_amount", (0)::numeric)) FILTER (WHERE (((CURRENT_DATE - "i"."due_date") >= 61) AND ((CURRENT_DATE - "i"."due_date") <= 90))))::numeric(18,2) AS "days_61_90",
    ("sum"(GREATEST("i"."balance_amount", (0)::numeric)) FILTER (WHERE ((CURRENT_DATE - "i"."due_date") > 90)))::numeric(18,2) AS "days_90_plus",
    "min"("i"."due_date") AS "oldest_due_date",
    "max"(GREATEST((CURRENT_DATE - "i"."due_date"), 0)) AS "maximum_days_overdue"
   FROM ("public"."customer_invoices" "i"
     JOIN "public"."customers" "c" ON ((("c"."customer_id" = "i"."customer_id") AND ("c"."is_deleted" = false))))
  WHERE (("i"."is_deleted" = false) AND ("i"."document_status" = 'Issued'::"text") AND ("i"."invoice_type" <> 'Credit Note'::"text") AND ("i"."payment_status" <> ALL (ARRAY['Paid'::"text", 'Overpaid'::"text"])) AND ("i"."balance_amount" > (0)::numeric))
  GROUP BY "i"."customer_id", "c"."customer_code", "c"."customer_name", "i"."currency_code";


ALTER VIEW "public"."_invoice_aging_summary" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."customer_addresses" (
    "address_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "customer_id" "uuid" NOT NULL,
    "address_type" "text" NOT NULL,
    "address_line1" "text" NOT NULL,
    "address_line2" "text",
    "suburb" "text",
    "state" "text",
    "postcode" "text",
    "country" "text" DEFAULT 'Australia'::"text" NOT NULL,
    "is_primary" boolean DEFAULT false NOT NULL,
    "is_active" boolean DEFAULT true NOT NULL,
    "is_deleted" boolean DEFAULT false NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_by" "uuid",
    "updated_by" "uuid",
    "deleted_at" timestamp with time zone
);


ALTER TABLE "public"."customer_addresses" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."customer_contacts" (
    "contact_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "customer_id" "uuid" NOT NULL,
    "contact_name" "text" NOT NULL,
    "position" "text",
    "phone" "text",
    "email" "text",
    "is_primary" boolean DEFAULT false NOT NULL,
    "is_active" boolean DEFAULT true NOT NULL,
    "is_deleted" boolean DEFAULT false NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_by" "uuid",
    "updated_by" "uuid",
    "deleted_at" timestamp with time zone
);


ALTER TABLE "public"."customer_contacts" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."projects" (
    "project_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "project_no" "text" NOT NULL,
    "customer_id" "uuid" NOT NULL,
    "project_name" "text" NOT NULL,
    "project_type" "text",
    "project_status" "text" DEFAULT 'Draft'::"text" NOT NULL,
    "quotation_id" "uuid",
    "price_book_id" "uuid",
    "contract_value" numeric(14,2) DEFAULT 0,
    "start_date" "date",
    "estimated_completion_date" "date",
    "actual_completion_date" "date",
    "notes" "text",
    "is_active" boolean DEFAULT true NOT NULL,
    "is_deleted" boolean DEFAULT false NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_by" "uuid" DEFAULT "auth"."uid"(),
    "updated_by" "uuid",
    "deleted_at" timestamp with time zone,
    CONSTRAINT "chk_projects_project_status" CHECK (("project_status" = ANY (ARRAY['Draft'::"text", 'Quoted'::"text", 'Approved'::"text", 'In Progress'::"text", 'On Hold'::"text", 'Completed'::"text", 'Cancelled'::"text"]))),
    CONSTRAINT "chk_projects_project_type" CHECK ((("project_type" IS NULL) OR ("project_type" = ANY (ARRAY['Residential'::"text", 'Commercial'::"text"]))))
);


ALTER TABLE "public"."projects" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."xero_export_logs" (
    "xero_export_log_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "source_type" "text" NOT NULL,
    "source_id" "uuid" NOT NULL,
    "export_status" "text" DEFAULT 'Pending'::"text" NOT NULL,
    "xero_reference_id" "text",
    "xero_reference_no" "text",
    "exported_at" timestamp with time zone,
    "exported_by" "uuid",
    "error_message" "text",
    "payload" "jsonb",
    "response" "jsonb",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "xero_export_logs_export_status_check" CHECK (("export_status" = ANY (ARRAY['Pending'::"text", 'Exported'::"text", 'Failed'::"text", 'Cancelled'::"text"]))),
    CONSTRAINT "xero_export_logs_source_type_check" CHECK (("source_type" = ANY (ARRAY['Customer Invoice'::"text", 'Customer Payment'::"text", 'Payroll Payment'::"text", 'Purchase Order'::"text"])))
);


ALTER TABLE "public"."xero_export_logs" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."_customer_profile_base" WITH ("security_invoker"='false') AS
 SELECT "c"."customer_id",
    "c"."customer_code",
    "c"."customer_name",
    "c"."customer_type",
    "c"."price_book_id",
    "c"."phone",
    "c"."email",
    "c"."abn",
    "c"."notes",
    "c"."is_active",
    "c"."created_at",
    "c"."updated_at",
    "primary_contact"."contact_id" AS "primary_contact_id",
    "primary_contact"."contact_name" AS "primary_contact_name",
    "primary_contact"."position" AS "primary_contact_position",
    "primary_contact"."phone" AS "primary_contact_phone",
    "primary_contact"."email" AS "primary_contact_email",
    (COALESCE("contact_data"."contact_count", (0)::bigint))::integer AS "contact_count",
    COALESCE("contact_data"."contacts", '[]'::"jsonb") AS "contacts",
    "primary_address"."address_id" AS "primary_address_id",
    "primary_address"."address_type" AS "primary_address_type",
    "primary_address"."address_line1" AS "primary_address_line1",
    "primary_address"."address_line2" AS "primary_address_line2",
    "primary_address"."suburb" AS "primary_address_suburb",
    "primary_address"."state" AS "primary_address_state",
    "primary_address"."postcode" AS "primary_address_postcode",
    "primary_address"."country" AS "primary_address_country",
    (COALESCE("address_data"."address_count", (0)::bigint))::integer AS "address_count",
    COALESCE("address_data"."addresses", '[]'::"jsonb") AS "addresses",
    "cfs"."customer_financial_setting_id",
    COALESCE("cfs"."default_currency", 'AUD'::"text") AS "default_currency",
    "cfs"."default_sales_account_code",
    "cfs"."default_tax_type",
    COALESCE("cfs"."line_amount_type", 'Exclusive'::"text") AS "line_amount_type",
    COALESCE("cfs"."discount_percent", (0)::numeric) AS "discount_percent",
    COALESCE("cfs"."payment_terms_type", 'Days After Bill'::"text") AS "payment_terms_type",
    COALESCE("cfs"."payment_terms_days", 14) AS "payment_terms_days",
    "cfs"."credit_limit",
    COALESCE("cfs"."is_account_on_hold", false) AS "is_account_on_hold",
    "cfs"."account_hold_reason",
    COALESCE("cfs"."invoice_delivery_method", 'Email'::"text") AS "invoice_delivery_method",
    COALESCE("cfs"."statement_delivery_method", 'Email'::"text") AS "statement_delivery_method",
    "cfs"."xero_contact_id",
    "cfs"."xero_contact_name",
    "cfs"."xero_contact_number",
    COALESCE("cfs"."xero_status", 'Not Connected'::"text") AS "xero_status",
    "cfs"."xero_last_synced_at",
    "cfs"."xero_sync_error",
    "cfs"."xero_branding_theme_id",
    "cfs"."xero_branding_theme_name",
    ("cfs"."customer_financial_setting_id" IS NOT NULL) AS "has_financial_settings",
    (COALESCE("project_data"."project_count", (0)::bigint))::integer AS "project_count",
    (COALESCE("project_data"."active_project_count", (0)::bigint))::integer AS "active_project_count",
    (COALESCE("project_data"."completed_project_count", (0)::bigint))::integer AS "completed_project_count",
    COALESCE("project_data"."projects", '[]'::"jsonb") AS "projects",
    COALESCE("account"."draft_invoice_count", 0) AS "draft_invoice_count",
    COALESCE("account"."issued_invoice_count", 0) AS "issued_invoice_count",
    COALESCE("account"."overdue_invoice_count", 0) AS "overdue_invoice_count",
    (COALESCE("account"."total_invoiced", (0)::numeric))::numeric(18,2) AS "total_invoiced",
    (COALESCE("account"."total_paid", (0)::numeric))::numeric(18,2) AS "total_paid",
    (COALESCE("account"."total_outstanding", (0)::numeric))::numeric(18,2) AS "total_outstanding",
    (COALESCE("account"."current_outstanding", (0)::numeric))::numeric(18,2) AS "current_outstanding",
    (COALESCE("account"."overdue_outstanding", (0)::numeric))::numeric(18,2) AS "overdue_outstanding",
    (COALESCE("account"."recorded_payment_total", (0)::numeric))::numeric(18,2) AS "recorded_payment_total",
    (COALESCE("account"."unallocated_credit", (0)::numeric))::numeric(18,2) AS "unallocated_credit",
    "account"."available_credit",
    (COALESCE("aging"."current_amount", (0)::numeric))::numeric(18,2) AS "aging_current",
    (COALESCE("aging"."days_1_30", (0)::numeric))::numeric(18,2) AS "aging_1_30",
    (COALESCE("aging"."days_31_60", (0)::numeric))::numeric(18,2) AS "aging_31_60",
    (COALESCE("aging"."days_61_90", (0)::numeric))::numeric(18,2) AS "aging_61_90",
    (COALESCE("aging"."days_90_plus", (0)::numeric))::numeric(18,2) AS "aging_90_plus",
    "aging"."oldest_due_date",
    COALESCE("aging"."maximum_days_overdue", 0) AS "maximum_days_overdue",
    (COALESCE("xero_log"."xero_export_count", (0)::bigint))::integer AS "xero_export_count",
    (COALESCE("xero_log"."xero_export_success_count", (0)::bigint))::integer AS "xero_export_success_count",
    (COALESCE("xero_log"."xero_export_failed_count", (0)::bigint))::integer AS "xero_export_failed_count",
    "xero_log"."last_xero_export_at",
    "xero_log"."last_xero_export_status",
    "xero_log"."last_xero_export_error",
    COALESCE("xero_log"."xero_export_history", '[]'::"jsonb") AS "xero_export_history"
   FROM ((((((((("public"."customers" "c"
     LEFT JOIN "public"."customer_financial_settings" "cfs" ON (("cfs"."customer_id" = "c"."customer_id")))
     LEFT JOIN LATERAL ( SELECT "cc"."contact_id",
            "cc"."contact_name",
            "cc"."position",
            "cc"."phone",
            "cc"."email"
           FROM "public"."customer_contacts" "cc"
          WHERE (("cc"."customer_id" = "c"."customer_id") AND ("cc"."is_deleted" = false) AND ("cc"."is_active" = true))
          ORDER BY "cc"."is_primary" DESC, "cc"."contact_name", "cc"."contact_id"
         LIMIT 1) "primary_contact" ON (true))
     LEFT JOIN LATERAL ( SELECT "count"(*) AS "contact_count",
            "jsonb_agg"("jsonb_build_object"('contact_id', "cc"."contact_id", 'contact_name', "cc"."contact_name", 'position', "cc"."position", 'phone', "cc"."phone", 'email', "cc"."email", 'is_primary', "cc"."is_primary", 'is_active', "cc"."is_active") ORDER BY "cc"."is_primary" DESC, "cc"."contact_name", "cc"."contact_id") AS "contacts"
           FROM "public"."customer_contacts" "cc"
          WHERE (("cc"."customer_id" = "c"."customer_id") AND ("cc"."is_deleted" = false) AND ("cc"."is_active" = true))) "contact_data" ON (true))
     LEFT JOIN LATERAL ( SELECT "ca"."address_id",
            "ca"."address_type",
            "ca"."address_line1",
            "ca"."address_line2",
            "ca"."suburb",
            "ca"."state",
            "ca"."postcode",
            "ca"."country"
           FROM "public"."customer_addresses" "ca"
          WHERE (("ca"."customer_id" = "c"."customer_id") AND ("ca"."is_deleted" = false) AND ("ca"."is_active" = true))
          ORDER BY "ca"."is_primary" DESC,
                CASE
                    WHEN ("lower"("ca"."address_type") = 'billing'::"text") THEN 0
                    WHEN ("lower"("ca"."address_type") = 'street'::"text") THEN 1
                    WHEN ("lower"("ca"."address_type") = 'postal'::"text") THEN 2
                    ELSE 3
                END, "ca"."address_id"
         LIMIT 1) "primary_address" ON (true))
     LEFT JOIN LATERAL ( SELECT "count"(*) AS "address_count",
            "jsonb_agg"("jsonb_build_object"('address_id', "ca"."address_id", 'address_type', "ca"."address_type", 'address_line1', "ca"."address_line1", 'address_line2', "ca"."address_line2", 'suburb', "ca"."suburb", 'state', "ca"."state", 'postcode', "ca"."postcode", 'country', "ca"."country", 'is_primary', "ca"."is_primary", 'is_active', "ca"."is_active") ORDER BY "ca"."is_primary" DESC, "ca"."address_type", "ca"."address_id") AS "addresses"
           FROM "public"."customer_addresses" "ca"
          WHERE (("ca"."customer_id" = "c"."customer_id") AND ("ca"."is_deleted" = false) AND ("ca"."is_active" = true))) "address_data" ON (true))
     LEFT JOIN LATERAL ( SELECT "count"(*) AS "project_count",
            "count"(*) FILTER (WHERE ("p"."project_status" = ANY (ARRAY['Approved'::"text", 'In Progress'::"text", 'On Hold'::"text"]))) AS "active_project_count",
            "count"(*) FILTER (WHERE ("p"."project_status" = 'Completed'::"text")) AS "completed_project_count",
            "jsonb_agg"("jsonb_build_object"('project_id', "p"."project_id", 'project_no', "p"."project_no", 'project_name', "p"."project_name", 'project_type', "p"."project_type", 'project_status', "p"."project_status", 'contract_value', "p"."contract_value", 'start_date', "p"."start_date", 'estimated_completion_date', "p"."estimated_completion_date", 'actual_completion_date', "p"."actual_completion_date") ORDER BY "p"."created_at" DESC, "p"."project_no") AS "projects"
           FROM "public"."projects" "p"
          WHERE (("p"."customer_id" = "c"."customer_id") AND ("p"."is_deleted" = false))) "project_data" ON (true))
     LEFT JOIN "public"."_customer_account_summary" "account" ON (("account"."customer_id" = "c"."customer_id")))
     LEFT JOIN LATERAL ( SELECT "sum"("a"."current_amount") AS "current_amount",
            "sum"("a"."days_1_30") AS "days_1_30",
            "sum"("a"."days_31_60") AS "days_31_60",
            "sum"("a"."days_61_90") AS "days_61_90",
            "sum"("a"."days_90_plus") AS "days_90_plus",
            "min"("a"."oldest_due_date") AS "oldest_due_date",
            "max"("a"."maximum_days_overdue") AS "maximum_days_overdue"
           FROM "public"."_invoice_aging_summary" "a"
          WHERE ("a"."customer_id" = "c"."customer_id")) "aging" ON (true))
     LEFT JOIN LATERAL ( WITH "customer_sources" AS (
                 SELECT 'Customer Invoice'::"text" AS "source_type",
                    "i"."customer_invoice_id" AS "source_id"
                   FROM "public"."customer_invoices" "i"
                  WHERE (("i"."customer_id" = "c"."customer_id") AND ("i"."is_deleted" = false))
                UNION ALL
                 SELECT 'Customer Payment'::"text" AS "text",
                    "p"."customer_payment_id"
                   FROM "public"."customer_payments" "p"
                  WHERE (("p"."customer_id" = "c"."customer_id") AND ("p"."is_deleted" = false))
                ), "logs" AS (
                 SELECT "xl"."xero_export_log_id",
                    "xl"."source_type",
                    "xl"."source_id",
                    "xl"."export_status",
                    "xl"."xero_reference_id",
                    "xl"."xero_reference_no",
                    "xl"."exported_at",
                    "xl"."exported_by",
                    "xl"."error_message",
                    "xl"."payload",
                    "xl"."response",
                    "xl"."created_at",
                    "xl"."updated_at"
                   FROM ("public"."xero_export_logs" "xl"
                     JOIN "customer_sources" "cs" ON ((("cs"."source_type" = "xl"."source_type") AND ("cs"."source_id" = "xl"."source_id"))))
                )
         SELECT "count"(*) AS "xero_export_count",
            "count"(*) FILTER (WHERE ("l"."export_status" = 'Exported'::"text")) AS "xero_export_success_count",
            "count"(*) FILTER (WHERE ("l"."export_status" = 'Failed'::"text")) AS "xero_export_failed_count",
            ( SELECT COALESCE("l_1"."exported_at", "l_1"."created_at") AS "coalesce"
                   FROM "logs" "l_1"
                  ORDER BY "l_1"."created_at" DESC
                 LIMIT 1) AS "last_xero_export_at",
            ( SELECT "l_1"."export_status"
                   FROM "logs" "l_1"
                  ORDER BY "l_1"."created_at" DESC
                 LIMIT 1) AS "last_xero_export_status",
            ( SELECT "l_1"."error_message"
                   FROM "logs" "l_1"
                  ORDER BY "l_1"."created_at" DESC
                 LIMIT 1) AS "last_xero_export_error",
            "jsonb_agg"("jsonb_build_object"('xero_export_log_id', "l"."xero_export_log_id", 'source_type', "l"."source_type", 'source_id', "l"."source_id", 'export_status', "l"."export_status", 'xero_reference_id', "l"."xero_reference_id", 'xero_reference_no', "l"."xero_reference_no", 'exported_at', "l"."exported_at", 'error_message', "l"."error_message", 'created_at', "l"."created_at") ORDER BY "l"."created_at" DESC) AS "xero_export_history"
           FROM "logs" "l") "xero_log" ON (true))
  WHERE ("c"."is_deleted" = false);


ALTER VIEW "public"."_customer_profile_base" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."_customer_xero_readiness" WITH ("security_invoker"='false') AS
 SELECT "customer_id",
    "customer_code",
    "customer_name",
    (("customer_name" IS NOT NULL) AND ("btrim"("customer_name") <> ''::"text")) AS "has_contact_name",
    (COALESCE(NULLIF("primary_contact_email", ''::"text"), NULLIF("email", ''::"text")) IS NOT NULL) AS "has_email",
    (COALESCE(NULLIF("primary_contact_phone", ''::"text"), NULLIF("phone", ''::"text")) IS NOT NULL) AS "has_phone",
    ("address_count" > 0) AS "has_address",
    "has_financial_settings",
    ("default_currency" ~ '^[A-Z]{3}$'::"text") AS "has_currency",
    (("payment_terms_type" IS NOT NULL) AND ("payment_terms_days" IS NOT NULL)) AS "has_payment_terms",
    (("default_sales_account_code" IS NOT NULL) AND ("btrim"("default_sales_account_code") <> ''::"text")) AS "has_sales_account",
    (("default_tax_type" IS NOT NULL) AND ("btrim"("default_tax_type") <> ''::"text")) AS "has_tax_type",
    ("xero_contact_id" IS NOT NULL) AS "has_xero_contact_id",
    (("xero_contact_name" IS NOT NULL) AND ("btrim"("xero_contact_name") <> ''::"text")) AS "has_xero_contact_name",
        CASE
            WHEN ("has_financial_settings" = false) THEN false
            WHEN ("address_count" = 0) THEN false
            WHEN ("default_currency" IS NULL) THEN false
            WHEN ("payment_terms_type" IS NULL) THEN false
            WHEN ("payment_terms_days" IS NULL) THEN false
            ELSE true
        END AS "is_xero_minimum_ready",
        CASE
            WHEN ("has_financial_settings" = false) THEN false
            WHEN ("address_count" = 0) THEN false
            WHEN ("default_currency" IS NULL) THEN false
            WHEN ("payment_terms_type" IS NULL) THEN false
            WHEN ("payment_terms_days" IS NULL) THEN false
            WHEN ("default_sales_account_code" IS NULL) THEN false
            WHEN ("default_tax_type" IS NULL) THEN false
            ELSE true
        END AS "is_xero_accounting_ready",
    ( SELECT "jsonb_agg"("issues"."issue" ORDER BY "issues"."sort_order") AS "jsonb_agg"
           FROM ( VALUES (10,
                        CASE
                            WHEN ("b"."has_financial_settings" = false) THEN 'Financial settings are not configured.'::"text"
                            ELSE NULL::"text"
                        END), (20,
                        CASE
                            WHEN ("b"."address_count" = 0) THEN 'No active Customer address is configured.'::"text"
                            ELSE NULL::"text"
                        END), (30,
                        CASE
                            WHEN (COALESCE(NULLIF("b"."primary_contact_email", ''::"text"), NULLIF("b"."email", ''::"text")) IS NULL) THEN 'No Customer or primary Contact email is configured.'::"text"
                            ELSE NULL::"text"
                        END), (40,
                        CASE
                            WHEN (COALESCE(NULLIF("b"."primary_contact_phone", ''::"text"), NULLIF("b"."phone", ''::"text")) IS NULL) THEN 'No Customer or primary Contact phone is configured.'::"text"
                            ELSE NULL::"text"
                        END), (50,
                        CASE
                            WHEN ("b"."default_sales_account_code" IS NULL) THEN 'Default sales account code is not configured.'::"text"
                            ELSE NULL::"text"
                        END), (60,
                        CASE
                            WHEN ("b"."default_tax_type" IS NULL) THEN 'Default tax type is not configured.'::"text"
                            ELSE NULL::"text"
                        END), (70,
                        CASE
                            WHEN ("b"."xero_contact_id" IS NULL) THEN 'Customer is not linked to a Xero Contact ID.'::"text"
                            ELSE NULL::"text"
                        END), (80,'Customer bank account fields are not present in the current schema.'::"text")) "issues"("sort_order", "issue")
          WHERE ("issues"."issue" IS NOT NULL)) AS "readiness_issues"
   FROM "public"."_customer_profile_base" "b";


