CREATE TABLE IF NOT EXISTS "public"."customer_invoice_items" (
    "customer_invoice_item_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "customer_invoice_id" "uuid" NOT NULL,
    "line_no" integer NOT NULL,
    "description" "text" NOT NULL,
    "quantity" numeric(12,2) DEFAULT 0 NOT NULL,
    "unit_price" numeric(12,2) DEFAULT 0 NOT NULL,
    "tax_rate" numeric(5,2) DEFAULT 0,
    "tax_amount" numeric(12,2) DEFAULT 0,
    "line_total" numeric(14,2) DEFAULT 0 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "is_deleted" boolean DEFAULT false NOT NULL,
    "deleted_at" timestamp with time zone,
    "created_by" "uuid" DEFAULT "auth"."uid"(),
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_by" "uuid",
    "line_type" "text" DEFAULT 'Manual'::"text" NOT NULL,
    "product_id" "uuid",
    "product_code_snapshot" "text",
    "product_name_snapshot" "text",
    "project_area_id" "uuid",
    "sales_uom_code" "text",
    "base_uom_code" "text",
    "conversion_factor" numeric(18,6),
    "base_quantity" numeric(18,6),
    "allow_fractional_quantity" boolean DEFAULT true NOT NULL,
    "price_book_id" "uuid",
    "price_book_line_id" "uuid",
    "price_source" "text" DEFAULT 'Manual'::"text" NOT NULL,
    "original_unit_price" numeric(18,2),
    "line_subtotal" numeric(18,2) DEFAULT 0 NOT NULL,
    "discount_percent" numeric(7,4) DEFAULT 0 NOT NULL,
    "discount_amount" numeric(18,2) DEFAULT 0 NOT NULL,
    "notes" "text",
    CONSTRAINT "customer_invoice_items_amounts_check" CHECK ((("quantity" > (0)::numeric) AND ("unit_price" >= (0)::numeric) AND ("line_subtotal" >= (0)::numeric) AND ("discount_amount" >= (0)::numeric) AND ("tax_amount" >= (0)::numeric) AND ("line_total" >= (0)::numeric) AND (("original_unit_price" IS NULL) OR ("original_unit_price" >= (0)::numeric)))),
    CONSTRAINT "customer_invoice_items_discount_percent_check" CHECK ((("discount_percent" >= (0)::numeric) AND ("discount_percent" <= (100)::numeric))),
    CONSTRAINT "customer_invoice_items_line_type_check" CHECK (("line_type" = ANY (ARRAY['Product'::"text", 'Service'::"text", 'Labour'::"text", 'Material'::"text", 'Transport'::"text", 'Manual'::"text", 'Retention'::"text", 'Credit'::"text"]))),
    CONSTRAINT "customer_invoice_items_price_book_snapshot_check" CHECK ((("price_book_line_id" IS NULL) OR (("price_book_id" IS NOT NULL) AND ("product_id" IS NOT NULL) AND (("price_source" = 'Price Book'::"text") OR (("price_source" = 'Manual'::"text") AND ("original_unit_price" IS NOT NULL) AND ("original_unit_price" >= (0)::numeric)))))),
    CONSTRAINT "customer_invoice_items_price_source_check" CHECK (("price_source" = ANY (ARRAY['Price Book'::"text", 'Product Default'::"text", 'Source Snapshot'::"text", 'Manual'::"text", 'Retention'::"text", 'Credit Note'::"text"]))),
    CONSTRAINT "customer_invoice_items_product_snapshot_check" CHECK ((("product_id" IS NULL) OR (("product_code_snapshot" IS NOT NULL) AND ("btrim"("product_code_snapshot") <> ''::"text") AND ("product_name_snapshot" IS NOT NULL) AND ("btrim"("product_name_snapshot") <> ''::"text") AND ("sales_uom_code" IS NOT NULL) AND ("base_uom_code" IS NOT NULL) AND ("conversion_factor" IS NOT NULL) AND ("base_quantity" IS NOT NULL)))),
    CONSTRAINT "customer_invoice_items_uom_snapshot_check" CHECK (((("sales_uom_code" IS NULL) AND ("base_uom_code" IS NULL) AND ("conversion_factor" IS NULL) AND ("base_quantity" IS NULL)) OR (("sales_uom_code" IS NOT NULL) AND ("base_uom_code" IS NOT NULL) AND ("conversion_factor" IS NOT NULL) AND ("conversion_factor" > (0)::numeric) AND ("base_quantity" IS NOT NULL) AND ("base_quantity" > (0)::numeric))))
);


ALTER TABLE "public"."customer_invoice_items" OWNER TO "postgres";


COMMENT ON COLUMN "public"."customer_invoice_items"."product_code_snapshot" IS 'Immutable Product Code snapshot used by the Invoice document.';



COMMENT ON COLUMN "public"."customer_invoice_items"."product_name_snapshot" IS 'Immutable Product Name snapshot used by the Invoice document.';



COMMENT ON COLUMN "public"."customer_invoice_items"."sales_uom_code" IS 'Invoice quantity UOM selected from the Product sales UOM structure.';



COMMENT ON COLUMN "public"."customer_invoice_items"."base_uom_code" IS 'Product Base UOM snapshot.';



COMMENT ON COLUMN "public"."customer_invoice_items"."conversion_factor" IS 'Snapshot factor from Sales UOM to Base UOM.';



COMMENT ON COLUMN "public"."customer_invoice_items"."base_quantity" IS 'Server-calculated base quantity = quantity × conversion_factor.';



COMMENT ON COLUMN "public"."customer_invoice_items"."price_source" IS 'Origin of the resolved Invoice unit price.';



COMMENT ON COLUMN "public"."customer_invoice_items"."original_unit_price" IS 'Resolved unit price before any permitted manual override.';



COMMENT ON CONSTRAINT "customer_invoice_items_price_book_snapshot_check" ON "public"."customer_invoice_items" IS 'Allows direct Price Book pricing or an authorised Manual unit-price override while preserving the original Price Book and Price Book Line lineage.';



