CREATE OR REPLACE VIEW "public"."_invoice_reporting_base" WITH ("security_invoker"='false') AS
 SELECT "i"."customer_invoice_id",
    "i"."invoice_no",
    "i"."invoice_type",
    "i"."document_status",
    "i"."payment_status",
    "i"."due_status",
    "i"."invoice_status" AS "legacy_invoice_status",
    "i"."customer_id",
    "c"."customer_code",
    "c"."customer_name",
    "c"."customer_type",
    "c"."abn" AS "customer_abn",
    "c"."email" AS "customer_email",
    "c"."phone" AS "customer_phone",
    "i"."project_id",
    "p"."project_no",
    "p"."project_name",
    "i"."project_site_id",
    "ps"."site_code",
    "ps"."site_name",
    "i"."invoice_date",
    "i"."due_date",
    "i"."subtotal_amount",
    "i"."tax_amount",
    "i"."total_amount",
    "i"."paid_amount",
    "i"."balance_amount",
    "i"."retention_release_amount",
    "i"."currency_code",
    "i"."customer_reference",
    "i"."notes",
    "i"."original_invoice_id",
    "original"."invoice_no" AS "original_invoice_no",
    "i"."credit_note_reason",
    "i"."approved_at",
    "i"."approved_by",
    "i"."issued_at",
    "i"."issued_by",
    "i"."voided_at",
    "i"."voided_by",
    "i"."void_reason",
    "i"."cancelled_at",
    "i"."cancelled_by",
    "i"."cancellation_reason",
    "i"."xero_exported",
    "i"."xero_exported_at",
    (COALESCE("lines"."active_line_count", (0)::bigint))::integer AS "active_line_count",
    (COALESCE("sources"."active_source_count", (0)::bigint))::integer AS "active_source_count",
    COALESCE("sources"."source_types", '[]'::"jsonb") AS "source_types",
        CASE
            WHEN (("i"."document_status" <> 'Issued'::"text") OR ("i"."payment_status" = ANY (ARRAY['Paid'::"text", 'Overpaid'::"text"]))) THEN 0
            ELSE GREATEST((CURRENT_DATE - "i"."due_date"), 0)
        END AS "days_overdue",
        CASE
            WHEN (("i"."document_status" <> 'Issued'::"text") OR ("i"."payment_status" = ANY (ARRAY['Paid'::"text", 'Overpaid'::"text"]))) THEN 'Not Applicable'::"text"
            WHEN ("i"."due_date" >= CURRENT_DATE) THEN 'Current'::"text"
            WHEN (((CURRENT_DATE - "i"."due_date") >= 1) AND ((CURRENT_DATE - "i"."due_date") <= 30)) THEN '1-30 Days'::"text"
            WHEN (((CURRENT_DATE - "i"."due_date") >= 31) AND ((CURRENT_DATE - "i"."due_date") <= 60)) THEN '31-60 Days'::"text"
            WHEN (((CURRENT_DATE - "i"."due_date") >= 61) AND ((CURRENT_DATE - "i"."due_date") <= 90)) THEN '61-90 Days'::"text"
            ELSE '90+ Days'::"text"
        END AS "aging_bucket",
    "i"."created_at",
    "i"."created_by",
    "i"."updated_at",
    "i"."updated_by"
   FROM (((((("public"."customer_invoices" "i"
     JOIN "public"."customers" "c" ON ((("c"."customer_id" = "i"."customer_id") AND ("c"."is_deleted" = false))))
     LEFT JOIN "public"."projects" "p" ON ((("p"."project_id" = "i"."project_id") AND ("p"."is_deleted" = false))))
     LEFT JOIN "public"."project_sites" "ps" ON ((("ps"."site_id" = "i"."project_site_id") AND ("ps"."is_deleted" = false))))
     LEFT JOIN "public"."customer_invoices" "original" ON (("original"."customer_invoice_id" = "i"."original_invoice_id")))
     LEFT JOIN LATERAL ( SELECT "count"(*) AS "active_line_count"
           FROM "public"."customer_invoice_items" "li"
          WHERE (("li"."customer_invoice_id" = "i"."customer_invoice_id") AND ("li"."is_deleted" = false))) "lines" ON (true))
     LEFT JOIN LATERAL ( SELECT "count"(*) AS "active_source_count",
            "jsonb_agg"(DISTINCT "s"."source_type" ORDER BY "s"."source_type") AS "source_types"
           FROM "public"."invoice_sources" "s"
          WHERE (("s"."customer_invoice_id" = "i"."customer_invoice_id") AND ("s"."is_deleted" = false))) "sources" ON (true))
  WHERE ("i"."is_deleted" = false);


ALTER VIEW "public"."_invoice_reporting_base" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."customer_payment_allocations" (
    "customer_payment_allocation_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "customer_payment_id" "uuid" NOT NULL,
    "customer_invoice_id" "uuid" NOT NULL,
    "allocated_amount" numeric(14,2) NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "is_deleted" boolean DEFAULT false NOT NULL,
    "deleted_at" timestamp with time zone,
    "created_by" "uuid" DEFAULT "auth"."uid"(),
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_by" "uuid",
    "reversed_at" timestamp with time zone,
    "reversed_by" "uuid",
    "reversal_reason" "text",
    CONSTRAINT "customer_payment_allocations_amount_positive_check" CHECK (("allocated_amount" > (0)::numeric)),
    CONSTRAINT "customer_payment_allocations_reversal_audit_check" CHECK ((("reversed_at" IS NULL) OR (("reversed_by" IS NOT NULL) AND ("reversal_reason" IS NOT NULL) AND ("btrim"("reversal_reason") <> ''::"text"))))
);


ALTER TABLE "public"."customer_payment_allocations" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."_payment_reporting_base" WITH ("security_invoker"='false') AS
 SELECT "p"."customer_payment_id",
    "p"."payment_no",
    "p"."customer_id",
    "c"."customer_code",
    "c"."customer_name",
    "p"."payment_date",
    "p"."payment_method",
    "p"."amount",
    "p"."currency_code",
    "p"."reference_no",
    "p"."notes",
    "p"."payment_status",
    (COALESCE("allocation"."active_allocation_count", (0)::bigint))::integer AS "active_allocation_count",
    (COALESCE("allocation"."allocated_amount", (0)::numeric))::numeric(18,2) AS "allocated_amount",
    (GREATEST(("p"."amount" - COALESCE("allocation"."allocated_amount", (0)::numeric)), (0)::numeric))::numeric(18,2) AS "unallocated_amount",
    COALESCE("allocation"."allocated_invoices", '[]'::"jsonb") AS "allocated_invoices",
    "p"."original_payment_id",
    "original"."payment_no" AS "original_payment_no",
    "p"."reversed_at",
    "p"."reversed_by",
    "p"."reversal_reason",
    "p"."xero_exported",
    "p"."xero_exported_at",
    "p"."created_at",
    "p"."created_by",
    "p"."updated_at",
    "p"."updated_by"
   FROM ((("public"."customer_payments" "p"
     JOIN "public"."customers" "c" ON ((("c"."customer_id" = "p"."customer_id") AND ("c"."is_deleted" = false))))
     LEFT JOIN "public"."customer_payments" "original" ON (("original"."customer_payment_id" = "p"."original_payment_id")))
     LEFT JOIN LATERAL ( SELECT "count"(*) AS "active_allocation_count",
            "sum"("a"."allocated_amount") AS "allocated_amount",
            "jsonb_agg"("jsonb_build_object"('customer_payment_allocation_id', "a"."customer_payment_allocation_id", 'customer_invoice_id', "a"."customer_invoice_id", 'invoice_no', "i"."invoice_no", 'allocated_amount', "a"."allocated_amount") ORDER BY "i"."invoice_no") AS "allocated_invoices"
           FROM ("public"."customer_payment_allocations" "a"
             JOIN "public"."customer_invoices" "i" ON (("i"."customer_invoice_id" = "a"."customer_invoice_id")))
          WHERE (("a"."customer_payment_id" = "p"."customer_payment_id") AND ("a"."is_deleted" = false) AND ("a"."reversed_at" IS NULL))) "allocation" ON (true))
  WHERE ("p"."is_deleted" = false);


ALTER VIEW "public"."_payment_reporting_base" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."retention_ledger" (
    "retention_ledger_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "site_id" "uuid" NOT NULL,
    "customer_invoice_id" "uuid",
    "source_invoice_id" "uuid",
    "ledger_entry_type" "text" NOT NULL,
    "amount" numeric(18,2) NOT NULL,
    "entry_date" "date" DEFAULT CURRENT_DATE NOT NULL,
    "description" "text" NOT NULL,
    "reference_no" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_by" "uuid" DEFAULT "auth"."uid"(),
    CONSTRAINT "retention_ledger_amount_positive_check" CHECK (("amount" > (0)::numeric)),
    CONSTRAINT "retention_ledger_context_check" CHECK (((("ledger_entry_type" = 'Retained'::"text") AND ("source_invoice_id" IS NOT NULL)) OR (("ledger_entry_type" = 'Released'::"text") AND ("customer_invoice_id" IS NOT NULL)) OR ("ledger_entry_type" = ANY (ARRAY['Adjustment Increase'::"text", 'Adjustment Decrease'::"text", 'Reversal'::"text"])))),
    CONSTRAINT "retention_ledger_description_check" CHECK (("btrim"("description") <> ''::"text")),
    CONSTRAINT "retention_ledger_entry_type_check" CHECK (("ledger_entry_type" = ANY (ARRAY['Retained'::"text", 'Released'::"text", 'Adjustment Increase'::"text", 'Adjustment Decrease'::"text", 'Reversal'::"text"])))
);


ALTER TABLE "public"."retention_ledger" OWNER TO "postgres";


COMMENT ON TABLE "public"."retention_ledger" IS 'Append-only ledger of retained, released, adjusted and reversed retention amounts.';



CREATE TABLE IF NOT EXISTS "public"."site_retention_settings" (
    "site_retention_setting_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "site_id" "uuid" NOT NULL,
    "retention_method" "text" DEFAULT 'Percentage'::"text" NOT NULL,
    "retention_percent" numeric(9,4),
    "retention_fixed_amount" numeric(18,2),
    "retention_cap_amount" numeric(18,2),
    "is_enabled" boolean DEFAULT false NOT NULL,
    "notes" "text",
    "is_active" boolean DEFAULT true NOT NULL,
    "is_deleted" boolean DEFAULT false NOT NULL,
    "deleted_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_by" "uuid" DEFAULT "auth"."uid"(),
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_by" "uuid",
    CONSTRAINT "site_retention_settings_amounts_check" CHECK (((("retention_fixed_amount" IS NULL) OR ("retention_fixed_amount" >= (0)::numeric)) AND (("retention_cap_amount" IS NULL) OR ("retention_cap_amount" >= (0)::numeric)))),
    CONSTRAINT "site_retention_settings_method_check" CHECK (("retention_method" = ANY (ARRAY['Percentage'::"text", 'Fixed'::"text"]))),
    CONSTRAINT "site_retention_settings_method_values_check" CHECK (((("retention_method" = 'Percentage'::"text") AND ("retention_percent" IS NOT NULL) AND ("retention_fixed_amount" IS NULL)) OR (("retention_method" = 'Fixed'::"text") AND ("retention_fixed_amount" IS NOT NULL) AND ("retention_percent" IS NULL)))),
    CONSTRAINT "site_retention_settings_percent_check" CHECK ((("retention_percent" IS NULL) OR (("retention_percent" >= (0)::numeric) AND ("retention_percent" <= (100)::numeric))))
);


ALTER TABLE "public"."site_retention_settings" OWNER TO "postgres";


COMMENT ON TABLE "public"."site_retention_settings" IS 'One active retention configuration per project site. Phase 1 supports percentage or fixed retention.';



CREATE OR REPLACE VIEW "public"."_site_retention_summary" WITH ("security_invoker"='false') AS
 SELECT "ps"."site_id",
    "ps"."site_code",
    "ps"."site_name",
    "p"."project_id",
    "p"."project_no",
    "p"."project_name",
    "p"."customer_id",
    "c"."customer_code",
    "c"."customer_name",
    "srs"."is_enabled",
    "srs"."retention_method",
    "srs"."retention_percent",
    "srs"."retention_fixed_amount",
    "srs"."retention_cap_amount",
    "srs"."notes" AS "retention_notes",
    (COALESCE("ledger"."retained_amount", (0)::numeric))::numeric(18,2) AS "retained_amount",
    (COALESCE("ledger"."released_amount", (0)::numeric))::numeric(18,2) AS "released_amount",
    (COALESCE("ledger"."adjustment_increase_amount", (0)::numeric))::numeric(18,2) AS "adjustment_increase_amount",
    (COALESCE("ledger"."adjustment_decrease_amount", (0)::numeric))::numeric(18,2) AS "adjustment_decrease_amount",
    (COALESCE("ledger"."reversal_amount", (0)::numeric))::numeric(18,2) AS "reversal_amount",
    (((((COALESCE("ledger"."retained_amount", (0)::numeric) + COALESCE("ledger"."adjustment_increase_amount", (0)::numeric)) - COALESCE("ledger"."released_amount", (0)::numeric)) - COALESCE("ledger"."adjustment_decrease_amount", (0)::numeric)) - COALESCE("ledger"."reversal_amount", (0)::numeric)))::numeric(18,2) AS "available_retention_balance",
    (COALESCE("ledger"."ledger_entry_count", (0)::bigint))::integer AS "ledger_entry_count",
    "ledger"."last_entry_date"
   FROM (((("public"."project_sites" "ps"
     JOIN "public"."projects" "p" ON ((("p"."project_id" = "ps"."project_id") AND ("p"."is_deleted" = false))))
     JOIN "public"."customers" "c" ON ((("c"."customer_id" = "p"."customer_id") AND ("c"."is_deleted" = false))))
     LEFT JOIN "public"."site_retention_settings" "srs" ON ((("srs"."site_id" = "ps"."site_id") AND ("srs"."is_deleted" = false) AND ("srs"."is_active" = true))))
     LEFT JOIN LATERAL ( SELECT "sum"("rl"."amount") FILTER (WHERE ("rl"."ledger_entry_type" = 'Retained'::"text")) AS "retained_amount",
            "sum"("rl"."amount") FILTER (WHERE ("rl"."ledger_entry_type" = 'Released'::"text")) AS "released_amount",
            "sum"("rl"."amount") FILTER (WHERE ("rl"."ledger_entry_type" = 'Adjustment Increase'::"text")) AS "adjustment_increase_amount",
            "sum"("rl"."amount") FILTER (WHERE ("rl"."ledger_entry_type" = 'Adjustment Decrease'::"text")) AS "adjustment_decrease_amount",
            "sum"("rl"."amount") FILTER (WHERE ("rl"."ledger_entry_type" = 'Reversal'::"text")) AS "reversal_amount",
            "count"(*) AS "ledger_entry_count",
            "max"("rl"."entry_date") AS "last_entry_date"
           FROM "public"."retention_ledger" "rl"
          WHERE ("rl"."site_id" = "ps"."site_id")) "ledger" ON (true))
  WHERE ("ps"."is_deleted" = false);


ALTER VIEW "public"."_site_retention_summary" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."variations" (
    "variation_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "variation_no" "text" NOT NULL,
    "quotation_id" "uuid" NOT NULL,
    "accepted_revision_id" "uuid",
    "customer_id" "uuid" NOT NULL,
    "project_id" "uuid" NOT NULL,
    "project_site_id" "uuid" NOT NULL,
    "variation_status" "text" DEFAULT 'Draft'::"text" NOT NULL,
    "variation_reason" "text" NOT NULL,
    "notes" "text",
    "issue_date" "date" DEFAULT CURRENT_DATE NOT NULL,
    "valid_until" "date",
    "subtotal" numeric(18,2) DEFAULT 0 NOT NULL,
    "discount_amount" numeric(18,2) DEFAULT 0 NOT NULL,
    "tax_amount" numeric(18,2) DEFAULT 0 NOT NULL,
    "total_amount" numeric(18,2) DEFAULT 0 NOT NULL,
    "sent_at" timestamp with time zone,
    "sent_by" "uuid",
    "accepted_at" timestamp with time zone,
    "accepted_by" "uuid",
    "rejected_at" timestamp with time zone,
    "rejected_by" "uuid",
    "rejection_reason" "text",
    "cancelled_at" timestamp with time zone,
    "cancelled_by" "uuid",
    "cancellation_reason" "text",
    "is_active" boolean DEFAULT true NOT NULL,
    "is_deleted" boolean DEFAULT false NOT NULL,
    "deleted_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_by" "uuid" DEFAULT "auth"."uid"(),
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_by" "uuid",
    CONSTRAINT "variations_amounts_check" CHECK ((("subtotal" >= (0)::numeric) AND ("discount_amount" >= (0)::numeric) AND ("tax_amount" >= (0)::numeric) AND ("total_amount" >= (0)::numeric))),
    CONSTRAINT "variations_cancellation_reason_check" CHECK ((("variation_status" <> 'Cancelled'::"text") OR (NULLIF("btrim"("cancellation_reason"), ''::"text") IS NOT NULL))),
    CONSTRAINT "variations_dates_check" CHECK ((("valid_until" IS NULL) OR ("valid_until" >= "issue_date"))),
    CONSTRAINT "variations_reason_check" CHECK ((NULLIF("btrim"("variation_reason"), ''::"text") IS NOT NULL)),
    CONSTRAINT "variations_rejection_reason_check" CHECK ((("variation_status" <> 'Rejected'::"text") OR (NULLIF("btrim"("rejection_reason"), ''::"text") IS NOT NULL))),
    CONSTRAINT "variations_soft_delete_check" CHECK (((("is_deleted" = false) AND ("deleted_at" IS NULL)) OR (("is_deleted" = true) AND ("deleted_at" IS NOT NULL)))),
    CONSTRAINT "variations_status_check" CHECK (("variation_status" = ANY (ARRAY['Draft'::"text", 'Sent'::"text", 'Accepted'::"text", 'Rejected'::"text", 'Cancelled'::"text"])))
);


