CREATE OR REPLACE VIEW "public"."_project_financial_summary" WITH ("security_invoker"='false') AS
 SELECT "p"."project_id",
    "p"."project_no",
    "p"."project_name",
    "p"."project_status",
    "p"."customer_id",
    "c"."customer_code",
    "c"."customer_name",
    (COALESCE("p"."contract_value", (0)::numeric))::numeric(18,2) AS "original_contract_value",
    (COALESCE("variation"."approved_variations", (0)::numeric))::numeric(18,2) AS "approved_variations",
    ((COALESCE("p"."contract_value", (0)::numeric) + COALESCE("variation"."approved_variations", (0)::numeric)))::numeric(18,2) AS "revised_contract_value",
    (COALESCE("invoice"."total_invoiced", (0)::numeric))::numeric(18,2) AS "total_invoiced",
    (COALESCE("invoice"."total_paid", (0)::numeric))::numeric(18,2) AS "total_paid",
    (COALESCE("invoice"."total_outstanding", (0)::numeric))::numeric(18,2) AS "total_outstanding",
    (COALESCE("invoice"."overdue_outstanding", (0)::numeric))::numeric(18,2) AS "overdue_outstanding",
    (COALESCE("retention"."available_retention", (0)::numeric))::numeric(18,2) AS "available_retention",
    (COALESCE("invoice"."invoice_count", (0)::bigint))::integer AS "invoice_count",
    (COALESCE("invoice"."open_invoice_count", (0)::bigint))::integer AS "open_invoice_count"
   FROM (((("public"."projects" "p"
     JOIN "public"."customers" "c" ON ((("c"."customer_id" = "p"."customer_id") AND ("c"."is_deleted" = false))))
     LEFT JOIN LATERAL ( SELECT "sum"("v"."total_amount") AS "approved_variations"
           FROM "public"."variations" "v"
          WHERE (("v"."project_id" = "p"."project_id") AND ("v"."variation_status" = 'Accepted'::"text") AND ("v"."is_deleted" = false) AND ("v"."is_active" = true))) "variation" ON (true))
     LEFT JOIN LATERAL ( SELECT "count"(*) FILTER (WHERE ("i"."document_status" = 'Issued'::"text")) AS "invoice_count",
            "count"(*) FILTER (WHERE (("i"."document_status" = 'Issued'::"text") AND ("i"."payment_status" <> ALL (ARRAY['Paid'::"text", 'Overpaid'::"text"])))) AS "open_invoice_count",
            "sum"("i"."total_amount") FILTER (WHERE (("i"."document_status" = 'Issued'::"text") AND ("i"."invoice_type" <> 'Credit Note'::"text"))) AS "total_invoiced",
            "sum"("i"."paid_amount") FILTER (WHERE (("i"."document_status" = 'Issued'::"text") AND ("i"."invoice_type" <> 'Credit Note'::"text"))) AS "total_paid",
            "sum"(GREATEST("i"."balance_amount", (0)::numeric)) FILTER (WHERE (("i"."document_status" = 'Issued'::"text") AND ("i"."invoice_type" <> 'Credit Note'::"text") AND ("i"."payment_status" <> ALL (ARRAY['Paid'::"text", 'Overpaid'::"text"])))) AS "total_outstanding",
            "sum"(GREATEST("i"."balance_amount", (0)::numeric)) FILTER (WHERE (("i"."document_status" = 'Issued'::"text") AND ("i"."invoice_type" <> 'Credit Note'::"text") AND ("i"."payment_status" <> ALL (ARRAY['Paid'::"text", 'Overpaid'::"text"])) AND ("i"."due_date" < CURRENT_DATE))) AS "overdue_outstanding"
           FROM "public"."customer_invoices" "i"
          WHERE (("i"."project_id" = "p"."project_id") AND ("i"."is_deleted" = false))) "invoice" ON (true))
     LEFT JOIN LATERAL ( SELECT "sum"("summary"."available_retention_balance") AS "available_retention"
           FROM "public"."_site_retention_summary" "summary"
          WHERE ("summary"."project_id" = "p"."project_id")) "retention" ON (true))
  WHERE ("p"."is_deleted" = false);


ALTER VIEW "public"."_project_financial_summary" OWNER TO "postgres";


