    CONSTRAINT "product_flooring_specs_fixed_size_requirements" CHECK ((("dimension_type" <> 'Fixed Size'::"text") OR (("plank_width_mm" IS NOT NULL) AND ("plank_length_mm" IS NOT NULL) AND ("planks_per_box" IS NOT NULL)))),
