COMMENT ON COLUMN "public"."products"."variant_description" IS 'Optional detailed description that distinguishes this product variant from other variants.';



CREATE OR REPLACE VIEW "public"."product_flooring_specs_v" WITH ("security_invoker"='true') AS
 SELECT "spec"."product_flooring_spec_id",
    "spec"."product_id",
    "product"."product_code",
    "product"."product_name",
    "spec"."dimension_type",
    "spec"."plank_width_mm",
    "spec"."plank_length_mm",
    "spec"."plank_thickness_mm",
    "spec"."minimum_length_mm",
    "spec"."maximum_length_mm",
    "spec"."planks_per_box",
    "spec"."declared_sqm_per_box",
    "spec"."coverage_method",
        CASE
            WHEN (("spec"."dimension_type" = 'Fixed Size'::"text") AND ("spec"."plank_width_mm" IS NOT NULL) AND ("spec"."plank_length_mm" IS NOT NULL)) THEN "round"((("spec"."plank_width_mm" * "spec"."plank_length_mm") / 1000000.0), 6)
            ELSE NULL::numeric
        END AS "calculated_sqm_per_plank",
        CASE
            WHEN (("spec"."dimension_type" = 'Fixed Size'::"text") AND ("spec"."plank_width_mm" IS NOT NULL) AND ("spec"."plank_length_mm" IS NOT NULL) AND ("spec"."planks_per_box" IS NOT NULL)) THEN "round"(((("spec"."plank_width_mm" * "spec"."plank_length_mm") * ("spec"."planks_per_box")::numeric) / 1000000.0), 6)
            ELSE NULL::numeric
        END AS "calculated_sqm_per_box",
        CASE
            WHEN ("spec"."coverage_method" = 'Manufacturer Declared'::"text") THEN "spec"."declared_sqm_per_box"
            WHEN (("spec"."coverage_method" = 'Calculated from Dimensions'::"text") AND ("spec"."dimension_type" = 'Fixed Size'::"text")) THEN "round"(((("spec"."plank_width_mm" * "spec"."plank_length_mm") * ("spec"."planks_per_box")::numeric) / 1000000.0), 6)
            ELSE NULL::numeric
        END AS "effective_sqm_per_box",
        CASE
            WHEN (("spec"."planks_per_box" IS NULL) OR ("spec"."planks_per_box" <= 0)) THEN NULL::numeric
            WHEN (("spec"."coverage_method" = 'Manufacturer Declared'::"text") AND ("spec"."declared_sqm_per_box" IS NOT NULL)) THEN "round"(("spec"."declared_sqm_per_box" / ("spec"."planks_per_box")::numeric), 6)
            WHEN (("spec"."coverage_method" = 'Calculated from Dimensions'::"text") AND ("spec"."dimension_type" = 'Fixed Size'::"text")) THEN "round"((("spec"."plank_width_mm" * "spec"."plank_length_mm") / 1000000.0), 6)
            ELSE NULL::numeric
        END AS "effective_sqm_per_plank",
        CASE
            WHEN (("spec"."dimension_type" = 'Fixed Size'::"text") AND ("spec"."declared_sqm_per_box" IS NOT NULL) AND ("spec"."plank_width_mm" IS NOT NULL) AND ("spec"."plank_length_mm" IS NOT NULL) AND ("spec"."planks_per_box" IS NOT NULL)) THEN "round"(("spec"."declared_sqm_per_box" - ((("spec"."plank_width_mm" * "spec"."plank_length_mm") * ("spec"."planks_per_box")::numeric) / 1000000.0)), 6)
            ELSE NULL::numeric
        END AS "coverage_difference_sqm",
        CASE
            WHEN ("spec"."dimension_type" <> 'Fixed Size'::"text") THEN 'Coverage is based on manufacturer-declared packaging information.'::"text"
            WHEN ("spec"."declared_sqm_per_box" IS NULL) THEN 'Manufacturer-declared coverage has not been entered.'::"text"
            WHEN ("abs"(("spec"."declared_sqm_per_box" - ((("spec"."plank_width_mm" * "spec"."plank_length_mm") * ("spec"."planks_per_box")::numeric) / 1000000.0))) > 0.010) THEN 'Warning: calculated coverage differs from manufacturer-declared coverage by more than 0.010 m² per box.'::"text"
            ELSE 'Coverage values are consistent.'::"text"
        END AS "coverage_validation_message",
    "spec"."manufacturer_name",
    "spec"."manufacturer_product_code",
    "spec"."manufacturer_notes",
    "spec"."is_active",
    "spec"."is_deleted",
    "spec"."created_at",
    "spec"."updated_at",
    "spec"."created_by",
    "spec"."updated_by",
    "spec"."deleted_at"
   FROM ("public"."product_flooring_specs" "spec"
     JOIN "public"."products" "product" ON ((("product"."product_id" = "spec"."product_id") AND ("product"."is_deleted" = false))));


ALTER VIEW "public"."product_flooring_specs_v" OWNER TO "postgres";


