CREATE OR REPLACE VIEW "public"."project_area_progress_v" AS
 SELECT "pa"."area_id",
    "pa"."project_id",
    "pa"."site_id",
    "pa"."area_code",
    "pa"."area_name",
    "pa"."area_type",
    "pa"."estimated_quantity",
    "pa"."unit_of_measure",
    "p"."project_no",
    "p"."project_name",
    "c"."customer_name",
    "ps"."site_code",
    "ps"."site_name",
    COALESCE("sum"("dr"."completed_quantity"), (0)::numeric) AS "actual_quantity",
    GREATEST((COALESCE("pa"."estimated_quantity", (0)::numeric) - COALESCE("sum"("dr"."completed_quantity"), (0)::numeric)), (0)::numeric) AS "remaining_quantity",
        CASE
            WHEN (COALESCE("pa"."estimated_quantity", (0)::numeric) > (0)::numeric) THEN LEAST(((COALESCE("sum"("dr"."completed_quantity"), (0)::numeric) / "pa"."estimated_quantity") * (100)::numeric), (100)::numeric)
            ELSE (0)::numeric
        END AS "progress_percent"
   FROM (((("public"."project_areas" "pa"
     LEFT JOIN "public"."projects" "p" ON (("p"."project_id" = "pa"."project_id")))
     LEFT JOIN "public"."customers" "c" ON (("c"."customer_id" = "p"."customer_id")))
     LEFT JOIN "public"."project_sites" "ps" ON (("ps"."site_id" = "pa"."site_id")))
     LEFT JOIN "public"."daily_reports" "dr" ON ((("dr"."area_id" = "pa"."area_id") AND (COALESCE("dr"."is_deleted", false) = false) AND ("dr"."approval_status" = 'Approved'::"text"))))
  WHERE (COALESCE("pa"."is_deleted", false) = false)
  GROUP BY "pa"."area_id", "pa"."project_id", "pa"."site_id", "pa"."area_code", "pa"."area_name", "pa"."area_type", "pa"."estimated_quantity", "pa"."unit_of_measure", "p"."project_no", "p"."project_name", "c"."customer_name", "ps"."site_code", "ps"."site_name";


ALTER VIEW "public"."project_area_progress_v" OWNER TO "postgres";


