COMMENT ON COLUMN "public"."stock_request_items"."material_requirement_line_id" IS 'Optional Material Requirement line used to compare planned, issued, pending and over-requirement quantities.';



COMMENT ON COLUMN "public"."stock_request_items"."request_line_type" IS 'Operational line type derived from Product Type: Material, Consumable, Tool or Equipment.';



COMMENT ON COLUMN "public"."stock_request_items"."fulfilment_method" IS 'Routing target: Issue, Loan, Purchase or DirectDelivery.';



CREATE TABLE IF NOT EXISTS "public"."stock_requests" (
    "stock_request_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "stock_request_no" "text" NOT NULL,
    "project_id" "uuid" NOT NULL,
    "site_id" "uuid" NOT NULL,
    "area_id" "uuid",
    "request_date" "date" DEFAULT CURRENT_DATE NOT NULL,
    "required_date" "date",
    "request_status" "text" DEFAULT 'Draft'::"text" NOT NULL,
    "requested_by" "uuid",
    "notes" "text",
    "is_deleted" boolean DEFAULT false NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_by" "uuid",
    "updated_by" "uuid",
    "deleted_at" timestamp with time zone,
    "work_order_id" "uuid",
    "material_requirement_id" "uuid",
    "request_type" "text" DEFAULT 'MaterialShortfall'::"text" NOT NULL,
    "priority" "text" DEFAULT 'Normal'::"text" NOT NULL,
    "requester_auth_user_id" "uuid",
    "requester_employee_id" "uuid",
    "submitted_at" timestamp with time zone,
    "submitted_by" "uuid",
    "reviewed_at" timestamp with time zone,
    "reviewed_by" "uuid",
    "approved_at" timestamp with time zone,
    "approved_by" "uuid",
    "rejected_at" timestamp with time zone,
    "rejected_by" "uuid",
    "rejection_reason" "text",
    "fulfilled_at" timestamp with time zone,
    "fulfilled_by" "uuid",
    "cancelled_at" timestamp with time zone,
    "cancelled_by" "uuid",
    "cancellation_reason" "text",
    CONSTRAINT "stock_requests_cancellation_reason_check" CHECK ((("request_status" <> 'Cancelled'::"text") OR (NULLIF("btrim"("cancellation_reason"), ''::"text") IS NOT NULL))),
    CONSTRAINT "stock_requests_priority_check" CHECK (("priority" = ANY (ARRAY['Low'::"text", 'Normal'::"text", 'High'::"text", 'Urgent'::"text"]))),
    CONSTRAINT "stock_requests_rejection_reason_check" CHECK ((("request_status" <> 'Rejected'::"text") OR (NULLIF("btrim"("rejection_reason"), ''::"text") IS NOT NULL))),
    CONSTRAINT "stock_requests_request_status_check" CHECK (("request_status" = ANY (ARRAY['Draft'::"text", 'Submitted'::"text", 'UnderReview'::"text", 'Approved'::"text", 'PartiallyApproved'::"text", 'Rejected'::"text", 'Fulfilled'::"text", 'Cancelled'::"text", 'Partially Reserved'::"text", 'Reserved'::"text", 'Partially Issued'::"text", 'Issued'::"text", 'Ordered'::"text", 'Partially Delivered'::"text", 'Delivered'::"text"]))),
    CONSTRAINT "stock_requests_request_type_check" CHECK (("request_type" = ANY (ARRAY['MaterialShortfall'::"text", 'AdditionalMaterial'::"text", 'Accessory'::"text", 'Tool'::"text", 'Equipment'::"text", 'Mixed'::"text"])))
);


ALTER TABLE "public"."stock_requests" OWNER TO "postgres";


COMMENT ON COLUMN "public"."stock_requests"."work_order_id" IS 'Assigned Work Order that supplies authoritative Project/Site/Area context for a worker request.';



COMMENT ON COLUMN "public"."stock_requests"."material_requirement_id" IS 'Optional Material Requirement header being followed up; mixed tool requests may leave this null.';



COMMENT ON COLUMN "public"."stock_requests"."request_type" IS 'Request classification: MaterialShortfall, AdditionalMaterial, Accessory, Tool, Equipment or Mixed.';



