CREATE TABLE IF NOT EXISTS "public"."tool_loan_items" (
    "tool_loan_item_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "tool_loan_id" "uuid" NOT NULL,
    "stock_request_item_id" "uuid",
    "line_no" integer NOT NULL,
    "product_id" "uuid" NOT NULL,
    "asset_reference" "text",
    "serial_number" "text",
    "description" "text" NOT NULL,
    "loan_uom_code" "text" NOT NULL,
    "base_uom_code" "text" NOT NULL,
    "conversion_factor_to_base" numeric(18,6) DEFAULT 1 NOT NULL,
    "allow_fractional_quantity" boolean DEFAULT false NOT NULL,
    "approved_quantity" numeric(18,6) DEFAULT 0 NOT NULL,
    "approved_base_quantity" numeric(18,6) DEFAULT 0 NOT NULL,
    "issued_quantity" numeric(18,6) DEFAULT 0 NOT NULL,
    "issued_base_quantity" numeric(18,6) DEFAULT 0 NOT NULL,
    "returned_quantity" numeric(18,6) DEFAULT 0 NOT NULL,
    "returned_base_quantity" numeric(18,6) DEFAULT 0 NOT NULL,
    "damaged_quantity" numeric(18,6) DEFAULT 0 NOT NULL,
    "lost_quantity" numeric(18,6) DEFAULT 0 NOT NULL,
    "condition_before" "text",
    "condition_notes_before" "text",
    "condition_after" "text",
    "condition_notes_after" "text",
    "item_status" "text" DEFAULT 'Draft'::"text" NOT NULL,
    "notes" "text",
    "is_active" boolean DEFAULT true NOT NULL,
    "is_deleted" boolean DEFAULT false NOT NULL,
    "deleted_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_by" "uuid" DEFAULT "auth"."uid"(),
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_by" "uuid",
    CONSTRAINT "tool_loan_items_condition_after_check" CHECK ((("condition_after" IS NULL) OR ("condition_after" = ANY (ARRAY['Good'::"text", 'Fair'::"text", 'Worn'::"text", 'Damaged'::"text", 'Lost'::"text"])))),
    CONSTRAINT "tool_loan_items_condition_before_check" CHECK ((("condition_before" IS NULL) OR ("condition_before" = ANY (ARRAY['New'::"text", 'Good'::"text", 'Fair'::"text", 'Worn'::"text", 'Damaged'::"text"])))),
    CONSTRAINT "tool_loan_items_conversion_factor_check" CHECK (("conversion_factor_to_base" > (0)::numeric)),
    CONSTRAINT "tool_loan_items_description_not_blank_check" CHECK ((NULLIF("btrim"("description"), ''::"text") IS NOT NULL)),
    CONSTRAINT "tool_loan_items_fractional_quantity_check" CHECK ((("allow_fractional_quantity" = true) OR (("approved_quantity" = "trunc"("approved_quantity")) AND ("issued_quantity" = "trunc"("issued_quantity")) AND ("returned_quantity" = "trunc"("returned_quantity")) AND ("damaged_quantity" = "trunc"("damaged_quantity")) AND ("lost_quantity" = "trunc"("lost_quantity"))))),
    CONSTRAINT "tool_loan_items_issued_not_over_approved_check" CHECK ((("issued_quantity" <= "approved_quantity") AND ("issued_base_quantity" <= "approved_base_quantity"))),
    CONSTRAINT "tool_loan_items_line_no_positive_check" CHECK (("line_no" > 0)),
    CONSTRAINT "tool_loan_items_loss_damage_check" CHECK ((("damaged_quantity" + "lost_quantity") <= "issued_quantity")),
    CONSTRAINT "tool_loan_items_quantity_check" CHECK ((("approved_quantity" >= (0)::numeric) AND ("approved_base_quantity" >= (0)::numeric) AND ("issued_quantity" >= (0)::numeric) AND ("issued_base_quantity" >= (0)::numeric) AND ("returned_quantity" >= (0)::numeric) AND ("returned_base_quantity" >= (0)::numeric) AND ("damaged_quantity" >= (0)::numeric) AND ("lost_quantity" >= (0)::numeric))),
    CONSTRAINT "tool_loan_items_returned_not_over_issued_check" CHECK ((("returned_quantity" <= "issued_quantity") AND ("returned_base_quantity" <= "issued_base_quantity"))),
    CONSTRAINT "tool_loan_items_soft_delete_check" CHECK (((("is_deleted" = false) AND ("deleted_at" IS NULL)) OR (("is_deleted" = true) AND ("deleted_at" IS NOT NULL)))),
    CONSTRAINT "tool_loan_items_status_check" CHECK (("item_status" = ANY (ARRAY['Draft'::"text", 'Approved'::"text", 'Prepared'::"text", 'Issued'::"text", 'InUse'::"text", 'PartiallyReturned'::"text", 'Returned'::"text", 'Damaged'::"text", 'Lost'::"text", 'Closed'::"text", 'Cancelled'::"text"])))
);


