CREATE OR REPLACE VIEW "public"."v_cash_flow" AS
 SELECT "ci"."due_date",
    "c"."customer_name",
    "ci"."invoice_no",
    "ci"."total_amount",
    "ci"."paid_amount",
    "ci"."balance_amount",
    "ci"."invoice_status"
   FROM ("public"."customer_invoices" "ci"
     JOIN "public"."customers" "c" ON (("c"."customer_id" = "ci"."customer_id")))
  WHERE (("ci"."is_deleted" = false) AND ("ci"."balance_amount" > (0)::numeric));


ALTER VIEW "public"."v_cash_flow" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_outstanding_invoices" AS
 SELECT "ci"."customer_invoice_id",
    "ci"."invoice_no",
    "c"."customer_name",
    "p"."project_name",
    "ci"."invoice_date",
    "ci"."due_date",
    "ci"."total_amount",
    "ci"."paid_amount",
    "ci"."balance_amount",
    "ci"."invoice_status",
        CASE
            WHEN (("ci"."due_date" < CURRENT_DATE) AND ("ci"."balance_amount" > (0)::numeric)) THEN true
            ELSE false
        END AS "is_overdue"
   FROM (("public"."customer_invoices" "ci"
     JOIN "public"."customers" "c" ON (("c"."customer_id" = "ci"."customer_id")))
     LEFT JOIN "public"."projects" "p" ON (("p"."project_id" = "ci"."project_id")))
  WHERE ("ci"."is_deleted" = false);


ALTER VIEW "public"."v_outstanding_invoices" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_payroll_summary" AS
 SELECT "pp"."payroll_period_id",
    "pp"."period_no",
    "pp"."period_name",
    "pp"."start_date",
    "pp"."end_date",
    "pp"."status",
    "count"("pe"."payroll_entry_id") AS "employee_count",
    COALESCE("sum"("pe"."gross_amount"), (0)::numeric) AS "total_gross_amount",
    COALESCE("sum"("pe"."net_amount"), (0)::numeric) AS "total_net_amount"
   FROM ("public"."payroll_periods" "pp"
     LEFT JOIN "public"."payroll_entries" "pe" ON ((("pe"."payroll_period_id" = "pp"."payroll_period_id") AND ("pe"."is_deleted" = false))))
  WHERE ("pp"."is_deleted" = false)
  GROUP BY "pp"."payroll_period_id", "pp"."period_no", "pp"."period_name", "pp"."start_date", "pp"."end_date", "pp"."status";


ALTER VIEW "public"."v_payroll_summary" OWNER TO "postgres";


