    CONSTRAINT "work_time_logs_time_status_check" CHECK (("time_status" = ANY (ARRAY['Needs Review'::"text", 'Reviewed'::"text", 'Approved'::"text", 'Missing CheckIn-Checkout'::"text"])))
);


