CREATE OR REPLACE VIEW "public"."v_project_profitability" AS
 SELECT "p"."project_id",
    "p"."project_no",
    "p"."project_name",
    "c"."customer_name",
    COALESCE("sum"(DISTINCT "ci"."total_amount"), (0)::numeric) AS "invoice_total",
    COALESCE(( SELECT "sum"("pol"."line_total") AS "sum"
           FROM ("public"."purchase_orders" "po"
             JOIN "public"."purchase_order_lines" "pol" ON (("pol"."purchase_order_id" = "po"."purchase_order_id")))
          WHERE (("po"."project_id" = "p"."project_id") AND ("po"."is_deleted" = false) AND ("pol"."is_deleted" = false))), (0)::numeric) AS "material_cost",
    COALESCE(( SELECT "sum"("pe"."gross_amount") AS "sum"
           FROM ("public"."payroll_entries" "pe"
             JOIN "public"."work_time_logs" "wtl" ON (("wtl"."employee_id" = "pe"."employee_id")))
          WHERE (("wtl"."project_id" = "p"."project_id") AND ("wtl"."is_deleted" = false) AND ("pe"."is_deleted" = false))), (0)::numeric) AS "labour_cost"
   FROM (("public"."projects" "p"
     JOIN "public"."customers" "c" ON (("c"."customer_id" = "p"."customer_id")))
     LEFT JOIN "public"."customer_invoices" "ci" ON ((("ci"."project_id" = "p"."project_id") AND ("ci"."is_deleted" = false))))
  WHERE ("p"."is_deleted" = false)
  GROUP BY "p"."project_id", "p"."project_no", "p"."project_name", "c"."customer_name";


ALTER VIEW "public"."v_project_profitability" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_project_progress" AS
 SELECT "p"."project_id",
    "p"."project_no",
    "p"."project_name",
    "c"."customer_name",
    "p"."project_status",
    "max"("dr"."report_date") AS "last_report_date",
    COALESCE("max"("dr"."progress_percent"), (0)::numeric) AS "latest_progress_percent"
   FROM (("public"."projects" "p"
     JOIN "public"."customers" "c" ON (("c"."customer_id" = "p"."customer_id")))
     LEFT JOIN "public"."daily_reports" "dr" ON ((("dr"."project_id" = "p"."project_id") AND ("dr"."is_deleted" = false))))
  WHERE ("p"."is_deleted" = false)
  GROUP BY "p"."project_id", "p"."project_no", "p"."project_name", "c"."customer_name", "p"."project_status";


ALTER VIEW "public"."v_project_progress" OWNER TO "postgres";


