    CONSTRAINT "variation_lines_base_quantity_check" CHECK (("base_quantity" >= (0)::numeric)),
    CONSTRAINT "variation_lines_conversion_factor_check" CHECK (("conversion_factor" > (0)::numeric)),
    CONSTRAINT "variation_lines_description_check" CHECK ((NULLIF("btrim"("description"), ''::"text") IS NOT NULL)),
    CONSTRAINT "variation_lines_line_no_check" CHECK (("line_no" > 0)),
    CONSTRAINT "variation_lines_percentages_check" CHECK ((("discount_percent" >= (0)::numeric) AND ("discount_percent" <= (100)::numeric) AND ("tax_rate" >= (0)::numeric) AND ("tax_rate" <= (100)::numeric))),
    CONSTRAINT "variation_lines_prices_check" CHECK ((("unit_price" >= (0)::numeric) AND ("cost_price" >= (0)::numeric) AND ("discount_amount" >= (0)::numeric) AND ("tax_amount" >= (0)::numeric) AND ("line_total" >= (0)::numeric))),
    CONSTRAINT "variation_lines_quantity_check" CHECK (("quantity" > (0)::numeric)),
    CONSTRAINT "variation_lines_soft_delete_check" CHECK (((("is_deleted" = false) AND ("deleted_at" IS NULL)) OR (("is_deleted" = true) AND ("deleted_at" IS NOT NULL))))
);


